INSERT INTO ETFOLessonPlan VALUES('cmf43u3ra002hvj9tfhiic32e',23,'Nos premières sculptures','cmf43u3r9002dvj9t9bqe14a3',1772035200000,45,'Révision tactile : toucher et nommer des objets 3D. Introduction de la pâte à modeler comme matériau pour créer nos propres objets 3D.','Création libre : explorer la pâte à modeler en roulant, pressant, étirant. Créer un objet simple (boule, serpent, pot). Décrire son processus.','Exposition des sculptures : placer les créations sur une table d''exposition. Chaque élève explique ce qu''il a fait.','Observer le concept de nos premières; Créer les techniques artistiques appropriées; Développer la créativité par l''expression créative','["Pâte à modeler colorée","Napperons plastifiés","Pâte à modeler","Outils simples (rouleau, emporte-pièces)","Napperons","Table d''exposition"]',NULL,'Nos premières sculptures','Révision tactile : toucher et nommer des objets 3D. Introduction de la pâte à modeler comme matériau pour créer nos propres objets 3D.','Création libre : explorer la pâte à modeler en roulant, pressant, étirant. Créer un objet simple (boule, serpent, pot). Décrire son processus.','Exposition des sculptures : placer les créations sur une table d''exposition. Chaque élève explique ce qu''il a fait.','Observer le concept de nos premières; Créer les techniques artistiques appropriées; Développer la créativité par l''expression créative',NULL,NULL,NULL,'formative','{"observable":["Manipule la pâte à modeler","Crée une forme tridimensionnelle","Décrit son processus"],"checkpoints":["Exploration des techniques de base","Création d''un objet identifiable","Participation au partage"]}',1,'Plan détaillé avec supports visuels',1756911653255,1757594653728,1,'fr','Arts visuels','{"pourDifficultés":["Pâte plus molle","Outils adaptés","Formes très simples"],"pourAvancés":["Combinaison de couleurs","Formes plus complexes","Ajout de textures"],"pourLangue":["Démonstration visuelle des techniques","Vocabulaire gestuel","Support de phrases"],"po