INSERT INTO ETFOLessonPlan VALUES('cmf43u3rb002jvj9t63916k19',23,'Construire avec des formes','cmf43u3r9002dvj9t9bqe14a3',1772121600000,45,'Défi d''équilibre : empiler 5 blocs sans qu''ils tombent. Discuter de ce qui rend une construction stable.','Construction créative : utiliser des formes variées (cubes, cylindres, cônes) pour créer une tour, une maison, ou un animal. Explorer l''équilibre.','Visite du musée des constructions : tour de la classe pour admirer et commenter les créations. Voter pour la plus stable.','Expérimenter les formes géométriques de base; Créer la reconnaissance des formes géométriques; Développer la créativité par l''expression créative','["Blocs de construction variés","Formes géométriques","Blocs géométriques","Formes en mousse","Tubes de carton","Boîtes diverses","Étiquettes de nom pour les constructions","Autocollants dorés pour les gagnants"]',NULL,'Construire avec des formes','Défi d''équilibre : empiler 5 blocs sans qu''ils tombent. Discuter de ce qui rend une construction stable.','Construction créative : utiliser des formes variées (cubes, cylindres, cônes) pour créer une tour, une maison, ou un animal. Explorer l''équilibre.','Visite du musée des constructions : tour de la classe pour admirer et commenter les créations. Voter pour la plus stable.','Expérimenter les formes géométriques de base; Créer la reconnaissance des formes géométriques; Développer la créativité par l''expression créative',NULL,NULL,NULL,'formative','{"observable":["Assemble les formes","Crée une construction stable","Utilise le vocabulaire de construction"],"checkpoints":["Participation au défi initial","Création d''une construction qui tient debout","Engagement dans l''exploration"]}',1,'Plan détaillé avec supports visuels',1756911653256,1757594653729,1,'fr','Arts visuels','{"pourDifficultés":["Formes plus grandes et stables","Aide pour placer les pièces","Constructions plus simples"],"pourAvancés":["Défis de hauteur ou complexité","Intégration de plusieurs m