INSERT INTO ETFOLessonPlan VALUES('cmf43u3rc002lvj9tt6kbtw1g',23,'Textures et surfaces','cmf43u3r9002dvj9t9bqe14a3',1772208000000,45,'Sac mystère des textures : identifier des objets par le toucher seulement. Décrire ce qu''on ressent avec des mots.','Création de textures : utiliser des outils variés pour créer des motifs sur de la pâte à modeler ou de l''argile. Expérimenter avec différentes impressions.','Galerie tactile : exposer les créations texturées. Les élèves touchent (avec permission) et décrivent les différentes sensations.','Transformer les textures variées; Créer les techniques artistiques appropriées; Développer la créativité par l''expression créative','["Sacs opaques","Objets de textures variées","Pâte à modeler/argile","Outils texturés (fourchettes, éponges, brosses)","Objets naturels","Napperons","Créations des élèves"]',NULL,'Textures et surfaces','Sac mystère des textures : identifier des objets par le toucher seulement. Décrire ce qu''on ressent avec des mots.','Création de textures : utiliser des outils variés pour créer des motifs sur de la pâte à modeler ou de l''argile. Expérimenter avec différentes impressions.','Galerie tactile : exposer les créations texturées. Les élèves touchent (avec permission) et décrivent les différentes sensations.','Transformer les textures variées; Créer les techniques artistiques appropriées; Développer la créativité par l''expression créative',NULL,NULL,NULL,'formative','{"observable":["Identifie différentes textures","Crée des textures variées","Utilise le vocabulaire tactile"],"checkpoints":["Participation au sac mystère","Expérimentation avec les outils","Description des textures créées"]}',1,'Plan détaillé avec supports visuels',1756911653256,1757594653730,1,'fr','Arts visuels','{"pourDifficultés":["Outils simples et efficaces","Pâte plus souple","Aide pour appuyer"],"pourAvancés":["Combinaison de plusieurs textures","Création de motifs répétitifs","Exploration d''outils complexes"],"pourLangue":["Démonstration de chaque technique","Vocabulaire gestuel","Exemples concrets"],"pourPEI":["Outils adaptés à la motricité fine","Support physique","Textures contrastées"]}','{"vocabulary":["texture","rugueux","lisse"],"visualSupports":["Mur de vocabulaire des textures avec échantillons","Tableau d''outils et leurs effets avec exemples","Cartes de vocabulaire tactile pour aider les descriptions"],"movementBreaks":["Faire passer les sacs de main en main","Marcher pour échanger des outils","Étirements des mains","Ranger nos idées : faire semblant de mettre nos pensées dans une boîte (2 minutes)","Étirer notre dos d''écrivains : rotation douce des épaules (2 minutes)"]}',NULL,NULL,NULL,NULL,'{"questions":["Les élèves ont-ils atteint les objectifs?","Quelles adaptations étaient nécessaires?","Que ferais-je différemment la prochaine fois?"]}',NULL,'',4,4,'core',1);
INSERT INTO ETFOLessonPlan VALUES('cmf43u3rd002nvj9tfiwxi3v6',23,'Animaux en 3D','cmf43u3r9002dvj9t9bqe14a3',1772467200000,45,'Jeu ''Devine mon animal'' : décrire les formes du corps d''un animal (tête ronde, corps ovale, pattes longues) pour que les autres devinent.','Sculpture d''animal : choisir un animal favori et le créer avec de la pâte à modeler en assemblant des formes de base (boules, saucisses, etc.).','Zoo de la classe : présenter son animal et dire pourquoi on l''a choisi. Les autres peuvent deviner l''animal si ce n''est pas évident.','Représenter les animaux et leurs besoins; Créer les caractéristiques des êtres vivants; Développer l''expression artistique par l''expression créative','["Cartes d''animaux","Images de formes géométriques","Pâte à modeler colorée","Outils de sculpture","Images d''animaux","Napperons","Animaux créés"]',NULL,'Animaux en 3D','Jeu ''Devine mon animal'' : décrire les formes du corps d''un animal (tête ronde, corps ovale, pattes longues) pour que les autres devinent.','Sculpture d''animal : choisir un animal favori et le créer avec de la pâte à modeler en assemblant des formes de base (boules, saucisses, etc.).','Zoo de la classe : présenter son animal et dire pourquoi on l''a choisi. Les autres peuvent deviner l''animal si ce n''est pas évident.','Représenter les animaux et leurs besoins; Créer les caractéristiques des êtres vivants; Développer l''expression artistique par l''expression créative',NULL,NULL,NULL,'formative','{"observable":["Identifie les formes des animaux","Assemble des formes pour créer un animal","Explique ses choix"],"checkpoints":["Participation au jeu de devinettes","Création d''un animal reconnaissable","Présentation de sa création"]}',1,'Plan détaillé avec supports visuels',1756911653257,1757594653731,1,'fr','Arts visuels','{"pourDifficultés":["Animaux très simples (serpent, poisson)","Aide pour assembler","Images de référence claires"],"pourAvancés":["Animaux plus complexes","Ajout de détails fins","Création de plusieurs animaux"],"pourLangue":["Vocabulaire visuel des parties du corps","Démonstrations étape par étape","Support gestuel"],"pourPEI":["Formes pré-préparées si nécessaire","Support individuel","Animaux adaptés aux intérêts"]}','{"vocabulary":["animal","corps","tête"],"visualSupports":["Affiche d''animaux avec leurs formes de base identifiées","Guide étape par étape pour créer des animaux simples","Phrases d''aide : ''Mon animal est...'', ''Il a...'', ''J''aime cet animal parce que...''"],"movementBreaks":["Imiter l''animal deviné","Se lever pour voir les animaux des autres","Mouvements d''animaux","Mimer les animaux créés avec tout le corps (3 minutes)"]}',NULL,NULL,NULL,NULL,'{"questions":["Les élèves ont-ils atteint les objectifs?","Quelles adaptations étaient nécessaires?","Que ferais-je différemment la prochaine fois?"]}',NULL,'',4,5,'core',1);
INSERT INTO ETFOLessonPlan VALUES('cmf43u3re002pvj9tbwvmn0cu',23,'Mobiles et équilibre','cmf43u3r9002dvj9t9bqe14a3',1772553600000,45,'Observation d''un mobile en mouvement. Discussion : pourquoi ça bouge ? Qu''est-ce qui le fait tenir en équilibre ?','Création de mobile : suspendre des objets légers (papier, plumes, petits jouets) à des branches ou bâtonnets. Tester l''équilibre.','Test de mobiles : suspendre les créations et observer lesquelles bougent le mieux. Discuter des découvertes.','Créer le concept de mobiles et; Créer les techniques artistiques appropriées; Développer l''expression artistique par l''expression créative','["Mobile simple ou vidéo de mobile","Objets de poids différents","Bâtonnets/branches","Ficelle","Objets légers variés","Papier coloré","Ciseaux","Supports pour suspendre","Mobiles créés"]',NULL,'Mobiles et équilibre','Observation d''un mobile en mouvement. Discussion : pourquoi ça bouge ? Qu''est-ce qui le fait tenir en équilibre ?','Création de mobile : suspendre des objets légers (papier, plumes, petits jouets) à des branches ou bâtonnets. Tester l''équilibre.','Test de mobiles : suspendre les créations et observer lesquelles bougent le mieux. Discuter des découvertes.','Créer le concept de mobiles et; Créer les techniques artistiques appropriées; Développer l''expression artistique par l''expression créative',NULL,NULL,NULL,'formative','{"observable":["Comprend le concept d''équilibre","Assemble un mobile fonctionnel","Ajuste pour améliorer"],"checkpoints":["Participation à l''observation","Création d''un mobile qui tient","Explication des ajustements"]}',1,'Plan détaillé avec supports visuels',1756911653258,1757594653732,1,'fr','Arts visuels','{"pourDifficultés":["Mobile à 2 éléments seulement","Aide pour les nœuds","Objets pré-perçés"],"pourAvancés":["Mobile à plusieurs niveaux","Calcul de l''équilibre","Décoration des éléments"],"pourLangue":["Démonstration visuelle des étapes","Vocabulaire gestuel","Travail en paire"],"pourPEI":["Ou