INSERT INTO ETFOLessonPlan VALUES('cmf43u3re002rvj9t71u3isdk',23,'Jardin de sculptures','cmf43u3r9002dvj9t9bqe14a3',1772640000000,45,'Chasse au trésor nature (si possible à l''extérieur) : collecter des matériaux naturels intéressants. Discuter des textures et formes trouvées.','Création de sculptures temporaires : arranger les matériaux naturels pour créer des œuvres d''art 3D. Explorer l''empilage, l''équilibre, et les motifs.','Galerie de jardin : présenter les sculptures et expliquer les choix de matériaux. Photographier les œuvres temporaires.','Dessiner le concept de jardin de; Créer les techniques artistiques appropriées; Développer l''expression artistique par l''expression créative','["Paniers de collecte","Feuilles, branches, pierres, pommes de pin","Matériaux naturels collectés","Bases (cartons, napperons)","Caméra/tablette pour photos"]',NULL,'Jardin de sculptures','Chasse au trésor nature (si possible à l''extérieur) : collecter des matériaux naturels intéressants. Discuter des textures et formes trouvées.','Création de sculptures temporaires : arranger les matériaux naturels pour créer des œuvres d''art 3D. Explorer l''empilage, l''équilibre, et les motifs.','Galerie de jardin : présenter les sculptures et expliquer les choix de matériaux. Photographier les œuvres temporaires.','Dessiner le concept de jardin de; Créer les techniques artistiques appropriées; Développer l''expression artistique par l''expression créative',NULL,NULL,NULL,'formative','{"observable":["Sélectionne des matériaux appropriés","Arrange les éléments de façon créative","Explique ses choix"],"checkpoints":["Participation à la collecte","Création d''un arrangement 3D","Présentation de son œuvre"]}',1,'Plan détaillé avec supports visuels',1756911653259,1757594653733,1,'fr','Arts visuels','{"pourDifficultés":["Arrangements simples et plats","Matériaux plus faciles à manipuler","Aide pour commencer"],"pourAvancés":["Structures complexes et hautes","Intégration de plusieurs techniques",