INSERT INTO ETFOLessonPlan VALUES('cmf43u3rm003bvj9tzhfvf4oy',23,'Sculptures sonores','cmf43u3r9002dvj9t9bqe14a3',1773846000000,45,'Exploration sonore : tester différents matériaux pour les sons qu''ils produisent. Créer une symphonie d''objets.','Construction d''instruments : créer une sculpture-instrument en assemblant des matériaux qui produisent des sons. Tester et ajuster.','Concert de sculptures : présenter les instruments créés en jouant une petite mélodie ou rythme. Orchestre de classe.','Représenter le concept de sculptures sonores; Créer les techniques artistiques appropriées; Développer l''appréciation artistique par l''expression créative','["Matériaux variés","Bâtonnets pour frapper","Récipients vides","Tubes, boîtes, métal","Matériaux de résonance","Outils de construction","Décorations","Instruments-sculptures créés"]',NULL,'Sculptures sonores','Exploration sonore : tester différents matériaux pour les sons qu''ils produisent. Créer une symphonie d''objets.','Construction d''instruments : créer une sculpture-instrument en assemblant des matériaux qui produisent des sons. Tester et ajuster.','Concert de sculptures : présenter les instruments créés en jouant une petite mélodie ou rythme. Orchestre de classe.','Représenter le concept de sculptures sonores; Créer les techniques artistiques appropriées; Développer l''appréciation artistique par l''expression créative',NULL,NULL,NULL,'formative','{"observable":["Identifie les matériaux sonores","Construit un instrument fonctionnel","Joue de son instrument créé"],"checkpoints":["Exploration des sons","Construction d''instrument","Performance musicale"]}',1,'Plan détaillé avec supports visuels',1756911653267,1757594653744,1,'fr','Arts visuels','{"pourDifficultés":["Instruments très simples","Sons faciles à produire","Aide technique"],"pourAvancés":["Instruments complexes multi-sons","Mélodies et rythmes","Techniques avancées"],"pourLangue":["Vocabulaire musical avec démonstrations","Apprentissage par écoute","Support gestuel"],"pourPEI":["Instruments adaptés aux capacités motrices","Volumes contrôlés","Participation adaptée"]}','{"vocabulary":["sonore","son","vibration"],"visualSupports":["Images d''instruments et sculptures sonores","Exemples d''instruments faits maison et techniques","Signes de chef d''orchestre simple"],"movementBreaks":["Bouger au rythme des sons créés","Tester les sons en bougeant","Pauses auditives","Chef d''orchestre : diriger la classe dans une symphonie de sculptures (2 minutes)"]}',NULL,NULL,NULL,NULL,'{"questions":["Les élèves ont-ils atteint les objectifs?","Quelles adaptations étaient nécessaires?","Que ferais-je différemment la prochaine fois?"]}',NULL,'',4,17,'extension',1);
INSERT INTO ETFOLessonPlan VALUES('cmf43u3rn003dvj9tp37fm7o7',23,'Installation artistique','cmf43u3r9002dvj9t9bqe14a3',1773932400000,45,'Découverte d''installations : observer des photos d''installations artistiques. Discuter de l''effet sur les spectateurs.','Création d''installation : transformer un coin de la classe en espace artistique spécial avec sculptures, lumières, textures.','Inauguration d''installation : inviter les autres à expérimenter l''installation créée. Recueillir les réactions.','Présenter le concept de installation artistique; Créer les techniques artistiques appropriées; Développer l''appréciation artistique par l''expression créative','["Images d''installations artistiques","Videos courtes","Tissus","Sculptures précédentes","Lumières colorées","Matériaux sensoriels","Installation complète"]',NULL,'Installation artistique','Découverte d''installations : observer des photos d''installations artistiques. Discuter de l''effet sur les spectateurs.','Création d''installation : transformer un coin de la classe en espace artistique spécial avec sculptures, lumières, textures.','Inauguration d''installation : inviter les autres à expérimenter l''installation créée. Recueillir les réactions.','Présenter le concept de installation artistique; Créer les techniques artistiques appropriées; Développer l''appréciation artistique par l''expression créative',NULL,NULL,NULL,'formative','{"observable":["Comprend le concept d''installation","Transforme effectivement l''espace","Crée une expérience pour les autres"],"checkpoints":["Analyse des installations existantes","Création d''espace transformé","Accueil des visiteurs"]}',1,'Plan détaillé avec supports visuels',1756911653267,1757594653745,1,'fr','Arts visuels','{"pourDifficultés":["Installations simples et sensorielles","Thèmes concrets","Support pour organiser"],"pourAvancés":["Installations conceptuelles complexes","Multi-sensorielles","Messages artistiques"],"pourLangue":["Thèmes universels","Expérience sensorielle avant verbale","Support descriptif"],"pourPEI":["Installations adaptées aux sensibilités","Expériences accessibles","Support individuel"]}','{"vocabulary":["installation","espace","environnement"],"visualSupports":["Exemples d''installations adaptées aux enfants","Plan simple pour organiser l''espace","Questions pour les visiteurs : ''Que ressens-tu ici ?''"],"movementBreaks":["Se déplacer pour imaginer être dans l''installation","Installer et réarranger les éléments","Tester l''expérience","Explorer l''installation en bougeant comme des visiteurs curieux (3 minutes)"]}',NULL,NULL,NULL,NULL,'{"questions":["Les élèves ont-ils atteint les objectifs?","Quelles adaptations étaient nécessaires?","Que ferais-je différemment la prochaine fois?"]}',NULL,'',4,18,'extension',1);
INSERT INTO ETFOLessonPlan VALUES('cmf43u3ro003fvj9tjee5tot3',23,'Art numérique 3D','cmf43u3r9002dvj9t9bqe14a3',4102416000000,45,'Découverte d''art numérique : observer des créations 3D réalisées sur ordinateur. Comparer avec l''art physique.','Création numérique : utiliser des applications simples de dessin/sculpture 3D pour créer des formes et objets virtuels.','Galerie virtuelle : partager les créations numériques sur grand écran. Discuter des différences avec l''art physique.','Intégrer le concept de art numérique; Créer les techniques artistiques appropriées; Développer l''appréciation artistique par l''expression créative','["Tablettes/ordinateurs","Exemples d''art numérique 3D","Tablettes avec apps de création 3D","Stylets si disponibles","Projecteur/grand écran","Créations numériques"]',NULL,'Art numérique 3D','Découverte d''art numérique : observer des créations 3D réalisées sur ordinateur. Comparer avec l''art physique.','Création numérique : utiliser des applications simples de dessin/sculpture 3D pour créer des formes et objets virtuels.','Galerie virtuelle : partager les créations numériques sur grand écran. Discuter des différences avec l''art physique.','Intégrer le concept de art numérique; Créer les techniques artistiques appropriées; Développer l''appréciation artistique par l''expression créative',NULL,NULL,NULL,'formative','{"observable":["Utilise les outils numériques de base","Crée des formes 3D virtuelles","Compare art physique et numérique"],"checkpoints":["Exploration des outils","Création numérique réussie","Réflexion comparative"]}',1,'Plan détaillé avec supports visuels',1756911653268,1757594653746,1,'fr','Arts visuels','{"pourDifficultés":["Applications très simples","Aide technique constante","Créations basiques"],"pourAvancés":["Outils plus complexes","Créations détaillées","Exploration approfondie"],"pourLangue":["Interface visuelle intuitive","Support technique","Apprentissage par exploration"],"pourPEI":["Outils adaptés aux capacités motrices","Interfaces simplifiées","Support individualisé"]}','{"vocabulary":["numérique","virtuel","ordinateur"],"visualSupports":["Comparaison art traditionnel vs numérique","Guide simple des outils numériques de base","Questions de comparaison : ''Qu''est-ce qui est différent ? Pareil ?''"],"movementBreaks":["Gestes de sculpture dans l''air","Pauses écran","Mouvements des doigts","Étirements numériques : bouger les doigts comme si on sculptait dans l''air (2 minutes)"]}',NULL,NULL,NULL,NULL,'{"questions":["Les élèves ont-ils atteint les objectifs?","Quelles adaptations étaient nécessaires?","Que ferais-je différemment la prochaine fois?"]}',NULL,'',4,19,'core',0);
INSERT INTO ETFOLessonPlan VALUES('cmf43u3ro003hvj9tg1bfgf1c',23,'Célébration 3D finale','cmf43u3r9002dvj9t9bqe14a3',1774018800000,45,'Rétrospective : revoir toutes les créations 3D réalisées pendant l''unité. Identifier les progrès et moments de fierté.','Musée des réussites : organiser une exposition finale avec toutes les meilleures créations. Préparer des présentations de fierté.','Cérémonie de remise : présenter les certificats d''artiste 3D. Partager les rêves artistiques futurs. Applaudissements de célébration.','Maîtriser le concept de célébration 3d; Créer les techniques artistiques appropriées; Développer l''appréciation artistique par la célébration collective','["Portfolio de créations","Photos du parcours","Toutes les créations de l''unité","Matériaux d''exposition","Cértificats d''artiste","Certificats personnalisés","Exposition finale"]',NULL,'Célébration 3D finale','Rétrospective : revoir toutes les créations 3D réalisées pendant l''unité. Identifier les progrès et moments de fierté.','Musée des réussites : organiser une exposition finale avec toutes les meilleures créations. Préparer des présentations de fierté.','Cérémonie de remise : présenter les certificats d''artiste 3D. Partager les rêves artistiques futurs. Applaudissements de célébration.','Maîtriser le concept de célébration 3d; Créer les techniques artistiques appropriées; Développer l''appréciation artistique par la célébration collective',NULL,NULL,NULL,'formative','{"observable":["Identifie ses progrès artistiques","Exprime sa fierté","Envisage des projets futurs"],"checkpoints":["Réflexion sur le parcours","Organisation d''exposition","Participation à la célébration"]}',1,'Plan détaillé avec supports visuels',1756911653269,1757594653747,1,'fr','Arts visuels','{"pourDifficultés":["Célébration de tous les efforts","Support pour identifier les réussites","Fierté des tentatives"],"pourAvancés":["Réflexion approfondie","Objectifs artistiques futurs","Leadership dans les présentations"],"pourLangue":["Célébration universelle","Expression par l''art plus que par les mots","Reconnaissance visuelle"],"pourPEI":["Célébration individualisée","Reconnaissance des forces uniques","Participation adaptée"]}','{"vocabulary":["célébrer","apprentissage","progrès"],"visualSupports":["Chronologie visuelle de l''unité avec photos","Modèles de réflexion : ''J''ai appris...'', ''Je suis fier de...''","Messages d''encouragement pour l''avenir artistique"],"movementBreaks":["Circuler pour revoir toutes les créations","Organiser l''exposition","Répéter les présentations","Grande célébration finale : applaudissements, danses de joie et high-fives artistiques (3 minutes)"]}',NULL,NULL,NULL,NULL,'{"questions":["Les élèves ont-ils atteint les objectifs?","Quelles adaptations étaient nécessaires?","Que ferais-je différemment la prochaine fois?"]}',NULL,'',4,20,'core',1);
INSERT INTO ETFOLessonPlan VALUES('cmf43u3rr003lvj9t8zi6w75r',23,'Découvrons l''art des fêtes','cmf43u3rq003jvj9t0fyfxgm2',1764000000000,45,'Show holiday art images from different cultures. Use gestures to show ''celebration'' (clapping, dancing). Say ''C''est l''art!'' while pointing to decorative items. Connect to students'' experiences: ''Avez-vous vu l''art pour les fêtes?''','Gallery walk around classroom with holiday art examples. Students draw one thing they see that celebrates. Practice saying ''fête'', ''art'', ''célébrer'' with actions. Create a class list of where we see celebration art.','Share one drawing with a partner. Practice saying ''C''est l''art pour célébrer.'' Clean up materials together.','Découvrir le concept de découvrons l''art; Créer les phénomènes hivernaux; Développer la créativité par l''expression créative','["Cartes d''images de fêtes hivernales (Noël, Hanukkah, Kwanzaa)","Décorations de classe existantes","Papier à dessiner et crayons de couleur","Tableau de gestes pour vocabulaire","Grandes images de fêtes du monde entier","Cartes d''activité avec gestes pour vocabulaire","Feuilles de dessin grand format","Liste de vérification visuelle pour galerie","Tableau de rangement pour dessins","Autocollants de félicitations","Cartes de phrases de partage","Bande sonore douce pour nettoyage"]',NULL,'Découvrons l''art des fêtes','Show holiday art images from different cultures. Use gestures to show ''celebration'' (clapping, dancing). Say ''C''est l''art!'' while pointing to decorative items. Connect to students'' experiences: ''Avez-vous vu l''art pour les fêtes?''','Gallery walk around classroom with holiday art examples. Students draw one thing they see that celebrates. Practice saying ''fête'', ''art'', ''célébrer'' with actions. Create a class list of where we see celebration art.','Share one drawing with a partner. Practice saying ''C''est l''art pour célébrer.'' Clean up materials together.','Découvrir le concept de découvrons l''art; Créer les phénomènes hivernaux; Développer la créativité par l''expression créative',NULL,NULL,NULL,'formative','{"observable":["L''élève regarde attentivement les images de fêtes montrées","L''élève fait le geste approprié quand il entend ''fête'' ou ''art''","L''élève dessine quelque chose en lien avec les célébrations","L''élève participe aux mouvements de galerie et observation"],"checkpoints":["Pendant l''activité principale: Vérifier si l''élève comprend la différence entre fête et art","Lors du dessin: Observer si l''élève peut créer quelque chose qui célèbre","À la fermeture: Noter comment l''élève partage ou apprécie l''art des autres"]}',1,'Plan détaillé avec supports visuels',1756911653271,1757594653751,1,'fr','Arts visuels','{"pourDifficultés":["Offrir seulement deux choix d''images de fêtes à dessiner","Permettre de pointer plutôt que de nommer les éléments artistiques","Jumeler avec un pair pour encouragement et aide"],"pourAvancés":["Encourager à dessiner des détails supplémentaires dans leurs œuvres","Inviter à aider les autres élèves à identifier l''art dans les images","Permettre d''utiliser des mots supplémentaires pour décrire ce qu''ils voient"],"pourLangue":["Utiliser beaucoup de gestes et d''expressions faciales pour le vocabulaire","Permettre l''usage de la langue maternelle pour expliquer leurs dessins","Fournir des images très claires avec étiquettes visuelles"],"pourPEI":["Adapter les matériaux de dessin selon les besoins moteurs","Offrir des images tactiles si bénéfique pour l''apprentissage","Modifier les attentes selon les objectifs individuels du PEI"]}','{"vocabulary":["fête","art","célébrer"],"visualSupports":["Photo cards of holiday decorations, festive art from various traditions","Picture cards, gesture cards for vocabulary, drawing templates if needed","Sentence strip with French phrase, cleanup picture schedule"],"movementBreaks":["Geste de célébration (applaudir et danser sur place)","Mouvement de création artistique (peindre dans l''air)","Pause pour tourner autour de la classe (galerie)","Étirement des bras comme des branches décorées","Mouvement de partage (montrer avec les mains)","Nettoyage silencieux comme des ninjas"]}',NULL,NULL,NULL,NULL,'{"questions":["Les élèves ont-ils atteint les objectifs?","Quelles adaptations étaient nécessaires?","Que ferais-je différemment la prochaine fois?"]}',NULL,'',4,1,'core',1);
INSERT INTO ETFOLessonPlan VALUES('cmf43u3rs003nvj9tv5268zyg',23,'Les couleurs de l''hiver','cmf43u3rq003jvj9t0fyfxgm2',1764086400000,45,'Review Lesson 1: ''Hier, nous avons vu l''art des fêtes.'' Show winter scene photos. Point to colors and say ''couleur''. Demonstrate winter colors with paint swatches.','Color hunt around room for winter colors. Sort color cards into ''hiver'' and ''pas hiver'' groups. Paint or color with winter palette. Create simple winter color collage.','Show collages to class. Practice ''Voici les couleurs d''hiver.'' Vote on favorite winter color as class.','Observer les caractéristiques de l''hiver et leurs effets; Créer des techniques de mélange de couleurs; Développer la créativité par l''expression créative','["Cartes de couleurs hivernales (blanc, bleu, argenté)","Photographies de scènes d''hiver réelles","Échantillons de peinture pour démonstration","Images de révision de la leçon 1","Cartes de couleurs à trier (hivernales et estivales)","Tapis de tri avec sections ''hiver'' et ''pas hiver''","Peintures ou crayons aux couleurs d''hiver","Papier pour collage et matériaux d''assemblage","Support pour affichage des collages","Tableau de vote avec couleurs d''hiver","Jetons ou autocollants pour voter","Bandes de phrases modèles en français"]',NULL,'Les couleurs de l''hiver','Review Lesson 1: ''Hier, nous avons vu l''art des fêtes.'' Show winter scene photos. Point to colors and say ''couleur''. Demonstrate winter colors with paint swatches.','Color hunt around room for winter colors. Sort color cards into ''hiver'' and ''pas hiver'' groups. Paint or color with winter palette. Create simple winter color collage.','Show collages to class. Practice ''Voici les couleurs d''hiver.'' Vote on favorite winter color as class.','Observer les caractéristiques de l''hiver et leurs effets; Créer des techniques de mélange de couleurs; Développer la créativité par l''expression créative',NULL,NULL,NULL,'formative','{"observable":["L''élève pointe ou nomme au moins une couleur d''hiver correctement","L''élève trie les couleurs dans les bonnes catégories (avec ou sans aide)","L''élève utilise des couleurs appropriées dans son collage hivernal","L''élève participe activement à la chasse aux couleurs dans la classe"],"checkpoints":["Pendant le tri: Observer si l''élève distingue les couleurs hivernales des autres","Durant la création: Vérifier si l''élève fait des choix appropriés de couleurs","À la présentation: Noter si l''élève peut identifier une couleur dans son œuvre"]}',1,'Plan détaillé avec supports visuels',1756911653272,1757594653752,1,'fr','Arts visuels','{"pourDifficultés":["Offrir seulement 3 couleurs d''hiver à identifier (blanc, bleu, gris)","Utiliser des objets concrets pour associer aux couleurs (neige, ciel, nuages)","Permettre de coller des morceaux pré-découpés pour le collage"],"pourAvancés":["Introduire des nuances (bleu pâle, blanc éclatant, gris foncé)","Encourager à créer des mélanges de couleurs d''hiver","Inviter à expliquer pourquoi certaines couleurs représentent l''hiver"],"pourLangue":["Associer chaque couleur à un geste simple et répétitif","Utiliser des images photographiques réelles d''hiver pour appuyer le vocabulaire","Permettre de nommer d''abord les couleurs dans leur langue maternelle"],"pourPEI":["Adapter les outils de peinture selon les besoins moteurs fins","Utiliser des textures différentes si le toucher aide à l''apprentissage des couleurs","Ajuster les attentes selon les objectifs du PEI (reconnaissance vs production)"]}','{"vocabulary":["couleur","hiver","blanc"],"visualSupports":["Color cards, winter photographs, paint swatches","Color sorting mats, winter vs summer color comparison charts","Sentence strips, color voting board"],"movementBreaks":["Geste pour ''couleur'' (peindre dans l''air avec le doigt)","Mouvement d''hiver (frissons et bras serrés contre le corps)","Chasse aux couleurs autour de la classe (marcher et pointer)","Pause peinture (étirer les doigts et poignets)","Geste de présentation (montrer avec fierté)","Mouvement de vote (lever la main solennellement)"]}',NULL,NULL,NULL,NULL,'{"questions":["Les élèves ont-ils atteint les objectifs?","Quelles adaptations étaient nécessaires?","Que ferais-je différemment la prochaine fois?"]}',NULL,'',4,2,'core',1);
INSERT INTO ETFOLessonPlan VALUES('cmf43u3rs003pvj9t8l3rn2ci',23,'Mes traditions familiales','cmf43u3rq003jvj9t0fyfxgm2',1764172800000,45,'Connect to Lesson 2: ''Nous avons vu les couleurs d''hiver.'' Show family celebration photos (diverse traditions). Use gesture for ''famille'' (group hug motion). Say ''Chaque famille a des traditions.''','Students draw their family''s way of celebrating (any tradition). Walk around, ask ''Qu''est-ce que c''est?'' Practice vocabulary while drawing. Share with table partners.','Gallery walk of family tradition drawings. Practice ''Ma famille...'' sentence starter. Appreciate diversity with ''C''est beau!''','Expérimenter le concept de mes traditions; Créer les phénomènes hivernaux; Développer la créativité par l''expression créative','["Photos de familles célébrant diverses traditions hivernales","Cartes de gestes pour vocabulaire familial","Images d''activités familiales variées (cuisine, décorations, jeux)","Papier et crayons pour dessiner","Exemples visuels de différentes traditions familiales","Papier à dessin et matériel artistique varié","Cartes de vocabulaire sur les activités familiales","Guides étape par étape pour dessiner des personnes simples","Espace d''affichage respectueux pour les dessins","Cartes de démarrage de phrase en français","Autocollants d''appréciation positive","Musique douce pour créer une ambiance bienveillante"]',NULL,'Mes traditions familiales','Connect to Lesson 2: ''Nous avons vu les couleurs d''hiver.'' Show family celebration photos (diverse traditions). Use gesture for ''famille'' (group hug motion). Say ''Chaque famille a des traditions.''','Students draw their family''s way of celebrating (any tradition). Walk around, ask ''Qu''est-ce que c''est?'' Practice vocabulary while drawing. Share with table partners.','Gallery walk of family tradition drawings. Practice ''Ma famille...'' sentence starter. Appreciate diversity with ''C''est beau!''','Expérimenter le concept de mes traditions; Créer les phénomènes hivernaux; Développer la créativité par l''expression créative',NULL,NULL,NULL,'formative','{"observable":["L''élève crée une représentation artistique de quelque chose d''important pour lui","L''élève fait le geste approprié pour ''famille'' ou ''tradition''","L''élève montre de l''intérêt et du respect pour les créations des autres","L''élève participe aux activités selon son niveau de confort"],"checkpoints":["Pendant le dessin: Observer le niveau de confort et d''engagement de l''élève","Lors du partage: Vérifier si l''élève peut communiquer quelque chose sur sa création","À la galerie: Noter si l''élève apprécie la diversité des œuvres avec respect"]}',1,'Plan détaillé avec supports visuels',1756911653273,1757594653753,1,'fr','Arts visuels','{"pourDifficultés":["Permettre de dessiner simplement ''quelque chose de spécial'' sans préciser famille","Offrir des modèles très simples (maison, cœur, sourire) pour commencer","Accepter des gribouillis comme expression artistique valide"],"pourAvancés":["Encourager à ajouter des détails sur les émotions dans leurs dessins","Inviter à dessiner des séquences d''activités traditionnelles","Permettre d''utiliser plus de vocabulaire pour décrire leurs traditions"],"pourLangue":["Accepter les explications dans la langue maternelle avec traduction douce","Utiliser des images universelles pour évoquer les traditions (nourriture, musique, danse)","Permettre les gestes et expressions faciales comme communication principale"],"pourPEI":["Adapter complètement selon la situation familiale et les besoins émotionnels","Utiliser des alternatives créatives si le dessin est difficile (collage, manipulation d''objets)","Respecter les limites personnelles et offrir des options de retrait si nécessaire"]}','{"vocabulary":["famille","tradition","dessiner"],"visualSupports":["Diverse family celebration photos, gesture cards","Tradition example cards, vocabulary picture cards, drawing step guides","Sentence starter cards, appreciation phrase cards"],"movementBreaks":["Geste de câlin familial (bras ouverts puis fermés contre soi)","Mouvement de tradition (répéter un geste trois fois)","Pause dessin (étirer les doigts et rouler les épaules)","Mouvement de partage doux (montrer avec les paumes ouvertes)","Marche d''appréciation silencieuse (pointes des pieds)","Geste d''acceptation (hocher la tête avec sourire)"]}',NULL,NULL,NULL,NULL,'{"questions":["Les élèves ont-ils atteint les objectifs?","Quelles adaptations étaient nécessaires?","Que ferais-je différemment la prochaine fois?"]}',NULL,'',4,3,'core',1);
INSERT INTO ETFOLessonPlan VALUES('cmf43u3rt003rvj9t9bn4kgka',23,'Créons ensemble','cmf43u3rq003jvj9t0fyfxgm2',1764259200000,45,'Review Lesson 3: ''Hier, vous avez dessiné vos traditions.'' Demonstrate ''ensemble'' by bringing hands together. Show large blank paper: ''Nous allons créer ensemble!''','Class collaborates on large winter scene. Each student adds one element. Practice turn-taking and French phrases: ''À mon tour'', ''Très beau'', ''Ensemble c''est mieux.''','Step back and admire class creation. Practice ''Nous avons créé ensemble!'' Take a class photo with the art.','Transformer le concept de créons ensemble; Créer les phénomènes hivernaux; Développer la créativité par l''expression créative','["Grande feuille de papier ou toile collaborative","Cartes de gestes pour ''ensemble'' et ''créer''","Exemples de projets collaboratifs simples","Matériel artistique varié pour tous","Matériaux artistiques variés (peinture, crayons, collage)","Système de rotation claire (numéros ou couleurs)","Cartes de phrases françaises pour encouragement","Minuteur visuel pour les tours de rôle","Caméra ou tablette pour photo de classe","Cartes de célébration des réussites","Accessoires amusants pour la photo (optionnel)","Espace pour afficher temporairement l''œuvre"]',NULL,'Créons ensemble','Review Lesson 3: ''Hier, vous avez dessiné vos traditions.'' Demonstrate ''ensemble'' by bringing hands together. Show large blank paper: ''Nous allons créer ensemble!''','Class collaborates on large winter scene. Each student adds one element. Practice turn-taking and French phrases: ''À mon tour'', ''Très beau'', ''Ensemble c''est mieux.''','Step back and admire class creation. Practice ''Nous avons créé ensemble!'' Take a class photo with the art.','Transformer le concept de créons ensemble; Créer les phénomènes hivernaux; Développer la créativité par l''expression créative',NULL,NULL,NULL,'formative','{"observable":["L''élève participe positivement au projet collaboratif","L''élève respecte les tours de rôle et attend son moment","L''élève fait le geste pour ''ensemble'' quand il entend le mot","L''élève montre de la fierté pour l''œuvre collective créée"],"checkpoints":["Pendant la collaboration: Observer les interactions sociales et le respect des règles","Durant la création: Vérifier si l''élève contribue de manière constructive","À la célébration: Noter le sentiment d''appartenance et de fierté collective"]}',1,'Plan détaillé avec supports visuels',1756911653274,1757594653755,1,'fr','Arts visuels','{"pourDifficultés":["Permettre de travailler en petits groupes de 2-3 plutôt qu''avec toute la classe","Offrir des tâches simples comme colorier une section déjà tracée","Assigner un partenaire bienveillant pour encouragement"],"pourAvancés":["Inviter à prendre un rôle de leadership pour organiser les tours","Encourager à suggérer des idées créatives pour l''œuvre collective","Permettre d''aider à enseigner les techniques aux autres"],"pourLangue":["Utiliser des gestes clairs pour expliquer les concepts de collaboration","Permettre l''expression dans la langue maternelle pour les idées créatives","Jumeler avec un pair francophone pour soutien linguistique"],"pourPEI":["Adapter les outils et matériaux selon les besoins moteurs ou sensoriels","Ajuster les attentes de participation selon les capacités individuelles","Offrir des alternatives si la collaboration est déficile (ex: création en parallèle)"]}','{"vocabulary":["ensemble","créer","classe"],"visualSupports":["Hand gesture cards, large collaborative space setup","Turn-taking cards, collaborative work examples, phrase strips","Achievement celebration cards, photo props"],"movementBreaks":["Geste d''union (mains qui se joignent au centre)","Mouvement de création collective (dessiner dans l''air tous ensemble)","Pause admiration (reculer et observer ensemble)","Rotation organisée autour de l''œuvre collective","Geste de fierté collective (lever les bras ensemble)","Mouvement de photo de groupe (sourire et poser ensemble)"]}',NULL,NULL,NULL,NULL,'{"questions":["Les élèves ont-ils atteint les objectifs?","Quelles adaptations étaient nécessaires?","Que ferais-je différemment la prochaine fois?"]}',NULL,'',4,4,'core',1);
INSERT INTO ETFOLessonPlan VALUES('cmf43u3ru003tvj9t1qxuz6vj',23,'Formes de l''hiver','cmf43u3rq003jvj9t0fyfxgm2',1764345600000,45,'Connect to Lesson 4: ''Hier, nous avons créé ensemble.'' Show winter objects (snowflake, tree, ornament). Trace shapes in air: ''Voici un rond, un triangle.'' Use body to make shapes.','Shape hunt in winter pictures. Students trace and cut basic shapes. Combine shapes to make winter objects (triangle trees, round snowmen). Practice shape names while creating.','Shape show-and-tell: ''J''ai fait un... avec des...'' Display creations on shape sorting board.','Représenter les caractéristiques de l''hiver et leurs effets; Créer la reconnaissance des formes géométriques; Développer l''expression artistique par l''expression créative','["Grandes cartes de formes géométriques (rond, triangle, carré)","Objets d''hiver réels ou images (flocons, sapins, ornements)","Guides pour tracer les formes dans l''air","Miroir pour que les élèves voient leurs mouvements corporels","Images d''hiver avec formes clairement identifiables","Ciseaux adaptés pour Grade 1 et gabarits de formes","Papiers de couleurs hivernales pour découper","Colle et supports pour assembler les créations","Tableau d''affichage organisé par formes","Cartes de démarrage de phrases simples","Autocollants de formes pour célébrer","Pointeur pour aider à identifier les formes dans les œuvres"]',NULL,'Formes de l''hiver','Connect to Lesson 4: ''Hier, nous avons créé ensemble.'' Show winter objects (snowflake, tree, ornament). Trace shapes in air: ''Voici un rond, un triangle.'' Use body to make shapes.','Shape hunt in winter pictures. Students trace and cut basic shapes. Combine shapes to make winter objects (triangle trees, round snowmen). Practice shape names while creating.','Shape show-and-tell: ''J''ai fait un... avec des...'' Display creations on shape sorting board.','Représenter les caractéristiques de l''hiver et leurs effets; Créer la reconnaissance des formes géométriques; Développer l''expression artistique par l''expression créative',NULL,NULL,NULL,'formative','{"observable":["L''élève identifie au moins une forme géométrique dans les objets d''hiver","L''élève trace ou fait le geste approprié pour nommer une forme","L''élève utilise les formes pour créer quelque chose d''hivernal","L''élève participe aux mouvements corporels de représentation des formes"],"checkpoints":["Pendant la chasse aux formes: Observer si l''élève peut pointer et nommer les formes vues","Durant la création: Vérifier si l''élève comprend comment combiner les formes","À la présentation: Noter si l''élève peut identifier au moins une forme dans sa création"]}',1,'Plan détaillé avec supports visuels',1756911653275,1757594653756,1,'fr','Arts visuels','{"pourDifficultés":["Offrir seulement 2 formes à la fois (rond et triangle) pour commencer","Utiliser des formes pré-découpées pour éviter les difficultés de motricité fine","Permettre de coller les formes sur des modèles déjà tracés"],"pourAvancés":["Introduire des formes plus complexes comme l''hexagone des flocons","Encourager à créer des motifs répétitifs avec les formes","Inviter à enseigner les noms de formes aux autres élèves"],"pourLangue":["Associer chaque forme à un mouvement corporel distinctif","Utiliser des objets réels de formes familières comme références","Permettre la répétition en langue maternelle puis en français"],"pourPEI":["Adapter les outils de découpage selon les besoins moteurs individuels","Utiliser des formes texturées ou en relief si le toucher aide l''apprentissage","Ajuster les attentes selon les capacités (reconnaissance vs création vs manipulation)"]}','{"vocabulary":["forme","rond","triangle"],"visualSupports":["Large shape cards, winter object photos, shape tracing guides","Shape sorting mats, winter object assembly guides, vocabulary cards","Sentence starter cards, shape display board"],"movementBreaks":["Faire des ronds avec tout le corps (tourner sur soi-même)","Faire des triangles avec les bras (pointe vers le haut)","Pause ciseaux (étirer les doigts et faire des rotations de poignets)","Danse des formes (bouger comme un rond qui roule, un triangle pointu)","Geste de présentation (montrer avec les bras ouverts)","Applaudissements en forme (taper en rond, en triangle)"]}',NULL,NULL,NULL,NULL,'{"questions":["Les élèves ont-ils atteint les objectifs?","Quelles adaptations étaient nécessaires?","Que ferais-je différemment la prochaine fois?"]}',NULL,'',4,5,'core',1);
INSERT INTO ETFOLessonPlan VALUES('cmf43u3rv003vvj9tlmluehy3',23,'Décorations simples','cmf43u3rq003jvj9t0fyfxgm2',1764604800000,45,'Review Lesson 5: ''Hier, nous avons fait des formes.'' Show simple paper decorations. Demonstrate ''décoration'' by hanging one up. Practice scissor safety: ''Attention avec les ciseaux!''','Students make paper chain decorations or simple snowflakes. Focus on safe scissor use and following steps. Practice vocabulary while creating: ''Je coupe le papier.''','Hang decorations around classroom. Practice ''Voici ma décoration!'' Admire everyone''s work with ''C''est joli!''','Créer le concept de décorations simples; Créer les phénomènes hivernaux; Développer l''expression artistique par l''expression créative','["Exemples de décorations en papier simples","Affiche de sécurité pour ciseaux","Photos étape par étape pour démonstration","Images de révision de la leçon 5","Bandes de papier de couleur pour chaînes","Papier blanc pour flocons de neige","Ciseaux sécuritaires pour enfants","Colle en bâton","Modèles de flocons simples","Ruban adhésif ou punaises pour accrocher","Cartes de phrases ''Voici ma décoration!''","Étiquettes d''appréciation ''C''est joli!''","Zones d''affichage désignées dans la classe"]',NULL,'Décorations simples','Review Lesson 5: ''Hier, nous avons fait des formes.'' Show simple paper decorations. Demonstrate ''décoration'' by hanging one up. Practice scissor safety: ''Attention avec les ciseaux!''','Students make paper chain decorations or simple snowflakes. Focus on safe scissor use and following steps. Practice vocabulary while creating: ''Je coupe le papier.''','Hang decorations around classroom. Practice ''Voici ma décoration!'' Admire everyone''s work with ''C''est joli!''','Créer le concept de décorations simples; Créer les phénomènes hivernaux; Développer l''expression artistique par l''expression créative',NULL,NULL,NULL,'formative','{"observable":["L''élève utilise les ciseaux de façon sécuritaire et appropriée","L''élève suit les étapes de création avec aide minimale","L''élève utilise le vocabulaire ''décoration'', ''papier'', ''ciseaux'' dans le contexte","L''élève montre fierté dans sa création et apprécie celle des autres"],"checkpoints":["Pendant l''ouverture: Vérifier la compréhension des règles de sécurité avec les ciseaux","Lors de l''activité principale: Observer les techniques de découpage et d''assemblage","À la fermeture: Noter comment l''élève présente sa décoration et interagit positivement"]}',1,'Plan détaillé avec supports visuels',1756911653276,1757594653757,1,'fr','Arts visuels','{"pourDifficultés":["Fournir des pièces pré-découpées pour éviter l''usage des ciseaux","Offrir des modèles très simples avec seulement 2-3 étapes","Permettre de travailler avec un partenaire pour encouragement"],"pourAvancés":["Encourager à créer des décorations plus complexes avec motifs détaillés","Inviter à aider les autres élèves avec les techniques de découpage","Permettre de faire plusieurs décorations ou combiner différents styles"],"pourLangue":["Utiliser beaucoup de gestes et démonstrations visuelles pour les instructions","Permettre l''usage de la langue maternelle pour expliquer les idées créatives","Fournir des étiquettes visuelles avec mots français sur les matériaux"],"pourPEI":["Adapter les outils selon les besoins moteurs (ciseaux adaptés, supports)","Modifier les attentes selon les objectifs individuels du PEI","Offrir du temps supplémentaire et des pauses fréquentes si nécessaire"]}','{"vocabulary":["décoration","papier","ciseaux"],"visualSupports":["Decoration examples, safety poster for scissors, step-by-step photos","Step-by-step instruction cards, safety reminders, finished examples","Appreciation phrase cards, decoration display area"],"movementBreaks":["Geste de sécurité avec les ciseaux (montrer avec les mains)","Mouvement de décoration (accrocher quelque chose en hauteur)","Pause pour étirer les doigts et poignets après découpage","Mouvement de collage (presser fermement avec les mains)","Mouvement de présentation (montrer fièrement sa décoration)","Geste d''appréciation (applaudir doucement pour les autres)"]}',NULL,NULL,NULL,NULL,'{"questions":["Les élèves ont-ils atteint les objectifs?","Quelles adaptations étaient nécessaires?","Que ferais-je différemment la prochaine fois?"]}',NULL,'',4,6,'core',1);
INSERT INTO ETFOLessonPlan VALUES('cmf43u3rw003xvj9ttio6rsre',23,'Cartes de souhaits','cmf43u3rq003jvj9t0fyfxgm2',1764691200000,45,'Connect to Lesson 6: ''Hier, nous avons fait des décorations.'' Show greeting cards from different cultures. Open and close cards: ''C''est une carte!'' Point to winter symbols: ''Voici des symboles.''','Students create greeting cards with winter symbols. Add simple French messages like ''Bonne fête!'' or draw pictures to communicate. Practice vocabulary while decorating.','Share cards with partners. Practice ''Voici ma carte!'' Discuss who they might give cards to: ''Pour ma famille!''','Dessiner le concept de cartes de; Créer les phénomènes hivernaux; Développer l''expression artistique par l''expression créative','["Cartes de souhaits de différentes cultures hivernales","Tableau de symboles d''hiver (flocons, arbres, cadeaux)","Cartes de gestes pour démonstration","Images de révision des décorations de la leçon 6","Papier cartonné plié pour cartes","Crayons de couleur et marqueurs","Autocollants de symboles d''hiver","Banques de mots français pour messages","Modèles de cartes complétées","Cartes de phrases pour partage ''Voici ma carte!''","Vocabulaire visuel des membres de la famille","Espace pour exposition des cartes","Liste de vérification pour partage respectueux"]',NULL,'Cartes de souhaits','Connect to Lesson 6: ''Hier, nous avons fait des décorations.'' Show greeting cards from different cultures. Open and close cards: ''C''est une carte!'' Point to winter symbols: ''Voici des symboles.''','Students create greeting cards with winter symbols. Add simple French messages like ''Bonne fête!'' or draw pictures to communicate. Practice vocabulary while decorating.','Share cards with partners. Practice ''Voici ma carte!'' Discuss who they might give cards to: ''Pour ma famille!''','Dessiner le concept de cartes de; Créer les phénomènes hivernaux; Développer l''expression artistique par l''expression créative',NULL,NULL,NULL,'formative','{"observable":["L''élève reconnaît et utilise des symboles d''hiver appropriés","L''élève essaie de communiquer en français lors du partage","L''élève crée une carte avec intention (pour quelqu''un de spécifique)","L''élève écoute respectueusement quand les autres partagent"],"checkpoints":["Pendant l''ouverture: Vérifier la compréhension des symboles d''hiver montrés","Lors de la création: Observer les choix de symboles et tentatives de messages","À la fermeture: Noter la capacité à partager et identifier le destinataire"]}',1,'Plan détaillé avec supports visuels',1756911653276,1757594653759,1,'fr','Arts visuels','{"pourDifficultés":["Fournir des cartes pré-pliées et des modèles à tracer","Offrir des autocollants plutôt que de demander de dessiner","Permettre de dicter leur message à un adulte"],"pourAvancés":["Encourager à écrire des messages plus longs en français","Inviter à créer des cartes pour plusieurs personnes","Proposer d''aider les autres avec l''orthographe française"],"pourLangue":["Permettre l''usage de la langue maternelle pour expliquer qui recevra la carte","Fournir des images pour exprimer les messages plutôt que des mots","Utiliser beaucoup de gestes pour démontrer le partage et l''appréciation"],"pourPEI":["Adapter les outils d''écriture selon les besoins moteurs","Modifier les attentes selon les objectifs individuels du PEI","Offrir des supports visuels personnalisés si nécessaire"]}','{"vocabulary":["carte","message","symbole"],"visualSupports":["Various greeting cards, winter symbol chart, gesture cards","French greeting examples, symbol reference sheet, card folding guide","Sharing sentence strips, family vocabulary cards"],"movementBreaks":["Geste d''ouverture de carte (mimer l''ouverture avec les mains)","Mouvement de pointer vers les symboles (pointer avec l''index)","Pause pour étirer les mains après écriture/dessin","Mouvement de décoration (tapoter doucement avec les doigts)","Geste de partage (montrer avec fierté)","Mouvement d''appréciation (applaudir ou hocher la tête)"]}',NULL,NULL,NULL,NULL,'{"questions":["Les élèves ont-ils atteint les objectifs?","Quelles adaptations étaient nécessaires?","Que ferais-je différemment la prochaine fois?"]}',NULL,'',4,7,'core',1);
INSERT INTO ETFOLessonPlan VALUES('cmf43u3rx003zvj9t75f0baqr',23,'Cadeaux faits main','cmf43u3rq003jvj9t0fyfxgm2',1764777600000,45,'Review Lesson 7: ''Hier, nous avons fait des cartes.'' Show handmade gifts. Use hands to demonstrate ''fait à la main.'' Practice ''C''est un cadeau!'' with giving gestures.','Students create simple gifts (decorated containers, bookmarks, painted stones). Focus on the care in making something for someone else. Practice ''Je donne un cadeau.''','Wrap gifts in simple materials. Practice ''C''est fait avec amour!'' Discuss the joy of giving vs. receiving.','Peindre le concept de cadeaux faits; Créer les phénomènes hivernaux; Développer l''expression artistique par l''expression créative','["Exemples de cadeaux faits à la main","Cartes de gestes pour ''fait à la main''","Images de mouvements de donner","Cartes récap de la leçon 7","Contenants à décorer (pots, boîtes)","Matériaux pour signets (carton, rubans)","Pierres lisses et peinture non-toxique","Autocollants et décorations variées","Guides visuels étape par étape","Papier de soie ou papier journal pour emballer","Rubans ou ficelles colorees","Cartes d''emotions (joie, amour)","Images de donner vs recevoir","Etiquettes ''fait avec amour''"]',NULL,'Cadeaux faits main','Review Lesson 7: ''Hier, nous avons fait des cartes.'' Show handmade gifts. Use hands to demonstrate ''fait à la main.'' Practice ''C''est un cadeau!'' with giving gestures.','Students create simple gifts (decorated containers, bookmarks, painted stones). Focus on the care in making something for someone else. Practice ''Je donne un cadeau.''','Wrap gifts in simple materials. Practice ''C''est fait avec amour!'' Discuss the joy of giving vs. receiving.','Peindre le concept de cadeaux faits; Créer les phénomènes hivernaux; Développer l''expression artistique par l''expression créative',NULL,NULL,NULL,'formative','{"observable":["L''élève crée un cadeau avec soin et attention","L''élève utilise le vocabulaire ''cadeau'', ''main'', ''donner'' appropriément","L''élève montre de la fierté dans sa création pour autrui","L''élève participe aux discussions sur donner vs recevoir"],"checkpoints":["Pendant l''ouverture: Vérifier la compréhension de ''fait à la main''","Lors de la création: Observer l''intention et le soin dans le travail","À la fermeture: Noter la capacité à exprimer l''amour dans la création"]}',1,'Plan détaillé avec supports visuels',1756911653277,1757594653760,1,'fr','Arts visuels','{"pourDifficultés":["Offrir des activités très simples comme décorer avec autocollants","Permettre de travailler avec un partenaire pour encouragement","Fournir des modèles pré-découpés à assembler seulement"],"pourAvancés":["Encourager des cadeaux plus élaborés avec plusieurs étapes","Inviter à aider les autres avec les techniques de création","Proposer de faire des cadeaux pour plusieurs personnes"],"pourLangue":["Utiliser beaucoup de démonstrations visuelles pour les techniques","Permettre l''usage de la langue maternelle pour expliquer leurs idées","Fournir des cartes visuelles pour vocabulaire des émotions"],"pourPEI":["Adapter les outils de création selon les besoins moteurs","Modifier les attentes selon les objectifs individuels du PEI","Offrir des supports additionnels pour manipulation fine"]}','{"vocabulary":["cadeau","main","donner"],"visualSupports":["Handmade gift examples, hand gesture cards, giving motion pictures","Gift-making step guides, caring gesture cards, finished examples","Emotion cards, giving vs. receiving pictures"],"movementBreaks":["Geste de création avec les mains (façonner dans l''air)","Mouvement de donner avec les bras (étendre vers l''avant)","Pause pour étirer les doigts et poignets","Mouvement de soin délicat (caresser doucement)","Geste d''emballage (envelopper avec les bras)","Expression d''amour (main sur le coeur)"]}',NULL,NULL,NULL,NULL,'{"questions":["Les élèves ont-ils atteint les objectifs?","Quelles adaptations étaient nécessaires?","Que ferais-je différemment la prochaine fois?"]}',NULL,'',4,8,'core',1);
INSERT INTO ETFOLessonPlan VALUES('cmf43u3ry0041vj9tqgfriy8c',23,'Textures d''hiver','cmf43u3rq003jvj9t0fyfxgm2',1764864000000,45,'Connect to Lesson 8: ''Hier, nous avons fait des cadeaux.'' Touch different materials: cotton (soft snow), sandpaper (rough bark). Practice ''doux'' and ''rugueux'' with facial expressions.','Texture exploration station. Students feel materials and sort into ''doux'' and ''rugueux.'' Create winter collages using different textures to represent snow, trees, ice.','Touch and describe textures: ''C''est doux comme...'' ''C''est rugueux comme...'' Display texture art gallery-style.','Modeler les caractéristiques de l''hiver et leurs effets; Créer les phénomènes hivernaux; Développer la motricité fine par l''expression créative','["Echantillons de textures (coton, papier sable, fourrure)","Plateau d''organisation des textures","Cartes d''expressions faciales pour doux/rugueux","Photos de textures d''hiver réelles","Variété de matériaux (coton, papier crêpé, écorce, tissu)","Tapis de tri avec sections ''doux'' et ''rugueux''","Papier de base pour collages","Colle adaptee aux enfants","Exemples de collages de scènes d''hiver","Bandelettes de phrases ''C''est doux comme...''","Cartes de comparaisons (nuage, écorce d''arbre)","Supports d''affichage pour galerie","Etiquettes pour identifier les collages"]',NULL,'Textures d''hiver','Connect to Lesson 8: ''Hier, nous avons fait des cadeaux.'' Touch different materials: cotton (soft snow), sandpaper (rough bark). Practice ''doux'' and ''rugueux'' with facial expressions.','Texture exploration station. Students feel materials and sort into ''doux'' and ''rugueux.'' Create winter collages using different textures to represent snow, trees, ice.','Touch and describe textures: ''C''est doux comme...'' ''C''est rugueux comme...'' Display texture art gallery-style.','Modeler les caractéristiques de l''hiver et leurs effets; Créer les phénomènes hivernaux; Développer la motricité fine par l''expression créative',NULL,NULL,NULL,'formative','{"observable":["L''élève différencie les textures douces et rugueuses par le toucher","L''élève utilise le vocabulaire ''texture'', ''doux'', ''rugueux'' appropriément","L''élève crée un collage intentionnel avec textures choisies","L''élève fait des comparaisons texturales simples"],"checkpoints":["Pendant l''ouverture: Vérifier la discrimination tactile de base","Lors de l''exploration: Observer les choix de textures et le tri","À la fermeture: Noter la capacité à décrire et comparer"]}',1,'Plan détaillé avec supports visuels',1756911653278,1757594653761,1,'fr','Arts visuels','{"pourDifficultés":["Offrir seulement 2-3 textures très contrastées à explorer","Permettre d''observer plutôt que de toucher si sensibilité tactile","Fournir des modèles de collage très simples à reproduire"],"pourAvancés":["Encourager à utiliser plus de textures variées dans leurs collages","Inviter à créer leurs propres comparaisons texturales créatives","Proposer d''aider les autres à identifier les textures difficiles"],"pourLangue":["Utiliser beaucoup de démonstrations tactiles et expressions faciales","Permettre l''usage de la langue maternelle pour les comparaisons","Fournir des images claires pour associer mots et sensations"],"pourPEI":["Adapter l''exploration tactile selon les sensibilités individuelles","Modifier les activités selon les objectifs sensoriels du PEI","Offrir des alternatives visuelles si besoin tactile limité"]}','{"vocabulary":["texture","doux","rugueux"],"visualSupports":["Texture sample board, expression cards for soft/rough, winter texture photos","Texture sorting mats, winter scene examples, texture vocabulary cards","Comparison sentence starters, texture description cards"],"movementBreaks":["Geste de caresser doucement (pour doux)","Geste de frotter énergiquement (pour rugueux)","Pause pour nettoyer les mains après manipulation","Mouvement de collage (presser délicatement)","Mouvement de galerie (marcher lentement et observer)","Geste d''appréciation artistique (hocher la tête)"]}',NULL,NULL,NULL,NULL,'{"questions":["Les élèves ont-ils atteint les objectifs?","Quelles adaptations étaient nécessaires?","Que ferais-je différemment la prochaine fois?"]}',NULL,'',4,9,'core',1);
INSERT INTO ETFOLessonPlan VALUES('cmf43u3rz0043vj9t30huwh8g',23,'Lumières et ombres','cmf43u3rq003jvj9t0fyfxgm2',1764950400000,45,'Review Lesson 9: ''Hier, nous avons touché les textures.'' Darken room, use flashlight to create shadows. Point to light: ''C''est la lumière!'' Point to shadow: ''C''est l''ombre!''','Shadow play with objects and flashlights. Students trace shadows on paper. Create ''light'' pictures with bright colors and ''shadow'' pictures with dark colors.','Compare light and shadow artworks. Practice ''Voici la lumière, voici l''ombre.'' Connect to holiday lights they''ve seen.','Transformer le concept de lumières et; Créer les phénomènes hivernaux; Développer la motricité fine par l''expression créative','["Lampes de poche pour démonstration","Objets variés pour faire des ombres","Cartes de vocabulaire lumière/ombre avec symboles","Contrôle d''éclairage de la classe","Lampes de poche individuelles ou partagées","Objets simples pour ombres (blocs, jouets)","Papier blanc pour traçage d''ombres","Crayons clairs et foncés","Exemples d''images lumineuses et sombres","Tableaux de comparaison lumière/ombre","Photos de lumières des fêtes (guirlandes, bougies)","Supports d''affichage pour œuvres d''élèves","Phrases modèles ''Voici la lumière...''"]',NULL,'Lumières et ombres','Review Lesson 9: ''Hier, nous avons touché les textures.'' Darken room, use flashlight to create shadows. Point to light: ''C''est la lumière!'' Point to shadow: ''C''est l''ombre!''','Shadow play with objects and flashlights. Students trace shadows on paper. Create ''light'' pictures with bright colors and ''shadow'' pictures with dark colors.','Compare light and shadow artworks. Practice ''Voici la lumière, voici l''ombre.'' Connect to holiday lights they''ve seen.','Transformer le concept de lumières et; Créer les phénomènes hivernaux; Développer la motricité fine par l''expression créative',NULL,NULL,NULL,'formative','{"observable":["L''élève distingue clairement lumière et ombre dans les démonstrations","L''élève utilise le vocabulaire ''lumière'', ''ombre'', ''briller'' appropriément","L''élève trace ou dessine en réponse aux effets lumineux observés","L''élève fait des connections avec les lumières festives familières"],"checkpoints":["Pendant l''ouverture: Vérifier la compréhension visuelle des concepts","Lors de l''exploration: Observer la manipulation et le traçage","À la fermeture: Noter la capacité à identifier et décrire"]}',1,'Plan détaillé avec supports visuels',1756911653279,1757594653762,1,'fr','Arts visuels','{"pourDifficultés":["Utiliser des objets plus grands pour créer des ombres plus visibles","Permettre de regarder plutôt que de tracer si coordination difficile","Fournir seulement 2 couleurs (une claire, une foncée) pour simplifier"],"pourAvancés":["Encourager à créer des ombres multiples avec plusieurs lampes","Inviter à expérimenter avec des objets transparents et opaques","Proposer de mélanger techniques de lumière et texture précédentes"],"pourLangue":["Utiliser beaucoup de démonstrations visuelles pour concepts abstraits","Permettre l''usage de la langue maternelle pour décrire les effets","Fournir des cartes imagées pour vocabulaire lumière/ombre/briller"],"pourPEI":["Adapter l''éclairage selon les sensibilités visuelles individuelles","Modifier les activités selon les objectifs visuels du PEI","Offrir des supports pour manipulation des lampes si nécessaire"]}','{"vocabulary":["lumière","ombre","briller"],"visualSupports":["Light/shadow demonstration setup, vocabulary cards with symbols","Shadow tracing guides, light/dark color examples, holiday light photos","Light/shadow comparison charts, holiday light examples"],"movementBreaks":["Jeu d''ombres avec les mains (animaux simples)","Mouvement de brillance (remuer les doigts comme des étoiles)","Pause pour reposer les yeux de la concentration","Mouvement de traçage dans l''air (suivre les contours)","Geste de montrer (pointer avec fierté)","Mouvement d''appréciation (applaudir doucement)"]}',NULL,NULL,NULL,NULL,'{"questions":["Les élèves ont-ils atteint les objectifs?","Quelles adaptations étaient nécessaires?","Que ferais-je différemment la prochaine fois?"]}',NULL,'',4,10,'core',1);
INSERT INTO ETFOLessonPlan VALUES('cmf43u3s00045vj9t9womwy1z',23,'Motifs répétés','cmf43u3rq003jvj9t0fyfxgm2',1765209600000,45,'Connect to Lesson 10: ''Hier, nous avons vu la lumière et l''ombre.'' Show patterned holiday decorations. Demonstrate ''répéter'' by repeating actions. Point to patterns: ''Voici un motif!''','Pattern detective hunt in room. Students identify repeating motifs. Create their own patterns using winter stamps or drawings. Practice ''Je répète le motif.''','Pattern show and tell. Students describe their patterns: ''Mon motif répète...'' Create class pattern book.','Représenter les motifs répétitifs; Créer des séquences répétitives créatives; Développer la motricité fine par l''expression créative','["Décorations à motifs des fêtes (guirlandes, papiers)","Cartes de démonstration pour répétition","Feuilles d''identification de motifs","Images de révision lumière/ombre","Loupes ou \"lunettes de détective\" en plastique","Tampons avec motifs d''hiver (flocons, arbres)","Papier et crayons pour dessiner motifs","Guides d''identification de motifs","Modèles de création de motifs","Bandelettes de phrases ''Mon motif répète...''","Pages pour livre de classe","Supports pour afficher les motifs","Matériel de reliure simple (agrafes, anneaux)"]',NULL,'Motifs répétés','Connect to Lesson 10: ''Hier, nous avons vu la lumière et l''ombre.'' Show patterned holiday decorations. Demonstrate ''répéter'' by repeating actions. Point to patterns: ''Voici un motif!''','Pattern detective hunt in room. Students identify repeating motifs. Create their own patterns using winter stamps or drawings. Practice ''Je répète le motif.''','Pattern show and tell. Students describe their patterns: ''Mon motif répète...'' Create class pattern book.','Représenter les motifs répétitifs; Créer des séquences répétitives créatives; Développer la motricité fine par l''expression créative',NULL,NULL,NULL,'formative','{"observable":["L''élève identifie des motifs répétés dans l''environnement","L''élève utilise le vocabulaire ''motif'', ''répéter'', ''modèle'' appropriément","L''élève crée un motif simple qui se répète au moins 2 fois","L''élève décrit son motif avec support ou indépendamment"],"checkpoints":["Pendant l''ouverture: Vérifier la reconnaissance visuelle des motifs","Lors de la chasse: Observer la capacité à identifier et créer","À la fermeture: Noter la capacité à expliquer et partager"]}',1,'Plan détaillé avec supports visuels',1756911653280,1757594653763,1,'fr','Arts visuels','{"pourDifficultés":["Commencer avec des motifs très simples (2 éléments qui alternent)","Fournir des modèles pré-faits à compléter plutôt qu''à créer","Permettre d''utiliser des autocollants plutôt que dessiner"],"pourAvancés":["Encourager des motifs plus complexes avec 3-4 éléments","Inviter à créer des motifs dans motifs (patterns dans patterns)","Proposer d''enseigner aux autres comment identifier les motifs"],"pourLangue":["Utiliser beaucoup de démonstrations physiques pour concept de répétition","Permettre l''usage de la langue maternelle pour expliquer leurs créations","Fournir des chiffres visuels pour compter les répétitions"],"pourPEI":["Adapter les outils de création selon les besoins moteurs","Modifier les attentes de complexité selon les objectifs du PEI","Offrir des supports visuels supplémentaires si nécessaire"]}','{"vocabulary":["motif","répéter","modèle"],"visualSupports":["Patterned decoration examples, repetition demonstration cards, motif identification sheets","Pattern identification guides, winter motif reference sheets, pattern creation templates","Pattern description sentence starters, class book template"],"movementBreaks":["Jeu de répétition de gestes simples","Mouvement de tracer des motifs dans l''air","Marche de détective autour de la classe","Mouvement de tamponner (presser et lever)","Geste de présentation fier","Mouvement de création de livre (tourner les pages)"]}',NULL,NULL,NULL,NULL,'{"questions":["Les élèves ont-ils atteint les objectifs?","Quelles adaptations étaient nécessaires?","Que ferais-je différemment la prochaine fois?"]}',NULL,'',4,11,'core',1);
INSERT INTO ETFOLessonPlan VALUES('cmf43u3s10047vj9t49iz0os0',23,'Mon chef-d''œuvre','cmf43u3rq003jvj9t0fyfxgm2',1765296000000,45,'Review all previous lessons with visual reminders. Explain ''chef-d''œuvre'' as ''your best art.'' Show how artists ''combiner'' different techniques. Let students choose their focus.','Students create their masterpiece using any combination of learned techniques (shapes, colors, textures, patterns, etc.). Circulate and practice vocabulary: ''J''ai combiné...''','Students place masterpieces in portfolios. Practice ''C''est mon chef-d''œuvre!'' Plan for sharing in next lesson.','Créer le concept de mon chef-d''œuvre; Créer les phénomènes hivernaux; Développer la motricité fine par l''expression créative','["Affiche de révision de toutes les leçons précédentes","Tableau de choix de techniques (formes, couleurs, textures, motifs)","Exemples de chefs-d''œuvre d''enfants","Cartes visuelles montrant comment combiner les techniques","Tous les matériaux des leçons précédentes disponibles","Papier de qualité supérieure pour chef-d''œuvre","Cartes de rappel des techniques","Modèles de planification pour organiser les idées","Guides visuels étape par étape","Portfolios ou dossiers personnels pour chaque élève","Étiquettes personnalisées pour portfolios","Cartes de préparation pour partage","Phrases modèles ''C''est mon chef-d''œuvre!''"]',NULL,'Mon chef-d''œuvre','Review all previous lessons with visual reminders. Explain ''chef-d''œuvre'' as ''your best art.'' Show how artists ''combiner'' different techniques. Let students choose their focus.','Students create their masterpiece using any combination of learned techniques (shapes, colors, textures, patterns, etc.). Circulate and practice vocabulary: ''J''ai combiné...''','Students place masterpieces in portfolios. Practice ''C''est mon chef-d''œuvre!'' Plan for sharing in next lesson.','Créer le concept de mon chef-d''œuvre; Créer les phénomènes hivernaux; Développer la motricité fine par l''expression créative',NULL,NULL,NULL,'formative','{"observable":["L''élève fait des choix réfléchis parmi les techniques apprises","L''élève utilise le vocabulaire ''chef-d''œuvre'', ''combiner'', ''personnel''","L''élève persévère dans son projet avec concentration","L''élève montre fierté et satisfaction dans son travail final"],"checkpoints":["Pendant l''ouverture: Observer la reconnaissance des techniques apprises","Lors de la création: Noter les choix, la planification et l''exécution","À la fermeture: Vérifier l''appropriation et la fierté du travail"]}',1,'Plan détaillé avec supports visuels',1756911653281,1757594653764,1,'fr','Arts visuels','{"pourDifficultés":["Limiter le choix à 1-2 techniques maîtrisées précédemment","Fournir un plan étape par étape très structuré","Permettre de refaire une technique préférée avec amélioration"],"pourAvancés":["Encourager à utiliser 3-4 techniques différentes harmonieusement","Inviter à expérimenter avec des combinaisons innovantes","Proposer d''aider les autres avec leurs choix techniques"],"pourLangue":["Permettre l''usage de la langue maternelle pour expliquer leurs choix","Fournir des images de référence pour chaque technique disponible","Utiliser beaucoup de démonstrations visuelles plutôt que verbales"],"pourPEI":["Adapter les attentes selon les capacités et objectifs individuels","Modifier les techniques disponibles selon les besoins moteurs","Offrir du temps supplémentaire et des pauses si nécessaire"]}','{"vocabulary":["chef-d''œuvre","combiner","personnel"],"visualSupports":["Lesson review poster, technique choice board, masterpiece examples","Technique reminder cards, planning templates, step-by-step guides","Portfolio labels, sharing preparation cards"],"movementBreaks":["Révision en gestes des techniques apprises","Mouvement de réflexion (main sur le menton)","Pause pour observer et apprécier le travail des autres","Étirements créatifs pour les mains et bras","Mouvement de présentation fier","Geste de rangement soigneusement"]}',NULL,NULL,NULL,NULL,'{"questions":["Les élèves ont-ils atteint les objectifs?","Quelles adaptations étaient nécessaires?","Que ferais-je différemment la prochaine fois?"]}',NULL,'',4,12,'core',1);
INSERT INTO ETFOLessonPlan VALUES('cmf43u3s10049vj9t636rvj71',23,'Galerie de classe','cmf43u3rq003jvj9t0fyfxgm2',1765382400000,45,'Connect to Lesson 12: ''Hier, vous avez fini vos chef-d''œuvres!'' Set up classroom like art gallery. Practice gallery manners: quiet walking, careful looking. Demonstrate ''montrer'' and ''expliquer.''','Gallery walk where students present their masterpieces. Practice ''Voici mon art. J''ai utilisé...'' Other students practice appreciation: ''C''est beau!'' ''J''aime...''','Vote for favorite gallery experience (not artwork). Practice ''Notre galerie est magnifique!'' Take photos for portfolios.','Dessiner le concept de galerie de; Créer les phénomènes hivernaux; Développer le sens esthétique par l''expression créative','["Supports d''affichage pour créer une galerie","Photos d''exemples de galeries réelles","Cartes de comportements de galerie","Guides de gestes pour présentation","Étiquettes ''artiste'' pour chaque élève","Bandelettes de phrases pour présentation","Cartes d''expressions d''appréciation","Guides pour observation de galerie","Microphone de classe (vrai ou jouet) pour présentations","Cartes de rappel des techniques apprises","Cartes de réflexion sur l''expérience galerie","Appareil photo ou tablette pour documentation","Autorisations de photos","Accessoires amusants pour photos (chapeaux d''artiste)","Bulletin de vote pour l''expérience préférée"]',NULL,'Galerie de classe','Connect to Lesson 12: ''Hier, vous avez fini vos chef-d''œuvres!'' Set up classroom like art gallery. Practice gallery manners: quiet walking, careful looking. Demonstrate ''montrer'' and ''expliquer.''','Gallery walk where students present their masterpieces. Practice ''Voici mon art. J''ai utilisé...'' Other students practice appreciation: ''C''est beau!'' ''J''aime...''','Vote for favorite gallery experience (not artwork). Practice ''Notre galerie est magnifique!'' Take photos for portfolios.','Dessiner le concept de galerie de; Créer les phénomènes hivernaux; Développer le sens esthétique par l''expression créative',NULL,NULL,NULL,'formative','{"observable":["L''élève participe respectueusement à l''expérience de galerie","L''élève utilise le vocabulaire ''galerie'', ''montrer'', ''expliquer''","L''élève présente son travail avec fierté appropriée","L''élève écoute et apprécie respectueusement le travail des autres"],"checkpoints":["Pendant l''installation: Observer l''engagement dans la préparation","Lors des présentations: Noter la communication et la participation","À la fermeture: Vérifier l''appréciation de l''expérience collective"]}',1,'Plan détaillé avec supports visuels',1756911653282,1757594653766,1,'fr','Arts visuels','{"pourDifficultés":["Permettre de présenter avec un partenaire ou aide d''adulte","Simplifier les phrases de présentation à 1-2 mots clés","Offrir des cartes visuelles pour guider la présentation"],"pourAvancés":["Encourager des présentations plus détaillées sur leurs choix","Inviter à poser des questions respectueuses aux autres artistes","Proposer d''aider à l''organisation de la galerie"],"pourLangue":["Permettre l''usage de la langue maternelle mélangée au français","Fournir des phrases modèles très simples à répéter","Utiliser beaucoup de gestes et expressions faciales pour communiquer"],"pourPEI":["Adapter les attentes de présentation selon les objectifs individuels","Modifier l''environnement de galerie selon les besoins sensoriels","Offrir des alternatives à la présentation orale si nécessaire"]}','{"vocabulary":["galerie","montrer","expliquer"],"visualSupports":["Gallery setup photos, gallery behavior cards, presentation gesture guides","Presentation sentence starters, appreciation phrase cards, gallery viewing guides","Gallery reflection cards, photo permission and props"],"movementBreaks":["Pratique de marche silencieuse de galerie","Gestes d''observation respectueuse","Rotation organisée autour de la galerie","Geste d''applaudissements respectueux","Poses d''artistes fières pour les photos","Célébration silencieuse de fin de galerie"]}',NULL,NULL,NULL,NULL,'{"questions":["Les élèves ont-ils atteint les objectifs?","Quelles adaptations étaient nécessaires?","Que ferais-je différemment la prochaine fois?"]}',NULL,'',4,13,'core',1);
INSERT INTO ETFOLessonPlan VALUES('cmf43u3s2004bvj9tq96845eq',23,'Réflexion artistique','cmf43u3rq003jvj9t0fyfxgm2',1765468800000,45,'Review journey from Lesson 1 to 13 using visual timeline. Practice ''réflexion'' by thinking gesture. Show growth from first drawings to masterpieces: ''Vous avez grandi!''','Students look through portfolios and identify learning. Complete simple reflection sheets with drawings/words. Practice ''J''ai appris...'' ''Je peux maintenant...'' Share growth with partners.','Class celebration of artistic growth. Practice ''Nous sommes des artistes!'' Plan how to share learning with families.','Peindre le concept de réflexion artistique; Créer les phénomènes hivernaux; Développer le sens esthétique par l''expression créative','["Chronologie visuelle du parcours d''apprentissage (leçons 1-13)","Exemples de comparaison de croissance (avant/après)","Cartes de gestes de réflexion (main au menton)","Premiers dessins et chefs-d''œuvre pour comparaison","Affiche de vocabulaire de réflexion","Portfolios complets de chaque élève","Modèles de feuilles de réflexion avec dessins","Cartes de vocabulaire d''apprentissage","Guides d''organisation de portfolio","Phrases débuts ''J''ai appris...'' et ''Je peux maintenant...''","Matériaux de célébration (banniere, autocollants)","Cartes d''identité d''artiste pour chaque élève","Feuilles de planification pour partage familial","Certificats de progrès artistique","Idées pour présentation aux familles"]',NULL,'Réflexion artistique','Review journey from Lesson 1 to 13 using visual timeline. Practice ''réflexion'' by thinking gesture. Show growth from first drawings to masterpieces: ''Vous avez grandi!''','Students look through portfolios and identify learning. Complete simple reflection sheets with drawings/words. Practice ''J''ai appris...'' ''Je peux maintenant...'' Share growth with partners.','Class celebration of artistic growth. Practice ''Nous sommes des artistes!'' Plan how to share learning with families.','Peindre le concept de réflexion artistique; Créer les phénomènes hivernaux; Développer le sens esthétique par l''expression créative',NULL,NULL,NULL,'formative','{"observable":["L''élève reconnaît sa croissance artistique avec support approprié","L''élève utilise le vocabulaire ''réflexion'', ''apprendre'', ''grandir''","L''élève identifie au moins un apprentissage spécifique","L''élève participe à la célébration avec fierté appropriée"],"checkpoints":["Pendant l''ouverture: Observer la reconnaissance du parcours d''apprentissage","Lors de la réflexion: Noter l''identification des apprentissages personnels","À la fermeture: Vérifier l''engagement dans la célébration collective"]}',1,'Plan détaillé avec supports visuels',1756911653283,1757594653767,1,'fr','Arts visuels','{"pourDifficultés":["Fournir des feuilles de réflexion avec images plutôt que mots","Permettre de montrer physiquement plutôt que d''expliquer verbalement","Simplifier aux apprentissages les plus concrets et visibles"],"pourAvancés":["Encourager des réflexions plus approfondies sur les processus créatifs","Inviter à identifier des objectifs d''apprentissage futurs","Proposer d''aider les autres avec leur réflexion"],"pourLangue":["Permettre l''usage de la langue maternelle pour exprimer les réflexions","Fournir beaucoup d''images pour stimuler la mémoire et l''expression","Utiliser des comparaisons simples et concrètes"],"pourPEI":["Adapter le format de réflexion selon les capacités communicatives","Modifier les attentes selon les objectifs individuels du PEI","Offrir des supports alternatifs (enregistrement, dessins) si nécessaire"]}','{"vocabulary":["réflexion","apprendre","grandir"],"visualSupports":["Learning journey timeline, growth comparison examples, thinking gesture cards","Reflection sheet templates, learning vocabulary cards, portfolio organization guides","Celebration materials, artist identity cards, family sharing planning sheets"],"movementBreaks":["Geste de croissance (grandir ave