INSERT INTO ETFOLessonPlan VALUES('cmf43u3t2006pvj9t5e8v5na6',23,'Échange avec d''autres galeries','cmf43u3ss005zvj9tpe37uas4',4102416000000,45,'Discuss how museums and galleries collaborate and share exhibitions. Plan connections with other classrooms or local art spaces. Introduce vocabulary: ÉCHANGE (exchange/sharing gesture), PARTAGER (giving/sharing motion), COLLABORATION (working together gesture).','Activité principale : exploration pratique et créative','Exchange Reflection. Reflect on what was learned through exchange or collaboration. Practice vocabulary: ''Grâce à cet échange, nous avons appris...'' Plan future collaborations.','Dessiner le concept de échange avec; Créer les techniques artistiques appropriées; Développer le sens esthétique par l''expression créative','["Cartes de vocabulaire visuelles","Supports visuels pour introduction","Matériel de démonstration","Exchange planning materials","Artwork samples for sharing","Demonstration materials","Communication tools for collaboration","Matériel de présentation","Outils d''évaluation formative","Supports pour partage"]',NULL,'Échange avec d''autres galeries','Discuss how museums and galleries collaborate and share exhibitions. Plan connections with other classrooms or local art spaces. Introduce vocabulary: ÉCHANGE (exchange/sharing gesture), PARTAGER (giving/sharing motion), COLLABORATION (working together gesture).','Activité principale : exploration pratique et créative','Exchange Reflection. Reflect on what was learned through exchange or collaboration. Practice vocabulary: ''Grâce à cet échange, nous avons appris...'' Plan future collaborations.','Dessiner le concept de échange avec; Créer les techniques artistiques appropriées; Développer le sens esthétique par l''expression créative',NULL,NULL,NULL,'Formative','Observation continue',1,'Plan détaillé avec supports visuels',1756911653318,1757587621433,1,'fr','Arts visuels','{"pourDifficultés":["Réduire le vocabulaire à 2-3 mots essentiels","Utiliser plus de supports visuels et de gestes","Jumeler avec un partenaire plus fort","Permettre l''usage de l''anglais au besoin"],"pourAvancés":["Ajouter du vocabulaire supplémentaire lié au thème","Devenir aide-enseignant pour leurs pairs","Créer des connections avec d''autres apprentissages","Utiliser des phrases plus complexes"],"pourLangue":["Cartes visuelles bilingues disponibles","Gestes et pointage encouragés pour communication","Permission d''utiliser L1 pour clarifier concepts","Partenaire francophone pour modéliser"],"pourPEI":["Adapter selon les objectifs individuels","Modifier les attentes de participation","Utiliser supports sensoriels au besoin","Temps supplémentaire pour traitement"]}','{"vocabulary":["échange","partager","collaboration"],"visualSupports":["Supports visuels appropriés pour Échange avec d''autres galeries, cartes de vocabulaire, démonstrations visuelles","Supports visuels appropriés pour Échange avec d''autres galeries, cartes de vocabulaire, démonstrations visuelles","Supports visuels appropriés pour Échange avec d''autres galeries, cartes de vocabulaire, démonstrations visuelles"],"movementBreaks":["Gestes de vocabulaire en grand groupe","Étirements ou mouvements simples liés au thème","Transitions organisées entre activités","Pauses actives selon les besoins","Mouvement pour rassemblement final","Gestes de célébration ou récapitulation"]}',NULL,NULL,NULL,NULL,'{"questions":["Les élèves ont-ils atteint les objectifs?","Quelles adaptations étaient nécessaires?","Que ferais-je différemment la prochaine fois?"]}',NULL,'',4,13,'core',0);
INSERT INTO ETFOLessonPlan VALUES('cmf43u3t3006rvj9te8vz4y2f',23,'Évolution de la galerie','cmf43u3ss005zvj9tpe37uas4',1780412400000,45,'Discuss how galleries change over time: new exhibitions, growing collections, facility improvements. Plan gallery future. Introduce vocabulary: ÉVOLUTION (growth/change motion), CHANGEMENT (transformation gesture), CROISSANCE (expansion gesture).','Activité principale : exploration pratique et créative','Gallery Future Presentation. Students present plans for gallery evolution and growth. Practice vocabulary: ''Pour l''évolution future, nous planifions...'' Commit to realistic next steps.','Peindre le concept de évolution de; Créer les techniques artistiques appropriées; Développer le sens esthétique par l''expression créative','["Cartes de vocabulaire visuelles","Supports visuels pour introduction","Matériel de démonstration","Future planning templates","Improvement brainstorming materials","Sustainability planning guides","Student leadership training materials","Matériel de présentation","Outils d''évaluation formative","Supports pour partage"]',NULL,'Évolution de la galerie','Discuss how galleries change over time: new exhibitions, growing collections, facility improvements. Plan gallery future. Introduce vocabulary: ÉVOLUTION (growth/change motion), CHANGEMENT (transformation gesture), CROISSANCE (expansion gesture).','Activité principale : exploration pratique et créative','Gallery Future Presentation. Students present plans for gallery evolution and growth. Practice vocabulary: ''Pour l''évolution future, nous planifions...'' Commit to realistic next steps.','Peindre le concept de évolution de; Créer les techniques artistiques appropriées; Développer le sens esthétique par l''expression créative',NULL,NULL,NULL,'Formative','Observation continue',1,'Plan détaillé avec supports visuels',1756911653319,1757587621433,1,'fr','Arts visuels','{"pourDifficultés":["Réduire le vocabulaire à 2-3 mots essentiels","Utiliser plus de supports visuels et de gestes","Jumeler avec un partenaire plus fort","Permettre l''usage de l''anglais au besoin"],"pourAvancés":["Ajouter du vocabulaire supplémentaire lié au thème","Devenir aide-enseignant pour leurs pairs","Créer des connections avec d''autres apprentissages","Utiliser des phrases plus complexes"],"pourLangue":["Cartes visuelles bilingues disponibles","Gestes et pointage encouragés pour communication","Permission d''utiliser L1 pour clarifier concepts","Partenaire francophone pour modéliser"],"pourPEI":["Adapter selon les objectifs individuels","Modifier les attentes de participation","Utiliser supports sensoriels au besoin","Temps supplémentaire pour traitement"]}','{"vocabulary":["évolution","changement","croissance"],"visualSupports":["Supports visuels appropriés pour Évolution de la galerie, cartes de vocabulaire, démonstrations visuelles","Supports visuels appropriés pour Évolution de la galerie, cartes de vocabulaire, démonstrations visuelles","Supports visuels appropriés pour Évolution de la galerie, cartes de vocabulaire, démonstrations visuelles"],"movementBreaks":["Gestes de vocabulaire en grand groupe","Étirements ou mouvements simples liés au thème","Transitions organisées entre activités","Pauses actives selon les besoins","Mouvement pour rassemblement final","Gestes de célébration ou récapitulation"]}',NULL,NULL,NULL,NULL,'{"questions":["Les élèves ont-ils atteint les objectifs?","Quelles adaptations étaient nécessaires?","Que ferais-je différemment la prochaine fois?"]}',NULL,'',4,14,'core',1);
INSERT INTO ETFOLessonPlan VALUES('cmf43u3t5006xvj9tcs0fj7y4',23,'Bonjour l''art!','cmf43u3t5006vvj9tb8txx7h5',1756911600000,45,'Circle time greeting with art objects. Show 3-4 familiar items (crayon, picture book, decorated pencil case). Point and say ''Voici l''art!'' Use big gestures and excited voice. Students repeat with actions.','Art Hunt Around the School: Students walk in pairs with collection baskets, looking for ''art'' examples everywhere - posters, decorations, patterns, colors. Teacher guides: ''Regardez! Voici de l''art!'' Students collect or sketch 3 things they find beautiful. Return to class and sort finds by colors: ''Rouge ici, bleu là!'' Practice vocabulary through discovery and sorting activities.','Art Gallery Share. Students place their chosen art object on desk. Walk around like in an art gallery, whispering ''Je vois...'' and naming colors they see. End with group cheer: ''L''art est partout!'' (Art is everywhere!)','Découvrir le concept de bonjour l''art!; Créer les techniques artistiques appropriées; Développer la créativité par l''expression créative','["Art objects for demonstration","Visual routine chart","Basic art supplies (crayons, paper, glue)","Color word cards with pictures","Small collection basket per student (20-25 total)","Clipboard for recording finds (optional)","Chart paper for color sorting","Marker for labeling","Art objects for demonstration","Visual routine chart","Basic art supplies (crayons, paper, glue)"]',NULL,'Bonjour l''art!','Circle time greeting with art objects. Show 3-4 familiar items (crayon, picture book, decorated pencil case). Point and say ''Voici l''art!'' Use big gestures and excited voice. Students repeat with actions.','Art Hunt Around the School: Students walk in pairs with collection baskets, looking for ''art'' examples everywhere - posters, decorations, patterns, colors. Teacher guides: ''Regardez! Voici de l''art!'' Students collect or sketch 3 things they find beautiful. Return to class and sort finds by colors: ''Rouge ici, bleu là!'' Practice vocabulary through discovery and sorting activities.','Art Gallery Share. Students place their chosen art object on desk. Walk around like in an art gallery, whispering ''Je vois...'' and naming colors they see. End with group cheer: ''L''art est partout!'' (Art is everywhere!)','Découvrir le concept de bonjour l''art!; Créer les techniques artistiques appropriées; Développer la créativité par l''expression créative',NULL,NULL,NULL,'formative','{"observable":["L''élève identifie différents outils d''art professionnel","L''élève démontre une utilisation sécuritaire des outils","L''élève utilise le vocabulaire: outil, professionnel, sécurité","L''élève respecte les consignes de manipulation"],"checkpoints":["Peut nommer 3 outils professionnels","Manipule les outils avec précaution","Utilise les mots de vocabulaire dans ses explications","Respecte les règles de sécurité établies"]}',1,'Plan détaillé avec supports visuels',1756911653322,1757594653865,1,'fr','Arts visuels','{"pourDifficultés":["Provide visual examples and demonstrations","Use simple gestures and basic vocabulary","Allow non-verbal responses initially","Partner with supportive peer"],"pourAvancés":["Encourage detailed French descriptions","Challenge with complex art concepts","Lead activities and help others","Explore creative extensions"],"pourLangue":["Provide visual vocabulary supports","Allow L1 support when needed","Use gestures and pointing","Focus on concrete, visible concepts"],"pourPEI":["Adapt materials and tools as needed","Provide sensory accommodations","Adjust expectations and timing","Offer multiple ways to show understanding"]}','{"vocabulary":["art","voir","couleur"],"visualSupports":["Gesture cards for ''voir'' (hand above eyes), visual routine chart for circle time","Color cards with French words and pictures, visual vocabulary chart showing ''art/voir/couleur'' with images and gestures","Gallery walk behavior chart, whisper voice visual cue, celebration gesture poster"],"movementBreaks":["Big gestures and excited movements for ''Voici l''art!'', action-based vocabulary repetition","Walking art hunt provides natural movement","Color sorting with standing and moving around chart","Gallery walk movement, celebration gestures for ''L''art est partout!''"]}',NULL,NULL,NULL,NULL,'{"questions":["Les élèves ont-ils atteint les objectifs?","Quelles adaptations étaient nécessaires?","Que ferais-je différemment la prochaine fois?"]}',NULL,'',4,1,'core',1);
INSERT INTO ETFOLessonPlan VALUES('cmf43u3t6006zvj9tqg2dcvzn',23,'Mes yeux découvrent','cmf43u3t5006vvj9tb8txx7h5',1756998000000,45,'Review game with Lesson 1 vocabulary using actions. Then introduce ''regarder'' with exaggerated looking gesture (hand above eyes like binoculars). Practice looking at ceiling, floor, each other with ''Je regarde...''','Detective Eyes Investigation: Students become art detectives using magnifying glasses to examine classroom objects closely. Practice ''Je regarde les détails!'' while finding shapes, textures, patterns. Create detail drawings of one special object, focusing on shapes they discover. Share findings: ''J''ai trouvé un cercle!'' Use shape vocabulary while examining and drawing.','Detail Gallery Walk. Post drawings on board. Students walk by and point to details they can identify, saying ''Je vois un détail!'' or ''Une forme!'' End with group celebration of their detective eyes.','Observer le concept de mes yeux; Créer les techniques artistiques appropriées; Développer la créativité par l''expression créative','["Art objects for demonstration","Visual routine chart","Basic art supplies (crayons, paper, glue)","Magnifying glasses or cardboard cutouts (20-25 total)","Shape cards (circle, square, triangle)","Paper and crayons for detail drawings","Clipboards for drawing support","Collection of interesting textured objects","Art objects for demonstration","Visual routine chart","Basic art supplies (crayons, paper, glue)"]',NULL,'Mes yeux découvrent','Review game with Lesson 1 vocabulary using actions. Then introduce ''regarder'' with exaggerated looking gesture (hand above eyes like binoculars). Practice looking at ceiling, floor, each other with ''Je regarde...''','Detective Eyes Investigation: Students become art detectives using magnifying glasses to examine classroom objects closely. Practice ''Je regarde les détails!'' while finding shapes, textures, patterns. Create detail drawings of one special object, focusing on shapes they discover. Share findings: ''J''ai trouvé un cercle!'' Use shape vocabulary while examining and drawing.','Detail Gallery Walk. Post drawings on board. Students walk by and point to details they can identify, saying ''Je vois un détail!'' or ''Une forme!'' End with group celebration of their detective eyes.','Observer le concept de mes yeux; Créer les techniques artistiques appropriées; Développer la créativité par l''expression créative',NULL,NULL,NULL,'formative','{"observable":["L''élève combine avec succès différents matériaux","L''élève utilise le vocabulaire: mélanger, médium, combinaison","L''élève planifie ses choix de matériaux","L''élève expérimente avec confiance"],"checkpoints":["Peut nommer les matériaux utilisés dans son œuvre","Démontre des techniques de mélange de base","Explique ses choix créatifs","Apprécie les combinaisons des autres"]}',1,'Plan détaillé avec supports visuels',1756911653323,1757594653866,1,'fr','Arts visuels','{"pourDifficultés":["Provide visual examples and demonstrations","Use simple gestures and basic vocabulary","Allow non-verbal responses initially","Partner with supportive peer"],"pourAvancés":["Encourage detailed French descriptions","Challenge with complex art concepts","Lead activities and help others","Explore creative extensions"],"pourLangue":["Provide visual vocabulary supports","Allow L1 support when needed","Use gestures and pointing","Focus on concrete, visible concepts"],"pourPEI":["Adapt materials and tools as needed","Provide sensory accommodations","Adjust expectations and timing","Offer multiple ways to show understanding"]}','{"vocabulary":["regarder","détail","forme"],"visualSupports":["Action cards for ''regarder'', vocabulary review chart from Lesson 1","Shape reference chart with French words, detective investigation steps poster, magnifying glass technique visual","Gallery walk behavior chart, sentence starters for sharing observations"],"movementBreaks":["Physical actions for each vocabulary word, looking gestures around the room","Walking around room as detectives","Standing and moving to examine different objects","Gallery walk movement, celebration gestures for detective success"]}',NULL,NULL,NULL,NULL,'{"questions":["Les élèves ont-ils atteint les objectifs?","Quelles adaptations étaient nécessaires?","Que ferais-je différemment la prochaine fois?"]}',NULL,'',4,2,'core',1);
INSERT INTO ETFOLessonPlan VALUES('cmf43u3t70071vj9thixwqqwe',23,'J''aime, j''aime pas','cmf43u3t5006vvj9tb8txx7h5',1757084400000,45,'Show two contrasting art pieces (bright vs dark, busy vs simple). Model preferences with clear gestures: ''J''aime!'' (thumbs up, smile) and ''J''aime pas!'' (gentle shake of head). Students practice with hand gestures for each phrase.','Art Preference Exploration: Present 6-8 diverse art images (different styles, colors, subjects). Students examine each and practice ''J''aime'' or ''J''aime pas'' with reasons: ''J''aime parce que c''est beau!'' Create preference voting with movement - students walk to ''J''aime'' or ''J''aime pas'' sides. Discuss: ''Pourquoi préféres-tu ça?'' Celebrate different opinions: ''Nos goûts sont différents et c''est parfait!''','Preference Circle. Students sit with their ''beau'' object from hunt. Each shares: ''J''aime...'' and points to their object. Others respond with ''C''est beau!'' End with ''Nos goûts sont différents!'' (Our tastes are different!)','Expérimenter le concept de j''aime, j''aime; Créer les techniques artistiques appropriées; Développer la créativité par l''expression créative','["Art objects for demonstration","Visual routine chart","Basic art supplies (crayons, paper, glue)","6-8 art image printouts (20-25 students can see clearly)","Talking stick or special object for sharing","Two easels or wall spaces for voting activity","''J''aime'' and ''J''aime pas'' signs for room sides","Art objects for demonstration","Visual routine chart","Basic art supplies (crayons, paper, glue)"]',NULL,'J''aime, j''aime pas','Show two contrasting art pieces (bright vs dark, busy vs simple). Model preferences with clear gestures: ''J''aime!'' (thumbs up, smile) and ''J''aime pas!'' (gentle shake of head). Students practice with hand gestures for each phrase.','Art Preference Exploration: Present 6-8 diverse art images (different styles, colors, subjects). Students examine each and practice ''J''aime'' or ''J''aime pas'' with reasons: ''J''aime parce que c''est beau!'' Create preference voting with movement - students walk to ''J''aime'' or ''J''aime pas'' sides. Discuss: ''Pourquoi préféres-tu ça?'' Celebrate different opinions: ''Nos goûts sont différents et c''est parfait!''','Preference Circle. Students sit with their ''beau'' object from hunt. Each shares: ''J''aime...'' and points to their object. Others respond with ''C''est beau!'' End with ''Nos goûts sont différents!'' (Our tastes are different!)','Expérimenter le concept de j''aime, j''aime; Créer les techniques artistiques appropriées; Développer la créativité par l''expression créative',NULL,NULL,NULL,'formative','{"observable":["L''élève utilise avec succès au moins une technique avancée","L''élève utilise le vocabulaire: technique, éponge, pochoir","L''élève compare les effets des différentes techniques","L''élève fait des choix techniques délibérés"],"checkpoints":["Démontre la technique de l''éponge","Utilise correctement un pochoir","Explique pourquoi il choisit une technique","Crée des effets variés avec les outils"]}',1,'Plan détaillé avec supports visuels',1756911653323,1757594653868,1,'fr','Arts visuels','{"pourDifficultés":["Provide visual examples and demonstrations","Use simple gestures and basic vocabulary","Allow non-verbal responses initially","Partner with supportive peer"],"pourAvancés":["Encourage detailed French descriptions","Challenge with complex art concepts","Lead activities and help others","Explore creative extensions"],"pourLangue":["Provide visual vocabulary supports","Allow L1 support when needed","Use gestures and pointing","Focus on concrete, visible concepts"],"pourPEI":["Adapt materials and tools as needed","Provide sensory accommodations","Adjust expectations and timing","Offer multiple ways to show understanding"]}','{"vocabulary":["j''aime","beau","préférer"],"visualSupports":["Preference gesture cards, contrasting art examples display, emotion/preference vocabulary chart","Preference vocabulary poster with gestures, sentence starters for opinions, celebration phrases chart","Circle time routine poster, response phrase chart, celebration vocabulary display"],"movementBreaks":["Physical gestures for preferences, movement between contrasting displays","Walking to different sides of room for voting","Moving between art displays for examination","Forming circle, gesturing toward chosen objects, celebration movements"]}',NULL,NULL,NULL,NULL,'{"questions":["Les élèves ont-ils atteint les objectifs?","Quelles adaptations étaient nécessaires?","Que ferais-je différemment la prochaine fois?"]}',NULL,'',4,3,'core',1);
INSERT INTO ETFOLessonPlan VALUES('cmf43u3t80073vj9tf1s39n16',23,'Mes mains créent','cmf43u3t5006vvj9tb8txx7h5',1757343600000,45,'Hand warm-up with finger wiggles and ''magic hands'' gestures. Introduce vocabulary with TPR: hold up ''crayon'' and pretend to draw, wave ''papier'' like a flag, use both hands in creating motion for ''créer''. Students mirror all actions.','Material Exploration Stations: Students rotate through 4 stations exploring different crayon-paper combinations. Station 1: Thick crayons + smooth paper, Station 2: Thin crayons + textured paper, Station 3: Colored crayons + white paper, Station 4: Dark crayons + colored paper. At each station: ''Qu''est-ce qui se passe?'' Practice vocabulary while creating and comparing results: ''Mon crayon crée sur ce papier!''','Creator Circle. Students hold their creation and share: ''J''ai créé avec...'' (holding up their crayon type). Others celebrate: ''Bravo! Tu crées!'' Practice putting materials away properly saying ''Merci, crayon!'' to each tool.','Transformer le concept de mes mains; Créer les techniques artistiques appropriées; Développer la créativité par l''expression créative','["Art objects for demonstration","Visual routine chart","Basic art supplies (crayons, paper, glue)","Various crayons - thick, thin, different colors (enough for 20-25 students)","Different paper types - smooth, textured, colored, white","Simple smocks or paper towels for cleanup","Station labels with French names","Collection trays for each station","Art objects for demonstration","Visual routine chart","Basic art supplies (crayons, paper, glue)"]',NULL,'Mes mains créent','Hand warm-up with finger wiggles and ''magic hands'' gestures. Introduce vocabulary with TPR: hold up ''crayon'' and pretend to draw, wave ''papier'' like a flag, use both hands in creating motion for ''créer''. Students mirror all actions.','Material Exploration Stations: Students rotate through 4 stations exploring different crayon-paper combinations. Station 1: Thick crayons + smooth paper, Station 2: Thin crayons + textured paper, Station 3: Colored crayons + white paper, Station 4: Dark crayons + colored paper. At each station: ''Qu''est-ce qui se passe?'' Practice vocabulary while creating and comparing results: ''Mon crayon crée sur ce papier!''','Creator Circle. Students hold their creation and share: ''J''ai créé avec...'' (holding up their crayon type). Others celebrate: ''Bravo! Tu crées!'' Practice putting materials away properly saying ''Merci, crayon!'' to each tool.','Transformer le concept de mes mains; Créer les techniques artistiques appropriées; Développer la créativité par l''expression créative',NULL,NULL,NULL,'formative','{"observable":["L''élève crée des formes tridimensionnelles","L''élève utilise le vocabulaire: sculpture, modelage, forme","L''élève manipule les matériaux avec intention","L''élève observe et décrit les formes 3D"],"checkpoints":["Crée au moins une forme 3D reconnaissable","Explique sa création en utilisant le vocabulaire","Démontre des techniques de base de modelage","Apprécie les sculptures des autres"]}',1,'Plan détaillé avec supports visuels',1756911653324,1757594653869,1,'fr','Arts visuels','{"pourDifficultés":["Provide visual examples and demonstrations","Use simple gestures and basic vocabulary","Allow non-verbal responses initially","Partner with supportive peer"],"pourAvancés":["Encourage detailed French descriptions","Challenge with complex art concepts","Lead activities and help others","Explore creative extensions"],"pourLangue":["Provide visual vocabulary supports","Allow L1 support when needed","Use gestures and pointing","Focus on concrete, visible concepts"],"pourPEI":["Adapt materials and tools as needed","Provide sensory accommodations","Adjust expectations and timing","Offer multiple ways to show understanding"]}','{"vocabulary":["crayon","papier","créer"],"visualSupports":["TPR action cards for art materials, vocabulary cards with gestures, magic hands routine poster","Station rotation chart, material vocabulary poster, creation process visuals, comparison chart","Creator circle sharing prompts, celebration phrases poster, cleanup routine chart"],"movementBreaks":["Hand warm-up exercises, full-body TPR movements for vocabulary","Moving between stations every 6-7 minutes","Standing and working at different heights","Forming circle, showing creations with gestures, cleanup movements"]}',NULL,NULL,NULL,NULL,'{"questions":["Les élèves ont-ils atteint les objectifs?","Quelles adaptations étaient nécessaires?","Que ferais-je différemment la prochaine fois?"]}',NULL,'',4,4,'core',1);
INSERT INTO ETFOLessonPlan VALUES('cmf43u3t90075vj9ttb2jti1v',23,'Lignes partout!','cmf43u3t5006vvj9tb8txx7h5',1757430000000,45,'Body lines: Students make straight lines with arms (''droite'' - arms out straight), curved lines with bodies (''courbe'' - bend and sway). Draw lines in air following teacher. Use whole body to understand ''ligne'' concept with movement.','Line Creation Adventure: Students explore making different line types on large paper. Challenge: Create a ''ligne droite'' path from one side to another, then add ''ligne courbe'' decorations. Hunt for lines in classroom objects - window frames (droite), plant stems (courbe), book edges (droite). Create collaborative line mural: each student adds their favorite line type while saying ''Ma ligne est...''','Line Gallery. Post artwork at student eye level. Walk gallery style, students point to different line types they see: ''Je vois une ligne droite!'' Celebrate variety and effort with specific praise about line choices.','Représenter les lignes et leurs variations; Créer les techniques artistiques appropriées; Développer l''expression artistique par l''expression créative','["Art objects for demonstration","Visual routine chart","Basic art supplies (crayons, paper, glue)","Large paper (at least 11x17) for each student (20-25 sheets)","Thick crayons or markers in various colors","Masking tape for floor lines (optional)","Examples of linear objects from classroom","Long mural paper for collaborative work","Art objects for demonstration","Visual routine chart","Basic art supplies (crayons, paper, glue)"]',NULL,'Lignes partout!','Body lines: Students make straight lines with arms (''droite'' - arms out straight), curved lines with bodies (''courbe'' - bend and sway). Draw lines in air following teacher. Use whole body to understand ''ligne'' concept with movement.','Line Creation Adventure: Students explore making different line types on large paper. Challenge: Create a ''ligne droite'' path from one side to another, then add ''ligne courbe'' decorations. Hunt for lines in classroom objects - window frames (droite), plant stems (courbe), book edges (droite). Create collaborative line mural: each student adds their favorite line type while saying ''Ma ligne est...''','Line Gallery. Post artwork at student eye level. Walk gallery style, students point to different line types they see: ''Je vois une ligne droite!'' Celebrate variety and effort with specific praise about line choices.','Représenter les lignes et leurs variations; Créer les techniques artistiques appropriées; Développer l''expression artistique par l''expression créative',NULL,NULL,NULL,'formative','{"observable":["L''élève crée une matrice d''impression simple","L''élève réalise plusieurs impressions identiques","L''élève utilise le vocabulaire: gravure, impression, multiples","L''élève comprend le concept de reproduction"],"checkpoints":["Produit au moins 3 impressions similaires","Explique le processus d''impression","Utilise correctement les outils de base","Participe à l''échange d''œuvres"]}',1,'Plan détaillé avec supports visuels',1756911653325,1757594653870,1,'fr','Arts visuels','{"pourDifficultés":["Provide visual examples and demonstrations","Use simple gestures and basic vocabulary","Allow non-verbal responses initially","Partner with supportive peer"],"pourAvancés":["Encourage detailed French descriptions","Challenge with complex art concepts","Lead activities and help others","Explore creative extensions"],"pourLangue":["Provide visual vocabulary supports","Allow L1 support when needed","Use gestures and pointing","Focus on concrete, visible concepts"],"pourPEI":["Adapt materials and tools as needed","Provide sensory accommodations","Adjust expectations and timing","Offer multiple ways to show understanding"]}','{"vocabulary":["ligne","droite","courbe"],"visualSupports":["Line type cards with body positions, movement demonstration poster, vocabulary action chart","Line type reference chart, classroom line hunt checklist, collaborative mural process poster","Gallery walk protocol poster, line identification prompts, celebration vocabulary display"],"movementBreaks":["Full body line making, air drawing exercises, dynamic movement between line types","Walking around classroom for line hunt","Moving along mural paper for collaborative creation","Gallery walk movement, pointing and gesturing at line discoveries"]}',NULL,NULL,NULL,NULL,'{"questions":["Les élèves ont-ils atteint les objectifs?","Quelles adaptations étaient nécessaires?","Que ferais-je différemment la prochaine fois?"]}',NULL,'',4,5,'core',1);
INSERT INTO ETFOLessonPlan VALUES('cmf43u3t90077vj9tugnwxhgm',23,'Formes magiques','cmf43u3t5006vvj9tb8txx7h5',1757516400000,45,'Shape actions: Draw shapes in air while saying names. ''Cercle'' - arms make big circle, ''carré'' - four-cornered gesture with index fingers, ''triangle'' - three-pointed shape with arms above head. Students mirror and chant shape names.','Shape Magic Creation: Students become shape magicians! Use templates to trace and create magic pictures combining all three shapes. Challenge: ''Peux-tu faire un bonhbonhomme avec des formes?'' (Can you make a person with shapes?) Create shape tally chart together - count circles, squares, triangles in classroom. End with shape stamp art: combine shapes to make creative pictures while naming each: ''Un cercle, un carré, un triangle!''','Shape Gallery Share. Students display their magic shape art and identify what shapes they used: ''J''ai utilisé des cercles!'' (I used circles!) Others guess what they see in the shape art: ''Je vois un soleil!'' (I see a sun!)','Créer les formes géométriques de base; Créer la reconnaissance des formes géométriques; Développer l''expression artistique par l''expression créative','["Art objects for demonstration","Visual routine chart","Basic art supplies (crayons, paper, glue)","Shape templates in various sizes (enough for 20-25 students)","Chart paper and markers for class tally","Crayons and paper for individual creative work","Shape stamps or cut-out templates for printing","Shape counting/recording sheets","Art objects for demonstration","Visual routine chart","Basic art supplies (crayons, paper, glue)"]',NULL,'Formes magiques','Shape actions: Draw shapes in air while saying names. ''Cercle'' - arms make big circle, ''carré'' - four-cornered gesture with index fingers, ''triangle'' - three-pointed shape with arms above head. Students mirror and chant shape names.','Shape Magic Creation: Students become shape magicians! Use templates to trace and create magic pictures combining all three shapes. Challenge: ''Peux-tu faire un bonhbonhomme avec des formes?'' (Can you make a person with shapes?) Create shape tally chart together - count circles, squares, triangles in classroom. End with shape stamp art: combine shapes to make creative pictures while naming each: ''Un cercle, un carré, un triangle!''','Shape Gallery Share. Students display their magic shape art and identify what shapes they used: ''J''ai utilisé des cercles!'' (I used circles!) Others guess what they see in the shape art: ''Je vois un soleil!'' (I see a sun!)','Créer les formes géométriques de base; Créer la reconnaissance des formes géométriques; Développer l''expression artistique par l''expression créative',NULL,NULL,NULL,'formative','{"observable":["L''élève crée un collage avec plusieurs couches","L''élève utilise le vocabulaire: collage, couche, composition","L''élève démontre des choix compositionnels délibérés","L''élève explique ses décisions créatives"],"checkpoints":["Planifie sa composition avant de coller","Utilise au moins 3 matériaux différents","Crée un effet de profondeur avec les couches","Présente son œuvre avec vocabulaire approprié"]}',1,'Plan détaillé avec supports visuels',1756911653326,1757594653871,1,'fr','Arts visuels','{"pourDifficultés":["Provide visual examples and demonstrations","Use simple gestures and basic vocabulary","Allow non-verbal responses initially","Partner with supportive peer"],"pourAvancés":["Encourage detailed French descriptions","Challenge with complex art concepts","Lead activities and help others","Explore creative extensions"],"pourLangue":["Provide visual vocabulary supports","Allow L1 support when needed","Use gestures and pointing","Focus on concrete, visible concepts"],"pourPEI":["Adapt materials and tools as needed","Provide sensory accommodations","Adjust expectations and timing","Offer multiple ways to show understanding"]}','{"vocabulary":["cercle","carré","triangle"],"visualSupports":["Shape action cards, vocabulary posters with movements, chanting rhythm chart","Shape identification poster, creation examples display, counting chart template, magic words vocabulary","Gallery sharing prompts, shape vocabulary reminder chart, guessing game sentence starters"],"movementBreaks":["Full-body shape making, air drawing, rhythmic chanting with movement","Moving around classroom for shape hunt and counting","Stamping activities with standing/reaching movements","Displaying and moving around gallery, gesturing toward shape discoveries"]}',NULL,NULL,NULL,NULL,'{"questions":["Les élèves ont-ils atteint les objectifs?","Quelles adaptations étaient nécessaires?","Que ferais-je différemment la prochaine fois?"]}',NULL,'',4,6,'core',1);
INSERT INTO ETFOLessonPlan VALUES('cmf43u3ta0079vj9trvao3z72',23,'Couleurs vivantes','cmf43u3t5006vvj9tb8txx7h5',1757602800000,45,'Color energy movement: ''Rouge'' - stomp like fire, ''bleu'' - flow like water, ''jaune'' - bounce like sunshine. Students mirror movements while chanting color names. Show how colors can have personalities and feelings.','Color Intention Exploration: Students choose ONE color to work with based on how they feel: ''Je me sens comme le rouge today!'' Create intentional color art expressing that feeling. Experiment with color layering using transparent sheets: ''Que se passe-t-il quand..?'' (What happens when..?) Document color mixing discoveries. Share color intention: ''J''ai choisi le bleu parce que...'' Create class color feeling chart.','Color Intention Share. Students explain their color choices: ''J''ai choisi le rouge pour...'' (I chose red for...). Others listen and respond with color connections: ''Le rouge me fait penser à...'' (Red makes me think of...)','Dessiner les couleurs primaires et secondaires; Créer des techniques de mélange de couleurs; Développer l''expression artistique par l''expression créative','["Art objects for demonstration","Visual routine chart","Basic art supplies (crayons, paper, glue)","Primary color paints or thick markers (enough for 20-25 students)","Transparent color sheets for layering experiments","White paper for individual work","Paint brushes (various sizes)","Water containers for cleanup","Chart paper for class color feelings record","Art objects for demonstration","Visual routine chart","Basic art supplies (crayons, paper, glue)"]',NULL,'Couleurs vivantes','Color energy movement: ''Rouge'' - stomp like fire, ''bleu'' - flow like water, ''jaune'' - bounce like sunshine. Students mirror movements while chanting color names. Show how colors can have personalities and feelings.','Color Intention Exploration: Students choose ONE color to work with based on how they feel: ''Je me sens comme le rouge today!'' Create intentional color art expressing that feeling. Experiment with color layering using transparent sheets: ''Que se passe-t-il quand..?'' (What happens when..?) Document color mixing discoveries. Share color intention: ''J''ai choisi le bleu parce que...'' Create class color feeling chart.','Color Intention Share. Students explain their color choices: ''J''ai choisi le rouge pour...'' (I chose red for...). Others listen and respond with color connections: ''Le rouge me fait penser à...'' (Red makes me think of...)','Dessiner les couleurs primaires et secondaires; Créer des techniques de mélange de couleurs; Développer l''expression artistique par l''expression créative',NULL,NULL,NULL,'formative','{"observable":["L''élève explore différentes techniques textiles","L''élève utilise le vocabulaire: textile, tisser, coudre","L''élève crée des œuvres textiles simples","L''élève fait des connexions avec les textiles quotidiens"],"checkpoints":["Essaie au moins deux techniques textiles","Identifie différentes structures textiles","Utilise le vocabulaire pour décrire son travail","Crée une petite œuvre textile personnelle"]}',1,'Plan détaillé avec supports visuels',1756911653327,1757594653872,1,'fr','Arts visuels','{"pourDifficultés":["Provide visual examples and demonstrations","Use simple gestures and basic vocabulary","Allow non-verbal responses initially","Partner with supportive peer"],"pourAvancés":["Encourage detailed French descriptions","Challenge with complex art concepts","Lead activities and help others","Explore creative extensions"],"pourLangue":["Provide visual vocabulary supports","Allow L1 support when needed","Use gestures and pointing","Focus on concrete, visible concepts"],"pourPEI":["Adapt materials and tools as needed","Provide sensory accommodations","Adjust expectations and timing","Offer multiple ways to show understanding"]}','{"vocabulary":["rouge","bleu","jaune"],"visualSupports":["Color energy cards with movements, personality/feeling vocabulary, color association poster","Color mixing chart, feeling vocabulary poster, intention-sharing sentence starters, discovery recording sheet","Intention sharing prompts, color connection vocabulary, active listening visual cues"],"movementBreaks":["Dynamic movements for each color, full-body color expressions, rhythmic chanting","Moving between mixing station and work space","Standing to demonstrate color layering techniques","Sharing circle formation, gesturing toward artwork, responsive body language"]}',NULL,NULL,NULL,NULL,'{"questions":["Les élèves ont-ils atteint les objectifs?","Quelles adaptations étaient nécessaires?","Que ferais-je différemment la prochaine fois?"]}',NULL,'',4,7,'core',1);
INSERT INTO ETFOLessonPlan VALUES('cmf43u3tb007bvj9to90xhvgd',23,'Textures à toucher','cmf43u3t5006vvj9tb8txx7h5',1757689200000,45,'Texture box mystery: Without looking, students feel objects of different textures. Describe with actions: ''doux'' - gentle pet motion, ''rugueux'' - scratchy clawing motion, ''toucher'' - reaching out with fingertips. Guess and reveal objects.','Texture Art Detective Work: Students explore texture samples, describing each: ''C''est doux comme...'' or ''C''est rugueux comme...'' Create texture rubbings using crayons over textured surfaces. Mystery texture guessing game - feel without looking: ''Je touche quelque chose de...'' Make texture collage combining real textures with drawn textures while practicing vocabulary.','Texture Gallery Walk. Students touch each other''s texture artwork (gently!) and identify what they feel: ''Je touche... c''est doux!'' Partner discussions about texture choices and techniques used.','Peindre les textures variées; Créer les techniques artistiques appropriées; Développer l''expression artistique par l''expression créative','["Art objects for demonstration","Visual routine chart","Basic art supplies (crayons, paper, glue)","Texture sample collection - sandpaper, cotton, fabric, bubble wrap (enough for 20-25 students)","Crayons and various paper types for rubbings","Mystery texture box or bag for guessing game","Glue sticks for texture collages","Collection sheets for texture organization","Art objects for demonstration","Visual routine chart","Basic art supplies (crayons, paper, glue)"]',NULL,'Textures à toucher','Texture box mystery: Without looking, students feel objects of different textures. Describe with actions: ''doux'' - gentle pet motion, ''rugueux'' - scratchy clawing motion, ''toucher'' - reaching out with fingertips. Guess and reveal objects.','Texture Art Detective Work: Students explore texture samples, describing each: ''C''est doux comme...'' or ''C''est rugueux comme...'' Create texture rubbings using crayons over textured surfaces. Mystery texture guessing game - feel without looking: ''Je touche quelque chose de...'' Make texture collage combining real textures with drawn textures while practicing vocabulary.','Texture Gallery Walk. Students touch each other''s texture artwork (gently!) and identify what they feel: ''Je touche... c''est doux!'' Partner discussions about texture choices and techniques used.','Peindre les textures variées; Créer les techniques artistiques appropriées; Développer l''expression artistique par l''expression créative',NULL,NULL,NULL,'formative','{"observable":["L''élève combine avec succès plusieurs techniques","L''élève utilise le vocabulaire: mixte, complexe, intégrer","L''élève planifie ses combinaisons de techniques","L''élève explique ses choix d''intégration"],"checkpoints":["Intègre au moins 2 techniques différentes","Planifie avant d''exécuter","Utilise le vocabulaire pour décrire son processus","Crée des effets uniques avec les combinaisons"]}',1,'Plan détaillé avec supports visuels',1756911653327,1757594653873,1,'fr','Arts visuels','{"pourDifficultés":["Provide visual examples and demonstrations","Use simple gestures and basic vocabulary","Allow non-verbal responses initially","Partner with supportive peer"],"pourAvancés":["Encourage detailed French descriptions","Challenge with complex art concepts","Lead activities and help others","Explore creative extensions"],"pourLangue":["Provide visual vocabulary supports","Allow L1 support when needed","Use gestures and pointing","Focus on concrete, visible concepts"],"pourPEI":["Adapt materials and tools as needed","Provide sensory accommodations","Adjust expectations and timing","Offer multiple ways to show understanding"]}','{"vocabulary":["toucher","doux","rugueux"],"visualSupports":["Relevant vocabulary cards and visual aids for lesson content","Texture vocabulary poster with touch demonstrations, rubbing technique visuals, comparison chart for descriptions","Relevant vocabulary cards and visual aids for lesson content"],"movementBreaks":["Natural movement opportunities during activity","Moving around room to find textured surfaces for rubbings","Active texture exploration and handling materials","Natural movement opportunities during activity"]}',NULL,NULL,NULL,NULL,'{"questions":["Les élèves ont-ils atteint les objectifs?","Quelles adaptations étaient nécessaires?","Que ferais-je différemment la prochaine fois?"]}',NULL,'',4,8,'core',1);
INSERT INTO ETFOLessonPlan VALUES('cmf43u3tc007dvj9tyfatrizr',23,'Mes sentiments en art','cmf43u3t5006vvj9tb8txx7h5',1757948400000,45,'Emotion mirror: Teacher shows emotion faces and students mirror while saying French words. ''Content'' - big smile and relaxed shoulders, ''triste'' - sad face and drooping posture, ''excité'' - bouncy energy and wide eyes. Practice transitioning between emotions.','Emotion Art Expression: Students choose their current feeling: ''Aujourd''hui je me sens...'' and select colors/techniques that match. Look in mirrors to practice emotion faces, then create art showing that feeling. Emotion guessing game: others look at artwork and guess: ''Tu te sens content?'' Share emotion vocabulary while creating. Build class emotion art gallery with French labels.','Emotion Art Share. Students hold artwork and share their emotion choice: ''Mon art montre que je suis content!'' Others respond supportively: ''Je comprends ton sentiment!'' (I understand your feeling!)','Modeler le concept de mes sentiments; Créer les techniques artistiques appropriées; Développer la motricité fine par l''expression créative','["Art objects for demonstration","Visual routine chart","Basic art supplies (crayons, paper, glue)","Emotion-themed art examples for inspiration","Full range of colors - paints, crayons, markers (for 20-25 students)","Paper for individual emotion art pieces","Mirrors for emotion face practice (hand mirrors work)","Labels for emotion gallery display","Art objects for demonstration","Visual routine chart","Basic art supplies (crayons, paper, glue)"]',NULL,'Mes sentiments en art','Emotion mirror: Teacher shows emotion faces and students mirror while saying French words. ''Content'' - big smile and relaxed shoulders, ''triste'' - sad face and drooping posture, ''excité'' - bouncy energy and wide eyes. Practice transitioning between emotions.','Emotion Art Expression: Students choose their current feeling: ''Aujourd''hui je me sens...'' and select colors/techniques that match. Look in mirrors to practice emotion faces, then create art showing that feeling. Emotion guessing game: others look at artwork and guess: ''Tu te sens content?'' Share emotion vocabulary while creating. Build class emotion art gallery with French labels.','Emotion Art Share. Students hold artwork and share their emotion choice: ''Mon art montre que je suis content!'' Others respond supportively: ''Je comprends ton sentiment!'' (I understand your feeling!)','Modeler le concept de mes sentiments; Créer les techniques artistiques appropriées; Développer la motricité fine par l''expression créative',NULL,NULL,NULL,'formative','{"observable":["L''élève identifie des éléments de son style personnel","L''élève utilise le vocabulaire: style, personnel, développer","L''élève crée consciemment dans son style","L''élève articule ses choix stylistiques"],"checkpoints":["Identifie 2-3 caractéristiques de son style","Crée une œuvre qui exprime son style personnel","Présente son style avec confiance","Apprécie la diversité des styles des autres"]}',1,'Plan détaillé avec supports visuels',1756911653328,1757594653874,1,'fr','Arts visuels','{"pourDifficultés":["Provide visual examples and demonstrations","Use simple gestures and basic vocabulary","Allow non-verbal responses initially","Partner with supportive peer"],"pourAvancés":["Encourage detailed French descriptions","Challenge with complex art concepts","Lead activities and help others","Explore creative extensions"],"pourLangue":["Provide visual vocabulary supports","Allow L1 support when needed","Use gestures and pointing","Focus on concrete, visible concepts"],"pourPEI":["Adapt materials and tools as needed","Provide sensory accommodations","Adjust expectations and timing","Offer multiple ways to show understanding"]}','{"vocabulary":["content","triste","excité"],"visualSupports":["Relevant vocabulary cards and visual aids for lesson content","Emotion vocabulary chart with faces, color-feeling association poster, mirror practice routine, gallery labels template","Relevant vocabulary cards and visual aids for lesson content"],"movementBreaks":["Natural movement opportunities during activity","Mirror practice with facial expressions and body language","Moving around to set up emotion gallery display","Natural movement opportunities during activity"]}',NULL,NULL,NULL,NULL,'{"questions":["Les élèves ont-ils atteint les objectifs?","Quelles adaptations étaient nécessaires?","Que ferais-je différemment la prochaine fois?"]}',NULL,'',4,9,'core',1);
INSERT INTO ETFOLessonPlan VALUES('cmf43u3td007fvj9tk5q6i3pt',23,'Outils d''artiste','cmf43u3t5006vvj9tb8txx7h5',1758034800000,45,'Tool parade: Hold up each tool type with exaggerated demonstration. ''Pinceau'' - painting gestures in air, ''colle'' - sticky finger motions, ''ciseaux'' - cutting actions (safety emphasis). Students practice motions while chanting tool names.','Artist Tool Challenge: Students rotate through tool stations, learning proper use and French names. Station 1: Pinceau painting techniques, Station 2: Ciseaux cutting practice, Station 3: Colle collage creation. Each station: ''Comment utilise-t-on...?'' Create one collaborative artwork using ALL three tools. Practice tool requests: ''Puis-je avoir le pinceau?'' Share favorite tool and explain why.','Artist Tool Talk. Students show their multi-tool artwork and explain which tools they used: ''J''ai utilisé les ciseaux pour...'' Others ask questions: ''Pourquoi le pinceau?'' Tool cleanup becomes vocabulary practice.','Transformer le concept de outils d''artiste; Créer les techniques artistiques appropriées; Développer la motricité fine par l''expression créative','["Art objects for demonstration","Visual routine chart","Basic art supplies (crayons, paper, glue)","Various paintbrushes - thick, thin, flat (enough for 20-25 students)","Child-safe scissors (checked for proper function)","Glue sticks (enough for sharing at stations)","Paper in different colors and textures","Paint or ink pads for painting station","Newspapers/plastic for work surface protection","Station instruction cards with French labels","Art objects for demonstration","Visual routine chart","Basic art supplies (crayons, paper, glue)"]',NULL,'Outils d''artiste','Tool parade: Hold up each tool type with exaggerated demonstration. ''Pinceau'' - painting gestures in air, ''colle'' - sticky finger motions, ''ciseaux'' - cutting actions (safety emphasis). Students practice motions while chanting tool names.','Artist Tool Challenge: Students rotate through tool stations, learning proper use and French names. Station 1: Pinceau painting techniques, Station 2: Ciseaux cutting practice, Station 3: Colle collage creation. Each station: ''Comment utilise-t-on...?'' Create one collaborative artwork using ALL three tools. Practice tool requests: ''Puis-je avoir le pinceau?'' Share favorite tool and explain why.','Artist Tool Talk. Students show their multi-tool artwork and explain which tools they used: ''J''ai utilisé les ciseaux pour...'' Others ask questions: ''Pourquoi le pinceau?'' Tool cleanup becomes vocabulary practice.','Transformer le concept de outils d''artiste; Créer les techniques artistiques appropriées; Développer la motricité fine par l''expression créative',NULL,NULL,NULL,'formative','{"observable":["L''élève choisit un concept à exprimer","L''élève utilise le vocabulaire: concept, idée, exprimer","L''élève crée une œuvre avec intention conceptuelle","L''élève explique le lien entre son idée et son œuvre"],"checkpoints":["Articule clairement le concept choisi","Fait des choix artistiques délibérés pour exprimer l''idée","Présente son œuvre conceptuelle avec confiance","Apprécie les concepts exprimés par les autres"]}',1,'Plan détaillé avec supports visuels',1756911653329,1757594653875,1,'fr','Arts visuels','{"pourDifficultés":["Provide visual examples and demonstrations","Use simple gestures and basic vocabulary","Allow non-verbal responses initially","Partner with supportive peer"],"pourAvancés":["Encourage detailed French descriptions","Challenge with complex art concepts","Lead activities and help others","Explore creative extensions"],"pourLangue":["Provide visual vocabulary supports","Allow L1 support when needed","Use gestures and pointing","Focus on concrete, visible concepts"],"pourPEI":["Adapt materials and tools as needed","Provide sensory accommodations","Adjust expectations and timing","Offer multiple ways to show understanding"]}','{"vocabulary":["pinceau","colle","ciseaux"],"visualSupports":["Relevant vocabulary cards and visual aids for lesson content","Tool vocabulary poster with proper usage, station rotation chart, safety reminder visuals, tool request phrase cards","Relevant vocabulary cards and visual aids for lesson content"],"movementBreaks":["Natural movement opportunities during activity","Rotating between three active stations","Standing and demonstrating tool techniques","Natural movement opportunities during activity"]}',NULL,NULL,NULL,NULL,'{"questions":["Les élèves ont-ils atteint les objectifs?","Quelles adaptations étaient nécessaires?","Que ferais-je différemment la prochaine fois?"]}',NULL,'',4,10,'core',1);
INSERT INTO ETFOLessonPlan VALUES('cmf43u3td007hvj9t8h3cz6fy',23,'Techniques nouvelles','cmf43u3t5006vvj9tb8txx7h5',1758121200000,45,'Technique demonstrations: Show each new technique with exaggerated actions. ''Mélanger'' - stirring/mixing motions, ''tamponner'' - dabbing/stamping actions, ''gratter'' - gentle scratching movements. Students practice motions in air while learning pronunciation.','New Technique Laboratory: Students become technique scientists! Try all three techniques: mélanger colors to discover new shades, tamponner with sponges to create patterns, gratter through crayon layers to reveal underneath. Document discoveries: ''Quand je mélange rouge et jaune...'' Choose favorite technique for final creation. Share technique tips with classmates.','Technique Gallery. Students explain which technique they chose and why: ''J''ai préféré mélanger parce que...'' Others observe technique effects in different artworks. Celebrate variety of choices and discoveries made.','Représenter le concept de techniques nouvelles; Créer les techniques artistiques appropriées; Développer la motricité fine par l''expression créative','["Art objects for demonstration","Visual routine chart","Basic art supplies (crayons, paper, glue)","Paint for mixing experiments (primary colors for 20-25 students)","Sponges in various shapes for stamping/dabbing","Crayons and safe scratch tools (popsicle sticks work)","Black crayon/paint for scratch technique base layers","Various paper types for different technique exploration","Discovery recording sheets","Mixing palettes or paper plates","Art objects for demonstration","Visual routine chart","Basic art supplies (crayons, paper, glue)"]',NULL,'Techniques nouvelles','Technique demonstrations: Show each new technique with exaggerated actions. ''Mélanger'' - stirring/mixing motions, ''tamponner'' - dabbing/stamping actions, ''gratter'' - gentle scratching movements. Students practice motions in air while learning pronunciation.','New Technique Laboratory: Students become technique scientists! Try all three techniques: mélanger colors to discover new shades, tamponner with sponges to create patterns, gratter through crayon layers to reveal underneath. Document discoveries: ''Quand je mélange rouge et jaune...'' Choose favorite technique for final creation. Share technique tips with classmates.','Technique Gallery. Students explain which technique they chose and why: ''J''ai préféré mélanger parce que...'' Others observe technique effects in different artworks. Celebrate variety of choices and discoveries made.','Représenter le concept de techniques nouvelles; Créer les techniques artistiques appropriées; Développer la motricité fine par l''expression créative',NULL,NULL,NULL,'formative','{"observable":["L''élève utilise le vocabulaire critique approprié","L''élève fait des observations précises sur les œuvres","L''élève donne des critiques constructives","L''élève réfléchit sur les critiques reçues"],"checkpoints":["Utilise au moins 3 termes de vocabulaire artistique","Identifie techniques et choix artistiques","Formule des commentaires constructifs","Planifie des améliorations basées sur les critiques"]}',1,'Plan détaillé avec supports visuels',1756911653330,1757594653876,1,'fr','Arts visuels','{"pourDifficultés":["Provide visual examples and demonstrations","Use simple gestures and basic vocabulary","Allow non-verbal responses initially","Partner with supportive peer"],"pourAvancés":["Encourage detailed French descriptions","Challenge with complex art concepts","Lead activities and help others","Explore creative extensions"],"pourLangue":["Provide visual vocabulary supports","Allow L1 support when needed","Use gestures and pointing","Focus on concrete, visible concepts"],"pourPEI":["Adapt materials and tools as needed","Provide sensory accommodations","Adjust expectations and timing","Offer multiple ways to show understanding"]}','{"vocabulary":["mélanger","tamponner","gratter"],"visualSupports":["Relevant vocabulary cards and visual aids for lesson content","Technique demonstration posters, discovery vocabulary chart, step-by-step visual guides, comparison recording sheet","Relevant vocabulary cards and visual aids for lesson content"],"movementBreaks":["Natural movement opportunities during activity","Moving between technique stations","Active demonstration of different motions for each technique","Natural movement opportunities during activity"]}',NULL,NULL,NULL,NULL,'{"questions":["Les élèves ont-ils atteint les objectifs?","Quelles adaptations étaient nécessaires?","Que ferais-je différemment la prochaine fois?"]}',NULL,'',4,11,'core',1);
INSERT INTO ETFOLessonPlan VALUES('cmf43u3te007jvj9trk9ul1mv',23,'Mon style unique','cmf43u3t5006vvj9tb8txx7h5',1758207600000,45,'Style celebration: Look at student artwork from previous lessons. Point out different approaches: ''Voici le style de...'' Emphasize that different is wonderful. Students practice saying ''Mon style est unique!'' with proud gestures.','Style Discovery Portfolio Review: Students examine their artwork collection from all previous lessons. Identify patterns: ''Je préfère toujours...'' or ''Mon style utilise beaucoup de...'' Create ''Mon Style'' poster showing their favorite techniques, colors, and subjects. Practice describing their unique artistic voice: ''Mon art est spécial parce que...'' Share style discoveries with art buddy.','Style Celebration Circle. Students share one thing that makes their style special: ''Mon style est spécial parce que...'' Others respond with appreciation: ''Ton style est unique!'' End with group cheer about everyone being special artists.','Créer le concept de mon style; Créer les techniques artistiques appropriées; Développer la motricité fine par l''expression créative','["Art objects for demonstration","Visual routine chart","Basic art supplies (crayons, paper, glue)","Previous lesson artwork collections (organized by student)","Portfolio folders or display spaces","Full art supply access for style poster creation","Mirrors for self-reflection moments","''Mon Style'' poster templates","Vocabulary cards for style descriptions","Art objects for demonstration","Visual routine chart","Basic art supplies (crayons, paper, glue)"]',NULL,'Mon style unique','Style celebration: Look at student artwork from previous lessons. Point out different approaches: ''Voici le style de...'' Emphasize that different is wonderful. Students practice saying ''Mon style est unique!'' with proud gestures.','Style Discovery Portfolio Review: Students examine their artwork collection from all previous lessons. Identify patterns: ''Je préfère toujours...'' or ''Mon style utilise beaucoup de...'' Create ''Mon Style'' poster showing their favorite techniques, colors, and subjects. Practice describing their unique artistic voice: ''Mon art est spécial parce que...'' Share style discoveries with art buddy.','Style Celebration Circle. Students share one thing that makes their style special: ''Mon style est spécial parce que...'' Others respond with appreciation: ''Ton style est unique!'' End with group cheer about everyone being special artists.','Créer le concept de mon style; Créer les techniques artistiques appropriées; Développer la motricité fine par l''expression créative',NULL,NULL,NULL,'formative','{"observable":["L''élève identifie les étapes de son processus créatif","L''élève utilise le vocabulaire: processus, créatif, documenter","L''élève documente ses choix et décisions","L''élève réfléchit sur sa façon de créer"],"checkpoints":["Décrit au moins 3 étapes de son processus","Documente ses décisions créatives","Partage ses insights sur son approche créative","Apprécie la diversité des processus des autres"]}',1,'Plan détaillé avec supports visuels',1756911653331,1757594653877,1,'fr','Arts visuels','{"pourDifficultés":["Provide visual examples and demonstrations","Use simple gestures and basic vocabulary","Allow non-verbal responses initially","Partner with supportive peer"],"pourAvancés":["Encourage detailed French descriptions","Challenge with complex art concepts","Lead activities and help others","Explore creative extensions"],"pourLangue":["Provide visual vocabulary supports","Allow L1 support when needed","Use gestures and pointing","Focus on concrete, visible concepts"],"pourPEI":["Adapt materials and tools as needed","Provide sensory accommodations","Adjust expectations and timing","Offer multiple ways to show understanding"]}','{"vocabulary":["style","unique","spécial"],"visualSupports":["Relevant vocabulary cards and visual aids for lesson content","Style vocabulary poster, portfolio organization guide, self-reflection prompts, sharing sentence starters","Relevant vocabulary cards and visual aids for lesson content"],"movementBreaks":["Natural movement opportunities during activity","Moving around to organize and examine portfolio pieces","Partner sharing with movement between workspaces","Natural movement opportunities during activity"]}',NULL,NULL,NULL,NULL,'{"questions":["Les élèves ont-ils atteint les objectifs?","Quelles adaptations étaient nécessaires?","Que ferais-je différemment la prochaine fois?"]}',NULL,'',4,12,'core',1);
INSERT INTO ETFOLessonPlan VALUES('cmf43u3tf007lvj9t5vycdhtp',23,'Partager mes idées','cmf43u3t5006vvj9tb8txx7h5',1758294000000,45,'Communication practice: Teacher models different ways to share art. ''Expliquer'' - pointing and describing, ''montrer'' - displaying and indicating features, ''raconter'' - telling story about the art. Students practice each gesture style.','Artist Interview Experience: Students become art reporters and artists! Practice interview questions: ''Peux-tu expliquer ton art?'' Take turns being interviewed about their favorite artwork. Use ''microphone'' prop for official feel. Practice explaining, showing, and telling stories about their creations. Create class art magazine with student quotes and artwork photos.','Communication Celebration. Students vote for different communication awards: ''Meilleure explication'' (best explanation), ''Meilleure histoire'' (best story), ''Meilleure présentation'' (best presentation). Everyone gets recognized for something special.','Dessiner le concept de partager mes; Créer les techniques artistiques appropriées; Développer le sens esthétique par l''expression créative','["Art objects for demonstration","Visual routine chart","Basic art supplies (crayons, paper, glue)","Student artwork from previous lessons (selected favorites)","Interview question prompt cards in French","''Microphone'' prop for authentic presentations","Comfortable presentation space with seating","Class art magazine template pages","Camera or device for artwork documentation (if available)","Art objects for demonstration","Visual routine chart","Basic art supplies (crayons, paper, glue)"]',NULL,'Partager mes idées','Communication practice: Teacher models different ways to share art. ''Expliquer'' - pointing and describing, ''montrer'' - displaying and indicating features, ''raconter'' - telling story about the art. Students practice each gesture style.','Artist Interview Experience: Students become art reporters and artists! Practice interview questions: ''Peux-tu expliquer ton art?'' Take turns being interviewed about their favorite artwork. Use ''microphone'' prop for official feel. Practice explaining, showing, and telling stories about their creations. Create class art magazine with student quotes and artwork photos.','Communication Celebration. Students vote for different communication awards: ''Meilleure explication'' (best explanation), ''Meilleure histoire'' (best story), ''Meilleure présentation'' (best presentation). Everyone gets recognized for something special.','Dessiner le concept de partager mes; Créer les techniques artistiques appropriées; Développer le sens esthétique par l''expression créative',NULL,NULL,NULL,'formative','{"observable":["L''élève contribue activement au projet d''équipe","L''élève utilise le vocabulaire: collaboration, avancé, technique","L''élève intègre ses compétences avec celles des autres","L''élève respecte et valorise les contributions des autres"],"checkpoints":["Remplit son rôle dans l''équipe efficacement","Contribue avec des techniques avancées maîtrisées","Communique et coordonne avec les coequipiers","Présente fier du travail collaboratif"]}',1,'Plan détaillé avec supports visuels',1756911653331,1757594653878,1,'fr','Arts visuels','{"pourDifficultés":["Provide visual examples and demonstrations","Use simple gestures and basic vocabulary","Allow non-verbal responses initially","Partner with supportive peer"],"pourAvancés":["Encourage detailed French descriptions","Challenge with complex art concepts","Lead activities and help others","Explore creative extensions"],"pourLangue":["Provide visual vocabulary supports","Allow L1 support when needed","Use gestures and pointing","Focus on concrete, visible concepts"],"pourPEI":["Adapt materials and tools as needed","Provide sensory accommodations","Adjust expectations and timing","Offer multiple ways to show understanding"]}','{"vocabulary":["expliquer","montrer","raconter"],"visualSupports":["Relevant vocabulary cards and visual aids for lesson content","Interview question cards, presentation tips poster, vocabulary for art discussion, confidence-building phrases","Relevant vocabulary cards and visual aids for lesson content"],"movementBreaks":["Natural movement opportunities during activity","Moving between interviewer and artist roles","Standing presentations and audience engagement","Natural movement opportunities during activity"]}',NULL,NULL,NULL,NULL,'{"questions":["Les élèves ont-ils atteint les objectifs?","Quelles adaptations étaient nécessaires?","Que ferais-je différemment la prochaine fois?"]}',NULL,'',4,13,'core',1);
INSERT INTO ETFOLessonPlan VALUES('cmf43u3tg007nvj9tupbo0hyi',23,'Art dans ma vie','cmf43u3t5006vvj9tb8txx7h5',1758553200000,45,'Daily art hunt: Students think about their morning routine and identify art they saw/used: clothing patterns, cereal box designs, toothbrush colors. Practice vocabulary: ''L''art est important dans ma vie quotidienne!'' (Art is important in my daily life!)','Art Life Connection Mapping: Students create visual map of art in their daily life - from morning (colorful toothbrush) to bedtime (patterned pajamas). Draw or list art connections: ''Dans ma chambre, il y a...'', ''Dans la cuisine, je vois...'' Plan one new way to add art to daily routine. Share discoveries: ''L''art est important dans ma vie parce que...''','Art Life Commitment. Students share one way they will use art in their daily life: ''L''art va être important dans ma vie parce que...'' Create class commitment to noticing and creating art every day.','Peindre le concept de art dans; Créer les techniques artistiques appropriées; Développer le sens esthétique par l''expression créative','["Art objects for demonstration","Visual routine chart","Basic art supplies (crayons, paper, glue)","Paper for life maps (large enough for drawings and words)","Crayons and markers for colorful illustrations","Daily routine planning sheets with French prompts","Examples of everyday art objects for inspiration","Home art checklist to take home","Art objects for demonstration","Visual routine chart","Basic art supplies (crayons, paper, glue)"]',NULL,'Art dans ma vie','Daily art hunt: Students think about their morning routine and identify art they saw/used: clothing patterns, cereal box designs, toothbrush colors. Practice vocabulary: ''L''art est important dans ma vie quotidienne!'' (Art is important in my daily life!)','Art Life Connection Mapping: Students create visual map of art in their daily life - from morning (colorful toothbrush) to bedtime (patterned pajamas). Draw or list art connections: ''Dans ma chambre, il y a...'', ''Dans la cuisine, je vois...'' Plan one new way to add art to daily routine. Share discoveries: ''L''art est important dans ma vie parce que...''','Art Life Commitment. Students share one way they will use art in their daily life: ''L''art va être important dans ma vie parce que...'' Create class commitment to noticing and creating art every day.','Peindre le concept de art dans; Créer les techniques artistiques appropriées; Développer le sens esthétique par l''expression créative',NULL,NULL,NULL,'formative','{"observable":["L''élève contribue à créer une installation spatiale","L''élève utilise le vocabulaire: installation, échelle, espace","L''élève considère les effets spatiaux et d''échelle","L''élève navigue et apprécie les installations des autres"],"checkpoints":["Participe à la planification spatiale de l''installation","Utilise les techniques apprises à grande échelle","Décrit l''impact de l''échelle sur l''expérience","Respecte et apprécie l''espace artistique créé"]}',1,'Plan détaillé avec supports visuels',1756911653332,1757594653879,1,'fr','Arts visuels','{"pourDifficultés":["Provide visual examples and demonstrations","Use simple gestures and basic vocabulary","Allow non-verbal responses initially","Partner with supportive peer"],"pourAvancés":["Encourage detailed French descriptions","Challenge with complex art concepts","Lead activities and help others","Explore creative extensions"],"pourLangue":["Provide visual vocabulary supports","Allow L1 support when needed","Use gestures and pointing","Focus on concrete, visible concepts"],"pourPEI":["Adapt materials and tools as needed","Provide sensory accommodations","Adjust expectations and timing","Offer multiple ways to show understanding"]}','{"vocabulary":["important","quotidien","utiliser"],"visualSupports":["Relevant vocabulary cards and visual aids for lesson content","Daily routine vocabulary poster, art identification guide, life mapping example, sharing prompts for family discussions","Relevant vocabulary cards and visual aids for lesson content"],"movementBreaks":["Natural movement opportunities during activity","Walking around classroom to find more art examples","Moving to share life maps with different partners","Natural movement opportunities during activity"]}',NULL,NULL,NULL,NULL,'{"questions":["Les élèves ont-ils atteint les objectifs?","Quelles adaptations étaient nécessaires?","Que ferais-je différemment la prochaine fois?"]}',NULL,'',4,14,'core',1);
INSERT INTO ETFOLessonPlan VALUES('cmf43u3th007pvj9t3l3q8xtc',23,'Atelier libre','cmf43u3t5006vvj9tb8txx7h5',1758639600000,45,'Art vocabulary review game: Students take turns acting out vocabulary words from lessons 1-14 while others guess in French. Quick energy builder that reinforces all learned terms before independent work time.','Free Choice Art Studio: Students choose their own project using any techniques learned. Options: continue a previous artwork, try combining techniques, create gift for family, or experiment with new ideas. Practice requesting materials in French: ''Puis-je avoir...?'' Teacher circulates providing vocabulary support. Focus on creative process and French expression during creation.','Artist Reflection. Students complete sentence starters: ''Aujourd''hui j''ai utilisé...'' (Today I used...) ''Ma technique préférée était...'' (My favorite technique was...) ''Je suis fier de...'' (I''m proud of...)','Modeler le concept de atelier libre; Créer les techniques artistiques appropriées; Développer le sens esthétique par l''expression créative','["Art objects for demonstration","Visual routine chart","Basic art supplies (crayons, paper, glue)","All art materials from previous lessons organized by type","Planning sheets for students who want structure (optional)","Clear organization systems for independent material access","Material request phrase cards","Timer for sharing reminders","Art objects for demonstration","Visual routine chart","Basic art supplies (crayons, paper, glue)"]',NULL,'Atelier libre','Art vocabulary review game: Students take turns acting out vocabulary words from lessons 1-14 while others guess in French. Quick energy builder that reinforces all learned terms before independent work time.','Free Choice Art Studio: Students choose their own project using any techniques learned. Options: continue a previous artwork, try combining techniques, create gift for family, or experiment with new ideas. Practice requesting materials in French: ''Puis-je avoir...?'' Teacher circulates providing vocabulary support. Focus on creative process and French expression during creation.','Artist Reflection. Students complete sentence starters: ''Aujourd''hui j''ai utilisé...'' (Today I used...) ''Ma technique préférée était...'' (My favorite technique was...) ''Je suis fier de...'' (I''m proud of...)','Modeler le concept de atelier libre; Créer les techniques artistiques appropriées; Développer le sens esthétique par l''expression créative',NULL,NULL,NULL,'formative','{"observable":["L''élève identifie ses techniques les mieux maîtrisées","L''élève utilise le vocabulaire: maîtrise, démontrer, choisi","L''élève exécute des techniques avec compétence","L''élève présente ses accomplissements avec fierté"],"checkpoints":["Démontre maîtrise d''au moins 2 techniques avancées","Crée une œuvre qui reflète ses compétences","Présente avec confiance et vocabulaire approprié","Reconnaît et célèbre sa croissance artistique"]}',1,'Plan détaillé avec supports visuels',1756911653333,1757594653880,1,'fr','Arts visuels','{"pourDifficultés":["Provide visual examples and demonstrations","Use simple gestures and basic vocabulary","Allow non-verbal responses initially","Partner with supportive peer"],"pourAvancés":["Encourage detailed French descriptions","Challenge with complex art concepts","Lead activities and help others","Explore creative extensions"],"pourLangue":["Provide visual vocabulary supports","Allow L1 support when needed","Use gestures and pointing","Focus on concrete, visible concepts"],"pourPEI":["Adapt materials and tools as needed","Provide sensory accommodations","Adjust expectations and timing","Offer multiple ways to show understanding"]}','{"vocabulary":["couleur","forme","créer","dessiner","beau"],"visualSupports":["Relevant vocabulary cards and visual aids for lesson content","Studio procedure poster, material location chart, French request phrases, technique reminder cards available","Relevant vocabulary cards and visual aids for lesson content"],"movementBreaks":["Natural movement opportunities during activity","Independent movement to access materials","Natural movement during creative process","Natural movement opportunities during activity"]}',NULL,NULL,NULL,NULL,'{"questions":["Les élèves ont-ils atteint les objectifs?","Quelles adaptations étaient nécessaires?","Que ferais-je différemment la prochaine fois?"]}',NULL,'',4,15,'extension',1);
INSERT INTO ETFOLessonPlan VALUES('cmf43u3th007rvj9tauiatcaf',23,'Collaboration artistique','cmf43u3t5006vvj9tb8txx7h5',1758726000000,45,'Collaboration warm-up: Partner mirror drawing - one student draws while partner mirrors movements in air. Practice sharing materials and space. Introduce collaboration phrases: ''On peut partager?'' (Can we share?) ''Bonne idée!'' (Good idea!)','Collaborative Art Creation: Partners or small groups plan and create together using all learned techniques. Practice collaboration vocabulary: ''Qu''est-ce que tu penses de...?'', ''On peut essayer...'', ''J''aime ton idée!'' Create large collaborative piece where each student contributes their artistic strengths. Document collaboration process with photos if possible.','Collaboration Celebration. Groups present their collaborative work, explaining how they worked together: ''Nous avons collaboré en...'' (We collaborated by...) Others appreciate: ''Votre collaboration est belle!'' (Your collaboration is beautiful!)','Transformer le concept de collaboration artistique; Créer les techniques artistiques appropriées; Développer le sens esthétique par l''expression créative','["Art objects for demonstration","Visual routine chart","Basic art supplies (crayons, paper, glue)","Large paper for collaborative work (poster size or mural paper)","Shared art supplies organized in central stations","Mural paper or connected sheets for class project","Organization containers for sharing materials efficiently","Collaboration phrase cards","Planning sheets for group projects","Art objects for demonstration","Visual routine chart","Basic art supplies (crayons, paper, glue)"]',NULL,'Collaboration artistique','Collaboration warm-up: Partner mirror drawing - one student draws while partner mirrors movements in air. Practice sharing materials and space. Introduce collaboration phrases: ''On peut partager?'' (Can we share?) ''Bonne idée!'' (Good idea!)','Collaborative Art Creation: Partners or small groups plan and create together using all learned techniques. Practice collaboration vocabulary: ''Qu''est-ce que tu penses de...?'', ''On peut essayer...'', ''J''aime ton idée!'' Create large collaborative piece where each student contributes their artistic strengths. Document collaboration process with photos if possible.','Collaboration Celebration. Groups present their collaborative work, explaining how they worked together: ''Nous avons collaboré en...'' (We collaborated by...) Others appreciate: ''Votre collaboration est belle!'' (Your collaboration is beautiful!)','Transformer le concept de collaboration artistique; Créer les techniques artistiques appropriées; Développer le sens esthétique par l''expression créative',NULL,NULL,NULL,'formative','{"observable":["L''élève explore les matériaux artistiques avec curiosité","L''élève explique ses choix artistiques en français simple","L''élève respecte les matériaux et l''espace de travail","L''élève apprécie les créations artistiques des autres"],"checkpoints":["Utilise les techniques artistiques démontrées","Exprime ses idées par l''art visuel","Utilise le vocabulaire artistique approprié","Montre fierté dans ses créations artistiques"]}',1,'Plan détaillé avec supports visuels',1756911653334,1757594653858,1,'fr','Arts visuels','{"pourDifficultés":["Provide visual examples and demonstrations","Use simple gestures and basic vocabulary","Allow non-verbal responses initially","Partner with supportive peer"],"pourAvancés":["Encourage detailed French descriptions","Challenge with complex art concepts","Lead activities and help others","Explore creative extensions"],"pourLangue":["Provide visual vocabulary supports","Allow L1 support when needed","Use gestures and pointing","Focus on concrete, visible concepts"],"pourPEI":["Adapt materials and tools as needed","Provide sensory accommodations","Adjust expectations and timing","Offer multiple ways to show understanding"]}','{"vocabulary":["couleur","forme","créer","dessiner","beau"],"visualSupports":["Relevant vocabulary cards and visual aids for lesson content","Collaboration vocabulary poster, sharing procedures chart, group work behavior expectations, project planning template","Relevant vocabulary cards and visual aids for lesson content"],"movementBreaks":["Natural movement opportunities during activity","Moving between shared material stations","Collaborative work requiring physical coordination","Natural movement opportunities during activity"]}',NULL,NULL,NULL,NULL,'{"questions":["Les élèves ont-ils atteint les objectifs?","Quelles adaptations étaient nécessaires?","Que ferais-je différemment la prochaine fois?"]}',NULL,'',4,16,'extension',1);
INSERT INTO ETFOLessonPlan VALUES('cmf43u3ti007tvj9tkuc59vmz',23,'Art en grand','cmf43u3t5006vvj9tb8txx7h5',1758812400000,45,'Scale exploration: Compare small and large versions of same artwork. Discuss challenges and opportunities of working big: ''En grand, je peux...'' (When working big, I can...) Practice big gestures and movements for large-scale art.','Big Art Challenge: Students work on large-scale projects using bigger tools and movements. Practice vocabulary for size: ''grand'', ''petit'', ''plus grand''. Explore how working big changes their technique and expression. Compare small and large versions of same concept. Use whole body movements while creating: ''Mon bras fait de grands mouvements!''','Scale Reflection. Students compare their large-scale work experience with smaller projects: ''Travailler en grand était...'' (Working big was...) ''J''ai appris que...'' (I learned that...) Discuss challenges and successes.','Représenter le concept de art en; Créer les techniques artistiques appropriées; Développer l''appréciation artistique par l''expression créative','["Art objects for demonstration","Visual routine chart","Basic art supplies (crayons, paper, glue)","Large format paper (poster size minimum, bigger if available)","Big brushes and tools (house painting brushes work well)","Floor space or large table areas for working","Small paper for planning sketches and comparison","Protective covering for work surface","Size comparison vocabulary cards","Art objects for demonstration","Visual routine chart","Basic art supplies (crayons, paper, glue)"]',NULL,'Art en grand','Scale exploration: Compare small and large versions of same artwork. Discuss challenges and opportunities of working big: ''En grand, je peux...'' (When working big, I can...) Practice big gestures and movements for large-scale art.','Big Art Challenge: Students work on large-scale projects using bigger tools and movements. Practice vocabulary for size: ''grand'', ''petit'', ''plus grand''. Explore how working big changes their technique and expression. Compare small and large versions of same concept. Use whole body movements while creating: ''Mon bras fait de grands mouvements!''','Scale Reflection. Students compare their large-scale work experience with smaller projects: ''Travailler en grand était...'' (Working big was...) ''J''ai appris que...'' (I learned that...) Discuss challenges and successes.','Représenter le concept de art en; Créer les techniques artistiques appropriées; Développer l''appréciation artistique par l''expression créative',NULL,NULL,NULL,'formative','{"observable":["L''élève explore les matériaux artistiques avec curiosité","L''élève explique ses choix artistiques en français simple","L''élève respecte les matériaux et l''espace de travail","L''élève apprécie les créations artistiques des autres"],"checkpoints":["Utilise les techniques artistiques démontrées","Exprime ses idées par l''art visuel","Utilise le vocabulaire artistique approprié","Montre fierté dans ses créations artistiques"]}',1,'Plan détaillé avec supports visuels',1756911653335,1757594653859,1,'fr','Arts visuels','{"pourDifficultés":["Provide visual examples and demonstrations","Use simple gestures and basic vocabulary","Allow non-verbal responses initially","Partner with supportive peer"],"pourAvancés":["Encourage detailed French descriptions","Challenge with complex art concepts","Lead activities and help others","Explore creative extensions"],"pourLangue":["Provide visual vocabulary supports","Allow L1 support when needed","Use gestures and pointing","Focus on concrete, visible concepts"],"pourPEI":["Adapt materials and tools as needed","Provide sensory accommodations","Adjust expectations and timing","Offer multiple ways to show understanding"]}','{"vocabulary":["couleur","forme","créer","dessiner","beau"],"visualSupports":["Relevant vocabulary cards and visual aids for lesson content","Scale comparison chart, large movement demonstration posters, size vocabulary cards, safety procedures for big art","Relevant vocabulary cards and visual aids for lesson content"],"movementBreaks":["Natural movement opportunities during activity","Large body movements required for big art creation","Moving around large work surfaces","Natural movement opportunities during activity"]}',NULL,NULL,NULL,NULL,'{"questions":["Les élèves ont-ils atteint les objectifs?","Quelles adaptations étaient nécessaires?","Que ferais-je différemment la prochaine fois?"]}',NULL,'',4,17,'extension',1);
INSERT INTO ETFOLessonPlan VALUES('cmf43u3tk007xvj9tzcjz8hm6',23,'Art et nature','cmf43u3t5006vvj9tb8txx7h5',4102416000000,45,'Nature art exploration: Show examples of natural materials used in art (leaf printing, stone painting, twig sculptures). Discuss respectful collection: ''Nous prenons seulement ce que nous avons besoin'' (We take only what we need). Practice nature vocabulary review.','Nature Art Exploration: Use natural materials to create eco-friendly art. Try leaf printing, rock painting, stick sculptures, or flower pressing. Practice nature vocabulary: ''feuille'', ''pierre'', ''fleur'', ''branche''. Discuss how nature inspires artists: ''La nature me donne des idées pour...'' Create temporary outdoor art that respects environment.','Nature Art Share. Students present their nature art explaining their inspiration: ''La nature m''inspire parce que...'' (Nature inspires me because...) ''J''ai utilisé...'' (I used...) Connect to environmental appreciation.','Présenter le concept de art et; Créer les techniques artistiques appropriées; Développer l''appréciation artistique par l''expression créative','["Art objects for demonstration","Visual routine chart","Basic art supplies (crayons, paper, glue)","Natural materials (leaves, rocks, sticks, flowers - collected respectfully)","Washable paint for printing on natural materials","Paper for rubbings and nature pressing","Art supplies for nature-inspired drawing and documentation","Collection bags for respectful gathering","Nature vocabulary cards","Art objects for demonstration","Visual routine chart","Basic art supplies (crayons, paper, glue)"]',NULL,'Art et nature','Nature art exploration: Show examples of natural materials used in art (leaf printing, stone painting, twig sculptures). Discuss respectful collection: ''Nous prenons seulement ce que nous avons besoin'' (We take only what we need). Practice nature vocabulary review.','Nature Art Exploration: Use natural materials to create eco-friendly art. Try leaf printing, rock painting, stick sculptures, or flower pressing. Practice nature vocabulary: ''feuille'', ''pierre'', ''fleur'', ''branche''. Discuss how nature inspires artists: ''La nature me donne des idées pour...'' Create temporary outdoor art that respects environment.','Nature Art Share. Students present their nature art explaining their inspiration: ''La nature m''inspire parce que...'' (Nature inspires me because...) ''J''ai utilisé...'' (I used...) Connect to environmental appreciation.','Présenter le concept de art et; Créer les techniques artistiques appropriées; Développer l''appréciation artistique par l''expression créative',NULL,NULL,NULL,'formative','{"observable":["L''élève explore les matériaux artistiques avec curiosité","L''élève explique ses choix artistiques en français simple","L''élève respecte les matériaux et l''espace de travail","L''élève apprécie les créations artistiques des autres"],"checkpoints":["Utilise les techniques artistiques démontrées","Exprime ses idées par l''art visuel","Utilise le vocabulaire artistique approprié","Montre fierté dans ses créations artistiques"]}',1,'Plan détaillé avec supports visuels',1756911653336,1757594653860,1,'fr','Arts visuels','{"pourDifficultés":["Provide visual examples and demonstrations","Use simple gestures and basic vocabulary","Allow non-verbal responses initially","Partner with supportive peer"],"pourAvancés":["Encourage detailed French descriptions","Challenge with complex art concepts","Lead activities and help others","Explore creative extensions"],"pourLangue":["Provide visual vocabulary supports","Allow L1 support when needed","Use gestures and pointing","Focus on concrete, visible concepts"],"pourPEI":["Adapt materials and tools as needed","Provide sensory accommodations","Adjust expectations and timing","Offer multiple ways to show understanding"]}','{"vocabulary":["couleur","forme","créer","dessiner","beau"],"visualSupports":["Relevant vocabulary cards and visual aids for lesson content","Nature vocabulary poster, eco-art techniques guide, respectful collection guidelines, inspiration examples from nature artists","Relevant vocabulary cards and visual aids for lesson content"],"movementBreaks":["Natural movement opportunities during activity","Outdoor exploration and material collection","Working with natural materials in various positions","Natural movement opportunities during activity"]}',NULL,NULL,NULL,NULL,'{"questions":["Les élèves ont-ils atteint les objectifs?","Quelles adaptations étaient nécessaires?","Que ferais-je différemment la prochaine fois?"]}',NULL,'',4,18,'extension',0);
INSERT INTO ETFOLessonPlan VALUES('cmf43u3tl007zvj9t4g0dg3sa',23,'Célébration artistique','cmf43u3t5006vvj9tb8txx7h5',1758898800000,45,'Growth reflection: Students look through portfolio of work from all lessons. Identify improvements and new skills: ''Au début, je...'' (At the beginning, I...) ''Maintenant, je peux...'' (Now I can...) Celebrate progress with encouraging gestures.','Artistic Journey Celebration: Students create final celebration piece showing their artistic growth. Choose favorite technique learned and create ''masterpiece'' while reflecting: ''Au début j''étais..., maintenant je suis...'' Prepare portfolio presentations for families. Practice sharing artistic vocabulary and growth stories in French.','Artist Commitment Circle. Students share one artistic goal for the future: ''Je veux continuer à...'' (I want to continue to...) ''L''art va toujours être important parce que...'' (Art will always be important because...) Group celebration of artistic growth.','Intégrer le concept de célébration artistique; Créer les techniques artistiques appropriées; Développer l''appréciation artistique par la célébration collective','["Art objects for demonstration","Visual routine chart","Basic art supplies (crayons, paper, glue)","Portfolio folders organized with chronological artwork","Full art supplies access for celebration piece creation","Presentation space setup with display areas","Family invitation preparations if doing presentation","Celebration certificates or recognition items","Reflection worksheets for growth documentation","Art objects for demonstration","Visual routine chart","Basic art supplies (crayons, paper, glue)"]',NULL,'Célébration artistique','Growth reflection: Students look through portfolio of work from all lessons. Identify improvements and new skills: ''Au début, je...'' (At the beginning, I...) ''Maintenant, je peux...'' (Now I can...) Celebrate progress with encouraging gestures.','Artistic Journey Celebration: Students create final celebration piece showing their artistic growth. Choose favorite technique learned and create ''masterpiece'' while reflecting: ''Au début j''étais..., maintenant je suis...'' Prepare portfolio presentations for families. Practice sharing artistic vocabulary and growth stories in French.','Artist Commitment Circle. Students share one artistic goal for the future: ''Je veux continuer à...'' (I want to continue to...) ''L''art va toujours être important parce que...'' (Art will always be important because...) Group celebration of artistic growth.','Intégrer le concept de célébration artistique; Créer les techniques artistiques appropriées; Développer l''appréciation artistique par la célébration collective',NULL,NULL,NULL,'formative','{"observable":["L''élève explore les matériaux artistiques avec curiosité","L''élève explique ses choix artistiques en français simple","L''élève respecte les matériaux et l''espace de travail","L''élève apprécie les créations artistiques des autres"],"checkpoints":["Utilise les techniques artistiques démontrées","Exprime ses idées par l''art visuel","Utilise le vocabulaire artistique approprié","Montre fierté dans ses créations artistiques"]}',1,'Plan détaillé avec supports visuels',1756911653337,1757594653861,1,'fr','Arts visuels','{"pourDifficultés":["Provide visual examples and demonstrations","Use simple gestures and basic vocabulary","Allow non-verbal responses initially","Partner with supportive peer"],"pourAvancés":["Encourage detailed French descriptions","Challenge with complex art concepts","Lead activities and help others","Explore creative extensions"],"pourLangue":["Provide visual vocabulary supports","Allow L1 support when needed","Use gestures and pointing","Focus on concrete, visible concepts"],"pourPEI":["Adapt materials and tools as needed","Provide sensory accommodations","Adjust expectations and timing","Offer multiple ways to show understanding"]}','{"vocabulary":["couleur","forme","créer","dessiner","beau"],"visualSupports":["Relevant vocabulary cards and visual aids for lesson content","Growth vocabulary poster, presentation tips chart, portfolio organization guide, celebration routine visual schedule","Relevant vocabulary cards and visual aids for lesson content"],"movementBreaks":["Natural movement opportunities during activity","Setting up celebration presentation space","Ceremonial movement during celebration activities","Natural movement opportunities during activity"]}',NULL,NULL,NULL,NULL,'{"questions":["Les élèves ont-ils atteint les objectifs?","Quelles adaptations étaient nécessaires?","Que ferais-je différemment la prochaine fois?"]}',NULL,'',4,19,'core',1);
INSERT INTO ETFOLessonPlan VALUES('cmf43u3tn0083vj9tq5ngzi30',23,'Outils d''artiste professionnel','cmf43u3tm0081vj9t236523o9',1774278000000,45,'Mystery tool exploration: Show professional art tools (palette knives, brayers, fine brushes, sculpting tools) in covered containers. Students guess what each tool does. Introduce vocabulary: OUTIL (show tool gesture), PROFESSIONNEL (formal, careful handling), SÉCURITÉ (safe handling demonstration).','Exploration guidée des outils professionnels. En stations rotatives de 4-5 minutes, les élèves explorent chaque outil sous supervision. Démontrer la technique correcte, laisser pratiquer sur papier d''essai. Encourager: ''Cet outil professionnel fait...'', ''Je dois être prudent avec...''. Documenter les découvertes.','Professional Artist Role-Play. Students choose their favorite professional tool and demonstrate proper use to ''art students'' (classmates). Practice vocabulary: ''Cet outil professionnel fait...'' Emphasize safety and skill.','Découvrir le concept de outils d''artiste; Créer les techniques artistiques appropriées; Développer la créativité par l''expression créative','["Outils d''art professionnels dans des contenants couverts","Cartes de vocabulaire avec gestes","Affiches de sécurité colorées","Exemples d''outils utilisés par différents professionnels","Professional art tools (palette knives, brayers, detail brushes, sculpting tools)","Practice materials for each tool","Safety guidelines poster","Tool storage organization","Outils utilisés pendant la leçon","Lingettes de nettoyage","Bacs de rangement étiquetés"]',NULL,'Outils d''artiste professionnel','Mystery tool exploration: Show professional art tools (palette knives, brayers, fine brushes, sculpting tools) in covered containers. Students guess what each tool does. Introduce vocabulary: OUTIL (show tool gesture), PROFESSIONNEL (formal, careful handling), SÉCURITÉ (safe handling demonstration).','Exploration guidée des outils professionnels. En stations rotatives de 4-5 minutes, les élèves explorent chaque outil sous supervision. Démontrer la technique correcte, laisser pratiquer sur papier d''essai. Encourager: ''Cet outil professionnel fait...'', ''Je dois être prudent avec...''. Documenter les découvertes.','Professional Artist Role-Play. Students choose their favorite professional tool and demonstrate proper use to ''art students'' (classmates). Practice vocabulary: ''Cet outil professionnel fait...'' Emphasize safety and skill.','Découvrir le concept de outils d''artiste; Créer les techniques artistiques appropriées; Développer la créativité par l''expression créative',NULL,NULL,NULL,'formative','{"observable":["L''élève identifie et nomme différents outils d''artiste (pinceaux, crayons, pastels)","L''élève manipule les outils avec une prise appropriée pour son âge","L''élève explore différentes techniques avec chaque outil","L''élève compare les effets créés par différents outils","L''élève exprime ses préférences d''outils en français"],"checkpoints":["Utilise correctement au moins 3 outils d''artiste différents","Explique en français l''effet créé par chaque outil testé"]}',1,'Plan détaillé avec supports visuels',1756911653339,1757587621443,1,'fr','Arts visuels','{"pourDifficultés":["Observer et nommer les outils sans les manipuler","Se concentrer sur 2-3 outils seulement","Jumeler avec un partenaire pour l''aide","Utiliser des outils plus gros et plus sécuritaires"],"pourAvancés":["Explorer des techniques combinées avec plusieurs outils","Devenir aide-enseignant pour démontrer aux autres","Rechercher des artistes qui utilisent ces outils","Créer un mini-guide d''utilisation illustré"],"pourLangue":["Cartes visuelles avec noms d''outils en images","Permettre l''usage de leur langue première pour clarifier","Gestes et démonstrations plutôt que explications verbales","Jumeler avec un élève bilingue si possible"],"pourPEI":["Adapter les outils selon les capacités motrices","Réduire le nombre d''outils à explorer","Fournir un support physique au besoin","Utiliser des outils modifiés ou adaptés"]}','{"vocabulary":["outil","professionnel","sécurité"],"visualSupports":["Photos d''artistes professionnels utilisant des outils, cartes de vocabulaire avec gestes, affiche de sécurité avec symboles colorés","Démonstrations étape par étape, affiches de sécurité, photos d''artistes au travail","Guide visuel pour le rangement des outils, cartes de rappel de sécurité"],"movementBreaks":["Gestes pour chaque outil (palette knife, brayer, etc.)","Mouvements de sécurité (mains propres, rangement soigneux)","Rotation entre stations d''outils","Pauses pour nettoyer et organiser les outils","Marche pour montrer son outil préféré","Geste de salut aux outils professionnels"]}',NULL,NULL,NULL,NULL,'{"questions":["Les élèves ont-ils atteint les objectifs?","Quelles adaptations étaient nécessaires?","Que ferais-je différemment la prochaine fois?"]}',NULL,'',4,1,'core',1);
INSERT INTO ETFOLessonPlan VALUES('cmf43u3tn0085vj9tob6pvvug',23,'Mélange des médiums','cmf43u3tm0081vj9t236523o9',1774364400000,45,'Show examples of mixed media artworks. Identify different materials used together: paint + collage, crayon + watercolor, etc. Introduce vocabulary: MÉLANGER (mixing gesture), MÉDIUM (hold up different materials), COMBINAISON (bringing hands together).','Création d''œuvres mixtes guidées. Les élèves planifient puis créent des œuvres combinant 2-3 matériaux différents. Démontrer des techniques: crayon + aquarelle, collage + peinture. Encourager: ''Je mélange... avec...'', ''Ma combinaison utilise...''. Circuler pour guider les choix.','Mixed Media Gallery Walk. Display all mixed media works. Students identify different mediums used in each artwork. Practice vocabulary: ''Je vois une combinaison de...'' Discuss which combinations were most effective.','Observer le concept de mélange des; Créer les techniques artistiques appropriées; Développer la créativité par l''expression créative','["Exemples d''œuvres d''art mixte","Cartes de vocabulaire avec gestes","Différents matériaux d''art pour démonstration","Photos avant/après de créations mixtes","Variety of art materials (paints, crayons, markers, collage materials, pastels)","Planning sheets","Mixed media paper","Demonstration examples","Espace d''affichage pour les œuvres","Supports pour exposition","Petites étiquettes pour identifier les techniques"]',NULL,'Mélange des médiums','Show examples of mixed media artworks. Identify different materials used together: paint + collage, crayon + watercolor, etc. Introduce vocabulary: MÉLANGER (mixing gesture), MÉDIUM (hold up different materials), COMBINAISON (bringing hands together).','Création d''œuvres mixtes guidées. Les élèves planifient puis créent des œuvres combinant 2-3 matériaux différents. Démontrer des techniques: crayon + aquarelle, collage + peinture. Encourager: ''Je mélange... avec...'', ''Ma combinaison utilise...''. Circuler pour guider les choix.','Mixed Media Gallery Walk. Display all mixed media works. Students identify different mediums used in each artwork. Practice vocabulary: ''Je vois une combinaison de...'' Discuss which combinations were most effective.','Observer le concept de mélange des; Créer les techniques artistiques appropriées; Développer la créativité par l''expression créative',NULL,NULL,NULL,'formative','{"observable":["L''élève mélange intentionnellement deux médiums différents","L''élève observe et décrit les changements créés par le mélange","L''élève expérimente différentes proportions de mélange","L''élève utilise le vocabulaire artistique approprié (couleur, texture, effet)","L''élève crée des effets visuels intéressants par le mélange"],"checkpoints":["Réalise au moins 3 mélanges de médiums différents avec succès","Explique en français les résultats de ses expérimentations"]}',1,'Plan détaillé avec supports visuels',1756911653340,1757587621444,1,'fr','Arts visuels','{"pourDifficultés":["Pré-sélectionner 2 matériaux compatibles","Fournir des exemples à reproduire","Jumeler avec un partenaire expérimenté","Utiliser des matériaux plus faciles à manipuler"],"pourAvancés":["Expérimenter avec plus de 3 matériaux","Créer des effets spéciaux avec les mélanges","Aider à enseigner les techniques aux autres","Créer une série d''œuvres avec différentes combinaisons"],"pourLangue":["Cartes visuelles montrant les combinaisons","Démonstrations plutôt qu''explications verbales","Permettre l''expression en langue première","Support d''un pair bilingue"],"pourPEI":["Adapter les outils selon les capacités motrices","Réduire le nombre de matériaux","Fournir un support physique","Permettre des techniques alternatives"]}','{"vocabulary":["mélanger","médium","combinaison"],"visualSupports":["Exemples d''œuvres mixtes, cartes de vocabulaire avec gestes, tableau de combinaisons possibles","Tableau des combinaisons possibles, exemples étape par étape, guide de planification illustré","Exemple de galerie d''art, cartes de vocabulaire pour décrire les œuvres"],"movementBreaks":["Gestes de mélange avec les mains","Mouvements pour chaque matériau (peinture, colle, etc.)","Rotation entre stations de matériaux","Pauses pour observer le travail des autres","Marche lente et silencieuse entre les œuvres","Pause pour admirer et réfléchir"]}',NULL,NULL,NULL,NULL,'{"questions":["Les élèves ont-ils atteint les objectifs?","Quelles adaptations étaient nécessaires?","Que ferais-je différemment la prochaine fois?"]}',NULL,'',4,2,'core',1);
INSERT INTO ETFOLessonPlan VALUES('cmf43u3to0087vj9t358pupf2',23,'Techniques de peinture avancées','cmf43u3tm0081vj9t236523o9',1774450800000,45,'Compare basic brush painting to advanced techniques using demonstrations. Show sponge painting, stencil work, palette knife techniques. Introduce vocabulary: TECHNIQUE (skillful gesture), ÉPONGE (dabbing motion), POCHOIR (stencil demonstration).','Exploration de stations de techniques avancées. Rotation de 8-9 minutes entre stations: éponge, pochoir, couteau. Démontrer chaque technique, laisser pratiquer. Encourager: ''Cette technique crée...'', ''J''utilise l''éponge pour...''. Documenter les effets préférés.','Technique Showcase. Students demonstrate their best advanced technique to classmates. Explain process: ''Ma technique avancée utilise...'' Compare effects achieved with different techniques.','Expérimenter le concept de techniques de; Créer les techniques artistiques appropriées; Développer la créativité par l''expression créative','["Pinceaux ordinaires et outils spéciaux","Éponges de différentes textures","Pochoirs et couteaux à palette","Cartes de vocabulaire avec démonstrations","Various sponges for painting","Stencils (commercial and handmade)","Palette knives","Paints suitable for advanced techniques","Practice papers","Exemples créés pendant la leçon","Outils de démonstration","Support d''affichage pour les techniques"]',NULL,'Techniques de peinture avancées','Compare basic brush painting to advanced techniques using demonstrations. Show sponge painting, stencil work, palette knife techniques. Introduce vocabulary: TECHNIQUE (skillful gesture), ÉPONGE (dabbing motion), POCHOIR (stencil demonstration).','Exploration de stations de techniques avancées. Rotation de 8-9 minutes entre stations: éponge, pochoir, couteau. Démontrer chaque technique, laisser pratiquer. Encourager: ''Cette technique crée...'', ''J''utilise l''éponge pour...''. Documenter les effets préférés.','Technique Showcase. Students demonstrate their best advanced technique to classmates. Explain process: ''Ma technique avancée utilise...'' Compare effects achieved with different techniques.','Expérimenter le concept de techniques de; Créer les techniques artistiques appropriées; Développer la créativité par l''expression créative',NULL,NULL,NULL,'formative','{"observable":["L''élève applique différentes techniques de peinture (tamponnage, grattage, projection)","L''élève contrôle la pression du pinceau pour créer différents effets","L''élève superpose les couleurs de manière intentionnelle","L''élève adapte sa technique selon l''effet désiré","L''élève utilise son corps et ses mouvements pour créer des effets artistiques"],"checkpoints":["Maîtrise au moins 2 techniques de peinture avancées","Crée une œuvre démontrant la maîtrise technique et la créativité"]}',1,'Plan détaillé avec supports visuels',1756911653341,1757587621445,1,'fr','Arts visuels','{"pourDifficultés":["Se concentrer sur une seule technique par leçon","Utiliser des outils adaptés (plus gros, plus faciles)","Fournir plus de guidage physique","Permettre des techniques simplifiées"],"pourAvancés":["Combiner plusieurs techniques en une œuvre","Expérimenter avec des variations personnelles","Enseigner les techniques à leurs pairs","Créer leurs propres pochoirs"],"pourLangue":["Démonstrations visuelles sans langage complexe","Cartes de vocabulaire avec images de techniques","Jumelage avec des pairs bilingues","Focus sur l''action plutôt que l''explication"],"pourPEI":["Adapter les outils selon les capacités","Réduire le nombre de techniques à essayer","Fournir un support physique","Modifier les attentes selon les objectifs"]}','{"vocabulary":["technique","éponge","pochoir"],"visualSupports":["Comparaisons avant/après, étapes des techniques illustrées, exemples d''effets obtenus","Guides visuels pour chaque station, exemples de techniques réussies, aide-mémoire des étapes","Galerie des techniques, étiquettes pour identifier chaque méthode"],"movementBreaks":["Gestes pour chaque technique (tamponner, gratter, rouler)","Mouvements de préparation des outils","Rotation active entre les stations","Nettoyage et préparation entre techniques","Mouvements de démonstration pour chaque technique","Applaudissements pour chaque présentation"]}',NULL,NULL,NULL,NULL,'{"questions":["Les élèves ont-ils atteint les objectifs?","Quelles adaptations étaient nécessaires?","Que ferais-je différemment la prochaine fois?"]}',NULL,'',4,3,'core',1);
INSERT INTO ETFOLessonPlan VALUES('cmf43u3tp0089vj9tia7ebuv6',23,'Sculpture et modelage','cmf43u3tm0081vj9t236523o9',1774537200000,45,'Explore 3D vs 2D concepts using simple objects and pictures. Handle sculptures vs looking at paintings. Introduce vocabulary: SCULPTURE (3D gesture with hands), MODELAGE (shaping clay motion), FORME (outline 3D shapes in air).','Exploration libre de sculpture et modelage. Stations avec différents matériaux: argile, pâte, matériaux souples. Encourager l''expérimentation: ''Ma sculpture a la forme de...'', ''Je modele pour créer...''. Documenter les découvertes sur les formes 3D.','Sculpture Gallery. Display 3D works so they can be viewed from all angles. Students walk around sculptures, describing what they see from different viewpoints. Practice 3D vocabulary.','Transformer le concept de sculpture et; Créer les techniques artistiques appropriées; Développer la créativité par l''expression créative','["Objets 3D et images 2D pour comparaison","Petites sculptures à manipuler","Cartes de vocabulaire avec gestes","Matériaux de modelage pour démonstration","Various clay types","Sculpting tools from Lesson 1","Found objects for assemblage","Soft carving materials (soap, foam)","Workspace protection","Surfaces d''exposition pour sculptures","Plateaux tournants si disponibles","Cartes pour commentaires sur les œuvres"]',NULL,'Sculpture et modelage','Explore 3D vs 2D concepts using simple objects and pictures. Handle sculptures vs looking at paintings. Introduce vocabulary: SCULPTURE (3D gesture with hands), MODELAGE (shaping clay motion), FORME (outline 3D shapes in air).','Exploration libre de sculpture et modelage. Stations avec différents matériaux: argile, pâte, matériaux souples. Encourager l''expérimentation: ''Ma sculpture a la forme de...'', ''Je modele pour créer...''. Documenter les découvertes sur les formes 3D.','Sculpture Gallery. Display 3D works so they can be viewed from all angles. Students walk around sculptures, describing what they see from different viewpoints. Practice 3D vocabulary.','Transformer le concept de sculpture et; Créer les techniques artistiques appropriées; Développer la créativité par l''expression créative',NULL,NULL,NULL,'formative','{"observable":["L''élève manipule l''argile ou la pâte à modeler avec contrôle","L''élève utilise des outils de modelage appropriés","L''élève crée des formes tridimensionnelles reconnaissables","L''élève ajoute des détails et des textures à ses sculptures","L''élève explique son processus créatif en français"],"checkpoints":["Crée une sculpture stable avec des détails ajoutés","Démontre des techniques de modelage variées (rouler, pincer, étirer)"]}',1,'Plan détaillé avec supports visuels',1756911653341,1757587621445,1,'fr','Arts visuels','{"pourDifficultés":["Utiliser des matériaux plus mous et faciles à manipuler","Créer des formes simples avec guidance","Travailler en équipe avec un partenaire","Se concentrer sur l''exploration tactile"],"pourAvancés":["Créer des sculptures détaillées et complexes","Combiner différents matériaux et techniques","Planifier des sculptures avec des croquis","Aider à enseigner les techniques aux autres"],"pourLangue":["Focus sur l''exploration tactile et visuelle","Cartes visuelles pour vocabulaire 3D","Démonstrations sans explications verbales complexes","Jumelage avec pairs bilingues"],"pourPEI":["Adapter les outils selon les capacités motrices","Fournir support physique au besoin","Matériaux adaptés aux sensibilités tactiles","Objectifs modifiés selon les besoins"]}','{"vocabulary":["sculpture","modelage","forme"],"visualSupports":["Comparaisons 2D/3D, gestes pour chaque mot de vocabulaire, exemples de sculptures célèbres","Exemples de techniques de modelage, guide des formes de base, photos de sculptures d''élèves","Exemple de galerie de sculptures, cartes de vocabulaire pour décrire les formes 3D"],"movementBreaks":["Gestes pour sculpter et modeler","Mouvements pour décrire des formes 3D dans l''espace","Rotation entre stations de matériaux","Pauses pour observer les créations sous tous les angles","Marche autour des sculptures pour voir tous les angles","Gestes pour décrire les formes observées"]}',NULL,NULL,NULL,NULL,'{"questions":["Les élèves ont-ils atteint les objectifs?","Quelles adaptations étaient nécessaires?","Que ferais-je différemment la prochaine fois?"]}',NULL,'',4,4,'core',1);
INSERT INTO ETFOLessonPlan VALUES('cmf43u3tq008bvj9tr5o5z5ny',23,'Gravure et impression','cmf43u3tm0081vj9t236523o9',1774623600000,45,'Demonstrate concept of making multiple copies: stamp a simple design multiple times. Compare to unique artworks vs prints. Introduce vocabulary: GRAVURE (carving motion), IMPRESSION (printing press motion), MULTIPLES (counting copies).','Création de matrices d''impression simples. Utiliser mousse, carton, objets texturés pour créer des matrices. Démontrer l''application d''encre et le processus d''impression. Encourager: ''Ma gravure montre...'', ''Je peux faire plusieurs impressions de...''. Créer une série de copies.','Print Exhibition and Trading. Display print series. Students can trade prints with each other since multiple copies exist. Discuss how printmaking allows sharing artwork. Practice printmaking vocabulary.','Représenter le concept de gravure et; Créer les techniques artistiques appropriées; Développer l''expression artistique par l''expression créative','["Tampons et encreurs pour démonstration","Exemples d''œuvres uniques vs imprimées","Cartes de vocabulaire avec gestes","Matériaux de gravure simples","Printmaking materials (foam plates, cardboard, cutting tools)","Printing ink or paint","Printing paper","Brayers for ink application","Printing press or spoons","Espace d''exposition pour séries d''impressions","Système d''échange organisé","Contenants pour ranger les œuvres"]',NULL,'Gravure et impression','Demonstrate concept of making multiple copies: stamp a simple design multiple times. Compare to unique artworks vs prints. Introduce vocabulary: GRAVURE (carving motion), IMPRESSION (printing press motion), MULTIPLES (counting copies).','Création de matrices d''impression simples. Utiliser mousse, carton, objets texturés pour créer des matrices. Démontrer l''application d''encre et le processus d''impression. Encourager: ''Ma gravure montre...'', ''Je peux faire plusieurs impressions de...''. Créer une série de copies.','Print Exhibition and Trading. Display print series. Students can trade prints with each other since multiple copies exist. Discuss how printmaking allows sharing artwork. Practice printmaking vocabulary.','Représenter le concept de gravure et; Créer les techniques artistiques appropriées; Développer l''expression artistique par l''expression créative',NULL,NULL,NULL,'formative','{"observable":["L''élève grave des motifs simples sur différentes surfaces","L''élève applique la peinture ou l''encre uniformément","L''élève effectue le processus d''impression avec assistance minimale","L''élève compare l''original et l''impression obtenue","L''élève répète le processus pour créer plusieurs copies"],"checkpoints":["Produit une impression claire et reconnaissable","Comprend le principe de base de la gravure et impression"]}',1,'Plan détaillé avec supports visuels',1756911653342,1757587621446,1,'fr','Arts visuels','{"pourDifficultés":["Utiliser des matrices pré-faites ou simplifiées","Se concentrer sur le processus d''impression seulement","Travailler avec assistance pour l''encrage","Utiliser des outils plus gros et plus faciles"],"pourAvancés":["Créer des matrices complexes avec plusieurs couleurs","Expérimenter avec différents papiers et encres","Créer des séries thématiques d''impressions","Enseigner les techniques aux autres"],"pourLangue":["Focus sur les démonstrations visuelles","Cartes de vocabulaire avec images du processus","Jumelage avec pairs pour guidance","Permettre l''expression en langue première"],"pourPEI":["Adapter les outils selon les capacités motrices","Simplifier les étapes du processus","Fournir aide physique pour l''impression","Objectifs adaptés aux capacités individuelles"]}','{"vocabulary":["gravure","impression","multiples"],"visualSupports":["Comparaisons œuvre unique vs multiples, étapes de l''impression illustrées, gestes pour le vocabulaire","Étapes de l''impression illustrées, exemples de matrices et résultats, guide de sécurité pour outils","Exposition organisée par séries, étiquettes pour identifier les techniques utilisées"],"movementBreaks":["Gestes de gravure et d''impression","Comptage des multiples avec les doigts","Mouvements de pressage pour l''impression","Rotation entre stations d''encrage et d''impression","Marche autour de l''exposition","Gestes d''échange et de partage"]}',NULL,NULL,NULL,NULL,'{"questions":["Les élèves ont-ils atteint les objectifs?","Quelles adaptations étaient nécessaires?","Que ferais-je différemment la prochaine fois?"]}',NULL,'',4,5,'core',1);
INSERT INTO ETFOLessonPlan VALUES('cmf43u3tr008dvj9t2doqxzmg',23,'Collage sophistiqué','cmf43u3tm0081vj9t236523o9',1774882800000,45,'Compare simple collages to sophisticated examples. Identify layers, composition principles, intentional material choices. Introduce vocabulary: COLLAGE (layering gesture), COUCHE (layer-building motion), COMPOSITION (arranging gesture).','Création de collages sophistiqués. Planifier d''abord la composition sur croquis, puis construire par couches. Utiliser variété de textures, transparences, papiers spéciaux. Encourager: ''Ma première couche montre...'', ''Cette composition crée...''. Documenter les choix créatifs.','Collage Critique Session. Students present their sophisticated collages, explaining layering and compositional choices. Use advanced vocabulary: ''Ma composition utilise des couches pour...''','Créer le concept de collage sophistiqué; Créer les techniques artistiques appropriées; Développer l''expression artistique par l''expression créative','["Exemples de collages simples et sophistiqués","Matériaux de collage variés pour démonstration","Cartes de vocabulaire avec gestes","Transparences pour montrer les couches","Variety of sophisticated collage materials (textured papers, transparencies, fabrics)","Quality adhesives","Cutting tools","Large format papers","Planning sketches","Supports d''exposition pour collages","Guides de présentation","Cartes de vocabulaire pour critique constructive"]',NULL,'Collage sophistiqué','Compare simple collages to sophisticated examples. Identify layers, composition principles, intentional material choices. Introduce vocabulary: COLLAGE (layering gesture), COUCHE (layer-building motion), COMPOSITION (arranging gesture).','Création de collages sophistiqués. Planifier d''abord la composition sur croquis, puis construire par couches. Utiliser variété de textures, transparences, papiers spéciaux. Encourager: ''Ma première couche montre...'', ''Cette composition crée...''. Documenter les choix créatifs.','Collage Critique Session. Students present their sophisticated collages, explaining layering and compositional choices. Use advanced vocabulary: ''Ma composition utilise des couches pour...''','Créer le concept de collage sophistiqué; Créer les techniques artistiques appropriées; Développer l''expression artistique par l''expression créative',NULL,NULL,NULL,'formative','{"observable":["L''élève sélectionne des matériaux variés pour son collage","L''élève superpose les éléments de manière intentionnelle","L''élève utilise différentes techniques d''assemblage (coller, coudre, agrafer)","L''élève crée de la profondeur et de la texture dans son collage","L''élève intègre des éléments culturels acadiens dans son œuvre"],"checkpoints":["Réalise un collage avec au moins 5 matériaux différents","Démontre une composition réfléchie et équilibrée"]}',1,'Plan détaillé avec supports visuels',1756911653343,1757587621447,1,'fr','Arts visuels','{"pourDifficultés":["Utiliser des modèles de composition pré-planés","Limiter à 2-3 types de matériaux","Fournir de l''aide pour la planification","Travailler sur format plus petit"],"pourAvancés":["Créer des compositions multi-couches complexes","Expérimenter avec des techniques mixtes","Planifier des séries de collages liés","Mentorer d''autres élèves dans leurs techniques"],"pourLangue":["Focus sur l''exploration visuelle et tactile","Cartes de vocabulaire avec images de techniques","Démonstrations sans explications verbales complexes","Support de pairs bilingues"],"pourPEI":["Adapter les outils de découpage selon les besoins","Simplifier les étapes de planification","Matériaux adaptés aux sensibilités","Objectifs modifiés selon les capacités"]}','{"vocabulary":["collage","couche","composition"],"visualSupports":["Comparaisons de collages, démonstration des couches, exemples de compositions réussies","Guide de planification de composition, exemples de superposition, techniques de collage illustrées","Modèles de présentation, vocabulaire de critique artistique, exemples de feedback constructif"],"movementBreaks":["Gestes pour superposer les couches","Mouvements d''organisation et de composition","Pauses pour reculer et observer la composition","Changement entre différentes stations de matériaux","Mouvements pour présenter et pointer les éléments","Applaudissements pour chaque présentation"]}',NULL,NULL,NULL,NULL,'{"questions":["Les élèves ont-ils atteint les objectifs?","Quelles adaptations étaient nécessaires?","Que ferais-je différemment la prochaine fois?"]}',NULL,'',4,6,'core',1);
INSERT INTO ETFOLessonPlan VALUES('cmf43u3ts008fvj9tqgabtz6u',23,'Art textile','cmf43u3tm0081vj9t236523o9',1774969200000,45,'Explore different textiles: woven vs knitted vs sewn. Feel different fabric textures and structures. Introduce vocabulary: TEXTILE (fabric touching motion), TISSER (weaving motion with fingers), COUDRE (stitching motion).','Stations d''exploration textile. Rotation entre tissage simple, couture sur feutrine, manipulation de tissus. Démontrer chaque technique, laisser explorer. Encourager: ''Je tisse en passant...'', ''Mon textile a une texture...''. Créer de petites œuvres textiles.','Textile Arts Appreciation. Display textile creations and discuss how textile arts connect to clothing, decoration, and cultural traditions. Practice textile vocabulary in context.','Dessiner le concept de art textile; Créer les techniques artistiques appropriées; Développer l''expression artistique par l''expression créative','["Variété de textiles à toucher et examiner","Exemples de tissage, tricot, couture","Cartes de vocabulaire avec gestes","Loupes pour observer les structures","Simple weaving looms or cardboard frames","Yarn and fabric strips","Large, safe needles","Felt and burlap for stitching","Variety of fabrics for manipulation","Supports d''affichage pour œuvres textiles","Images de textiles traditionnels de différentes cultures","Vêtements ou objets décoratifs textiles"]',NULL,'Art textile','Explore different textiles: woven vs knitted vs sewn. Feel different fabric textures and structures. Introduce vocabulary: TEXTILE (fabric touching motion), TISSER (weaving motion with fingers), COUDRE (stitching motion).','Stations d''exploration textile. Rotation entre tissage simple, couture sur feutrine, manipulation de tissus. Démontrer chaque technique, laisser explorer. Encourager: ''Je tisse en passant...'', ''Mon textile a une texture...''. Créer de petites œuvres textiles.','Textile Arts Appreciation. Display textile creations and discuss how textile arts connect to clothing, decoration, and cultural traditions. Practice textile vocabulary in context.','Dessiner le concept de art textile; Créer les techniques artistiques appropriées; Développer l''expression artistique par l''expression créative',NULL,NULL,NULL,'formative','{"observable":["L''élève manipule différents tissus et fibres avec dextérité","L''élève applique des techniques de base (tressage, nouage, tissage simple)","L''élève combine couleurs et textures de manière harmonieuse","L''élève utilise des outils textiles appropriés avec sécurité","L''élève exprime ses idées à travers le médium textile"],"checkpoints":["Crée une pièce textile simple mais complète","Démontre la maîtrise d''au moins 2 techniques textiles"]}',1,'Plan détaillé avec supports visuels',1756911653344,1757587621447,1,'fr','Arts visuels','{"pourDifficultés":["Utiliser des matériaux plus gros et plus faciles à manipuler","Se concentrer sur une seule technique par session","Fournir aide physique pour les mouvements complexes","Simplifier les projets textile"],"pourAvancés":["Combiner plusieurs techniques textiles en une œuvre","Explorer des motifs et designs complexes","Rechercher des techniques textiles traditionnelles","Enseigner les techniques à leurs pairs"],"pourLangue":["Focus sur l''exploration tactile et visuelle","Cartes de vocabulaire avec images de techniques","Démonstrations sans explications verbales complexes","Jumelage avec pairs bilingues"],"pourPEI":["Adapter les outils selon les capacités motrices","Simplifier les techniques selon les besoins","Fournir supports physiques au besoin","Matériaux adaptés aux sensibilités"]}','{"vocabulary":["textile","tisser","coudre"],"visualSupports":["Images agrandies de structures textiles, gestes pour chaque mot de vocabulaire, exemples d''arts textiles","Démonstrations étape par étape pour chaque technique, guides de sécurité, exemples d''œuvres textiles","Galerie d''arts textiles, connexions culturelles illustrées, vocabulaire textile en contexte"],"movementBreaks":["Gestes de tissage avec les doigts","Mouvements de couture et de manipulation de tissu","Rotation entre stations d''activités textiles","Mouvements de tissage et d''étirement des fils","Mouvements pour imiter les techniques textiles observées","Gestes d''appréciation pour les créations"]}',NULL,NULL,NULL,NULL,'{"questions":["Les élèves ont-ils atteint les objectifs?","Quelles adaptations étaient nécessaires?","Que ferais-je différemment la prochaine fois?"]}',NULL,'',4,7,'core',1);
INSERT INTO ETFOLessonPlan VALUES('cmf43u3tt008hvj9tmk4gsd59',23,'Techniques mixtes','cmf43u3tm0081vj9t236523o9',1775055600000,45,'Review all advanced techniques learned in previous lessons. Show examples of artworks combining multiple techniques. Introduce vocabulary: MIXTE (combining gesture), COMPLEXE (layered complexity gesture), INTÉGRER (integration motion).','Création d''œuvres à techniques mixtes. Planifier d''abord: choisir 2-3 techniques compatibles. Créer une œuvre intégrant les techniques choisies. Encourager: ''J''intègre... avec...'', ''Mon œuvre complexe utilise...''. Documenter le processus créatif.','Complex Artwork Presentation. Students present their multi-technique works, explaining how different techniques were integrated. Use sophisticated vocabulary to describe complex creative decisions.','Peindre le concept de techniques mixtes; Créer les techniques artistiques appropriées; Développer l''expression artistique par l''expression créative','["Exemples d''œuvres utilisant plusieurs techniques","Affichage des techniques apprises (leçons 1-7)","Cartes de vocabulaire avec gestes","Matériaux de toutes les leçons précédentes","All materials from previous advanced technique lessons","Large format paper or canvas","Planning sheets","Documentation cameras","Complex artwork examples","Supports d''exposition pour œuvres complexes","Cartes de présentation structurées","Guide de vocabulaire pour présentations"]',NULL,'Techniques mixtes','Review all advanced techniques learned in previous lessons. Show examples of artworks combining multiple techniques. Introduce vocabulary: MIXTE (combining gesture), COMPLEXE (layered complexity gesture), INTÉGRER (integration motion).','Création d''œuvres à techniques mixtes. Planifier d''abord: choisir 2-3 techniques compatibles. Créer une œuvre intégrant les techniques choisies. Encourager: ''J''intègre... avec...'', ''Mon œuvre complexe utilise...''. Documenter le processus créatif.','Complex Artwork Presentation. Students present their multi-technique works, explaining how different techniques were integrated. Use sophisticated vocabulary to describe complex creative decisions.','Peindre le concept de techniques mixtes; Créer les techniques artistiques appropriées; Développer l''expression artistique par l''expression créative',NULL,NULL,NULL,'formative','{"observable":["L''élève combine au moins 3 techniques artistiques différentes","L''élève planifie l''intégration des différentes techniques","L''élève adapte ses techniques selon les matériaux utilisés","L''élève crée une œuvre cohérente malgré la diversité des techniques","L''élève explique ses choix techniques en français"],"checkpoints":["Produit une œuvre intégrant harmonieusement plusieurs techniques","Justifie ses choix artistiques et techniques"]}',1,'Plan détaillé avec supports visuels',1756911653346,1757587621448,1,'fr','Arts visuels','{"pourDifficultés":["Limiter à 2 techniques simples et compatibles","Fournir des modèles de planification pré-faits","Travailler en équipe avec support","Se concentrer sur l''exploration plutôt que le résultat"],"pourAvancés":["Intégrer 4-5 techniques différentes","Créer des effets innovants avec les combinaisons","Planifier des séries d''œuvres liées","Mentorer d''autres élèves dans l''intégration"],"pourLangue":["Focus sur la création visuelle plutôt que verbale","Démonstrations claires des combinaisons","Vocabulaire supporté par des images","Jumelage pour l''explication du processus"],"pourPEI":["Adapter le nombre de techniques selon les capacités","Simplifier la planification avec supports visuels","Fournir aide physique pour l''exécution","Objectifs modifiés selon les besoins individuels"]}','{"vocabulary":["mixte","complexe","intégrer"],"visualSupports":["Résumé visuel des techniques apprises, exemples de combinaisons réussies, gestes pour le vocabulaire","Guide de planification pour techniques mixtes, exemples d''intégration réussie, étapes de combinaison illustrées","Modèles de présentation, vocabulaire sophistiqué pour décrire les œuvres, exemples d''analyse d''œuvres"],"movementBreaks":["Gestes de rappel pour chaque technique apprise","Mouvements d''intégration et de combinaison","Rotation entre différentes stations de techniques","Pauses pour observer et planifier les prochaines étapes","Mouvements pour démontrer les techniques intégrées","Applaudissements pour célébrer les créations complexes"]}',NULL,NULL,NULL,NULL,'{"questions":["Les élèves ont-ils atteint les objectifs?","Quelles adaptations étaient nécessaires?","Que ferais-je différemment la prochaine fois?"]}',NULL,'',4,8,'core',1);
INSERT INTO ETFOLessonPlan VALUES('cmf43u3tu008jvj9t4bgksgsd',23,'Style personnel avancé','cmf43u3tm0081vj9t236523o9',1775142000000,45,'Look at students'' artwork from throughout the unit. Identify patterns in their choices: favorite techniques, colors, subjects, approaches. Introduce vocabulary: STYLE (distinctive gesture), PERSONNEL (point to self), DÉVELOPPER (growth motion).','Développement du style personnel. Analyser ses œuvres précédentes pour identifier son style unique. Créer une nouvelle œuvre qui exprime délibérément ce style. Encourager: ''Mon style personnel utilise...'', ''Je développe mon style en...''. Documenter les choix stylistiques.','Personal Style Gallery. Display newest artworks that emphasize individual styles. Students present style statements and point out style elements in their work. Celebrate artistic individuality.','Modeler le concept de style personnel; Créer les techniques artistiques appropriées; Développer la motricité fine par l''expression créative','["Portfolios d''œuvres des élèves de l''unité","Exemples de styles artistiques variés","Cartes de vocabulaire avec gestes","Grilles d''analyse de style personnel","Student artwork portfolios from entire unit","Art creation materials matching individual preferences","Style documentation sheets","Recording equipment for style statements","Espace d''exposition pour styles personnels","Cartes de déclaration de style","Supports pour présentation individuelle"]',NULL,'Style personnel avancé','Look at students'' artwork from throughout the unit. Identify patterns in their choices: favorite techniques, colors, subjects, approaches. Introduce vocabulary: STYLE (distinctive gesture), PERSONNEL (point to self), DÉVELOPPER (growth motion).','Développement du style personnel. Analyser ses œuvres précédentes pour identifier son style unique. Créer une nouvelle œuvre qui exprime délibérément ce style. Encourager: ''Mon style personnel utilise...'', ''Je développe mon style en...''. Documenter les choix stylistiques.','Personal Style Gallery. Display newest artworks that emphasize individual styles. Students present style statements and point out style elements in their work. Celebrate artistic individuality.','Modeler le concept de style personnel; Créer les techniques artistiques appropriées; Développer la motricité fine par l''expression créative',NULL,NULL,NULL,'formative','{"observable":["L''élève identifie ses préférences artistiques personnelles","L''élève développe des motifs ou techniques récurrents","L''élève fait des choix cohérents de couleurs et formes","L''élève exprime sa personnalité à travers ses créations","L''élève affine sa motricité fine par la répétition de gestes précis"],"checkpoints":["Crée des œuvres reconnaissables comme étant les siennes","Explique ce qui rend son style unique"]}',1,'Plan détaillé avec supports visuels',1756911653346,1757587621448,1,'fr','Arts visuels','{"pourDifficultés":["Fournir des guides pour identifier les éléments de style","Concentrer sur 1-2 caractéristiques de style seulement","Utiliser des comparaisons visuelles simples","Célébrer tous les choix comme valides"],"pourAvancés":["Analyser l''évolution de leur style à travers l''unité","Créer une série d''œuvres dans leur style","Comparer leur style à celui d''artistes célèbres","Planifier le développement futur de leur style"],"pourLangue":["Focus sur l''identification visuelle plutôt que verbale","Utiliser des images pour communiquer le style","Permettre l''expression en langue première","Support par des pairs bilingues"],"pourPEI":["Adapter l''analyse selon les capacités cognitives","Simplifier les concepts de style","Utiliser des supports visuels concrets","Célébrer leur expression unique"]}','{"vocabulary":["style","personnel","développer"],"visualSupports":["Galerie des œuvres de l''élève, exemples de différents styles artistiques, gestes pour le vocabulaire","Guide d''analyse de style personnel, exemples de déclarations d''artistes sur leur style, modèles de documentation","Galerie organisée par style, modèles de déclarations d''artiste, célébration de la diversité"],"movementBreaks":["Gestes distinctifs pour montrer son style personnel","Mouvements de développement et de croissance artistique","Mouvements expressifs qui représentent leur style","Pauses pour réfléchir et observer son travail","Mouvements de présentation confiante de son style","Célébration collective de la diversité artistique"]}',NULL,NULL,NULL,NULL,'{"questions":["Les élèves ont-ils atteint les objectifs?","Quelles adaptations étaient nécessaires?","Que ferais-je différemment la prochaine fois?"]}',NULL,'',4,9,'core',1);
INSERT INTO ETFOLessonPlan VALUES('cmf43u3tv008lvj9ts8zq8z0n',23,'Art conceptuel','cmf43u3tm0081vj9t236523o9',1775228400000,45,'Discuss difference between decorative art and conceptual art. Show examples of art that expresses ideas vs art that''s purely visual. Introduce vocabulary: CONCEPT (thinking gesture), IDÉE (lightbulb gesture), EXPRIMER (expression gestures).','Création d''art conceptuel. Choisir une idée importante (amitié, nature, famille). Planifier comment l''exprimer avec les techniques apprises. Créer une œuvre qui communique ce concept. Encourager: ''Mon concept est...'', ''J''exprime cette idée en...''. Documenter les choix conceptuels.','Conceptual Art Presentations. Students present artworks and explain concepts being expressed. Audience tries to ''read'' concepts in artwork. Practice vocabulary: ''Cette œuvre exprime le concept de...''','Transformer le concept de art conceptuel; Créer les techniques artistiques appropriées; Développer la motricité fine par l''expression créative','["Exemples d''art décoratif vs conceptuel","Images d''œuvres qui expriment des idées","Cartes de vocabulaire avec gestes","Objets pour illustrer les concepts vs décoration","All advanced technique materials from previous lessons","Concept planning sheets","Idea development templates","Examples of concept-technique connections","Supports de présentation pour art conceptuel","Guide pour ''lire'' les concepts dans l''art","Cartes de feedback constructif"]',NULL,'Art conceptuel','Discuss difference between decorative art and conceptual art. Show examples of art that expresses ideas vs art that''s purely visual. Introduce vocabulary: CONCEPT (thinking gesture), IDÉE (lightbulb gesture), EXPRIMER (expression gestures).','Création d''art conceptuel. Choisir une idée importante (amitié, nature, famille). Planifier comment l''exprimer avec les techniques apprises. Créer une œuvre qui communique ce concept. Encourager: ''Mon concept est...'', ''J''exprime cette idée en...''. Documenter les choix conceptuels.','Conceptual Art Presentations. Students present artworks and explain concepts being expressed. Audience tries to ''read'' concepts in artwork. Practice vocabulary: ''Cette œuvre exprime le concept de...''','Transformer le concept de art conceptuel; Créer les techniques artistiques appropriées; Développer la motricité fine par l''expression créative',NULL,NULL,NULL,'formative','{"observable":["L''élève exprime une idée simple à travers son art","L''élève explique le message ou l''émotion de son œuvre","L''élève choisit des matériaux qui soutiennent son concept","L''élève développe sa pensée créative au-delà de la représentation","L''élève utilise des gestes fins et contrôlés dans sa création"],"checkpoints":["Crée une œuvre avec une intention claire","Communique efficacement son concept artistique"]}',1,'Plan détaillé avec supports visuels',1756911653347,1757587621449,1,'fr','Arts visuels','{"pourDifficultés":["Fournir une liste de concepts simples à choisir","Utiliser des images pour clarifier les concepts","Se concentrer sur l''expression plutôt que la complexité","Permettre l''aide verbale pour expliquer le concept"],"pourAvancés":["Explorer des concepts abstraits plus complexes","Créer des séries d''œuvres sur le même concept","Analyser comment les artistes célèbres expriment des idées","Développer leur propre symbolisme artistique"],"pourLangue":["Utiliser des concepts universels (famille, nature)","Permettre l''explication en langue première","Focus sur l''expression visuelle plutôt que verbale","Support par des images et des gestes"],"pourPEI":["Simplifier les concepts selon les capacités cognitives","Utiliser des supports visuels concrets","Adapter les attentes d''expression","Célébrer toute tentative d''expression conceptuelle"]}','{"vocabulary":["concept","idée","exprimer"],"visualSupports":["Comparaisons art décoratif/conceptuel, gestes pour le vocabulaire, exemples d''œuvres à message","Guide de développement d''idées, connexions concept-technique, exemples d''art conceptuel pour enfants","Modèles de présentation conceptuelle, vocabulaire pour analyser l''art conceptuel"],"movementBreaks":["Gestes de réflexion et d''expression d''idées","Mouvements pour représenter différents concepts","Pauses pour réfléchir sur le concept choisi","Mouvements expressifs liés au concept","Mouvements pour ''montrer'' et expliquer le concept","Gestes d''appréciation pour les idées partagées"]}',NULL,NULL,NULL,NULL,'{"questions":["Les élèves ont-ils atteint les objectifs?","Quelles adaptations étaient nécessaires?","Que ferais-je différemment la prochaine fois?"]}',NULL,'',4,10,'core',1);
INSERT INTO ETFOLessonPlan VALUES('cmf43u3tw008nvj9tu2bx9vyf',23,'Critique d''art','cmf43u3tm0081vj9t236523o9',1775487600000,45,'Introduce art criticism as learning tool, not just opinion sharing. Practice constructive criticism vs destructive criticism. Introduce vocabulary: CRITIQUE (analytical thinking gesture), ANALYSER (close examination motion), VOCABULAIRE (words/speaking gesture).','Pratique de critique d''art guidée. En paires, analyser des œuvres d''élèves et d''artistes professionnels. Utiliser le vocabulaire avancé et poser des questions analytiques. Pratiquer: ''Cette œuvre utilise...'', ''L''artiste exprime...''. Documenter les analyses.','Critique Reflection. Students reflect on criticism received and given. Discuss how critique helps artistic growth. Practice vocabulary: ''La critique m''aide à...'' Plan how to use critique for improvement.','Représenter le concept de critique d''art; Créer les techniques artistiques appropriées; Développer la motricité fine par l''expression créative','["Exemples de critiques constructives vs destructives","Liste de vocabulaire d''analyse artistique","Cartes de questions pour la critique","Exemples d''œuvres à analyser","Advanced art vocabulary lists","Critique question templates","Student artworks for analysis","Professional artwork examples","Critique recording sheets","Feuilles de réflexion sur la critique","Guide pour utiliser la critique constructivement","Cartes de résumé des apprentissages"]',NULL,'Critique d''art','Introduce art criticism as learning tool, not just opinion sharing. Practice constructive criticism vs destructive criticism. Introduce vocabulary: CRITIQUE (analytical thinking gesture), ANALYSER (close examination motion), VOCABULAIRE (words/speaking gesture).','Pratique de critique d''art guidée. En paires, analyser des œuvres d''élèves et d''artistes professionnels. Utiliser le vocabulaire avancé et poser des questions analytiques. Pratiquer: ''Cette œuvre utilise...'', ''L''artiste exprime...''. Documenter les analyses.','Critique Reflection. Students reflect on criticism received and given. Discuss how critique helps artistic growth. Practice vocabulary: ''La critique m''aide à...'' Plan how to use critique for improvement.','Représenter le concept de critique d''art; Créer les techniques artistiques appropriées; Développer la motricité fine par l''expression créative',NULL,NULL,NULL,'formative','{"observable":["L''élève observe attentivement les œuvres d''art","L''élève utilise un vocabulaire artistique approprié pour décrire","L''élève exprime ses opinions personnelles avec respect","L''élève identifie les techniques utilisées par l''artiste","L''élève fait des liens entre l''art et ses propres expériences"],"checkpoints":["Décrit une œuvre d''art en utilisant le vocabulaire approprié","Exprime une opinion personnelle justifiée sur une œuvre"]}',1,'Plan détaillé avec supports visuels',1756911653348,1757587621449,1,'fr','Arts visuels','{"pourDifficultés":["Fournir des phrases-modèles pour la critique","Se concentrer sur des observations simples avant l''analyse","Utiliser des images pour supporter le vocabulaire","Permettre la critique orale plutôt qu''écrite"],"pourAvancés":["Utiliser un vocabulaire critique plus sophistiqué","Analyser des aspects techniques complexes","Comparer les œuvres à différents styles artistiques","Formuler des critiques détaillées et nuancées"],"pourLangue":["Vocabulaire critique supporté par des images","Permettre l''usage de la langue première pour clarifier","Focus sur l''observation avant l''analyse verbale","Support de pairs bilingues"],"pourPEI":["Simplifier le vocabulaire critique","Adapter les attentes d''analyse","Utiliser des supports visuels concrets","Encourager toute tentative d''analyse"]}','{"vocabulary":["critique","analyser","vocabulaire"],"visualSupports":["Comparaisons critique constructive/destructive, vocabulaire d''analyse illustré, gestes pour le vocabulaire","Guide de questions d''analyse, vocabulaire d''art avancé, modèles de critique constructive","Modèles de réflexion, cycle de l''amélioration par la critique, vocabulaire de croissance"],"movementBreaks":["Gestes d''analyse et d''examen attentif","Mouvements pour exprimer différents types de critiques","Changement de partenaires pour différentes analyses","Mouvements pour pointer et examiner les détails","Gestes de croissance et d''amélioration","Mouvements de gratitude pour les commentaires reçus"]}',NULL,NULL,NULL,NULL,'{"questions":["Les élèves ont-ils atteint les objectifs?","Quelles adaptations étaient nécessaires?","Que ferais-je différemment la prochaine fois?"]}',NULL,'',4,11,'core',1);
INSERT INTO ETFOLessonPlan VALUES('cmf43u3tx008pvj9taiw7f7wv',23,'Processus créatif','cmf43u3tm0081vj9t236523o9',1775574000000,45,'Discuss how they created their best artwork: what steps, what decisions, what changes. Introduce vocabulary: PROCESSUS (step-by-step motion), CRÉATIF (creative thinking gesture), DOCUMENTER (recording/writing motion).','Documentation du processus créatif personnel. Créer une petite œuvre en documentant chaque étape: idée initiale, choix de matériaux, décisions, changements. Encourager: ''Mon processus commence par...'', ''Je documente en...''. Réfléchir sur leurs habitudes créatives.','Process Sharing. Students share insights about their creative processes. Compare different approaches. Discuss how understanding process helps improve art-making. Celebrate process diversity.','Créer le concept de processus créatif; Créer les techniques artistiques appropriées; Développer la motricité fine par l''expression créative','["Œuvres précédentes des élèves pour référence","Diagrammes de processus créatifs","Cartes de vocabulaire avec gestes","Exemples de documentation de processus","Documentation tools (cameras, recording devices, notebooks)","Art materials for new creation","Process analysis templates","Process documentation examples","Documentations de processus créées","Tableau comparatif des différents processus","Cartes de célébration de la diversité"]',NULL,'Processus créatif','Discuss how they created their best artwork: what steps, what decisions, what changes. Introduce vocabulary: PROCESSUS (step-by-step motion), CRÉATIF (creative thinking gesture), DOCUMENTER (recording/writing motion).','Documentation du processus créatif personnel. Créer une petite œuvre en documentant chaque étape: idée initiale, choix de matériaux, décisions, changements. Encourager: ''Mon processus commence par...'', ''Je documente en...''. Réfléchir sur leurs habitudes créatives.','Process Sharing. Students share insights about their creative processes. Compare different approaches. Discuss how understanding process helps improve art-making. Celebrate process diversity.','Créer le concept de processus créatif; Créer les techniques artistiques appropriées; Développer la motricité fine par l''expression créative',NULL,NULL,NULL,'formative','{"observable":["L''élève planifie son travail avant de commencer","L''élève documente ses étapes de création (dessins, notes)","L''élève fait des ajustements en cours de création","L''élève réfléchit sur ses choix artistiques","L''élève persévère malgré les défis rencontrés"],"checkpoints":["Complète un projet en suivant toutes les étapes du processus","Explique son processus créatif de l''idée à la réalisation"]}',1,'Plan détaillé avec supports visuels',1756911653349,1757587621450,1,'fr','Arts visuels','{"pourDifficultés":["Simplifier la documentation à 3 étapes principales","Utiliser des dessins plutôt que des mots pour documenter","Fournir des modèles de réflexion guidée","Se concentrer sur le ressenti plutôt que l''analyse"],"pourAvancés":["Analyser l''évolution de leur processus à travers l''unité","Comparer leur processus à celui d''artistes professionnels","Développer des stratégies pour améliorer leur processus","Documenter de multiples approches créatives"],"pourLangue":["Documentation visuelle plutôt que verbale","Vocabulaire du processus supporté par des images","Permettre l''explication en langue première","Focus sur l''action plutôt que la description"],"pourPEI":["Adapter la complexité de la réflexion","Utiliser des supports visuels concrets","Simplifier les outils de documentation","Célébrer leur approche unique"]}','{"vocabulary":["processus","créatif","documenter"],"visualSupports":["Étapes du processus créatif illustrées, gestes pour le vocabulaire, exemples de réflexion d''artistes","Modèles de documentation, exemples de processus créatifs d''élèves, guide de réflexion","Galerie de processus, comparaisons de différentes approches, célébration de l''unicité"],"movementBreaks":["Gestes pour montrer les étapes du processus","Mouvements de documentation et d''enregistrement","Pauses pour observer et réfléchir sur le processus","Mouvements pour changer entre création et documentation","Mouvements pour montrer et expliquer son processus","Gestes d''appréciation pour la diversité créative"]}',NULL,NULL,NULL,NULL,'{"questions":["Les élèves ont-ils atteint les objectifs?","Quelles adaptations étaient nécessaires?","Que ferais-je différemment la prochaine fois?"]}',NULL,'',4,12,'core',1);
INSERT INTO ETFOLessonPlan VALUES('cmf43u3tx008rvj9tsm4jkoit',23,'Collaboration artistique avancée','cmf43u3tm0081vj9t236523o9',4102416000000,45,'Discuss how professional artists collaborate: sharing expertise, dividing complex tasks, combining different strengths. Introduce vocabulary: COLLABORATION (working together gesture), AVANCÉ (sophisticated level gesture), TECHNIQUE (skillful demonstration).','Projet collaboratif avancé. Équipes de 3-4 élèves planifient puis créent une œuvre combinant plusieurs techniques apprises. Chaque membre contribue avec sa spécialité. Encourager: ''Notre collaboration utilise...'', ''Mon rôle avancé est de...''. Documenter le processus collaboratif.','Collaborative Artwork Presentation. Groups present artworks and explain how different advanced techniques were contributed by different collaborators. Celebrate successful artistic teamwork.','Dessiner le concept de collaboration artistique; Créer les techniques artistiques appropriées; Développer le sens esthétique par l''expression créative','["Images d''artistes collaborant","Exemples de projets collaboratifs réussis","Cartes de rôles pour collaboration","Cartes de vocabulaire avec gestes","All advanced technique materials from unit","Large format collaborative workspace","Role assignment tools","Collaboration planning templates","Supports de présentation pour œuvres collaboratives","Cartes de réflexion sur la collaboration","Certificats de collaboration réussie"]',NULL,'Collaboration artistique avancée','Discuss how professional artists collaborate: sharing expertise, dividing complex tasks, combining different strengths. Introduce vocabulary: COLLABORATION (working together gesture), AVANCÉ (sophisticated level gesture), TECHNIQUE (skillful demonstration).','Projet collaboratif avancé. Équipes de 3-4 élèves planifient puis créent une œuvre combinant plusieurs techniques apprises. Chaque membre contribue avec sa spécialité. Encourager: ''Notre collaboration utilise...'', ''Mon rôle avancé est de...''. Documenter le processus collaboratif.','Collaborative Artwork Presentation. Groups present artworks and explain how different advanced techniques were contributed by different collaborators. Celebrate successful artistic teamwork.','Dessiner le concept de collaboration artistique; Créer les techniques artistiques appropriées; Développer le sens esthétique par l''expression créative',NULL,NULL,NULL,'formative','{"observable":["L''élève partage ses idées de manière constructive","L''élève écoute et intègre les suggestions des autres","L''élève contribue équitablement au projet de groupe","L''élève négocie les décisions artistiques avec respect","L''élève coordonne ses mouvements avec ceux de ses pairs"],"checkpoints":["Participe activement à la création d''une œuvre collective","Démontre des habiletés de collaboration positives"]}',1,'Plan détaillé avec supports visuels',1756911653350,1757587621450,1,'fr','Arts visuels','{"pourDifficultés":["Assigner des rôles spécifiques et plus simples","Jumeler avec des équipiers soutenants","Réduire la complexité des techniques requises","Fournir plus de structure et de guidance"],"pourAvancés":["Prendre des rôles de leadership dans l''équipe","Intégrer des techniques particulièrement complexes","Aider à coordonner le projet d''équipe","Développer des innovations collaboratives"],"pourLangue":["Focus sur la contribution technique plutôt que verbale","Jumelage avec pairs bilingues","Rôles qui utilisent leurs forces artistiques","Communication supportée par l''art visuel"],"pourPEI":["Adapter les rôles selon les capacités individuelles","Fournir support supplémentaire pour l''interaction sociale","Ajuster les attentes de collaboration","Célébrer toute participation à l''équipe"]}','{"vocabulary":["collaboration","avancé","technique"],"visualSupports":["Exemples de collaborations artistiques, gestes pour le vocabulaire, diagrammes de rôles collaboratifs","Guides de planification collaborative, exemples de répartition des rôles, modèles d''œuvres collaboratives","Galerie de projets collaboratifs, modèles de présentation d''équipe, célébration du travail d''équipe"],"movementBreaks":["Gestes de collaboration et de travail d''équipe","Mouvements pour montrer différentes compétences techniques","Rotation entre différentes tâches collaboratives","Pauses pour coordination et planification d''équipe","Mouvements de présentation collaborative","Célébrations d''équipe et applaudissements"]}',NULL,NULL,NULL,NULL,'{"questions":["Les élèves ont-ils atteint les objectifs?","Quelles adaptations étaient nécessaires?","Que ferais-je différemment la prochaine fois?"]}',NULL,'',4,13,'core',0);
INSERT INTO ETFOLessonPlan VALUES('cmf43u3tz008vvj9t6j09fwnl',23,'Maîtrise technique','cmf43u3tm0081vj9t236523o9',1775660400000,45,'Review all advanced techniques learned in unit. Students identify which techniques they feel most confident using. Introduce vocabulary: MAÎTRISE (mastery demonstration), DÉMONTRER (showing/proving gesture), CHOISI (choice-making gesture).','Démonstration de maîtrise personnelle. Chaque élève crée une œuvre finale utilisant ses techniques les mieux maîtrisées. Viser l''excellence dans l''exécution. Encourager: ''Je démontre ma maîtrise de...'', ''J''ai choisi cette technique parce que...''. Préparer une déclaration d''artiste.','Mastery Exhibition. Present mastery artworks with formal artist statements. Celebrate individual technical growth and achievement. Practice mastery vocabulary in formal presentation context.','Peindre le concept de maîtrise technique; Créer les techniques artistiques appropriées; Développer le sens esthétique par l''expression créative','["Portfolio complet des techniques apprises dans l''unité","Auto-évaluations des compétences techniques","Cartes de vocabulaire avec gestes","Exemples de maîtrise artistique de différents niveaux","All advanced technique materials","High-quality art materials for mastery work","Documentation tools","Artist statement templates","Espace d''exposition formelle pour œuvres de maîtrise","Supports pour déclarations d''artiste","Certificats de maîtrise technique","Cartes de célébration des progrès"]',NULL,'Maîtrise technique','Review all advanced techniques learned in unit. Students identify which techniques they feel most confident using. Introduce vocabulary: MAÎTRISE (mastery demonstration), DÉMONTRER (showing/proving gesture), CHOISI (choice-making gesture).','Démonstration de maîtrise personnelle. Chaque élève crée une œuvre finale utilisant ses techniques les mieux maîtrisées. Viser l''excellence dans l''exécution. Encourager: ''Je démontre ma maîtrise de...'', ''J''ai choisi cette technique parce que...''. Préparer une déclaration d''artiste.','Mastery Exhibition. Present mastery artworks with formal artist statements. Celebrate individual technical growth and achievement. Practice mastery vocabulary in formal presentation context.','Peindre le concept de maîtrise technique; Créer les techniques artistiques appropriées; Développer le sens esthétique par l''expression créative',NULL,NULL,NULL,'formative','{"observable":["L''élève démontre un contrôle amélioré de ses outils artistiques","L''élève reproduit intentionnellement des techniques apprises","L''élève combine plusieurs techniques avec aisance","L''élève évalue la qualité technique de son propre travail","L''élève développe son sens esthétique par l''appréciation des détails"],"checkpoints":["Exécute des techniques artistiques avec précision et confiance","Crée une œuvre finale démontrant la maîtrise de plusieurs techniques"]}',1,'Plan détaillé avec supports visuels',1756911653351,1757587621451,1,'fr','Arts visuels','{"pourDifficultés":["Définir la maîtrise selon leurs capacités individuelles","Célébrer les progrès plutôt que la perfection","Fournir des exemples concrets de leurs améliorations","Permettre la démonstration de techniques plus simples mais bien exécutées"],"pourAvancés":["Défier à démontrer des techniques particulièrement complexes","Encourager l''innovation dans l''usage des techniques maîtrisées","Créer des œuvres qui poussent leurs limites techniques","Devenir mentors pour partager leur maîtrise"],"pourLangue":["Maîtrise démontrée à travers l''art plutôt que les mots","Vocabulaire de maîtrise supporté par l''action","Déclarations d''artiste avec support visuel","Célébration de l''expression artistique universelle"],"pourPEI":["Adapter les critères de maîtrise aux objectifs individuels","Célébrer toute démonstration de progrès","Fournir supports supplémentaires pour la présentation","Reconnaissance de leurs accomplissements uniques"]}','{"vocabulary":["maîtrise","démontrer","choisi"],"visualSupports":["Résumé visuel de toutes les techniques, échelles de maîtrise, gestes pour le vocabulaire","Modèles de déclarations d''artiste, critères d''excellence technique, exemples de maîtrise artistique","Galerie de maîtrise, modèles de présentations formelles, célébration des accomplissements"],"movementBreaks":["Gestes de démonstration de maîtrise pour chaque technique","Mouvements de choix délibéré et de confiance","Pauses pour évaluer et ajuster la qualité du travail","Moments de concentration intense sur la maîtrise technique","Mouvements de présentation confiante et professionnelle","Célébrations d''accomplissement et de fierté artistique"]}',NULL,NULL,NULL,NULL,'{"questions":["Les élèves ont-ils atteint les objectifs?","Quelles adaptations étaient nécessaires?","Que ferais-je différemment la prochaine fois?"]}',NULL,'',4,14,'core',1);
INSERT INTO ETFOLessonPlan VALUES('cmf43u3u1008zvj9tnxws7z6a',23,'Découverte tactile: Qu''est-ce qu''une texture?','cmf43u3u0008xvj9tsg5gcs5s',1766160000000,45,'Cercle de bienvenue. Montrer une boîte mystère contenant différents objets texturés (lisse, rugueux, doux, dur). Les élèves touchent les objets sans regarder et décrivent ce qu''ils ressentent en français: ''C''est rugueux comme l''écorce d''un arbre'' ou ''C''est lisse comme du verre''.','Station d''exploration tactile avec 6 postes : 1) Textiles variés, 2) Papiers différents, 3) Objets naturels, 4) Surfaces métalliques, 5) Plastiques texturés, 6) Matériaux recyclés. Les élèves circulent par groupes de 4, touchent et décrivent en français. Création d''un ''livre tactile'' collectif où chaque élève dessine et colle un échantillon de texture avec le mot français.','Cercle de partage. Chaque élève choisit sa texture préférée de la journée et explique pourquoi en français simple: ''J''aime le doux parce que c''est comme câliner maman.'' Récapitulatif du vocabulaire avec gestes. Plan pour la prochaine leçon : chercher des textures dans notre environnement.','Découvrir le concept de découverte tactile:; Créer les techniques artistiques appropriées; Développer la créativité par l''expression créative','["Boîte mystère","Objets texturés variés (lisse: miroir, rugueux: papier sablé, doux: peluche, dur: pierre)","Cartes visuelles des textures","6 plateaux d''exploration","Textiles variés","Papiers texturés","Objets naturels (coquillages, pierres, écorce)","Surfaces métalliques","Plastiques texturés","Matériaux recyclés","Carnet collectif","Colle","Crayons","Échantillons de textures explorées","Cartes vocabulaire"]',NULL,'Découverte tactile: Qu''est-ce qu''une texture?','Cercle de bienvenue. Montrer une boîte mystère contenant différents objets texturés (lisse, rugueux, doux, dur). Les élèves touchent les objets sans regarder et décrivent ce qu''ils ressentent en français: ''C''est rugueux comme l''écorce d''un arbre'' ou ''C''est lisse comme du verre''.','Station d''exploration tactile avec 6 postes : 1) Textiles variés, 2) Papiers différents, 3) Objets naturels, 4) Surfaces métalliques, 5) Plastiques texturés, 6) Matériaux recyclés. Les élèves circulent par groupes de 4, touchent et décrivent en français. Création d''un ''livre tactile'' collectif où chaque élève dessine et colle un échantillon de texture avec le mot français.','Cercle de partage. Chaque élève choisit sa texture préférée de la journée et explique pourquoi en français simple: ''J''aime le doux parce que c''est comme câliner maman.'' Récapitulatif du vocabulaire avec gestes. Plan pour la prochaine leçon : chercher des textures dans notre environnement.','Découvrir le concept de découverte tactile:; Créer les techniques artistiques appropriées; Développer la créativité par l''expression créative',NULL,NULL,NULL,'formative','{"observable":["Élève touche différentes textures volontairement","Utilise le vocabulaire tactile en français","Fait des comparaisons simples entre textures","Participe aux discussions de groupe"],"checkpoints":["Évaluation informelle pendant l''exploration des stations","Observation des interactions pendant le cercle de partage","Documentation des mots de vocabulaire utilisés spontanément"]}',1,'Plan détaillé avec supports visuels',1756911653353,1757594653884,1,'fr','Arts visuels','{"pourDifficultés":["Commencer avec seulement 3 textures de base (lisse, rugueux, doux)","Utiliser des objets familiers (peluche, livre, caillou)","Permettre de toucher avec supervision étroite"],"pourAvancés":["Introduire des nuances (très rugueux, un peu lisse)","Créer des phrases comparatives complexes","Devenir ''expert texture'' pour aider les pairs"],"pourLangue":["Cartes visuelles avec mots en français et images claires","Gestes corporels pour chaque texture","Répétition fréquente du vocabulaire"],"pourPEI":["Adaptation tactile selon sensibilités sensorielles","Temps supplémentaire pour explorer","Support visuel personnalisé"]}','{"vocabulary":["texture","rugueux","lisse","doux"],"visualSupports":["Cartes illustrées montrant différentes textures avec les mots en français","Affiches des 6 stations avec pictogrammes et mots en français, tableau de vocabulaire tactile","Mur de mots tactiles commencé aujourd''hui"],"movementBreaks":["Jeu ''texture corporelle'' - les élèves imitent des textures avec leur corps (rigide pour dur, ondulé pour ondulé)","Danse des textures - musique rythmée, les élèves bougent selon la texture nommée","Relaxation tactile - caresser doucement ses bras en respirant calmement"]}',NULL,NULL,NULL,NULL,'{"questions":["Les élèves ont-ils atteint les objectifs?","Quelles adaptations étaient nécessaires?","Que ferais-je différemment la prochaine fois?"]}',NULL,'',4,1,'core',1);
INSERT INTO ETFOLessonPlan VALUES('cmf43u3u20091vj9t0az6dp9o',23,'Chasse aux textures dans notre environnement','cmf43u3u0008xvj9tsg5gcs5s',1767628800000,45,'Cercle d''ouverture avec révision des textures d''hier. Présenter la mission du jour : devenir des ''détectives de textures'' pour explorer l''école. Montrer des cartes d''exploration avec symboles pour observer, documenter et classifier. Expliquer la différence entre naturel (arbre, pierre) et artificiel (plastique, métal) avec exemples concrets.','Chasse aux textures par équipes de 3 dans différentes zones de l''école : 1) Cour d''école (naturel), 2) Couloirs (artificiel), 3) Bibliothèque (mixte), 4) Gymnase (artificiel), 5) Jardin scolaire (naturel). Chaque équipe documente 5 textures différentes par zone avec dessins simples et mots français. Retour en classe pour créer une carte géante des textures de l''école avec classification naturel/artificiel.','Rassemblement devant la carte géante des textures. Chaque équipe présente sa découverte la plus surprenante en français : ''Nous avons trouvé que le mur de briques est rugueux ET dur.'' Célébrer les détectives avec remise de badges. Connexion avec demain : nous utiliserons ces textures pour créer de l''art avec la technique du frottage.','Observer les textures variées; Créer les techniques artistiques appropriées; Développer la créativité par l''expression créative','["Cartes d''exploration","Carnets de détective","Crayons","Tablettes à pinces","Exemples naturels et artificiels","Carnets d''exploration par équipe","Crayons de couleur","Tablettes à pinces","Grande carte de l''école","Autocollants colorés (vert=naturel, bleu=artificiel)","Appareil photo pour documentation","Carte géante complétée","Badges de détectives","Découvertes documentées"]',NULL,'Chasse aux textures dans notre environnement','Cercle d''ouverture avec révision des textures d''hier. Présenter la mission du jour : devenir des ''détectives de textures'' pour explorer l''école. Montrer des cartes d''exploration avec symboles pour observer, documenter et classifier. Expliquer la différence entre naturel (arbre, pierre) et artificiel (plastique, métal) avec exemples concrets.','Chasse aux textures par équipes de 3 dans différentes zones de l''école : 1) Cour d''école (naturel), 2) Couloirs (artificiel), 3) Bibliothèque (mixte), 4) Gymnase (artificiel), 5) Jardin scolaire (naturel). Chaque équipe documente 5 textures différentes par zone avec dessins simples et mots français. Retour en classe pour créer une carte géante des textures de l''école avec classification naturel/artificiel.','Rassemblement devant la carte géante des textures. Chaque équipe présente sa découverte la plus surprenante en français : ''Nous avons trouvé que le mur de briques est rugueux ET dur.'' Célébrer les détectives avec remise de badges. Connexion avec demain : nous utiliserons ces textures pour créer de l''art avec la technique du frottage.','Observer les textures variées; Créer les techniques artistiques appropriées; Développer la créativité par l''expression créative',NULL,NULL,NULL,'formative','{"observable":["Élève identifie correctement naturel vs artificiel","Utilise le vocabulaire d''observation en français","Documente ses découvertes avec dessins ou mots","Collabore efficacement en équipe"],"checkpoints":["Observation pendant l''exploration","Vérification des carnets de détective","Écoute lors des présentations finales","Participation à la carte géante"]}',1,'Plan détaillé avec supports visuels',1756911653354,1757594653885,1,'fr','Arts visuels','{"pourDifficultés":["Limiter à 3 textures claires","Partenaire de soutien constant","Cartes visuelles avec exemples évidents","Zone d''exploration réduite"],"pourAvancés":["Chercher 7-8 textures différentes","Utiliser un vocabulaire descriptif plus riche","Aider à guider les pairs","Créer des catégories supplémentaires (dur/mou, chaud/froid)"],"pourLangue":["Images claires pour naturel/artificiel","Gestes pour chaque action (observer, toucher, dessiner)","Partenaire francophone","Liste visuelle du vocabulaire"],"pourPEI":["Temps supplémentaire pour exploration","Adaptation selon besoins sensoriels","Zone de retrait si surcharge","Documentation simplifiée"]}','{"vocabulary":["observer","documenter","environnement"],"visualSupports":["Tableau de classification naturel/artificiel avec images, badges de détectives","Carte de l''école avec zones marquées, exemples visuels de documentation, tableau de classification","Carte des textures avec classification visuelle, galerie des découvertes"],"movementBreaks":["Échauffement corporel : imiter les mouvements d''observation (regarder de près, de loin, toucher délicatement)","Pause mouvement entre zones : marcher comme la texture trouvée (rigide, souple, ondulé)","Danse de célébration : bouger selon les textures trouvées"]}',NULL,NULL,NULL,NULL,'{"questions":["Les élèves ont-ils atteint les objectifs?","Quelles adaptations étaient nécessaires?","Que ferais-je différemment la prochaine fois?"]}',NULL,'',4,2,'core',1);
INSERT INTO ETFOLessonPlan VALUES('cmf43u3u30093vj9thccr82y4',23,'Premiers frottages: Technique de base','cmf43u3u0008xvj9tsg5gcs5s',1767715200000,45,'Cercle magique avec démonstration mystère : placer une pièce de monnaie sous papier et frotter avec crayon pour révéler l''image. Émerveiller les élèves avec cette ''magie'' du frottage. Expliquer que nous allons utiliser cette technique pour capturer les textures trouvées hier.','Atelier de frottage avec progression : 1) Pratique avec objets plats (feuilles, formes géométriques), 2) Textures de l''école découvertes hier, 3) Création libre avec combinaisons. Les élèves expérimentent différentes pressions et directions. Création d''un portfolio individuel de frottages avec annotations en français.','Galerie instantanée : afficher tous les frottages sur les tables. Promenade silencieuse pour admirer le travail de chacun. Chaque élève choisit un frottage (pas le sien) et dit un mot d''appréciation en français. Réflexion : qu''avons-nous appris sur les textures invisibles?','Expérimenter le concept de premiers frottages:; Créer les techniques artistiques appropriées; Développer la créativité par l''expression créative','["Pièces de monnaie","Papier fin","Crayons de cire","Exemples de frottages","Papier de soie ou papier fin","Crayons de cire variés","Objets texturés collectionnables","Planches à dessin","Portfolios individuels","Frottages créés","Supports d''affichage"]',NULL,'Premiers frottages: Technique de base','Cercle magique avec démonstration mystère : placer une pièce de monnaie sous papier et frotter avec crayon pour révéler l''image. Émerveiller les élèves avec cette ''magie'' du frottage. Expliquer que nous allons utiliser cette technique pour capturer les textures trouvées hier.','Atelier de frottage avec progression : 1) Pratique avec objets plats (feuilles, formes géométriques), 2) Textures de l''école découvertes hier, 3) Création libre avec combinaisons. Les élèves expérimentent différentes pressions et directions. Création d''un portfolio individuel de frottages avec annotations en français.','Galerie instantanée : afficher tous les frottages sur les tables. Promenade silencieuse pour admirer le travail de chacun. Chaque élève choisit un frottage (pas le sien) et dit un mot d''appréciation en français. Réflexion : qu''avons-nous appris sur les textures invisibles?','Expérimenter le concept de premiers frottages:; Créer les techniques artistiques appropriées; Développer la créativité par l''expression créative',NULL,NULL,NULL,'formative','{"observable":["Élève maîtrise la technique de base du frottage","Produit des impressions reconnaissables","Utilise le vocabulaire technique en français","Fait preuve de persévérance face aux défis"],"checkpoints":["Observation pendant la pratique guidée","Évaluation des portfolios individuels","Participation aux discussions techniques","Capacité d''auto-évaluation"]}',1,'Plan détaillé avec supports visuels',1756911653355,1757594653886,1,'fr','Arts visuels','{"pourDifficultés":["Textures très marquées pour débuter","Guidage manuel de la technique","Papier plus épais si nécessaire","Validation fréquente des progrès"],"pourAvancés":["Expérimentation avec couleurs multiples","Combinaison de plusieurs textures","Création d''effets artistiques","Aide aux pairs en difficulté"],"pourLangue":["Démonstrations visuelles claires","Vocabulaire technique avec gestes","Exemples annotés en français simple","Support par un pair francophone"],"pourPEI":["Adaptation des outils selon capacités motrices","Temps supplémentaire","Support émotionnel si frustration","Alternative si difficultés sensorielles"]}','{"vocabulary":["frottage","pression","mouvement"],"visualSupports":["Affiches montrant les étapes du frottage, exemples artistiques célèbres","Guide visuel des techniques de pression, galerie d''exemples, carte de l''école pour référence","Espace galerie aménagé, vocabulaire d''appréciation affiché"],"movementBreaks":["Gestes corporels : imiter les mouvements de frottage dans les airs","Pause créative : étirement des bras et des doigts avec mouvements ondulés","Relaxation : respirer profondément en imaginant les textures créées"]}',NULL,NULL,NULL,NULL,'{"questions":["Les élèves ont-ils atteint les objectifs?","Quelles adaptations étaient nécessaires?","Que ferais-je différemment la prochaine fois?"]}',NULL,'',4,3,'core',1);
INSERT INTO ETFOLessonPlan VALUES('cmf43u3u30095vj9t3oobil1s',23,'Frottages créatifs: Exploration avancée','cmf43u3u0008xvj9tsg5gcs5s',1767801600000,45,'Révision des frottages simples de la leçon précédente avec présentation des réussites. Introduction du concept de superposition : montrer comment superposer deux frottages crée de nouveaux effets visuels. Démonstration en direct avec deux textures différentes. Discussion sur contraste (rugueux + lisse) vs harmonie (textures similaires).','Création de frottages superposés par étapes guidées. Étape 1 : Premier frottage avec couleur claire sur texture douce (7 min). Étape 2 : Deuxième frottage avec couleur plus foncée sur texture contrastée, en superposition partielle (10 min). Étape 3 : Ajouts créatifs et détails personnels (10 min). Circulation pour encouragements et conseils techniques personnalisés.','Galerie d''appréciation mutuelle : accrochage temporaire des frottages superposés. Visite libre avec commentaires positifs encouragés. Identification collective des effets de superposition réussis : contrastes saisissants, harmonies douces, effets surprise. Chaque élève choisit son détail préféré sur l''œuvre d''un pair.','Transformer le concept de frottages créatifs:; Explorer les techniques artistiques appropriées; Développer la créativité par l''exploration guidée','["Frottages de la leçon précédente","Papier calque","Crayons cire de couleurs variées","Objets texturés pour démonstration","Papier résistant pour frottages multiples","Crayons cire palette étendue","Variété d''objets texturés classés par intensité","Papier brouillon pour tests","Frottages superposés créés","Système d''accrochage rapide","Cartons pour commentaires positifs"]',NULL,'Frottages créatifs: Exploration avancée','Révision des frottages simples de la leçon précédente avec présentation des réussites. Introduction du concept de superposition : montrer comment superposer deux frottages crée de nouveaux effets visuels. Démonstration en direct avec deux textures différentes. Discussion sur contraste (rugueux + lisse) vs harmonie (textures similaires).','Création de frottages superposés par étapes guidées. Étape 1 : Premier frottage avec couleur claire sur texture douce (7 min). Étape 2 : Deuxième frottage avec couleur plus foncée sur texture contrastée, en superposition partielle (10 min). Étape 3 : Ajouts créatifs et détails personnels (10 min). Circulation pour encouragements et conseils techniques personnalisés.','Galerie d''appréciation mutuelle : accrochage temporaire des frottages superposés. Visite libre avec commentaires positifs encouragés. Identification collective des effets de superposition réussis : contrastes saisissants, harmonies douces, effets surprise. Chaque élève choisit son détail préféré sur l''œuvre d''un pair.','Transformer le concept de frottages créatifs:; Explorer les techniques artistiques appropriées; Développer la créativité par l''exploration guidée',NULL,NULL,NULL,'formative','{"observable":["L''élève explore les matériaux artistiques avec curiosité","L''élève explique ses choix artistiques en français simple","L''élève respecte les matériaux et l''espace de travail","L''élève apprécie les créations artistiques des autres"],"checkpoints":["Utilise les techniques artistiques démontrées","Exprime ses idées par l''art visuel","Utilise le vocabulaire artistique approprié","Montre fierté dans ses créations artistiques"]}',1,'Plan détaillé avec supports visuels',1756911653356,1757594653887,1,'fr','Arts visuels','{"pourDifficultés":["Proposer des supports audio pour accompagner le texte écrit","Permettre les réponses gestuelles avant la production orale","Encourager l''utilisation de manipulatifs (lettres magnétiques, etc.)"],"pourAvancés":["Permettre l''exploration de différents genres littéraires (poésie, théâtre)","Encourager la création d''histoires originales avec début, milieu, fin","Proposer des textes plus complexes avec vocabulaire étendu"],"pourLangue":["Encourager le jumelage avec un pair plus fort en français","Créer des liens avec des mots similaires dans la langue première","Offrir des gestes et actions pour accompagner les mots nouveaux"],"pourPEI":["Offrir des pauses sensorielles fréquentes selon les besoins","Fournir des instructions simples, une étape à la fois","Utiliser des minuteurs visuels pour structurer le temps"]}','{"vocabulary":["superposition","composition","contraste"],"visualSupports":["Exemples de superpositions réussies, vocabulaire contraste/harmonie illustré","Exemples d''étapes en cours d''exécution, palette de couleurs conseillées pour superposition","Galerie organisée avec éclairage valorisant, cartes de vocabulaire appréciatif"],"movementBreaks":["Danse de superposition : mouvements de couches qui se superposent harmonieusement","Pause créative : étirements en admirant les œuvres en cours depuis différents angles","Applaudissements texturés : applaudir avec différentes nuances selon les œuvres"]}',NULL,NULL,NULL,NULL,'{"questions":["Les élèves ont-ils atteint les objectifs?","Quelles adaptations étaient nécessaires?","Que ferais-je différemment la prochaine fois?"]}',NULL,'',4,4,'core',1);
INSERT INTO ETFOLessonPlan VALUES('cmf43u3u40097vj9tm3fa4l3p',23,'Matériaux naturels: Découverte et collection','cmf43u3u0008xvj9tsg5gcs5s',1767888000000,45,'Cercle de découverte avec boîte mystère contenant des trésors naturels (feuilles, écorce, cailloux, branches). Les élèves explorent en touchant et décrivent en français. Discussion sur les différences entre matériaux naturels et fabriqués par l''humain.','Sortie d''exploration dans la cour d''école ou le parc adjacent. Par équipes de 3, les élèves collectent différentes textures naturelles en respectant les règles (ne pas arracher de plantes vivantes, prendre seulement ce qui est tombé). Création d''un ''passeport de textures naturelles'' avec dessins et échantillons collés. Classification par texture : rugueux, lisse, doux, piquant.','Exposition des collections sur les tables. Chaque équipe présente sa trouvaille la plus intéressante en expliquant sa texture en français. Création d''une banque collective de matériaux naturels pour les prochaines activités artistiques. Discussion sur le respect de la nature.','Représenter le concept de matériaux naturels:; Créer les techniques artistiques appropriées; Développer l''expression artistique par l''expression créative','["Boîte mystère","Trésors naturels variés (feuilles, écorce, pierres lisses, branches, pommes de pin)","Cartes visuelles nature/artificiel","Sacs de collection","Carnets de terrain","Crayons","Loupes","Colle","Étiquettes","Règles de collecte illustrées","Collections créées","Passeports complétés","Bacs de rangement pour banque collective"]',NULL,'Matériaux naturels: Découverte et collection','Cercle de découverte avec boîte mystère contenant des trésors naturels (feuilles, écorce, cailloux, branches). Les élèves explorent en touchant et décrivent en français. Discussion sur les différences entre matériaux naturels et fabriqués par l''humain.','Sortie d''exploration dans la cour d''école ou le parc adjacent. Par équipes de 3, les élèves collectent différentes textures naturelles en respectant les règles (ne pas arracher de plantes vivantes, prendre seulement ce qui est tombé). Création d''un ''passeport de textures naturelles'' avec dessins et échantillons collés. Classification par texture : rugueux, lisse, doux, piquant.','Exposition des collections sur les tables. Chaque équipe présente sa trouvaille la plus intéressante en expliquant sa texture en français. Création d''une banque collective de matériaux naturels pour les prochaines activités artistiques. Discussion sur le respect de la nature.','Représenter le concept de matériaux naturels:; Créer les techniques artistiques appropriées; Développer l''expression artistique par l''expression créative',NULL,NULL,NULL,'formative','{"observable":["Identifie matériaux naturels vs artificiels","Décrit textures en français simple","Respecte règles de collecte","Participe activement à l''exploration"],"checkpoints":["Observation pendant la collecte extérieure","Qualité des descriptions dans le passeport","Participation aux présentations"]}',1,'Plan détaillé avec supports visuels',1756911653357,1757594653888,1,'fr','Arts visuels','{"pourDifficultés":["Collection guidée avec aide directe","Seulement 3 textures de base à identifier","Support visuel constant"],"pourAvancés":["Recherche de textures complexes ou rares","Documentation scientifique détaillée","Animation de la présentation pour les pairs"],"pourLangue":["Vocabulaire illustré avec gestes","Focus sur l''exploration sensorielle","Expression par le dessin encouragée"],"pourPEI":["Adaptation selon sensibilités sensorielles","Zone de collecte réduite si nécessaire","Support individuel pour manipulation"]}','{"vocabulary":["naturel","collecter","respectueux"],"visualSupports":["Tableau de classification nature vs artificiel avec images claires","Guide visuel des bonnes pratiques de collecte, carte de la zone d''exploration","Galerie temporaire des découvertes, affiche des règles de respect de la nature"],"movementBreaks":["Mouvement nature : imiter la croissance d''un arbre (racines, tronc, branches)","Pause exploration : étirements comme les branches dans le vent","Remerciement à la nature : geste de gratitude avec les mains vers le cœur"]}',NULL,NULL,NULL,NULL,'{"questions":["Les élèves ont-ils atteint les objectifs?","Quelles adaptations étaient nécessaires?","Que ferais-je différemment la prochaine fois?"]}',NULL,'',4,5,'core',1);
INSERT INTO ETFOLessonPlan VALUES('cmf43u3u50099vj9thhcu0i3d',23,'Art avec la nature: Créations éphémères','cmf43u3u0008xvj9tsg5gcs5s',1767974400000,45,'Découverte du concept d''art éphémère avec photos d''Andy Goldsworthy et d''autres artistes du land art. Explication que certaines œuvres d''art sont temporaires et changent avec le temps. Les élèves observent leurs collections de matériaux naturels de la leçon précédente et imaginent des arrangements possibles.','Création d''arrangements artistiques éphémères à l''extérieur ou dans un espace dédié. Les élèves travaillent par équipes de 2-3 pour créer des mandalas, spirales, ou autres formes avec leurs matériaux naturels. Accent sur l''harmonie des couleurs, textures et formes. Documentation photographique de chaque étape et du résultat final. Observation des changements si vent ou autre élément naturel interagit.','Galerie éphémère : chaque équipe présente son œuvre en expliquant les choix de matériaux et de formes. Photos projetées pour que tous puissent apprécier les détails. Discussion sur les sentiments ressentis en créant quelque chose de temporaire. Laisser les œuvres dehors pour observer l''évolution naturelle lors de la prochaine visite.','Créer le concept de art avec; Créer les techniques artistiques appropriées; Développer l''expression artistique par la création personnelle','["Photos d''art éphémère","Collections de matériaux naturels de la leçon 5","Loupe","Appareils photo ou tablettes","Matériaux naturels collectés","Bâches ou supports temporaires","Appareils photo/tablettes","Carnet d''artiste","Minuterie pour rotations","Photos des créations","Écran ou mur de projection","Carnets d''artiste"]',NULL,'Art avec la nature: Créations éphémères','Découverte du concept d''art éphémère avec photos d''Andy Goldsworthy et d''autres artistes du land art. Explication que certaines œuvres d''art sont temporaires et changent avec le temps. Les élèves observent leurs collections de matériaux naturels de la leçon précédente et imaginent des arrangements possibles.','Création d''arrangements artistiques éphémères à l''extérieur ou dans un espace dédié. Les élèves travaillent par équipes de 2-3 pour créer des mandalas, spirales, ou autres formes avec leurs matériaux naturels. Accent sur l''harmonie des couleurs, textures et formes. Documentation photographique de chaque étape et du résultat final. Observation des changements si vent ou autre élément naturel interagit.','Galerie éphémère : chaque équipe présente son œuvre en expliquant les choix de matériaux et de formes. Photos projetées pour que tous puissent apprécier les détails. Discussion sur les sentiments ressentis en créant quelque chose de temporaire. Laisser les œuvres dehors pour observer l''évolution naturelle lors de la prochaine visite.','Créer le concept de art avec; Créer les techniques artistiques appropriées; Développer l''expression artistique par la création personnelle',NULL,NULL,NULL,'formative','{"observable":["Crée des arrangements esthétiques","Utilise variété de matériaux naturels","Comprend le concept d''art temporaire","Documente son processus créatif"],"checkpoints":["Qualité de l''arrangement créé","Collaboration dans l''équipe","Réaction face au caractère éphémère"]}',1,'Plan détaillé avec supports visuels',1756911653358,1757594653889,1,'fr','Arts visuels','{"pourDifficultés":["Arrangements très simples (lignes, cercles)","Travail avec partenaire expérimenté","Focus sur l''expérience plutôt que le résultat"],"pourAvancés":["Création de motifs complexes","Intégration d''éléments environnementaux","Documentation détaillée du processus"],"pourLangue":["Expression principalement visuelle","Vocabulaire de base avec gestes","Partage par montrer plutôt que parler"],"pourPEI":["Matériaux adaptés aux capacités motrices","Temps flexible","Support émotionnel si attachement difficile"]}','{"vocabulary":["éphémère","temporaire","arrangement"],"visualSupports":["Galerie d''images d''art éphémère, vocabulaire illustré temporaire/permanent","Exemples de formes géométriques simples, guide de composition","Galerie photo numérique des créations, certificats de ''créateur d''art éphémère''"],"movementBreaks":["Imitation des cycles naturels : grandir, fleurir, faner, renaître","Pause créative : mouvements lents et harmonieux comme disposer délicatement des matériaux","Respiration d''acceptation : inspirer la création, expirer le détachement"]}',NULL,NULL,NULL,NULL,'{"questions":["Les élèves ont-ils atteint les objectifs?","Quelles adaptations étaient nécessaires?","Que ferais-je différemment la prochaine fois?"]}',NULL,'',4,6,'core',1);
INSERT INTO ETFOLessonPlan VALUES('cmf43u3u6009bvj9tfw7rokbe',23,'Introduction au collage: Techniques de base','cmf43u3u0008xvj9tsg5gcs5s',1768233600000,45,'Démonstration des techniques de base du collage avec différents adhésifs (bâton de colle, colle liquide, ruban adhésif). Les élèves explorent une sélection de papiers aux textures variées (lisse, rugueux, brillant, mat) et apprennent à les déchirer vs les couper pour différents effets.','Création d''un collage libre sur le thème ''Mon jardin de textures''. Les élèves choisissent un support et composent en superposant papiers de différentes textures pour représenter un jardin imaginaire. Expérimentation avec transparence (papier calque), contraste (lisse vs rugueux) et harmonie des couleurs. Introduction de la technique du frottage sur certains papiers avant collage.','Galerie des jardins de textures : accrochage temporaire des œuvres et visite guidée par les artistes. Chaque élève présente une texture préférée de son jardin et explique pourquoi. Introduction du vocabulaire critique simple : ''J''aime parce que...'' Discussion sur les découvertes techniques.','Dessiner le concept de introduction au; Créer les techniques artistiques appropriées; Développer l''expression artistique par l''expression créative','["Variété de papiers texturés","Bâtons de colle","Colle liquide avec pinceaux","Ciseaux à bout rond","Supports cartonnés","Chiffons humides","Papiers variés (journal, magazine, papier de soie, papier sableux, papier métallisé)","Supports A4 cartonnés","Adhésifs variés","Crayons cire pour frottage","Objets texturés pour frottage","Œuvres créées","Système d''accrochage temporaire","Cartons d''identification"]',NULL,'Introduction au collage: Techniques de base','Démonstration des techniques de base du collage avec différents adhésifs (bâton de colle, colle liquide, ruban adhésif). Les élèves explorent une sélection de papiers aux textures variées (lisse, rugueux, brillant, mat) et apprennent à les déchirer vs les couper pour différents effets.','Création d''un collage libre sur le thème ''Mon jardin de textures''. Les élèves choisissent un support et composent en superposant papiers de différentes textures pour représenter un jardin imaginaire. Expérimentation avec transparence (papier calque), contraste (lisse vs rugueux) et harmonie des couleurs. Introduction de la technique du frottage sur certains papiers avant collage.','Galerie des jardins de textures : accrochage temporaire des œuvres et visite guidée par les artistes. Chaque élève présente une texture préférée de son jardin et explique pourquoi. Introduction du vocabulaire critique simple : ''J''aime parce que...'' Discussion sur les découvertes techniques.','Dessiner le concept de introduction au; Créer les techniques artistiques appropriées; Développer l''expression artistique par l''expression créative',NULL,NULL,NULL,'formative','{"observable":["Utilise techniques de base du collage","Combine différentes textures harmonieusement","Fait des choix artistiques réfléchis","Prend soin du matériel"],"checkpoints":["Maîtrise technique pendant création","Qualité esthétique de l''œuvre","Participation à la discussion critique"]}',1,'Plan détaillé avec supports visuels',1756911653358,1757594653890,1,'fr','Arts visuels','{"pourDifficultés":["Pré-découpe de formes de base","Support avec guide visuel léger","Choix limité de matériaux pour éviter surcharge"],"pourAvancés":["Techniques avancées (superposition complexe, frottage multiple)","Rôle de mentor pour pairs","Exploration de nouvelles combinaisons"],"pourLangue":["Focus sur création visuelle","Vocabulaire tactile avec gestes","Expression non-verbale encouragée"],"pourPEI":["Outils adaptés (gros pinceaux, prises faciles)","Espace de travail organisé","Pauses fréquentes"]}','{"vocabulary":["collage","adhésif","support"],"visualSupports":["Exemples de collages célèbres adaptés à l''âge, démonstration des techniques","Exemples de jardins de textures, palette de combinaisons harmonieuses","Espace galerie organisé, cartes de vocabulaire critique"],"movementBreaks":["Gestes de l''artiste : mouvements de déchirure délicate et de collage précis","Danse du collage : mouvements de déplacement et de superposition avec le corps","Applaudissements texturés : applaudir avec différentes intensités selon les œuvres"]}',NULL,NULL,NULL,NULL,'{"questions":["Les élèves ont-ils atteint les objectifs?","Quelles adaptations étaient nécessaires?","Que ferais-je différemment la prochaine fois?"]}',NULL,'',4,7,'core',1);
INSERT INTO ETFOLessonPlan VALUES('cmf43u3u7009dvj9t47i2r4vx',23,'Collage texturé: Intégration des matériaux','cmf43u3u0008xvj9tsg5gcs5s',1768320000000,45,'Révision des collages de la leçon précédente et découverte d''œuvres d''artistes utilisant matériaux mixtes (Kurt Schwitters, Robert Rauschenberg adapté ). Introduction du concept de technique mixte : papier + matériaux naturels. Les élèves observent leurs matériaux naturels et imaginent comment les intégrer artistiquement.','Création de collages techniques mixtes sur le thème ''Portraits de la nature''. Les élèves combinent papiers de différentes textures avec leurs matériaux naturels pour créer des visages ou silhouettes abstraites. Techniques enseignées : fixation d''éléments 3D avec colle forte, création de reliefs, jeu entre mat et brillant. Rotation entre 4 stations de matériaux.','Exposition ''Portraits nature'' avec mise en scène dramatique (lumière tamisée). Chaque artiste présente son portrait en décrivant le ''caractère'' qu''il a voulu donner avec les matériaux choisis. Introduction du vocabulaire émotionnel lié aux textures : doux = calme, rugueux = fort, etc.','Peindre le concept de collage texturé:; Créer les techniques artistiques appropriées; Développer l''expression artistique par l''expression créative','["Collages de la leçon 7","Exemples d''œuvres mixtes","Matériaux naturels conservés","Loupe pour observation détaillée","Papiers variés","Matériaux naturels sélectionnés","Colle forte adaptée","Pinces à linge pour séchage","Plateaux par station","Supports rigides","Œuvres séchées","Éclairage d''ambiance","Cartes vocabulaire émotionnel"]',NULL,'Collage texturé: Intégration des matériaux','Révision des collages de la leçon précédente et découverte d''œuvres d''artistes utilisant matériaux mixtes (Kurt Schwitters, Robert Rauschenberg adapté ). Introduction du concept de technique mixte : papier + matériaux naturels. Les élèves observent leurs matériaux naturels et imaginent comment les intégrer artistiquement.','Création de collages techniques mixtes sur le thème ''Portraits de la nature''. Les élèves combinent papiers de différentes textures avec leurs matériaux naturels pour créer des visages ou silhouettes abstraites. Techniques enseignées : fixation d''éléments 3D avec colle forte, création de reliefs, jeu entre mat et brillant. Rotation entre 4 stations de matériaux.','Exposition ''Portraits nature'' avec mise en scène dramatique (lumière tamisée). Chaque artiste présente son portrait en décrivant le ''caractère'' qu''il a voulu donner avec les matériaux choisis. Introduction du vocabulaire émotionnel lié aux textures : doux = calme, rugueux = fort, etc.','Peindre le concept de collage texturé:; Créer les techniques artistiques appropriées; Développer l''expression artistique par l''expression créative',NULL,NULL,NULL,'formative','{"observable":["Intègre harmonieusement matériaux mixtes","Utilise techniques de fixation appropriées","Exprime des idées par les textures","Respecte temps de rotation"],"checkpoints":["Réussite technique des assemblages","Originalité dans combinaisons","Expression du ''caractère'' de l''œuvre"]}',1,'Plan détaillé avec supports visuels',1756911653359,1757594653891,1,'fr','Arts visuels','{"pourDifficultés":["Matériaux pré-fixés partiellement","Choix simplifié de 2 matériaux naturels","Support avec guide léger"],"pourAvancés":["Défi multi-textures complexes","Création de reliefs prononcés","Aide technique aux pairs"],"pourLangue":["Communication par gestes et montrer","Focus sur ressenti tactile","Vocabulaire émotionnel avec images"],"pourPEI":["Outils de manipulation adaptés","Espace de séchage personnalisé","Temps supplémentaire selon besoin"]}','{"vocabulary":["intégrer","combiner","mixte"],"visualSupports":["Galerie d''œuvres mixtes, schéma visuel papier + nature","4 stations thématiques (feuilles, pierres, textures, couleurs), guides techniques","Mise en scène galerie, association texture-émotion illustrée"],"movementBreaks":["Danse de l''intégration : mouvements qui mélangent et unifient","Rotation-danse : mouvement fluide entre stations au son de la nature","Salut d''artiste : révérence théâtrale pour célébrer les créations"]}',NULL,NULL,NULL,NULL,'{"questions":["Les élèves ont-ils atteint les objectifs?","Quelles adaptations étaient nécessaires?","Que ferais-je différemment la prochaine fois?"]}',NULL,'',4,8,'core',1);
INSERT INTO ETFOLessonPlan VALUES('cmf43u3u8009fvj9tmsn07e00',23,'Palette de textures: Organisation et présentation','cmf43u3u0008xvj9tsg5gcs5s',1768406400000,45,'Découverte du concept de portfolio d''artiste avec exemples de portfolios simples. Discussion sur l''importance de garder des traces de ses découvertes artistiques. Les élèves rassemblent toutes leurs créations texturées : frottages, collages, photos d''art éphémère, matériaux collectés.','Création d''un portfolio ''Mon parcours des textures''. Les élèves organisent chronologiquement leurs découvertes avec pages dédiées : ''Mes premières textures'', ''Mes trouvailles naturelles'', ''Mes frottages'', ''Mes collages'', ''Mon art éphémère''. Chaque section include œuvres, photos, et une phrase de réflexion dictée à l''adulte. Décoration personnalisée de la couverture.','Vernissage des portfolios : présentation solennelle où chaque élève montre sa page préférée. Signature collective d''un ''livre d''or'' de l''unité. Remise de certificats ''Explorateur de textures diplômé''. Discussion sur ce qu''ils aimeraient découvrir ensuite en art.','Modeler les textures variées; Présenter les techniques artistiques appropriées; Développer la motricité fine par le partage des apprentissages','["Exemples de portfolios adaptés à l''âge","Toutes créations de l''unité","Chemises ou cartables","Photos imprimées des créations éphémères","Cartables ou chemises épaisses","Feuilles de séparation","Toutes créations accumulées","Matériaux de décoration","Plastification pour protection","Portfolios complétés","Livre d''or collectif","Certificats personnalisés","Espace vernissage aménagé"]',NULL,'Palette de textures: Organisation et présentation','Découverte du concept de portfolio d''artiste avec exemples de portfolios simples. Discussion sur l''importance de garder des traces de ses découvertes artistiques. Les élèves rassemblent toutes leurs créations texturées : frottages, collages, photos d''art éphémère, matériaux collectés.','Création d''un portfolio ''Mon parcours des textures''. Les élèves organisent chronologiquement leurs découvertes avec pages dédiées : ''Mes premières textures'', ''Mes trouvailles naturelles'', ''Mes frottages'', ''Mes collages'', ''Mon art éphémère''. Chaque section include œuvres, photos, et une phrase de réflexion dictée à l''adulte. Décoration personnalisée de la couverture.','Vernissage des portfolios : présentation solennelle où chaque élève montre sa page préférée. Signature collective d''un ''livre d''or'' de l''unité. Remise de certificats ''Explorateur de textures diplômé''. Discussion sur ce qu''ils aimeraient découvrir ensuite en art.','Modeler les textures variées; Présenter les techniques artistiques appropriées; Développer la motricité fine par le partage des apprentissages',NULL,NULL,NULL,'formative','{"observable":["Organise portfolio de manière cohérente","Sélectionne œuvres représentatives","Exprime réflexions sur son parcours","Présente son travail avec fierté"],"checkpoints":["Complétude et organisation du portfolio","Qualité des réflexions partagées","Engagement dans le processus de documentation"]}',1,'Plan détaillé avec supports visuels',1756911653360,1757594653892,1,'fr','Arts visuels','{"pourDifficultés":["Organisation simplifiée en 3 sections max","Aide pour placement et colle","Réflexions très courtes"],"pourAvancés":["Sections supplémentaires personnelles","Réflexions détaillées auto-dictées","Aide à l''organisation des pairs"],"pourLangue":["Réflexions avec dessins/gestes","Organisation par images plutôt que mots","Partage visuel du portfolio"],"pourPEI":["Portfolio adapté aux capacités motrices","Aide technique pour organisation","Objectifs ajustés selon besoins"]}','{"vocabulary":["portfolio","organiser","présenter"],"visualSupports":["Portfolios d''artistes simplifiés, exemples d''organisation claire","Modèle de pages types, exemples de réflexions adaptées à l''âge","Espace galerie solennel, certificats artistiques"],"movementBreaks":["Danse de l''archiviste : mouvements de tri et classement délicats","Pause portfolio : feuilleter délicatement comme un livre précieux","Applaudissements de vernissage : applaudissements sophistiqués d''exposition"]}',NULL,NULL,NULL,NULL,'{"questions":["Les élèves ont-ils atteint les objectifs?","Quelles adaptations étaient nécessaires?","Que ferais-je différemment la prochaine fois?"]}',NULL,'',4,9,'core',1);
INSERT INTO ETFOLessonPlan VALUES('cmf43u3u8009hvj9t011tl6ol',23,'Projet personnel: Planification','cmf43u3u0008xvj9tsg5gcs5s',1768492800000,45,'Introduction au concept de projet artistique personnel avec exemples adaptés (construire une cabane, faire un gâteau, planter un jardin). Discussion sur l''importance de planifier avant de créer. Les élèves consultent leurs portfolios pour s''inspirer de leurs découvertes préférées. Brainstorm collectif d''idées de projets utilisant textures.','Création d''un plan de projet individuel avec fiche de planification illustrée. Les élèves choisissent leur projet, dessinent leur idée, sélectionnent 3-5 matériaux/textures de leur portfolio, anticipent les étapes (découper, coller, décorer). Consultation individuelle avec l''enseignant pour valider faisabilité. Préparation de la ''commande'' de matériaux nécessaires.','Partage des plans de projet par binômes. Chaque élève explique son idée et les matériaux choisis. Les pairs posent une question ou donnent une idée constructive. Vérification collective des listes de matériaux et préparation pour la réalisation. Signature solennelle du ''contrat d''artiste'' avec son projet.','Transformer le concept de projet personnel:; Réaliser les techniques artistiques appropriées; Développer la motricité fine par la création personnelle','["Portfolios de la leçon précédente","Exemples de projets simples","Tableau pour brainstorm","Images inspirantes de créations texturées","Fiches de planification illustrées","Crayons et crayons de couleur","Portfolios personnels","Catalogs de matériaux disponibles","Listes de vérification simples","Plans de projet complétés","Contrats d''artiste pré-imprimés","Matériaux pour vérification"]',NULL,'Projet personnel: Planification','Introduction au concept de projet artistique personnel avec exemples adaptés (construire une cabane, faire un gâteau, planter un jardin). Discussion sur l''importance de planifier avant de créer. Les élèves consultent leurs portfolios pour s''inspirer de leurs découvertes préférées. Brainstorm collectif d''idées de projets utilisant textures.','Création d''un plan de projet individuel avec fiche de planification illustrée. Les élèves choisissent leur projet, dessinent leur idée, sélectionnent 3-5 matériaux/textures de leur portfolio, anticipent les étapes (découper, coller, décorer). Consultation individuelle avec l''enseignant pour valider faisabilité. Préparation de la ''commande'' de matériaux nécessaires.','Partage des plans de projet par binômes. Chaque élève explique son idée et les matériaux choisis. Les pairs posent une question ou donnent une idée constructive. Vérification collective des listes de matériaux et préparation pour la réalisation. Signature solennelle du ''contrat d''artiste'' avec son projet.','Transformer le concept de projet personnel:; Réaliser les techniques artistiques appropriées; Développer la motricité fine par la création personnelle',NULL,NULL,NULL,'formative','{"observable":["Élabore un plan réalisable","Sélectionne matériaux appropriés","Anticipe les étapes principales","Communique son idée clairement"],"checkpoints":["Qualité et faisabilité du plan créé","Pertinence des matériaux choisis","Engagement dans le processus de planification"]}',1,'Plan détaillé avec supports visuels',1756911653361,1757594653894,1,'fr','Arts visuels','{"pourDifficultés":["Choix pré-sélectionnés de 3 projets simples","Fiche de planification simplifiée","Consultation approfondie avec enseignant"],"pourAvancés":["Projets plus complexes multi-étapes","Planification détaillée avec timing","Rôle de mentor pour pairs"],"pourLangue":["Planification principalement visuelle","Support gestuel pour explication","Utilisation du portfolio comme référence"],"pourPEI":["Projets adaptés aux capacités motrices","Planification avec support individuel","Objectifs ajustés selon besoins"]}','{"vocabulary":["planifier","projet","personnel"],"visualSupports":["Galerie d''inspiration, schéma simple des étapes de projet","Modèles de fiches complétées, galerie d''étapes visuelles","Galerie temporaire des plans, contrat d''artiste officiel"],"movementBreaks":["Gestes de planification : mouvements de réflexion et d''organisation dans l''espace","Pause créative : mouvements d''artiste qui visualise son œuvre future","Signature cérémonielle : geste solennel de l''engagement artistique"]}',NULL,NULL,NULL,NULL,'{"questions":["Les élèves ont-ils atteint les objectifs?","Quelles adaptations étaient nécessaires?","Que ferais-je différemment la prochaine fois?"]}',NULL,'',4,10,'core',1);
INSERT INTO ETFOLessonPlan VALUES('cmf43u3u9009jvj9tkud2uxm0',23,'Projet personnel: Création (Partie 1)','cmf43u3u0008xvj9tsg5gcs5s',1768579200000,45,'Rappel des projets planifiés avec consultation des plans individuels. Mise en place des espaces de travail personnalisés selon les projets. Distribution des matériaux demandés. Rituel de début d''atelier : ''Aujourd''hui je suis un artiste qui crée''. Échanges sur l''excitation et l''anxiété de commencer.','Travail individuel guidé sur les projets personnels. Les élèves commencent par préparer leur support, puis appliquent leur première étape (souvent coller/placer les éléments principaux). Circulation de l''enseignant pour encouragement et conseils techniques. Mini-consultations de 2 minutes par élève. Partage spontané de découvertes entre pairs. Documentation photo du processus.','Galerie d''avancement : chaque élève montre brièvement où il en est sans jugement de complétude. Focus sur ''ce que j''ai découvert aujourd''hui'' plutôt que sur ce qui reste à faire. Planification de ce qui sera fait dans la partie 2. Rangement soigneux des projets en cours avec étiquettes nom.','Représenter le concept de projet personnel:; Réaliser les techniques artistiques appropriées; Développer la motricité fine par la création personnelle','["Plans de projets individuels","Tous matériaux demandés","Espaces de travail organisés","Portfolios pour inspiration","Matériaux individuels sélectionnés","Outils de base (colle, ciseaux, pinceaux)","Supports variés","Appareils photo pour documentation","Chiffons et nettoyage","Œuvres en cours","Espace de séchage/conservation sécurisé","Étiquettes d''identification","Carnets pour notes"]',NULL,'Projet personnel: Création (Partie 1)','Rappel des projets planifiés avec consultation des plans individuels. Mise en place des espaces de travail personnalisés selon les projets. Distribution des matériaux demandés. Rituel de début d''atelier : ''Aujourd''hui je suis un artiste qui crée''. Échanges sur l''excitation et l''anxiété de commencer.','Travail individuel guidé sur les projets personnels. Les élèves commencent par préparer leur support, puis appliquent leur première étape (souvent coller/placer les éléments principaux). Circulation de l''enseignant pour encouragement et conseils techniques. Mini-consultations de 2 minutes par élève. Partage spontané de découvertes entre pairs. Documentation photo du processus.','Galerie d''avancement : chaque élève montre brièvement où il en est sans jugement de complétude. Focus sur ''ce que j''ai découvert aujourd''hui'' plutôt que sur ce qui reste à faire. Planification de ce qui sera fait dans la partie 2. Rangement soigneux des projets en cours avec étiquettes nom.','Représenter le concept de projet personnel:; Réaliser les techniques artistiques appropriées; Développer la motricité fine par la création personnelle',NULL,NULL,NULL,'formative','{"observable":["Suit son plan avec flexibilité","Utilise techniques apprises appropriement","Persévère face aux défis","Demande aide au besoin"],"checkpoints":["Progression vers objectif personnel","Application des techniques texturées","Autonomie et engagement dans le processus"]}',1,'Plan détaillé avec supports visuels',1756911653362,1757594653895,1,'fr','Arts visuels','{"pourDifficultés":["Supervision étroite et encouragement constant","Simplification des étapes si nécessaire","Collaboration avec pair aidant"],"pourAvancés":["Défis techniques supplémentaires","Rôle de mentor discret","Exploration de variations créatives"],"pourLangue":["Communication gestuelle et visuelle","Modélisation plutôt qu''explications verbales","Encouragement par sourires et approbation"],"pourPEI":["Adaptations techniques selon besoins","Rythme personnalisé","Outils et supports adaptés"]}','{"vocabulary":["réalisation","autonome","persévérer","défis","ajustements"],"visualSupports":["Ateliers aménagés selon projets, rappel des techniques apprises","Rappel des techniques disponibles, galerie des étapes en cours","Espace d''exposition temporaire des progrès, planning de la suite"],"movementBreaks":["Réchauffement d''artiste : préparation des mains et de l''esprit créatif","Pause créative : étirements en observant son œuvre sous différents angles","Relaxation post-création : mouvements de satisfaction et anticipation"]}',NULL,NULL,NULL,NULL,'{"questions":["Les élèves ont-ils atteint les objectifs?","Quelles adaptations étaient nécessaires?","Que ferais-je différemment la prochaine fois?"]}',NULL,'',4,11,'core',1);
INSERT INTO ETFOLessonPlan VALUES('cmf43u3ua009lvj9tqha2xwrs',23,'Projet personnel: Création (Partie 2)','cmf43u3u0008xvj9tsg5gcs5s',1768838400000,45,'Retrouvailles avec projets et évaluation du travail à compléter. Introduction au concept de ''regard critique constructif'' : observer ce qui fonctionne bien et ce qui pourrait être amélioré. Modélisation avec une œuvre de l''enseignant. Établissement d''objectifs de finition réalistes pour chaque élève.','Travail de finition guidé avec pauses réflexives. Les élèves appliquent améliorations identifiées : ajout de détails, renforcement de textures, harmonisation des couleurs. À mi-parcours, échange critique constructive en binômes avec structure : ''Ce que j''aime'' + ''Une idée pour embellir encore''. Finalisation avec attention aux détails. Préparation de l''exposition avec titres et descriptions.','Cérémonie de finalisation : signature solennelle des œuvres complétées. Chaque artiste présente en 30 secondes son œuvre finalisée avec fierté. Installation de l''exposition pour le lendemain. Cercle de gratitude pour le parcours accompli ensemble. Anticipation joyeuse du partage avec familles.','Créer le concept de projet personnel:; Réaliser les techniques artistiques appropriées; Développer la motricité fine par la création personnelle','["Projets en cours","Œuvre exemple de l''enseignant","Grille d''évaluation simplifiée","Matériaux de finition","Matériaux de finition variés","Grilles d''échange entre pairs","Cartons pour titres","Feutres pour descriptions","Outils de précision","Œuvres finalisées","Système d''exposition","Programme de l''exposition","Invitations pour familles"]',NULL,'Projet personnel: Création (Partie 2)','Retrouvailles avec projets et évaluation du travail à compléter. Introduction au concept de ''regard critique constructif'' : observer ce qui fonctionne bien et ce qui pourrait être amélioré. Modélisation avec une œuvre de l''enseignant. Établissement d''objectifs de finition réalistes pour chaque élève.','Travail de finition guidé avec pauses réflexives. Les élèves appliquent améliorations identifiées : ajout de détails, renforcement de textures, harmonisation des couleurs. À mi-parcours, échange critique constructive en binômes avec structure : ''Ce que j''aime'' + ''Une idée pour embellir encore''. Finalisation avec attention aux détails. Préparation de l''exposition avec titres et descriptions.','Cérémonie de finalisation : signature solennelle des œuvres complétées. Chaque artiste présente en 30 secondes son œuvre finalisée avec fierté. Installation de l''exposition pour le lendemain. Cercle de gratitude pour le parcours accompli ensemble. Anticipation joyeuse du partage avec familles.','Créer le concept de projet personnel:; Réaliser les techniques artistiques appropriées; Développer la motricité fine par la création personnelle',NULL,NULL,NULL,'formative','{"observable":["Améliore son œuvre avec discernement","Participe à échanges critiques constructifs","Persiste jusqu''à satisfaction personnelle","Prépare présentation soignée"],"checkpoints":["Qualité des améliorations apportées","Pertinence des échanges critiques","Fierté et satisfaction exprimées"]}',1,'Plan détaillé avec supports visuels',1756911653362,1757594653896,1,'fr','Arts visuels','{"pourDifficultés":["Évaluation très positive focusée sur réussites","Finitions simples et réalisables","Support constant pour maintenir confiance"],"pourAvancés":["Défis techniques avancés de finition","Rôle de critique constructif expert","Aide à l''installation d''exposition"],"pourLangue":["Évaluation principalement visuelle et gestuelle","Expression de satisfaction non-verbale","Participation à l''exposition par présence"],"pourPEI":["Critères d''aboutissement personnalisés","Outils adaptés pour finitions","Reconnaissance individuelle de l''effort"]}','{"vocabulary":["finaliser","finition","évaluer","critique","constructif"],"visualSupports":["Modèle de critique constructive, exemples avant/après finition","Structure d''échange positive, exemples de descriptions d''œuvres","Espace d''exposition prêt, galerie des œuvres abouties"],"movementBreaks":["Gestes d''évaluation : observer avec les yeux, toucher délicatement, réfléchir","Pause perspective : reculer et observer son œuvre comme un visiteur de musée","Applaudissements d''aboutissement : reconnaissance collective du travail accompli"]}',NULL,NULL,NULL,NULL,'{"questions":["Les élèves ont-ils atteint les objectifs?","Quelles adaptations étaient nécessaires?","Que ferais-je différemment la prochaine fois?"]}',NULL,'',4,12,'core',1);
INSERT INTO ETFOLessonPlan VALUES('cmf43u3ub009nvj9tsvkc7y85',23,'Présentation et partage','cmf43u3u0008xvj9tsg5gcs5s',1768924800000,45,'Préparation de l''exposition et accueil des invités (parents, autres classes). Installation finale des œuvres avec vérification des cartons d''identification. Les élèves-artistes se préparent mentalement et pratiquent leurs présentations. Discussion sur le courage et la beauté du partage artistique.','Vernissage officiel avec visite guidée par les jeunes artistes. Chaque élève présente son œuvre aux invités en expliquant : titre choisi, matériaux utilisés, ce qu''il a voulu exprimer. Temps libre pour admiration et questions du public. Circulation libre avec élèves comme guides. Livre d''or pour commentaires des visiteurs. Photos souvenirs officielles.','Cérémonie de clôture après départ des invités. Lecture de commentaires du livre d''or. Chaque élève partage en un mot son sentiment sur cette expérience. Remise solennelle de certificats ''Artiste explorateur de textures''. Projection vers les prochaines aventures artistiques. Applaudissements finaux.','Dessiner le concept de présentation et; Présenter les techniques artistiques appropriées; Développer le sens esthétique par le partage des apprentissages','["Œuvres prêtes à exposer","Cartons d''identification","Espace d''exposition organisé","Badges ou écharpes ''artiste''","Œuvres installées","Livre d''or et stylos","Appareils photo","Espace circulation organisé","Collations simples optionnelles","Livre d''or avec commentaires","Certificats personnalisés","Espace cercle de clôture"]',NULL,'Présentation et partage','Préparation de l''exposition et accueil des invités (parents, autres classes). Installation finale des œuvres avec vérification des cartons d''identification. Les élèves-artistes se préparent mentalement et pratiquent leurs présentations. Discussion sur le courage et la beauté du partage artistique.','Vernissage officiel avec visite guidée par les jeunes artistes. Chaque élève présente son œuvre aux invités en expliquant : titre choisi, matériaux utilisés, ce qu''il a voulu exprimer. Temps libre pour admiration et questions du public. Circulation libre avec élèves comme guides. Livre d''or pour commentaires des visiteurs. Photos souvenirs officielles.','Cérémonie de clôture après départ des invités. Lecture de commentaires du livre d''or. Chaque élève partage en un mot son sentiment sur cette expérience. Remise solennelle de certificats ''Artiste explorateur de textures''. Projection vers les prochaines aventures artistiques. Applaudissements finaux.','Dessiner le concept de présentation et; Présenter les techniques artistiques appropriées; Développer le sens esthétique par le partage des apprentissages',NULL,NULL,NULL,'formative','{"observable":["Présente œuvre avec fierté appropriée","Communique processus créatif clairement","Interagit respectueusement avec public","Démontre apprentissages intégrés"],"checkpoints":["Qualité et confiance de la présentation","Capacité à expliquer son travail","Fierté et accomplissement manifestés"]}',1,'Plan détaillé avec supports visuels',1756911653363,1757594653897,1,'fr','Arts visuels','{"pourDifficultés":["Présentation libre (gestes, sourires)","Présence bienveillante constante","Valorisation de toute participation"],"pourAvancés":["Rôles d''organisation d''exposition","Présentations détaillées engageantes","Questions au public sur réactions"],"pourLangue":["Communication gestuelle et visuelle","Mots simples suffisants","Expression par présence joyeuse"],"pourPEI":["Modalités de présentation personnalisées","Espace sécurisé disponible","Reconnaissance adaptée aux capacités"]}','{"vocabulary":["présenter","fierté","communication","apprécier","respecter"],"visualSupports":["Exposition complètement installée, espace accueillant pour visiteurs","Exposition professionnelle complète, signalisation claire","Certificats officiels, exposition encore visible"],"movementBreaks":["Respiration d''artiste : préparation calme et confiante pour le grand moment","Circulation d''exposition : mouvements dignes et professionnels de guide d''art","Salut final d''artistes : reconnaissance collective de l''aventure partagée"]}',NULL,NULL,NULL,NULL,'{"questions":["Les élèves ont-ils atteint les objectifs?","Quelles adaptations étaient nécessaires?","Que ferais-je différemment la prochaine fois?"]}',NULL,'',4,13,'core',1);
INSERT INTO ETFOLessonPlan VALUES('cmf43u3uc009pvj9t4t4mky55',23,'Réflexion et évaluation de l''unité','cmf43u3u0008xvj9tsg5gcs5s',1769011200000,45,'Retour sur l''exposition de la veille avec partage des moments forts. Consultation des portfolios personnels pour retracer le chemin parcouru depuis la première leçon. Comparaison des premières découvertes tactiles avec les créations finales. Introduction du concept de progrès artistique et personnel.','Création d''une carte mentale collective ''Nos découvertes sur les textures'' avec techniques apprises, matériaux explorés, mots nouveaux. Activité individuelle : ''Chasse aux textures dans ma vie'' où chaque élève identifie textures dans vêtements, jouets, nourriture, maison. Échange en petits groupes sur applications futures. Création d''un ''contrat d''explorateur'' pour continuer à remarquer textures au quotidien.','Cérémonie finale de clôture de l''unité. Chaque élève exprime une découverte surprenante et un engagement pour continuer à explorer. Signature collective du ''contrat de classe des explorateurs de textures''. Rangement soigneux des portfolios pour les rapporter. Projection vers la prochaine aventure artistique. Remerciements mutuels pour le parcours partagé.','Peindre le concept de réflexion et; Créer les techniques artistiques appropriées; Développer le sens esthétique par l''expression créative','["Portfolios personnels complets","Photos de l''exposition","Premières créations de l''unité (frottages, collections)","Grand papier pour carte mentale","Feutres et crayons","Images de textures quotidiennes","Contrats d''explorateur à emporter","Contrat collectif à signer","Portfolios à emporter","Certificats finaux si non remis"]',NULL,'Réflexion et évaluation de l''unité','Retour sur l''exposition de la veille avec partage des moments forts. Consultation des portfolios personnels pour retracer le chemin parcouru depuis la première leçon. Comparaison des premières découvertes tactiles avec les créations finales. Introduction du concept de progrès artistique et personnel.','Création d''une carte mentale collective ''Nos découvertes sur les textures'' avec techniques apprises, matériaux explorés, mots nouveaux. Activité individuelle : ''Chasse aux textures dans ma vie'' où chaque élève identifie textures dans vêtements, jouets, nourriture, maison. Échange en petits groupes sur applications futures. Création d''un ''contrat d''explorateur'' pour continuer à remarquer textures au quotidien.','Cérémonie finale de clôture de l''unité. Chaque élève exprime une découverte surprenante et un engagement pour continuer à explorer. Signature collective du ''contrat de classe des explorateurs de textures''. Rangement soigneux des portfolios pour les rapporter. Projection vers la prochaine aventure artistique. Remerciements mutuels pour le parcours partagé.','Peindre le concept de réflexion et; Créer les techniques artistiques appropriées; Développer le sens esthétique par l''expression créative',NULL,NULL,NULL,'formative','{"observable":["Identifie progrès personnels réalisés","Fait liens entre apprentissages et vie quotidienne","Exprime appréciation pour expériences vécues","Montre motivation pour continuer l''exploration"],"checkpoints":["Qualité de la réflexion sur les apprentissages","Pertinence des connexions avec quotidien","Engagement dans les projections futures"]}',1,'Plan détaillé avec supports visuels',1756911653364,1757594653898,1,'fr','Arts visuels','{"pourDifficultés":["Réflexion guidée avec questions très concrètes","Valorisation de chaque petite découverte","Support visuel constant"],"pourAvancés":["Réflexions plus approfondies sur techniques","Connexions sophistiquées avec d''autres domaines","Rôle de facilitateur pour pairs"],"pourLangue":["Expression par gestes et dessins","Mots clés illustrés","Participation selon niveau de confort"],"pourPEI":["Modalités d''expression adaptées","Réflexion à son rythme","Reconnaissance personnalisée du parcours"]}','{"vocabulary":["réfléchir","évaluer","progrès","connexions","quotidien"],"visualSupports":["Galerie chronologique du parcours de l''unité, photos souvenirs de l''exposition","Toutes créations de l''unité visibles, exemples de textures quotidiennes","Contrat collectif sur affiche, résumé visuel du parcours accompli"],"movementBreaks":["Voyage dans le temps : mouvements représentant l''évolution du débutant à l''artiste","Démonstration tactile : toucher différentes textures des vêtements portés","Salut final d''explorateurs : geste symbolique de reconnaissance mutuelle"]}',NULL,NULL,NULL,NULL,'{"questions":["Les élèves ont-ils atteint les objectifs?","Quelles adaptations étaient nécessaires?","Que ferais-je différemment la prochaine fois?"]}',NULL,'',4,14,'core',1);
INSERT INTO ETFOLessonPlan VALUES('cmf43u3ud009rvj9tacirgdy7',23,'Textures et lumière: Jeux d''ombres','cmf43u3u0008xvj9tsg5gcs5s',1769097600000,45,'Jeu de découverte avec lampe de poche et objets texturés. Observer comment les textures créent des ombres différentes. Introduction au concept de projection d''ombres texturées.','Création d''art d''ombres texturées. Les élèves placent objets texturés devant sources lumineuses pour projeter des ombres intéressantes. Documentation par dessins et frottages des ombres créées. Expérimentation avec transparences colorées.','Spectacle d''ombres : chaque élève présente sa création d''ombre favorite. Discussion sur comment la lumière change notre perception des textures. Connexion avec l''art des ombres dans le monde.','Modeler les textures variées; Participer à les techniques artistiques appropriées; Développer le sens esthétique par le jeu dirigé','["Lampes de poche","Objets texturés variés","Mur blanc ou écran","Lampes variées","Objets texturés","Papiers transparents colorés","Carnet de documentation","Créations d''ombres","Équipement de projection"]',NULL,'Textures et lumière: Jeux d''ombres','Jeu de découverte avec lampe de poche et objets texturés. Observer comment les textures créent des ombres différentes. Introduction au concept de projection d''ombres texturées.','Création d''art d''ombres texturées. Les élèves placent objets texturés devant sources lumineuses pour projeter des ombres intéressantes. Documentation par dessins et frottages des ombres créées. Expérimentation avec transparences colorées.','Spectacle d''ombres : chaque élève présente sa création d''ombre favorite. Discussion sur comment la lumière change notre perception des textures. Connexion avec l''art des ombres dans le monde.','Modeler les textures variées; Participer à les techniques artistiques appropriées; Développer le sens esthétique par le jeu dirigé',NULL,NULL,NULL,'formative','{"observable":["Manipule efficacement lumière et objets","Reconnaît effets de lumière sur textures","Participe aux présentations"],"checkpoints":["Observation pendant manipulation","Documentation créée","Participation aux discussions"]}',1,'Plan détaillé avec supports visuels',1756911653365,1757594653899,1,'fr','Arts visuels','{"pourDifficultés":["Textures simples avec ombres marquées","Documentation simplifiée","Support constant"],"pourAvancés":["Création d''histoires avec ombres","Manipulation complexe de lumière","Leadership dans groupes"],"pourLangue":["Démonstrations visuelles","Vocabulaire illustré","Expression par l''art plutôt que mots"],"pourPEI":["Adaptation outils selon capacités","Temps flexible","Support sensoriel approprié"]}','{"vocabulary":["ombre","lumière","transparent"],"visualSupports":["Exemples d''art avec ombres, vocabulaire lumière/ombre illustré","Guide de manipulation de la lumière, exemples d''artistes travaillant avec ombres","Espace de présentation avec éclairage approprié"],"movementBreaks":["Jeu corporel : créer des ombres avec les mains","Pause mouvement : danse des ombres au rythme lent","Relaxation : imaginer être une ombre qui danse"]}',NULL,NULL,NULL,NULL,'{"questions":["Les élèves ont-ils atteint les objectifs?","Quelles adaptations étaient nécessaires?","Que ferais-je différemment la prochaine fois?"]}',NULL,'',4,15,'extension',1);
INSERT INTO ETFOLessonPlan VALUES('cmf43u3ud009tvj9tp2mhybei',23,'Textures comestibles: Art culinaire tactile','cmf43u3u0008xvj9tsg5gcs5s',1769184000000,45,'Dégustation à l''aveugle de différentes textures alimentaires. Décrire les sensations tactiles dans la bouche en français. Introduction à l''art culinaire comme forme d''expression artistique.','Création d''arrangements artistiques avec aliments de différentes textures. Focus sur couleurs, formes et textures contrastantes. Documentation photographique avant dégustation collective. Connexion art et nutrition.','Exposition culinaire suivie de dégustation collective. Chaque élève présente son arrangement en décrivant les textures choisies. Réflexion sur art éphémère et plaisir des sens.','Transformer les textures variées; Créer les techniques artistiques appropriées; Développer le sens esthétique par l''expression créative','["Aliments textures variées (sécuritaires)","Bandeaux","Assiettes","Serviettes","Fruits/légumes variés","Assiettes artistiques","Ustensiles","Appareil photo","Arrangements créés","Documentation photo"]',NULL,'Textures comestibles: Art culinaire tactile','Dégustation à l''aveugle de différentes textures alimentaires. Décrire les sensations tactiles dans la bouche en français. Introduction à l''art culinaire comme forme d''expression artistique.','Création d''arrangements artistiques avec aliments de différentes textures. Focus sur couleurs, formes et textures contrastantes. Documentation photographique avant dégustation collective. Connexion art et nutrition.','Exposition culinaire suivie de dégustation collective. Chaque élève présente son arrangement en décrivant les textures choisies. Réflexion sur art éphémère et plaisir des sens.','Transformer les textures variées; Créer les techniques artistiques appropriées; Développer le sens esthétique par l''expression créative',NULL,NULL,NULL,'formative','{"observable":["Crée arrangements esthétiques","Utilise vocabulaire des textures alimentaires","Participe aux échanges sensoriels"],"checkpoints":["Qualité arrangements créés","Participation aux discussions","Respect des autres et des aliments"]}',1,'Plan détaillé avec supports visuels',1756911653366,1757594653900,1,'fr','Arts visuels','{"pourDifficultés":["Aliments très familiers","Création simple","Pas d''obligation de goûter"],"pourAvancés":["Arrangements complexes","Recherche sur traditions culinaires","Animation des dégustations"],"pourLangue":["Focus sur exploration sensorielle","Vocabulaire alimentaire de base","Partage culturel"],"pourPEI":["Respect sensibilités alimentaires","Alternatives adaptées","Participation selon capacités"]}','{"vocabulary":["comestible","croquant","moelleux"],"visualSupports":["Images d''art culinaire, vocabulaire des textures alimentaires","Exemples d''art culinaire, guide des combinaisons harmonieuses","Galerie des créations photographiées"],"movementBreaks":["Mouvement de mastication exagérée pour comprendre textures","Étirement gourmand : mouvements imitant croquer, mâcher délicatement","Remerciement corporel pour les sens : toucher cœur, bouche, yeux"]}',NULL,NULL,NULL,NULL,'{"questions":["Les élèves ont-ils atteint les objectifs?","Quelles adaptations étaient nécessaires?","Que ferais-je différemment la prochaine fois?"]}',NULL,'',4,16,'extension',1);
INSERT INTO ETFOLessonPlan VALUES('cmf43u3ue009vvj9tcpf6pcd1',23,'Textures numériques: Art et technologie','cmf43u3u0008xvj9tsg5gcs5s',1769443200000,45,'Découverte des textures sur tablettes tactiles. Comparaison entre toucher réel et virtuel. Introduction aux applications d''art numérique adaptées à l''âge.','Création d''art numérique inspiré des textures découvertes dans les leçons précédentes. Utilisation d''outils de texture virtuels pour recréer sensations tactiles. Expérimentation avec couleurs et formes.','Présentation des créations numériques sur écran partagé. Comparaison avec créations physiques précédentes. Discussion sur avantages et limites de l''art numérique.','Représenter les textures variées; Créer les techniques artistiques appropriées; Développer l''appréciation artistique par l''expression créative','["Tablettes","Applications d''art adaptées","Stylets","Tablettes avec applications","Stylets","Portfolios physiques pour inspiration","Créations numériques","Écran de projection","Créations physiques antérieures"]',NULL,'Textures numériques: Art et technologie','Découverte des textures sur tablettes tactiles. Comparaison entre toucher réel et virtuel. Introduction aux applications d''art numérique adaptées à l''âge.','Création d''art numérique inspiré des textures découvertes dans les leçons précédentes. Utilisation d''outils de texture virtuels pour recréer sensations tactiles. Expérimentation avec couleurs et formes.','Présentation des créations numériques sur écran partagé. Comparaison avec créations physiques précédentes. Discussion sur avantages et limites de l''art numérique.','Représenter les textures variées; Créer les techniques artistiques appropriées; Développer l''appréciation artistique par l''expression créative',NULL,NULL,NULL,'formative','{"observable":["Utilise outils numériques de base","Crée art inspiré d''expériences tactiles","Compare art numérique et physique"],"checkpoints":["Manipulation des outils","Créations produites","Participation aux discussions comparatives"]}',1,'Plan détaillé avec supports visuels',1756911653367,1757594653901,1,'fr','Arts visuels','{"pourDifficultés":["Applications très simples","Support technique constant","Objectifs réduits"],"pourAvancés":["Fonctions avancées des applications","Création de tutoriels pour pairs","Exploration autonome"],"pourLangue":["Interface visuelle intuitive","Démonstrations sans paroles nécessaires","Expression artistique universelle"],"pourPEI":["Adaptations technologiques selon besoins","Alternatives si difficultés","Rythme personnalisé"]}','{"vocabulary":["numérique","virtuel","application"],"visualSupports":["Exemples d''art numérique texturé, comparaison réel/virtuel","Guide d''utilisation applications, galerie d''inspirations numériques","Espace de présentation numérique organisé"],"movementBreaks":["Mouvement doigts : exercices préparatoires pour manipulation tactile","Pause écran : regarder au loin et cligner des yeux","Reconnection corporelle : toucher différentes textures réelles"]}',NULL,NULL,NULL,NULL,'{"questions":["Les élèves ont-ils atteint les objectifs?","Quelles adaptations étaient nécessaires?","Que ferais-je différemment la prochaine fois?"]}',NULL,'',4,17,'extension',1);
INSERT INTO ETFOLessonPlan VALUES('cmf43u3uf009xvj9tx3rsr4to',23,'Textures musicales: Sons et sensations','cmf43u3u0008xvj9tsg5gcs5s',1769529600000,45,'Écoute de sons produits par différentes textures (frotter papier sablé, caresser soie, taper surfaces variées). Association texture-son en français. Introduction synesthésie artistique.','Création de ''paysages sonores texturés''. Les élèves associent leurs textures favorites à des sons, créent des séquences rythmiques. Composition collective d''une ''symphonie des textures'' avec mouvements corporels.','Concert final de la ''symphonie des textures''. Chaque groupe présente sa création. Réflexion sur liens entre sens différents et expression artistique multisensorielle.','Présenter les sons et leur correspondance; Créer la discrimination auditive des sons; Développer l''appréciation artistique par l''expression créative','["Objets texturés","Enregistreur/haut-parleur","Instruments simples","Objets texturés producteurs de sons","Instruments de percussion simple","Enregistreur","Compositions créées","Instruments utilisés"]',NULL,'Textures musicales: Sons et sensations','Écoute de sons produits par différentes textures (frotter papier sablé, caresser soie, taper surfaces variées). Association texture-son en français. Introduction synesthésie artistique.','Création de ''paysages sonores texturés''. Les élèves associent leurs textures favorites à des sons, créent des séquences rythmiques. Composition collective d''une ''symphonie des textures'' avec mouvements corporels.','Concert final de la ''symphonie des textures''. Chaque groupe présente sa création. Réflexion sur liens entre sens différents et expression artistique multisensorielle.','Présenter les sons et leur correspondance; Créer la discrimination auditive des sons; Développer l''appréciation artistique par l''expression créative',NULL,NULL,NULL,'formative','{"observable":["Établit connexions texture-son","Participe aux créations collectives","Exprime préférences artistiques"],"checkpoints":["Participation aux associations","Contribution aux créations groupales","Expression dans discussions finales"]}',1,'Plan détaillé avec supports visuels',1756911653367,1757594653902,1,'fr','Arts visuels','{"pourDifficultés":["Associations simples évidentes","Participation par mouvement","Rôles adaptés dans groupe"],"pourAvancés":["Créations sonores complexes","Direction musicale de groupes","Exploration d''instruments variés"],"pourLangue":["Expression par sons et mouvements","Participation non-verbale valorisée","Découverte culturelle par musique"],"pourPEI":["Adaptations sensorielles nécessaires","Participation selon confort auditif","Alternatives visuelles/tactiles"]}','{"vocabulary":["sonorité","rythme","mélodie"],"visualSupports":["Carte son-texture, exemples d''art synesthésique","Partition visuelle simple, code couleur pour textures-sons","Programme de concert créé collectivement"],"movementBreaks":["Mouvement rythmé selon textures entendues","Danse des textures : mouvements selon qualité sonore","Applaudissements texturés : frotter mains plutôt que claquer"]}',NULL,NULL,NULL,NULL,'{"questions":["Les élèves ont-ils atteint les objectifs?","Quelles adaptations étaient nécessaires?","Que ferais-je différemment la prochaine fois?"]}',NULL,'',4,18,'extension',1);
INSERT INTO ETFOLessonPlan VALUES('cmf43u3ug009zvj9tuvmtsr3p',23,'Textures en mouvement: Danse tactile','cmf43u3u0008xvj9tsg5gcs5s',4102416000000,45,'Échauffement corporel en imitant différentes textures : mouvements lisses comme soie, saccadés comme rugueux, rebondissants comme spongieux. Connexion corps-texture-expression.','Création de danses individuelles et en petits groupes inspirées des textures explorées. Chaque élève développe sa ''signature de texture'' en mouvement. Répétitions pour présentation finale avec narration en français.','Spectacle de danses texturées. Chaque création est présentée avec explication de l''inspiration texture. Public apprécie en identifiant les textures représentées. Célébration du voyage artistique multisensoriel.','Intégrer les textures variées; Créer les techniques artistiques appropriées; Développer l''appréciation artistique par l''expression créative','["Espace dégagé","Musiques variées","Échantillons textures","Musiques variées","Accessoires texture (foulards, papiers)","Espace de pratique","Costumes/accessoires simples","Espace de présentation"]',NULL,'Textures en mouvement: Danse tactile','Échauffement corporel en imitant différentes textures : mouvements lisses comme soie, saccadés comme rugueux, rebondissants comme spongieux. Connexion corps-texture-expression.','Création de danses individuelles et en petits groupes inspirées des textures explorées. Chaque élève développe sa ''signature de texture'' en mouvement. Répétitions pour présentation finale avec narration en français.','Spectacle de danses texturées. Chaque création est présentée avec explication de l''inspiration texture. Public apprécie en identifiant les textures représentées. Célébration du voyage artistique multisensoriel.','Intégrer les textures variées; Créer les techniques artistiques appropriées; Développer l''appréciation artistique par l''expression créative',NULL,NULL,NULL,'formative','{"observable":["Traduit textures en mouvements expressifs","Participe aux créations collaboratives","Communique idées par le corps"],"checkpoints":["Créativité mouvements développés","Collaboration dans groupes","Participation aux présentations finales"]}',1,'Plan détaillé avec supports visuels',1756911653368,1757594653903,1,'fr','Arts visuels','{"pourDifficultés":["Mouvements simples repetitifs","Imitation d''autres élèves","Participation partielle valorisée"],"pourAvancés":["Chorégraphies complexes","Leadership créatif","Narration sophistiquée en français"],"pourLangue":["Expression corporelle universelle","Pas de barrière linguistique","Vocabulaire mouvement avec gestes"],"pourPEI":["Mouvements adaptés aux capacités","Participation selon confort physique","Rôles alternatifs disponibles"]}','{"vocabulary":["mouvement","chorégraphie","fluide"],"visualSupports":["Guide mouvements-textures illustré, exemples de danse expressive","Exemples chorégraphiques, vocabulaire mouvement en français","Scène aménagée, programme du spectacle"],"movementBreaks":["L''activité entière est un mouvement break !","Repos dynamique : étirements doux entre séquences","Relaxation finale : retour au calme avec respirations profondes"]}',NULL,NULL,NULL,NULL,'{"questions":["Les élèves ont-ils atteint les objectifs?","Quelles adaptations étaient nécessaires?","Que ferais-je différemment la prochaine fois?"]}',NULL,'',4,19,'core',0);
INSERT INTO ETFOLessonPlan VALUES('cmf43u3ug00a1vj9ttgn5vo4p',23,'Célébration des textures: Exposition finale','cmf43u3u0008xvj9tsg5gcs5s',1769616000000,45,'Préparation de l''exposition : sélection des meilleures créations, rédaction d''étiquettes en français, organisation de l''espace. Rôles de curator attribués aux élèves volontaires.','Vernissage de l''exposition ''Notre Voyage dans les Textures''. Chaque élève guide les visiteurs devant ses créations favorites, explique son parcours d''apprentissage en français. Démonstrations interactives pour les invités.','Cercle final de réflexion après l''exposition. Chaque élève partage sa découverte la plus surprenante sur les textures. Remise de certificats de ''Explorateur de Textures''. Projection vers futures explorations artistiques.','Maîtriser les textures variées; Créer les techniques artistiques appropriées; Développer l''appréciation artistique par la célébration collective','["Toutes créations de l''unité","Étiquettes","Supports d''exposition","Matériel d''organisation","Exposition installée","Programmes","Démonstrations tactiles","Rafraîchissements simples","Certificats personnalisés","Portfolio collectif complet"]',NULL,'Célébration des textures: Exposition finale','Préparation de l''exposition : sélection des meilleures créations, rédaction d''étiquettes en français, organisation de l''espace. Rôles de curator attribués aux élèves volontaires.','Vernissage de l''exposition ''Notre Voyage dans les Textures''. Chaque élève guide les visiteurs devant ses créations favorites, explique son parcours d''apprentissage en français. Démonstrations interactives pour les invités.','Cercle final de réflexion après l''exposition. Chaque élève partage sa découverte la plus surprenante sur les textures. Remise de certificats de ''Explorateur de Textures''. Projection vers futures explorations artistiques.','Maîtriser les textures variées; Créer les techniques artistiques appropriées; Développer l''appréciation artistique par la célébration collective',NULL,NULL,NULL,'formative','{"observable":["Articule apprentissages sur les textures","Présente travaux avec fierté","Apprécie créations des pairs"],"checkpoints":["Qualité présentation personnelle","Participation à organisation collective","Réflexion sur parcours d''apprentissage"]}',1,'Plan détaillé avec supports visuels',1756911653369,1757594653904,1,'fr','Arts visuels','{"pourDifficultés":["Rôle adapté dans exposition","Phrases préparées pour présentation","Support par pairs"],"pourAvancés":["Rôle de guide principal","Créations sophistiquées mises en valeur","Animation des démonstrations"],"pourLangue":["Présentation visuelle prioritaire","Support traduction si nécessaire","Fierté culturelle valorisée"],"pourPEI":["Participation selon capacités","Adaptations pour confort","Célébration individualisée des progrès"]}','{"vocabulary":["exposition","curator","vernissage"],"visualSupports":["Exemples d''expositions d''art, guide du curator débutant","Signalisation exposition, parcours fléché, portfolio collectif de l''unité","Mur des découvertes surprenantes, galerie des moments forts"],"movementBreaks":["Installation dynamique : porter, placer, arranger avec soin","Circulation libre et naturelle dans l''exposition","Applaudissements finaux et accolades de célébration"]}',NULL,NULL,NULL,NULL,'{"questions":["Les élèves ont-ils atteint les objectifs?","Quelles adaptations étaient nécessaires?","Que ferais-je différemment la prochaine fois?"]}',NULL,'',4,20,'core',1);
INSERT INTO ETFOLessonPlan VALUES('cmf43u3uj00a5vj9t37u7ek2t',23,'Qu''est-ce qu''un ami?','cmf43u3ui00a3vj9to9pgq6bi',1766160000000,45,'Cercle d''amitié avec la marionnette Léo. Comptine: ''Bonjour mes amis, comment allez-vous?'' Présentation de Léo qui cherche des amis. Discussion: Qu''est-ce qui rend quelqu''un un bon ami? Montrer des images d''enfants qui jouent ensemble, partagent et s''aident.','Léo raconte ses aventures d''amitié. Histoire interactive: ''Léo au parc'' - comment il a rencontré ses amis en partageant sa balle. Élèves identifient les comportements amicaux dans l''histoire. Jeu du miroir de l''amitié: regarder son reflet et dire une qualité d''ami qu''on a.','Retour au cercle avec Léo. Question réflexive: ''Quelle façon d''être un bon ami veux-tu essayer aujourd''hui?'' Chaque élève choisit une carte-objectif d''amitié. Chanson finale: ''Les amis, c''est précieux dans mon cœur!'' Câlin de groupe amical.','Identifier le concept de qu''est-ce qu''un; Pratiquer les habiletés de vie quotidienne; Développer l''autonomie par des situations authentiques','["Marionnette Léo (petit lapin en peluche)","Images d''amitié (partager, jouer, aider)","Livre illustré ''Léo cherche des amis''","Miroir de l''amitié décoré","Histoire illustrée de Léo","Balles colorées pour démonstration","Miroir de l''amitié","Cartes des qualités d''amis","Cartes-objectifs d''amitié","Léo la marionnette","Tableau des intentions d''amitié","Carte de chanson illustrée"]',NULL,'Qu''est-ce qu''un ami?','Cercle d''amitié avec la marionnette Léo. Comptine: ''Bonjour mes amis, comment allez-vous?'' Présentation de Léo qui cherche des amis. Discussion: Qu''est-ce qui rend quelqu''un un bon ami? Montrer des images d''enfants qui jouent ensemble, partagent et s''aident.','Léo raconte ses aventures d''amitié. Histoire interactive: ''Léo au parc'' - comment il a rencontré ses amis en partageant sa balle. Élèves identifient les comportements amicaux dans l''histoire. Jeu du miroir de l''amitié: regarder son reflet et dire une qualité d''ami qu''on a.','Retour au cercle avec Léo. Question réflexive: ''Quelle façon d''être un bon ami veux-tu essayer aujourd''hui?'' Chaque élève choisit une carte-objectif d''amitié. Chanson finale: ''Les amis, c''est précieux dans mon cœur!'' Câlin de groupe amical.','Identifier le concept de qu''est-ce qu''un; Pratiquer les habiletés de vie quotidienne; Développer l''autonomie par des situations authentiques',NULL,NULL,NULL,'formative','{"observable":["L''élève écoute attentivement l''histoire de Léo","L''élève pointe ou nomme des comportements amicaux dans les images","L''élève participe aux gestes d''amitié avec plaisir","L''élève choisit une qualité d''ami dans le miroir"],"checkpoints":["Début de leçon: Observer l''engagement avec la marionnette Léo","Milieu: Vérifier la compréhension des comportements amicaux","Fin: Noter le choix d''objectif d''amitié de chaque élève"]}',1,'Plan détaillé avec supports visuels',1756911653371,1757594653908,1,'fr','Formation personnelle et sociale','{"pourDifficultés":["Utiliser uniquement les concepts de base: gentil, partager, jouer","Permettre la réponse par gestes ou pointage plutôt que par mots","Offrir plus de temps avec Léo en interaction individuelle"],"pourAvancés":["Introduire des qualités d''amis plus nuancées: loyal, compréhensif","Encourager à donner des exemples personnels d''amitié","Inviter à aider les pairs à identifier les qualités d''amis"],"pourLangue":["Utiliser beaucoup de supports visuels et de démonstrations","Permettre l''expression dans leur langue maternelle si nécessaire","Jumeler avec un pair francophone pour le soutien"],"pourPEI":["Adapter selon les besoins sociaux individuels","Utiliser des supports sensoriels appropriés","Modifier les attentes selon les objectifs du PEI"]}','{"vocabulary":["ami","gentil","partager"],"visualSupports":["Cartes visuelles des comportements amicaux, gestes TPR pour ''ami'', ''gentil'', ''partager'', expressions faciales chaleureuses","Séquences d''images de l''histoire, démonstrations concrètes du partage, expressions faciales positives constantes","Routine de fermeture prévisible, gestes pour la chanson, tableau visuel des objectifs d''amitié"],"movementBreaks":["Geste de l''amitié (serrer la main doucement)","Mouvement du partage (offrir avec les deux mains)","Étirement des bras ''accueillir un ami''","Marche sur place ''aller vers un ami''","Geste du cœur précieux","Mouvement de câlin doux"]}',NULL,NULL,NULL,NULL,'{"questions":["Les élèves ont-ils atteint les objectifs?","Quelles adaptations étaient nécessaires?","Que ferais-je différemment la prochaine fois?"]}',NULL,'',5,1,'core',1);
INSERT INTO ETFOLessonPlan VALUES('cmf43u3uj00a7vj9ticmaznoy',23,'Mes qualités d''ami','cmf43u3ui00a3vj9to9pgq6bi',1767715200000,45,'Révision avec Léo qui présente son coffre aux trésors des qualités d''amis. Comptine: ''Moi aussi j''ai des qualités, dans mon cœur elles brillent!'' Léo montre fièrement ses qualités: ''Je suis serviable, je partage mes carottes.'' Préparation à découvrir nos propres trésors.','Exploration personnelle des qualités. Chaque élève reçoit son propre petit miroir pour découvrir ses qualités d''ami. Léo aide: ''Regarde-toi, qu''est-ce que tu fais bien avec tes amis?'' Création d''un collier de qualités personnalisé avec des perles colorées représentant chaque qualité identifiée.','Cercle de partage des qualités. Chaque élève montre fièrement son collier et dit une qualité qu''il a découverte. Léo applaudit chaque partage. Engagement: ''Cette semaine, je vais utiliser ma qualité spéciale pour être un bon ami.'' Chanson: ''Mes qualités brillent, mes qualités grandissent!''','Explorer le concept de mes qualités; Pratiquer les habiletés de vie quotidienne; Développer l''autonomie par des situations authentiques','["Coffre aux trésors décoré","Léo la marionnette","Cartes de qualités brillantes","Miroir magique des qualités","Petits miroirs individuels","Perles colorées et ficelles","Images de qualités d''amis","Tableau des découvertes personnelles","Colliers de qualités complétés","Tableau d''engagement hebdomadaire","Léo la marionnette","Carte de chanson des qualités"]',NULL,'Mes qualités d''ami','Révision avec Léo qui présente son coffre aux trésors des qualités d''amis. Comptine: ''Moi aussi j''ai des qualités, dans mon cœur elles brillent!'' Léo montre fièrement ses qualités: ''Je suis serviable, je partage mes carottes.'' Préparation à découvrir nos propres trésors.','Exploration personnelle des qualités. Chaque élève reçoit son propre petit miroir pour découvrir ses qualités d''ami. Léo aide: ''Regarde-toi, qu''est-ce que tu fais bien avec tes amis?'' Création d''un collier de qualités personnalisé avec des perles colorées représentant chaque qualité identifiée.','Cercle de partage des qualités. Chaque élève montre fièrement son collier et dit une qualité qu''il a découverte. Léo applaudit chaque partage. Engagement: ''Cette semaine, je vais utiliser ma qualité spéciale pour être un bon ami.'' Chanson: ''Mes qualités brillent, mes qualités grandissent!''','Explorer le concept de mes qualités; Pratiquer les habiletés de vie quotidienne; Développer l''autonomie par des situations authentiques',NULL,NULL,NULL,'formative','{"observable":["L''élève regarde attentivement dans le miroir des qualités","L''élève identifie au moins une qualité positive en lui","L''élève participe activement à la création de son collier","L''élève montre de la fierté lors du partage final"],"checkpoints":["Début: Observer l''engagement avec le coffre aux trésors","Milieu: Vérifier si l''élève peut nommer une qualité personnelle","Fin: Noter la participation au partage et l''engagement pris"]}',1,'Plan détaillé avec supports visuels',1756911653372,1757594653909,1,'fr','Formation personnelle et sociale','{"pourDifficultés":["Commencer par une seule qualité simple et concrète","Utiliser des photos de l''élève en action positive","Permettre l''aide d''un pair pour identifier les qualités"],"pourAvancés":["Explorer des qualités plus abstraites comme ''compréhensif'' ou ''patient''","Encourager à donner des exemples spécifiques de leurs qualités","Inviter à aider les autres à découvrir leurs qualités"],"pourLangue":["Utiliser des images et des gestes pour chaque qualité","Permettre l''expression dans leur langue maternelle","Offrir un vocabulaire visuel des qualités de base"],"pourPEI":["Adapter les matériaux (collier plus simple, moins de perles)","Modifier les attentes selon les capacités individuelles","Utiliser des supports sensoriels appropriés"]}','{"vocabulary":["qualité","bon","spécial"],"visualSupports":["Coffre coloré et attrayant, cartes scintillantes des qualités, gestes TPR pour ''qualité'', ''bon'', ''spécial''","Code couleur pour les qualités (rouge=gentil, bleu=serviable, etc.), démonstrations concrètes avec Léo, photos d''enfants montrant diverses qualités","Routine de partage structurée, applaudissements encourageants, tableau visuel des engagements"],"movementBreaks":["Geste du trésor (mains en coupe)","Mouvement du cœur qui brille (mains sur le cœur)","Étirement ''je grandis avec mes qualités''","Danse douce avec le collier","Geste de fierté (bras croisés, sourire)","Mouvement de croissance (étirer vers le haut)"]}',NULL,NULL,NULL,NULL,'{"questions":["Les élèves ont-ils atteint les objectifs?","Quelles adaptations étaient nécessaires?","Que ferais-je différemment la prochaine fois?"]}',NULL,'',5,2,'core',1);
INSERT INTO ETFOLessonPlan VALUES('cmf43u3uk00a9vj9tyi4q168t',23,'Comment faire des amis','cmf43u3ui00a3vj9to9pgq6bi',1767888000000,45,'Léo arrive avec son sac à dos d''aventures sociales. Comptine: ''Pour faire un ami, que dois-je faire? Saluer, sourire et partager!'' Léo montre comment il approche les nouveaux amis. Démonstration: les bonnes façons de dire bonjour et de commencer à jouer.','Atelier pratique des stratégies d''amitié. Léo présente ses ''super pouvoirs d''amitié'': 1) Regarder dans les yeux 2) Sourire 3) Dire quelque chose de gentil 4) Proposer de jouer ensemble. Jeux de rôle en paires: pratiquer chaque stratégie avec un partenaire différent.','Cercle de réflexion avec Léo. Chaque élève choisit sa stratégie d''amitié préférée pour essayer cette semaine. Création d''un ''passeport d''amitié'' personnel avec sa stratégie choisie. Chanson: ''Je peux faire des amis, je sais comment m''y prendre!''','Découvrir l''amitié positive; Pratiquer les habiletés de vie quotidienne; Développer l''autonomie par des situations authentiques','["Sac à dos d''aventures sociales","Léo la marionnette","Cartes des stratégies d''amitié","Tableau des étapes pour faire des amis","Cartes des super pouvoirs d''amitié","Accessoires de jeu de rôle (chapeaux, jouets)","Tableau de suivi des pratiques","Autocollants de réussite","Passeports d''amitié vierges","Crayons et autocollants","Tableau des engagements de la semaine","Chanson illustrée"]',NULL,'Comment faire des amis','Léo arrive avec son sac à dos d''aventures sociales. Comptine: ''Pour faire un ami, que dois-je faire? Saluer, sourire et partager!'' Léo montre comment il approche les nouveaux amis. Démonstration: les bonnes façons de dire bonjour et de commencer à jouer.','Atelier pratique des stratégies d''amitié. Léo présente ses ''super pouvoirs d''amitié'': 1) Regarder dans les yeux 2) Sourire 3) Dire quelque chose de gentil 4) Proposer de jouer ensemble. Jeux de rôle en paires: pratiquer chaque stratégie avec un partenaire différent.','Cercle de réflexion avec Léo. Chaque élève choisit sa stratégie d''amitié préférée pour essayer cette semaine. Création d''un ''passeport d''amitié'' personnel avec sa stratégie choisie. Chanson: ''Je peux faire des amis, je sais comment m''y prendre!''','Découvrir l''amitié positive; Pratiquer les habiletés de vie quotidienne; Développer l''autonomie par des situations authentiques',NULL,NULL,NULL,'formative','{"observable":["L''élève écoute attentivement les stratégies présentées par Léo","L''élève participe aux jeux de rôle avec intérêt","L''élève démontre au moins une stratégie d''approche sociale","L''élève choisit une stratégie pour son passeport d''amitié"],"checkpoints":["Début: Observer l''engagement avec les démonstrations de Léo","Milieu: Vérifier la participation aux jeux de rôle et la compréhension","Fin: Noter la stratégie choisie et le niveau de confiance exprimé"]}',1,'Plan détaillé avec supports visuels',1756911653373,1757594653910,1,'fr','Formation personnelle et sociale','{"pourDifficultés":["Se concentrer sur une seule stratégie à la fois (commencer par le sourire)","Utiliser plus de modélage avec l''adulte avant la pratique entre pairs","Offrir des scripts visuels: ''Bonjour, comment tu t''appelles?''"],"pourAvancés":["Explorer des stratégies plus complexes: trouver des intérêts communs","Encourager à aider les pairs plus timides dans leurs approches","Discuter de l''adaptation des stratégies selon différentes personnes"],"pourLangue":["Enseigner des phrases simples dans les deux langues si nécessaire","Utiliser beaucoup de démonstrations non verbales","Jumeler avec un pair bienveillant pour la pratique"],"pourPEI":["Adapter selon les besoins sociaux (certains peuvent préférer les jeux parallèles)","Utiliser des supports visuels personnalisés","Modifier les attentes selon les capacités d''interaction sociale"]}','{"vocabulary":["saluer","jouer","inviter"],"visualSupports":["Séquence visuelle des étapes (1. Saluer 2. Sourire 3. Demander de jouer), gestes TPR pour chaque étape, expressions faciales démonstratrices","Démonstrations visuelles de chaque étape, modèles de phrases à utiliser (''Veux-tu jouer avec moi?''), langage corporel positif","Passeport coloré et attrayant, routine de choix individuel, célébration de chaque engagement pris"],"movementBreaks":["Geste de salutation (main levée)","Mouvement du sourire (mains sur les joues)","Marche confiante vers un nouvel ami","Étirement ''j''ouvre mes bras pour accueillir''","Geste de confiance (pouce levé)","Mouvement de célébration douce"]}',NULL,NULL,NULL,NULL,'{"questions":["Les élèves ont-ils atteint les objectifs?","Quelles adaptations étaient nécessaires?","Que ferais-je différemment la prochaine fois?"]}',NULL,'',5,3,'core',1);
INSERT INTO ETFOLessonPlan VALUES('cmf43u3ul00abvj9te21qvvv9',23,'Partager c''est important','cmf43u3ui00a3vj9to9pgq6bi',1768233600000,45,'Léo arrive avec une belle pomme rouge qu''il veut partager. Comptine: ''Partager, partager, c''est donner avec son cœur!'' Démonstration: Léo coupe sa pomme en morceaux pour tous ses amis. Discussion: Pourquoi est-ce que partager rend tout le monde content?','Station d''exploration du partage. Léo guide trois activités: 1) Partage de jouets (chacun son tour avec les blocs) 2) Partage de matériaux d''art (crayons et papier) 3) Partage d''idées (construire ensemble). Pratique du ''tour de rôle'' avec minuteur visuel.','Cercle de réflexion sur le partage. Léo demande: ''Comment vous sentez-vous quand vous partagez?'' et ''Comment vous sentez-vous quand quelqu''un partage avec vous?'' Création d''un ''contrat de partage'' de classe avec des dessins simples.','Coopérer le concept de partager c''est; Pratiquer les habiletés de vie quotidienne; Développer l''autonomie par des situations authentiques','["Pomme factice sécable","Léo la marionnette","Plateau de partage","Images d''enfants qui partagent","Blocs de construction variés","Matériaux d''art à partager","Minuteur visuel coloré","Cartes ''C''est ton tour''","Grande affiche ''Notre contrat de partage''","Crayons et autocollants","Cartes d''émotions (content, fier)","Léo la marionnette"]',NULL,'Partager c''est important','Léo arrive avec une belle pomme rouge qu''il veut partager. Comptine: ''Partager, partager, c''est donner avec son cœur!'' Démonstration: Léo coupe sa pomme en morceaux pour tous ses amis. Discussion: Pourquoi est-ce que partager rend tout le monde content?','Station d''exploration du partage. Léo guide trois activités: 1) Partage de jouets (chacun son tour avec les blocs) 2) Partage de matériaux d''art (crayons et papier) 3) Partage d''idées (construire ensemble). Pratique du ''tour de rôle'' avec minuteur visuel.','Cercle de réflexion sur le partage. Léo demande: ''Comment vous sentez-vous quand vous partagez?'' et ''Comment vous sentez-vous quand quelqu''un partage avec vous?'' Création d''un ''contrat de partage'' de classe avec des dessins simples.','Coopérer le concept de partager c''est; Pratiquer les habiletés de vie quotidienne; Développer l''autonomie par des situations authentiques',NULL,NULL,NULL,'formative','{"observable":["L''élève observe attentivement la démonstration de partage de Léo","L''élève participe à au moins une activité de partage","L''élève respecte le tour des autres avec le minuteur","L''élève exprime ses sentiments sur le partage (verbalement ou visuellement)"],"checkpoints":["Début: Observer la réaction à la démonstration de partage","Milieu: Vérifier la participation aux stations et l''usage du minuteur","Fin: Noter la contribution au contrat de partage et l''expression des sentiments"]}',1,'Plan détaillé avec supports visuels',1756911653373,1757594653911,1,'fr','Formation personnelle et sociale','{"pourDifficultés":["Commencer par des objets moins précieux ou en double","Utiliser un minuteur très court au début (30 secondes)","Offrir beaucoup d''encouragement pour chaque petit partage"],"pourAvancés":["Explorer le concept de partage d''idées et de solutions","Encourager à aider les autres dans leurs difficultés de partage","Discuter des différents types de partage (temps, attention, aide)"],"pourLangue":["Utiliser beaucoup de démonstrations visuelles et de gestes","Enseigner des phrases clés: ''Peux-tu partager?'' ''C''est ton tour''","Permettre l''usage de leur langue maternelle pour exprimer les émotions"],"pourPEI":["Adapter selon les capacités sensorielles (certains enfants peuvent avoir des objets réconfortants)","Modifier les attentes selon les besoins individuels","Utiliser des supports visuels personnalisés pour la séquence de partage"]}','{"vocabulary":["partager","tour","ensemble"],"visualSupports":["Démonstration concrète du partage, images séquentielles (avant/après partage), gestes TPR pour ''partager'', ''tour'', ''ensemble''","Minuteur visuel pour les tours, cartes de rappel du partage, démonstrations de Léo à chaque station","Affiche colorée du contrat, cartes d''émotions pour exprimer les sentiments, dessins simples pour représenter les accords"],"movementBreaks":["Geste du partage (diviser avec les mains)","Mouvement du cœur content (mains sur le cœur)","Danse du partage (passer des objets imaginaires)","Étirement ''mes bras s''ouvrent pour donner''","Geste de signature fière","Mouvement de célébration du groupe"]}',NULL,NULL,NULL,NULL,'{"questions":["Les élèves ont-ils atteint les objectifs?","Quelles adaptations étaient nécessaires?","Que ferais-je différemment la prochaine fois?"]}',NULL,'',5,4,'core',1);
INSERT INTO ETFOLessonPlan VALUES('cmf43u3um00advj9tkc1h9ehj',23,'Jouer ensemble','cmf43u3ui00a3vj9to9pgq6bi',1768406400000,45,'Léo présente ses amis les oursons qui veulent construire une maison ensemble. Comptine: ''À plusieurs c''est plus amusant, tous ensemble on est gagnant!'' Démonstration: comment les oursons s''entraident - un tient, l''autre colle, le troisième décore.','Ateliers de jeu coopératif guidés par Léo. Station 1: Construction collective d''une tour (chacun ajoute un bloc). Station 2: Peinture de groupe (chacun peint une partie). Station 3: Puzzle géant (chacun place des pièces). Accent sur l''encouragement mutuel et la célébration des succès d''équipe.','Cercle de célébration des réussites d''équipe. Léo félicite chaque groupe et demande: ''Qu''est-ce qui a bien marché quand vous avez joué ensemble?'' Création d''un tableau de ''Nos succès d''équipe'' avec dessins et mots.','Pratiquer le concept de jouer ensemble; Participer à les habiletés de vie quotidienne; Développer la régulation émotionnelle par des situations authentiques','["Famille d''oursons en peluche","Petite maison à construire (blocs)","Léo la marionnette","Images de travail d''équipe","Blocs de construction variés","Papier géant et pinceaux","Puzzle géant simple (12 pièces)","Autocollants d''équipe","Tableau ''Nos succès d''équipe''","Crayons colorés","Autocollants de félicitations","Léo la marionnette"]',NULL,'Jouer ensemble','Léo présente ses amis les oursons qui veulent construire une maison ensemble. Comptine: ''À plusieurs c''est plus amusant, tous ensemble on est gagnant!'' Démonstration: comment les oursons s''entraident - un tient, l''autre colle, le troisième décore.','Ateliers de jeu coopératif guidés par Léo. Station 1: Construction collective d''une tour (chacun ajoute un bloc). Station 2: Peinture de groupe (chacun peint une partie). Station 3: Puzzle géant (chacun place des pièces). Accent sur l''encouragement mutuel et la célébration des succès d''équipe.','Cercle de célébration des réussites d''équipe. Léo félicite chaque groupe et demande: ''Qu''est-ce qui a bien marché quand vous avez joué ensemble?'' Création d''un tableau de ''Nos succès d''équipe'' avec dessins et mots.','Pratiquer le concept de jouer ensemble; Participer à les habiletés de vie quotidienne; Développer la régulation émotionnelle par des situations authentiques',NULL,NULL,NULL,'formative','{"observable":["L''élève observe attentivement la démonstration avec les oursons","L''élève participe positivement à au moins une activité d''équipe","L''élève montre des signes d''encouragement envers ses coéquipiers","L''élève contribue au tableau des succès d''équipe"],"checkpoints":["Début: Observer l''intérêt pour la démonstration de coopération","Milieu: Vérifier la participation aux stations et les interactions positives","Fin: Noter la capacité à identifier et célébrer les succès d''équipe"]}',1,'Plan détaillé avec supports visuels',1756911653374,1757594653912,1,'fr','Formation personnelle et sociale','{"pourDifficultés":["Commencer par des groupes de 2 plutôt que plus grands","Donner des rôles très spécifiques et simples","Offrir plus de soutien de l''adulte pendant les activités"],"pourAvancés":["Introduire des défis plus complexes nécessitant plus de planification","Encourager à être des leaders positifs dans leur équipe","Discuter de stratégies d''entraide et de résolution de problèmes"],"pourLangue":["Utiliser beaucoup de démonstrations et de modélage","Enseigner des phrases d''encouragement simples: ''Bon travail!'', ''Continue!''","Jumeler avec des pairs bienveillants et patients"],"pourPEI":["Adapter les activités selon les capacités motrices et sensorielles","Modifier les attentes selon les besoins sociaux individuels","Utiliser des supports visuels personnalisés pour les étapes de coopération"]}','{"vocabulary":["coopérer","équipe","aider"],"visualSupports":["Démonstration concrète avec les oursons, gestes TPR pour ''coopérer'', ''équipe'', ''aider'', séquence visuelle de la construction","Instructions visuelles pour chaque station, minuteur pour la rotation, modèles d''encouragement (''Bravo!'', ''Super travail d''équipe!'')","Tableau coloré et invitant, routine de célébration positive, modèles de phrases pour décrire les succès"],"movementBreaks":["Geste de l''équipe (mains jointes au centre)","Mouvement d''entraide (tendre la main)","Danse de l''équipe (mouvement synchronisé)","Étirement ''on se soutient'' (en paires)","Applaudissements d''équipe","Mouvement de fierté collective"]}',NULL,NULL,NULL,NULL,'{"questions":["Les élèves ont-ils atteint les objectifs?","Quelles adaptations étaient nécessaires?","Que ferais-je différemment la prochaine fois?"]}',NULL,'',5,5,'core',1);
INSERT INTO ETFOLessonPlan VALUES('cmf43u3un00afvj9t07s6glrh',23,'Quand les amis sont différents','cmf43u3ui00a3vj9to9pgq6bi',1768579200000,45,'Léo présente sa collection d''amis: un chat, un oiseau, un poisson. Comptine: ''Différents mais amis, c''est ça la magie!'' Discussion: Comment ses amis sont-ils différents? Comment sont-ils semblables? Pourquoi Léo les aime tous?','Exploration des différences célébrées. Station 1: ''Nos cheveux différents'' (observer et dessiner). Station 2: ''Nos langues différentes'' (écouter des salutations). Station 3: ''Nos talents différents'' (montrer une habileté spéciale). Léo guide et célèbre chaque découverte.','Cercle de célébration de l''unicité. Léo demande: ''Qu''est-ce qui rend tes amis spéciaux et différents?'' Création d''un collage de classe: ''Nous sommes tous différents et c''est merveilleux!'' Chant: ''Vive nos différences!''','Développer l''amitié positive; Pratiquer les habiletés de vie quotidienne; Développer la régulation émotionnelle par des situations authentiques','["Marionnettes variées (chat, oiseau, poisson)","Léo la marionnette","Images de familles diverses","Miroir de la diversité","Miroirs individuels","Papier et crayons colorés","Enregistrements de salutations multilingues","Cartes de talents spéciaux","Grande toile pour collage","Photos ou dessins des élèves","Matériaux de collage variés","Chanson illustrée"]',NULL,'Quand les amis sont différents','Léo présente sa collection d''amis: un chat, un oiseau, un poisson. Comptine: ''Différents mais amis, c''est ça la magie!'' Discussion: Comment ses amis sont-ils différents? Comment sont-ils semblables? Pourquoi Léo les aime tous?','Exploration des différences célébrées. Station 1: ''Nos cheveux différents'' (observer et dessiner). Station 2: ''Nos langues différentes'' (écouter des salutations). Station 3: ''Nos talents différents'' (montrer une habileté spéciale). Léo guide et célèbre chaque découverte.','Cercle de célébration de l''unicité. Léo demande: ''Qu''est-ce qui rend tes amis spéciaux et différents?'' Création d''un collage de classe: ''Nous sommes tous différents et c''est merveilleux!'' Chant: ''Vive nos différences!''','Développer l''amitié positive; Pratiquer les habiletés de vie quotidienne; Développer la régulation émotionnelle par des situations authentiques',NULL,NULL,NULL,'formative','{"observable":["L''élève écoute respectueusement la présentation des amis différents de Léo","L''élève participe positivement aux stations d''exploration des différences","L''élève montre du respect pour les différences des autres","L''élève contribue au collage de célébration de la diversité"],"checkpoints":["Début: Observer l''ouverture aux amis différents de Léo","Milieu: Vérifier les interactions respectueuses aux stations","Fin: Noter la participation positive au collage et à la célébration"]}',1,'Plan détaillé avec supports visuels',1756911653375,1757594653913,1,'fr','Formation personnelle et sociale','{"pourDifficultés":["Se concentrer sur des différences simples et observables (couleurs de cheveux, taille)","Utiliser beaucoup de modélage positif de la part de l''adulte","Célébrer chaque petit pas vers l''acceptation"],"pourAvancés":["Explorer des concepts plus complexes comme les cultures et traditions","Encourager à être des ambassadeurs de l''inclusion","Discuter de comment aider quelqu''un qui se sent différent"],"pourLangue":["Célébrer spécifiquement leur multilinguisme comme une richesse","Utiliser leur expertise culturelle comme un atout pour la classe","Permettre de partager des éléments de leur culture d''origine"],"pourPEI":["Célébrer leurs forces uniques et contributions spéciales","Utiliser leurs intérêts particuliers comme ponts vers l''inclusion","Utiliser supports visuels agrandis selon besoins visuels","Permettre réponses par pointage ou sélection d''images"]}','{"vocabulary":["différent","unique","accepter"],"visualSupports":["Collection visuelle d''amis différents, gestes TPR pour ''différent'', ''unique'', ''accepter'', images de diversité positive","Photos de diversité positive, cartes visuelles des différents talents, démonstrations de Léo célébrant chaque différence","Collage coloré et inclusif, routine de célébration positive, modèles de phrases pour décrire les différences positivement"],"movementBreaks":["Mouvement du chat, de l''oiseau, du poisson","Geste de célébration de la diversité","Danse des différences (chacun son mouvement)","Étirement ''je suis unique'' (pose personnelle)","Applaudissements pour la diversité","Mouvement de groupe inclusif"]}',NULL,NULL,NULL,NULL,'{"questions":["Les élèves ont-ils atteint les objectifs?","Quelles adaptations étaient nécessaires?","Que ferais-je différemment la prochaine fois?"]}',NULL,'',5,6,'core',1);
INSERT INTO ETFOLessonPlan VALUES('cmf43u3uo00ahvj9t5eiyb0af',23,'Inclure tout le monde','cmf43u3ui00a3vj9to9pgq6bi',1768924800000,45,'Léo présente pingouin et introduit inclure tout le monde. Comptine thématique. Discussion: Comment pouvons-nous inviter les autres à jouer? Démonstration avec les marionnettes.','Exploration active de inclure tout le monde avec Léo. Activités pratiques pour inviter les autres à jouer. Stations d''apprentissage thématiques avec manipulation et interaction sociale guidée.','Retour au cercle avec Léo. Réflexion: ''Qu''avez-vous appris sur inclure tout le monde?'' Partage des découvertes et engagement personnel pour la semaine. Chanson de fermeture thématique.','Exprimer le concept de inclure tout; Pratiquer les habiletés de vie quotidienne; Développer la régulation émotionnelle par des situations authentiques','["Léo la marionnette","pingouin (marionnette/peluche)","Livre illustré ''inclure tout le monde''","Cartes visuelles du thème","Matériaux d''activité pour inviter les autres à jouer","Supports visuels thématiques","Tableau d''exploration du thème","Autocollants de réussite","Cartes de réflexion sur inclure tout le monde","Tableau des apprentissages","Léo la marionnette","Matériaux pour engagement personnel"]',NULL,'Inclure tout le monde','Léo présente pingouin et introduit inclure tout le monde. Comptine thématique. Discussion: Comment pouvons-nous inviter les autres à jouer? Démonstration avec les marionnettes.','Exploration active de inclure tout le monde avec Léo. Activités pratiques pour inviter les autres à jouer. Stations d''apprentissage thématiques avec manipulation et interaction sociale guidée.','Retour au cercle avec Léo. Réflexion: ''Qu''avez-vous appris sur inclure tout le monde?'' Partage des découvertes et engagement personnel pour la semaine. Chanson de fermeture thématique.','Exprimer le concept de inclure tout; Pratiquer les habiletés de vie quotidienne; Développer la régulation émotionnelle par des situations au