INSERT INTO ETFOLessonPlan VALUES('cmf43u3uy00b5vj9tr493rby8',23,'Célébration finale de l''amitié','cmf43u3ui00a3vj9to9pgq6bi',1772121600000,45,'Léo présente tout le groupe classe et introduit célébrer la croissance en amitié. Comptine thématique. Discussion: Comment pouvons-nous fête finale des apprentissages? Démonstration avec les marionnettes.','Exploration active de célébrer la croissance en amitié avec Léo. Activités pratiques pour fête finale des apprentissages. Stations d''apprentissage thématiques avec manipulation et interaction sociale guidée.','Retour au cercle avec Léo. Réflexion: ''Qu''avez-vous appris sur célébrer la croissance en amitié?'' Partage des découvertes et engagement personnel pour la semaine. Chanson de fermeture thématique.','Maintenir le concept de célébration finale; Pratiquer les habiletés de vie quotidienne; Développer la résilience par la célébration collective','["Léo la marionnette","tout le groupe classe (marionnette/peluche)","Livre illustré ''célébrer la croissance en amitié''","Cartes visuelles du thème","Matériaux d''activité pour fête finale des apprentissages","Supports visuels thématiques","Tableau d''exploration du thème","Autocollants de réussite","Cartes de réflexion sur célébrer la croissance en amitié","Tableau des apprentissages","Léo la marionnette","Matériaux pour engagement personnel"]',NULL,'Célébration finale de l''amitié','Léo présente tout le groupe classe et introduit célébrer la croissance en amitié. Comptine thématique. Discussion: Comment pouvons-nous fête finale des apprentissages? Démonstration avec les marionnettes.','Exploration active de célébrer la croissance en amitié avec Léo. Activités pratiques pour fête finale des apprentissages. Stations d''apprentissage thématiques avec manipulation et interaction sociale guidée.','Retour au cercle avec Léo. Réflexion: ''Qu''avez-vous appris sur célébrer la croissance en amitié?'' Partage des découvertes et engagement personnel pour la semaine. Chanson de fermeture thématique.','Maintenir le concept de célébration finale; Pratiquer les habiletés de vie quotidienne; Développer la résilience par la célébration collective',NULL,NULL,NULL,'formative','{"observable":["L''élève écoute attentivement l''introduction de célébrer la croissance en amitié","L''élève participe activement aux activités de fête finale des apprentissages","L''élève démontre une compréhension de célébrer la croissance en amitié par ses actions","L''élève engage dans la réflexion finale et prend un engagement personnel"],"checkpoints":["Début: Observer l''engagement initial avec le thème présenté","Milieu: Vérifier la participation et la compréhension de célébrer la croissance en amitié","Fin: Noter la qualité de la réflexion et l''engagement personnel pris"]}',1,'Plan détaillé avec supports visuels',1756911653386,1757594653926,1,'fr','Formation personnelle et sociale','{"pourDifficultés":["Simplifier célébrer la croissance en amitié avec des exemples très concrets","Permettre plus de temps et de soutien individuel","Utiliser des supports visuels additionnels et des gestes"],"pourAvancés":["Approfondir célébrer la croissance en amitié avec des nuances et des applications étendues","Encourager à aider leurs pairs dans leurs apprentissages","Explorer des connexions plus complexes avec d''autres concepts"],"pourLangue":["Utiliser beaucoup de supports visuels pour célébrer la croissance en amitié","Permettre l''expression dans leur langue maternelle si nécessaire","Jumeler avec des pairs francophones bienveillants"],"pourPEI":["Modifier les matériaux et les attentes selon les capacités","Utiliser des supports sensoriels appropriés","Utiliser supports visuels agrandis selon besoins visuels","Permettre réponses par pointage ou sélection d''images"]}','{"vocabulary":["ami","gentil","sain","grandir","heureux"],"visualSupports":["Supports visuels pour célébrer la croissance en amitié, gestes TPR pour le vocabulaire clé, expressions faciales démonstratrices","Démonstrations concrètes, séquences d''images pour fête finale des apprentissages, modélage constant de Léo","Routine de fermeture prévisible, supports visuels pour la réflexion sur célébrer la croissance en amitié, tableau des engagements"],"movementBreaks":["Geste thématique pour amitié","Mouvement d''expression du thème principal","Étirement thématique lié à célébrer la croissance en amitié","Mouvement coopératif de groupe","Geste de réflexion personnelle","Mouvement de célébration des apprentissages"]}',NULL,NULL,NULL,NULL,'{"questions":["Les élèves ont-ils atteint les objectifs?","Quelles adaptations étaient nécessaires?","Que ferais-je différemment la prochaine fois?"]}',NULL,'',5,19,'core',1);
INSERT INTO ETFOLessonPlan VALUES('cmf43u3v000b9vj9tt6dyxxuy',23,'Qu''est-ce que je ressens?','cmf43u3uz00b7vj9toxmjxb0a',1761750000000,45,'Cercle de découverte émotionnelle avec marionnette Émilie. Comptine: ''Comment tu te sens, mon petit cœur?'' Montrer des visages souriants et tristes avec miroir magique des émotions. TPR: mimer content (sourire, mains sur le cœur) et triste (moue, essuyer des larmes imaginaires).','Exploration émotionnelle interactive. Émilie la marionnette raconte ses journées: ''Hier j''étais contente parce que...'' Élèves écoutent et montrent l''émotion avec leur corps. Jeu du détective émotionnel: regarder des images et deviner ''Est-ce qu''Émilie est contente ou triste?'' Chaque élève choisit une carte émotion et mime pour les amis.','Retour au cercle. Émilie demande: ''Comment vous sentez-vous maintenant?'' Chaque élève choisit un autocollant émotion pour son cahier. Chanson de fermeture: ''Toutes mes émotions sont importantes, dans mon cœur elles restent!'' Câlin de groupe avec Émilie.','Identifier le concept de qu''est-ce que; Pratiquer les habiletés de vie quotidienne; Développer l''autonomie par des situations authentiques','["Marionnette Émilie (petit ourson en peluche)","Miroir magique des émotions (miroir décoré)","Cartes d''émotions visuelles (content/triste)","Livre d''images ''Les émotions de Petit Ours''","Histoires visuelles d''Émilie la marionnette","Cartes émotionnelles à grandes images","Boîte magique des émotions","Autocollants souriants et tristes","Cahiers personnels des élèves","Autocollants émotionnels","Carte de chanson illustrée","Émilie la marionnette"]',NULL,'Qu''est-ce que je ressens?','Cercle de découverte émotionnelle avec marionnette Émilie. Comptine: ''Comment tu te sens, mon petit cœur?'' Montrer des visages souriants et tristes avec miroir magique des émotions. TPR: mimer content (sourire, mains sur le cœur) et triste (moue, essuyer des larmes imaginaires).','Exploration émotionnelle interactive. Émilie la marionnette raconte ses journées: ''Hier j''étais contente parce que...'' Élèves écoutent et montrent l''émotion avec leur corps. Jeu du détective émotionnel: regarder des images et deviner ''Est-ce qu''Émilie est contente ou triste?'' Chaque élève choisit une carte émotion et mime pour les amis.','Retour au cercle. Émilie demande: ''Comment vous sentez-vous maintenant?'' Chaque élève choisit un autocollant émotion pour son cahier. Chanson de fermeture: ''Toutes mes émotions sont importantes, dans mon cœur elles restent!'' Câlin de groupe avec Émilie.','Identifier le concept de qu''est-ce que; Pratiquer les habiletés de vie quotidienne; Développer l''autonomie par des situations authentiques',NULL,NULL,NULL,'formative','{"observable":["L''élève prend soin de son corps et de sa santé","L''élève fait des choix sécuritaires dans ses activités","L''élève communique ses besoins clairement aux adultes","L''élève respecte les limites personnelles et celles des autres"],"checkpoints":["Comprend l''importance de l''hygiène personnelle","Reconnaît les situations dangereuses","Utilise des stratégies pour rester en sécurité","Fait confiance aux adultes responsables"]}',1,'Plan détaillé avec supports visuels',1756911653389,1757594653930,1,'fr','Formation personnelle et sociale','{"pourDifficultés":["Utiliser uniquement ''content'' et ''triste'' avec beaucoup de support visuel","Permettre la réponse par gestes plutôt que par mots","Offrir plus de temps avec la marionnette en individuel"],"pourAvancés":["Introduire ''très content'' et ''un peu triste'' pour nuancer","Encourager à aider leurs pairs à identifier les émotions","Permettre de raconter des histoires d''émotions plus complexes"],"pourLangue":["Utiliser des supports visuels très clairs et répétés","Permettre l''expression dans leur langue maternelle si nécessaire","Jumeler avec un pair francophone pour le soutien"],"pourPEI":["Adapter selon les besoins sensoriels individuels","Utiliser des aides technologiques si approprié","Modifier les attentes selon les objectifs du PEI"]}','{"vocabulary":["content","triste","émotions"],"visualSupports":["Cartes visuelles avec visages expressifs, gestuelle TPR pour chaque émotion, expressions faciales exagérées de l''enseignant(e)","Séquences d''images émotionnelles, expressions corporelles marquées, gestuelle constante pour renforcer chaque émotion","Geste du cœur pour la chanson finale, cercle visuel pour le retour au calme, routine prévisible de fermeture"],"movementBreaks":["Geste du cœur content (mains sur le cœur)","Mouvement triste (essuyer larmes doucement)","Respiration de petit ours (lente et profonde)","Étirement des bras ''content comme un oiseau''","Câlin de groupe doux","Geste du cœur pour la chanson"]}',NULL,NULL,NULL,NULL,'{"questions":["Les élèves ont-ils atteint les objectifs?","Quelles adaptations étaient nécessaires?","Que ferais-je différemment la prochaine fois?"]}',NULL,'',5,1,'core',1);
INSERT INTO ETFOLessonPlan VALUES('cmf43u3v100bbvj9t18l4whfs',23,'Mon visage montre mes émotions','cmf43u3uz00b7vj9toxmjxb0a',1761922800000,45,'Jeu du miroir magique. Émilie montre son visage dans le miroir: ''Regardez mon visage!'' Faire des expressions exagérées (fâché = sourcils froncés, peur = yeux grands ouverts). Comptine: ''Mon visage raconte mes histoires, dans mes yeux tu peux voir!'' Chaque élève se regarde dans le miroir.','Exploration des visages émotionnels. Galerie de portraits: regarder des photos de vrais enfants avec différentes émotions. Jeu ''Devine l''émotion'': un élève fait une expression, les autres devinent. Émilie raconte: ''Quand mon visage montre fâché...'' Créer un livre collectif des visages émotionnels avec photos des élèves (optionnel).','Retour au grand miroir. Chaque élève montre à Émilie son expression préférée. Chanson finale: ''Mon visage, c''est ma voix, il raconte tout de moi!'' Ranger les petits miroirs en disant merci pour les découvertes. Câlin facial doux avec Émilie.','Explorer les émotions de base; Pratiquer des stratégies de gestion émotionnelle; Développer l''autonomie par des situations authentiques','["Grand miroir incassable décoré","Petits miroirs individuels","Cartes d''expressions faciales (fâché/peur/content)","Émilie la marionnette","Photos d''enfants avec expressions émotionnelles variées","Caméra Polaroid ou tablette (optionnel)","Carnet collectif pour livre des visages","Autocollants d''émotions faciales","Grand miroir pour fermeture","Petits miroirs à ranger","Chanson illustrée du visage","Émilie la marionnette"]',NULL,'Mon visage montre mes émotions','Jeu du miroir magique. Émilie montre son visage dans le miroir: ''Regardez mon visage!'' Faire des expressions exagérées (fâché = sourcils froncés, peur = yeux grands ouverts). Comptine: ''Mon visage raconte mes histoires, dans mes yeux tu peux voir!'' Chaque élève se regarde dans le miroir.','Exploration des visages émotionnels. Galerie de portraits: regarder des photos de vrais enfants avec différentes émotions. Jeu ''Devine l''émotion'': un élève fait une expression, les autres devinent. Émilie raconte: ''Quand mon visage montre fâché...'' Créer un livre collectif des visages émotionnels avec photos des élèves (optionnel).','Retour au grand miroir. Chaque élève montre à Émilie son expression préférée. Chanson finale: ''Mon visage, c''est ma voix, il raconte tout de moi!'' Ranger les petits miroirs en disant merci pour les découvertes. Câlin facial doux avec Émilie.','Explorer les émotions de base; Pratiquer des stratégies de gestion émotionnelle; Développer l''autonomie par des situations authentiques',NULL,NULL,NULL,'formative','{"observable":["L''élève nomme 4 émotions de base: joie, tristesse, colère, peur","L''élève reconnaît les émotions sur les visages des autres","L''élève explique: ''Quand je suis triste, je peux demander de l''aide''","L''élève utilise des mots au lieu de gestes agressifs"],"checkpoints":["Identifie ses propres émotions avec des mots précis","Utilise des stratégies pour se calmer quand nécessaire","Respecte les émotions des autres enfants","Demande l''aide d''un adulte quand il en a besoin"]}',1,'Plan détaillé avec supports visuels',1756911653389,1757594653931,1,'fr','Formation personnelle et sociale','{"pourDifficultés":["Se concentrer sur ''content'' et ''triste'' seulement avec gestes très marqués","Utiliser uniquement Émilie la marionnette pour les expressions difficiles","Permettre d''observer sans participer activement aux mimiques"],"pourAvancés":["Ajouter ''surpris'' et ''timide'' aux expressions faciales","Encourager à créer des histoires sur les expressions vues","Inviter à guider les pairs dans la reconnaissance faciale"],"pourLangue":["Utiliser beaucoup de mime et de gestes plutôt que de mots","Permettre de nommer dans leur langue maternelle puis répéter en français","Fournir des cartes visuelles avec mots dans les deux langues"],"pourPEI":["Adapter les miroirs selon les besoins sensoriels (taille, distance)","Modifier les attentes selon la capacité de reconnaissance visuelle","Utiliser des supports tactiles si les supports visuels sont inadaptés"]}','{"vocabulary":["visage","fâché","peur"],"visualSupports":["Expressions faciales très marquées de l''enseignant(e), cartes visuelles montées sur bâtons, miroirs pour auto-observation","Photos réelles d''enfants, démonstrations corporelles, expressions faciales modelées par l''enseignant(e)","Routine de rangement visuelle, chanson avec gestes pour le visage, expressions finales positives"],"movementBreaks":["Toucher doucement son propre visage","Faire des grimaces amusantes","Massage doux du visage (tempes, joues)","Exercices faciaux (ouvrir/fermer les yeux, sourire/froncer)","Câlin facial doux (mains sur les joues)","Sourire final partagé"]}',NULL,NULL,NULL,NULL,'{"questions":["Les élèves ont-ils atteint les objectifs?","Quelles adaptations étaient nécessaires?","Que ferais-je différemment la prochaine fois?"]}',NULL,'',5,2,'core',1);
INSERT INTO ETFOLessonPlan VALUES('cmf43u3v200bdvj9tvylgfr7q',23,'Mon corps ressent aussi','cmf43u3uz00b7vj9toxmjxb0a',1762272000000,45,'Écoute ton corps avec Émilie. Utiliser un stéthoscope jouet pour écouter les battements de cœur. Comptine corporelle: ''Mon cœur bat fort quand je suis content!'' Exercice calme: mains sur le cœur, puis sur le ventre. Émilie montre où elle ressent ses émotions sur son corps de peluche.','Découverte des sensations corporelles. Émilie raconte: ''Quand je suis contente, mon cœur danse!'' Placer des autocollants sur la silhouette géante pour marquer où on ressent les émotions. Exercice de conscience corporelle: sentir son cœur battre après avoir sauté, remarquer son ventre quand on respire profondément. Créer une carte corporelle personnelle.','Moment de gratitude corporelle. Remercier son corps: ''Merci mon cœur, merci mon ventre!'' Placer les mains sur différentes parties du corps en disant merci. Émilie fait un câlin corporel doux. Ranger les matériaux en étant conscient de ses mains qui bougent.','Découvrir le corps et ses besoins; Pratiquer les habiletés de vie quotidienne; Développer l''autonomie par des situations authentiques','["Stéthoscope jouet (sécuritaire)","Silhouette géante du corps humain","Autocollants de cœur et d''étoiles colorées","Émilie la marionnette avec marqueurs corporels","Autocollants de formes variées (cœurs, étoiles, nuages)","Feuilles individuelles avec silhouette corporelle","Crayons de couleur","Petites balles de stress (douces et sécuritaires)","Cartes personnelles terminées","Chanson de gratitude corporelle","Émilie pour câlins finaux","Boîte de rangement décorée"]',NULL,'Mon corps ressent aussi','Écoute ton corps avec Émilie. Utiliser un stéthoscope jouet pour écouter les battements de cœur. Comptine corporelle: ''Mon cœur bat fort quand je suis content!'' Exercice calme: mains sur le cœur, puis sur le ventre. Émilie montre où elle ressent ses émotions sur son corps de peluche.','Découverte des sensations corporelles. Émilie raconte: ''Quand je suis contente, mon cœur danse!'' Placer des autocollants sur la silhouette géante pour marquer où on ressent les émotions. Exercice de conscience corporelle: sentir son cœur battre après avoir sauté, remarquer son ventre quand on respire profondément. Créer une carte corporelle personnelle.','Moment de gratitude corporelle. Remercier son corps: ''Merci mon cœur, merci mon ventre!'' Placer les mains sur différentes parties du corps en disant merci. Émilie fait un câlin corporel doux. Ranger les matériaux en étant conscient de ses mains qui bougent.','Découvrir le corps et ses besoins; Pratiquer les habiletés de vie quotidienne; Développer l''autonomie par des situations authentiques',NULL,NULL,NULL,'formative','{"observable":["L''élève prend soin de son corps et de sa santé","L''élève fait des choix sécuritaires dans ses activités","L''élève communique ses besoins clairement aux adultes","L''élève respecte les limites personnelles et celles des autres"],"checkpoints":["Comprend l''importance de l''hygiène personnelle","Reconnaît les situations dangereuses","Utilise des stratégies pour rester en sécurité","Fait confiance aux adultes responsables"]}',1,'Plan détaillé avec supports visuels',1756911653390,1757594653932,1,'fr','Formation personnelle et sociale','{"pourDifficultés":["Se concentrer uniquement sur cœur et respiration avec Émilie comme guide","Utiliser moins d''autocollants, plus de démonstration","Permettre d''observer plutôt que de participer activement"],"pourAvancés":["Explorer plus de parties du corps (mains, pieds, tête)","Encourager à décrire les sensations avec plus de détail","Inviter à aider les pairs à découvrir leurs sensations"],"pourLangue":["Utiliser beaucoup de gestes et de toucher doux pour enseigner","Répéter les mots corporels avec pointage constant","Utiliser des chansons corporelles simples et répétitives"],"pourPEI":["Adapter selon les besoins sensoriels (aucun toucher si nécessaire)","Modifier les outils selon les capacités motrices","Ajuster les attentes selon la conscience corporelle individuelle"]}','{"vocabulary":["corps","cœur","ventre"],"visualSupports":["Silhouette corporelle affichée, gestes pour localiser cœur et ventre, démonstrations avec Émilie","Carte corporelle collective, démonstrations avec gestes, autocollants visuels pour marquer les zones","Routine de gratitude avec gestes, chanson illustrée, câlin visuel avec Émilie"],"movementBreaks":["Respiration avec les mains sur le cœur","Caresser doucement son ventre (auto-apaisement)","Sauts légers pour sentir le cœur","Respiration ventrale profonde et lente","Caresses douces sur les bras (auto-apaisement)","Câlin de soi-même"]}',NULL,NULL,NULL,NULL,'{"questions":["Les élèves ont-ils atteint les objectifs?","Quelles adaptations étaient nécessaires?","Que ferais-je différemment la prochaine fois?"]}',NULL,'',5,3,'core',1);
INSERT INTO ETFOLessonPlan VALUES('cmf43u3v300bfvj9tokaywgcw',23,'Toutes les émotions sont normales','cmf43u3uz00b7vj9toxmjxb0a',1762444800000,45,'Cercle d''acceptation avec la Boîte Arc-en-ciel des Émotions. Émilie sort différentes émotions colorées: ''Toutes mes émotions sont importantes!'' Comptine: ''Content, triste, fâché, peur... tous sont normal dans mon cœur!'' Chaque élève choisit une émotion et la place dans l''arc-en-ciel collectif.','Exploration de la normalité émotionnelle. Émilie raconte des histoires: ''Un jour j''étais fâchée et c''était normal parce que...'' Créer un livre collectif ''Nos Émotions Normales'' avec dessins ou autocollants. Jeu des émotions météo: ''Aujourd''hui mon cœur est ensoleillé/nuageux/orageux et c''est normal!''','Célébration de la diversité émotionnelle. Chaque élève place sa main sur l''arc-en-ciel collectif et dit: ''Mes émotions sont normales!'' Chanson finale: ''Dans l''arc-en-ciel de mon cœur, toutes les couleurs ont leur tour!'' Émilie donne un câlin d''acceptation à chacun.','Coopérer les émotions de base; Pratiquer des stratégies de gestion émotionnelle; Développer l''autonomie par des situations authentiques','["Boîte Arc-en-ciel des Émotions décorée","Cartes émotions de toutes les couleurs","Grande affiche arc-en-ciel pour le mur","Émilie avec sa propre boîte d''émotions","Histoires d''Émilie illustrées","Grand cahier pour livre collectif","Autocollants météo et émotions","Roue des émotions météo","Arc-en-ciel collectif terminé","Chanson illustrée de l''arc-en-ciel","Certificats ''Mes Émotions Normales'' (optionnel)","Émilie pour câlins finaux"]',NULL,'Toutes les émotions sont normales','Cercle d''acceptation avec la Boîte Arc-en-ciel des Émotions. Émilie sort différentes émotions colorées: ''Toutes mes émotions sont importantes!'' Comptine: ''Content, triste, fâché, peur... tous sont normal dans mon cœur!'' Chaque élève choisit une émotion et la place dans l''arc-en-ciel collectif.','Exploration de la normalité émotionnelle. Émilie raconte des histoires: ''Un jour j''étais fâchée et c''était normal parce que...'' Créer un livre collectif ''Nos Émotions Normales'' avec dessins ou autocollants. Jeu des émotions météo: ''Aujourd''hui mon cœur est ensoleillé/nuageux/orageux et c''est normal!''','Célébration de la diversité émotionnelle. Chaque élève place sa main sur l''arc-en-ciel collectif et dit: ''Mes émotions sont normales!'' Chanson finale: ''Dans l''arc-en-ciel de mon cœur, toutes les couleurs ont leur tour!'' Émilie donne un câlin d''acceptation à chacun.','Coopérer les émotions de base; Pratiquer des stratégies de gestion émotionnelle; Développer l''autonomie par des situations authentiques',NULL,NULL,NULL,'formative','{"observable":["L''élève nomme 4 émotions de base: joie, tristesse, colère, peur","L''élève reconnaît les émotions sur les visages des autres","L''élève explique: ''Quand je suis triste, je peux demander de l''aide''","L''élève utilise des mots au lieu de gestes agressifs"],"checkpoints":["Identifie ses propres émotions avec des mots précis","Utilise des stratégies pour se calmer quand nécessaire","Respecte les émotions des autres enfants","Demande l''aide d''un adulte quand il en a besoin"]}',1,'Plan détaillé avec supports visuels',1756911653391,1757594653933,1,'fr','Formation personnelle et sociale','{"pourDifficultés":["Utiliser seulement 3-4 émotions de base avec beaucoup de répétition","Se concentrer sur le message ''C''est correct de ressentir'' avec Émilie","Utiliser plus d''autocollants, moins de discussion verbale"],"pourAvancés":["Explorer les nuances: ''un peu fâché'' vs ''très fâché''","Discuter pourquoi certaines émotions arrivent dans certaines situations","Inviter à créer des histoires d''acceptation pour les pairs"],"pourLangue":["Utiliser beaucoup de visuels et de gestes pour ''normal'' et ''accepter''","Répéter les concepts avec des exemples concrets et universels","Permettre l''expression dans la langue maternelle puis traduire ensemble"],"pourPEI":["Adapter le concept d''acceptation selon la compréhension individuelle","Utiliser des supports visuels personnalisés si nécessaire","Modifier les attentes selon les besoins émotionnels spécifiques"]}','{"vocabulary":["normal","accepter","tous"],"visualSupports":["Arc-en-ciel visuel des émotions, cartes colorées organisées, geste d''acceptation (mains sur le cœur)","Livre en construction visible, métaphores météo avec images, expressions rassurantes constantes","Arc-en-ciel complété bien visible, routine positive de fermeture, gestes d''acceptation partagés"],"movementBreaks":["Geste d''acceptation (mains sur le cœur)","Mouvement arc-en-ciel (bras en arc au-dessus de la tête)","Respiration arc-en-ciel (inspirer toutes les couleurs)","Danser comme la météo de son cœur","Câlin d''acceptation de soi","Salut arc-en-ciel (geste final partagé)"]}',NULL,NULL,NULL,NULL,'{"questions":["Les élèves ont-ils atteint les objectifs?","Quelles adaptations étaient nécessaires?","Que ferais-je différemment la prochaine fois?"]}',NULL,'',5,4,'core',1);
INSERT INTO ETFOLessonPlan VALUES('cmf43u3v400bhvj9tygtkidem',23,'Dire mes sentiments','cmf43u3uz00b7vj9toxmjxb0a',1762876800000,45,'Téléphone émotionnel avec Émilie. Utiliser un faux téléphone coloré. Émilie appelle: ''Allo! Comment tu te sens?'' Modèle de phrases: ''Je me sens content'', ''Je me sens triste''. Comptine du téléphone: ''Allo, allo, je peux te dire, ce que je ressens dans mon cœur!'' Chaque élève répond au téléphone d''Émilie.','Pratique d''expression émotionnelle. Jeu de rôle: Émilie a différents problèmes et demande de l''aide (''Je me sens triste parce que j''ai perdu mon jouet''). Élèves répondent avec empathie. Créer un ''Guide de Communication Émotionnelle'' avec dessins et phrases simples. Station de pratique: parler à différents amis (marionnettes).','Cérémonie de communication. Chaque élève dit à Émilie: ''Maintenant je peux dire mes sentiments!'' Tour de cercle: chaque élève partage UNE émotion qu''il ressent maintenant. Applaudissements pour tous. Chanson finale: ''Mes mots sont importants, mes sentiments aussi!'' Ranger les téléphones en disant merci.','Pratiquer le concept de dire mes; Pratiquer les habiletés de vie quotidienne; Développer la régulation émotionnelle par des situations authentiques','["Téléphone jouet coloré (2-3 exemplaires)","Cartes phrases avec images ''Je me sens...''","Support visuel pour structures de phrases","Émilie avec son propre petit téléphone","Marionnettes diverses pour amis (3-4 personnages)","Scénarios simples illustrés pour Émilie","Cahier collectif pour guide de communication","Autocollants récompenses pour tentatives","Téléphones à ranger cérémonieusement","Guide de communication terminé","Chanson d''autonomie illustrée","Émilie pour félicitations finales"]',NULL,'Dire mes sentiments','Téléphone émotionnel avec Émilie. Utiliser un faux téléphone coloré. Émilie appelle: ''Allo! Comment tu te sens?'' Modèle de phrases: ''Je me sens content'', ''Je me sens triste''. Comptine du téléphone: ''Allo, allo, je peux te dire, ce que je ressens dans mon cœur!'' Chaque élève répond au téléphone d''Émilie.','Pratique d''expression émotionnelle. Jeu de rôle: Émilie a différents problèmes et demande de l''aide (''Je me sens triste parce que j''ai perdu mon jouet''). Élèves répondent avec empathie. Créer un ''Guide de Communication Émotionnelle'' avec dessins et phrases simples. Station de pratique: parler à différents amis (marionnettes).','Cérémonie de communication. Chaque élève dit à Émilie: ''Maintenant je peux dire mes sentiments!'' Tour de cercle: chaque élève partage UNE émotion qu''il ressent maintenant. Applaudissements pour tous. Chanson finale: ''Mes mots sont importants, mes sentiments aussi!'' Ranger les téléphones en disant merci.','Pratiquer le concept de dire mes; Pratiquer les habiletés de vie quotidienne; Développer la régulation émotionnelle par des situations authentiques',NULL,NULL,NULL,'formative','{"observable":["L''élève nomme 4 émotions de base: joie, tristesse, colère, peur","L''élève reconnaît les émotions sur les visages des autres","L''élève explique: ''Quand je suis triste, je peux demander de l''aide''","L''élève utilise des mots au lieu de gestes agressifs"],"checkpoints":["Identifie ses propres émotions avec des mots précis","Utilise des stratégies pour se calmer quand nécessaire","Respecte les émotions des autres enfants","Demande l''aide d''un adulte quand il en a besoin"]}',1,'Plan détaillé avec supports visuels',1756911653392,1757594653934,1,'fr','Formation personnelle et sociale','{"pourDifficultés":["Accepter un mot seul ou un geste pour exprimer l''émotion","Utiliser plus de cartes visuelles avec phrases pré-écrites","Permettre plus de temps et de répétition avec Émilie"],"pourAvancés":["Encourager l''ajout de ''parce que'' dans leurs phrases","Inviter à consoler et répondre aux émotions des marionnettes","Permettre de créer leurs propres scénarios émotionnels"],"pourLangue":["Répéter les structures de phrases avec beaucoup de modèles","Utiliser des gestes et des images pour soutenir chaque mot","Permettre la traduction initiale puis la pratique en français"],"pourPEI":["Adapter les modes de communication selon les besoins individuels","Utiliser la technologie d''assistance si nécessaire","Modifier les attentes d''expression selon les capacités verbales"]}','{"vocabulary":["dire","sentir","parler"],"visualSupports":["Structures de phrases visuelles, cartes de soutien, modèle constant avec Émilie au téléphone","Scénarios en images, structures de réponse affichées, démonstrations constantes avec marionnettes","Routine de célébration visuelle, guide terminé bien visible, gestes de félicitation partagés"],"movementBreaks":["Geste de tenir le téléphone à l''oreille","Mouvement de parler (geste de la bouche)","Échange de marionnettes (mouvement et choix)","Gestes d''empathie (câlin, tape sur l''épaule)","Applaudissements pour tous","Geste de ''parler'' (main sur le cœur, puis vers l''extérieur)"]}',NULL,NULL,NULL,NULL,'{"questions":["Les élèves ont-ils atteint les objectifs?","Quelles adaptations étaient nécessaires?","Que ferais-je différemment la prochaine fois?"]}',NULL,'',5,5,'core',1);
INSERT INTO ETFOLessonPlan VALUES('cmf43u3v500bjvj9tal0go1m9',23,'Quand je suis content','cmf43u3uz00b7vj9toxmjxb0a',1763049600000,45,'Fête de la joie avec Émilie! Bulles de savon magiques qui apportent le bonheur. Émilie danse: ''Je suis contente, je suis heureuse!'' Comptine joyeuse: ''Quand je suis content, mon cœur fait la fête!'' Chaque élève attrape des bulles et dit ce qui le rend heureux. Mouvements de joie: sautiller, battre des mains, tourner.','Exploration de la joie appropriée. Émilie enseigne: ''Il y a différentes façons d''être content!'' Démonstration: joie calme (sourire, mains sur cœur), joie moyenne (rire, applaudissements), grande joie (sauter, crier de joie doucement). Créer un ''Livre de nos Joies'' avec dessins de ce qui rend chacun heureux. Pratiquer la joie respectueuse adaptée aux situations.','Célébration joyeuse collective. Tour de cercle: chaque élève montre sa façon préférée d''être content. Créer un ''Sourire Collectif'' - tous sourient ensemble et se regardent. Chanson finale calme: ''Ma joie est précieuse, je la garde dans mon cœur!'' Émilie donne un câlin joyeux mais doux à chacun.','Développer le concept de quand je; Raconter les habiletés de vie quotidienne; Développer la régulation émotionnelle par la narration','["Machine à bulles ou bulles manuelles","Musique joyeuse douce","Rubans colorés pour danser","Émilie décorée avec des autocollants souriants","Cartes de niveaux de joie avec images","Grand cahier pour livre collectif des joies","Crayons de couleurs vives","Miroir pour observer ses expressions joyeuses","Livre des joies terminé à montrer","Appareil photo pour capturer le sourire collectif (optionnel)","Chanson douce illustrée","Émilie pour câlins joyeux finaux"]',NULL,'Quand je suis content','Fête de la joie avec Émilie! Bulles de savon magiques qui apportent le bonheur. Émilie danse: ''Je suis contente, je suis heureuse!'' Comptine joyeuse: ''Quand je suis content, mon cœur fait la fête!'' Chaque élève attrape des bulles et dit ce qui le rend heureux. Mouvements de joie: sautiller, battre des mains, tourner.','Exploration de la joie appropriée. Émilie enseigne: ''Il y a différentes façons d''être content!'' Démonstration: joie calme (sourire, mains sur cœur), joie moyenne (rire, applaudissements), grande joie (sauter, crier de joie doucement). Créer un ''Livre de nos Joies'' avec dessins de ce qui rend chacun heureux. Pratiquer la joie respectueuse adaptée aux situations.','Célébration joyeuse collective. Tour de cercle: chaque élève montre sa façon préférée d''être content. Créer un ''Sourire Collectif'' - tous sourient ensemble et se regardent. Chanson finale calme: ''Ma joie est précieuse, je la garde dans mon cœur!'' Émilie donne un câlin joyeux mais doux à chacun.','Développer le concept de quand je; Raconter les habiletés de vie quotidienne; Développer la régulation émotionnelle par la narration',NULL,NULL,NULL,'formative','{"observable":["L''élève prend soin de son corps et de sa santé","L''élève fait des choix sécuritaires dans ses activités","L''élève communique ses besoins clairement aux adultes","L''élève respecte les limites personnelles et celles des autres"],"checkpoints":["Comprend l''importance de l''hygiène personnelle","Reconnaît les situations dangereuses","Utilise des stratégies pour rester en sécurité","Fait confiance aux adultes responsables"]}',1,'Plan détaillé avec supports visuels',1756911653393,1757594653935,1,'fr','Formation personnelle et sociale','{"pourDifficultés":["Se concentrer sur joie calme et sourires simples avec Émilie","Utiliser moins de stimulation (moins de bulles, musique plus douce)","Permettre d''observer la joie des autres sans obligation de participer activement"],"pourAvancés":["Explorer différentes intensités de joie et leurs contextes appropriés","Encourager à aider leurs pairs à trouver leur façon d''être content","Inviter à créer des histoires joyeuses pour le livre collectif"],"pourLangue":["Utiliser beaucoup de gestes et d''expressions faciales pour enseigner les nuances","Répéter ''content'', ''heureux'', ''joie'' avec des démonstrations claires","Permettre l''expression de la joie dans leur langue maternelle d''abord"],"pourPEI":["Adapter le niveau de stimulation selon les besoins sensoriels","Modifier les attentes d''expression selon les capacités individuelles","Utiliser des supports visuels personnalisés pour les niveaux de joie"]}','{"vocabulary":["joie","heureux","excité"],"visualSupports":["Bulles visibles et amusantes, mouvements de danse démontrés, expressions faciales très joyeuses","Niveaux de joie illustrés clairement, démonstrations continues avec Émilie, exemples visuels de joie appropriée","Livre terminé visible, routine de sourire partagé, gestes doux pour la chanson finale"],"movementBreaks":["Sautillements joyeux sur place","Battements de mains rythmiques","Pratiquer la joie calme (balancement doux)","Pratiquer la grande joie (sauts contrôlés)","Sourire collectif partagé","Câlins joyeux mais calmes"]}',NULL,NULL,NULL,NULL,'{"questions":["Les élèves ont-ils atteint les objectifs?","Quelles adaptations étaient nécessaires?","Que ferais-je différemment la prochaine fois?"]}',NULL,'',5,6,'core',1);
INSERT INTO ETFOLessonPlan VALUES('cmf43u3v500blvj9tmbl6un86',23,'Quand je suis triste','cmf43u3uz00b7vj9toxmjxb0a',1763395200000,45,'Cercle de réconfort avec Émilie qui se sent triste. Histoire: ''Hier Émilie était triste parce que son ami n''était pas là.'' Chanson douce: ''Quand mon cœur est triste, j''ai besoin d''amour.'' Introduction de la boîte à réconfort avec objets doux. TPR: geste de câlin (bras croisés sur le cœur) et mouvement de consoler doucement.','Exploration du réconfort. Émilie montre différentes façons de se consoler: câlin avec doudou, respiration douce, demander de l''aide. Jeu ''Qui peut consoler Émilie?'': élèves proposent des gestes doux. Création d''un coin réconfort dans la classe avec coussins et objets doux. Chaque élève pratique demander un câlin à Émilie.','Retour au cercle avec Émilie qui se sent mieux. Chanson: ''Quand je suis triste, je demande de l''aide, et mon cœur se sent mieux!'' Chaque élève choisit un objet réconfortant à garder sur son bureau. Câlin de groupe doux optionnel. Message final: ''Il est normal d''être triste parfois.''','Exprimer le concept de quand je; Pratiquer les habiletés de vie quotidienne; Développer la régulation émotionnelle par des situations authentiques','["Émilie la marionnette (avec expression triste)","Boîte à réconfort (tissu doux, petit coussin, photo de famille)","Livre illustré ''Quand Petit Ours est triste''","Musique douce de fond","Coussins doux et couvertures","Doudous et peluches diverses","Cartes visuelles des gestes de réconfort","Boîte à mouchoirs décorée","Petits objets réconfortants (pierres douces, autocollants cœur)","Chanson illustrée du réconfort","Émilie souriante maintenant","Miroir pour vérifier les sourires retrouvés"]',NULL,'Quand je suis triste','Cercle de réconfort avec Émilie qui se sent triste. Histoire: ''Hier Émilie était triste parce que son ami n''était pas là.'' Chanson douce: ''Quand mon cœur est triste, j''ai besoin d''amour.'' Introduction de la boîte à réconfort avec objets doux. TPR: geste de câlin (bras croisés sur le cœur) et mouvement de consoler doucement.','Exploration du réconfort. Émilie montre différentes façons de se consoler: câlin avec doudou, respiration douce, demander de l''aide. Jeu ''Qui peut consoler Émilie?'': élèves proposent des gestes doux. Création d''un coin réconfort dans la classe avec coussins et objets doux. Chaque élève pratique demander un câlin à Émilie.','Retour au cercle avec Émilie qui se sent mieux. Chanson: ''Quand je suis triste, je demande de l''aide, et mon cœur se sent mieux!'' Chaque élève choisit un objet réconfortant à garder sur son bureau. Câlin de groupe doux optionnel. Message final: ''Il est normal d''être triste parfois.''','Exprimer le concept de quand je; Pratiquer les habiletés de vie quotidienne; Développer la régulation émotionnelle par des situations authentiques',NULL,NULL,NULL,'formative','{"observable":["L''élève prend soin de son corps et de sa santé","L''élève fait des choix sécuritaires dans ses activités","L''élève communique ses besoins clairement aux adultes","L''élève respecte les limites personnelles et celles des autres"],"checkpoints":["Comprend l''importance de l''hygiène personnelle","Reconnaît les situations dangereuses","Utilise des stratégies pour rester en sécurité","Fait confiance aux adultes responsables"]}',1,'Plan détaillé avec supports visuels',1756911653394,1757594653936,1,'fr','Formation personnelle et sociale','{"pourDifficultés":["Se concentrer sur ''triste'' et ''câlin'' uniquement avec objets de réconfort tangibles","Permettre l''expression par les gestes plutôt que par les mots","Offrir plus de temps individuel avec objets réconfortants"],"pourAvancés":["Explorer différents types de tristesse (déçu, nostalgique, inquiet)","Encourager à consoler leurs pairs avec des gestes appropriés","Discuter de quand demander l''aide d''un adulte versus d''un ami"],"pourLangue":["Utiliser des objets réconfortants universels et beaucoup de gestuelle","Permettre l''expression des émotions dans leur langue maternelle si nécessaire","Jumeler avec un pair francophone compatissant"],"pourPEI":["Adapter les objets réconfortants selon les besoins sensoriels","Utiliser des supports visuels personnalisés pour les stratégies de réconfort","Modifier les attentes selon les objectifs individuels du PEI"]}','{"vocabulary":["pleurer","consoler","réconfort"],"visualSupports":["Carte visuelle ''demander un câlin'', expressions faciales douces, gestes de réconfort modelés, environnement chaleureux et sécurisant","Séquence visuelle ''quand je suis triste'', coin réconfort bien défini, gestes de consolation modelés clairement","Progression visuelle triste→réconfort→mieux, routine de fermeture apaisante, objets tangibles de réconfort"],"movementBreaks":["Geste du câlin doux (bras sur le cœur)","Caresser doucement un tissu réconfortant","Respiration de réconfort (lente et apaisante)","Bercement doux assis au coin réconfort","Câlin de groupe doux et volontaire","Caresser l''objet réconfortant choisi"]}',NULL,NULL,NULL,NULL,'{"questions":["Les élèves ont-ils atteint les objectifs?","Quelles adaptations étaient nécessaires?","Que ferais-je différemment la prochaine fois?"]}',NULL,'',5,7,'core',1);
INSERT INTO ETFOLessonPlan VALUES('cmf43u3v600bnvj9t9lhxrxnl',23,'Quand je suis fâché','cmf43u3uz00b7vj9toxmjxb0a',1763568000000,45,'Cercle de découverte de la colère avec Émilie qui boude. Histoire: ''Émilie était fâchée quand quelqu''un a pris son jouet.'' Introduction du coussin de colère et de la bouteille magique de calme (avec paillettes). TPR: respiration de dragon (souffler lentement) et geste de calme (mains qui descendent).','Exploration de la gestion de colère. Émilie montre différentes façons de se calmer: respirer avec la bouteille magique, serrer le coussin de colère, compter jusqu''à cinq. Jeu ''Aide Émilie à se calmer'': élèves proposent des stratégies. Pratique de la respiration du dragon ensemble. Création d''un coin de calme avec outils de gestion.','Retour au cercle avec Émilie maintenant calme. Révision: ''Quand je suis fâché, je peux respirer, serrer un coussin, compter.'' Chaque élève choisit sa stratégie préférée et la mime. Chanson: ''Respire, compte, serre fort, et ton cœur retrouve le confort!'' Message: ''Il est correct d''être fâché, mais on peut apprendre à se calmer.''','Gérer le concept de quand je; Pratiquer les habiletés de vie quotidienne; Développer la régulation émotionnelle par des situations authentiques','["Émilie la marionnette (expression fâchée)","Coussin de colère rouge spécial","Bouteille de calme avec paillettes","Cartes visuelles ''fâché'' et ''calme''","Multiples bouteilles de calme","Coussins de différentes textures pour serrer","Timer visuel pour respirer","Cartes de stratégies de calme illustrées","Cartes stratégies individuelles pour chaque élève","Émilie maintenant souriante","Autocollants ''Je sais me calmer''","Chanson illustrée du calme"]',NULL,'Quand je suis fâché','Cercle de découverte de la colère avec Émilie qui boude. Histoire: ''Émilie était fâchée quand quelqu''un a pris son jouet.'' Introduction du coussin de colère et de la bouteille magique de calme (avec paillettes). TPR: respiration de dragon (souffler lentement) et geste de calme (mains qui descendent).','Exploration de la gestion de colère. Émilie montre différentes façons de se calmer: respirer avec la bouteille magique, serrer le coussin de colère, compter jusqu''à cinq. Jeu ''Aide Émilie à se calmer'': élèves proposent des stratégies. Pratique de la respiration du dragon ensemble. Création d''un coin de calme avec outils de gestion.','Retour au cercle avec Émilie maintenant calme. Révision: ''Quand je suis fâché, je peux respirer, serrer un coussin, compter.'' Chaque élève choisit sa stratégie préférée et la mime. Chanson: ''Respire, compte, serre fort, et ton cœur retrouve le confort!'' Message: ''Il est correct d''être fâché, mais on peut apprendre à se calmer.''','Gérer le concept de quand je; Pratiquer les habiletés de vie quotidienne; Développer la régulation émotionnelle par des situations authentiques',NULL,NULL,NULL,'formative','{"observable":["L''élève prend soin de son corps et de sa santé","L''élève fait des choix sécuritaires dans ses activités","L''élève communique ses besoins clairement aux adultes","L''élève respecte les limites personnelles et celles des autres"],"checkpoints":["Comprend l''importance de l''hygiène personnelle","Reconnaît les situations dangereuses","Utilise des stratégies pour rester en sécurité","Fait confiance aux adultes responsables"]}',1,'Plan détaillé avec supports visuels',1756911653395,1757594653937,1,'fr','Formation personnelle et sociale','{"pourDifficultés":["Se concentrer sur une seule technique: respiration du dragon avec support visuel","Utiliser des objets sensoriels (coussin texturé, bouteille tactile)","Permettre l''expression physique avant la technique de calme"],"pourAvancés":["Explorer différents niveaux de colère (irrité, fâché, très fâché)","Enseigner à reconnaître les signes avant-coureurs de colère","Encourager à aider leurs pairs avec des techniques de calme"],"pourLangue":["Utiliser beaucoup de démonstration physique et d''objets manipulables","Permettre l''expression initiale de colère dans leur langue maternelle","Jumeler avec un pair pour pratiquer les techniques ensemble"],"pourPEI":["Adapter les outils sensoriels selon les besoins individuels","Utiliser des supports visuels personnalisés et des horaires prévisibles","Modifier les techniques selon les capacités motrices de l''élève"]}','{"vocabulary":["colère","calmer","respirer"],"visualSupports":["Expressions faciales marquées pour ''fâché'' (sourcils froncés), gestes de respiration visibles, couleurs rouge (colère) et bleu (calme)","Séquence visuelle ''fâché→respire→calme'', coin de calme bien défini, démonstration claire des techniques de respiration","Progression visuelle fâché→techniques→calme, stratégies affichées clairement, routine de fermeture apaisante"],"movementBreaks":["Respiration du dragon (lente et contrôlée)","Secouer les mains pour évacuer la colère","Secouer tout le corps puis se détendre","Marche lente autour du coin de calme","Respiration finale profonde ensemble","Étirement relaxant des bras"]}',NULL,NULL,NULL,NULL,'{"questions":["Les élèves ont-ils atteint les objectifs?","Quelles adaptations étaient nécessaires?","Que ferais-je différemment la prochaine fois?"]}',NULL,'',5,8,'core',1);
INSERT INTO ETFOLessonPlan VALUES('cmf43u3v700bpvj9tpmj8wtx5',23,'Quand j''ai peur','cmf43u3uz00b7vj9toxmjxb0a',1763740800000,45,'Cercle de courage avec Émilie qui chuchote qu''elle a un peu peur. Histoire: ''Émilie a peur du noir parfois, mais elle sait demander de l''aide.'' Introduction du doudou courage et de la cape de super-héros. TPR: geste courage (poing sur le cœur) et signal d''aide (main levée). Chanson douce: ''Quand j''ai peur, je demande de l''aide.''','Exploration du courage et de l''aide. Émilie montre comment elle devient courageuse: tenir son doudou, respirer profondément, demander de l''aide à un adulte. Jeu ''Qui peut aider Émilie?'': identifier les personnes sécuritaires (parents, enseignants, pompiers). Pratique du signal d''aide et du geste courage. Création d''une boîte à courage avec objets réconfortants.','Retour au cercle avec Émilie maintenant courageuse grâce à l''aide reçue. Révision: ''Quand j''ai peur, je peux tenir mon doudou, respirer, demander de l''aide.'' Chaque élève choisit un objet courage à emporter. Chanson finale: ''Je suis courageux, je peux demander de l''aide!'' Message: ''Il est normal d''avoir peur, et c''est intelligent de demander de l''aide.''','Coopérer le concept de quand j''ai; Pratiquer les habiletés de vie quotidienne; Développer les habiletés sociales par des situations authentiques','["Émilie la marionnette (expression inquiète)","Doudou courage spécial (ours ou lapin doux)","Cape de super-héros miniature","Cartes visuelles ''peur'' et ''courageux''","Photos de personnes sécuritaires (parents, enseignants, pompiers)","Boîte à courage décorée","Multiples doudous et objets réconfortants","Cartes visuelles ''demander aide'' illustrées","Petits objets courage pour chaque élève (pierre douce, autocollant étoile)","Émilie maintenant souriante et confiante","Certificats ''Je suis courageux'' illustrés","Chanson du courage avec gestes"]',NULL,'Quand j''ai peur','Cercle de courage avec Émilie qui chuchote qu''elle a un peu peur. Histoire: ''Émilie a peur du noir parfois, mais elle sait demander de l''aide.'' Introduction du doudou courage et de la cape de super-héros. TPR: geste courage (poing sur le cœur) et signal d''aide (main levée). Chanson douce: ''Quand j''ai peur, je demande de l''aide.''','Exploration du courage et de l''aide. Émilie montre comment elle devient courageuse: tenir son doudou, respirer profondément, demander de l''aide à un adulte. Jeu ''Qui peut aider Émilie?'': identifier les personnes sécuritaires (parents, enseignants, pompiers). Pratique du signal d''aide et du geste courage. Création d''une boîte à courage avec objets réconfortants.','Retour au cercle avec Émilie maintenant courageuse grâce à l''aide reçue. Révision: ''Quand j''ai peur, je peux tenir mon doudou, respirer, demander de l''aide.'' Chaque élève choisit un objet courage à emporter. Chanson finale: ''Je suis courageux, je peux demander de l''aide!'' Message: ''Il est normal d''avoir peur, et c''est intelligent de demander de l''aide.''','Coopérer le concept de quand j''ai; Pratiquer les habiletés de vie quotidienne; Développer les habiletés sociales par des situations authentiques',NULL,NULL,NULL,'formative','{"observable":["L''élève prend soin de son corps et de sa santé","L''élève fait des choix sécuritaires dans ses activités","L''élève communique ses besoins clairement aux adultes","L''élève respecte les limites personnelles et celles des autres"],"checkpoints":["Comprend l''importance de l''hygiène personnelle","Reconnaît les situations dangereuses","Utilise des stratégies pour rester en sécurité","Fait confiance aux adultes responsables"]}',1,'Plan détaillé avec supports visuels',1756911653395,1757594653938,1,'fr','Formation personnelle et sociale','{"pourDifficultés":["Se concentrer sur ''demander aide'' avec objets courage tangibles et support visuel","Utiliser uniquement des exemples très doux et rassurants","Permettre plus de temps avec les doudous et objets réconfortants"],"pourAvancés":["Explorer différents types de courage (essayer quelque chose de nouveau, aider un ami)","Discuter de différentes personnes qui peuvent aider selon les situations","Encourager à réconforter leurs pairs avec empathie"],"pourLangue":["Utiliser beaucoup de gestuelle et d''objets visuels pour ''aide'' et ''courage''","Permettre l''identification de personnes sécuritaires dans leur langue maternelle","Jumeler avec un pair francophone bienveillant"],"pourPEI":["Adapter les objets courage selon les préférences sensorielles","Utiliser des supports visuels personnalisés pour identifier l''aide disponible","Modifier les attentes selon les objectifs individuels de sécurité"]}','{"vocabulary":["courageux","peur","aide"],"visualSupports":["Expressions faciales pour ''avoir peur'' (yeux grands, bouche petite), geste de demander aide très visible, environnement rassurant et lumineux","Séquence visuelle ''peur→demande aide→courage'', personnes sécuritaires clairement identifiées, gestes d''aide bien démontrés","Progression visuelle peur→aide→courage, routine de fermeture sécurisante, objets courage tangibles"],"movementBreaks":["Geste du courage (poing doux sur le cœur)","Caresser le doudou courage","Respiration de courage (profonde et lente)","Marche confiante autour du cercle avec doudou","Geste final du courage en groupe","Caresser l''objet courage choisi"]}',NULL,NULL,NULL,NULL,'{"questions":["Les élèves ont-ils atteint les objectifs?","Quelles adaptations étaient nécessaires?","Que ferais-je différemment la prochaine fois?"]}',NULL,'',5,9,'core',1);
INSERT INTO ETFOLessonPlan VALUES('cmf43u3v800brvj9tcspo8yu0',23,'Respirer pour me calmer','cmf43u3uz00b7vj9toxmjxb0a',1764086400000,45,'Cercle de respiration avec Émilie qui montre comment elle respire pour se calmer. Histoire: ''Émilie était énervée, mais elle a respiré comme un papillon doux.'' Introduction de plumes légères pour pratiquer la respiration. TPR: respiration papillon (légère) et respiration ours (profonde). Chanson: ''Respire in, respire out, ton cœur devient tout doux.''','Exploration de différentes respirations calmantes. Émilie enseigne la respiration de l''ours (profonde), du papillon (légère), et de l''arbre (lente). Jeu ''Fais voler la plume'': chaque élève souffle doucement pour faire bouger sa plume. Station de respiration avec coussins confortables. Pratique de respirer quand on se sent différentes émotions.','Retour au cercle pour respiration finale apaisante. Émilie fait une respiration très calme avec tout le groupe. Révision: ''Quand je veux être calme, je peux respirer comme un ours, un papillon, ou un arbre.'' Chaque élève garde sa plume spéciale. Chanson finale douce: ''Ma respiration m''aide à rester calme et heureux.''','Pratiquer le concept de respirer pour; Pratiquer les habiletés de vie quotidienne; Développer les habiletés sociales par des situations authentiques','["Émilie la marionnette montrant la respiration calme","Plumes colorées légères pour exercices","Cartes visuelles ''respirer'' avec flèches","Petite clochette pour rythme de respiration","Coussins de respiration confortables","Plumes individuelles pour chaque élève","Cartes d''animaux respirants (ours, papillon, arbre)","Musique douce de fond","Plumes à emporter pour chaque élève","Petites cartes de rappel respiration","Émilie très détendue et calme","Musique de relaxation finale"]',NULL,'Respirer pour me calmer','Cercle de respiration avec Émilie qui montre comment elle respire pour se calmer. Histoire: ''Émilie était énervée, mais elle a respiré comme un papillon doux.'' Introduction de plumes légères pour pratiquer la respiration. TPR: respiration papillon (légère) et respiration ours (profonde). Chanson: ''Respire in, respire out, ton cœur devient tout doux.''','Exploration de différentes respirations calmantes. Émilie enseigne la respiration de l''ours (profonde), du papillon (légère), et de l''arbre (lente). Jeu ''Fais voler la plume'': chaque élève souffle doucement pour faire bouger sa plume. Station de respiration avec coussins confortables. Pratique de respirer quand on se sent différentes émotions.','Retour au cercle pour respiration finale apaisante. Émilie fait une respiration très calme avec tout le groupe. Révision: ''Quand je veux être calme, je peux respirer comme un ours, un papillon, ou un arbre.'' Chaque élève garde sa plume spéciale. Chanson finale douce: ''Ma respiration m''aide à rester calme et heureux.''','Pratiquer le concept de respirer pour; Pratiquer les habiletés de vie quotidienne; Développer les habiletés sociales par des situations authentiques',NULL,NULL,NULL,'formative','{"observable":["L''élève prend soin de son corps et de sa santé","L''élève fait des choix sécuritaires dans ses activités","L''élève communique ses besoins clairement aux adultes","L''élève respecte les limites personnelles et celles des autres"],"checkpoints":["Comprend l''importance de l''hygiène personnelle","Reconnaît les situations dangereuses","Utilise des stratégies pour rester en sécurité","Fait confiance aux adultes responsables"]}',1,'Plan détaillé avec supports visuels',1756911653396,1757594653939,1,'fr','Formation personnelle et sociale','{"pourDifficultés":["Se concentrer sur une seule technique de respiration simple avec beaucoup de support visuel","Permettre des respirations plus courtes et moins profondes selon le confort","Utiliser des objets tactiles comme les plumes pour rendre l''exercice plus concret"],"pourAvancés":["Enseigner des techniques de respiration plus sophistiquées (respiration carrée simple)","Encourager à guider leurs pairs dans les exercices de respiration","Discuter de quand utiliser différentes respirations selon les situations"],"pourLangue":["Utiliser beaucoup de modélisation physique et d''objets manipulables","Permettre l''expression du ressenti dans leur langue maternelle","Jumeler avec un pair pour pratiquer les techniques ensemble"],"pourPEI":["Adapter les positions de respiration selon les capacités motrices","Utiliser des aides visuelles personnalisées et des rappels tactiles","Modifier la durée et l''intensité selon les besoins sensoriels"]}','{"vocabulary":["respirer","calme","lentement"],"visualSupports":["Démonstration claire de respiration profonde, flèches visuelles inspirer/expirer, mouvements lents et apaisants modelés","Cartes visuelles des différents types de respiration, démonstrations claires avec les mains, environnement calme et apaisant","Progression visuelle énervé→respire→calme, routine de fermeture très apaisante, objets tangibles de rappel"],"movementBreaks":["Respiration papillon (très légère)","Faire voler les plumes doucement","Respiration debout avec bras qui montent et descendent","Marche lente avec respiration","Respiration finale très lente en groupe","Caresser doucement la plume"]}',NULL,NULL,NULL,NULL,'{"questions":["Les élèves ont-ils atteint les objectifs?","Quelles adaptations étaient nécessaires?","Que ferais-je différemment la prochaine fois?"]}',NULL,'',5,10,'core',1);
INSERT INTO ETFOLessonPlan VALUES('cmf43u3v900btvj9tjhxy6b0y',23,'Comprendre les autres','cmf43u3uz00b7vj9toxmjxb0a',1764259200000,45,'Cercle d''observation avec Émilie et son amie Léa (deux marionnettes). Histoire: ''Émilie voit que Léa semble triste aujourd''hui.'' Jeu du miroir émotionnel: regarder le visage d''un ami et deviner ce qu''il ressent. TPR: geste ''regarder avec ses yeux'' et geste ''cœur qui comprend''. Chanson: ''Avec mes yeux je regarde, avec mon cœur je comprends.''','Exploration de la compréhension des autres. Émilie et Léa montrent différentes situations: Léa est fatiguée, contente, inquiète. Jeu ''Détective du cœur'': observer et deviner ce que ressent un camarade. Pratique de gestes gentils: donner un cœur en feutrine, offrir un sourire, dire ''Ça va?''. Création d''une boîte de gentillesse avec gestes réconfortants.','Retour au cercle avec Émilie et Léa maintenant heureuses. Révision: ''Pour comprendre les autres, je regarde avec mes yeux et j''écoute avec mon cœur.'' Chaque élève choisit un geste gentil à pratiquer aujourd''hui. Chanson finale: ''Comprendre les autres, ça rend tout le monde heureux!'' Message: ''Être gentil avec les autres nous rend heureux aussi.''','Développer le concept de comprendre les; Pratiquer les habiletés de vie quotidienne; Développer les habiletés sociales par des situations authentiques','["Émilie et Léa (deux marionnettes)","Grand miroir pour jeu d''observation","Cartes d''émotions avec visages d''enfants","Cœurs en feutrine à distribuer","Scénarios illustrés avec les marionnettes","Cœurs en feutrine pour chaque élève","Boîte de gentillesse décorée","Cartes de gestes gentils (sourire, câlin, écouter)","Cartes de gestes gentils à emporter","Émilie et Léa souriantes ensemble","Autocollants ''cœur qui comprend''","Chanson illustrée de la compréhension"]',NULL,'Comprendre les autres','Cercle d''observation avec Émilie et son amie Léa (deux marionnettes). Histoire: ''Émilie voit que Léa semble triste aujourd''hui.'' Jeu du miroir émotionnel: regarder le visage d''un ami et deviner ce qu''il ressent. TPR: geste ''regarder avec ses yeux'' et geste ''cœur qui comprend''. Chanson: ''Avec mes yeux je regarde, avec mon cœur je comprends.''','Exploration de la compréhension des autres. Émilie et Léa montrent différentes situations: Léa est fatiguée, contente, inquiète. Jeu ''Détective du cœur'': observer et deviner ce que ressent un camarade. Pratique de gestes gentils: donner un cœur en feutrine, offrir un sourire, dire ''Ça va?''. Création d''une boîte de gentillesse avec gestes réconfortants.','Retour au cercle avec Émilie et Léa maintenant heureuses. Révision: ''Pour comprendre les autres, je regarde avec mes yeux et j''écoute avec mon cœur.'' Chaque élève choisit un geste gentil à pratiquer aujourd''hui. Chanson finale: ''Comprendre les autres, ça rend tout le monde heureux!'' Message: ''Être gentil avec les autres nous rend heureux aussi.''','Développer le concept de comprendre les; Pratiquer les habiletés de vie quotidienne; Développer les habiletés sociales par des situations authentiques',NULL,NULL,NULL,'formative','{"observable":["L''élève prend soin de son corps et de sa santé","L''élève fait des choix sécuritaires dans ses activités","L''élève communique ses besoins clairement aux adultes","L''élève respecte les limites personnelles et celles des autres"],"checkpoints":["Comprend l''importance de l''hygiène personnelle","Reconnaît les situations dangereuses","Utilise des stratégies pour rester en sécurité","Fait confiance aux adultes responsables"]}',1,'Plan détaillé avec supports visuels',1756911653397,1757594653940,1,'fr','Formation personnelle et sociale','{"pourDifficultés":["Se concentrer sur une seule émotion à la fois (content/triste) avec beaucoup de support visuel","Utiliser des gestes très simples et tangibles comme donner un cœur en feutrine","Permettre l''observation passive sans obligation d''interagir"],"pourAvancés":["Explorer des émotions plus nuancées (inquiet, excité, déçu)","Encourager à guider leurs pairs dans l''identification des émotions","Discuter de différentes façons d''aider selon les émotions observées"],"pourLangue":["Utiliser beaucoup de gestuelle et d''expressions faciales exagérées","Permettre l''expression des émotions observées dans leur langue maternelle","Jumeler avec un pair francophone empathique"],"pourPEI":["Adapter les activités d''observation selon les capacités sensorielles","Utiliser des supports visuels personnalisés et des objets tactiles","Modifier les interactions sociales selon les besoins individuels"]}','{"vocabulary":["comprendre","autres","gentillesse"],"visualSupports":["Expressions faciales très marquées, geste pointant vers les yeux puis vers le cœur, environnement invitant à l''observation","Séquences visuelles ''observer→comprendre→aider'', démonstration claire des gestes gentils, expressions faciales modelées","Progression visuelle observer→comprendre→être gentil, routine de fermeture chaleureuse, objets de rappel tangibles"],"movementBreaks":["Geste de regarder avec les yeux (mains autour des yeux)","Geste du cœur qui comprend (main sur le cœur)","Distribuer les cœurs en feutrine avec douceur","Marche d''observation calme autour du cercle","Geste final du cœur qui comprend ensemble","Caresser doucement l''autocollant cœur"]}',NULL,NULL,NULL,NULL,'{"questions":["Les élèves ont-ils atteint les objectifs?","Quelles adaptations étaient nécessaires?","Que ferais-je différemment la prochaine fois?"]}',NULL,'',5,11,'core',1);
INSERT INTO ETFOLessonPlan VALUES('cmf43u3va00bxvj9tjsl7nqsv',23,'Mes stratégies émotionnelles','cmf43u3uz00b7vj9toxmjxb0a',1764604800000,45,'Introduction à la leçon : Mes stratégies émotionnelles','Activité principale : exploration pratique et créative','Consolidation : partage et réflexion sur nos apprentissages','Exprimer le concept de mes stratégies; Pratiquer les habiletés de vie quotidienne; Développer les habiletés sociales par des situations authentiques','["autocollants motivants (1 planche)","marionnettes simples (3-4 personnages)","tapis de rassemblement coloré","tableaux individuels effaçables (15 tableaux)","marqueurs effaçables (15 marqueurs)","livrets de lecture simple (niveau débutant, 15 copies)","crayons à mine large (30 crayons)","cahiers d''écriture (30 cahiers)","étiquettes autocollantes (2 planches)","chemises individuelles (30 chemises)","tampons motivants avec encreur (5 tampons)"]',NULL,'Mes stratégies émotionnelles','Introduction à la leçon : Mes stratégies émotionnelles','Activité principale : exploration pratique et créative','Consolidation : partage et réflexion sur nos apprentissages','Exprimer le concept de mes stratégies; Pratiquer les habiletés de vie quotidienne; Développer les habiletés sociales par des situations authentiques',NULL,NULL,NULL,'formative','{"observable":["L''élève prend soin de son corps et de sa santé","L''élève fait des choix sécuritaires dans ses activités","L''élève communique ses besoins clairement aux adultes","L''élève respecte les limites personnelles et celles des autres"],"checkpoints":["Comprend l''importance de l''hygiène personnelle","Reconnaît les situations dangereuses","Utilise des stratégies pour rester en sécurité","Fait confiance aux adultes responsables"]}',1,'Plan détaillé avec supports visuels',1756911653399,1757594653941,1,'fr','Formation personnelle et sociale','{"pourDifficultés":["Utiliser des cartes visuelles avec images pour chaque mot nouveau","Proposer des supports audio pour accompagner le texte écrit","Offrir du temps supplémentaire pour compléter les activités"],"pourAvancés":["Proposer des défis de vocabulaire avec mots plus sophistiqués","Permettre l''exploration de différents genres littéraires (poésie, théâtre)","Encourager la création d''histoires originales avec début, milieu, fin"],"pourLangue":["Permettre les explications dans la langue première si nécessaire","Utiliser des images et symboles pour soutenir la compréhension","Encourager le jumelage avec un pair plus fort en français"],"pourPEI":["Utiliser des supports visuels clairs et contrastés","Adapter les outils d''écriture (crayons ergonomiques, guides-lignes)","Permettre différents moyens d''expression (oral, dessin, technologie)"]}','{"vocabulary":["stratégies","outils","choisir"],"visualSupports":[],"movementBreaks":["Imiter les animaux des histoires : sauter comme un lapin, voler comme un oiseau (3 minutes)","Répéter des comptines avec gestes : ''Tête, épaules, genoux et pieds'' (2 minutes)","Faire une pause lecture : s''étirer comme un chat qui se réveille (2 minutes)","Marcher sur place en récitant l''alphabet lentement (2 minutes)","Dire au revoir avec tout notre corps : mains, têtes, pieds (2 minutes)","Faire une révérence à nos nouvelles connaissances (1 minute)"]}',NULL,NULL,NULL,NULL,'{"questions":["Les élèves ont-ils atteint les objectifs?","Quelles adaptations étaient nécessaires?","Que ferais-je différemment la prochaine fois?"]}',NULL,'',5,12,'core',1);
INSERT INTO ETFOLessonPlan VALUES('cmf43u3vb00bzvj9tcf7jhczn',23,'Mon journal des émotions','cmf43u3uz00b7vj9toxmjxb0a',1764777600000,45,'Introduction à la leçon : Mon journal des émotions','Activité principale : exploration pratique et créative','Consolidation : partage et réflexion sur nos apprentissages','Gérer les émotions de base; Pratiquer des stratégies de gestion émotionnelle; Développer la conscience de soi par des situations authentiques','["crayons de couleur (boîte de 24)","autocollants motivants (1 planche)","marionnettes simples (3-4 personnages)","cahiers d''écriture (30 cahiers)","marqueurs effaçables (15 marqueurs)","gommes à effacer douces (15 gommes)","lettres magnétiques (jeu complet A-Z)","livrets de lecture simple (niveau débutant, 15 copies)","lingettes pour nettoyer les mains (1 paquet)","certificats d''encouragement (30 copies)","étiquettes autocollantes (2 planches)"]',NULL,'Mon journal des émotions','Introduction à la leçon : Mon journal des émotions','Activité principale : exploration pratique et créative','Consolidation : partage et réflexion sur nos apprentissages','Gérer les émotions de base; Pratiquer des stratégies de gestion émotionnelle; Développer la conscience de soi par des situations authentiques',NULL,NULL,NULL,'formative','{"observable":["L''élève nomme 4 émotions de base: joie, tristesse, colère, peur","L''élève reconnaît les émotions sur les visages des autres","L''élève explique: ''Quand je suis triste, je peux demander de l''aide''","L''élève utilise des mots au lieu de gestes agressifs"],"checkpoints":["Identifie ses propres émotions avec des mots précis","Utilise des stratégies pour se calmer quand nécessaire","Respecte les émotions des autres enfants","Demande l''aide d''un adulte quand il en a besoin"]}',1,'Plan détaillé avec supports visuels',1756911653400,1757594653942,1,'fr','Formation personnelle et sociale','{"pourDifficultés":["Utiliser des cartes visuelles avec images pour chaque mot nouveau","Offrir du temps s