INSERT INTO ETFOLessonPlan VALUES('cmf43u3ye00ivvj9te7jsmr8t',23,'Descriptions vivantes','cmf43u3y400i7vj9tu1eu69f8',1770393600000,45,'Review giving clear instructions. Today paint pictures with words using vivid descriptions!','Description practice - students describe pictures, objects, or experiences using sensory details and descriptive French words. Help others ''see'' through words.','Guessing game - students give descriptions while others guess what they''re describing.','Lire le concept de descriptions vivantes; Utiliser les compétences langagières fondamentales; Développer la communication orale par des activités langagières variées','["Images variées pour description","Objets variés pour toucher","Images mystères","certificats d''encouragement (30 copies)","boîte de rangement pour travaux (1 grande boîte)","lingettes pour nettoyer les mains (1 paquet)"]',NULL,'Descriptions vivantes','Review giving clear instructions. Today paint pictures with words using vivid descriptions!','Description practice - students describe pictures, objects, or experiences using sensory details and descriptive French words. Help others ''see'' through words.','Guessing game - students give descriptions while others guess what they''re describing.','Lire le concept de descriptions vivantes; Utiliser les compétences langagières fondamentales; Développer la communication orale par des activités langagières variées',NULL,NULL,NULL,'formative','{"observable":["Utilise mots descriptifs variés","Aide autres à visualiser","Améliore descriptions avec pratique"],"checkpoints":["Décrit avec 2+ détails","Utilise mots nouveaux","Participe jeux devinettes"]}',1,'Plan détaillé avec supports visuels',1756911653511,1757594654082,1,'fr','Français (Immersion)','{"pourDifficultés":["Un détail à la fois","Objets très familiers","Support pour trouver mots"],"pourAvancés":["Descriptions multi-sensorielles","Métaphores simples","Descriptions d''émotions aussi"],"pourLangue":["Support visuel pour vocabulaire","Descriptions bilingues OK","Gestes pour expliquer"],"pourPEI":["Descriptions adaptées aux forces","Supports sensoriels","Temps flexible"]}','{"vocabulary":["décrire","détail","imaginer"],"visualSupports":["Mots descriptifs par catégorie : couleur, taille, forme, texture","Banque de mots sensoriels avec images","Règles du jeu de devinettes affichées"],"movementBreaks":["Gestes descriptifs","Exploration tactile d''objets","Étirer notre dos d''écrivains : rotation douce des épaules (2 minutes)","Faire une révérence à nos nouvelles connaissances (1 minute)"]}',NULL,NULL,NULL,NULL,'{"questions":["Les élèves ont-ils atteint les objectifs?","Quelles adaptations étaient nécessaires?","Que ferais-je différemment la prochaine fois?"]}',NULL,'',1,12,'core',1);
