INSERT INTO ETFOLessonPlan VALUES('cmf43u3yj00j5vj9tyfuar85g',23,'Débat amical','cmf43u3y400i7vj9tu1eu69f8',1770998400000,45,'Review news reporting. Today learn that people can have different ideas and still be friends!','Gentle debate practice - students share different opinions on simple topics (favorite seasons, best playground games) while practicing respectful disagreement.','Reflection on respectful disagreement - students share what they learned about different opinions.','Décrire le concept de débat amical; Utiliser les compétences langagières fondamentales; Développer l''expression écrite par des activités langagières variées','["Images de sujets d''opinion simples","Cartes de sujets d''opinion appropriées","Bâton de parole","tampons motivants avec encreur (5 tampons)","boîte de rangement pour travaux (1 grande boîte)","certificats d''encouragement (30 copies)"]',NULL,'Débat amical','Review news reporting. Today learn that people can have different ideas and still be friends!','Gentle debate practice - students share different opinions on simple topics (favorite seasons, best playground games) while practicing respectful disagreement.','Reflection on respectful disagreement - students share what they learned about different opinions.','Décrire le concept de débat amical; Utiliser les compétences langagières fondamentales; Développer l''expression écrite par des activités langagières variées',NULL,NULL,NULL,'formative','{"observable":["Exprime opinion personnelle","Respecte opinions différentes","Écoute sans interrompre"],"checkpoints":["Partage une préférence","Accepte désaccord avec calme","Pose question respectueuse"]}',1,'Plan détaillé avec supports visuels',1756911653515,1757594654087,1,'fr','Français (Immersion)','{"pourDifficultés":["Partage préférences simples","Sujets très familiers","Pas de pression argumenter"],"pourAvancés":["Argmentation avec raisons","Questions de suivi","Médiation entre opinions"],"pourLangue":["Opinions culturelles valorisées","Support pour exprimer idées","Comparaisons interculturelles"],"pourPEI":["Participation selon confort social","Support pour interaction respectueuse","Alternatives à débat oral"]}','{"vocabulary":["opinion","différent","respecter"],"visualSupports":["Phrases respectueuses : ''Je pense que...'', ''Tu as raison aussi''","Règles du débat respectueux affichées","Leçons sur diversité d''opinions affichées"],"movementBreaks":["Gestes d''accord et désaccord respectueux","Cercle de respect entre sujets","Dire au revoir avec tout notre corps : mains, têtes, pieds (2 minutes)","Faire une révérence à nos nouvelles connaissances (1 minute)"]}',NULL,NULL,NULL,NULL,'{"questions":["Les élèves ont-ils atteint les objectifs?","Quelles adaptations étaient nécessaires?","Que ferais-je différemment la prochaine fois?"]}',NULL,'',1,17,'extension',1);
INSERT INTO ETFOLessonPlan VALUES('cmf43u3yk00j7vj9tbbdvi29e',23,'Enseignants experts','cmf43u3y400i7vj9tu1eu69f8',4102416000000,45,'Review respectful opinion sharing. Today become teachers sharing expertise with others!','Teaching practice - students plan and practice teaching something they know well to younger students, family members, or classmates.','Teacher appreciation - students reflect on what makes good teaching and how it feels to help others learn.','Appliquer le concept de enseignants experts; Utiliser les compétences langagières fondamentales; Développer l''expression écrite par des activités langagières variées','["Badge ''Enseignant Expert''","Matériaux variés pour démonstrations","Tableau individuel si possible","tampons motivants avec encreur (5 tampons)","étiquettes autocollantes (2 planches)","lingettes pour nettoyer les mains (1 paquet)"]',NULL,'Enseignants experts','Review respectful opinion sharing. Today become teachers sharing expertise with others!','Teaching practice - students plan and practice teaching something they know well to younger students, family members, or classmates.','Teacher appreciation - students reflect on what makes good teaching and how it feels to help others learn.','Appliquer le concept de enseignants experts; Utiliser les compétences langagières fondamentales; Développer l''expression écrite par des activités langagières variées',NULL,NULL,NULL,'formative','{"observable":["Partage expertise authentique","Adapte enseignement à audience","Montre fierté dans savoir partagé"],"checkpoints":["Enseigne quelque chose qu''il maîtrise","Aide autrui à apprendre","Réfléchit sur expérience enseignement"]}',1,'Plan détaillé avec supports visuels',1756911653516,1757594654088,1,'fr','Français (Immersion)','{"pourDifficultés":["Démonstration simple","Sujet très familier","Co-enseignement avec ami"],"pourAvancés":["Enseignement structuré","Adaptation à différents apprenants","Création matériel pédagogique"],"pourLangue":["Enseignement bilingue valorisé","Partage expertise culturelle","Démonstration prioritaire"],"pourPEI":["Enseignement selon forces uniques","Support pour planification","Format adapté aux capacités"]}','{"vocabulary":["enseigner","expert","apprendre"],"visualSupports":["Qualités d''un bon enseignant affichées","Guide de planification de leçon simple","Célébration des enseignants du jour"],"movementBreaks":["Posture enseignant confiant","Rotation entre enseignants-élèves","Étirer notre dos d''écrivains : rotation douce des épaules (2 minutes)","Célébrer nos apprentissages : applaudir, lever les bras, sourire (2 minutes)"]}',NULL,NULL,NULL,NULL,'{"questions":["Les élèves ont-ils atteint les objectifs?","Quelles adaptations étaient nécessaires?","Que ferais-je différemment la prochaine fois?"]}',NULL,'',1,18,'extension',0);
INSERT INTO ETFOLessonPlan VALUES('cmf43u3yl00j9vj9tuznsaupe',23,'Ambassadeurs culturels','cmf43u3y400i7vj9tu1eu69f8',4102416000000,45,'Review being teachers and experts. Today be cultural ambassadors sharing special traditions from our families!','Cultural sharing - students present aspects of their family culture, traditions, or heritage using communication skills developed throughout unit.','Cultural appreciation - celebrate the diversity in classroom and what we learned about each other''s backgrounds.','Créer le concept de ambassadeurs culturels; Utiliser les compétences langagières fondamentales; Développer l''expression écrite par des activités langagières variées','["Objets culturels apportés par élèves","Photos de famille","Aliments culturels si possible","chemises individuelles (30 chemises)","étiquettes autocollantes (2 planches)","lingettes pour nettoyer les mains (1 paquet)"]',NULL,'Ambassadeurs culturels','Review being teachers and experts. Today be cultural ambassadors sharing special traditions from our families!','Cultural sharing - students present aspects of their family culture, traditions, or heritage using communication skills developed throughout unit.','Cultural appreciation - celebrate the diversity in classroom and what we learned about each other''s backgrounds.','Créer le concept de ambassadeurs culturels; Utiliser les compétences langagières fondamentales; Développer l''expression écrite par des activités langagières variées',NULL,NULL,NULL,'formative','{"observable":["Partage aspect de sa culture","Respecte cultures d''autrui","Contribue à appréciation diversité"],"checkpoints":["Présente tradition familiale","Pose questions respectueuses","Célèbre richesse culturelle classe"]}',1,'Plan détaillé avec supports visuels',1756911653517,1757594654089,1,'fr','Français (Immersion)','{"pourDifficultés":["Tradition très simple","Avec support familial","Objets pour montrer plutôt que expliquer"],"pourAvancés":["Présentation culturelle détaillée","Comparaisons interculturelles","Leadership pour célébration diversité"],"pourLangue":["Expertise culturelle valorisée","Partage dans langue d''origine encourage","Traduction pour classe"],"pourPEI":["Partage selon niveau confort","Toutes formes de partage valorisées","Soutien pour participation sociale"]}','{"vocabulary":["culture","ambassadeur","tradition"],"visualSupports":["Carte du monde pour localiser cultures","Galerie de diversité culturelle de classe","Mosaïque de diversité créée ensemble"],"movementBreaks":["Salutations de différentes cultures","Danses ou mouvements culturels simples","Dire au revoir avec tout notre corps : mains, têtes, pieds (2 minutes)","Ranger nos idées : faire semblant de mettre nos pensées dans une boîte (2 minutes)"]}',NULL,NULL,NULL,NULL,'{"questions":["Les élèves ont-ils atteint les objectifs?","Quelles adaptations étaient nécessaires?","Que ferais-je différemment la prochaine fois?"]}',NULL,'',1,19,'core',0);
INSERT INTO ETFOLessonPlan VALUES('cmf43u3ym00jbvj9tehsoxint',23,'Célébration de communicateurs','cmf43u3y400i7vj9tu1eu69f8',1771862400000,45,'Look back at incredible communication journey from shy beginners to confident communicators!','Communication celebration - students showcase their favorite communication skills, receive certificates, and reflect on amazing growth as French speakers.','Final circle: each student completes ''Je suis un communicateur confiant parce que...'' Group celebration photo with certificates.','Maîtriser le concept de célébration de; Utiliser les compétences langagières fondamentales; Développer l''expression écrite par la célébration collective','["Portfolio de classe avec photos/travaux du début","Certificats personnalisés","Décorations festives","Caméra pour photo de groupe"]',NULL,'Célébration de communicateurs','Look back at incredible communication journey from shy beginners to confident communicators!','Communication celebration - students showcase their favorite communication skills, receive certificates, and reflect on amazing growth as French speakers.','Final circle: each student completes ''Je suis un communicateur confiant parce que...'' Group celebration photo with certificates.','Maîtriser le concept de célébration de; Utiliser les compétences langagières fondamentales; Développer l''expression écrite par la célébration collective',NULL,NULL,NULL,'formative','{"observable":["Exprime fierté d''apprentissage","Reconnaît progrès personnel","Célèbre avec communauté classe"],"checkpoints":["Complète phrase de fierté","Participe à célébration","Montre confiance communicative acquise"]}',1,'Plan détaillé avec supports visuels',1756911653518,1757594654090,1,'fr','Français (Immersion)','{"pourDifficultés":["Célébration de tout progrès","Reconnaissance efforts plutôt que résultats","Soutien pour identifier forces"],"pourAvancés":["Réflexion approfondie sur apprentissage","Plans futurs détaillés","Mentorship pour célébration collective"],"pourLangue":["Célébration courage linguistique","Fierté identité multilingue","Progrès dans toutes langues valorisés"],"pourPEI":["Célébration personnalisée aux réussites uniques","Reconnaissance de tous types progrès","Soutien pour confiance en soi"]}','{"vocabulary":["célébrer","confiant","succès"],"visualSupports":["Ligne de temps des apprentissages avec photos","Galerie de réussites et progrès affichés","Phrase de complétion affichée"],"movementBreaks":["Danse célébration du progrès","Parade de fierté communicative","Étirer notre dos d''écrivains : rotation douce des épaules (2 minutes)","Dire au revoir avec tout notre corps : mains, têtes, pieds (2 minutes)"]}',NULL,NULL,NULL,NULL,'{"questions":["Les élèves ont-ils atteint les objectifs?","Quelles adaptations étaient nécessaires?","Que ferais-je différemment la prochaine fois?"]}',NULL,'',1,20,'core',1);
INSERT INTO ETFOLessonPlan VALUES('cmf43u3yo00jfvj9t6ecx10if',23,'Découvrir les mots','cmf43u3yn00jdvj9t4ynrfkm6',1763568000000,45,'Welcome circle - Show magnifying glass and say ''Nous sommes des explorateurs!'' Use TPR to mime looking and discovering. Point to French words around the room.','Word Detective Walk - Take students around the room to ''discover'' French words on labels, posters, books. Students point and teacher names each word clearly. Create a simple chart of discovered words with pictures.','Circle back - Show three discovered words with pictures. Students repeat after teacher. End with ''Nous sommes des explorateurs de mots!''','Explorer les mots familiers; Utiliser le vocabulaire thématique en contexte; Développer la conscience phonologique par des activités langagières variées','["Magnifying glass (real or toy)","French word labels around room","Explorer hat (optional)","Chart paper and markers","Clipboards (10-12 for pairs)","Pencils/crayons","Stickers for discovered words","Simple picture cards for common words","Word cards from activity","Picture supports","Explorer badges/stickers"]',NULL,'Découvrir les mots','Welcome circle - Show magnifying glass and say ''Nous sommes des explorateurs!'' Use TPR to mime looking and discovering. Point to French words around the room.','Word Detective Walk - Take students around the room to ''discover'' French words on labels, posters, books. Students point and teacher names each word clearly. Create a simple chart of discovered words with pictures.','Circle back - Show three discovered words with pictures. Students repeat after teacher. End with ''Nous sommes des explorateurs de mots!''','Explorer les mots familiers; Utiliser le vocabulaire thématique en contexte; Développer la conscience phonologique par des activités langagières variées',NULL,NULL,NULL,'formative','{"observable":["Élève pointe et nomme différents textes","Élève participe activement à la chasse aux textes","Élève comprend que les textes donnent de l''information"],"checkpoints":["Peut identifier au moins 3 types de textes différents","Utilise le vocabulaire ''texte'', ''livre'', ''écrit'' correctement","Montre de l''enthousiasme pour découvrir les textes"]}',1,'Plan détaillé avec supports visuels',1756911653520,1757594654117,1,'fr','Français (Immersion)','{"pourDifficultés":["Partner with confident peer","Use more picture supports","Focus on 2-3 simple words only","Allow pointing instead of verbal responses"],"pourAvancés":["Count syllables in discovered words","Find words that start with same sound","Help teach words to classmates","Create own word categories"],"pourLangue":["Connect to home language cognates when possible","Use extra visual and gesture supports","Allow code-switching during discovery","Pair with bilingual buddy"],"pourPEI":["Modify activity length as needed","Provide sensory supports (fidgets during circle)","Use communication device if needed","Celebrate any participation level"]}','{"vocabulary":["mot","découvrir","français"],"visualSupports":["Visual schedule showing lesson flow, Word detective poster with magnifying glass image","Word discovery chart with pictures, Visual instructions for word hunt","Three chosen words with clear pictures, Class motto poster"],"movementBreaks":["Standing and walking around room","TPR gestures for discovering","Walking around classroom","Pointing and reaching gestures","Clapping for each discovery","Standing for motto chant","Action gestures with exploring theme"]}',NULL,NULL,NULL,NULL,'{"questions":["Les élèves ont-ils atteint les objectifs?","Quelles adaptations étaient nécessaires?","Que ferais-je différemment la prochaine fois?"]}',NULL,'',1,1,'core',1);
INSERT INTO ETFOLessonPlan VALUES('cmf43u3yp00jhvj9tdlzv3jk0',23,'Sons et lettres','cmf43u3yn00jdvj9t4ynrfkm6',1763654400000,45,'Review yesterday''s discovered words from chart. Point to each word and have students repeat the sounds they hear.','Sound Matching Game - Show large letter cards A, E, I, O, U. Say simple French words (ami, eau, etc.) and students listen for the vowel sounds. Use picture cards to support meaning. Students move to the letter they hear.','Sound Circle - Everyone sits and practices the 5 vowel sounds with hand gestures: A (arms wide), E (hands by ears), I (point up), O (make circle), U (pucker lips).','Identifier les lettres de l''alphabet; Utiliser la formation correcte des lettres; Développer la conscience phonologique par des activités langagières variées','["Word chart from lesson 1","Pointer","Picture cards for vocabulary words","Large letter cards A,E,I,O,U (25 sets)","Picture cards for French words","Masking tape for floor letters","Small vowel cards for each student","Vowel gesture reminder cards","Mirror (optional for mouth positions)"]',NULL,'Sons et lettres','Review yesterday''s discovered words from chart. Point to each word and have students repeat the sounds they hear.','Sound Matching Game - Show large letter cards A, E, I, O, U. Say simple French words (ami, eau, etc.) and students listen for the vowel sounds. Use picture cards to support meaning. Students move to the letter they hear.','Sound Circle - Everyone sits and practices the 5 vowel sounds with hand gestures: A (arms wide), E (hands by ears), I (point up), O (make circle), U (pucker lips).','Identifier les lettres de l''alphabet; Utiliser la formation correcte des lettres; Développer la conscience phonologique par des activités langagières variées',NULL,NULL,NULL,'formative','{"observable":["Élève ''lit'' activement les images","Élève comprend que les images donnent de l''information","Élève utilise le nouveau vocabulaire"],"checkpoints":["Peut décrire au moins un élément vu dans une image","Reconnaît que les images ''parlent''","Montre de l''engagement avec les livres sans mots"]}',1,'Plan détaillé avec supports visuels',1756911653521,1757594654118,1,'fr','Français (Immersion)','{"pourDifficultés":["Focus on 2-3 vowels only","Use extra visual mouth position cues","Allow approximations of sounds","Pair with strong phonics peer"],"pourAvancés":["Identify beginning AND ending sounds","Find multiple words with same vowel","Help demonstrate sounds to classmates","Try blending simple sounds"],"pourLangue":["Compare to home language vowel sounds","Use extra gesture and visual supports","Allow native language sound approximations","Practice with familiar English cognates first"],"pourPEI":["Modify movement expectations","Use alternative communication methods","Provide sensory supports for sound work","Celebrate any sound approximation"]}','{"vocabulary":["son","lettre","écouter"],"visualSupports":["Yesterday''s word discovery chart, Sound symbols poster, Listening ear visual cue","Vowel sound posters with mouth positions, Picture-word cards, Floor letter spaces marked clearly","Gesture poster for each vowel sound, Sound-symbol connections chart"],"movementBreaks":["Pointing to words on chart","Cupping ears for listening","Moving to different letter stations","Hand gestures for vowel sounds","Stretching between rounds","All vowel gestures with full body movement","Standing for final vowel chant"]}',NULL,NULL,NULL,NULL,'{"questions":["Les élèves ont-ils atteint les objectifs?","Quelles adaptations étaient nécessaires?","Que ferais-je différemment la prochaine fois?"]}',NULL,'',1,2,'core',1);
INSERT INTO ETFOLessonPlan VALUES('cmf43u3yq00jjvj9tseq9msi6',23,'Familles de sons','cmf43u3yn00jdvj9t4ynrfkm6',1763740800000,45,'Sound Review - Practice vowel sounds from yesterday with gestures. Then show family photo and explain ''famille'' - people who belong together.','Sound Family Sorting - Give students picture cards (ballon, bébé, bateau / chat, chien, chaussure / pain, papa, poisson). Students sort cards by beginning sound into labeled circles. Teacher models first few.','Family Parade - Each sound family group stands up and says their sound together, then marches around showing their pictures.','Reconnaître les sons et leur correspondance; Utiliser la discrimination auditive des sons; Développer la conscience phonologique par des activités langagières variées','["Vowel gesture cards from lesson 2","Family photo (teacher''s or stock photo)","Visual family concept card","Picture cards for B, CH, P sounds (6-8 per family, 5-6 sets)","Sorting circles or hula hoops (3 per group)","Letter labels B, CH, P","Demonstration cards for modeling","Images de familles diverses (monoparentales, recomposées, multiculturelles)","Picture cards from activity","Optional: simple musical instrument for marching"]',NULL,'Familles de sons','Sound Review - Practice vowel sounds from yesterday with gestures. Then show family photo and explain ''famille'' - people who belong together.','Sound Family Sorting - Give students picture cards (ballon, bébé, bateau / chat, chien, chaussure / pain, papa, poisson). Students sort cards by beginning sound into labeled circles. Teacher models first few.','Family Parade - Each sound family group stands up and says their sound together, then marches around showing their pictures.','Reconnaître les sons et leur correspondance; Utiliser la discrimination auditive des sons; Développer la conscience phonologique par des activités langagières variées',NULL,NULL,NULL,'formative','{"observable":["Élève examine attentivement les images","Élève fait des prédictions logiques","Élève utilise le vocabulaire de prédiction"],"checkpoints":["Peut faire au moins une prédiction basée sur une image","Comprend le concept de prédire","Montre de l''excitation pour vérifier ses prédictions"]}',1,'Plan détaillé avec supports visuels',1756911653522,1757594654119,1,'fr','Français (Immersion)','{"pourDifficultés":["Work with 2 sound families only","Use extra picture supports","Allow peer helpers for sorting","Focus on most distinct sounds (B vs M)"],"pourAvancés":["Sort by ending sounds too","Create their own sound family","Help explain sorting to peers","Find objects in room for each family"],"pourLangue":["Connect to similar sounds in home language","Use extra visual cues and gestures","Allow sorting with home language words","Provide one-on-one sound practice"],"pourPEI":["Modify sorting expectations","Use larger materials for easier manipulation","Allow alternative participation in parade","Celebrate any grouping attempt"]}','{"vocabulary":["même","commence","famille","unique"],"visualSupports":["Vowel sound poster, Family concept visual showing people grouped together","Sound family house posters, Sorting demonstration chart, Picture-word connection cards","Sound family banners or signs, Marching route visual"],"movementBreaks":["Vowel gestures with full body","Pointing to family members in photo","Moving between sorting circles","Acting out picture card meanings","Marching to place cards","Full marching parade around classroom","Sound family chants with actions"]}',NULL,NULL,NULL,NULL,'{"questions":["Les élèves ont-ils atteint les objectifs?","Quelles adaptations étaient nécessaires?","Que ferais-je différemment la prochaine fois?"]}',NULL,'',1,3,'core',1);
INSERT INTO ETFOLessonPlan VALUES('cmf43u3yq00jlvj9tipwzfs4g',23,'Jeu des rimes','cmf43u3yn00jdvj9t4ynrfkm6',1764000000000,45,'Review sound families from yesterday by having students make the B, P, and CH sounds. Explain that today we listen to the END of words.','Rhyme Time - Teach simple rhyme ''Chat, rat, chocolat!'' with rhythm sticks. Show picture cards that rhyme (chat/rat, pain/main, eau/bateau). Students clap when they hear rhyming words.','Rhyme Circle - Students sit in circle and pass a ball. When they catch it, they say one word from today''s rhymes and everyone else says the rhyming partner.','Exprimer le concept de jeu des; Participer à les compétences langagières fondamentales; Développer la conscience phonologique par le jeu dirigé','["Sound family cards from lesson 3","Pointer for word endings","Visual cue for ''end'' concept","Rhythm sticks (25 sets)","Rhyming picture cards (chat/rat, pain/main, eau/bateau)","Chart with rhyme written out","Clapping rhythm visual guide","Soft ball for passing","Rhyme reminder cards (visual supports)","Optional: timer for turn-taking"]',NULL,'Jeu des rimes','Review sound families from yesterday by having students make the B, P, and CH sounds. Explain that today we listen to the END of words.','Rhyme Time - Teach simple rhyme ''Chat, rat, chocolat!'' with rhythm sticks. Show picture cards that rhyme (chat/rat, pain/main, eau/bateau). Students clap when they hear rhyming words.','Rhyme Circle - Students sit in circle and pass a ball. When they catch it, they say one word from today''s rhymes and everyone else says the rhyming partner.','Exprimer le concept de jeu des; Participer à les compétences langagières fondamentales; Développer la conscience phonologique par le jeu dirigé',NULL,NULL,NULL,'formative','{"observable":["Élève écoute attentivement l''histoire","Élève compare prédictions à l''histoire","Élève célèbre les découvertes"],"checkpoints":["Peut comparer au moins une prédiction à l''histoire réelle","Comprend que prédictions incorrectes sont aussi de bonnes pensées","Montre engagement durant l''écoute"]}',1,'Plan détaillé avec supports visuels',1756911653523,1757594654120,1,'fr','Français (Immersion)','{"pourDifficultés":["Use simple one-syllable rhymes only","Provide visual ending cues","Allow English rhyme practice first","Work with partner for support"],"pourAvancés":["Create new rhymes with given words","Find rhymes beyond the lesson examples","Help teach rhyming concept to peers","Try three-word rhyme families"],"pourLangue":["Connect to rhymes in home language","Use familiar English rhymes as bridge","Extra visual and gestural supports","Allow approximate rhyming attempts"],"pourPEI":["Modify participation as needed","Use alternative communication for rhymes","Focus on rhythm rather than exact rhymes","Celebrate any sound pattern recognition"]}','{"vocabulary":["rime","pareil","fin"],"visualSupports":["Sound family poster, Visual showing word beginning vs. ending, Listening ear pointing to end","Rhyming word pairs poster, Rhythm pattern chart, Visual cue for clapping timing","Circle sitting arrangement visual, Rhyme pairs reference chart, Turn-taking cues"],"movementBreaks":["Making B, P, CH sounds with gestures","Pointing to beginnings and endings","Rhythm stick playing","Clapping for rhymes","Standing to act out rhyming words","Arm movements for ball passing","Standing to celebrate good rhymes"]}',NULL,NULL,NULL,NULL,'{"questions":["Les élèves ont-ils atteint les objectifs?","Quelles adaptations étaient nécessaires?","Que ferais-je différemment la prochaine fois?"]}',NULL,'',1,4,'core',1);
INSERT INTO ETFOLessonPlan VALUES('cmf43u3yr00jnvj9tiun3dan2',23,'Mots courts et longs','cmf43u3yn00jdvj9t4ynrfkm6',1764086400000,45,'Practice rhyming from yesterday with ''Chat, rat, chocolat!'' Then show arms for ''court'' (close together) and ''long'' (far apart).','Word Measuring - Show word cards (la, éléphant, chat, ordinateur). Students use arms or fingers to show if words are ''court'' or ''long''. Sort cards into two boxes labeled with visual symbols.','Length Line-up - Students stand and arrange themselves in order from shortest to longest names, with teacher support for pronunciation.','Décrire les mots familiers; Utiliser le vocabulaire thématique en contexte; Développer le vocabulaire français par des activités langagières variées','["Rhyme cards from lesson 4","Visual demonstration props for short/long","Word cards with varied lengths (30-40 cards)","Two sorting boxes","Short/long symbol labels","Measuring tape or ruler (demonstration)","Student finger-counting cards","Name cards for visual support","Tape for floor line (optional)","Number line for reference"]',NULL,'Mots courts et longs','Practice rhyming from yesterday with ''Chat, rat, chocolat!'' Then show arms for ''court'' (close together) and ''long'' (far apart).','Word Measuring - Show word cards (la, éléphant, chat, ordinateur). Students use arms or fingers to show if words are ''court'' or ''long''. Sort cards into two boxes labeled with visual symbols.','Length Line-up - Students stand and arrange themselves in order from shortest to longest names, with teacher support for pronunciation.','Décrire les mots familiers; Utiliser le vocabulaire thématique en contexte; Développer le vocabulaire français par des activités langagières variées',NULL,NULL,NULL,'formative','{"observable":["Élève participe au récit collectif","Élève utilise gestes et mots pour reconter","Élève comprend l''ordre séquentiel"],"checkpoints":["Peut contribuer au moins une partie de l''histoire","Utilise mots de transition ou gestes appropriés","Montre fierté de reconter des histoires"]}',1,'Plan détaillé avec supports visuels',1756911653524,1757594654121,1,'fr','Français (Immersion)','{"pourDifficultés":["Use very distinct length differences","Allow visual letter counting","Work with 2-3 examples at a time","Pair with confident partner"],"pourAvancés":["Count exact letters or syllables","Find patterns in long vs short words","Help explain length concept to peers","Create own word length categories"],"pourLangue":["Use familiar words from home language for comparison","Extra visual supports for length concept","Allow approximate length judgments","Connect to English word length patterns"],"pourPEI":["Modify length comparison expectations","Use alternative methods for measuring","Allow flexible participation in line-up","Celebrate any categorization attempt"]}','{"vocabulary":["court","long","comparer"],"visualSupports":["Short vs long comparison poster, Arm gesture demonstration chart, Rhyme reminder cards","Word length comparison chart, Sorting box labels with symbols, Finger-counting guide","Length ordering example, Name length comparison chart, Visual line-up guide"],"movementBreaks":["Rhyme chanting with gestures","Short and long arm movements","Arm stretching for word lengths","Moving between sorting boxes","Acting out long and short with whole body","Standing and moving in line","Celebrating with length gestures"]}',NULL,NULL,NULL,NULL,'{"questions":["Les élèves ont-ils atteint les objectifs?","Quelles adaptations étaient nécessaires?","Que ferais-je différemment la prochaine fois?"]}',NULL,'',1,5,'core',1);
INSERT INTO ETFOLessonPlan VALUES('cmf43u3ys00jpvj9trnuolqn5',23,'Syllabes et battements','cmf43u3yn00jdvj9t4ynrfkm6',1764172800000,45,'Review long and short words with arm gestures. Introduce clapping by clapping your name slowly: ''Ma-da-me Smith'' (3 claps).','Name Clapping Circle - Students sit in circle with instruments. Each student claps their name syllables and everyone repeats. Then try picture words: ''é-lé-phant'', ''chat'', ''cho-co-lat''.','Syllable Symphony - Whole class claps ''Au re-voir'' (3 claps) together to end the lesson.','Lire les syllabes dans les mots; Utiliser les compétences langagières fondamentales; Développer le vocabulaire français par des activités langagières variées','["Long/short word cards from lesson 5","Demonstration name card","Optional: drum for rhythm","Rhythm instruments (sticks, shakers) - 25 sets","Picture cards for target words","Visual syllable breakdown cards","Name cards for students","''Au revoir'' visual card","Optional: conductor''s baton for teacher"]',NULL,'Syllabes et battements','Review long and short words with arm gestures. Introduce clapping by clapping your name slowly: ''Ma-da-me Smith'' (3 claps).','Name Clapping Circle - Students sit in circle with instruments. Each student claps their name syllables and everyone repeats. Then try picture words: ''é-lé-phant'', ''chat'', ''cho-co-lat''.','Syllable Symphony - Whole class claps ''Au re-voir'' (3 claps) together to end the lesson.','Lire les syllabes dans les mots; Utiliser les compétences langagières fondamentales; Développer le vocabulaire français par des activités langagières variées',NULL,NULL,NULL,'formative','{"observable":["Élève reconnaît différents types de textes","Élève participe au tri","Élève fait des connexions avec sa vie"],"checkpoints":["Peut identifier au moins 2 types différents de textes","Comprend que les textes ont différents buts","Fait des liens entre école et maison"]}',1,'Plan détaillé avec supports visuels',1756911653525,1757594654122,1,'fr','Français (Immersion)','{"pourDifficultés":["Start with simple 1-2 syllable words","Use physical chin support for syllables","Allow approximation of clapping rhythm","Pair with strong syllable counter"],"pourAvancés":["Try 4+ syllable words","Count syllables in sentences","Create rhythms for syllable patterns","Help demonstrate to struggling peers"],"pourLangue":["Connect to rhythm patterns in home language","Use familiar words for practice","Allow approximate syllable identification","Focus on rhythm rather than perfect counting"],"pourPEI":["Modify clapping expectations (allow any rhythm participation)","Use alternative movement patterns","Focus on participation rather than accuracy","Provide quiet instruments if needed"]}','{"vocabulary":["syllabe","battre","partie"],"visualSupports":["Syllable clapping demonstration poster, Name broken into parts visually","Circle arrangement guide, Syllable counting visual aids, Picture-word syllable charts","''Au re-voir'' broken into syllables visually, Conductor gestures guide"],"movementBreaks":["Arm gestures for long/short words","Clapping demonstration with full body","Playing rhythm instruments","Moving around circle for turns","Acting out picture words","Standing for symphony performance","Dramatic conducting gestures"]}',NULL,NULL,NULL,NULL,'{"questions":["Les élèves ont-ils atteint les objectifs?","Quelles adaptations étaient nécessaires?","Que ferais-je différemment la prochaine fois?"]}',NULL,'',1,6,'core',1);
INSERT INTO ETFOLessonPlan VALUES('cmf43u3yt00jrvj9tlgxtcsm2',23,'Petits mots magiques','cmf43u3yn00jdvj9t4ynrfkm6',1764259200000,45,'Practice syllable clapping with ''Bon-jour'' and ''Au re-voir''. Show magic wand and explain these are ''mots magiques'' that appear everywhere.','Magic Word Hunt - Show 3 high-frequency words (le, la, et) on large cards. Look through simple French books together to find these ''magic words''. Students point and count how many times they appear.','Magic Word Spell - Students stand and ''cast spells'' by saying each magic word while waving imaginary wands: ''le!'', ''la!'', ''et!''','Écrire les mots familiers; Utiliser le vocabulaire thématique en contexte; Développer le vocabulaire français par des activités langagières variées','["Magic wand (decorative or toy)","Sparkly stars or magic props","''Bon-jour'' and ''Au revoir'' syllable cards","Large magic word cards (le, la, et)","Simple French books (20-25 copies)","Magnifying glasses","Tally counters or pencils","Stickers for found words","Magic word cards for reference","Optional: craft stick wands for each student"]',NULL,'Petits mots magiques','Practice syllable clapping with ''Bon-jour'' and ''Au re-voir''. Show magic wand and explain these are ''mots magiques'' that appear everywhere.','Magic Word Hunt - Show 3 high-frequency words (le, la, et) on large cards. Look through simple French books together to find these ''magic words''. Students point and count how many times they appear.','Magic Word Spell - Students stand and ''cast spells'' by saying each magic word while waving imaginary wands: ''le!'', ''la!'', ''et!''','Écrire les mots familiers; Utiliser le vocabulaire thématique en contexte; Développer le vocabulaire français par des activités langagières variées',NULL,NULL,NULL,'formative','{"observable":["Élève examine images pour trouver indices","Élève fait des tentatives logiques de devinette","Élève utilise stratégie de détective"],"checkpoints":["Peut identifier au moins un indice visuel","Fait des suppositions raisonnables sur mots inconnus","Comprend l''idée de chercher des indices"]}',1,'Plan détaillé avec supports visuels',1756911653526,1757594654123,1,'fr','Français (Immersion)','{"pourDifficultés":["Focus on one magic word at a time","Use finger tracking for word recognition","Provide word cards for matching","Allow peer support for hunting"],"pourAvancés":["Learn additional high-frequency words","Count total occurrences across multiple books","Help teach recognition strategies to peers","Notice patterns in word usage"],"pourLangue":["Connect to similar function words in English","Use visual word shapes and patterns","Allow bilingual word recognition strategies","Practice with familiar simple texts"],"pourPEI":["Modify word recognition expectations","Use larger text or different materials","Allow alternative participation in spell-casting","Focus on engagement rather than accuracy"]}','{"vocabulary":["petit","magique","partout"],"visualSupports":["Magic words concept poster with stars, Syllable breakdown cards from lesson 6","High-frequency word poster, Counting tally chart, Magic word reference cards","Spell-casting gesture guide, Magic words with visual cues"],"movementBreaks":["Clapping syllables with magic gestures","Waving magic wand movements","Moving around to share books","Pointing and reaching to find words","Victory gestures for discoveries","Standing and wand-waving gestures","Dramatic spell-casting movements"]}',NULL,NULL,NULL,NULL,'{"questions":["Les élèves ont-ils atteint les objectifs?","Quelles adaptations étaient nécessaires?","Que ferais-je différemment la prochaine fois?"]}',NULL,'',1,7,'core',1);
INSERT INTO ETFOLessonPlan VALUES('cmf43u3yu00jtvj9t0lxexox7',23,'Construire des mots','cmf43u3yn00jdvj9t4ynrfkm6',1764345600000,45,'Review magic words ''le'', ''la'', ''et'' by having students spot them on the word wall. Show letter tiles and explain we''re going to BUILD words like construction workers.','Letter Construction - Give students magnetic letters. Start with simple 3-letter words (pot, ami, eau). Teacher builds first word together, then students try to copy and build new ones with guidance.','Word Builders'' Show - Students hold up one word they built and say it proudly. Everyone claps for the ''constructors''.','Raconter les mots familiers; Utiliser le vocabulaire thématique en contexte; Développer le vocabulaire français par des activités langagières variées','["Word wall with magic words","Letter tiles/magnetic letters","Construction worker hat (optional)","Building blocks for demonstration","Magnetic letters (full alphabet sets for pairs)","Magnetic boards or cookie sheets","Word building cards for reference","Letter sound cards","Picture cards for target words","Built words from activity","Applause cue cards","Optional: construction badges/stickers"]',NULL,'Construire des mots','Review magic words ''le'', ''la'', ''et'' by having students spot them on the word wall. Show letter tiles and explain we''re going to BUILD words like construction workers.','Letter Construction - Give students magnetic letters. Start with simple 3-letter words (pot, ami, eau). Teacher builds first word together, then students try to copy and build new ones with guidance.','Word Builders'' Show - Students hold up one word they built and say it proudly. Everyone claps for the ''constructors''.','Raconter les mots familiers; Utiliser le vocabulaire thématique en contexte; Développer le vocabulaire français par des activités langagières variées',NULL,NULL,NULL,'formative','{"observable":["Élève pose des questions sur les textes","Élève utilise mots questions appropriés","Élève comprend le but des questions"],"checkpoints":["Peut poser au moins une question simple sur un texte","Utilise ''qui'', ''quoi'' ou gestes appropriés","Comprend que questions aident à comprendre"]}',1,'Plan détaillé avec supports visuels',1756911653526,1757594654124,1,'fr','Français (Immersion)','{"pourDifficultés":["Start with 2-letter combinations","Use picture cues for target words","Allow letter copying rather than independent building","Work with partner for support"],"pourAvancés":["Try 4+ letter words","Build word families","Create rhyming words","Help demonstrate building process to peers"],"pourLangue":["Use familiar words for building practice","Connect to English spelling patterns where helpful","Allow sound approximations","Use extra visual supports for letter-sound connections"],"pourPEI":["Modify fine motor expectations","Use larger letters or different materials","Focus on letter recognition rather than building","Celebrate any letter manipulation attempts"]}','{"vocabulary":["construire","combiner","nouveau"],"visualSupports":["Construction worker poster, Word building demonstration chart, Magic words reference","Word building steps poster, Letter-sound reference chart, Target word picture cards","Show and tell format guide, Celebration clapping poster"],"movementBreaks":["Pointing to words on wall","Construction worker movements and gestures","Reaching and placing letters","Standing to share built words","Acting out word meanings","Standing to show words","Enthusiastic clapping and cheering"]}',NULL,NULL,NULL,NULL,'{"questions":["Les élèves ont-ils atteint les objectifs?","Quelles adaptations étaient nécessaires?","Que ferais-je différemment la prochaine fois?"]}',NULL,'',1,8,'core',1);
INSERT INTO ETFOLessonPlan VALUES('cmf43u3yv00jvvj9t7ef2ex8n',23,'Mots de la même famille','cmf43u3yn00jdvj9t4ynrfkm6',1764604800000,45,'Review word building by having students build ''chat'' with letters. Show family photo again and explain word families - words that look and sound similar at the end.','Word Family Houses - Set up three ''houses'' (sorting mats) for -at, -an, -in families. Students sort word cards (chat, rat, chocolat / plan, Jean, maman / fin, pain, main) into correct family houses.','Family Reunion - Each word family group stands together and chants their family ending: ''-at, -at, we''re the -at family!''','Communiquer les mots familiers; Utiliser le vocabulaire thématique en contexte; Développer la communication orale par des activités langagières variées','["Magnetic letters for ''chat''","Family photo from lesson 3","Word family concept poster","Three house sorting mats or hula hoops","Word cards for each family (30+ cards total)","Family ending labels (-at, -an, -in)","Picture supports for vocabulary words","Images de familles diverses (monoparentales, recomposées, multiculturelles)","Family ending banners or signs","Optional: simple instruments for chanting rhythm"]',NULL,'Mots de la même famille','Review word building by having students build ''chat'' with letters. Show family photo again and explain word families - words that look and sound similar at the end.','Word Family Houses - Set up three ''houses'' (sorting mats) for -at, -an, -in families. Students sort word cards (chat, rat, chocolat / plan, Jean, maman / fin, pain, main) into correct family houses.','Family Reunion - Each word family group stands together and chants their family ending: ''-at, -at, we''re the -at family!''','Communiquer les mots familiers; Utiliser le vocabulaire thématique en contexte; Développer la communication orale par des activités langagières variées',NULL,NULL,NULL,'formative','{"observable":["Élève identifie un livre préféré","Élève partage avec partenaire","Élève donne une raison simple pour son choix"],"checkpoints":["Peut identifier au moins un livre aimé","Participe au partage avec support","Comprend que chacun a des préférences différentes"]}',1,'Plan détaillé avec supports visuels',1756911653527,1757594654125,1,'fr','Français (Immersion)','{"pourDifficultés":["Work with one word family at a time","Use picture cues for all words","Allow peer support for sorting","Focus on most obvious patterns"],"pourAvancés":["Find additional words for each family","Create new word families","Help explain patterns to classmates","Try families with different vowel patterns"],"pourLangue":["Connect to word patterns in home language","Use extra visual and picture supports","Allow discussion of pattern recognition in both languages","Focus on sound patterns over spelling"],"pourPEI":["Modify sorting expectations","Use fewer word families","Allow flexible participation in group activities","Celebrate pattern recognition at any level"]}','{"vocabulary":["famille","appartenir","groupe","unique"],"visualSupports":["Word families explanation chart, ''Chat'' building demonstration, Family connection visual","Word family house posters, Sorting demonstration chart, Picture-word connection cards for difficult vocabulary","Family chant format poster, Ending pattern visual cues"],"movementBreaks":["Building letters with hands","Pointing to family photo connections","Moving between family houses","Acting out word meanings","Placing cards with dramatic gestures","Standing in family groups","Chanting with full body movement and gestures"]}',NULL,NULL,NULL,NULL,'{"questions":["Les élèves ont-ils atteint les objectifs?","Quelles adaptations étaient nécessaires?","Que ferais-je différemment la prochaine fois?"]}',NULL,'',1,9,'core',1);
INSERT INTO ETFOLessonPlan VALUES('cmf43u3yw00jxvj9t0zhkwafk',23,'Chasse aux mots','cmf43u3yn00jdvj9t4ynrfkm6',1764691200000,45,'Review word families by chanting ''-at, -an, -in'' with actions. Put on detective hats/magnifying glasses and explain we''re going hunting for words in real books.','Text Detective Work - Give pairs of students simple French texts. Have them hunt for previously learned words (le, la, et, words from families). Students circle or highlight words they find and keep count.','Detective Report - Each pair reports one interesting word they found. Class celebrates all discoveries with detective applause.','Exprimer les mots familiers; Utiliser le vocabulaire thématique en contexte; Développer la communication orale par des activités langagières variées','["Detective hats or headbands","Magnifying glasses (real or toy)","Word family chant cards from lesson 9","Simple French texts (25+ copies)","Highlighters or pencils for circling","Word hunt checklist cards","Magnifying glasses","Tally sheets for counting","Detective reporting format card","Found word examples","Celebration applause cue cards"]',NULL,'Chasse aux mots','Review word families by chanting ''-at, -an, -in'' with actions. Put on detective hats/magnifying glasses and explain we''re going hunting for words in real books.','Text Detective Work - Give pairs of students simple French texts. Have them hunt for previously learned words (le, la, et, words from families). Students circle or highlight words they find and keep count.','Detective Report - Each pair reports one interesting word they found. Class celebrates all discoveries with detective applause.','Exprimer les mots familiers; Utiliser le vocabulaire thématique en contexte; Développer la communication orale par des activités langagières variées',NULL,NULL,NULL,'formative','{"observable":["Élève identifie au moins un élément similaire ou différent","Élève participe à l''activité de comparaison","Élève comprend le concept de comparer"],"checkpoints":["Peut trouver une similitude ou différence entre deux histoires","Utilise vocabulaire ''même'' ou ''différent''","Comprend que histoires peuvent avoir éléments en commun"]}',1,'Plan détaillé avec supports visuels',1756911653529,1757594654126,1,'fr','Français (Immersion)','{"pourDifficultés":["Use larger text materials","Focus on 2-3 target words only","Provide word cards for matching rather than free searching","Work with stronger reading partner"],"pourAvancés":["Hunt for additional word types (action words, describing words)","Count and compare frequency of different words","Help struggling pairs with their searches","Use more complex texts"],"pourLangue":["Use texts with familiar vocabulary","Allow searching for cognates or English-French connections","Provide picture supports for target words","Focus on word recognition over text comprehension"],"pourPEI":["Modify search expectations","Use highlighting instead of circling if easier","Allow verbal reporting of found words","Celebrate any word recognition in text"]}','{"vocabulary":["chercher","trouver","texte"],"visualSupports":["Detective poster, Word family reference chart, Hunting/searching visual cues","Target words poster, Detective investigation process chart, Counting/tally visual guides","Detective report format poster, Celebration applause guide"],"movementBreaks":["Word family chanting with actions","Putting on detective gear with drama","Moving around to work with different pairs","Acting out detective searching behaviors","Celebrating discoveries with gestures","Standing for detective reports","Special detective applause gestures"]}',NULL,NULL,NULL,NULL,'{"questions":["Les élèves ont-ils atteint les objectifs?","Quelles adaptations étaient nécessaires?","Que ferais-je différemment la prochaine fois?"]}',NULL,'',1,10,'core',1);
INSERT INTO ETFOLessonPlan VALUES('cmf43u3yx00jzvj9tanf8df1q',23,'Inventer avec les mots','cmf43u3yn00jdvj9t4ynrfkm6',1764777600000,45,'Review word hunting by showing some words they found yesterday. Explain that now we''ll put words together to create messages, like building with blocks.','Sentence Building Workshop - Provide word cards (le, chat, et, petit, grand, la, maison). Students work in pairs to arrange 3-4 words into simple sentences like ''Le chat et la maison''. Teacher circulates to help with word order.','Sentence Share Circle - Students take turns showing their sentence creations. Class repeats each sentence together.','Décrire les mots familiers; Utiliser le vocabulaire thématique en contexte; Développer la communication orale par des activités langagières variées','["Word cards from lesson 10 hunts","Building blocks for demonstration","Message/communication visual","Word card sets for each pair (40-50 cards per set)","Sentence building mats","Picture supports for vocabulary","Sentence pattern guide cards","Created sentences from activity","Sharing circle arrangement guide"]',NULL,'Inventer avec les mots','Review word hunting by showing some words they found yesterday. Explain that now we''ll put words together to create messages, like building with blocks.','Sentence Building Workshop - Provide word cards (le, chat, et, petit, grand, la, maison). Students work in pairs to arrange 3-4 words into simple sentences like ''Le chat et la maison''. Teacher circulates to help with word order.','Sentence Share Circle - Students take turns showing their sentence creations. Class repeats each sentence together.','Décrire les mots familiers; Utiliser le vocabulaire thématique en contexte; Développer la communication orale par des activités langagières variées',NULL,NULL,NULL,'formative','{"observable":["Élève explore activement les textes informatifs","Élève identifie des faits réels","Élève comprend la différence avec histoires imaginaires"],"checkpoints":["Peut identifier au moins un fait appris","Comprend que certains livres enseignent des choses vraies","Montre intérêt pour apprendre de nouveaux faits"]}',1,'Plan détaillé avec supports visuels',1756911653529,1757594654127,1,'fr','Français (Immersion)','{"pourDifficultés":["Use 2-word combinations only","Provide sentence frames with blanks","Use picture cues for word meaning","Allow copying successful patterns"],"pourAvancés":["Create multiple sentences","Use connecting words like ''et''","Try different sentence types","Help explain sentence building to peers"],"pourLangue":["Compare to English sentence patterns","Use familiar vocabulary in sentences","Allow approximate French word order","Focus on meaning over perfect grammar"],"pourPEI":["Modify sentence length expectations","Use visual sentence building supports","Allow alternative communication methods","Celebrate any word combination attempts"]}','{"vocabulary":["inventer","phrase","créer"],"visualSupports":["Sentence building concept poster, Building blocks metaphor chart, Found words reference","French sentence pattern poster, Word order guide, Picture-word connection charts","Sentence sharing format poster, Circle time arrangement visual"],"movementBreaks":["Building block stacking gestures","Pointing to remembered hunt words","Moving word cards around on mats","Standing to share progress with teacher","Acting out sentence meanings","Standing to share sentences","Gestures and actions while reading sentences"]}',NULL,NULL,NULL,NULL,'{"questions":["Les élèves ont-ils atteint les objectifs?","Quelles adaptations étaient nécessaires?","Que ferais-je différemment la prochaine fois?"]}',NULL,'',1,11,'core',1);
INSERT INTO ETFOLessonPlan VALUES('cmf43u3yy00k1vj9tl5wnks37',23,'Mes mots préférés','cmf43u3yn00jdvj9t4ynrfkm6',1764864000000,45,'Review sentence building by having class create one sentence together. Show heart shape and explain everyone has ''mots préférés'' - favorite words that they like best.','Favorite Word Gallery - Students choose 3 favorite French words from all those learned. They write/draw each word on heart-shaped paper and explain why they like it: ''J''aime... parce que...'' (with teacher support).','Favorite Word Show-and-Tell - Students share one favorite word and show their heart. Class says ''C''est beau!'' after each share.','Lire les mots familiers; Utiliser le vocabulaire thématique en contexte; Développer la communication orale par des activités langagières variées','["Word cards from previous lessons","Large heart shape prop","Favorite concept visual aids","Heart-shaped paper (75+ pieces)","Crayons/markers","Word reference charts from all lessons","Reason sentence starters","Glue sticks for pictures","Completed heart word papers","''C''est beau!'' response card for class"]',NULL,'Mes mots préférés','Review sentence building by having class create one sentence together. Show heart shape and explain everyone has ''mots préférés'' - favorite words that they like best.','Favorite Word Gallery - Students choose 3 favorite French words from all those learned. They write/draw each word on heart-shaped paper and explain why they like it: ''J''aime... parce que...'' (with teacher support).','Favorite Word Show-and-Tell - Students share one favorite word and show their heart. Class says ''C''est beau!'' after each share.','Lire les mots familiers; Utiliser le vocabulaire thématique en contexte; Développer la communication orale par des activités langagières variées',NULL,NULL,NULL,'formative','{"observable":["Élève participe à la lecture partagée","Élève essaie d''utiliser expression","Élève montre plaisir à lire ensemble"],"checkpoints":["Participe à la lecture partagée d''une façon ou d''une autre","Essaie d''ajuster sa voix selon le texte","Comprend que lecture expressive rend histoires plus amusantes"]}',1,'Plan détaillé avec supports visuels',1756911653530,1757594654128,1,'fr','Français (Immersion)','{"pourDifficultés":["Choose from limited word selection","Use picture reasons instead of verbal explanations","Allow teacher scribing for word writing","Focus on 1-2 favorites instead of 3"],"pourAvancés":["Write simple sentences about why they like words","Choose favorites from different word categories","Help peers explain their choices","Create word recommendation for classmates"],"pourLangue":["Allow connection to home language favorites","Use pictures and gestures for explanations","Compare favorite sounds across languages","Support with bilingual word connections"],"pourPEI":["Modify writing/drawing expectations","Allow alternative ways to show favorites","Support choice-making with visual aids","Celebrate any word preference expression"]}','{"vocabulary":["préféré","choisir","pourquoi"],"visualSupports":["Favorite words concept poster, Heart shape for preference, Class word collection display","All unit vocabulary displayed, ''J''aime... parce que...'' sentence frame, Favorite word examples","Show-and-tell format guide, Class response poster"],"movementBreaks":["Building class sentence with gestures","Heart shape hand movements","Moving around to reference word charts","Sharing choices with neighbors","Acting out word meanings","Standing to share","Holding up heart papers","Clapping and celebrating responses"]}',NULL,NULL,NULL,NULL,'{"questions":["Les élèves ont-ils atteint les objectifs?","Quelles adaptations étaient nécessaires?","Que ferais-je différemment la prochaine fois?"]}',NULL,'',1,12,'core',1);
INSERT INTO ETFOLessonPlan VALUES('cmf43u3yz00k3vj9tmix67p5n',23,'Dictionnaire d''images','cmf43u3yn00jdvj9t4ynrfkm6',1764950400000,45,'Review favorite words by having a few students share. Show a real dictionary and explain it''s a book that organizes all words - we''ll make our own with pictures.','Dictionary Makers - Students create personal picture dictionaries by sorting their learned words and drawing pictures for each. Start with simple alphabetical order (A words together, B words together, etc.).','Dictionary Celebration - Students flip through their dictionaries and share one page they''re proud of. Class applauds each mini-dictionary.','Écrire le concept de dictionnaire d''images; Utiliser les compétences langagières fondamentales; Développer la compréhension par des activités langagières variées','["Real French dictionary (picture dictionary ideal)","Favorite word hearts from lesson 12","Dictionary concept visual aids","Small booklets or folded paper (25 sets)","Word lists from all lessons","Crayons/colored pencils","Alphabet reference strips","Picture idea cards","Stapler for booklet assembly","Completed student dictionaries","Celebration applause cue"]',NULL,'Dictionnaire d''images','Review favorite words by having a few students share. Show a real dictionary and explain it''s a book that organizes all words - we''ll make our own with pictures.','Dictionary Makers - Students create personal picture dictionaries by sorting their learned words and drawing pictures for each. Start with simple alphabetical order (A words together, B words together, etc.).','Dictionary Celebration - Students flip through their dictionaries and share one page they''re proud of. Class applauds each mini-dictionary.','Écrire le concept de dictionnaire d''images; Utiliser les compétences langagières fondamentales; Développer la compréhension par des activités langagières variées',NULL,NULL,NULL,'formative','{"observable":["Élève crée au moins une question sur le texte","Élève pose sa question à un partenaire","Élève comprend que questions aident à penser"],"checkpoints":["Peut créer ou compléter au moins une question appropriée","Partage sa question avec autres","Comprend l''importance de questionner pour comprendre"]}',1,'Plan détaillé avec supports visuels',1756911653531,1757594654129,1,'fr','Français (Immersion)','{"pourDifficultés":["Use fewer words (5-8 only)","Provide pre-drawn pictures to match with words","Allow simple copying of words","Focus on personal meaningful words"],"pourAvancés":["Include word definitions in simple French","Add more vocabulary beyond lesson words","Create themed dictionary sections","Help peers organize their dictionaries"],"pourLangue":["Include home language translations if desired","Use familiar words as dictionary foundation","Allow creative organization systems","Focus on visual representation over text"],"pourPEI":["Modify fine motor expectations for drawing","Use alternative organization methods","Allow collaborative dictionary creation","Focus on word collection rather than perfect organization"]}','{"vocabulary":["dictionnaire","organiser","image"],"visualSupports":["Dictionary concept poster, Organization example chart, Picture dictionary sample pages","Alphabet organization guide, Picture drawing examples, Dictionary page layout model","Dictionary celebration format, Applause and appreciation cues"],"movementBreaks":["Sharing favorite word hearts","Flipping through real dictionary pages","Moving around to reference alphabet charts","Standing to share progress","Acting out words while drawing","Standing to share dictionaries","Flipping through pages","Celebratory applause movements"]}',NULL,NULL,NULL,NULL,'{"questions":["Les élèves ont-ils atteint les objectifs?","Quelles adaptations étaient nécessaires?","Que ferais-je différemment la prochaine fois?"]}',NULL,'',1,13,'core',1);
INSERT INTO ETFOLessonPlan VALUES('cmf43u3z000k5vj9tarvc94vg',23,'Présentation de mes découvertes','cmf43u3yn00jdvj9t4ynrfkm6',1765209600000,45,'Students get their dictionaries from yesterday. Explain that good explorers share their discoveries with others - like scientists or treasure hunters.','Word Explorer Presentations - Each student chooses 2-3 words from their dictionary to present to the class. They show the word, picture, and teach it to classmates. Audience repeats each new word.','Explorer Celebration - Give each presenter a ''Word Explorer'' sticker. Class chants ''Nous sommes des explorateurs de mots!'' to celebrate everyone''s learning journey.','Raconter le concept de présentation de; Présenter les compétences langagières fondamentales; Développer la compréhension par le partage des apprentissages','["Student dictionaries from lesson 13","Explorer/scientist visual aids","Treasure hunter props","Student dictionaries","Presentation space/chair","Optional: microphone prop","Audience response cue cards","Word Explorer stickers (25+)","Class motto poster","Celebration props"]',NULL,'Présentation de mes découvertes','Students get their dictionaries from yesterday. Explain that good explorers share their discoveries with others - like scientists or treasure hunters.','Word Explorer Presentations - Each student chooses 2-3 words from their dictionary to present to the class. They show the word, picture, and teach it to classmates. Audience repeats each new word.','Explorer Celebration - Give each presenter a ''Word Explorer'' sticker. Class chants ''Nous sommes des explorateurs de mots!'' to celebrate everyone''s learning journey.','Raconter le concept de présentation de; Présenter les compétences langagières fondamentales; Développer la compréhension par le partage des apprentissages',NULL,NULL,NULL,'formative','{"observable":["Élève sélectionne éléments pour portfolio","Élève montre fierté de ses apprentissages","Élève peut identifier au moins une chose apprise"],"checkpoints":["Crée un portfolio personnalisé avec aide","Partage au moins un apprentissage sur les textes","Démontre fierté de son parcours d''explorateur"]}',1,'Plan détaillé avec supports visuels',1756911653532,1757594654130,1,'fr','Français (Immersion)','{"pourDifficultés":["Allow very brief presentations (1 word)","Provide presentation sentence frames","Allow picture-only sharing","Pair with confident presenter"],"pourAvancés":["Present more words or create teaching activities","Help facilitate classmate presentations","Add explanations about why words are interesting","Lead class in response activities"],"pourLangue":["Allow explanations in home language if needed","Use visual supports heavily","Focus on pronunciation practice rather than explanation","Celebrate multilingual word knowledge"],"pourPEI":["Modify presentation expectations","Allow alternative sharing methods","Provide extra processing time","Focus on participation rather than performance"]}','{"vocabulary":["présenter","découverte","partager"],"visualSupports":["Explorer sharing concept poster, Scientist presentation model, Discovery sharing examples","Presentation format guide, Audience participation cues, ''Good presenter'' behavior chart","Class motto display, Celebration format guide, Unit learning journey visual"],"movementBreaks":["Getting dictionaries from storage","Explorer discovery gestures","Standing for presentations","Moving to presentation area","Audience participation gestures","Standing for sticker ceremony","Class motto chanting with actions"]}',NULL,NULL,NULL,NULL,'{"questions":["Les élèves ont-ils atteint les objectifs?","Quelles adaptations étaient nécessaires?","Que ferais-je différemment la prochaine fois?"]}',NULL,'',1,14,'core',1);
INSERT INTO ETFOLessonPlan VALUES('cmf43u3z100k7vj9ta59qvb77',23,'Jeux de mots créatifs','cmf43u3yn00jdvj9t4ynrfkm6',1765296000000,45,'Celebrate completing the core lessons! Explain that now we get to PLAY with all the words we''ve learned. Show game materials and build excitement.','Word Game Stations - Set up 3 game stations: 1) Word Bingo with learned words, 2) Musical Words (walk around, when music stops grab a word card), 3) Word Memory matching game. Students rotate every 8 minutes.','Game Champions Circle - Everyone sits and shares which game was most fun. Give everyone a ''Word Game Champion'' sticker because everyone played well.','Communiquer les mots familiers; Participer à le vocabulaire thématique en contexte; Développer la compréhension par le jeu dirigé','["Game station materials preview","Celebration banners","Core lessons completion certificate","Bingo cards and markers (Station 1)","Music player and word cards (Station 2)","Memory matching card sets (Station 3)","Timer for rotations","Station instruction cards","Word Game Champion stickers (25+)","Circle sitting arrangement","Game reflection prompts"]',NULL,'Jeux de mots créatifs','Celebrate completing the core lessons! Explain that now we get to PLAY with all the words we''ve learned. Show game materials and build excitement.','Word Game Stations - Set up 3 game stations: 1) Word Bingo with learned words, 2) Musical Words (walk around, when music stops grab a word card), 3) Word Memory matching game. Students rotate every 8 minutes.','Game Champions Circle - Everyone sits and shares which game was most fun. Give everyone a ''Word Game Champion'' sticker because everyone played well.','Communiquer les mots familiers; Participer à le vocabulaire thématique en contexte; Développer la compréhension par le jeu dirigé',NULL,NULL,NULL,'formative','{"observable":["L''élève utilise 3 nouveaux mots français dans ses phrases","L''élève prononce clairement les sons français ciblés","L''élève comprend les instructions avec les nouveaux mots","L''élève fait les gestes associés aux mots appris"],"checkpoints":["Reconnaît les mots à l''oral sans aide visuelle","Peut répéter les mots avec la bonne prononciation","Utilise les mots en contexte approprié","Montre compréhension par actions ou réponses"]}',1,'Plan détaillé avec supports visuels',1756911653533,1757594654131,1,'fr','Français (Immersion)','{"pourDifficultés":["Provide game partners for support","Use simpler word sets","Allow longer time at stations","Focus on participation rather than game success"],"pourAvancés":["Add challenge variations to games","Help facilitate game stations","Create new game rules","Support struggling players"],"pourLangue":["Allow use of familiar words from any language","Pair with bilingual support","Focus on fun rather than perfect French","Use visual game supports"],"pourPEI":["Modify game participation as needed","Provide sensory supports if needed","Allow alternative ways to participate","Focus on enjoyment of word play"]}','{"vocabulary":["jeu","créatif","s''amuser"],"visualSupports":["Game station preview poster, Celebration of learning visual, Word games excitement chart","Station instruction posters, Rotation schedule visual, Game rules charts for each station","Circle sharing format, Game reflection guide, Champion celebration visual"],"movementBreaks":["Celebration gestures","Preview of game movements","Moving between stations","Active participation in all games","Dancing during musical words","Moving to circle formation","Standing for champion sticker ceremony"]}',NULL,NULL,NULL,NULL,'{"questions":["Les élèves ont-ils atteint les objectifs?","Quelles adaptations étaient nécessaires?","Que ferais-je différemment la prochaine fois?"]}',NULL,'',1,15,'extension',1);
INSERT INTO ETFOLessonPlan VALUES('cmf43u3z200k9vj9t6i2zyf1c',23,'Histoires avec nos mots','cmf43u3yn00jdvj9t4ynrfkm6',1765382400000,45,'Review favorite word games from yesterday. Show a simple picture book and explain that stories are made with words - we can make stories with OUR words.','Mini Story Creators - Students choose 4-5 words from their collection and create a simple story. They can draw pictures and use simple sentences like ''Le chat et le chien...'' Template: Beginning, middle, end with pictures.','Story Time Circle - 3-4 volunteers share their mini stories. Class responds with ''C''est une belle histoire!'' after each one.','Exprimer les mots familiers; Raconter le vocabulaire thématique en contexte; Développer la compréhension par la narration','["Simple French picture book","Game memories chart from lesson 15","Story concept visual aids","Story template papers (folded in thirds)","Student word collections/dictionaries","Crayons/markers","Simple sentence starter cards","Story idea picture prompts","Student created stories","Class response cue card","Cozy story circle setup"]',NULL,'Histoires avec nos mots','Review favorite word games from yesterday. Show a simple picture book and explain that stories are made with words - we can make stories with OUR words.','Mini Story Creators - Students choose 4-5 words from their collection and create a simple story. They can draw pictures and use simple sentences like ''Le chat et le chien...'' Template: Beginning, middle, end with pictures.','Story Time Circle - 3-4 volunteers share their mini stories. Class responds with ''C''est une belle histoire!'' after each one.','Exprimer les mots familiers; Raconter le vocabulaire thématique en contexte; Développer la compréhension par la narration',NULL,NULL,NULL,'formative','{"observable":["L''élève utilise 3 nouveaux mots français dans ses phrases","L''élève prononce clairement les sons français ciblés","L''élève comprend les instructions avec les nouveaux mots","L''élève fait les gestes associés aux mots appris"],"checkpoints":["Reconnaît les mots à l''oral sans aide visuelle","Peut répéter les mots avec la bonne prononciation","Utilise les mots en contexte approprié","Montre compréhension par actions ou réponses"]}',1,'Plan détaillé avec supports visuels',1756911653534,1757594654132,1,'fr','Français (Immersion)','{"pourDifficultés":["Use 2-3 words only","Allow picture-only stories","Provide story templates with blanks","Work with partner support"],"pourAvancés":["Create longer stories with multiple sentences","Add dialogue or character emotions","Help peers develop their stories","Create story illustrations with detail"],"pourLangue":["Allow bilingual storytelling","Use familiar story patterns from home culture","Focus on visual storytelling with some French words","Connect to known story structures"],"pourPEI":["Modify story length expectations","Allow alternative story formats","Use visual supports extensively","Focus on creative expression over structure"]}','{"vocabulary":["histoire","utiliser","collection"],"visualSupports":["Story structure poster (beginning-middle-end), Word collection display, Picture book example","Story template example, Beginning-middle-end visual guide, Sentence starter poster","Story time format poster, Audience response guide, Story sharing celebration visual"],"movementBreaks":["Acting out favorite games","Page-turning gestures with picture book","Moving around to gather word materials","Acting out story ideas","Drawing movements for illustrations","Moving to story circle","Story sharing gestures","Appreciative response movements"]}',NULL,NULL,NULL,NULL,'{"questions":["Les élèves ont-ils atteint les objectifs?","Quelles adaptations étaient nécessaires?","Que ferais-je différemment la prochaine fois?"]}',NULL,'',1,16,'extension',1);
INSERT INTO ETFOLessonPlan VALUES('cmf43u3z300kbvj9t4der868p',23,'Mots dans notre école','cmf43u3yn00jdvj9t4ynrfkm6',1765468800000,45,'Share a few mini stories from yesterday. Show school map and explain that our school is FULL of French words - we''re going on a word treasure hunt around the building.','School Word Safari - Take students on guided walk through school (library, office, cafeteria, gym). Students identify and record French words on signs, posters, labels. Work in pairs with clipboards.','Safari Debrief - Back in classroom, share the most interesting words found. Create a class list of ''School French Words'' on chart paper.','Décrire les mots familiers; Utiliser le vocabulaire thématique en contexte; Développer l''expression écrite par des activités langagières variées','["Mini stories from lesson 16","Simple school map or layout","Treasure hunt props (magnifying glasses)","Clipboards (12-15)","Pencils/pens","Word collection sheets","Magnifying glasses (optional)","Camera for teacher documentation","Chart paper and markers","Word collection sheets from hunt","Safari celebration props"]',NULL,'Mots dans notre école','Share a few mini stories from yesterday. Show school map and explain that our school is FULL of French words - we''re going on a word treasure hunt around the building.','School Word Safari - Take students on guided walk through school (library, office, cafeteria, gym). Students identify and record French words on signs, posters, labels. Work in pairs with clipboards.','Safari Debrief - Back in classroom, share the most interesting words found. Create a class list of ''School French Words'' on chart paper.','Décrire les mots familiers; Utiliser le vocabulaire thématique en contexte; Développer l''expression écrite par des activités langagières variées',NULL,NULL,NULL,'formative','{"observable":["L''élève utilise 3 nouveaux mots français dans ses phrases","L''élève prononce clairement les sons français ciblés","L''élève comprend les instruc