INSERT INTO ETFOLessonPlan VALUES('cmf43u3z300kdvj9t7vc82wtf',23,'Atelier de poésie simple','cmf43u3yn00jdvj9t4ynrfkm6',4102416000000,45,'Review school words found yesterday. Read a simple French poem or chant with rhythm and rhyme. Explain that poems are special ways to play with words and sounds.','Young Poets Workshop - Students create simple 4-line poems using rhyming words from their collection. Template: ''Dans l''école je vois... / Dans l''école j''entends...'' Encourage rhythm and repetition.','Poetry Café - Students sit in circle and share poems like a coffee shop poetry reading. Soft snaps or finger wiggles for applause after each poem.','Appliquer le concept de atelier de; Utiliser les compétences langagières fondamentales; Développer l''expression écrite par des activités langagières variées','["School words chart from lesson 17","Simple French poem book or chant card","Rhythm instruments (optional)","Poetry template papers","Student word collections","Rhyming word cards","Crayons for illustrations","Poem starter phrase cards","Student created poems","Cozy circle setup","Optional: coffee shop props"]',NULL,'Atelier de poésie simple','Review school words found yesterday. Read a simple French poem or chant with rhythm and rhyme. Explain that poems are special ways to play with words and sounds.','Young Poets Workshop - Students create simple 4-line poems using rhyming words from their collection. Template: ''Dans l''école je vois... / Dans l''école j''entends...'' Encourage rhythm and repetition.','Poetry Café - Students sit in circle and share poems like a coffee shop poetry reading. Soft snaps or finger wiggles for applause after each poem.','Appliquer le concept de atelier de; Utiliser les compétences langagières fondamentales; Développer l''expression écrite par des activités langagières variées',NULL,NULL,NULL,'formative','{"observable":["L''élève utilise 3 nouveaux mots français dans ses phrases","L''élève prononce clairement les sons français ciblés","L''élève comprend les instructions avec les nouveaux mots","L''élève fait les gestes associés aux mots appris"],"checkpoints":["Reconnaît les mots à l''oral sans aide visuelle","Peut répéter les mots avec la bonne prononciation","Utilise les mots en contexte approprié","Montre compréhension par actions ou réponses"]}',1,'Plan détaillé avec supports visuels',1756911653536,1757594654134,1,'fr','Français (Immersion)','{"pourDifficultés":["Use simple word repetition patterns","Allow picture poems with few words","Provide sentence frames to complete","Focus on favorite word lists rather than structured poems"],"pourAvancés":["Create longer or more complex poems","Experiment with different poetic forms","Help peers with poem creation","Add detailed illustrations to poems"],"pourLangue":["Allow bilingual poetry creation","Use familiar rhythm patterns from home language","Focus on sound play over complex meaning","Connect to cultural poetry traditions"],"pourPEI":["Modify poetry length and complexity","Allow alternative creative expression","Use visual and tactile supports","Focus on creative enjoyment over structure"]}','{"vocabulary":["poésie","simple","création"],"visualSupports":["Poetry concept poster, Rhythm and rhyme examples, Simple poem format guide","Poetry template example, Rhyming words reference, Simple poem structure guide","Poetry café setup visual, Audience appreciation guide, Poetry sharing format"],"movementBreaks":["Rhythmic movements while reading poem","Sound and rhythm exploration gestures","Moving around to gather word materials","Acting out poem ideas","Rhythmic movements while composing","Moving to poetry circle","Gentle applause movements","Poetry performance gestures"]}',NULL,NULL,NULL,NULL,'{"questions":["Les élèves ont-ils atteint les objectifs?","Quelles adaptations étaient nécessaires?","Que ferais-je différemment la prochaine fois?"]}',NULL,'',1,18,'extension',0);
INSERT INTO ETFOLessonPlan VALUES('cmf43u3z400kfvj9t81odywi6',23,'Concours d''orthographe amical','cmf43u3yn00jdvj9t4ynrfkm6',4102416000000,45,'Share a few poems from yesterday''s poetry café. Explain that today we celebrate how well we can spell our learned words - like a friendly contest where everyone wins.','Friendly Spelling Celebration - Divide class into mixed-ability teams. Use learned words for team spelling challenges: letter building, word completion, and oral spelling. Focus on encouragement and team support.','Spelling Champions Ceremony - Every student receives a ''Spelling Star'' certificate. Celebrate growth and effort rather than perfect spelling.','Créer le concept de concours d''orthographe; Utiliser les compétences langagières fondamentales; Développer l''expression écrite par des activités langagières variées','["Poems from lesson 18","Friendly competition concept visual","Celebration props","Letter tiles or cards (multiple sets)","Word completion worksheets","Team identification materials","Encouragement prompt cards","Timer for activities","Spelling Star certificates (25+)","Ceremony music (optional)","Celebration props"]',NULL,'Concours d''orthographe amical','Share a few poems from yesterday''s poetry café. Explain that today we celebrate how well we can spell our learned words - like a friendly contest where everyone wins.','Friendly Spelling Celebration - Divide class into mixed-ability teams. Use learned words for team spelling challenges: letter building, word completion, and oral spelling. Focus on encouragement and team support.','Spelling Champions Ceremony - Every student receives a ''Spelling Star'' certificate. Celebrate growth and effort rather than perfect spelling.','Créer le concept de concours d''orthographe; Utiliser les compétences langagières fondamentales; Développer l''expression écrite par des activités langagières variées',NULL,NULL,NULL,'formative','{"observable":["L''élève utilise 3 nouveaux mots français dans ses phrases","L''élève prononce clairement les sons français ciblés","L''élève comprend les instructions avec les nouveaux mots","L''élève fait les gestes associés aux mots appris"],"checkpoints":["Reconnaît les mots à l''oral sans aide visuelle","Peut répéter les mots avec la bonne prononciation","Utilise les mots en contexte approprié","Montre compréhension par actions ou réponses"]}',1,'Plan détaillé avec supports visuels',1756911653537,1757594654135,1,'fr','Français (Immersion)','{"pourDifficultés":["Use simple words only","Allow letter card building instead of writing","Provide peer support within teams","Focus on letter recognition rather than complete spelling"],"pourAvancés":["Include challenging vocabulary words","Help facilitate team activities","Support struggling team members","Try spelling words from multiple lessons"],"pourLangue":["Use familiar vocabulary for spelling","Allow sound-based spelling attempts","Connect to home language spelling patterns","Focus on effort over accuracy"],"pourPEI":["Modify spelling expectations","Allow alternative participation methods","Use supportive team environments","Celebrate any spelling attempt"]}','{"vocabulary":["concours","orthographe","amical"],"visualSupports":["Friendly spelling celebration poster, ''Everyone wins'' concept visual, Spelling celebration format","Team spelling challenge stations, Encouragement phrases poster, Spelling celebration rules","Spelling champions ceremony format, Growth and effort celebration poster, Certificate presentation visual"],"movementBreaks":["Poetry sharing gestures","Celebration anticipation movements","Moving between spelling stations","Team huddle movements","Celebratory gestures for all efforts","Standing for certificate ceremony","Applause for all participants","Victory celebration gestures"]}',NULL,NULL,NULL,NULL,'{"questions":["Les élèves ont-ils atteint les objectifs?","Quelles adaptations étaient nécessaires?","Que ferais-je différemment la prochaine fois?"]}',NULL,'',1,19,'core',0);
INSERT INTO ETFOLessonPlan VALUES('cmf43u3z500khvj9t1q7d7i1v',23,'Célébration des explorateurs','cmf43u3yn00jdvj9t4ynrfkm6',1765555200000,45,'Show spelling certificates from yesterday. Set up celebration atmosphere with decorations. Announce that today we celebrate our amazing journey as word explorers!','Explorer Celebration Festival - Set up stations: 1) Memory gallery of all unit work, 2) Favorite moment sharing circle, 3) Future goals setting (''Next I want to learn...''). Students rotate and celebrate their growth.','Explorer Pledge - Class stands together and recites: ''We are word explorers! We discover, we learn, we share, we grow!'' End with group cheer and applause.','Maîtriser le concept de célébration des; Utiliser les compétences langagières fondamentales; Développer l''expression écrite par la célébration collective','["Spelling certificates from lesson 19","Celebration decorations (streamers, banners)","Unit journey display materials","All unit work samples for display","Sharing circle setup","Future goals recording sheets","Celebration station signs","Rotation timer","Explorer pledge poster","Class celebration props","Final unit achievement certificates (optional)"]',NULL,'Célébration des explorateurs','Show spelling certificates from yesterday. Set up celebration atmosphere with decorations. Announce that today we celebrate our amazing journey as word explorers!','Explorer Celebration Festival - Set up stations: 1) Memory gallery of all unit work, 2) Favorite moment sharing circle, 3) Future goals setting (''Next I want to learn...''). Students rotate and celebrate their growth.','Explorer Pledge - Class stands together and recites: ''We are word explorers! We discover, we learn, we share, we grow!'' End with group cheer and applause.','Maîtriser le concept de célébration des; Utiliser les compétences langagières fondamentales; Développer l''expression écrite par la célébration collective',NULL,NULL,NULL,'formative','{"observable":["L''élève utilise 3 nouveaux mots français dans ses phrases","L''élève prononce clairement les sons français ciblés","L''élève comprend les instructions avec les nouveaux mots","L''élève fait les gestes associés aux mots appris"],"checkpoints":["Reconnaît les mots à l''oral sans aide visuelle","Peut répéter les mots avec la bonne prononciation","Utilise les mots en contexte approprié","Montre compréhension par actions ou réponses"]}',1,'Plan détaillé avec supports visuels',1756911653538,1757594654136,1,'fr','Français (Immersion)','{"pourDifficultés":["Focus on personal growth rather than comparisons","Highlight individual achievements","Allow flexible participation in stations","Celebrate effort and progress"],"pourAvancés":["Help facilitate celebration stations","Support peers in reflecting on growth","Share leadership in class activities","Contribute ideas for future learning goals"],"pourLangue":["Celebrate bilingual learning strengths","Allow sharing in comfortable language","Highlight cultural contributions to class learning","Connect to home language learning experiences"],"pourPEI":["Modify celebration participation as needed","Focus on individual meaningful achievements","Allow alternative ways to participate","Celebrate all forms of learning progress"]}','{"vocabulary":["célébration","explorateur","futur"],"visualSupports":["Unit celebration poster, Word explorer journey timeline, Achievement celebration visual","Celebration stations guide, Memory gallery display, Future goals prompts, Learning journey celebration chart","Explorer pledge visual, Class motto poster, Unit completion celebration chart"],"movementBreaks":["Admiring certificates together","Setting up celebration space","Rotating between celebration stations","Sharing and admiring work displays","Celebrating achievements with gestures","Standing together for pledge","Group cheer with full body movement","Celebration applause and cheering"]}',NULL,NULL,NULL,NULL,'{"questions":["Les élèves ont-ils atteint les objectifs?","Quelles adaptations étaient nécessaires?","Que ferais-je différemment la prochaine fois?"]}',NULL,'',1,20,'core',1);
INSERT INTO ETFOLessonPlan VALUES('cmf43u3z800klvj9tw0h2uupg',23,'Qu''est-ce qu''un texte?','cmf43u3z700kjvj9tp4zi2b5e',1771948800000,45,'Look around classroom and point to different texts. Use gestures: point and say ''texte'', ''livre'', ''écrit''. Make discovery exciting!','Text hunt around school - students find and point to different texts with teacher. Practice saying ''C''est un texte!'' Use magnifying glasses for fun detective work.','Share discoveries in circle. Count how many different texts we found. Preview tomorrow''s picture exploration.','Explorer le concept de qu''est-ce qu''un; Utiliser les compétences langagières fondamentales; Développer la conscience phonologique par des activités langagières variées','["Grande variété de textes affichés dans la classe","Cartes visuelles des mots vocabulaire","Loupes ou verres grossissants (25)","Liste de vérification simple","Paniers pour collecter découvertes","Tableau de compte simple","Découvertes collectées"]',NULL,'Qu''est-ce qu''un texte?','Look around classroom and point to different texts. Use gestures: point and say ''texte'', ''livre'', ''écrit''. Make discovery exciting!','Text hunt around school - students find and point to different texts with teacher. Practice saying ''C''est un texte!'' Use magnifying glasses for fun detective work.','Share discoveries in circle. Count how many different texts we found. Preview tomorrow''s picture exploration.','Explorer le concept de qu''est-ce qu''un; Utiliser les compétences langagières fondamentales; Développer la conscience phonologique par des activités langagières variées',NULL,NULL,NULL,'Formative','Observation continue',1,'Plan détaillé avec supports visuels',1756911653540,1757587622527,1,'fr','Français (Immersion)','{"pourDifficultés":["Commencer avec des textes très familiers (noms des élèves, mots de routine)","Utiliser plus de supports visuels et de gestes","Permettre de montrer au lieu de nommer verbalement"],"pourAvancés":["Identifier des caractéristiques spécifiques des textes trouvés","Classer les textes par catégorie","Expliquer la fonction de chaque texte découvert"],"pourLangue":["Permettre l''usage de la L1 pour expliquer les découvertes","Jumeler avec élèves francophones","Utiliser des textes bilingues si disponibles"],"pourPEI":["Utiliser des textes à contraste élevé si nécessaire","Permettre le mouvement pendant l''exploration","Utiliser supports visuels agrandis selon besoins visuels","Permettre réponses par pointage ou sélection d''images"]}','{"vocabulary":["texte","livre","écrit"],"visualSupports":["Gestes pour ''texte'', ''livre'', ''écrit'', affiche avec images des types de textes","Phrase modèle ''C''est un texte!'' affichée, cartes vocabulaire portables","Tableau visuel pour compter les découvertes, aperçu imagé de demain"],"movementBreaks":["Marcher dans la classe pour découvrir","Marche exploratoire dans l''école","S''asseoir en cercle au sol"]}',NULL,NULL,NULL,NULL,'{"questions":["Les élèves ont-ils atteint les objectifs?","Quelles adaptations étaient nécessaires?","Que ferais-je différemment la prochaine fois?"]}',NULL,'',1,1,'core',1);
INSERT INTO ETFOLessonPlan VALUES('cmf43u3z800knvj9twry0vokj',23,'Images parlent aussi','cmf43u3z700kjvj9tp4zi2b5e',1772035200000,45,'Review yesterday''s text hunt. Show book with only pictures. ''Est-ce que c''est un texte? Les images peuvent parler!''','Explore wordless books together. Students ''read'' pictures and tell what they see. Practice getting information from images without words.','Share one thing they learned from pictures today. Introduce tomorrow''s prediction activity.','Identifier le concept de images parlent; Utiliser les compétences langagières fondamentales; Développer la conscience phonologique par des activités langagières variées','["Livres sans mots (25 copies ou grandes images)","Images du récapitulatif d''hier","Collection de livres sans mots (25)","Grandes images séquentielles","Tableaux pour enregistrer observations","Images de récapitulatif","Aperçu visuel de demain"]',NULL,'Images parlent aussi','Review yesterday''s text hunt. Show book with only pictures. ''Est-ce que c''est un texte? Les images peuvent parler!''','Explore wordless books together. Students ''read'' pictures and tell what they see. Practice getting information from images without words.','Share one thing they learned from pictures today. Introduce tomorrow''s prediction activity.','Identifier le concept de images parlent; Utiliser les compétences langagières fondamentales; Développer la conscience phonologique par des activités langagières variées',NULL,NULL,NULL,'Formative','Observation continue',1,'Plan détaillé avec supports visuels',1756911653541,1757587622527,1,'fr','Français (Immersion)','{"pourDifficultés":["Utiliser images très simples avec éléments familiers","Permettre de montrer au lieu de verbaliser","Fournir phrases de départ (''Je vois...'')"],"pourAvancés":["Décrire les émotions des personnages dans les images","Prédire ce qui pourrait arriver ensuite","Comparer différents styles d''illustration"],"pourLangue":["Permettre descriptions dans L1 puis traduire ensemble","Utiliser gestes pour clarifier vocabulaire","Jumeler avec élèves plus forts en français"],"pourPEI":["Adapter images selon capacités visuelles","Permettre manipulation d''objets physiques","Utiliser images plus contrastantes si nécessaire"]}','{"vocabulary":["image","information","comprendre"],"visualSupports":["Cartes vocabulaire pour ''image'', ''information'', ''comprendre'', livre sans mots agrandi","Phrases modèles ''Je vois...'', ''L''image dit...'', bulles de pensée","Tableau ''Ce que j''ai appris des images'', images preview de prédiction"],"movementBreaks":["Gestes pour ''parler'' et ''comprendre''","Mimer les actions vues dans les images","Cercle assis au sol pour partager"]}',NULL,NULL,NULL,NULL,'{"questions":["Les élèves ont-ils atteint les objectifs?","Quelles adaptations étaient nécessaires?","Que ferais-je différemment la prochaine fois?"]}',NULL,'',1,2,'core',1);
INSERT INTO ETFOLessonPlan VALUES('cmf43u3z900kpvj9t0pkbhjay',23,'Prédire avec les images','cmf43u3z700kjvj9tp4zi2b5e',1772121600000,45,'Review how pictures give information. Today we use pictures to guess what might happen. Model with familiar book cover.','Show various book covers. Students make predictions based on pictures. Record predictions on chart. Use ''Je pense que...'' sentence starter.','Choose one book to read tomorrow to check predictions. Students excited to see if they were right!','Reconnaître le concept de prédire avec; Utiliser les compétences langagières fondamentales; Développer la conscience phonologique par des activités langagières variées','["Couvertures de livres familiers (grandes versions)","Cartes vocabulaire nouvelles","Variété de couvertures de livres (25)","Grand tableau de prédictions","Marqueurs","Livre choisi pour demain","Prédictions enregistrées"]',NULL,'Prédire avec les images','Review how pictures give information. Today we use pictures to guess what might happen. Model with familiar book cover.','Show various book covers. Students make predictions based on pictures. Record predictions on chart. Use ''Je pense que...'' sentence starter.','Choose one book to read tomorrow to check predictions. Students excited to see if they were right!','Reconnaître le concept de prédire avec; Utiliser les compétences langagières fondamentales; Développer la conscience phonologique par des activités langagières variées',NULL,NULL,NULL,'Formative','Observation continue',1,'Plan détaillé avec supports visuels',1756911653542,1757587622529,1,'fr','Français (Immersion)','{"pourDifficultés":["Fournir options de prédiction simples (heureux/triste)","Utiliser images très évidentes","Permettre de dessiner leurs prédictions"],"pourAvancés":["Expliquer les indices qui justifient leurs prédictions","Prédire des détails spécifiques","Comparer leurs prédictions avec celles des autres"],"pourLangue":["Accepter prédictions en L1 puis aider à traduire","Utiliser gestes et dessins","Jumeler avec élèves bilingues"],"pourPEI":["Adapter selon capacités de communication","Utiliser supports visuels additionnels","Permettre réponses non-verbales"]}','{"vocabulary":["prédire","penser","deviner"],"visualSupports":["Gestes pour ''prédire'', ''penser'', ''deviner'', bulle de pensée géante","Phrase de départ ''Je pense que...'', icônes pour indices visuels, tableau de prédictions","Aperçu visuel du livre choisi, rappel des prédictions faites"],"movementBreaks":["Gestes pour montrer la ''réflexion''","Se lever pour regarder de plus près les couvertures","Applaudissements pour toutes les bonnes prédictions"]}',NULL,NULL,NULL,NULL,'{"questions":["Les élèves ont-ils atteint les objectifs?","Quelles adaptations étaient nécessaires?","Que ferais-je différemment la prochaine fois?"]}',NULL,'',1,3,'core',1);
INSERT INTO ETFOLessonPlan VALUES('cmf43u3za00krvj9twlbk564v',23,'Écouter et découvrir','cmf43u3z700kjvj9tp4zi2b5e',1772208000000,45,'Review yesterday''s predictions. Put on ''listening ears'' to check if guesses were right.','Read chosen story with expression and pictures. Stop periodically to check predictions. Celebrate both correct and incorrect predictions as good thinking.','Compare predictions to actual story. Discuss what surprised them. Preview tomorrow''s retelling activity.','Exprimer le concept de écouter et; Utiliser les compétences langagières fondamentales; Développer la conscience phonologique par des activités langagières variées','["Tableau des prédictions d''hier","Accessoires ''oreilles d''écoute'' (25)","Livre choisi hier","Tableau de comparaison prédictions/réalité","Autocollants ou tampons de célébration","Récapitulatif visuel des comparaisons","Aperçu de l''activité de demain"]',NULL,'Écouter et découvrir','Review yesterday''s predictions. Put on ''listening ears'' to check if guesses were right.','Read chosen story with expression and pictures. Stop periodically to check predictions. Celebrate both correct and incorrect predictions as good thinking.','Compare predictions to actual story. Discuss what surprised them. Preview tomorrow''s retelling activity.','Exprimer le concept de écouter et; Utiliser les compétences langagières fondamentales; Développer la conscience phonologique par des activités langagières variées',NULL,NULL,NULL,'Formative','Observation continue',1,'Plan détaillé avec supports visuels',1756911653543,1757587622529,1,'fr','Français (Immersion)','{"pourDifficultés":["Pauses plus fréquentes pour vérifier compréhension","Supports visuels additionnels","Répéter les parties importantes"],"pourAvancés":["Prédire ce qui va arriver ensuite pendant l''histoire","Analyser pourquoi certaines prédictions étaient bonnes","Faire des connexions avec d''autres histoires"],"pourLangue":["Paraphraser en mots plus simples","Utiliser plus de gestes et expressions","Vérifier compréhension fréquemment"],"pourPEI":["Adapter la durée d''écoute selon capacités","Utiliser supports tactiles si bénéfique","Permettre mouvement pendant l''écoute"]}','{"vocabulary":["écouter","découvrir","vérifier"],"visualSupports":["Gestes pour ''écouter'', ''découvrir'', ''vérifier'', oreilles géantes pour ''écouter''","Images du livre agrandies, symboles pour ''correct'' et ''différent mais intelligent''","Tableau comparatif final, images de reconter des histoires"],"movementBreaks":["Geste de mettre les ''oreilles d''écoute''","Applaudissements pour bonnes prédictions","Mimer des actions de l''histoire","Cercle de partage au sol"]}',NULL,NULL,NULL,NULL,'{"questions":["Les élèves ont-ils atteint les objectifs?","Quelles adaptations étaient nécessaires?","Que ferais-je différemment la prochaine fois?"]}',NULL,'',1,4,'core',1);
INSERT INTO ETFOLessonPlan VALUES('cmf43u3zb00ktvj9tpia6lt79',23,'Reconter ensemble','cmf43u3z700kjvj9tp4zi2b5e',1772467200000,45,'Review yesterday''s story briefly. ''Maintenant, nous recontons l''histoire ensemble!''','Students retell story parts in sequence. Use props, gestures, and simple French words. Support with ''D''abord... Ensuite... Finalement...''','Whole group retelling with everyone contributing. Celebrate successful storytelling.','Décrire le concept de reconter ensemble; Raconter les compétences langagières fondamentales; Développer le vocabulaire français par la narration','["Livre d''hier","Accessoires ou marionnettes simples","Accessoires simples pour l''histoire","Cartes séquences","Mots de transition affichés","Certificats ou badges de ''conteur''","L''histoire complète remontée"]',NULL,'Reconter ensemble','Review yesterday''s story briefly. ''Maintenant, nous recontons l''histoire ensemble!''','Students retell story parts in sequence. Use props, gestures, and simple French words. Support with ''D''abord... Ensuite... Finalement...''','Whole group retelling with everyone contributing. Celebrate successful storytelling.','Décrire le concept de reconter ensemble; Raconter les compétences langagières fondamentales; Développer le vocabulaire français par la narration',NULL,NULL,NULL,'Formative','Observation continue',1,'Plan détaillé avec supports visuels',1756911653544,1757587622532,1,'fr','Français (Immersion)','{"pourDifficultés":["Permettre de montrer et dire un seul mot par image","Utiliser supports visuels très clairs","Jumeler avec partenaires plus forts"],"pourAvancés":["Ajouter détails et émotions au récit","Utiliser vocabulaire plus riche","Aider les autres à reconter"],"pourLangue":["Accepter mélange de langues au début","Fournir phrases de départ simples","Encourager gestes pour communiquer"],"pourPEI":["Adapter longueur de participation selon capacités","Utiliser supports tactiles ou visuels spéciaux","Permettre communication non-verbale"]}','{"vocabulary":["reconter","partie","expliquer"],"visualSupports":["Gestes pour ''reconter'', ''partie'', ''expliquer'', séquence d''images de l''histoire","Cartes ''D''abord'', ''Ensuite'', ''Finalement'', images séquentielles de l''histoire","Histoire entière en séquence, célébrations visuelles"],"movementBreaks":["Gestes expressifs pour ''reconter ensemble''","Se lever pour ''jouer'' les parties de l''histoire","Applaudissements et célébrations debout"]}',NULL,NULL,NULL,NULL,'{"questions":["Les élèves ont-ils atteint les objectifs?","Quelles adaptations étaient nécessaires?","Que ferais-je différemment la prochaine fois?"]}',NULL,'',1,5,'core',1);
INSERT INTO ETFOLessonPlan VALUES('cmf43u3zc00kvvj9ttzuysj7u',23,'Textes différents partout','cmf43u3z700kjvj9tp4zi2b5e',1772553600000,45,'Review that we''ve been reading stories. ''Il y a d''autres sortes de textes aussi!'' Show variety of examples.','Explore different text types - shopping lists, signs, letters, recipes. Discuss purpose of each type. Sort into categories.','Share different text types they found. Discuss which ones they see at home.','Lire le concept de textes différents; Utiliser les compétences langagières fondamentales; Développer le vocabulaire français par des activités langagières variées','["Collection de différents types de textes réels","Boîte mystère","Listes d''épicerie réelles","Panneaux/affiches","Lettres/cartes","Recettes simples","Boîtes de tri","Textes triés en catégories"]',NULL,'Textes différents partout','Review that we''ve been reading stories. ''Il y a d''autres sortes de textes aussi!'' Show variety of examples.','Explore different text types - shopping lists, signs, letters, recipes. Discuss purpose of each type. Sort into categories.','Share different text types they found. Discuss which ones they see at home.','Lire le concept de textes différents; Utiliser les compétences langagières fondamentales; Développer le vocabulaire français par des activités langagières variées',NULL,NULL,NULL,'Formative','Observation continue',1,'Plan détaillé avec supports visuels',1756911653545,1757587622675,1,'fr','Français (Immersion)','{"pourDifficultés":["Utiliser seulement 2-3 types de textes très différents","Fournir supports visuels clairs pour chaque type","Permettre travail en paires"],"pourAvancés":["Identifier la fonction spécifique de chaque type de texte","Créer leurs propres exemples","Expliquer pourquoi différents textes existent"],"pourLangue":["Utiliser textes bilingues si disponibles","Connecter avec textes de leur culture d''origine","Permettre explications en L1"],"pourPEI":["Adapter nombre de catégories selon capacités","Utiliser manipulation physique pour trier","Permettre participation non-verbale"]}','{"vocabulary":["différent","sorte","type"],"visualSupports":["Cartes catégories de textes avec images, gestes pour ''différent'', ''sorte'', ''type''","Tableau de tri avec icônes, exemples de chaque type de texte agrandis","Affichage des catégories créées, connexions maison-école"],"movementBreaks":["Gestes pour montrer ''différents'' types","Se déplacer pour examiner différents textes","Cercle de partage assis"]}',NULL,NULL,NULL,NULL,'{"questions":["Les élèves ont-ils atteint les objectifs?","Quelles adaptations étaient nécessaires?","Que ferais-je différemment la prochaine fois?"]}',NULL,'',1,6,'core',1);
INSERT INTO ETFOLessonPlan VALUES('cmf43u3zd00kxvj9tyfbhy237',23,'Lire les indices','cmf43u3z700kjvj9tp4zi2b5e',1772640000000,45,'Become detectives! When we don''t know a word, we look for clues. Model with obvious picture-word connection.','Practice finding clues in pictures and context when encountering unknown words. Use detective approach - what clues help us guess meaning?','Share best clues they found today. Remind them they can be word detectives with any text.','Écrire le concept de lire les; Utiliser les compétences langagières fondamentales; Développer le vocabulaire français par des activités langagières variées','["Chapeaux ou badges de détectives (25)","Loupes","Exemple évident mot-image","Textes avec mots inconnus mais images claires","Tableau ''Indices trouvés''","Autocollants de découvertes","Collection des meilleurs indices"]',NULL,'Lire les indices','Become detectives! When we don''t know a word, we look for clues. Model with obvious picture-word connection.','Practice finding clues in pictures and context when encountering unknown words. Use detective approach - what clues help us guess meaning?','Share best clues they found today. Remind them they can be word detectives with any text.','Écrire le concept de lire les; Utiliser les compétences langagières fondamentales; Développer le vocabulaire français par des activités langagières variées',NULL,NULL,NULL,'Formative','Observation continue',1,'Plan détaillé avec supports visuels',1756911653545,1757587622675,1,'fr','Français (Immersion)','{"pourDifficultés":["Utiliser correspondances très évidentes image-mot","Donner indices supplémentaires si nécessaire","Travailler en paires avec élèves plus forts"],"pourAvancés":["Chercher plusieurs indices pour un même mot","Expliquer leur processus de déduction","Aider autres élèves à trouver indices"],"pourLangue":["Permettre utilisation de L1 pour expliquer indices","Connecter avec stratégies déjà utilisées en L1","Utiliser gestes pour clarifier"],"pourPEI":["Adapter complexité des indices selon capacités","Utiliser supports tactiles si bénéfique","Permettre temps supplémentaire pour observation"]}','{"vocabulary":["indice","contexte","deviner"],"visualSupports":["Icônes de détective, gestes pour ''indice'', ''contexte'', ''deviner'', exemple visuel clair","Questions guides visuelles (''Que vois-tu?'', ''Qu''est-ce qui t''aide?'')","Badge ''Détective de mots'' pour chaque élève"],"movementBreaks":["Mimer être des détectives","Chercher physiquement des indices dans la classe","Célébration des découvertes"]}',NULL,NULL,NULL,NULL,'{"questions":["Les élèves ont-ils atteint les objectifs?","Quelles adaptations étaient nécessaires?","Que ferais-je différemment la prochaine fois?"]}',NULL,'',1,7,'core',1);
INSERT INTO ETFOLessonPlan VALUES('cmf43u3ze00kzvj9t67j28x8v',23,'Questions importantes','cmf43u3z700kjvj9tp4zi2b5e',1772726400000,45,'Review being text detectives. ''Les détectives posent des questions!'' Introduce question words with gestures.','Practice asking ''Qui?'' ''Quoi?'' ''Où?'' questions about familiar texts. Use question words cards as supports.','Share best questions they asked. Explain how questions help us understand stories better.','Raconter le concept de questions importantes; Utiliser les compétences langagières fondamentales; Développer le vocabulaire français par des activités langagières variées','["Cartes de mots questions (25 jeux)","Point d''interrogation géant","Textes familiers agrandis","Cartes mots questions","Microphone jouet pour poser questions","Collection des meilleures questions"]',NULL,'Questions importantes','Review being text detectives. ''Les détectives posent des questions!'' Introduce question words with gestures.','Practice asking ''Qui?'' ''Quoi?'' ''Où?'' questions about familiar texts. Use question words cards as supports.','Share best questions they asked. Explain how questions help us understand stories better.','Raconter le concept de questions importantes; Utiliser les compétences langagières fondamentales; Développer le vocabulaire français par des activités langagières variées',NULL,NULL,NULL,'Formative','Observation continue',1,'Plan détaillé avec supports visuels',1756911653546,1757587622675,1,'fr','Français (Immersion)','{"pourDifficultés":["Fournir débuts de questions (''Qui est...?'')","Utiliser images pour aider à formuler","Accepter questions très simples"],"pourAvancés":["Poser questions plus complexes (''Pourquoi?'', ''Comment?'')","Aider autres à améliorer leurs questions","Expliquer pourquoi leurs questions sont bonnes"],"pourLangue":["Permettre questions en L1 puis traduire","Utiliser structure de question simple","Modéliser beaucoup avant de demander"],"pourPEI":["Adapter complexité selon capacités","Permettre questions non-verbales (pointer)","Utiliser supports visuels pour structure"]}','{"vocabulary":["question","qui","quoi"],"visualSupports":["Gestes pour ''question'', ''qui'', ''quoi'', affiches des mots questions avec images","Exemples de questions affichées, images pour aider à formuler questions","Tableau ''Nos meilleures questions'', connexions questions-compréhension"],"movementBreaks":["Gestes expressifs pour chaque mot question","Se lever pour être ''journalistes'' et interviewer","Célébration des bons questionneurs"]}',NULL,NULL,NULL,NULL,'{"questions":["Les élèves ont-ils atteint les objectifs?","Quelles adaptations étaient nécessaires?","Que ferais-je différemment la prochaine fois?"]}',NULL,'',1,8,'core',1);
INSERT INTO ETFOLessonPlan VALUES('cmf43u3zf00l1vj9tbup7wgy7',23,'Mes livres préférés','cmf43u3z700kjvj9tp4zi2b5e',1772812800000,45,'Everyone has favorite books! Share teacher''s favorite and explain why. Model simple reasons.','Students share favorite books with partners and simple reasons why they like them. Use ''J''aime... parce que...'' structure with supports.','Few students share favorites with whole class. Create class list of favorite books.','Communiquer le concept de mes livres; Utiliser les compétences langagières fondamentales; Développer la communication orale par des activités langagières variées','["Livre préféré de l''enseignant","Coeurs ou étoiles pour montrer ''préféré''","Sélection de livres de classe","Cartes de raisons simples (images)","Feuilles de partage","Grand tableau pour liste de classe"]',NULL,'Mes livres préférés','Everyone has favorite books! Share teacher''s favorite and explain why. Model simple reasons.','Students share favorite books with partners and simple reasons why they like them. Use ''J''aime... parce que...'' structure with supports.','Few students share favorites with whole class. Create class list of favorite books.','Communiquer le concept de mes livres; Utiliser les compétences langagières fondamentales; Développer la communication orale par des activités langagières variées',NULL,NULL,NULL,'Formative','Observation continue',1,'Plan détaillé avec supports visuels',1756911653547,1757587622675,1,'fr','Français (Immersion)','{"pourDifficultés":["Permettre de montrer livre sans explication verbale","Offrir choix de raisons simples avec images","Accepter raisons très basiques"],"pourAvancés":["Donner raisons multiples pour leurs choix","Recommander livres aux autres","Comparer différents livres qu''ils aiment"],"pourLangue":["Accepter explications en L1 puis traduire ensemble","Utiliser beaucoup de supports visuels","Jumeler avec élèves bilingues"],"pourPEI":["Adapter selon capacités de communication","Permettre choix non-verbaux","Utiliser livres avec supports tactiles si bénéfique"]}','{"vocabulary":["préféré","aimer","choisir"],"visualSupports":["Gestes pour ''préféré'', ''aimer'', ''choisir'', phrases simples modelès ''J''aime parce que...''","Structure ''J''aime... parce que...'' affichée, cartes raisons avec images","Liste visuelle des favoris de la classe avec couvertures si possible"],"movementBreaks":["Gestes du coeur pour montrer ''aimer''","Se déplacer pour trouver partenaires","Applaudissements pour chaque partage"]}',NULL,NULL,NULL,NULL,'{"questions":["Les élèves ont-ils atteint les objectifs?","Quelles adaptations étaient nécessaires?","Que ferais-je différemment la prochaine fois?"]}',NULL,'',1,9,'core',1);
INSERT INTO ETFOLessonPlan VALUES('cmf43u3zg00l3vj9tsji0oc9g',23,'Comparer les histoires','cmf43u3z700kjvj9tp4zi2b5e',1773068400000,45,'Review favorite books. Today we compare two stories to see what''s the same and different.','Read/review two simple stories. Use chart to record what''s the same and what''s different. Support with visual comparisons.','Discuss what they learned from comparing stories. Some stories share ideas but tell them differently.','Exprimer le concept de comparer les; Raconter les compétences langagières fondamentales; Développer la communication orale par la narration','["Deux livres simples pour comparaison","Balance visuelle pour comparer","Deux histoires simples","Tableau de comparaison géant","Images des éléments à comparer","Tableau de comparaison terminé"]',NULL,'Comparer les histoires','Review favorite books. Today we compare two stories to see what''s the same and different.','Read/review two simple stories. Use chart to record what''s the same and what''s different. Support with visual comparisons.','Discuss what they learned from comparing stories. Some stories share ideas but tell them differently.','Exprimer le concept de comparer les; Raconter les compétences langagières fondamentales; Développer la communication orale par la narration',NULL,NULL,NULL,'Formative','Observation continue',1,'Plan détaillé avec supports visuels',1756911653548,1757587622675,1,'fr','Français (Immersion)','{"pourDifficultés":["Se concentrer sur une seule similitude/différence évidente","Utiliser objets physiques pour modéliser comparaison","Travailler en petits groupes avec soutien"],"pourAvancés":["Trouver similitudes et différences multiples","Expliquer pourquoi les différences existent","Faire des connexions avec d''autres histoires connues"],"pourLangue":["Utiliser beaucoup d''images pour soutenir comparaisons","Permettre explications en L1","Modéliser beaucoup avant de demander participation"],"pourPEI":["Adapter nombre d''éléments à comparer","Utiliser supports tactiles si approprié","Permettre participation non-verbale"]}','{"vocabulary":["comparer","même","différent"],"visualSupports":["Gestes pour ''comparer'', ''même'', ''différent'', diagramme de Venn simple","Diagramme de Venn simple, images des personnages et éléments des histoires","Récapitulatif visuel des découvertes de comparaison"],"movementBreaks":["Gestes pour montrer ''pareil'' et ''différent''","Bouger vers différentes sections du tableau pour comparer","Cercle de discussion finale"]}',NULL,NULL,NULL,NULL,'{"questions":["Les élèves ont-ils atteint les objectifs?","Quelles adaptations étaient nécessaires?","Que ferais-je différemment la prochaine fois?"]}',NULL,'',1,10,'core',1);
INSERT INTO ETFOLessonPlan VALUES('cmf43u3zg00l5vj9tconx9tmk',23,'Textes informatifs','cmf43u3z700kjvj9tp4zi2b5e',1773154800000,45,'Review story books. ''Certains livres nous enseignent des choses vraies!'' Show non-fiction examples.','Explore simple non-fiction texts about animals, families, or familiar topics. Discuss how these teach real facts.','Share one new fact they learned today. Discuss difference between learning facts and enjoying stories.','Décrire le concept de textes informatifs; Utiliser les compétences langagières fondamentales; Développer la communication orale par des activités langagières variées','["Livres d''histoires vs livres informatifs","Objets réels mentionnés dans livres informatifs","Livres informatifs simples sur animaux/familles","Tableau ''Faits appris''","Objets réels pour connections","Tableau des faits appris rempli"]',NULL,'Textes informatifs','Review story books. ''Certains livres nous enseignent des choses vraies!'' Show non-fiction examples.','Explore simple non-fiction texts about animals, families, or familiar topics. Discuss how these teach real facts.','Share one new fact they learned today. Discuss difference between learning facts and enjoying stories.','Décrire le concept de textes informatifs; Utiliser les compétences langagières fondamentales; Développer la communication orale par des activités langagières variées',NULL,NULL,NULL,'Formative','Observation continue',1,'Plan détaillé avec supports visuels',1756911653549,1757587622675,1,'fr','Français (Immersion)','{"pourDifficultés":["Utiliser livres avec beaucoup d''images et peu de texte","Se concentrer sur un seul fait simple","Permettre de montrer au lieu de verbaliser"],"pourAvancés":["Poser questions plus approfondies sur les faits","Faire connexions entre différents faits","Partager connaissances préalables sur sujets"],"pourLangue":["Utiliser livres bilingues si disponibles","Connecter avec connaissances de leur culture","Utiliser beaucoup de supports visuels"],"pourPEI":["Adapter selon intérêts et capacités","Utiliser livres tactiles si approprié","Permettre exploration à leur rythme"]}','{"vocabulary":["informatif","apprendre","vrai"],"visualSupports":["Gestes pour ''informatif'', ''apprendre'', ''vrai'', comparaison visuelle fiction vs non-fiction","Images des sujets explorés, tableau pour enregistrer nouveaux faits","Comparaison visuelle entre ''faits'' et ''histoires imaginaires''"],"movementBreaks":["Gestes pour montrer ''apprendre'' des choses nouvelles","Mimer les animaux ou sujets appris","Célébration des nouvelles connaissances"]}',NULL,NULL,NULL,NULL,'{"questions":["Les élèves ont-ils atteint les objectifs?","Quelles adaptations étaient nécessaires?","Que ferais-je différemment la prochaine fois?"]}',NULL,'',1,11,'core',1);
INSERT INTO ETFOLessonPlan VALUES('cmf43u3zh00l7vj9t8ghksdgi',23,'Lire ensemble fort','cmf43u3z700kjvj9tp4zi2b5e',1773241200000,45,'Review different types of texts. Today we read together with strong voices! Model expressive reading.','Shared reading of familiar text with expression. Students join in on repeated phrases, practice different voices for characters.','Discuss how reading with expression makes stories more fun. Practice reading one sentence with different emotions.','Lire le concept de lire ensemble; Utiliser les compétences langagières fondamentales; Développer la communication orale par des activités langagières variées','["Livre grand format pour lecture partagée","Microphone jouet ou amplificateur voix","Texte familier en grand format","Cartes d''émotions","Accessoires pour personnages","Phrase simple écrite pour pratiquer","Cartes émotions"]',NULL,'Lire ensemble fort','Review different types of texts. Today we read together with strong voices! Model expressive reading.','Shared reading of familiar text with expression. Students join in on repeated phrases, practice different voices for characters.','Discuss how reading with expression makes stories more fun. Practice reading one sentence with different emotions.','Lire le concept de lire ensemble; Utiliser les compétences langagières fondamentales; Développer la communication orale par des activités langagières variées',NULL,NULL,NULL,'Formative','Observation continue',1,'Plan détaillé avec supports visuels',1756911653550,1757587622676,1,'fr','Français (Immersion)','{"pourDifficultés":["Permettre participation même si pas parfaite","Utiliser textes très familiers ou chansons","Encourager gestes au lieu de mots si nécessaire"],"pourAvancés":["Prendre rôles de leader dans lecture","Expérimenter avec différents styles de voix","Aider autres à améliorer expression"],"pourLangue":["Permettre imitation plutôt que prononciation parfaite","Utiliser beaucoup de modélage","Célébrer toute participation"],"pourPEI":["Adapter selon capacités vocales","Permettre participation non-verbale avec gestes","Utiliser supports visuels additionnels"]}','{"vocabulary":["ensemble","voix","expression"],"visualSupports":["Gestes pour ''ensemble'', ''voix'', ''expression'', symboles pour différentes émotions","Texte projeté ou très grand, cartes émotions pour guider expression","Démonstration visuelle de différentes expressions faciales"],"movementBreaks":["Exercices d''échauffement vocal","Gestes corporels pour accompagner lecture","Mimer différentes émotions en lisant"]}',NULL,NULL,NULL,NULL,'{"questions":["Les élèves ont-ils atteint les objectifs?","Quelles adaptations étaient nécessaires?","Que ferais-je différemment la prochaine fois?"]}',NULL,'',1,12,'core',1);
INSERT INTO ETFOLessonPlan VALUES('cmf43u3zj00l9vj9tmv1qnvbz',23,'Création de questions','cmf43u3z700kjvj9tp4zi2b5e',1773327600000,45,'Review asking questions about texts. Today students become the question creators! Model making questions.','Students create their own questions about familiar text using question word prompts. Support with sentence frames and encouragement.','Students ask their questions to partners. Celebrate being good questioners who help others think.','Écrire le concept de création de; Créer les compétences langagières fondamentales; Développer la compréhension par la création personnelle','["Couronne ou chapeau ''Créateur de questions''","Cartes mots questions","Texte familier","Cartes de débuts de questions","Feuilles pour écrire/dessiner questions","Questions créées par les élèves"]',NULL,'Création de questions','Review asking questions about texts. Today students become the question creators! Model making questions.','Students create their own questions about familiar text using question word prompts. Support with sentence frames and encouragement.','Students ask their questions to partners. Celebrate being good questioners who help others think.','Écrire le concept de création de; Créer les compétences langagières fondamentales; Développer la compréhension par la création personnelle',NULL,NULL,NULL,'Formative','Observation continue',1,'Plan détaillé avec supports visuels',1756911653551,1757587622676,1,'fr','Français (Immersion)','{"pourDifficultés":["Fournir débuts de questions à compléter","Permettre questions très simples","Travailler en paires pour support"],"pourAvancés":["Créer questions plus complexes (''Pourquoi...?'')","Créer plusieurs questions différentes","Aider autres à améliorer leurs questions"],"pourLangue":["Accepter questions en L1 puis traduire","Utiliser beaucoup d''images pour inspiration","Modéliser beaucoup avant participation"],"pourPEI":["Adapter selon capacités de communication","Permettre questions non-verbales (pointer)","Utiliser supports visuels pour structure"]}','{"vocabulary":["créer","questionner","curiosité"],"visualSupports":["Gestes pour ''créer'', ''questionner'', ''curiosité'', exemples de bonnes questions affichées","Cadres de phrases (''Qui est...?'', ''Où va...?''), banque de mots questions","Certificats ''Excellent questionneur'', mur des bonnes questions"],"movementBreaks":["Gestes créatifs pour ''faire'' des questions","Se lever pour partager questions avec différents partenaires","Célébration des créateurs de questions"]}',NULL,NULL,NULL,NULL,'{"questions":["Les élèves ont-ils atteint les objectifs?","Quelles adaptations étaient nécessaires?","Que ferais-je différemment la prochaine fois?"]}',NULL,'',1,13,'core',1);
INSERT INTO ETFOLessonPlan VALUES('cmf43u3zk00lbvj9taxi9cm9p',23,'Portfolio de lecture','cmf43u3z700kjvj9tp4zi2b5e',1773414000000,45,'Look back at all the texts and skills from this unit. ''Regardez tout ce que nous avons appris sur les textes!''','Students create reading portfolio with favorite texts, pictures of learning activities, and simple reflections on their growth.','Students share one thing they learned about texts. Celebrate growth as text explorers and readers.','Raconter le concept de portfolio de; Utiliser les compétences langagières fondamentales; Développer la compréhension par des activités langagières variées','["Collection des travaux de l''unité","Photos des activités passées","Dossiers/pochettes pour portfolios (25)","Photos d''activités","Exemples de travaux","Autocollants décoratifs","Portfolios terminés"]',NULL,'Portfolio de lecture','Look back at all the texts and skills from this unit. ''Regardez tout ce que nous avons appris sur les textes!''','Students create reading portfolio with favorite texts, pictures of learning activities, and simple reflections on their growth.','Students share one thing they learned about texts. Celebrate growth as text explorers and readers.','Raconter le concept de portfolio de; Utiliser les compétences langagières fondamentales; Développer la compréhension par des activités langagières variées',NULL,NULL,NULL,'Formative','Observation continue',1,'Plan détaillé avec supports visuels',1756911653552,1757587622676,1,'fr','Français (Immersion)','{"pourDifficultés":["Portfolio plus simple avec moins d''éléments","Utiliser dessins au lieu de mots","Support individuel pour organisation"],"pourAvancés":["Portfolio plus détaillé avec réflexions écrites","Inclure objectifs pour apprentissages futurs","Aider autres à organiser portfolios"],"pourLangue":["Permettre réflexions en L1","Utiliser beaucoup d''images et moins de texte","Support pour vocabulaire de réflexion"],"pourPEI":["Adapter format selon capacités","Portfolio peut être plus visuel/tactile","Inclure accommodations utilisées"]}','{"vocabulary":["portfolio","voyage","progrès"],"visualSupports":["Gestes pour ''portfolio'', ''voyage'', ''progrès'', chronologie visuelle de l''unité","Modèle de portfolio, prompts de réflexion avec images","Certificat d''explorateur de textes, photos de célébration"],"movementBreaks":["Gestes pour montrer croissance et voyage d''apprentissage","Se déplacer pour collectionner matériaux de portfolio","Célébration debout des accomplissements"]}',NULL,NULL,NULL,NULL,'{"questions":["Les élèves ont-ils atteint les objectifs?","Quelles adaptations étaient nécessaires?","Que ferais-je différemment la prochaine fois?"]}',NULL,'',1,14,'core',1);
INSERT INTO ETFOLessonPlan VALUES('cmf43u3zl00ldvj9tgrct21zx',23,'Explorateurs de genres','cmf43u3z700kjvj9tp4zi2b5e',1773673200000,45,'Review all different text types learned. Today explore special kinds of stories - poetry, fairy tales, etc.','Playful exploration of different genres through listening, acting, and simple identification games. Focus on enjoyment over analysis.','Share which genre was most interesting today. Discuss how many different ways there are to tell stories.','Communiquer le concept de explorateurs de; Utiliser les compétences langagières fondamentales; Développer la compréhension par des activités langagières variées','["Collection de livres de différents genres (5-6 livres)","Affiches visuelles des genres (poésie, conte, histoire vraie)","Cartes vocabulaire illustrées pour chaque genre","Livre de poésie illustré pour enfants","Livre de contes traditionnels","Histoire vraie simple avec photos","CD ou enregistrement audio de poèmes","Costumes simples ou accessoires pour jouer les genres","Exemples des genres explorés","Tableaux simples pour noter préférences","Autocollants ou tampons pour marquer favoris"]',NULL,'Explorateurs de genres','Review all different text types learned. Today explore special kinds of stories - poetry, fairy tales, etc.','Playful exploration of different genres through listening, acting, and simple identification games. Focus on enjoyment over analysis.','Share which genre was most interesting today. Discuss how many different ways there are to tell stories.','Communiquer le concept de explorateurs de; Utiliser les compétences langagières fondamentales; Développer la compréhension par des activités langagières variées',NULL,NULL,NULL,'Formative','Observation continue',1,'Plan détaillé avec supports visuels',1756911653553,1757587622676,1,'fr','Français (Immersion)','{"pourDifficultés":["Permettre les réponses gestuelles avant la production orale","Utiliser des couleurs différentes pour chaque syllabe lors de la lecture","Diviser les tâches longues en étapes plus petites et gérables"],"pourAvancés":["Proposer des textes plus complexes avec vocabulaire étendu","Proposer des défis de vocabulaire avec mots plus sophistiqués","Demander d''enseigner une nouvelle règle de français à un camarade"],"pourLangue":["Créer des liens avec des mots similaires dans la langue première","Offrir des gestes et actions pour accompagner les mots nouveaux","Répéter les consignes importantes avec des gestes clairs"],"pourPEI":["Utiliser des minuteurs visuels pour structurer le temps","Adapter les outils d''écriture (crayons ergonomiques, guides-lignes)","Ajuster l''éclairage et réduire les distractions visuelles"]}','{"vocabulary":["genre","poésie","conte"],"visualSupports":["Affiches colorées montrant caractéristiques de chaque genre","Images des personnages de contes, exemples de rimes visuelles","Tableau de préférences avec symboles pour chaque genre"],"movementBreaks":["Se déplacer pour explorer différents coins de lecture","Jouer des personnages, réciter poèmes avec gestes","Cercle de partage avec gestes pour favoris"]}',NULL,NULL,NULL,NULL,'{"questions":["Les élèves ont-ils atteint les objectifs?","Quelles adaptations étaient nécessaires?","Que ferais-je différemment la prochaine fois?"]}',NULL,'',1,15,'extension',1);
INSERT INTO ETFOLessonPlan VALUES('cmf43u3zm00lfvj9t8cn65rh0',23,'Détectives de mots','cmf43u3z700kjvj9tp4zi2b5e',1773759600000,45,'Return to detective theme! Today hunt for words we know in new places. Model finding familiar word in new text.','Word hunting game in new texts - students search for and collect familiar words they can recognize and understand.','Share word hunting successes. Discuss how knowing some words helps us read new things.','Exprimer les mots familiers; Utiliser le vocabulaire thématique en contexte; Développer la compréhension par des activités langagières variées','["Chapeaux de détectives (25)","Loupes","Exemple de mot familier dans nouveau texte","Nouveaux textes avec mots familiers inclus","Paniers de collection","Autocollants pour marquer trouvailles","Collection des mots trouvés"]',NULL,'Détectives de mots','Return to detective theme! Today hunt for words we know in new places. Model finding familiar word in new text.','Word hunting game in new texts - students search for and collect familiar words they can recognize and understand.','Share word hunting successes. Discuss how knowing some words helps us read new things.','Exprimer les mots familiers; Utiliser le vocabulaire thématique en contexte; Développer la compréhension par des activités langagières variées',NULL,NULL,NULL,'Formative','Observation continue',1,'Plan détaillé avec supports visuels',1756911653554,1757587622687,1,'fr','Français (Immersion)','{"pourDifficultés":["Diviser les tâches longues en étapes plus petites et gérables","Permettre les réponses gestuelles avant la production orale","Utiliser des couleurs différentes pour chaque syllabe lors de la lecture"],"pourAvancés":["Proposer des textes plus complexes avec vocabulaire étendu","Offrir des projets de recherche sur des auteurs franco-canadiens","Proposer des défis de vocabulaire avec mots plus sophistiqués"],"pourLangue":["Encourager le jumelage avec un pair plus fort en français","Créer des liens avec des mots similaires dans la langue première","Répéter les consignes importantes avec des gestes clairs"],"pourPEI":["Offrir des pauses sensorielles fréquentes selon les besoins","Permettre différents moyens d''expression (oral, dessin, technologie)","Adapter les outils d''écriture (crayons ergonomiques, guides-lignes)"]}','{"vocabulary":["détective","chercher","trouver"],"visualSupports":["Rappels visuels des mots familiers, gestes de détectives","Banque de mots familiers affichée, cartes pour collection","Tableau des succès de chasse aux mots"],"movementBreaks":["Gestes de détectives","Mouvement libre pour chasser les mots","Célébration des découvertes"]}',NULL,NULL,NULL,NULL,'{"questions":["Les élèves ont-ils atteint les objectifs?","Quelles adaptations étaient nécessaires?","Que ferais-je différemment la prochaine fois?"]}',NULL,'',1,16,'extension',1);
INSERT INTO ETFOLessonPlan VALUES('cmf43u3zm00lhvj9tep77aypf',23,'Théâtre des histoires','cmf43u3z700kjvj9tp4zi2b5e',1773846000000,45,'Review favorite stories from unit. Today we become actors and show stories with our bodies and voices!','Students choose familiar stories to act out in small groups. Focus on showing understanding through movement and simple dialogue.','Mini performances for class. Celebrate how acting helps us understand and remember stories better.','Décrire le concept de théâtre des; Raconter les compétences langagières fondamentales; Développer l''expression écrite par la narration','["Histoires préférées de l''unité","Accessoires simples (chapeaux, foulards)","Sélection d''histoires familiers","Accessoires de théâtre simples","Espace pour représentations","Scène simple pour performances"]',NULL,'Théâtre des histoires','Review favorite stories from unit. Today we become actors and show stories with our bodies and voices!','Students choose familiar stories to act out in small groups. Focus on showing understanding through movement and simple dialogue.','Mini performances for class. Celebrate how acting helps us understand and remember stories better.','Décrire le concept de théâtre des; Raconter les compétences langagières fondamentales; Développer l''expression écrite par la narration',NULL,NULL,NULL,'Formative','Observation continue',1,'Plan détaillé avec supports visuels',1756911653555,1757587622676,1,'fr','Français (Immersion)','{"pourDifficultés":["Utiliser des couleurs différentes pour chaque syllabe lors de la lecture","Encourager l''utilisation de manipulatifs (lettres magnétiques, etc.)","Offrir du temps supplémentaire pour compléter les activités"],"pourAvancés":["Encourager la création d''histoires originales avec début, milieu, fin","Permettre l''exploration de différents genres littéraires (poésie, théâtre)","Demander d''enseigner une nouvelle règle de français à un camarade"],"pourLangue":["Offrir des gestes et actions pour accompagner les mots nouveaux","Encourager le jumelage avec un pair plus fort en français","Créer des liens avec des mots similaires dans la langue première"],"pourPEI":["Ajuster l''éclairage et réduire les distractions visuelles","Permettre différents moyens d''expression (oral, dessin, technologie)","Fournir des instructions simples, une étape à la fois"]}','{"vocabulary":["théâtre","jouer","montrer"],"visualSupports":["Gestes pour ''théâtre'', ''jouer'', ''montrer'', exemples d''expressions dramatiques","Images des histoires pour inspiration, conseils simples pour jeu dramatique","Applaudimètre visuel, certificats d''acteur"],"movementBreaks":["Exercices d''échauffement dramatique","Jeu dramatique continu","Applaudissements et célébrations debout"]}',NULL,NULL,NULL,NULL,'{"questions":["Les élèves ont-ils atteint les objectifs?","Quelles adaptations étaient nécessaires?","Que ferais-je différemment la prochaine fois?"]}',NULL,'',1,17,'extension',1);
INSERT INTO ETFOLessonPlan VALUES('cmf43u3zn00ljvj9t7fsrm9kl',23,'Bibliothécaires experts','cmf43u3z700kjvj9tp4zi2b5e',4102416000000,45,'Discuss how librarians help people find good books. Today students become book experts who help friends!','Students interview classmates about interests, then recommend books from classroom library. Practice giving simple reasons for recommendations.','Share successful recommendations made today. Discuss how helping others find good books makes reading more fun.','Appliquer le concept de bibliothécaires experts; Utiliser les compétences langagières fondamentales; Développer l''expression écrite par des activités langagières variées','["Badges ''Expert bibliothécaire'' (25)","Sélection de livres de classe","Feuilles d''interview simples","Bibliothèque de classe organisée","Cartes de recommandation","Recommandations faites pendant la leçon"]',NULL,'Bibliothécaires experts','Discuss how librarians help people find good books. Today students become book experts who help friends!','Students interview classmates about interests, then recommend books from classroom library. Practice giving simple reasons for recommendations.','Share successful recommendations made today. Discuss how helping others find good books makes reading more fun.','Appliquer le concept de bibliothécaires experts; Utiliser les compétences langagières fondamentales; Développer l''expression écrite par des activités langagières variées',NULL,NULL,NULL,'Formative','Observation continue',1,'Plan détaillé avec supports visuels',1756911653556,1757587622676,1,'fr','Français (Immersion)','{"pourDifficultés":["Permettre les réponses gestuelles avant la production orale","Utiliser des cartes visuelles avec images pour chaque mot nouveau","Offrir du temps supplémentaire pour compléter les activités"],"pourAvancés":["Proposer des défis de vocabulaire avec mots plus sophistiqués","Demander d''enseigner une nouvelle règle de français à un camarade","Inviter à créer un livre illustré pour les plus jeunes"],"pourLangue":["Offrir des gestes et actions pour accompagner les mots nouveaux","Permettre les explications dans la langue première si nécessaire","Répéter les consignes importantes avec des gestes clairs"],"pourPEI":["Utiliser des supports visuels clairs et contrastés","Fournir des instructions simples, une étape à la fois","Ajuster l''éclairage et réduire les distractions visuelles"]}','{"vocabulary":["recommander","expert","suggestion"],"visualSupports":["Gestes pour ''recommander'', ''expert'', ''suggestion'', images de bibliothécaires au travail","Questions d''interview affichées, structure ''Je recommande... parce que...''","Tableau des bonnes recommandations, connexions lecture-amitié"],"movementBreaks":["Se déplacer comme vrais bibliothécaires","Circulation pour interviews et recommandations","Cercle de partage final"]}',NULL,NULL,NULL,NULL,'{"questions":["Les élèves ont-ils atteint les objectifs?","Quelles adaptations étaient nécessaires?","Que ferais-je différemment la prochaine fois?"]}',NULL,'',1,18,'extension',0);
INSERT INTO ETFOLessonPlan VALUES('cmf43u3zo00llvj9tek9foty8',23,'Textes de chez nous','cmf43u3z700kjvj9tp4zi2b5e',4102416000000,45,'Discuss how every family and culture has special stories and texts. Invite sharing about texts from home.','Students share texts, stories, or traditions from their families/cultures. Celebrate diversity and different ways of telling stories.','Reflect on how many different types of stories and texts exist in our classroom community.','Créer le concept de textes de; Utiliser les compétences langagières fondamentales; Développer l''expression écrite par des activités langagières variées','["Carte du monde ou globe","Photos de familles diverses","Objets ou images apportés de la maison","Espace de partage confortable","Collection des partages de la journée"]',NULL,'Textes de chez nous','Discuss how every family and culture has special stories and texts. Invite sharing about texts from home.','Students share texts, stories, or traditions from their families/cultures. Celebrate diversity and different ways of telling stories.','Reflect on how many different types of stories and texts exist in our classroom community.','Créer le concept de textes de; Utiliser les compétences langagières fondamentales; Développer l''expression écrite par des activités langagières variées',NULL,NULL,NULL,'Formative','Observation continue',1,'Plan détaillé avec supports visuels',1756911653557,1757587622695,1,'fr','Français (Immersion)','{"pourDifficultés":["Permettre les réponses gestuelles avant la production orale","Utiliser des cartes visuelles avec images pour chaque mot nouveau","Proposer des supports audio pour accompagner le texte écrit"],"pourAvancés":["Offrir des projets de recherche sur des auteurs franco-canadiens","Inviter à créer un livre illustré pour les plus jeunes","Encourager la création d''histoires originales avec début, milieu, fin"],"pourLangue":["Offrir des gestes et actions pour accompagner les mots nouveaux","Encourager le jumelage avec un pair plus fort en français","Répéter les consignes importantes avec des gestes clairs"],"pourPEI":["Offrir des pauses sensorielles fréquentes selon les besoins","Utiliser des supports visuels clairs et contrastés","Ajuster l''éclairage et réduire les distractions visuelles"]}','{"vocabulary":["culture","famille","tradition"],"visualSupports":["Gestes pour ''culture'', ''famille'', ''tradition'', images de différentes cultures et textes","Affichage célébrant la diversité, support pour structures de partage","Mur de la diversité des textes et cultures de la classe"],"movementBreaks":["Gestes pour représenter différentes cultures","Mouvement pour montrer différentes traditions","Cercle de réflexion assis ensemble"]}',NULL,NULL,NULL,NULL,'{"questions":["Les élèves ont-ils atteint les objectifs?","Quelles adaptations étaient nécessaires?","Que ferais-je différemment la prochaine fois?"]}',NULL,'',1,19,'core',0);
INSERT INTO ETFOLessonPlan VALUES('cmf43u3zp00lnvj9t9t93wsic',23,'Célébration de lecteurs','cmf43u3z700kjvj9tp4zi2b5e',1773932400000,45,'Look back at journey from Lesson 1 to now. ''Vous êtes maintenant des explorateurs de textes experts!''','Celebration of reading growth with sharing of portfolios, presentation of certificates, and reflection on favorite discoveries.','Final circle: each student completes ''Je suis un explorateur de textes parce que...'' Group celebration photo.','Maîtriser le concept de célébration de; Utiliser les compétences langagières fondamentales; Développer l''expression écrite par la célébration collective','["Chronologie visuelle de l''unité","Travaux des élèves du début à maintenant","Portfolios de lecture créés","Certificats d''explorateur de textes (25)","Décorations de célébration","Phrase à compléter affichée","Appareil photo pour photo de groupe"]',NULL,'Célébration de lecteurs','Look back at journey from Lesson 1 to now. ''Vous êtes maintenant des explorateurs de textes experts!''','Celebration of reading growth with sharing of portfolios, presentation of certificates, and reflection on favorite discoveries.','Final circle: each student completes ''Je suis un explorateur de textes parce que...'' Group celebration photo.','Maîtriser le concept de célébration de; Utiliser les compétences langagières fondamentales; Développer l''expression écrite par la célébration collective',NULL,NULL,NULL,'Formative','Observation continue',1,'Plan détaillé avec supports visuels',1756911653557,1757587622676,1,'fr','Français (Immersion)','{"pourDifficultés":["Utiliser des cartes visuelles avec images pour chaque mot nouveau","Proposer des supports audio pour accompagner le texte écrit","Permettre les réponses gestuelles avant la production orale"],"pourAvancés":["Encourager la création d''histoires originales avec début, milieu, fin","Proposer des textes plus complexes avec vocabulaire étendu","Offrir des projets de recherche sur des auteurs franco-canadiens"],"pourLangue":["Répéter les consignes importantes avec des gestes clairs","Utiliser un dictionnaire visuel français-anglais","Offrir des gestes et actions pour accompagner les mots nouveaux"],"pourPEI":["Utiliser des minuteurs visuels pour structurer le temps","Adapter les outils d''écriture (crayons ergonomiques, guides-lignes)","Offrir des pauses sensorielles fréquentes selon les besoins"]}','{"vocabulary":["célébrer","lecteur","explorer"],"visualSupports":["Gestes pour ''célébrer'', ''lecteur'', ''explorer'', parcours visuel d''apprentissage","Affichage des accomplissements de la classe, photos du parcours d''apprentissage","Structure de phrase compléter, accessoires pour photo célébratoire"],"movementBreaks":["Gestes célébratoires","Marche fière pour recevoir certificats","Positionnement pour photo de groupe finale"]}',NULL,NULL,NULL,NULL,'{"questions":["Les élèves ont-ils atteint les objectifs?","Quelles adaptations étaient nécessaires?","Que ferais-je différemment la prochaine fois?"]}',NULL,'',1,20,'core',1);
INSERT INTO ETFOLessonPlan VALUES('cmf43u3zs00lrvj9tiscbf1o7',23,'Ma famille','cmf43u3zq00lpvj9tnsaml469',1761231600000,45,'Chanson d''accueil chaleureuse: ''Bonjour ma famille!'' avec gestes. Montrer des photos de familles diverses en disant ''Voici des familles!'' Chaque famille est spéciale et différente.','Cercle de partage familial avec support visuel: Les élèves explorent les photos de famille et apprennent ''ma famille''. Introduction douce aux mots ''maman'' et ''papa'' avec gestes rassurants.','Moment de célébration tendre: Chaque élève tient sa photo (ou une photo d''exemple) et chuchote ''ma famille'' avec fierté. Chanson douce: ''Ma famille est spéciale, ma famille est belle!''','Explorer la famille et ses membres; Utiliser les rôles familiaux avec respect; Développer la conscience phonologique par des activités langagières variées','["Matériel de classe"]',NULL,'Ma famille','Chanson d''accueil chaleureuse: ''Bonjour ma famille!'' avec gestes. Montrer des photos de familles diverses en disant ''Voici des familles!'' Chaque famille est spéciale et différente.','Cercle de partage familial avec support visuel: Les élèves explorent les photos de famille et apprennent ''ma famille''. Introduction douce aux mots ''maman'' et ''papa'' avec gestes rassurants.','Moment de célébration tendre: Chaque élève tient sa photo (ou une photo d''exemple) et chuchote ''ma famille'' avec fierté. Chanson douce: ''Ma famille est spéciale, ma famille est belle!''','Explorer la famille et ses membres; Utiliser les rôles familiaux avec respect; Développer la conscience phonologique par des activités langagières variées',NULL,NULL,NULL,'formative','{"observable":["Élève montre de l''intérêt pour les photos de familles","Élève reconnaît le mot ''famille'' quand prononcé","Élève participe positivement au cercle de partage","Élève utilise des gestes appropriés pour ''maman'' et ''papa''"],"checkpoints":["Pendant l''ouverture: Observer l''engagement avec les photos de familles","Pendant le cercle: Noter la participation et le confort avec le vocabulaire","Pendant la fermeture: Vérifier la reconnaissance du concept ''ma famille''"]}',1,'Plan détaillé avec supports visuels',1756911653560,1757594654140,1,'fr','Français (Immersion)','{"pourDifficultés":["Utiliser seulement des gestes sans pression de parler","Permettre de pointer vers les photos sans nommer","Offrir des images simples et claires de familles","Donner plus de temps pour observer avant de partager"],"pourAvancés":["Encourager l''ajout de détails: ''Dans ma famille il y a...''","Inviter à nommer d''autres membres de la famille (tante, oncle)","Demander de compter les personnes dans leur famille","Permettre d''aider leurs camarades timides à partager"],"pourLangue":["Permettre l''usage de la langue première pour identifier les membres","Utiliser des photos très claires avec gestes exagérés","Accepter le mélange des langues pendant l''apprentissage","Fournir des cartes visuelles avec mots et images"],"pourPEI":["Adapter selon les besoins de communication (gestes, images, technologie)","Modifier les attentes de participation selon les capacités","Utiliser supports sensoriels si appropriés (textures, sons)","Permettre des positions alternatives à l''assise au cercle"]}','{"vocabulary":["famille","maman","papa","unique"],"visualSupports":["Geste du cœur pour ''famille'', bras ouverts pour ''bienvenue'', sourire expressif","Geste de bercement tendre pour ''maman'', geste de force douce pour ''papa'', pointer vers soi pour ''ma''","Geste du cœur sur la poitrine, sourire bienveillant, hochement de tête approbateur"],"movementBreaks":["Répéter des comptines avec gestes : ''Tête, épaules, genoux et pieds'' (2 minutes)","Faire l''alphabet avec notre corps : A comme arbre (étirer les bras), B comme ballon (forme ronde) (3 minutes)","Marcher sur place en récitant l''alphabet lentement (2 minutes)","Faire une pause lecture : s''étirer comme un chat qui se réveille (2 minutes)","Ranger nos idées : faire semblant de mettre nos pensées dans une boîte (2 minutes)","Dire au revoir avec tout notre corps : mains, têtes, pieds (2 minutes)"]}',NULL,NULL,NULL,NULL,'{"questions":["Les élèves ont-ils atteint les objectifs?","Quelles adaptations étaient nécessaires?","Que ferais-je différemment la prochaine fois?"]}',NULL,'',1,1,'core',1);
INSERT INTO ETFOLessonPlan VALUES('cmf43u3zt00ltvj9tj8js05ic',23,'Qui est dans ma famille?','cmf43u3zq00lpvj9tnsaml469',1761318000000,45,'Révision chaleureuse: ''Hier nous avons parlé de nos familles!'' Revoir les gestes pour ''famille'', ''maman'', ''papa''. Nouveaux amis: présenter ''frère'' et ''sœur'' avec gestes fraternels.','Jeu d''identification familiale avec mouvement: Stations rotatives - Station 1: trier les cartes famille, Station 2: mimer les membres de famille, Station 3: matcher photos aux mots. Beaucoup de mouvement et rires!','Galerie familiale: Les élèves déambulent et pointent vers différentes photos en nommant les membres en français. Chanson finale: ''Dans ma famille il y a...'' avec gestes.','Identifier la famille et ses membres; Utiliser les rôles familiaux avec respect; Développer la conscience phonologique par des activités langagières variées','["Matériel de classe"]',NULL,'Qui est dans ma famille?','Révision chaleureuse: ''Hier nous avons parlé de nos familles!'' Revoir les gestes pour ''famille'', ''maman'', ''papa''. Nouveaux amis: présenter ''frère'' et ''sœur'' avec gestes fraternels.','Jeu d''identification familiale avec mouvement: Stations rotatives - Station 1: trier les cartes famille, Station 2: mimer les membres de famille, Station 3: matcher photos aux mots. Beaucoup de mouvement et rires!','Galerie familiale: Les élèves déambulent et pointent vers différentes photos en nommant les membres en français. Chanson finale: ''Dans ma famille il y a...'' avec gestes.','Identifier la famille et ses membres; Utiliser les rôles familiaux avec respect; Développer la conscience phonologique par des activités langagières variées',NULL,NULL,NULL,'formative','{"observable":["Élève distingue entre ''frère'' et ''sœur'' visuellement","Élève utilise les gestes appropriés pour les nouveaux mots","Élève participe activement aux stations rotatives","Élève montre progression depuis la Leçon 1"],"checkpoints":["Pendant les stations: Observer la manipulation et reconnaissance","Pendant la galerie: Noter l''usage des nouveaux mots","Comparer avec Leçon 1: Vérifier rétention du vocabulaire"]}',1,'Plan détaillé avec supports visuels',1756911653561,1757594654141,1,'fr','Français (Immersion)','{"pourDifficultés":["Se concentrer seulement sur ''frère'' ou ''sœur'' selon leur famille","Utiliser plus de gestes et moins de mots","Permettre de pointer sans nommer au début","Offrir support d''un partenaire pendant les stations"],"pourAvancés":["Ajouter ''pépère'' s''ils maîtrisent le vocabulaire de base","Encourager des phrases: ''J''ai un frère'' ou ''Je n''ai pas de sœur''","Inviter à compter les frères et sœurs dans les photos","Aider à enseigner aux camarades qui ont des difficultés"],"pourLangue":["Connecter avec les mots frère/sœur dans leur langue première","Utiliser gestes très clairs et répétition","Permettre mélange linguistique temporairement","Fournir support visuel constant avec cartes"],"pourPEI":["Adapter les stations selon capacités motrices (assis vs debout)","Modifier attentes selon besoins communicatifs","Utiliser supports alternatifs (images, technologie)","Permettre plus de temps aux stations"]}','{"vocabulary":["frère","sœur","mémère"],"visualSupports":["Geste fraternel (bras autour des épaules) pour ''frère/sœur'', geste de grandeur pour ''grand''","Gestes distincts pour chaque membre: bercement (maman), force (papa), hauteur (frère/sœur), geste d''honneur (mémère)","Pointer clairement, gestes de rappel pour chaque membre, sourires d''encouragement"],"movementBreaks":["Faire l''alphabet avec notre corps : A comme arbre (étirer les bras), B comme ballon (forme ronde) (3 minutes)","Former des lettres dans l''air avec nos doigts : A, B, C (3 minutes)","Étirer nos doigts et mains d''écrivains : ouvrir, fermer, tourner (2 minutes)","Faire des gestes de marionnettes pour raconter notre histoire (3 minutes)","Faire une révérence à nos nouvelles connaissances (1 minute)","Célébrer nos apprentissages : applaudir, lever les bras, sourire (2 minutes)"]}',NULL,NULL,NULL,NULL,'{"questions":["Les élèves ont-ils atteint les objectifs?","Quelles adaptations étaient nécessaires?","Que ferais-je différemment la prochaine fois?"]}',NULL,'',1,2,'core',1);
INSERT INTO ETFOLessonPlan VALUES('cmf43u3zt00lvvj9tnxhzgom7',23,'Ma famille à moi','cmf43u3zq00lpvj9tnsaml469',1761577200000,45,'Réunion familiale: Revoir tous nos amis famille avec chanson cumulative. ''Maman, papa, frère, sœur, mémère!'' Nouveau grand-ami: ''pépère'' avec geste de respect.','Création d''affiches familiales personnalisées: Chaque élève crée son affiche ''MA famille'' avec photos ou dessins. Pratique douce de ''mon papa'', ''ma maman'' avec soutien visuel.','Vernissage familial: Chaque élève présente fièrement son affiche ''MA famille'' et nomme un membre. Applaudissements chaleureux pour chaque famille unique et spéciale.','Reconnaître la famille et ses membres; Utiliser les rôles familiaux avec respect; Développer la conscience phonologique par des activités langagières variées','["Matériel de classe"]',NULL,'Ma famille à moi','Réunion familiale: Revoir tous nos amis famille avec chanson cumulative. ''Maman, papa, frère, sœur, mémère!'' Nouveau grand-ami: ''pépère'' avec geste de respect.','Création d''affiches familiales personnalisées: Chaque élève crée son affiche ''MA famille'' avec photos ou dessins. Pratique douce de ''mon papa'', ''ma maman'' avec soutien visuel.','Vernissage familial: Chaque élève présente fièrement son affiche ''MA famille'' et nomme un membre. Applaudissements chaleureux pour chaque famille unique et spéciale.','Reconnaître la famille et ses membres; Utiliser les rôles familiaux avec respect; Développer la conscience phonologique par des activités langagières variées',NULL,NULL,NULL,'formative','{"observable":["Élève crée une affiche familiale avec engagement","Élève utilise ''ma famille'' appropriément","Élève montre fierté de sa création familiale","Élève identifie au moins un membre de famille"],"checkpoints":["Pendant création: Observer engagement et compréhension","Pendant présentation: Noter usage du vocabulaire possessif","Évaluer progrès cumulatif depuis Leçons 1-2"]}',1,'Plan détaillé avec supports visuels',1756911653562,1757594654142,1,'fr','Français (Immersion)','{"pourDifficultés":["Accepter pointage simple sans mots","Utiliser seulement ''ma famille'' sans distinction mon/ma","Permettre aide pour création d''affiche","Offrir choix limités d''images pré-sélectionnées"],"pourAvancés":["Encourager phrases complètes: ''Voici mon papa''","Inviter à compter les membres sur leur affiche","Ajouter détails: âges, activités préférées","Aider camarades à présenter leurs affiches"],"pourLangue":["Permettre description dans langue première puis en français","Utiliser gestures expressifs avec chaque mot","Accepter mélange linguistique temporaire","Fournir phrases modèles visuelles"],"pourPEI":["Adapter outils de création (gros crayons, aide physique)","Modifier format de présentation selon capacités","Utiliser support technologique si approprié","Respecter besoins sensoriels (éclairage, bruit)"]}','{"vocabulary":["pépère","mon","ma"],"visualSupports":["Geste de respect pour pépère (légère inclination), pointer vers soi pour ''mon/ma''","Cartes de référence: ''MON papa'' (image homme), ''MA maman'' (image femme), geste de propriété affectueuse","Gestes d''applaudissement, expressions de fierté, pointer vers affiche avec amour"],"movementBreaks":["Marcher en syllabant notre nom : Ma-rie, Paul, etc. en tapant dans nos mains (2 minutes)","Répéter des comptines avec gestes : ''Tête, épaules, genoux et pieds'' (2 minutes)","Étirer nos doigts et mains d''écrivains : ouvrir, fermer, tourner (2 minutes)","Marcher sur place en récitant l''alphabet lentement (2 minutes)","Ranger nos idées : faire semblant de mettre nos pensées dans une boîte (2 minutes)","Célébrer nos apprentissages : applaudir, lever les bras, sourire (2 minutes)"]}',NULL,NULL,NULL,NULL,'{"questions":["Les élèves ont-ils atteint les objectifs?","Quelles adaptations étaient nécessaires?","Que ferais-je différemment la prochaine fois?"]}',NULL,'',1,3,'core',1);
INSERT INTO ETFOLessonPlan VALUES('cmf43u3zv00lxvj9t6wiccuyn',23,'Les familles sont différentes','cmf43u3zq00lpvj9tnsaml469',1761663600000,45,'Célébration de la diversité: ''Regardez toutes nos belles familles!'' Revoir les affiches de la Leçon 3 en soulignant combien chaque famille est ''différente'' et ''spéciale''.','Exploration bienveillante de la diversité: Découverte guidée d''images montrant la beauté des différences familiales. Activité ''Trouver la beauté'' - identifier ce qui rend chaque famille spéciale.','Affirmation collective puissante: Chaque élève regarde son affiche familiale et dit avec fierté ''Ma famille est spéciale!'' Chanson finale: ''Différentes, spéciales, toutes belles!''','Exprimer la famille et ses membres; Utiliser les rôles familiaux avec respect; Développer la conscience phonologique par des activités langagières variées','["Matériel de classe"]',NULL,'Les familles sont différentes','Célébration de la diversité: ''Regardez toutes nos belles familles!'' Revoir les affiches de la Leçon 3 en soulignant combien chaque famille est ''différente'' et ''spéciale''.','Exploration bienveillante de la diversité: Découverte guidée d''images montrant la beauté des différences familiales. Activité ''Trouver la beauté'' - identifier ce qui rend chaque famille spéciale.','Affirmation collective puissante: Chaque élève regarde son affiche familiale et dit avec fierté ''Ma famille est spéciale!'' Chanson finale: ''Différentes, spéciales, toutes belles!''','Exprimer la famille et ses membres; Utiliser les rôles familiaux avec respect; Développer la conscience phonologique par des activités langagières variées',NULL,NULL,NULL,'formative','{"observable":["Élève montre acceptation positive des différences familiales","Élève utilise ''spécial'' pour décrire les familles","Élève participe à l''affirmation de sa propre famille","Élève démontre respect pour la diversité des autres familles"],"checkpoints":["Pendant exploration: Observer attitudes envers images diverses","Pendant discussions: Écouter commentaires positifs vs négatifs","Pendant affirmation finale: Vérifier fierté authentique de sa famille"]}',1,'Plan détaillé avec supports visuels',1756911653563,1757594654143,1,'fr','Français (Immersion)','{"pourDifficultés":["Utiliser seulement geste du cœur sans mots si nécessaire","Se concentrer sur ''spécial'' seulement comme concept","Permettre observation sans participation active","Offrir support individuel pour identifier aspects positifs"],"pourAvancés":["Encourager identification de plusieurs différences belles","Inviter à expliquer pourquoi leur famille est spéciale","Demander d''aider camarades à voir beauté de leur famille","Créer des connexions entre différentes familles"],"pourLangue":["Utiliser images et gestes principalement","Permettre expression dans langue première puis traduire","Connecter avec ma famille de leur culture d''origine","Utiliser support visuel constant pour nouveaux concepts"],"pourPEI":["Adapter selon besoins émotionnels spécifiques","Utiliser supports alternatifs si difficultés de traitement visuel","Permettre expression alternative (dessin, mouvement)","Respecter besoin de temps supplémentaire pour traitement"]}','{"vocabulary":["différent","spécial","beau"],"visualSupports":["Geste d''ouverture pour ''différent'' (mains écartées), cœur pour ''spécial'', sourire radieux pour ''beau''","Collection diversifiée montrant: parents seuls, grands-parents, familles adoptives, cultures variées, tailles différentes - toutes positives","Gestes d''affirmation positive, sourires bienveillants, pointer vers affiche avec amour et fierté"],"movementBreaks":["Répéter des comptines avec gestes : ''Tête, épaules, genoux et pieds'' (2 minutes)","Marcher en syllabant notre nom : Ma-rie, Paul, etc. en tapant dans nos mains (2 minutes)","Étirer nos doigts et mains d''écrivains : ouvrir, fermer, tourner (2 minutes)","Danser avec les sons : ''a'' avec les bras, ''o'' en rond, ''i'' pointu (3 minutes)","Étirer notre dos d''écrivains : rotation douce des épaules (2 minutes)","Ranger nos idées : faire semblant de mettre nos pensées dans une boîte (2 minutes)"]}',NULL,NULL,NULL,NULL,'{"questions":["Les élèves ont-ils atteint les objectifs?","Quelles adaptations étaient nécessaires?","Que ferais-je différemment la prochaine fois?"]}',NULL,'',1,4,'core',1);
INSERT INTO ETFOLessonPlan VALUES('cmf43u3zw00lzvj9two8g0acz',23,'Qu''est-ce qu''on fait ensemble?','cmf43u3zq00lpvj9tnsaml469',1761750000000,45,'Mime matinal amusant: Mimer différentes activités familiales et laisser les élèves deviner. ''Qu''est-ce que je fais avec ma famille?'' Introduction joyeuse de ''manger'', ''jouer'', ''regarder''.','Centres d''activités familiales: 3 stations rotatives avec TPR. Station 1: ''Manger'' - jeu de pique-nique, Station 2: ''Jouer'' - jeux familiaux miniatures, Station 3: ''Regarder'' - albums photos de familles en action.','Spectacle d''activités familiales: Chaque élève choisit une activité, fait le geste et dit le mot français. Création collective d''une chanson: ''Manger, jouer, regarder - ensemble c''est formidable!''','Décrire le concept de qu''est-ce qu''on; Utiliser les compétences langagières fondamentales; Développer le vocabulaire français par des activités langagières variées','["Matériel de classe"]',NULL,'Qu''est-ce qu''on fait ensemble?','Mime matinal amusant: Mimer différentes activités familiales et laisser les élèves deviner. ''Qu''est-ce que je fais avec ma famille?'' Introduction joyeuse de ''manger'', ''jouer'', ''regarder''.','Centres d''activités familiales: 3 stations rotatives avec TPR. Station 1: ''Manger'' - jeu de pique-nique, Station 2: ''Jouer'' - jeux familiaux miniatures, Station 3: ''Regarder'' - albums photos de familles en action.','Spectacle d''activités familiales: Chaque élève choisit une activité, fait le geste et dit le mot français. Création collective d''une chanson: ''Manger, jouer, regarder - ensemble c''est formidable!''','Décrire le concept de qu''est-ce qu''on; Utiliser les compétences langagières fondamentales; Développer le vocabulaire français par des activités langagières variées',NULL,NULL,NULL,'formative','{"observable":["Élève associe gestes aux activités familiales","Élève reconnaît et utilise ''manger'', ''jouer'', ''regarder''","Élève participe activement aux stations rotatives","Élève fait connexions entre activités et sa propre famille"],"checkpoints":["Pendant stations: Observer engagement et compréhension des activités","Pendant spectacle final: Noter usage du vocabulaire et des gestes","Évaluer connexion émotionnelle positive avec activités familiales"]}',1,'Plan détaillé avec supports visuels',1756911653564,1757594654144,1,'fr','Français (Immersion)','{"pourDifficultés":["Se concentrer sur une seule activité à la fois","Permettre imitation simple sans production de mots","Utiliser objets concrets pour soutenir compréhension","Offrir choix limité entre deux activités seulement"],"pourAvancés":["Encourager phrases complètes: ''Ma famille aime manger ensemble''","Inviter à décrire quand ils font ces activités","Ajouter détails: où, avec qui, comment","Créer nouvelles combinaisons d''activités"],"pourLangue":["Connecter activités avec mots de langue première","Utiliser objets et actions réels pour clarifier","Permettre description dans L1 puis tentative en français","Utiliser support visuel constant avec gestes"],"pourPEI":["Adapter participation aux capacités motrices (gestes modifiés)","Utiliser supports technologiques si approprié","Permettre observation active sans performance","Respecter besoins sensoriels (niveau bruit, éclairage)"]}','{"vocabulary":["manger","jouer","regarder"],"visualSupports":["Gestes très expressifs: manger (porter à la bouche), jouer (mouvement de balle), regarder (main sur front)","Photos d''action familiales authentiques: repas partagés, jeux de cartes, lecture ensemble, films en famille","Gestes de référence bien établis, expressions de joie et satisfaction pour chaque activité"],"movementBreaks":["Marcher en syllabant notre nom : Ma-rie, Paul, etc. en tapant dans nos mains (2 minutes)","Former des lettres dans l''air avec nos doigts : A, B, C (3 minutes)","Marcher sur place en récitant l''alphabet lentement (2 minutes)","Étirer nos doigts et mains d''écrivains : ouvrir, fermer, tourner (2 minutes)","Dire au revoir avec tout notre corps : mains, têtes, pieds (2 minutes)","Étirer notre dos d''écrivains : rotation douce des épaules (2 minutes)"]}',NULL,NULL,NULL,NULL,'{"questions":["Les élèves ont-ils atteint les objectifs?","Quelles adaptations étaient nécessaires?","Que ferais-je différemment la prochaine fois?"]}',NULL,'',1,5,'core',1);
INSERT INTO ETFOLessonPlan VALUES('cmf43u3zx00m1vj9tgff4ls5k',23,'Notre maison','cmf43u3zq00lpvj9tnsaml469',1761836400000,45,'Visite virtuelle joyeuse: ''Où habite votre famille?'' Présentation de différents types de maisons avec respect - appartements, maisons, condos. Introduction de ''maison'' comme lieu d''amour familial.','Exploration des pièces familiales: Jeu ''Où fait-on quoi?'' - associer activités de la Leçon 5 (manger, jouer) avec pièces (cuisine, salon). Création de plan de maison simple avec étiquettes.','Tour des maisons de famille: Chaque élève montre fièrement son plan et dit ''Voici MA maison!'' ou ''Ma famille habite ici!'' Chanson finale sur la sécurité du foyer familial.','Lire le concept de notre maison; Utiliser les compétences langagières fondamentales; Développer le vocabulaire français par des activités langagières variées','["Matériel de classe"]',NULL,'Notre maison','Visite virtuelle joyeuse: ''Où habite votre famille?'' Présentation de différents types de maisons avec respect - appartements, maisons, condos. Introduction de ''maison'' comme lieu d''amour familial.','Exploration des pièces familiales: Jeu ''Où fait-on quoi?'' - associer activités de la Leçon 5 (manger, jouer) avec pièces (cuisine, salon). Création de plan de maison simple avec étiquettes.','Tour des maisons de famille: Chaque élève montre fièrement son plan et dit ''Voici MA maison!'' ou ''Ma famille habite ici!'' Chanson finale sur la sécurité du foyer familial.','Lire le concept de notre maison; Utiliser les compétences langagières fondamentales; Développer le vocabulaire français par des activités langagières variées',NULL,NULL,NULL,'formative','{"observable":["Élève reconnaît ''maison'' comme lieu de famille","Élève associe ''cuisine'' et ''salon'' à des activités","Élève crée representation spatiale de base","Élève montre fierté de son espace familial"],"checkpoints":["Pendant création: Observer compréhension espace-fonction","Pendant présentation: Noter usage du vocabulaire spatial","Évaluer connexion émotionnelle positive avec concept ''foyer''"]}',1,'Plan détaillé avec supports visuels',1756911653565,1757594654145,1,'fr','Français (Immersion)','{"pourDifficultés":["Se concentrer seulement sur ''maison'' sans les pièces spécifiques","Utiliser plan très simple avec seulement 2 pièces","Permettre collage d''étiquettes au lieu d''écriture","Offrir aide individuelle pour création du plan"],"pourAvancés":["Ajouter plus de pièces: bureau, garage, sous-sol","Encourager description: ''Dans ma cuisine, nous mangeons''","Inviter à comparer avec maisons des camarades","Créer plan plus détaillé avec fenêtres, portes"],"pourLangue":["Connecter pièces avec mots de langue première","Utiliser images très claires pour chaque pièce","Permettre explication dans L1 puis tentative française","Support visuel constant avec vocabulaire affiché"],"pourPEI":["Adapter outils de dessin selon capacités motrices","Utiliser plan pré-dessiné à décorer seulement","Permettre création en 3D avec blocs si approprié","Respecter difficultés de traitement spatial"]}','{"vocabulary":["maison","cuisine","salon"],"visualSupports":["Geste de toit avec les mains pour ''maison'', bras ouverts pour accueil chaleureux","Photos de vraies cuisines et salons accueillants, gestes pour chaque pièce, connexions visuelles activité-lieu","Gestes de fierté et d''appartenance, pointer avec amour vers création"],"movementBreaks":["Imiter les animaux des histoires : sauter comme un lapin, voler comme un oiseau (3 minutes)","Former des lettres dans l''air avec nos doigts : A, B, C (3 minutes)","Faire une pause lecture : s''étirer comme un chat qui se réveille (2 minutes)","Faire des gestes de marionnettes pour raconter notre histoire (3 minutes)","Ranger nos idées : faire semblant de mettre nos pensées dans une boîte (2 minutes)","Étirer notre dos d''écrivains : rotation douce des épaules (2 minutes)"]}',NULL,NULL,NULL,NULL,'{"questions":["Les élèves ont-ils atteint les objectifs?","Quelles adaptations étaient nécessaires?","Que ferais-je différemment la prochaine fois?"]}',NULL,'',1,6,'core',1);
INSERT INTO ETFOLessonPlan VALUES('cmf43u3zy00m3vj9tbtw34pll',23,'Nos traditions familiales','cmf43u3zq00lpvj9tnsaml469',1761922800000,45,'Célébration multiculturelle: ''Qu''est-ce que votre famille célèbre?'' Présenter images joyeuses de différentes fêtes culturelles. Introduction respectueuse de ''tradition'' comme choses spéciales que les familles font.','Partage des traditions familiales: Chaque élève dessine ou décrit une tradition de sa famille (anniversaire, fête, repas spécial). Création d''un ''Livre des traditions de notre classe'' collectif.','Célébration finale: Chaque élève fait le geste de célébration et dit fièrement ''Ma famille célèbre!'' Promesse de continuer le livre des traditions pendant l''année.','Écrire le concept de nos traditions; Utiliser les compétences langagières fondamentales; Développer le vocabulaire français par des activités langagières variées','["Matériel de classe"]',NULL,'Nos traditions familiales','Célébration multiculturelle: ''Qu''est-ce que votre famille célèbre?'' Présenter images joyeuses de différentes fêtes culturelles. Introduction respectueuse de ''tradition'' comme choses spéciales que les familles font.','Partage des traditions familiales: Chaque élève dessine ou décrit une tradition de sa famille (anniversaire, fête, repas spécial). Création d''un ''Livre des traditions de notre classe'' collectif.','Célébration finale: Chaque élève fait le geste de célébration et dit fièrement ''Ma famille célèbre!'' Promesse de continuer le livre des traditions pendant l''année.','Écrire le concept de nos traditions; Utiliser les compétences langagières fondamentales; Développer le vocabulaire français par des activités langagières variées',NULL,NULL,NULL,'formative','{"observable":["Élève identifie au moins une tradition familiale","Élève utilise ''célébrer'' dans le contexte","Élève participe respectueusement aux partages culturels","Élève montre fierté de ses traditions familiales"],"checkpoints":["Pendant création: Observer engagement avec concept de tradition","Pendant partage: Noter respect pour diversité culturelle","Évaluer connection émotionnelle positive avec héritage familial"]}',1,'Plan détaillé avec supports visuels',1756911653566,1757594654146,1,'fr','Français (Immersion)','{"pourDifficultés":["Accepter dessins très simples ou abstraits","Permettre description orale au lieu de dessin","Utiliser traditions universelles (anniversaires, repas)","Offrir aide pour identifier une tradition familiale"],"pourAvancés":["Encourager détails sur comment ils célèbrent","Inviter à comparer traditions avec camarades","Ajouter éléments textuels à leur dessin","Aider à organiser le livre collectif"],"pourLangue":["Permettre explication dans langue première puis français","Connecter avec traditions de culture d''origine","Utiliser dessins comme communication principale","Support pour vocabulaire spécifique aux traditions"],"pourPEI":["Adapter outils de dessin selon capacités","Permettre représentation alternative (collage, 3D)","Respecter sensibilités culturelles ou familiales","Offrir temps supplémentaire pour réflexion"]}','{"vocabulary":["tradition","fête","célébrer"],"visualSupports":["Gestes de joie et célébration, mains levées pour ''fête'', geste circulaire pour ''tradition'' (continuité)","Exemples de dessins simples de traditions, images de référence pour inspiration, gestes encourageants","Gestes joyeux de célébration, expressions de fierté culturelle"],"movementBreaks":["Imiter les animaux des histoires : sauter comme un lapin, voler comme un oiseau (3 minutes)","Marcher en syllabant notre nom : Ma-rie, Paul, etc. en tapant dans nos mains (2 minutes)","Marcher sur place en récitant l''alphabet lentement (2 minutes)","Faire une pause lecture : s''étirer comme un chat qui se réveille (2 minutes)","Ranger nos idées : faire semblant de mettre nos pensées dans une boîte (2 minutes)","Dire au revoir avec tout notre corps : mains, têtes, pieds (2 minutes)"]}',NULL,NULL,NULL,NULL,'{"questions":["Les élèves ont-ils atteint les objectifs?","Quelles adaptations étaient nécessaires?","Que ferais-je différemment la prochaine fois?"]}',NULL,'',1,7,'core',1);
INSERT INTO ETFOLessonPlan VALUES('cmf43u3zy00m5vj9t49kto0db',23,'Mon histoire familiale','cmf43u3zq00lpvj9tnsaml469',1762185600000,45,'Conte du temps: Introduction d''histoire familiale avec ''hier'' vs ''aujourd''hui''. Gestes temporels simples et exemples concrets de souvenirs familiaux joyeux.','Création de livres d''histoires familiales: Élèves créent mini-livre avec 3 pages: Hier ma famille, Aujourd''hui ma famille, Demain ma famille (optionnel).','Cercle de conteurs: Chaque élève montre une page de son livre et raconte ''Mon histoire'' - célébration des souvenirs familiaux.','Raconter le concept de mon histoire; Raconter les compétences langagières fondamentales; Développer le vocabulaire français par la narration','["Matériel de classe"]',NULL,'Mon histoire familiale','Conte du temps: Introduction d''histoire familiale avec ''hier'' vs ''aujourd''hui''. Gestes temporels simples et exemples concrets de souvenirs familiaux joyeux.','Création de livres d''histoires familiales: Élèves créent mini-livre avec 3 pages: Hier ma famille, Aujourd''hui ma famille, Demain ma famille (optionnel).','Cercle de conteurs: Chaque élève montre une page de son livre et raconte ''Mon histoire'' - célébration des souvenirs familiaux.','Raconter le concept de mon histoire; Raconter les compétences langagières fondamentales; Développer le vocabulaire français par la narration',NULL,NULL,NULL,'formative','{"observable":["Élève distingue concept ''hier'' vs ''aujourd''hui''","Élève crée représentation d''histoire familiale","Élève utilise vocabulaire: histoire, hier, aujourd''hui","Élève partage souvenirs familiaux positivement"],"checkpoints":["Pendant création: Observer compréhension des concepts temporels","Pendant partage: Noter capacité narrative et vocabulaire","Évaluer connection émotionnelle avec mémoires familiales"]}',1,'Plan détaillé avec supports visuels',1756911653567,1757594654147,1,'fr','Français (Immersion)','{"pourDifficultés":["Se concentrer sur ''aujourd''hui'' seulement","Utiliser dessins très simples ou collage","Permettre aide pour idées d''histoires","Accepter représentation non-verbale"],"pourAvancés":["Ajouter page ''demain'' avec projections","Encourager détails narratifs: qui, quand, où","Inviter à aider camarades avec leurs histoires","Créer séquences plus complexes"],"pourLangue":["Permettre mélange linguistique dans narration","Utiliser images comme support principal","Connecter avec histoires de culture d''origine","Support gestuel constant pour vocabulaire temporel"],"pourPEI":["Adapter format de livre selon capacités motrices","Utiliser supports technologiques si approprié","Permettre narration alternative (gestes, sons)","Respecter besoins de traitement temporel"]}','{"vocabulary":["histoire","hier","aujourd''hui"],"visualSupports":["Geste vers l''arrière pour ''hier'', pointer ici pour ''aujourd''hui'', expression nostalgique pour ''histoire''","Exemple de mini-livre complété, images séquentielles familiales, gestes narratifs encourageants","Expressions d''écoute attentive, gestes d''encouragement, validation des histoires partagées"],"movementBreaks":["Marcher en syllabant notre nom : Ma-rie, Paul, etc. en tapant dans nos mains (2 minutes)","Répéter des comptines avec gestes : ''Tête, épaules, genoux et pieds'' (2 minutes)","Danser avec les sons : ''a'' avec les bras, ''o'' en rond, ''i'' pointu (3 minutes)","Faire des gestes de marionnettes pour raconter notre histoire (3 minutes)","Étirer notre dos d''écrivains : rotation douce des épaules (2 minutes)","Dire au revoir avec tout notre corps : mains, têtes, pieds (2 minutes)"]}',NULL,NULL,NULL,NULL,'{"questions":["Les élèves ont-ils atteint les objectifs?","Quelles adaptations étaient nécessaires?","Que ferais-je différemment la prochaine fois?"]}',NULL,'',1,8,'core',1);
INSERT INTO ETFOLessonPlan VALUES('cmf43u3zz00m7vj9t3dlpg88e',23,'Je décris ma famille','cmf43u3zq00lpvj9tnsaml469',1762272000000,45,'Galerie des qualités: Introduction respectueuse des mots descriptifs positifs. ''Chaque personne est spéciale!'' Modélage de ''grand'', ''petit'', ''gentil'' avec exemples bienveillants.','Création de ''Cartes de qualités familiales'': Élèves créent cartes décrivant positivement leurs membres de famille. Focus sur qualités du cœur et respect.','Partage des qualités: Chaque élève présente une carte et dit: ''Mon/Ma ___ est ___'' - célébration des qualités familiales positives.','Communiquer la famille et ses membres; Utiliser les rôles familiaux avec respect; Développer la communication orale par des activités langagières variées','["Matériel de classe"]',NULL,'Je décris ma famille','Galerie des qualités: Introduction respectueuse des mots descriptifs positifs. ''Chaque personne est spéciale!'' Modélage de ''grand'', ''petit'', ''gentil'' avec exemples bienveillants.','Création de ''Cartes de qualités familiales'': Élèves créent cartes décrivant positivement leurs membres de famille. Focus sur qualités du cœur et respect.','Partage des qualités: Chaque élève présente une carte et dit: ''Mon/Ma ___ est ___'' - célébration des qualités familiales positives.','Communiquer la famille et ses membres; Utiliser les rôles familiaux avec respect; Développer la communication orale par des activités langagières variées',NULL,NULL,NULL,'formative','{"observable":["Élève utilise vocabulaire descriptif positif","Élève crée représentations respectueuses de famille","Élève distingue qualités physiques et comportementales","Élève exprime affection pour membres de famille"],"checkpoints":["Pendant création: Observer choix de vocabulaire et attitudes","Pendant partage: Noter usage respectueux des descriptions","Évaluer développement de langage descriptif positif"]}',1,'Plan détaillé avec supports visuels',1756911653568,1757594654148,1,'fr','Français (Immersion)','{"pourDifficultés":["Se concentrer sur un seul mot: ''gentil'' pour tous","Utiliser dessins très simples ou autocollants","Permettre aide pour écriture des mots","Accepter pointage vers qualités sans verbalisation"],"pourAvancés":["Encourager multiple qualités par personne","Ajouter explications: pourquoi cette qualité?","Créer cartes pour plus de membres famille","Aider camarades à identifier qualités positives"],"pourLangue":["Connecter qualités avec langue première","Utiliser gestes expressifs pour chaque qualité","Permettre descriptions dans L1 puis français","Support visuel constant avec images-mots"],"pourPEI":["Adapter création selon capacités motrices","Utiliser format alternatif (oral, technologique)","Respecter sensibilités émotionnelles familiales","Permettre temps supplémentaire pour réflexion"]}','{"vocabulary":["grand","petit","gentil"],"visualSupports":["Gestes respectueux pour taille (mains en hauteur), cœur pour gentillesse, sourires bienveillants","Photos de familles montrant amour et qualités positives, exemples de cartes complétées, modèles positifs","Expressions d''admiration et respect pour chaque partage, gestes d''approbation"],"movementBreaks":["Imiter les animaux des histoires : sauter comme un lapin, voler comme un oiseau (3 minutes)","Répéter des comptines avec gestes : ''Tête, épaules, genoux et pieds'' (2 minutes)","Danser avec les sons : ''a'' avec les bras, ''o'' en rond, ''i'' pointu (3 minutes)","Faire une pause lecture : s''étirer comme un chat qui se réveille (2 minutes)","Ranger nos idées : faire semblant de mettre nos pensées dans une boîte (2 minutes)","Dire au revoir avec tout notre corps : mains, têtes, pieds (2 minutes)"]}',NULL,NULL,NULL,NULL,'{"questions":["Les élèves ont-ils atteint les objectifs?","Quelles adaptations étaient nécessaires?","Que ferais-je différemment la prochaine fois?"]}',NULL,'',1,9,'core',1);
INSERT INTO ETFOLessonPlan VALUES('cmf43u40000m9vj9tqyt1140r',23,'Les émotions en famille','cmf43u3zq00lpvj9tnsaml469',1762358400000,45,'Cercle des sentiments chaleureux: ''Comment votre famille vous fait-elle sentir?'' Introduction tendre des émotions positives avec validation des sentiments de chaque enfant.','Jardin des sentiments familiaux: Élèves créent ''fleur des émotions'' avec pétales représentant comment leur famille les fait sentir. Focus sur émotions positives et sécurité émotionnelle.','Affirmation collective puissante: Chaque élève se fait un câlin et dit avec fierté ''Je suis aimé dans ma famille!'' Célébration de l''amour familial universel.','Exprimer la famille et ses membres; Utiliser les rôles familiaux avec respect; Développer la communication orale par des activités langagières variées','["Matériel de classe"]',NULL,'Les émotions en famille','Cercle des sentiments chaleureux: ''Comment votre famille vous fait-elle sentir?'' Introduction tendre des émotions positives avec validation des sentiments de chaque enfant.','Jardin des sentiments familiaux: Élèves créent ''fleur des émotions'' avec pétales représentant comment leur famille les fait sentir. Focus sur émotions positives et sécurité émotionnelle.','Affirmation collective puissante: Chaque élève se fait un câlin et dit avec fierté ''Je suis aimé dans ma famille!'' Célébration de l''amour familial universel.','Exprimer la famille et ses membres; Utiliser les rôles familiaux avec respect; Développer la communication orale par des activités langagières variées',NULL,NULL,NULL,'formative','{"observable":["Élève identifie émotions positives liées à la famille","Élève utilise vocabulaire: heureux, content, aimé","Élève exprime sécurité émotionnelle avec famille","Élève participe positivement à l''affirmation collective"],"checkpoints":["Pendant création: Observer bien-être émotionnel et engagement","Pendant partage: Noter confort avec expression émotionnelle","Surveiller signes de détresse et offrir soutien approprié"]}',1,'Plan détaillé avec supports visuels',1756911653569,1757594654149,1,'fr','Français (Immersion)','{"pourDifficultés":["Se concentrer sur une émotion: ''aimé'' ou ''heureux''","Utiliser dessins simples au lieu de mots","Permettre expression non-verbale (étreinte, sourire)","Offrir soutien émotionnel supplémentaire"],"pourAvancés":["Encourager vocabulaire émotionnel plus riche","Inviter à expliquer pourquoi ils ressentent ces émotions","Ajouter nuances: très heureux, un peu content","Aider camarades à identifier leurs émotions"],"pourLangue":["Connecter émotions avec langue première","Utiliser expressions faciales comme communication principale","Permettre description dans L1 puis français","Support gestuel constant pour vocabulaire émotionnel"],"pourPEI":["Adapter selon besoins émotionnels spécifiques","Utiliser supports alternatifs pour expression","Respecter difficultés de régulation émotionnelle","Offrir espace sécuritaire pour traitement"]}','{"vocabulary":["heureux","content","aimé"],"visualSupports":["Expressions faciales très claires, gestes du cœur pour ''aimé'', sourire pour ''heureux'', bras croisés pour ''content''","Images de familles dans moments émotionnels positifs: rires, câlins, jeux, réconforts tendres","Gestes d''auto-câlin bienveillant, expressions de tendresse et validation, sourires rassurants"],"movementBreaks":["Marcher en syllabant notre nom : Ma-rie, Paul, etc. en tapant dans nos mains (2 minutes)","Imiter les animaux des histoires : sauter comme un lapin, voler comme un oiseau (3 minutes)","Danser avec les sons : ''a'' avec les bras, ''o'' en rond, ''i'' pointu (3 minutes)","Marcher sur place en récitant l''alphabet lentement (2 minutes)","Faire une révérence à nos nouvelles connaissances (1 minute)","Ranger nos idées : faire semblant de mettre nos pensées dans une boîte (2 minutes)"]}',NULL,NULL,NULL,NULL,'{"questions":["Les élèves ont-ils atteint les objectifs?","Quelles adaptations étaient nécessaires?","Que ferais-je différemment la prochaine fois?"]}',NULL,'',1,10,'core',1);
INSERT INTO ETFOLessonPlan VALUES('cmf43u40100mbvj9tij7e2a3o',23,'Créer notre livre de famille','cmf43u3zq00lpvj9tnsaml469',1762444800000,45,'Inspiration littéraire: Présentation d''exemples de livres de famille créés par d''autres élèves (années précédentes). ''Nous allons devenir des auteurs de livres familiaux!'' Introduction du projet créatif.','Atelier de création de livres familiaux: Élèves commencent leur livre personnel avec support scaffoldé. Pages suggérées: Couverture, Ma famille, Nos activités, Ce que j''aime de ma famille.','Présentation des couvertures: Chaque élève montre fièrement sa couverture et dit ''Voici MON livre de famille!'' Planification de la suite du projet.','Décrire la famille et ses membres; Créer les rôles familiaux avec respect; Développer la communication orale par des activités langagières variées','["Matériel de classe"]',NULL,'Créer notre livre de famille','Inspiration littéraire: Présentation d''exemples de livres de famille créés par d''autres élèves (années précédentes). ''Nous allons devenir des auteurs de livres familiaux!'' Introduction du projet créatif.','Atelier de création de livres familiaux: Élèves commencent leur livre personnel avec support scaffoldé. Pages suggérées: Couverture, Ma famille, Nos activités, Ce que j''aime de ma famille.','Présentation des couvertures: Chaque élève montre fièrement sa couverture et dit ''Voici MON livre de famille!'' Planification de la suite du projet.','Décrire la famille et ses membres; Créer les rôles familiaux avec respect; Développer la communication orale par des activités langagières variées',NULL,NULL,NULL,'formative','{"observable":["Élève s''engage activement dans projet créatif","Élève utilise vocabulaire familial appris dans unité","Élève fait choix créatifs réfléchis pour représenter sa famille","Élève exprime fierté d''auteur avec sa création"],"checkpoints":["Pendant création: Observer engagement créatif et utilisation de ressources","Pendant présentation: Noter fierté d''auteur et connexion au contenu","Évaluer integration cumulative du vocabulaire et concepts de l''unité"]}',1,'Plan détaillé avec supports visuels',1756911653569,1757594654150,1,'fr','Français (Immersion)','{"pourDifficultés":["Réduire à 3-4 pages simples","Permettre plus de dessins, moins d''écriture","Offrir templates pré-formatés à compléter","Aide individuelle pour planification et organisation"],"pourAvancés":["Encourager plus de pages et détails","Inviter à ajouter phrases complètes","Permettre expérimentation avec formats créatifs","Aider camarades avec techniques artistiques"],"pourLangue":["Permettre mélange linguistique dans création","Utiliser plus d''images, moins de texte","Support avec copie de mots français","Connecter avec traditions de livres de culture d''origine"],"pourPEI":["Adapter outils selon capacités motrices","Permettre collaboration avec assistant ou pair","Utiliser technologie d''assistance si appropriée","Respecter besoins de traitement et d''organisation"]}','{"vocabulary":["livre","page","écrire"],"visualSupports":["Gestes d''écriture et création, expressions d''excitement créatif, modèles inspirants","Templates de pages, exemples de mise en page, guide visuel d''étapes de création","Expressions de fierté d''auteur, gestes de présentation, validation de chaque création"],"movementBreaks":["Imiter les animaux des histoires : sauter comme un lapin, voler comme un oiseau (3 minutes)","Former des lettres dans l''air avec nos doigts : A, B, C (3 minutes)","Danser avec les sons : ''a'' avec les bras, ''o'' en rond, ''i'' pointu (3 minutes)","Faire des gestes de marionnettes pour raconter notre histoire (3 minutes)","Célébrer nos apprentissages : applaudir, lever les bras, sourire (2 minutes)","Étirer notre dos d''écrivains : rotation douce des épaules (2 minutes)"]}',NULL,NULL,NULL,NULL,'{"questions":["Les élèves ont-ils atteint les objectifs?","Quelles adaptations étaient nécessaires?","Que ferais-je différemment la prochaine fois?"]}',NU