INSERT INTO ETFOLessonPlan VALUES('cmf43u40200mdvj9tiwkm2k5y',23,'Mon arbre généalogique','cmf43u3zq00lpvj9tnsaml469',1762790400000,45,'Métaphore de l''arbre familial: ''Les familles poussent comme des arbres!'' Introduction du concept avec vraie plante ou image d''arbre. Explication simple des relations familiales avec gestes.','Création d''arbres familiaux inclusifs: Élèves créent leur arbre unique avec templates flexibles. Accent sur diversité: familles monoparentales, grands-parents, familles recomposées - tous formats acceptés.','Forêt familiale: Affichage temporaire de tous les arbres créant une ''forêt de familles''. Chaque élève pointe fièrement vers son arbre: ''Voici MON arbre de famille!''','Lire le concept de mon arbre; Utiliser les compétences langagières fondamentales; Développer la communication orale par des activités langagières variées','["Matériel de classe"]',NULL,'Mon arbre généalogique','Métaphore de l''arbre familial: ''Les familles poussent comme des arbres!'' Introduction du concept avec vraie plante ou image d''arbre. Explication simple des relations familiales avec gestes.','Création d''arbres familiaux inclusifs: Élèves créent leur arbre unique avec templates flexibles. Accent sur diversité: familles monoparentales, grands-parents, familles recomposées - tous formats acceptés.','Forêt familiale: Affichage temporaire de tous les arbres créant une ''forêt de familles''. Chaque élève pointe fièrement vers son arbre: ''Voici MON arbre de famille!''','Lire le concept de mon arbre; Utiliser les compétences langagières fondamentales; Développer la communication orale par des activités langagières variées',NULL,NULL,NULL,'formative','{"observable":["Élève comprend concept de relations familiales","Élève crée représentation visuelle de sa structure familiale","Élève utilise vocabulaire: arbre, parents, enfant","Élève respecte et apprécie diversité des ma famille"],"checkpoints":["Pendant création: Observer compréhension des relations et organisation spatiale","Pendant présentation: Noter fierté de structure familiale unique","Évaluer integration des concepts de parenté et appartenance"]}',1,'Plan détaillé avec supports visuels',1756911653570,1757594654151,1,'fr','Français (Immersion)','{"pourDifficultés":["Utiliser format très simple (cercle avec élève au centre)","Se concentrer sur qui vit à la maison seulement","Permettre collage simple sans écriture","Aide individuelle pour organisation spatiale"],"pourAvancés":["Ajouter générations supplémentaires si connues","Inclure animaux domestiques comme membres famille","Ajouter descriptions ou qualités près de chaque membre","Créer légende ou code couleur pour relations"],"pourLangue":["Permettre étiquettes dans langue première aussi","Utiliser dessins comme communication principale","Support pour vocabulaire de relations familiales","Connecter avec ma famille de culture d''origine"],"pourPEI":["Adapter format selon capacités de traitement spatial","Utiliser supports technologiques si appropriés","Permettre création collaborative avec aide","Respecter sensibilités liées aux relations familiales"]}','{"vocabulary":["arbre","parents","enfant"],"visualSupports":["Gestes de croissance (mains qui poussent), relations spatiales (haut/bas), connexions familiales","Exemples variés d''arbres familiaux non-traditionnels, guide visuel d''étapes de création","Gestes de fierté et appartenance, expressions d''admiration pour diversité des structures"],"movementBreaks":["Répéter des comptines avec gestes : ''Tête, épaules, genoux et pieds'' (2 minutes)","Former des lettres dans l''air avec nos doigts : A, B, C (3 minutes)","Marcher sur place en récitant l''alphabet lentement (2 minutes)","Faire une pause lecture : s''étirer comme un chat qui se réveille (2 minutes)","Ranger nos idées : faire semblant de mettre nos pensées dans une boîte (2 minutes)","Faire une révérence à nos nouvelles connaissances (1 minute)"]}',NULL,NULL,NULL,NULL,'{"questions":["Les élèves ont-ils atteint les objectifs?","Quelles adaptations étaient nécessaires?","Que ferais-je différemment la prochaine fois?"]}',NULL,'',1,12,'core',1);
INSERT INTO ETFOLessonPlan VALUES('cmf43u40300mfvj9to8dq2j6c',23,'Partager nos familles','cmf43u3zq00lpvj9tnsaml469',1762876800000,45,'Préparation de présentateurs: ''Comment être un bon présentateur?'' Modélage de présentation avec gestes clairs, voix forte, et fierté. Introduction des mots clés avec actions.','Préparation et pratique de présentations: Élèves préparent présentation de leur travail familial (livre, arbre, affiche) avec support de phrases modèles. Pratique en petits groupes avant présentation à la classe.','Répétition générale collective: Tous ensemble, pratique de l''ouverture ''Voici ma famille!'' avec gestes confiants. Préparation mentale positive pour présentations de demain.','Écrire la famille et ses membres; Utiliser les rôles familiaux avec respect; Développer la compréhension par des activités langagières variées','["Matériel de classe"]',NULL,'Partager nos familles','Préparation de présentateurs: ''Comment être un bon présentateur?'' Modélage de présentation avec gestes clairs, voix forte, et fierté. Introduction des mots clés avec actions.','Préparation et pratique de présentations: Élèves préparent présentation de leur travail familial (livre, arbre, affiche) avec support de phrases modèles. Pratique en petits groupes avant présentation à la classe.','Répétition générale collective: Tous ensemble, pratique de l''ouverture ''Voici ma famille!'' avec gestes confiants. Préparation mentale positive pour présentations de demain.','Écrire la famille et ses membres; Utiliser les rôles familiaux avec respect; Développer la compréhension par des activités langagières variées',NULL,NULL,NULL,'formative','{"observable":["Élève prépare présentation avec engagement","Élève utilise phrases modèles et vocabulaire familial","Élève fait effort pour communiquer clairement","Élève montre fierté et confiance croissante"],"checkpoints":["Pendant préparation: Observer organisation et utilisation de supports","Pendant pratique: Noter progrès en confiance et clarté","Évaluer préparation pour culmination réussie de l''unité"]}',1,'Plan détaillé avec supports visuels',1756911653571,1757594654152,1,'fr','Français (Immersion)','{"pourDifficultés":["Réduire à phrase simple: ''Voici ma famille''","Permettre pointage avec support minimal oral","Présentation en très petit groupe d''amis","Utiliser supports visuels comme aide-mémoire"],"pourAvancés":["Encourager détails et descriptions enrichies","Inviter questions de l''audience et réponses","Ajouter éléments narratifs ou anecdotes","Aider à animer présentations d''autres élèves"],"pourLangue":["Permettre mélange linguistique si nécessaire","Utiliser supports visuels comme communication principale","Support gestuel constant et encouragement","Accepter tentatives même avec erreurs linguistiques"],"pourPEI":["Adapter format selon besoins communicatifs","Utiliser supports technologiques si appropriés","Permettre présentation alternative (dessin, mouvement)","Respecter besoins d''anxiété sociale et offrir accommodations"]}','{"vocabulary":["présenter","montrer","expliquer"],"visualSupports":["Gestes de présentation clairs, posture confiante, expressions engageantes","Guide visuel de bonnes pratiques de présentation, gestes encourageants, modèles de phrases","Gestes collectifs confiants, expressions de fierté, ambiance de soutien mutuel"],"movementBreaks":["Marcher en syllabant notre nom : Ma-rie, Paul, etc. en tapant dans nos mains (2 minutes)","Faire l''alphabet avec notre corps : A comme arbre (étirer les bras), B comme ballon (forme ronde) (3 minutes)","Marcher sur place en récitant l''alphabet lentement (2 minutes)","Danser avec les sons : ''a'' avec les bras, ''o'' en rond, ''i'' pointu (3 minutes)","Ranger nos idées : faire semblant de mettre nos pensées dans une boîte (2 minutes)","Étirer notre dos d''écrivains : rotation douce des épaules (2 minutes)"]}',NULL,NULL,NULL,NULL,'{"questions":["Les élèves ont-ils atteint les objectifs?","Quelles adaptations étaient nécessaires?","Que ferais-je différemment la prochaine fois?"]}',NULL,'',1,13,'core',1);
INSERT INTO ETFOLessonPlan VALUES('cmf43u40400mhvj9tm3j0j5cw',23,'Célébration des familles','cmf43u3zq00lpvj9tnsaml469',1762963200000,45,'Ouverture festive: Décoration de la classe en ''galerie familiale''. Musique douce multiculturelle, installation de chaise spéciale présentateur. ''Aujourd''hui nous célébrons nos belles familles!''','Présentations culminantes: Chaque élève présente fièrement un de leurs travaux familiaux. Applaudissements chaleureux, documentation photo respectueuse, célébration de chaque famille unique.','Célébration collective puissante: Tous ensemble, chant ou déclaration finale ''Nos familles sont belles et spéciales!'' Réflexion sur apprentissages et fierté collective.','Raconter la famille et ses membres; Utiliser les rôles familiaux avec respect; Développer la compréhension par la célébration collective','["Matériel de classe"]',NULL,'Célébration des familles','Ouverture festive: Décoration de la classe en ''galerie familiale''. Musique douce multiculturelle, installation de chaise spéciale présentateur. ''Aujourd''hui nous célébrons nos belles familles!''','Présentations culminantes: Chaque élève présente fièrement un de leurs travaux familiaux. Applaudissements chaleureux, documentation photo respectueuse, célébration de chaque famille unique.','Célébration collective puissante: Tous ensemble, chant ou déclaration finale ''Nos familles sont belles et spéciales!'' Réflexion sur apprentissages et fierté collective.','Raconter la famille et ses membres; Utiliser les rôles familiaux avec respect; Développer la compréhension par la célébration collective',NULL,NULL,NULL,'formative','{"observable":["Élève présente avec fierté et engagement","Élève utilise vocabulaire familial appris dans unité","Élève participe positivement à célébration collective","Élève démontre integration des apprentissages familiaux"],"checkpoints":["Pendant présentations: Observer confiance, utilisation vocabulaire, fierté familiale","Pendant célébration: Noter engagement communautaire et respect diversité","Évaluation sommative: accomplissement objectifs d''unité et croissance linguistique"]}',1,'Plan détaillé avec supports visuels',1756911653572,1757594654153,1,'fr','Français (Immersion)','{"pourDifficultés":["Permettre présentation très courte ou simple monter d''objet","Support d''un ami ou enseignant pendant présentation","Participation alternative (applaudir, aider à organiser)","Célébration de participation à tout niveau"],"pourAvancés":["Encourager présentations détaillées et interactives","Inviter à animer ou aider autres présentations","Ajouter éléments créatifs (chanson, poème)","Prendre rôle de leadership dans célébration"],"pourLangue":["Accepter présentations multilingues avec tentatives françaises","Support gestuel et visuel maximal","Célébrer efforts linguistiques quel que soit niveau","Permettre traduction par pairs si nécessaire"],"pourPEI":["Adapter format de présentation selon besoins individuels","Utiliser supports technologiques ou alternatifs","Respecter besoins sensoriels et émotionnels","Célébrer participation unique et précieuse"]}','{"vocabulary":["célébration","fier","apprendre"],"visualSupports":["Affichage de tous travaux familiaux, gestes de célébration joyeux, ambiance d''honneur et respect","Espace d''honneur pour présentations, guide visuel de rôles audience (applaudir, écouter), expressions de fierté","Gestes collectifs de célébration, expressions de joie partagée, validation universelle"],"movementBreaks":["Marcher en syllabant notre nom : Ma-rie, Paul, etc. en tapant dans nos mains (2 minutes)","Imiter les animaux des histoires : sauter comme un lapin, voler comme un oiseau (3 minutes)","Faire une pause lecture : s''étirer comme un chat qui se réveille (2 minutes)","Danser avec les sons : ''a'' avec les bras, ''o'' en rond, ''i'' pointu (3 minutes)","Faire une révérence à nos nouvelles connaissances (1 minute)","Étirer notre dos d''écrivains : rotation douce des épaules (2 minutes)"]}',NULL,NUL