INSERT INTO ETFOLessonPlan VALUES('cmf43u40400mjvj9t39bnkphh',23,'Jeux de rôle familiaux','cmf43u3zq00lpvj9tnsaml469',1763049600000,45,'Transformation théâtrale: ''Aujourd''hui nous devenons des acteurs!'' Installation d''espaces jeu dramatique avec accessoires. Introduction du jeu libre avec vocabulaire familial.','Jeu dramatique familial libre: Élèves explorent rôles familiaux à travers jeu créatif. Renforcement naturel vocabulaire français dans contexte ludique et social.','Partage d''acteurs: Chaque élève partage un mot français utilisé pendant le jeu. Applaudissements pour performances créatives.','Communiquer le concept de jeux de; Participer à les compétences langagières fondamentales; Développer la compréhension par le jeu dirigé','["Matériel de classe"]',NULL,'Jeux de rôle familiaux','Transformation théâtrale: ''Aujourd''hui nous devenons des acteurs!'' Installation d''espaces jeu dramatique avec accessoires. Introduction du jeu libre avec vocabulaire familial.','Jeu dramatique familial libre: Élèves explorent rôles familiaux à travers jeu créatif. Renforcement naturel vocabulaire français dans contexte ludique et social.','Partage d''acteurs: Chaque élève partage un mot français utilisé pendant le jeu. Applaudissements pour performances créatives.','Communiquer le concept de jeux de; Participer à les compétences langagières fondamentales; Développer la compréhension par le jeu dirigé',NULL,NULL,NULL,'formative','{"observable":["Élève s''engage dans jeu créatif collaboratif","Élève utilise vocabulaire familial dans contexte naturel","Élève explore rôles et relations familiales positivement","Élève participe au partage réflexif final"],"checkpoints":["Pendant jeu: Observer utilisation naturelle du vocabulaire appris","Pendant interactions: Noter collaboration et créativité sociale","Évaluer transfert des apprentissages vers contexte ludique authentique"]}',1,'Plan détaillé avec supports visuels',1756911653573,1757594654154,1,'fr','Français (Immersion)','{"po