INSERT INTO ETFOLessonPlan VALUES('cmf43u40500mlvj9tqvo6vjre',23,'Album photo familial','cmf43u3zq00lpvj9tnsaml469',1763136000000,45,'Inspiration d''archiviste: Présentation d''albums photo authentiques. ''Comment garder nos souvenirs familiaux précieux?'' Introduction projet créatif personnalisé.','Création d''albums photo familiaux personnalisés avec légendes en français. Projet créatif combinant mémoires visuelles et apprentissage linguistique.','Partage d''archivistes: Élèves présentent une page favorite et lisent légende française. Célébration des mémoires préservées.','Exprimer le concept de album photo; Utiliser les compétences langagières fondamentales; Développer la compréhension par des activités langagières variées','["Matériel de classe"]',NULL,'Album photo familial','Inspiration d''archiviste: Présentation d''albums photo authentiques. ''Comment garder nos souvenirs familiaux précieux?'' Introduction projet créatif personnalisé.','Création d''albums photo familiaux personnalisés avec légendes en français. Projet créatif combinant mémoires visuelles et apprentissage linguistique.','Partage d''archivistes: Élèves présentent une page favorite et lisent légende française. Célébration des mémoires préservées.','Exprimer le concept de album photo; Utiliser les compétences langagières fondamentales; Développer la compréhension par des activités langagières variées',NULL,NULL,NULL,'formative','{"observable":["Élève crée album personnalisé avec engagement","Élève utilise vocabulaire familial dans légendes","Élève organise contenu de manière cohérente","Élève partage fièrement sa création"],"checkpoints":["Pendant création: Observer choix créatifs et utilisation vocabulaire","Pendant partage: Noter fierté et connexion émotionnelle au projet","Évaluer integration créative des apprentissages linguistiques"]}',1,'Plan détaillé avec supports visuels',1756911653574,1757594654155,1,'fr','Français (Immersion)','{"pourDifficultés":["Légendes d''un mot seulement","Plus de dessins, moins de photos","Aide pour organisation et écriture","Format album simplifié (3-4 pages)"],"pourAvancés":["Légendes détaillées en phrases complètes","Organisation thématique ou chronologique","Éléments artistiques et décoratifs avancés","Aide aux camarades avec techniques de création"],"pourLangue":["Légendes bilingues acceptées","Support visuel prioritaire sur textuel","Aide avec vocabulaire français spécifique","Encouragement tentatives sans pression perfection"],"pourPEI":["Adaptation outils selon capacités motrices","Support technologique si approprié","Format alternatif (collage, compilation)","Respect besoins organisation et traitement"]}','{"vocabulary":["mot","phrase","histoire","lire","écrire"],"visualSupports":["Gestes de préciosité et mémoire, expressions d''admiration pour souvenirs","Banque mots famille affichée, modèles de légendes simples, exemples de mise en page","Expressions d''appréciation pour mémoires partagées, gestes de respect pour histoires familiales"],"movementBreaks":["Répéter des comptines avec gestes : ''Tête, épaules, genoux et pieds'' (2 minutes)","Marcher en syllabant notre nom : Ma-rie, Paul, etc. en tapant dans nos mains (2 minutes)","Danser avec les sons : ''a'' avec les bras, ''o'' en rond, ''i'' pointu (3 minutes)","Marcher sur place en récitant l''alphabet lentement (2 minutes)","Célébrer nos apprentissages : applaudir, lever les bras, sourire (2 minutes)","Ranger nos idées : faire semblant de mettre nos pensées dans une boîte (2 minutes)"]}',NULL,NULL,NULL,NULL,'{"questions":["Les élèves ont-ils atteint les objectifs?","Quelles adaptations étaient nécessaires?","Que ferais-je différemment la prochaine fois?"]}',NULL,'',1,16,'extension',1);
INSERT INTO ETFOLessonPlan VALUES('cmf43u40600mnvj9tt1fifhoe',23,'Interviews avec la famille','cmf43u3zq00lpvj9tnsaml469',1763395200000,45,'Formation de journalistes: ''Comment découvrir plus sur nos familles?'' Présentation de questions simples avec intonation interview respectueuse.','Pratique d''interviews familiales: Jeu de rôle journaliste-interviewé avec questions simples en français. Rotation des rôles et pratique bienveillante.','Conférence de presse: Chaque ''élève-journaliste'' pose une question à la classe. Pratique collective et applaudissements.','Décrire la famille et ses membres; Utiliser les rôles familiaux avec respect; Développer l''expression écrite par des activités langagières variées','["Matériel de classe"]',NULL,'Interviews avec la famille','Formation de journalistes: ''Comment découvrir plus sur nos familles?'' Présentation de questions simples avec intonation interview respectueuse.','Pratique d''interviews familiales: Jeu de rôle journaliste-interviewé avec questions simples en français. Rotation des rôles et pratique bienveillante.','Conférence de presse: Chaque ''élève-journaliste'' pose une question à la classe. Pratique collective et applaudissements.','Décrire la famille et ses membres; Utiliser les rôles familiaux avec respect; Développer l''expression écrite par des activités langagières variées',NULL,NULL,NULL,'formative','{"observable":["Élève tente formulation de questions en français","Élève utilise intonation interrogative appropriée","Élève s''engage dans jeu de rôle collaboratif","Élève participe au partage collectif final"],"checkpoints":["Pendant pratique: Observer tentatives linguistiques et intonation","Pendant jeu de rôle: Noter engagement social et créatif","Évaluer transfert de vocabulaire vers nouveaux contextes communicatifs"]}',1,'Plan détaillé avec supports visuels',1756911653575,1757594654156,1,'fr','Français (Immersion)','{"pourDifficultés":["Questions d''un mot: ''Qui?'', ''Quoi?''","Répétition après enseignant","Pointage au lieu de questions verbales","Participation comme interviewé plutôt que journaliste"],"pourAvancés":["Création de questions originales","Questions de suivi selon réponses","Animation du jeu d''interview","Aide aux camarades avec formulation"],"pourLangue":["Mélange linguistique accepté dans questions","Support gestuel avec questions","Questions dans L1 puis tentative française","Focus sur intonation plus que vocabulaire"],"pourPEI":["Adaptation selon besoins communicatifs","Questions écrites si expression orale difficile","Participation observateur si nécessaire","Support technologique pour formulation"]}','{"vocabulary":["mot","phrase","histoire","lire","écrire"],"visualSupports":["Gestes d''intonation interrogative, expressions curieuses respectueuses","Guide questions affiché, modèles d''intonation, encouragements pour tentatives","Gestes d''encouragement, validation des tentatives linguistiques"],"movementBreaks":["Répéter des comptines avec gestes : ''Tête, épaules, genoux et pieds'' (2 minutes)","Faire l''alphabet avec notre corps : A comme arbre (étirer les bras), B comme ballon (forme ronde) (3 minutes)","Étirer nos doigts et mains d''écrivains : ouvrir, fermer, tourner (2 minutes)","Faire une pause lecture : s''étirer comme un chat qui se réveille (2 minutes)","Étirer notre dos d''écrivains : rotation douce des épaules (2 minutes)","Dire au revoir avec tout notre corps : mains, têtes, pieds (2 minutes)"]}',NULL,NULL,NULL,NULL,'{"questions":["Les élèves ont-ils atteint les objectifs?","Quelles adaptations étaient nécessaires?","Que ferais-je différemment la prochaine fois?"]}',NULL,'',1,17,'extension',1);
INSERT INTO ETFOLessonPlan VALUES('cmf43u40700mpvj9t3b5188pf',23,'Familles du monde','cmf43u3zq00lpvj9tnsaml469',4102416000000,45,'Voyage mondial virtuel: ''Les familles partout dans le monde!'' Présentation respectueuse de diversité culturelle familiale globale.','Exploration respectueuse familles mondiales: Découverte guidée de traditions familiales diverses. Focus sur similitudes universelles et beauté des différences.','Déclaration mondiale: Élèves pointent vers carte et disent ''Des familles partout!'' Célébration de l''universalité de l''amour familial.','Appliquer la famille et ses membres; Utiliser les rôles familiaux avec respect; Développer l''expression écrite par des activités langagières variées','["Matériel de classe"]',NULL,'Familles du monde','Voyage mondial virtuel: ''Les familles partout dans le monde!'' Présentation respectueuse de diversité culturelle familiale globale.','Exploration respectueuse familles mondiales: Découverte guidée de traditions familiales diverses. Focus sur similitudes universelles et beauté des différences.','Déclaration mondiale: Élèves pointent vers carte et disent ''Des familles partout!'' Célébration de l''universalité de l''amour familial.','Appliquer la famille et ses membres; Utiliser les rôles familiaux avec respect; Développer l''expression écrite par des activités langagières variées',NULL,NULL,NULL,'formative','{"observable":["Élève montre intérêt respectueux pour diversité culturelle","Élève identifie points communs entre familles mondiales","Élève participe à célébration d''unité familiale universelle","Élève utilise vocabulaire familial dans contexte global"],"checkpoints":["Pendant exploration: Observer attitudes d''ouverture et respect","Pendant discussions: Noter compréhension concepts universels vs uniques","Évaluer développement de perspective mondiale bienveillante"]}',1,'Plan détaillé avec supports visuels',1756911653576,1757594654157,1,'fr','Français (Immersion)','{"pourDifficultés":["Focus sur similitudes plutôt que différences","Images très claires et évidentes","Concepts simples: familles mangent, jouent, s''aiment","Participation par observation principalement"],"pourAvancés":["Encourager questions réfléchies sur cultures","Connections avec leur propre héritage culturel","Comparaisons respectueuses entre traditions","Aide à expliquer concepts aux camarades"],"pourLangue":["Connecter avec culture d''origine avec fierté","Permettre partage de traditions familiales","Utiliser langue première pour enrichir discussion","Validation de diversité linguistique comme atout"],"pourPEI":["Adapter selon capacités de traitement culturel","Utiliser supports visuels comme priorité","Respecter sensibilités à nouveaux concepts","Permettre temps supplémentaire pour absorption"]}','{"vocabulary":["mot","phrase","histoire","lire","écrire"],"visualSupports":["Gestes d''ouverture mondiale, expressions de curiosité respectueuse, célébration diversité","Images positives et respectueuses, gestes d''inclusion, expressions d''admiration culturelle","Gestes inclusifs vers toutes directions, expressions d''unité mondiale"],"movementBreaks":["Faire l''alphabet avec notre corps : A comme arbre (étirer les bras), B comme ballon (forme ronde) (3 minutes)","Répéter des comptines avec gestes : ''Tête, épaules, genoux et pieds'' (2 minutes)","Faire des gestes de marionnettes pour raconter notre histoire (3 minutes)","Faire une pause lecture : s''étirer comme un chat qui se réveille (2 minutes)","Ranger nos idées : faire semblant de mettre nos pensées dans une boîte (2 minutes)","Célébrer nos apprentissages : applaudir, lever les bras, sourire (2 minutes)"]}',NULL,NULL,NULL,NULL,'{"questions":["Les élèves ont-ils atteint les objectifs?","Quelles adaptations étaient nécessaires?","Que ferais-je différemment la prochaine fois?"]}',NULL,'',1,18,'extension',0);
INSERT INTO ETFOLessonPlan VALUES('cmf43u40800mrvj9t4xpzxutq',23,'Chansons et comptines familiales','cmf43u3zq00lpvj9tnsaml469',4102416000000,45,'Atelier de musique familiale: ''La musique unit les familles!'' Introduction joyeuse aux chansons comme tradition familiale universelle.','Apprentissage et pratique chansons familiales françaises. Combinaison musique, mouvement, et vocabulaire dans expérience culturelle joyeuse.','Concert familial: Performance collective de chanson apprise. Applaudissements et célébration de talents musicaux.','Créer les sons et leur correspondance; Chanter la discrimination auditive des sons; Développer l''expression écrite par les activités musicales','["Matériel de classe"]',NULL,'Chansons et comptines familiales','Atelier de musique familiale: ''La musique unit les familles!'' Introduction joyeuse aux chansons comme tradition familiale universelle.','Apprentissage et pratique chansons familiales françaises. Combinaison musique, mouvement, et vocabulaire dans expérience culturelle joyeuse.','Concert familial: Performance collective de chanson apprise. Applaudissements et célébration de talents musicaux.','Créer les sons et leur correspondance; Chanter la discrimination auditive des sons; Développer l''expression écrite par les activités musicales',NULL,NULL,NULL,'formative','{"observable":["Élève participe joyeusement à expérience musicale","Élève utilise vocabulaire familial dans contexte musical","Élève s''engage avec gestes et mouvements appropriés","Élève contribue positivement à performance collective"],"checkpoints":["Pendant apprentissage: Observer engagement musical et linguistique","Pendant performance: Noter confiance et participation collaborative","Évaluer intégration créative de tous apprentissages de l''unité"]}',1,'Plan détaillé avec supports visuels',1756911653576,1757594654158,1,'fr','Français (Immersion)','{"pourDifficultés":["Participation par gestes plutôt que chant","Répétition de mots-clés seulement","Accompagnement instrumental simple","Encouragement sans pression performance"],"pourAvancés":["Leadership dans enseignement aux camarades","Création de couplets additionnels","Accompagnement instrumental plus complexe","Performance solo pour démonstration"],"pourLangue":["Focus sur rythme et mélodie avant paroles parfaites","Acceptation approximations phonetiques","Connection avec musique de culture d''origine","Support gestuel maximal"],"pourPEI":["Adaptation selon capacités sensorielles et de traitement","Participation observateur si nécessaire","Volume et stimulation ajustés","Expression créative alternative si chant difficile"]}','{"vocabulary":["mot","phrase","histoire","lire","écrire"],"visualSupports":["Paroles avec images vocabulaire, gestes musicaux, expressions de joie musicale","Paroles affichées, cartes gestuelles, modélage expressions musicales joyeuses","Gestes d''encouragement musical, expressions de fierté artistique"],"movementBreaks":["Marcher en syllabant notre nom : Ma-rie, Paul, etc. en tapant dans nos mains (2 minutes)","Répéter des comptines avec gestes : ''Tête, épaules, genoux et pieds'' (2 minutes)","Faire des gestes de marionnettes pour raconter notre histoire (3 minutes)","Étirer nos doigts et mains d''écrivains : ouvrir, fermer, tourner (2 minutes)","Dire au revoir avec tout notre corps : mains, têtes, pieds (2 minutes)","Faire une révérence à nos nouvelles connaissances (1 minute)"]}',NULL,NULL,NULL,NULL,'{"questions":["Les élèves ont-ils atteint les objectifs?","Quelles adaptations étaient nécessaires?","Que ferais-je différemment la prochaine fois?"]}',NULL,'',1,19,'core',0);
INSERT INTO ETFOLessonPlan VALUES('cmf43u40900mtvj9tt1w9at9t',23,'Exposition des familles','cmf43u3zq00lpvj9tnsaml469',1763481600000,45,'Préparation du musée familial: ''Nous créons un musée de nos familles!'' Transformation classe en galerie d''exposition célébrant tout apprentissage d''unité.','Exposition familiale culminante: Élèves deviennent guides musée, présentant fierté parcours d''apprentissage. Célébration comprehensive de croissance linguistique et culturelle.','Réflexion culminante collective: Élèves font tour de leur exposition et déclarent avec fierté: ''J''ai appris beaucoup sur les familles!'' Célébration finale unité.','Maîtriser la famille et ses membres; Utiliser les rôles familiaux avec respect; Développer l''expression écrite par des activités langagières variées','["Matériel de classe"]',NULL,'Exposition des familles','Préparation du musée familial: ''Nous créons un musée de nos familles!'' Transformation classe en galerie d''exposition célébrant tout apprentissage d''unité.','Exposition familiale culminante: Élèves deviennent guides musée, présentant fierté parcours d''apprentissage. Célébration comprehensive de croissance linguistique et culturelle.','Réflexion culminante collective: Élèves font tour de leur exposition et déclarent avec fierté: ''J''ai appris beaucoup sur les familles!'' Célébration finale unité.','Maîtriser la famille et ses membres; Utiliser les rôles familiaux avec respect; Développer l''expression écrite par des activités langagières variées',NULL,NULL,NULL,'formative','{"observable":["Élève démontre fierté de parcours d''apprentissage complet","Élève peut identifier accomplissements et croissance personnelle","Élève participe à célébration collective avec joie","Élève intègre et synthétise apprentissages de toute l''unité"],"checkpoints":["Pendant exposition: Observer fierté authentique et ownership des apprentissages","Pendant réflexion: Noter capacité à articuler croissance et apprentissages","Évaluation sommative finale: accomplissement objectifs unité et préparation suite parcours"]}',1,'Plan détaillé avec supports visuels',1756911653577,1757594654159,1,'fr','Français (Immersion)','{"pourDifficultés":["Célébrer chaque contribution sans comparaison","Permettre rôle observateur avec validation","Reconnaissance de progrès individuels uniques","Support pour identifier leurs accomplissements personnels"],"pourAvancés":["Rôle leadership comme guide d''exposition","Synthèse et connexions entre apprentissages","Aide à animer réflexions de camarades","Planification extensions futures possibles"],"pourLangue":["Célébration spéciale de croissance linguistique","Reconnaissance de bilinguisme comme atout","Permettre fierté dans toutes langues maîtrisées","Support pour expression dans langue la plus confortable"],"pourPEI":["Célébration adaptée aux capacités individuelles","Reconnaissance de contributions uniques","Support pour participation confortable","Validation de tous accomplissements sans comparaison"]}','{"vocabulary":["mot","phrase","histoire","lire","écrire"],"visualSupports":["Signalisation d''exposition, guide de parcours, ambiance célébratoire","Exposition complète travaux, documentation photographique respectueuse, ambiance musée","Vue panoramique de tous accomplissements, expressions de fierté collective"],"movementBreaks":["Répéter des comptines avec gestes : ''Tête, épaules, genoux et pieds'' (2 minutes)","Former des lettres dans l''air avec nos doigts : A, B, C (3 minutes)","Faire des gestes de marionnettes pour raconter notre histoire (3 minutes)","Marcher sur place en récitant l''alphabet lentement (2 minutes)","Ranger nos idées : faire semblant de mettre nos pensées dans une boîte (2 minutes)","Dire au revoir avec tout notre corps : mains, têtes, pieds (2 minutes)"]}',NULL,NULL,NULL,NULL,'{"questions":["Les élèves ont-ils atteint les objectifs?","Quelles adaptations étaient nécessaires?","Que ferais-je différemment la prochaine fois?"]}',NULL,'',1,20,'core',1);
INSERT INTO ETFOLessonPlan VALUES('cmf43u40b00mxvj9t6eqtw308',23,'L''automne arrive!','cmf43u40a00mvvj9tk4l6dmf7',1758898800000,45,'Chanson d''accueil avec gestes : ''Bonjour l''automne!'' Les élèves se rassemblent au tapis et chantent en mimant les feuilles qui tombent et le vent qui souffle.','Exploration guidée : Sortie à l''extérieur (ou observation par la fenêtre) pour identifier les signes d''automne. Les élèves nomment ce qu''ils voient en français avec aide. Retour en classe pour créer un mur de mots illustré ''L''automne arrive!'' avec dessins et étiquettes.','Cercle de partage : Chaque élève partage un mot qu''il a appris ou montre quelque chose qu''il a dessiné. Révision du vocabulaire avec répétition chorale et gestes. Chanson de fermeture : ''Au revoir automne, à demain!''','Explorer les changements d''automne dans l''environnement; Utiliser les observations automnales; Développer la conscience phonologique par des activités langagières variées','["Tapis de rassemblement pour 25 élèves","Images d''automne collées au tableau","Feuilles d''automne réelles (ramassées dehors)","Tableau blanc ou papier grand format","Marqueurs de couleur (orange, rouge, jaune, brun)","Étiquettes pré-écrites : automne, feuilles, orange","Crayons et papier pour dessins individuels (25 copies)","Bac pour collecter feuilles d''automne","Dessins des élèves","Mur de mots créé pendant l''activité principale","Feuilles d''automne collectées"]',NULL,'L''automne arrive!','Chanson d''accueil avec gestes : ''Bonjour l''automne!'' Les élèves se rassemblent au tapis et chantent en mimant les feuilles qui tombent et le vent qui souffle.','Exploration guidée : Sortie à l''extérieur (ou observation par la fenêtre) pour identifier les signes d''automne. Les élèves nomment ce qu''ils voient en français avec aide. Retour en classe pour créer un mur de mots illustré ''L''automne arrive!'' avec dessins et étiquettes.','Cercle de partage : Chaque élève partage un mot qu''il a appris ou montre quelque chose qu''il a dessiné. Révision du vocabulaire avec répétition chorale et gestes. Chanson de fermeture : ''Au revoir automne, à demain!''','Explorer les changements d''automne dans l''environnement; Utiliser les observations automnales; Développer la conscience phonologique par des activités langagières variées',NULL,NULL,NULL,'formative','{"observable":["Reconnaît et nomme ''automne'', ''feuilles'', ''orange'' avec ou sans support visuel","Participe aux activités de groupe avec engagement","Démontre compréhension par gestes, dessins ou mots","Utilise le nouveau vocabulaire dans des contextes similaires"],"checkpoints":["Pendant l''exploration : observer qui identifie les signes d''automne","Pendant le dessin : noter qui peut associer les mots aux images","Pendant le partage : écouter pour l''usage spontané du vocabulaire"]}',1,'Plan détaillé avec supports visuels',1756911653579,1757594654163,1,'fr','Français (Immersion)','{"pourDifficultés":["Fournir des images avec mots écrits dessus","Permettre de montrer au lieu de dire","Travailler en petit groupe avec plus de soutien","Utiliser des objets concrets et manipulation"],"pourAvancés":["Encourager à utiliser des phrases complètes en français","Demander de décrire pourquoi les feuilles changent de couleur","Rôle d''aide-enseignant pour modéliser aux autres","Ajouter du vocabulaire supplémentaire (brun, doré)"],"pourLangue":["Permettre l''usage de L1 pour expliquer puis répéter en français","Pairs tutors avec élèves francophones","Plus de supports visuels et gestes","Répétition fréquente et modélisation claire"],"pourPEI":["Adapter selon objectifs individuels du PEI","Soutien individuel si nécessaire","Outils alternatifs de communication si requis","Modification de l''environnement selon les besoins sensoriels"]}','{"vocabulary":["automne","feuilles","orange"],"visualSupports":["Affichage de photos d''automne avec les mots ''automne'', ''feuilles'', ''orange'' écrits en gros sous chaque image","Cartes-images plastifiées montrant les couleurs d''automne, les arbres avec/sans feuilles, le vocabulaire écrit en gros caractères","Affichage final du mur de mots avec dessins et étiquettes, gestes pour chaque mot de vocabulaire"],"movementBreaks":["Gestes pour imiter les feuilles qui tombent (bras qui bougent)","Mouvements pour représenter le vent (corps qui balance)","Marcher dehors pour observer (si possible)","Se lever pour coller les étiquettes au mur","Pause danse : imiter les feuilles qui tombent","Se lever pour montrer les dessins","Gestes accompagnant la chanson de fermeture"]}',NULL,NULL,NULL,NULL,'{"questions":["Les élèves ont-ils atteint les objectifs?","Quelles adaptations étaient nécessaires?","Que ferais-je différemment la prochaine fois?"]}',NULL,'',1,1,'core',1);
INSERT INTO ETFOLessonPlan VALUES('cmf43u40c00mzvj9t33ws43dv',23,'Les feuilles dansent','cmf43u40a00mvvj9tk4l6dmf7',1759158000000,45,'Révision des mots d''automne avec une danse des feuilles. Les élèves tiennent des feuilles de papier colorées (rouge, jaune, orange) et dansent en écoutant ''Les feuilles d''automne tombent, tombent, tombent...''','Station d''exploration des couleurs : 3 stations rotatives (1) Tri des feuilles par couleurs avec verbalisation, (2) Peinture avec éponges pour créer des arbres d''automne rouge/jaune, (3) Jeu de mouvement ''Jacques a dit'' avec actions des feuilles (tomber, danser, voler).','Galerie d''art des feuilles : Les élèves présentent leurs peintures et nomment les couleurs utilisées. Chanson finale ''Rouge, jaune, orange - les couleurs d''automne!'' avec gestes pour chaque couleur.','Identifier le concept de les feuilles; Utiliser les observations automnales; Développer la conscience phonologique par des activités langagières variées','["Feuilles de papier coloré (rouge, jaune, orange) - 25 copies","Musique douce d''automne ou chanson enregistrée","Haut-parleur/lecteur de musique","Affichage des couleurs avec mots écrits","Vraies feuilles d''automne de différentes couleurs","3 bacs de tri étiquetés rouge, jaune, orange","Peinture rouge et jaune avec éponges (25 sets)","Papier blanc format lettre (25 copies)","Tabliers ou vieux vêtements pour peinture","Cartes d''instructions visuelles pour chaque station","Peintures séchées des élèves","Espace pour exposition temporaire","Paroles de la chanson affichées avec couleurs"]',NULL,'Les feuilles dansent','Révision des mots d''automne avec une danse des feuilles. Les élèves tiennent des feuilles de papier colorées (rouge, jaune, orange) et dansent en écoutant ''Les feuilles d''automne tombent, tombent, tombent...''','Station d''exploration des couleurs : 3 stations rotatives (1) Tri des feuilles par couleurs avec verbalisation, (2) Peinture avec éponges pour créer des arbres d''automne rouge/jaune, (3) Jeu de mouvement ''Jacques a dit'' avec actions des feuilles (tomber, danser, voler).','Galerie d''art des feuilles : Les élèves présentent leurs peintures et nomment les couleurs utilisées. Chanson finale ''Rouge, jaune, orange - les couleurs d''automne!'' avec gestes pour chaque couleur.','Identifier le concept de les feuilles; Utiliser les observations automnales; Développer la conscience phonologique par des activités langagières variées',NULL,NULL,NULL,'formative','{"observable":["Identifie et nomme les couleurs rouge, jaune avec support visuel","Démontre compréhension de ''tomber'' par mouvement ou geste","Participe aux activités de tri et création avec engagement","Utilise le vocabulaire de couleurs dans le contexte des feuilles"],"checkpoints":["Station de tri : observer la précision de classification des couleurs","Pendant la peinture : écouter l''usage spontané des mots de couleur","Présentation finale : noter l''aisance avec le nouveau vocabulaire"]}',1,'Plan détaillé avec supports visuels',1756911653580,1757594654164,1,'fr','Français (Immersion)','{"pourDifficultés":["Réduire le nombre de couleurs à 2 (rouge et jaune)","Fournir des modèles visuels à copier","Assistance individuelle pour le tri des couleurs","Mouvements adaptés selon capacités physiques"],"pourAvancés":["Ajouter des nuances (rouge foncé/clair, jaune doré)","Encourager des phrases descriptives complètes","Rôle de leader dans les stations","Créer des motifs complexes avec les couleurs"],"pourLangue":["Étiquettes couleurs en L1 et français côte à côte","Démonstration répétée des actions","Partenariat avec élève francophone","Plus de temps pour traitement et réponse"],"pourPEI":["Modifications selon objectifs PEI individuels","Outils adaptatifs pour peinture si nécessaire","Environnement sensoriel ajusté","Support de communication alternatif"]}','{"vocabulary":["rouge","jaune","tomber"],"visualSupports":["Cartes de couleurs géantes au mur (rouge, jaune, orange) avec les mots écrits clairement, démonstration des mouvements par l''enseignant","Instructions illustrées à chaque station, modèles de peintures terminées, cartes de mouvements avec flèches et images","Exposition des œuvres avec étiquettes de couleurs, gestes standardisés pour chaque couleur enseignés"],"movementBreaks":["Danse avec feuilles - mouvements libres","Imiter les feuilles qui tombent lentement puis rapidement","Transition entre stations en marchant comme des feuilles qui tombent","Station de jeu de mouvement intégrée","Étirements en imitant les branches d''arbres","Se déplacer pour voir les œuvres des autres","Gestes de la chanson finale avec tout le corps"]}',NULL,NULL,NULL,NULL,'{"questions":["Les élèves ont-ils atteint les objectifs?","Quelles adaptations étaient nécessaires?","Que ferais-je différemment la prochaine fois?"]}',NULL,'',1,2,'core',1);
INSERT INTO ETFOLessonPlan VALUES('cmf43u40d00n1vj9twavj9c6s',23,'Les arbres en automne','cmf43u40a00mvvj9tk4l6dmf7',1759244400000,45,'Jeu de devinettes : L''enseignant(e) décrit un arbre (''Je vois quelque chose de grand avec des branches'') et les élèves devinent. Révision kinesthésique : les élèves deviennent des arbres avec leurs bras comme branches.','Exploration d''arbres réels : Observation guidée par la fenêtre ou sortie courte pour identifier les parties d''un arbre. Activité de dessin détaillé : créer un arbre d''automne en étiquetant les parties. Jeu de comparaison : trier des images d''arbres par taille (grand/petit).','Exposition d''arbres : Les élèves présentent leurs dessins d''arbres en utilisant le vocabulaire appris. Jeu final ''Grand ou petit?'' avec gestes corporels pour renforcer les concepts de taille.','Reconnaître les changements d''automne dans l''environnement; Utiliser les observations automnales; Développer la conscience phonologique par des activités langagières variées','["Images d''arbres de différentes tailles","Espace libre pour mouvement","Cartes de vocabulaire : arbre, branches, grand","Papier de dessin (25 copies)","Crayons de couleur et crayons à mine","Images d''arbres variés pour tri (grand/petit)","Étiquettes pré-écrites : arbre, branches, grand, petit","Colle bâton (assez pour la classe)","Jumelles jouet ou loupes pour observation (optionnel)","Dessins terminés des élèves","Espace pour mini-exposition","Cartes de révision vocabulaire"]',NULL,'Les arbres en automne','Jeu de devinettes : L''enseignant(e) décrit un arbre (''Je vois quelque chose de grand avec des branches'') et les élèves devinent. Révision kinesthésique : les élèves deviennent des arbres avec leurs bras comme branches.','Exploration d''arbres réels : Observation guidée par la fenêtre ou sortie courte pour identifier les parties d''un arbre. Activité de dessin détaillé : créer un arbre d''automne en étiquetant les parties. Jeu de comparaison : trier des images d''arbres par taille (grand/petit).','Exposition d''arbres : Les élèves présentent leurs dessins d''arbres en utilisant le vocabulaire appris. Jeu final ''Grand ou petit?'' avec gestes corporels pour renforcer les concepts de taille.','Reconnaître les changements d''automne dans l''environnement; Utiliser les observations automnales; Développer la conscience phonologique par des activités langagières variées',NULL,NULL,NULL,'formative','{"observable":["Identifie et nomme ''arbre'' et ''branches'' avec support visuel","Démontre compréhension de ''grand'' vs ''petit'' par tri ou geste","Participe activement aux observations et discussions","Inclut éléments de base dans son dessin d''arbre (tronc, branches)"],"checkpoints":["Pendant observation : noter qui identifie les parties correctement","Pendant dessin : observer l''inclusion du vocabulaire appris","Pendant présentation : écouter l''usage approprié des nouveaux mots"]}',1,'Plan détaillé avec supports visuels',1756911653581,1757594654165,1,'fr','Français (Immersion)','{"pourDifficultés":["Gabarits d''arbres à tracer pour le dessin","Images avec moins de détails pour simplifier l''observation","Travail en petit groupe avec soutien supplémentaire","Focus sur vocabulaire de base : arbre, grand seulement"],"pourAvancés":["Ajouter vocabulaire enrichi (tronc, racines, écorce)","Dessiner plusieurs types d''arbres différents","Créer des descriptions complètes des arbres observés","Rechercher différents types d''arbres sur le terrain de l''école"],"pourLangue":["Étiquettes bilingues pour supports visuels","Plus de temps pour traitement et réponse","Modélisation répétée des gestes et mots","Partenariat avec élève francophone fort"],"pourPEI":["Adaptations selon besoins individuels du PEI","Outils de dessin alternatifs si difficultés motrices","Environnement d''apprentissage ajusté","Objectifs modifiés selon capacités"]}','{"vocabulary":["arbre","branches","grand"],"visualSupports":["Photos d''arbres avec étiquettes, démonstration physique des concepts ''grand'', ''petit'', gestes pour ''branches''","Diagramme d''arbre avec parties étiquetées au tableau, séquence d''instructions de dessin illustrées, exemples de dessins terminés","Galerie de dessins affichée, cartes récapitulatives avec mots et images, gestes de référence pour grand/petit"],"movementBreaks":["Imiter des arbres : se tenir debout, bras levés comme branches","Grandir lentement de petit à grand arbre","Sortie courte pour observation (si météo permet)","Se déplacer pour coller étiquettes sur dessins","Pause ''grandir comme un arbre'' - mouvement lent de bas en haut","Circuler pour voir les dessins des autres","Gestes corporels pour grand (étirement) et petit (accroupi)"]}',NULL,NULL,NULL,NULL,'{"questions":["Les élèves ont-ils atteint les objectifs?","Quelles adaptations étaient nécessaires?","Que ferais-je différemment la prochaine fois?"]}',NULL,'',1,3,'core',1);
INSERT INTO ETFOLessonPlan VALUES('cmf43u40e00n3vj9ttmx9k2r9',23,'Il fait frais!','cmf43u40a00mvvj9tk4l6dmf7',1759330800000,45,'Routine météo interactive : Observer par la fenêtre et décrire ce qu''on voit et ressent. Mime de sensations : ''Il fait frais!'' (serrer les bras), ''Le vent souffle!'' (balancer), ''Je vois des nuages'' (pointer le ciel).','Station météo active : (1) Station vêtements - associer vêtements aux conditions météo avec verbalisation, (2) Station observation - dessiner la météo d''aujourd''hui avec étiquettes, (3) Station sensorielle - sentir différents niveaux de température/air avec ventilateur et expérimenter les sensations ''frais''.','Bulletin météo de classe : Les élèves présentent leurs dessins météo en utilisant les nouveaux mots. Création collective d''un bulletin météo chanté : ''Aujourd''hui il fait frais, le vent souffle, je vois des nuages!''','Exprimer le concept de il fait; Utiliser les observations automnales; Développer la conscience phonologique par des activités langagières variées','["Grande fenêtre ou espace pour voir dehors","Cartes météo avec pictogrammes","Thermomètre géant en carton","Vêtements d''automne pour démonstration","Vêtements d''automne variés (chandails, vestes, foulards) - 20-25 pièces","Images de conditions météo pour association","Papier et crayons pour dessin météo (25 copies)","Étiquettes pré-écrites : frais, vent, nuages","Petit ventilateur portable pour simulation du vent","Bouteille d''eau froide et tiède pour comparaisons de température","Dessins météo des élèves","Grand tableau ou espace d''affichage","Microphone jouet pour bulletin météo (optionnel)","Paroles de la chanson météo affichées"]',NULL,'Il fait frais!','Routine météo interactive : Observer par la fenêtre et décrire ce qu''on voit et ressent. Mime de sensations : ''Il fait frais!'' (serrer les bras), ''Le vent souffle!'' (balancer), ''Je vois des nuages'' (pointer le ciel).','Station météo active : (1) Station vêtements - associer vêtements aux conditions météo avec verbalisation, (2) Station observation - dessiner la météo d''aujourd''hui avec étiquettes, (3) Station sensorielle - sentir différents niveaux de température/air avec ventilateur et expérimenter les sensations ''frais''.','Bulletin météo de classe : Les élèves présentent leurs dessins météo en utilisant les nouveaux mots. Création collective d''un bulletin météo chanté : ''Aujourd''hui il fait frais, le vent souffle, je vois des nuages!''','Exprimer le concept de il fait; Utiliser les observations automnales; Développer la conscience phonologique par des activités langagières variées',NULL,NULL,NULL,'formative','{"observable":["Associe sensation ''frais'' avec geste ou expression appropriée","Identifie ''vent'' et ''nuages'' visuellement ou par description","Fait des connexions appropriées vêtements-météo","Utilise vocabulaire météo dans contexte approprié"],"checkpoints":["Station vêtements : observer précision des associations météo-vêtements","Station dessin : noter inclusion du vocabulaire dans représentations","Bulletin météo : écouter usage naturel et approprié des nouveaux termes"]}',1,'Plan détaillé avec supports visuels',1756911653582,1757594654166,1,'fr','Français (Immersion)','{"pourDifficultés":["Focus sur un seul concept météo à la fois","Plus d''expériences sensorielles concrètes","Images très simples et claires pour association","Assistance individuelle pour dessins et étiquetage"],"pourAvancés":["Ajouter vocabulaire météo enrichi (nuageux, venteux, frisquet)","Prédictions météo simples pour demain","Descriptions météo en phrases complètes","Recherche sur pourquoi il fait plus frais en automne"],"pourLangue":["Comparaisons avec météo de pays d''origine","Mots météo en L1 et français côte à côte","Plus de supports visuels et expériences tactiles","Temps supplémentaire pour associations conceptuelles"],"pourPEI":["Adaptations sensorielles selon besoins individuels","Modifications des matériaux tactiles si sensibilités","Objectifs simplifiés selon capacités","Support additionnel pour concepts abstraits"]}','{"vocabulary":["frais","vent","nuages"],"visualSupports":["Cartes météo colorées avec mots et images, gestes standardisés pour chaque condition météo, photos de nuages différents","Instructions illustrées pour chaque station, modèles de dessins météo, diagramme de vêtements étiquetés","Gallery de dessins météo affichée, paroles avec images météo intégrées, gestes de révision pour chaque mot"],"movementBreaks":["Gestes météo : serrer les bras pour ''frais''","Balancer comme le vent","Pointer et observer le ciel","Rotation entre stations avec marche ''météo'' (marcher contre le vent, etc.)","Pause étirements en imitant des nuages qui bougent","Essayer les vêtements (mouvement naturel)","Présentation debout avec gestes","Mouvement de la chanson météo avec tout le corps"]}',NULL,NULL,NULL,NULL,'{"questions":["Les élèves ont-ils atteint les objectifs?","Quelles adaptations étaient nécessaires?","Que ferais-je différemment la prochaine fois?"]}',NULL,'',1,4,'core',1);
INSERT INTO ETFOLessonPlan VALUES('cmf43u40f00n5vj9tcfnwuqwi',23,'Les animaux se préparent','cmf43u40a00mvvj9tk4l6dmf7',1759417200000,45,'Jeu de mime animalier : L''enseignant(e) mime un écureuil qui ramasse des noix, puis un oiseau qui bat des ailes. Les élèves devinent et imitent. Introduction du concept ''se préparer pour l''hiver'' avec gestes de rangement et préparation.','Histoire interactive des animaux : Lecture d''une histoire simple sur les animaux qui se préparent, avec participation des élèves (bruitages, mouvements). Création d''un livre de classe : chaque élève dessine un animal qui se prépare et explique comment. Jeu de correspondance : associer animaux et leurs préparations d''automne.','Présentation du livre de classe terminé : Lecture collective de ''Notre livre des animaux qui se préparent''. Chanson/comptine finale avec mouvements : ''L''écureuil ramasse, l''oiseau s''envole, tous se préparent pour l''hiver qui arrive!''','Décrire les animaux et leurs besoins; Utiliser les caractéristiques des êtres vivants; Développer le vocabulaire français par des activités langagières variées','["Images d''animaux d''automne (écureuil, oiseau, ours, etc.)","Vraies noix ou images de noix","Espace libre pour mouvements","Cartes de vocabulaire avec images d''animaux","Livre d''histoire simple sur animaux d''automne (ou histoire créée)","Papier pour livre de classe (25 copies)","Crayons de couleur et crayons réguliers","Cartes d''association animaux-préparations","Images de nourritures d''animaux (noix, graines, etc.)","Agrafeuse pour assembler le livre de classe","Livre de classe assemblé avec dessins des élèves","Espace pour rassemblement circulaire","Paroles de la chanson écrites avec pictogrammes"]',NULL,'Les animaux se préparent','Jeu de mime animalier : L''enseignant(e) mime un écureuil qui ramasse des noix, puis un oiseau qui bat des ailes. Les élèves devinent et imitent. Introduction du concept ''se préparer pour l''hiver'' avec gestes de rangement et préparation.','Histoire interactive des animaux : Lecture d''une histoire simple sur les animaux qui se préparent, avec participation des élèves (bruitages, mouvements). Création d''un livre de classe : chaque élève dessine un animal qui se prépare et explique comment. Jeu de correspondance : associer animaux et leurs préparations d''automne.','Présentation du livre de classe terminé : Lecture collective de ''Notre livre des animaux qui se préparent''. Chanson/comptine finale avec mouvements : ''L''écureuil ramasse, l''oiseau s''envole, tous se préparent pour l''hiver qui arrive!''','Décrire les animaux et leurs besoins; Utiliser les caractéristiques des êtres vivants; Développer le vocabulaire français par des activités langagières variées',NULL,NULL,NULL,'formative','{"observable":["Identifie et nomme ''écureuil'' et ''oiseau'' avec support visuel","Démontre compréhension de ''se préparer'' par actions ou explications simples","Associe correctement animaux et leurs comportements d''automne","Participe activement aux imitations et créations"],"checkpoints":["Pendant l''histoire : noter qui fait des connexions appropriées","Pendant le dessin : observer qui peut expliquer ce que fait son animal","Pendant la présentation : écouter pour usage approprié du nouveau vocabulaire"]}',1,'Plan détaillé avec supports visuels',1756911653583,1757594654167,1,'fr','Français (Immersion)','{"pourDifficultés":["Focus sur un seul animal à la fois (écureuil OU oiseau)","Dessins très simples avec étiquettes pré-faites","Plus de support pour tenir crayons et dessiner","Associations visuelles très claires (une image = une action)"],"pourAvancés":["Ajouter plus d''animaux (ours, marmotte, castor)","Encourager descriptions complètes des préparations","Rechercher d''autres comportements d''animaux en automne","Créer mini-histoire personnelle avec animal choisi"],"pourLangue":["Images avec mots en L1 et français","Plus de démonstrations physiques des concepts","Partenariat avec élève francophone pour explication","Connexions avec animaux de pays d''origine si pertinent"],"pourPEI":["Adaptations selon objectifs individuels du PEI","Matériaux de dessin alternatifs si difficultés motrices","Support supplémentaire pour concepts abstraits","Participation modifiée aux activités de mouvement"]}','{"vocabulary":["écureuil","oiseau","préparer"],"visualSupports":["Grandes photos d''animaux avec leurs noms écrits, séquences illustrées d''animaux se préparant (écureuil avec noix, oiseaux qui migrent)","Illustrations de l''histoire projetées ou affichées, exemples de dessins d''animaux avec leurs préparations, cartes de correspondance claires et colorées","Livre de classe avec dessins visibles pour tous, cartes de révision des animaux et actions, gestes de la chanson modélisés"],"movementBreaks":["Mimer l''écureuil : ramasser et cacher des noix","Mimer l''oiseau : battre des ailes, regarder au loin","Gestes pour ''se préparer'' : organiser, ranger, planifier","Participation physique pendant l''histoire (mouvements d''animaux)","Se lever pour contribuer au livre de classe collectif","Pause ''migration'' : marcher en formation comme des oiseaux","Gestes de la chanson : actions d''animaux intégrées","Applaudissements pour célébrer le livre créé ensemble"]}',NULL,NULL,NULL,NULL,'{"questions":["Les élèves ont-ils atteint les objectifs?","Quelles adaptations étaient nécessaires?","Que ferais-je différemment la prochaine fois?"]}',NULL,'',1,5,'core',1);
INSERT INTO ETFOLessonPlan VALUES('cmf43u40g00n7vj9ts5qmol4y',23,'Première histoire d''automne','cmf43u40a00mvvj9tk4l6dmf7',1759503600000,45,'Cercle d''écoute : Les élèves s''assoient confortablement pendant que l''enseignant(e) introduit l''heure du conte avec des gestes pour ''écouter'' (main à l''oreille) et ''regarder'' (pointer les yeux). Révision rapide du vocabulaire d''automne appris.','Lecture interactive d''une histoire d''automne simple : L''enseignant(e) lit en montrant les images, fait des pauses pour questions/prédictions, encourage les élèves à participer avec gestes et sons. Après la lecture : discussion guidée sur l''histoire, séquençage d''images de l''histoire, et début d''une création collective d''histoire de classe.','Réflexion sur l''histoire : Les élèves partagent leur partie préférée en montrant une image ou en faisant un geste. Préparation pour demain : ''Demain, nous continuons notre histoire de classe!'' Chanson de fermeture sur l''écoute des histoires.','Lire les changements d''automne dans l''environnement; Raconter les observations automnales; Développer le vocabulaire français par la narration','["Tapis ou coussins pour cercle confortable","Livre d''histoire d''automne illustré","Cartes de gestes pour écouter/regarder","Affichage du vocabulaire d''automne précédent","Histoire d''automne appropriée (livre ou histoire créée)","Images séquentielles de l''histoire plastifiées","Tableau de flanelle ou support magnétique","Papier grand format pour histoire de classe","Marqueurs colorés","Cartes de questions simples (Qui? Quoi? Où?)","Images de l''histoire pour sélection par élèves","Début d''histoire de classe créée","Paroles de chanson d''histoire"]',NULL,'Première histoire d''automne','Cercle d''écoute : Les élèves s''assoient confortablement pendant que l''enseignant(e) introduit l''heure du conte avec des gestes pour ''écouter'' (main à l''oreille) et ''regarder'' (pointer les yeux). Révision rapide du vocabulaire d''automne appris.','Lecture interactive d''une histoire d''automne simple : L''enseignant(e) lit en montrant les images, fait des pauses pour questions/prédictions, encourage les élèves à participer avec gestes et sons. Après la lecture : discussion guidée sur l''histoire, séquençage d''images de l''histoire, et début d''une création collective d''histoire de classe.','Réflexion sur l''histoire : Les élèves partagent leur partie préférée en montrant une image ou en faisant un geste. Préparation pour demain : ''Demain, nous continuons notre histoire de classe!'' Chanson de fermeture sur l''écoute des histoires.','Lire les changements d''automne dans l''environnement; Raconter les observations automnales; Développer le vocabulaire français par la narration',NULL,NULL,NULL,'formative','{"observable":["Démontre comportements d''écoute appropriés pendant l''histoire","Répond aux questions sur l''histoire par gestes, mots, ou images","Participe aux activités de séquençage avec support","Montre compréhension de base de l''histoire lue"],"checkpoints":["Pendant la lecture : observer l''engagement et les réactions appropriées","Pendant les questions : noter qui peut identifier éléments de base","Pendant le séquençage : observer la logique dans l''organisation des images"]}',1,'Plan détaillé avec supports visuels',1756911653584,1757594654168,1,'fr','Français (Immersion)','{"pourDifficultés":["Histoire plus courte avec images très claires","Questions avec choix de réponses visuelles","Plus de temps pour traiter les informations","Support individuel pour compréhension"],"pourAvancés":["Questions plus complexes sur l''histoire (pourquoi, comment)","Encourager à prédire la suite","Rôle d''aide pour expliquer aux autres","Connexions avec d''autres histoires connues"],"pourLangue":["Images avec vocabulaire en L1 et français","Plus de répétition des concepts clés","Partenariat pour soutien en compréhension","Gestes et expressions faciales accentués"],"pourPEI":["Adaptations selon objectifs PEI individuels","Position assise confortable adaptée aux besoins","Supports sensoriels si nécessaire","Participation modifiée selon capacités"]}','{"vocabulary":["histoire","écouter","regarder"],"visualSupports":["Cartes de comportements d''écoute (yeux qui regardent, oreilles qui écoutent), couverture du livre montrée, gestes clairs modélisés","Images de l''histoire clairement visibles, séquence d''événements illustrée, début d''histoire de classe avec images","Récapitulatif visuel de l''histoire lue, images pour soutenir les réflections des élèves"],"movementBreaks":["Gestes pour ''écouter'' et ''regarder''","S''installer confortablement dans le cercle d''écoute","Gestes et mouvements pendant la lecture interactive","Se lever pour placer images en séquence","Pause étirement au milieu de l''activité principale","Gestes pour montrer les parties préférées","Chanson avec mouvements simples"]}',NULL,NULL,NULL,NULL,'{"questions":["Les élèves ont-ils atteint les objectifs?","Quelles adaptations étaient nécessaires?","Que ferais-je différemment la prochaine fois?"]}',NULL,'',1,6,'core',1);
INSERT INTO ETFOLessonPlan VALUES('cmf43u40h00n9vj9tpcprn0ff',23,'Les personnages d''automne','cmf43u40a00mvvj9tk4l6dmf7',1759762800000,45,'Jeu de personnages : L''enseignant(e) se déguise ou utilise une voix différente pour présenter des personnages d''automne (petit écureuil gentil, grand arbre sage). Les élèves devinent et décrivent les personnages avec les mots ''petit'' et ''gentil''.','Atelier de création de personnages : Les élèves créent leurs propres personnages d''automne en dessinant et en choisissant des caractéristiques (petit/grand, gentil/méchant). Théâtre de personnages : présentation des créations avec jeu de rôle simple et description des traits de caractère.','Galerie de personnages : Tour de la classe pour admirer tous les personnages créés. Chaque élève présente brièvement son personnage en utilisant les mots appris. Vote amical pour différentes catégories (plus gentil, plus coloré, etc.).','Écrire les changements d''automne dans l''environnement; Utiliser les observations automnales; Développer le vocabulaire français par des activités langagières variées','["Accessoires simples (chapeau, écharpe, oreilles d''écureuil)","Images de personnages d''histoires d''automne","Cartes de vocabulaire : personnage, petit, gentil","Miroir pour montrer les expressions","Papier de dessin (25 copies)","Crayons de couleur et marqueurs","Autocollants de traits (sourires, formes)","Bâtonnets de bricolage pour marionnettes","Cartes de traits de caractère illustrées","Espace pour mini-théâtre","Personnages créés par les élèves","Espace d''exposition temporaire","Certificats de reconnaissance simples"]',NULL,'Les personnages d''automne','Jeu de personnages : L''enseignant(e) se déguise ou utilise une voix différente pour présenter des personnages d''automne (petit écureuil gentil, grand arbre sage). Les élèves devinent et décrivent les personnages avec les mots ''petit'' et ''gentil''.','Atelier de création de personnages : Les élèves créent leurs propres personnages d''automne en dessinant et en choisissant des caractéristiques (petit/grand, gentil/méchant). Théâtre de personnages : présentation des créations avec jeu de rôle simple et description des traits de caractère.','Galerie de personnages : Tour de la classe pour admirer tous les personnages créés. Chaque élève présente brièvement son personnage en utilisant les mots appris. Vote amical pour différentes catégories (plus gentil, plus coloré, etc.).','Écrire les changements d''automne dans l''environnement; Utiliser les observations automnales; Développer le vocabulaire français par des activités langagières variées',NULL,NULL,NULL,'formative','{"observable":["Identifie et utilise ''personnage'', ''petit'', ''gentil'' appropriément","Crée un personnage avec caractéristiques identifiables","Décrit son personnage en utilisant le nouveau vocabulaire","Participe aux activités créatives et théâtrales"],"checkpoints":["Pendant la création : observer inclusion des traits enseignés","Pendant les présentations : écouter usage du vocabulaire de caractère","Pendant la galerie : noter reconnaissance des traits chez les autres"]}',1,'Plan détaillé avec supports visuels',1756911653585,1757594654169,1,'fr','Français (Immersion)','{"pourDifficultés":["Gabarits de personnages à colorier","Choix limités de traits (2-3 options max)","Support individuel pour création artistique","Focus sur un trait à la fois"],"pourAvancés":["Création de plusieurs personnages","Histoires courtes avec leurs personnages","Traits de caractère plus complexes","Aide aux autres élèves dans leurs créations"],"pourLangue":["Images très claires pour chaque trait","Répétition fréquente du vocabulaire","Association avec personnages familiers","Plus de temps pour expression verbale"],"pourPEI":["Adaptations selon objectifs PEI","Matériaux adaptés pour création","Participation modifiée au théâtre si nécessaire","Support pour concepts abstraits"]}','{"vocabulary":["personnage","petit","gentil"],"visualSupports":["Cartes de personnages avec caractéristiques (petit/grand, gentil/méchant), expressions faciales illustrées, gestes pour chaque adjectif","Exemples de personnages créés avec traits étiquetés, banque d''expressions et caractéristiques illustrées","Galerie organisée avec personnages affichés, étiquettes de catégories positives"],"movementBreaks":["Imiter les personnages avec voix et gestes","Montrer ''petit'' et ''grand'' avec le corps","Se lever pour présenter les personnages","Gestes et mouvements pour le mini-théâtre","Pause danse : bouger comme différents personnages","Circuler pour voir la galerie","Applaudissements pour chaque présentation"]}',NULL,NULL,NULL,NULL,'{"questions":["Les élèves ont-ils atteint les objectifs?","Quelles adaptations étaient nécessaires?","Que ferais-je différemment la prochaine fois?"]}',NULL,'',1,7,'core',1);
INSERT INTO ETFOLessonPlan VALUES('cmf43u40i00nbvj9t4mbfo55y',23,'Que se passe-t-il?','cmf43u40a00mvvj9tk4l6dmf7',1759849200000,45,'Séquence du matin : Les élèves racontent leur routine matinale en utilisant ''D''abord je me lève, puis je mange, après je me brosse les dents, maintenant je suis à l''école.'' Gestes pour chaque mot de temps introduit.','Rétablir l''ordre d''une histoire d''automne : Présenter histoire en désordre, les élèves remettent événements en séquence en utilisant les mots de temps. Création d''une histoire collective avec séquence claire. Jeu ''Que se passe-t-il après?'' avec prédictions.','Récapitulatif de l''histoire remise en ordre : Lecture finale de l''histoire séquencée avec participation des élèves pour les mots de temps. Prévision pour demain : ''Maintenant nous savons séquencer, après nous créerons nos propres histoires!''','Raconter le concept de que se; Utiliser les observations automnales; Développer le vocabulaire français par des activités langagières variées','["Cartes de routine quotidienne illustrées","Cartes de mots de temps : puis, après, maintenant","Ligne de temps simple au tableau","Horloge décorative (optionnel)","Images d''histoire d''automne en désordre (6-8 images)","Bandes de séquençage ou ligne de temps géante","Papier pour histoire collective","Marqueurs colorés","Cartes de mots de temps à placer","Images de cause-effet simples","Histoire remise en ordre par la classe","Cartes de mots de temps pour révision","Tableau de prévisions pour demain"]',NULL,'Que se passe-t-il?','Séquence du matin : Les élèves racontent leur routine matinale en utilisant ''D''abord je me lève, puis je mange, après je me brosse les dents, maintenant je suis à l''école.'' Gestes pour chaque mot de temps introduit.','Rétablir l''ordre d''une histoire d''automne : Présenter histoire en désordre, les élèves remettent événements en séquence en utilisant les mots de temps. Création d''une histoire collective avec séquence claire. Jeu ''Que se passe-t-il après?'' avec prédictions.','Récapitulatif de l''histoire remise en ordre : Lecture finale de l''histoire séquencée avec participation des élèves pour les mots de temps. Prévision pour demain : ''Maintenant nous savons séquencer, après nous créerons nos propres histoires!''','Raconter le concept de que se; Utiliser les observations automnales; Développer le vocabulaire français par des activités langagières variées',NULL,NULL,NULL,'formative','{"observable":["Utilise ''puis'', ''après'', ''maintenant'' dans contexte approprié","Place événements en ordre logique avec support","Comprend séquence temporelle basique","Participe aux activités de séquençage et prédiction"],"checkpoints":["Pendant séquençage : observer logique dans placement des images","Pendant histoire collective : noter usage des mots de temps","Pendant récapitulatif : écouter compréhension de l''ordre des événements"]}',1,'Plan détaillé avec supports visuels',1756911653586,1757594654170,1,'fr','Français (Immersion)','{"pourDifficultés":["Séquences très simples (3 étapes max)","Manipulation physique des cartes d''images","Plus de support individuel pour logique","Connexions avec expériences personnelles familières"],"pourAvancés":["Séquences plus complexes avec détails","Création de leurs propres histoires séquencées","Utilisation de tous les mots de temps en phrases","Aide aux autres pour comprendre la séquence"],"pourLangue":["Répétition fréquente des mots de temps","Gestes très clairs pour chaque concept temporel","Images avec séquences très évidentes","Plus de temps pour comprendre les relations temporelles"],"pourPEI":["Adaptations selon besoins PEI individuels","Support pour concepts abstraits de temps","Matériaux concrets pour manipulation","Objectifs simplifiés selon capacités"]}','{"vocabulary":["puis","après","maintenant"],"visualSupports":["Séquence visuelle de routine avec flèches, cartes de temps avec couleurs différentes, gestes standardisés pour chaque mot de séquence","Ligne de temps visuelle claire, numéros et flèches pour séquence, images d''histoire grandes et claires","Histoire finale bien organisée et visible, mots de temps mis en évidence en couleur"],"movementBreaks":["Mimer les actions de routine matinale","Gestes pour chaque mot de temps (pointer, continuer, présent)","Se lever pour placer images dans l''ordre","Mimer les événements de l''histoire en séquence","Pause danse : mouvements séquentiels (1-2-3)","Gestes de récapitulation pour chaque étape","Applaudissements pour le travail d''équipe accompli"]}',NULL,NULL,NULL,NULL,'{"questions":["Les élèves ont-ils atteint les objectifs?","Quelles adaptations étaient nécessaires?","Que ferais-je différemment la prochaine fois?"]}',NULL,'',1,8,'core',1);
INSERT INTO ETFOLessonPlan VALUES('cmf43u40i00ndvj9tb0vw3e85',23,'Mes mots d''automne','cmf43u40a00mvvj9tk4l6dmf7',1759935600000,45,'Jeu ''J''espère un mot...'' : L''élève dit un mot d''automne, les autres répètent puis ajoutent un nouveau. Introduction de ''mot'', ''dire'', ''répéter'' avec gestes (pointer la bouche, parler, redîre).','Centres de mots d''automne : (1) Mémoire de mots - associer images et mots écrits, (2) Création de livre personnel de mots avec dessins, (3) Théâtre de mots - mimer des mots pour que les autres devinent. Rotation entre les trois centres.','Partage de mots préférés : Chaque élève partage un mot de son carnet ou un nouveau mot appris. Chanson de récapitulatif : ''Les mots d''automne que je dis, je les répète et je souris!''','Communiquer les mots familiers; Utiliser le vocabulaire thématique en contexte; Développer la communication orale par des activités langagières variées','["Mur de mots d''automne créé précédemment","Cartes de gestes pour dire/répéter","Boule de neige/objet à passer pour prendre la parole","Jeu de mémoire avec mots d''automne (images et mots)","Carnets de mots personnels (25 copies)","Crayons et matériel de dessin","Cartes de mots à mimer","Minuteur pour rotations","Instructions illustrées pour chaque centre","Carnets de mots des élèves","Paroles de chanson illustrées","Mur de mots classé pour référence"]',NULL,'Mes mots d''automne','Jeu ''J''espère un mot...'' : L''élève dit un mot d''automne, les autres répètent puis ajoutent un nouveau. Introduction de ''mot'', ''dire'', ''répéter'' avec gestes (pointer la bouche, parler, redîre).','Centres de mots d''automne : (1) Mémoire de mots - associer images et mots écrits, (2) Création de livre personnel de mots avec dessins, (3) Théâtre de mots - mimer des mots pour que les autres devinent. Rotation entre les trois centres.','Partage de mots préférés : Chaque élève partage un mot de son carnet ou un nouveau mot appris. Chanson de récapitulatif : ''Les mots d''automne que je dis, je les répète et je souris!''','Communiquer les mots familiers; Utiliser le vocabulaire thématique en contexte; Développer la communication orale par des activités langagières variées',NULL,NULL,NULL,'formative','{"observable":["Reconnaît et utilise ''mot'', ''dire'', ''répéter'' appropriément","Démontre compréhension du vocabulaire d''automne dans les jeux","Crée un carnet de mots personnel avec éléments appropriés","Participe activement aux centres et partages de mots"],"checkpoints":["Centres de mots : observer reconnaissance et usage du vocabulaire","Carnet personnel : noter inclusion et compréhension des mots","Partage final : écouter confiance et aisance avec nouveaux mots"]}',1,'Plan détaillé avec supports visuels',1756911653587,1757594654171,1,'fr','Français (Immersion)','{"pourDifficultés":["Focus sur 5-6 mots de base seulement","Plus d''images et moins de mots écrits","Répétition supplémentaire avec support individuel","Association d''images avec chaque nouveau mot"],"pourAvancés":["Vocabulaire enrichi et mots plus complexes","Création de phrases avec les nouveaux mots","Rôle d''enseignant pour aider les autres","Recherche de mots d''automne supplémentaires"],"pourLangue":["Connexion avec mots similaires en L1 si possible","Plus de support visuel et gestuel","Répétition avec correction douce de prononciation","Temps supplémentaire pour traitement"],"pourPEI":["Adaptations selon objectifs PEI","Matériaux alternatifs pour création (autocollants, etc.)","Objectifs de vocabulaire ajustés","Support pour rétention et rappel"]}','{"vocabulary":["mot","dire","répéter"],"visualSupports":["Cartes de vocabulaire d''automne affichées, gestes standard pour chaque action verbale, modélisation claire des tours de parole","Instructions visuelles claires à chaque centre, exemples de pages de carnets terminées, cartes de mots avec images pour support","Chanson avec pictogrammes, mur de mots organisé par catégories, gestes de la chanson modélisés"],"movementBreaks":["Gestes pour ''dire'' (bouche) et ''répéter'' (geste de boucle)","Passer l''objet de parole autour du cercle","Rotation physique entre les centres","Centre théâtre intègre mouvement naturellement","Pause étirement au milieu des rotations","Gestes et mouvements de la chanson de récapitulatif","Montrer fîèrement les créations de mots"]}',NULL,NULL,NULL,NULL,'{"questions":["Les élèves ont-ils atteint les objectifs?","Quelles adaptations étaient nécessaires?","Que ferais-je différemment la prochaine fois?"]}',NULL,'',1,9,'core',1);
INSERT INTO ETFOLessonPlan VALUES('cmf43u40j00nfvj9tghecjygo',23,'Raconter ensemble','cmf43u40a00mvvj9tk4l6dmf7',1760022000000,45,'Cercle de pratique ''tour à tour'' : Passer un objet speécial, chaque élève dit ''C''est mon tour'' et ajoute une phrase à une histoire simple. Introduction des concepts ''raconter'', ''ensemble'', ''tour'' avec gestes et démonstrations.','Création d''histoire collaborative d''automne : Débuter avec une phrase («Il était une fois, en automne...»), chaque élèves ajoute une phrase à tour de rôle. L''enseignant(e) écrit/dessine l''histoire au fur et à mesure. Deuxième histoire en petits groupes avec support d''images.','Partage des histoires créées : Lecture à haute voix de l''histoire collective, puis représentants de chaque petit groupe présentent leur histoire. Célébration du travail ''ensemble'' avec applaudissements.','Exprimer le concept de raconter ensemble; Raconter les observations automnales; Développer la communication orale par la narration','["Bâton de parole ou objet speécial à passer","Images d''histoires pour inspiration","Cartes de vocabulaire : raconter, ensemble, tour","Affichage des règles de tour de parole","Papier géant pour histoire collective","Marqueurs colorés","Images d''automne pour inspiration","Papier pour histoires de petits groupes","Cartes de début d''histoire («Il était une fois...»)","Minuteur pour tours de parole","Histoire collective terminée","Histoires de petits groupes","Espace pour présentations","Certificats de ''Conteurs d''automne'' (optionnel)"]',NULL,'Raconter ensemble','Cercle de pratique ''tour à tour'' : Passer un objet speécial, chaque élève dit ''C''est mon tour'' et ajoute une phrase à une histoire simple. Introduction des concepts ''raconter'', ''ensemble'', ''tour'' avec gestes et démonstrations.','Création d''histoire collaborative d''automne : Débuter avec une phrase («Il était une fois, en automne...»), chaque élèves ajoute une phrase à tour de rôle. L''enseignant(e) écrit/dessine l''histoire au fur et à mesure. Deuxième histoire en petits groupes avec support d''images.','Partage des histoires créées : Lecture à haute voix de l''histoire collective, puis représentants de chaque petit groupe présentent leur histoire. Célébration du travail ''ensemble'' avec applaudissements.','Exprimer le concept de raconter ensemble; Raconter les observations automnales; Développer la communication orale par la narration',NULL,NULL,NULL,'formative','{"observable":["Comprend et utilise ''raconter'', ''ensemble'', ''tour'' appropriément","Respecte les tours de parole dans les activités de groupe","Contribue de manière positive aux histoires collectives","Démontre compréhension de la collaboration en narration"],"checkpoints":["Pendant histoire collective : observer respect des tours et qualité des contributions","Pendant petits groupes : noter collaboration et utilisation du vocabulaire","Pendant partage : évaluer compréhension du processus collaboratif"]}',1,'Plan détaillé avec supports visuels',1756911653588,1757594654172,1,'fr','Français (Immersion)','{"pourDifficultés":["Contribution par dessins ou gestes si mots difficiles","Support individuel pour connexion avec histoire précédente","Groupes plus petits avec plus d''aide","Prompts ou choix multiples pour inspiration"],"pourAvancés":["Encourager détails et descriptions riches","Rôle de facilitateur dans petit groupe","Connexions complexes entre événements d''histoire","Création d''histoires multiples ou plus longues"],"pourLangue":["Images pour soutenir contribution verbale","Accepter mélange de L1 et français au besoin","Partenariat avec élève francophone fort","Plus de temps pour formuler contributions"],"pourPEI":["Adaptations selon objectifs PEI","Méthodes alternatives de contribution (dessin, choix)","Soutien pour tour de parole si difficultés sociales","Environnement ajusté pour concentration"]}','{"vocabulary":["raconter","ensemble","tour"],"visualSupports":["Règles visuelles pour tours de parole, gestes pour ''ensemble'' (bras ouverts) et ''tour'' (pointer), modélisation claire du partage","Histoire écrite/dessinée en temps réel visible à tous, images d''inspiration affichées, indicateur visuel de qui a le tour","Histoires affichées pour que tous puissent voir, gestes d''encouragement et applaudissements modélisés"],"movementBreaks":["Passer l''objet de parole physiquement","Gestes pour ''ensemble'' et ''tour'' avec tout le corps","Se lever pour contribuer à l''écriture collective","Déplacements entre petits groupes","Pause gestuelle pour mimer parties de l''histoire","Applaudissements pour chaque histoire partagée","Célébration finale avec gestes de joie"]}',NULL,NULL,NULL,NULL,'{"questions":["Les élèves ont-ils atteint les objectifs?","Quelles adaptations étaient nécessaires?","Que ferais-je différemment la prochaine fois?"]}',NULL,'',1,10,'core',1);
INSERT INTO ETFOLessonPlan VALUES('cmf43u40k00nhvj9t5569krax',23,'Les sons d''automne','cmf43u40a00mvvj9tk4l6dmf7',1760108400000,45,'Jeu d''écoute : Moment de silence complet pour écouter les sons autour (dans la classe, dehors). Les élèves partagent ce qu''ils entendent. Introduction du vocabulaire avec gestes : ''bruit'' (couvrir oreilles), ''entendre'' (main à l''oreille), ''silence'' (doigt sur les lèvres).','Exploration sonore d''automne : (1) Chasse aux sons - sortie courte pour collecter et imiter sons d''automne, (2) Création d''instruments d''automne avec feuilles, noix, brindilles, (3) Orchestre d''automne - chacun joue son instrument pour créer ''symphonie d''automne''.','Concert d''automne : Présentation de la symphonie d''automne créée par la classe. Moment final de silence pour apprécier et comparer avec les bruits. Réflexion : ''Quels sons préférez-vous en automne?''','Décrire les sons et leur correspondance; Utiliser la discrimination auditive des sons; Développer la communication orale par des activités langagières variées','["Espace silencieux pour écoute","Cartes de vocabulaire sonore","Images de sources de bruits d''automne","Gestes de référence affichés","Sacs pour collecter matériaux naturels","Feuilles sèches, noix, brindilles, céréales","Contenants (boîtes, bouteilles) pour instruments","Enregistreur pour capturer sons (optionnel)","Cartes d''instructions pour fabrication d''instruments","Espace pour orchestre","Instruments d''automne créés","Espace de concert","Support pour enregistrement si désiré"]',NULL,'Les sons d''automne','Jeu d''écoute : Moment de silence complet pour écouter les sons autour (dans la classe, dehors). Les élèves partagent ce qu''ils entendent. Introduction du vocabulaire avec gestes : ''bruit'' (couvrir oreilles), ''entendre'' (main à l''oreille), ''silence'' (doigt sur les lèvres).','Exploration sonore d''automne : (1) Chasse aux sons - sortie courte pour collecter et imiter sons d''automne, (2) Création d''instruments d''automne avec feuilles, noix, brindilles, (3) Orchestre d''automne - chacun joue son instrument pour créer ''symphonie d''automne''.','Concert d''automne : Présentation de la symphonie d''automne créée par la classe. Moment final de silence pour apprécier et comparer avec les bruits. Réflexion : ''Quels sons préférez-vous en automne?''','Décrire les sons et leur correspondance; Utiliser la discrimination auditive des sons; Développer la communication orale par des activités langagières variées',NULL,NULL,NULL,'formative','{"observable":["Identifie et nomme différents ''bruits'' avec support","Démontre compréhension d''''écouter'' et ''silence'' par comportements","Participe activement aux activités d''exploration sonore","Crée et utilise instruments simples de manière appropriée"],"checkpoints":["Pendant chasse aux sons : observer identification et imitation des sons","Pendant création : noter engagement et compréhension des concepts","Pendant concert : évaluer participation et utilisation du vocabulaire"]}',1,'Plan détaillé avec supports visuels',1756911653589,1757594654173,1,'fr','Français (Immersion)','{"pourDifficultés":["Focus sur sons très distincts et familiers","Instruments pré-fabriqués ou plus simples","Plus de supports visuels pour concepts sonores","Partenariat pour activités de création"],"pourAvancés":["Identification de sons plus subtils","Création d''instruments plus complexes","Composition de mélodies ou rythmes","Rôle de chef d''orchestre"],"pourLangue":["Association sons avec mots en L1 et français","Plus d''expérience sensorielle directe","Répétition des termes avec les sons réels","Support gestuel accentué"],"pourPEI":["Adaptations selon besoins sensoriels individuels","Alternatives pour difficultés auditives","Instruments adaptés aux capacités motrices","Participation ajustée à l''orchestre"]}','{"vocabulary":["bruit","entendre","silence"],"visualSupports":["Cartes avec bruits d''automne illustrés (feuilles qui craquent, vent, oiseaux), gestes clairs pour chaque concept sonore","Instructions illustrées pour création d''instruments, exemples d''instruments terminés, notation musicale simple pour orchestre","Programme de concert simple, images des sons d''automne pour références, applaudissements illustrés"],"movementBreaks":["Gestes pour bruit, entendre, silence","Position d''écoute active (se pencher, tendre l''oreille)","Sortie de collecte (marche et exploration)","Fabrication d''instruments (manipulation fine)","Performance d''orchestre (mouvements musicaux)","Performance musicale avec mouvements","Applaudissements et célébrations"]}',NULL,NULL,NULL,NULL,'{"questions":["Les élèves ont-ils atteint les objectifs?","Quelles adaptations étaient nécessaires?","Que ferais-je différemment la prochaine fois?"]}',NULL,'',1,11,'core',1);
INSERT INTO ETFOLessonPlan VALUES('cmf43u40l00njvj9tsvuz54zn',23,'Notre histoire de classe','cmf43u40a00mvvj9tk4l6dmf7',1760454000000,45,'Révision collaborative : ''Qu''avons-nous appris sur l''automne?'' Création d''une liste collective avec tous les mots et idées. Introduction des mots ''créer'' (geste de façonner), ''dessiner'' (geste de crayon), ''notre'' (geste englobant tout le groupe).','Création collaborative du livre ''Notre Automne'' : Planification de l''histoire ensemble (personnages, événements, début-milieu-fin). Chaque élève crée une page avec dessin et phrase courte. Assembly initial du livre avec couverture décorée collectivement.','Présentation du livre en cours : Montrer la couverture créée et quelques pages terminées. Célébrer le travail collaboratif : ''Regardez ce que nous avons créé ensemble!'' Anticiper la finalisation pour la prochaine leçon.','Lire le concept de notre histoire; Raconter les observations automnales; Développer la communication orale par la narration','["Tableau ou papier géant pour liste collective","Marqueurs de couleur","Tous les travaux d''automne créés précédemment","Cartes de vocabulaire pour révision","Papier spécial pour livre (25+ pages)","Crayons de couleur, feutres, matériel artistique","Matériaux pour couverture (carton coloré, autocollants)","Guide de planification d''histoire simple","Reliure temporaire (anneaux ou agrafes)","Modèles de phrases simples","Livre en cours avec couverture et pages initiales","Espace d''exposition pour montrer le progrès","Certificats de ''Créateurs d''histoire'' temporaires"]',NULL,'Notre histoire de classe','Révision collaborative : ''Qu''avons-nous appris sur l''automne?'' Création d''une liste collective avec tous les mots et idées. Introduction des mots ''créer'' (geste de façonner), ''dessiner'' (geste de crayon), ''notre'' (geste englobant tout le groupe).','Création collaborative du livre ''Notre Automne'' : Planification de l''histoire ensemble (personnages, événements, début-milieu-fin). Chaque élève crée une page avec dessin et phrase courte. Assembly initial du livre avec couverture décorée collectivement.','Présentation du livre en cours : Montrer la couverture créée et quelques pages terminées. Célébrer le travail collaboratif : ''Regardez ce que nous avons créé ensemble!'' Anticiper la finalisation pour la prochaine leçon.','Lire le concept de notre histoire; Raconter les observations automnales; Développer la communication orale par la narration',NULL,NULL,NULL,'formative','{"observable":["Utilise ''créer'', ''dessiner'', ''notre'' dans contexte approprié","Contribue de manière positive au projet collectif","Crée une page personnelle qui s''intègre au thème d''automne","Démontre fierté du travail collaboratif accompli"],"checkpoints":["Pendant planification : observer contribution aux idées collectives","Pendant création : noter qualité et engagement dans travail personnel","Pendant présentation : évaluer compréhension du processus collaboratif"]}',1,'Plan détaillé avec supports visuels',1756911653590,1757594654174,1,'fr','Français (Immersion)','{"pourDifficultés":["Page plus simple avec dessin de base et phrase courte dictée","Collaboration avec partenaire pour création","Contribution par autocollants ou découpage si dessin difficile","Plus de temps et de soutien individuel"],"pourAvancés":["Page plus détaillée avec phrase complexe ou multiple","Rôle de coordinateur pour aider à l''assemblage","Création de page de titre ou d''index","Aide aux autres élèves dans leurs créations"],"pourLangue":["Dessin comme forme principale d''expression","Phrases très simples avec support visuel","Collaboration avec élève francophone pour phrase","Acceptation de contribution en L1 avec traduction"],"pourPEI":["Adaptations selon objectifs PEI individuels","Matériaux créatifs adaptés aux capacités motrices","Forme de contribution ajustée (tampon, collage, etc.)","Soutien pour participation au travail de groupe"]}','{"vocabulary":["créer","dessiner","notre"],"visualSupports":["Mur de mots d''automne visible, gestes clairs pour chaque nouveau terme, travaux antérieurs affichés pour inspiration","Plan d''histoire illustré au tableau, exemples de pages terminées, banque de phrases débuts pour inspiration","Livre partiellement terminé bien visible, progrès illustré visuellement, tableau de planification pour prochaine étape"],"movementBreaks":["Gestes pour créer, dessiner, notre","Se lever pour contribuer à la liste au tableau","Circuler pour travailler sur différentes parties du livre","Collaboration pour décoration de couverture","Pause étirement au milieu de l''activité créative","Circuler pour admirer le travail en cours","Applaudissements pour célébrer l''effort collectif"]}',NULL,NULL,NULL,NULL,'{"questions":["Les élèves ont-ils atteint les objectifs?","Quelles adaptations étaient nécessaires?","Que ferais-je différemment la prochaine fois?"]}',NULL,'',1,12,'core',1);
INSERT INTO ETFOLessonPlan VALUES('cmf43u40m00nlvj9tp5haabpq',23,'Révision et célébration','cmf43u40a00mvvj9tk4l6dmf7',1760540400000,45,'Cercle de fierté : Chaque élève partage quelque chose qu''il sait maintenant sur l''automne qu''il ne savait pas avant. Introduction de ''savoir'' (toucher la tête), ''apprendre'' (geste d''ouverture), ''bien'' (pouce en l''air).','Festival de jeux d''automne : Stations rotatives avec jeux de révision - (1) Charades d''automne avec tous les mots appris, (2) Bingo d''automne avec images et mots, (3) Course aux trésors de vocabulaire dans la classe, (4) Quiz d''équipe amical avec célébrations pour toutes les bonnes réponses.','Cérémonie de célébration : Distribution de certificats ''Experts d''automne'' personnalisés. Chanson finale récapitulative de tous les mots appris avec gestes. Promesse pour demain : ''Demain nous présentons notre livre à d''autres classes!''','Écrire le concept de révision et; Utiliser les observations automnales; Développer la compréhension par la célébration collective','["Tous les travaux d''automne de l''unité pour référence","Cartes de vocabulaire complète de l''unité","Photos des activités faites ensemble","Certificats de progrès préparés","Cartes de charades avec mots d''automne","Cartes de bingo personnalisées (25 copies)","Marqueurs ou jetons pour bingo","Indices de chasse au trésor illustrés","Questions de quiz adaptées au niveau","Prix symboliques (autocollants, certificats)","Minuteur pour rotations","Certificats personnalisés pour chaque élève","Chanson récapitulative avec paroles affichées","Livre de classe terminé pour montrer","Appareil photo pour capturer célébration (optionnel)"]',NULL,'Révision et célébration','Cercle de fierté : Chaque élève partage quelque chose qu''il sait maintenant sur l''automne qu''il ne savait pas avant. Introduction de ''savoir'' (toucher la tête), ''apprendre'' (geste d''ouverture), ''bien'' (pouce en l''air).','Festival de jeux d''automne : Stations rotatives avec jeux de révision - (1) Charades d''automne avec tous les mots appris, (2) Bingo d''automne avec images et mots, (3) Course aux trésors de vocabulaire dans la classe, (4) Quiz d''équipe amical avec célébrations pour toutes les bonnes réponses.','Cérémonie de célébration : Distribution de certificats ''Experts d''automne'' personnalisés. Chanson finale récapitulative de tous les mots appris avec gestes. Promesse pour demain : ''Demain nous présentons notre livre à d''autres classes!''','Écrire le concept de révision et; Utiliser les observations automnales; Développer la compréhension par la célébration collective',NULL,NULL,NULL,'formative','{"observable":["Démontre reco nnaissance du vocabulaire d''automne dans les jeux","Utilise ''savoir'', ''apprendre'', ''bien'' de manière appropriée","Participe avec confiance aux activités de révision","Montre fierté et conscience de ses apprentissages"],"checkpoints":["Stations de jeux : observer aisance avec vocabulaire dans contextes variés","Partage de fierté : noter articulation des apprentissages réalisés","Participation générale : évaluer engagement et confiance avec contenu d''unité"]}',1,'Plan détaillé avec supports visuels',1756911653591,1757594654175,1,'fr','Français (Immersion)','{"pourDifficultés":["Jeux adaptés avec moins de vocabulaire","Plus de supports visuels et indices","Partenariat pour les activités de station","Célébration de progrès personnels plutôt que absolus"],"pourAvancés":["Défis supplémentaires dans les jeux","Rôle d''aide-animateur aux stations","Vocabulaire étendu ou phrases complètes","Leadership dans activités de groupe"],"pourLangue":["Jeux avec supports visuels très clairs","Permission d''utiliser L1 pour expliquer si nécessaire","Plus de temps pour réponses","Célébration de l''effort linguistique autant que résultats"],"pourPEI":["Adaptations selon objectifs PEI individuels","Jeux modifiés selon capacités","Participation ajustée aux activités de groupe","Reconnaissance des progrès selon objectifs personnels"]}','{"vocabulary":["savoir","apprendre","bien"],"visualSupports":["Portfolio d''activités d''automne visible, mur de mots complet affiché, photos des créations et apprentissages","Instructions claires à chaque station, références visuelles pour tous les jeux, tableau de score positif et encourageant","Cérémonie organisée avec espace spécial, chanson avec gestes illustrés, affichage fier de tous les accomplissements"],"movementBreaks":["Gestes pour savoir, apprendre, bien","Applaudissements pour chaque partage de fierté","Rotation active entre stations","Charades implique mouvement naturel","Chasse au trésor nécessite déplacement","Recevoir certificats debout avec fierté","Chanson finale avec tous les gestes appris"]}',NULL,NULL,NULL,NULL,'{"questions":["Les élèves ont-ils atteint les objectifs?","Quelles adaptations étaient nécessaires?","Que ferais-je différemment la prochaine fois?"]}',NULL,'',1,13,'core',1);
INSERT INTO ETFOLessonPlan VALUES('cmf43u40n00nnvj9trst50aab',23,'Présentation du livre','cmf43u40a00mvvj9tk4l6dmf7',1760626800000,45,'Préparatifs de présentation : Les élèves s''exercent à présenter leurs pages en disant ''Je suis fier de présenter ma page'' et ''J''aime partager notre histoire.'' Révision des mots avec gestes : présenter (montrer), partager (donner), fier (sourire et poitrine bombée).','Lanc ement officiel du livre : Présentation du livre à une autre classe, aux parents, ou à la direction (selon disponibilité). Chaque élève présente sa page et explique sa contribution. Lecture chorale de parties sélectionnées. Session de questions et d''appréciation avec l''audience.','Célébration finale : Réflexion sur l''unité complète d''automne. ''De quoi sommes-nous les plus fiers?'' Placement spécial du livre dans la bibliothèque de classe. Chanson finale : ''Nous avons appris, nous avons créé, nous sommes fiers de partager!''','Raconter le concept de présentation du; Présenter les observations automnales; Développer la compréhension par le partage des apprentissages','["Livre de classe ''Notre Automne'' terminé","Espace arrangé pour présentation spéciale","Microphone jouet (optionnel)","Cartes de phrases d''aide pour présentation","Livre ''Notre Automne'' relié et prêt","Audience invitée (autre classe, parents, personnel)","Espace de présentation aménagé","Support visuel agrandi de pages clés","Certificats de reconnaissance pour audience","Appareil photo/vidéo pour mémoires","Place d''honneur pour le livre dans la classe","Certificats finaux de ''Créateurs d''histoires d''automne''","Paroles de chanson finale","Photos prises pendant présentation"]',NULL,'Présentation du livre','Préparatifs de présentation : Les élèves s''exercent à présenter leurs pages en disant ''Je suis fier de présenter ma page'' et ''J''aime partager notre histoire.'' Révision des mots avec gestes : présenter (montrer), partager (donner), fier (sourire et poitrine bombée).','Lanc ement officiel du livre : Présentation du livre à une autre classe, aux parents, ou à la direction (selon disponibilité). Chaque élève présente sa page et explique sa contribution. Lecture chorale de parties sélectionnées. Session de questions et d''appréciation avec l''audience.','Célébration finale : Réflexion sur l''unité complète d''automne. ''De quoi sommes-nous les plus fiers?'' Placement spécial du livre dans la bibliothèque de classe. Chanson finale : ''Nous avons appris, nous avons créé, nous sommes fiers de partager!''','Raconter le concept de présentation du; Présenter les observations automnales; Développer la compréhension par le partage des apprentissages',NULL,NULL,NULL,'formative','{"observable":["Utilise ''présenter'', ''partager'', ''fier'' de manière appropriée","Démontre fierté authentique de son travail et de celui du groupe","Participe positivement à la présentation publique","Articule sa contribution au projet collaboratif"],"checkpoints":["Pendant présentations : observer confiance et usage du vocabulaire de fierté","Pendant interactions avec audience : noter aisance et engagement","Réflexion finale : écouter articulation des apprentissages et accomplissements"]}',1,'Plan détaillé avec supports visuels',1756911653592,1757594654176,1,'fr','Français (Immersion)','{"pourDifficultés":["Présentation simplifiée avec support de phrases","Possibilité de présentation en duo ou petit groupe","Focus sur montrer leur page plutôt qu''expliquer longuement","Reconnaissance spéciale pour effort et participation"],"pourAvancés":["Présentation plus détaillée avec descriptions étendues","Rôle d''animateur ou de maître de cérémonie","Questions à poser à l''audience pour engagement","Leadership dans organisation de présentation"],"pourLangue":["Support bilingue si nécessaire","Focus sur fierté visà-vis accomplissement plutôt que perfection linguistique","Partenariat avec élève francophone pour soutien","Célébration du courage linguistique"],"pourPEI":["Adaptations selon objectifs PEI et préférences","Forme de présentation ajustée aux capacités","Soutien émotionnel si nécessaire pour situation sociale","Reconnaissance des progrès individuels accomplis"]}','{"vocabulary":["présenter","partager","fier"],"visualSupports":["Phrases modèles affichées, gestes de présentation modélisés, livre fini attrayant prêt à montrer","Livre bien présenté et visible, pages clés agrandies pour audience, espace organisé professionnellement","Livre placé fièrement en évidence, photos de présentation montrées, chanson avec gestes fiers"],"movementBreaks":["Gestes de présentation (montrer, partager, fier)","S''exercer à tenir et montrer le livre","Se lever pour présentations individuelles","Circuler pour montrer pages aux membres de l''audience","Applaudissements et célébrations tout au long","Placement cérémonieux du livre","Chanson finale avec gestes de fierté et de célébration"]}',NULL,NULL,NULL,NULL,'{"questions":["Les élèves ont-ils atteint les objectifs?","Quelles adaptations étaient nécessaires?","Que ferais-je différemment la prochaine fois?"]}',NULL,'',1,14,'core',1);
INSERT INTO ETFOLessonPlan VALUES('cmf43u40o00npvj9twggwjs0m',23,'Contes traditionnels d''automne','cmf43u40a00mvvj9tk4l6dmf7',1760713200000,45,'Voyage culturel : Introduction aux contes traditionnels avec images de différents pays francophones. Écoute d''une comptine traditionnelle française d''automne. Les élèves explorent les mots ''traditionnel'', ''culture'', ''autrefois'' avec gestes temporels.','Découverte de contes : Écoute d''une version adaptée d''un conte traditionnel d''automne francophone. Comparaison avec traditions locales d''automne. Création d''illustrations inspirées du conte avec matériaux divers pour accommoder styles d''apprentissage variés.','Galerie culturelle : Partage des créations inspirées du conte. Réflexion guidée sur ressemblances entre traditions d''ici et d''ailleurs. Préparation pour activité optionnelle : recherche de traditions familiales.','Communiquer les changements d''automne dans l''environnement; Raconter les observations automnales; Développer la compréhension par la narration','["Carte du monde avec pays francophones","Images de fêtes d''automne du Québec, France, Afrique francophone","Comptine traditionnelle enregistrée ou chantée","Objets traditionnels d''automne (vraies citrouilles, blé, etc.)","Conte traditionnel d''automne adapté pour 1re année","Matériaux artistiques variés (papier, tissus, éléments naturels)","Images de traditions d''automne locales pour comparaison","Cartes de compréhension avec choix multiples","Matériaux sensoriels pour différents apprenants","Espace d''exposition pour créations","Questions de réflexion illustrées","Note optionnelle aux parents sur traditions familiales"]',NULL,'Contes traditionnels d''automne','Voyage culturel : Introduction aux contes traditionnels avec images de différents pays francophones. Écoute d''une comptine traditionnelle française d''automne. Les élèves explorent les mots ''traditionnel'', ''culture'', ''autrefois'' avec gestes temporels.','Découverte de contes : Écoute d''une version adaptée d''un conte traditionnel d''automne francophone. Comparaison avec traditions locales d''automne. Création d''illustrations inspirées du conte avec matériaux divers pour accommoder styles d''apprentissage variés.','Galerie culturelle : Partage des créations inspirées du conte. Réflexion guidée sur ressemblances entre traditions d''ici et d''ailleurs. Préparation pour activité optionnelle : recherche de traditions familiales.','Communiquer les changements d''automne dans l''environnement; Raconter les observations automnales; Développer la compréhension par la narration',NULL,NULL,NULL,'formative','{"observable":["Montre intérêt pour contes traditionnels d''autres cultures","Fait des connections entre traditions différentes","Participe aux activités culturelles avec respect","Exprime appréciation pour diversité culturelle"],"checkpoints":["Pendant écoute du conte : observer engagement et compréhension","Pendant création : noter connections personnelles avec contenu","Pendant partage : écouter réflexions sur diversité culturelle"]}',1,'Plan détaillé avec supports visuels',1756911653592,1757594654177,1,'fr','Français (Immersion)','{"pourDifficultés":["Focus sur une tradition simple et concrète","Plus d''images et moins de concepts abstraits","Activités créatives adaptées aux capacités","Connection avec traditions très familières d''abord"],"pourAvancés":["Exploration de multiples traditions culturelles","Recherche supplémentaire sur pays francophones","Créations artistiques plus élaborées","Leadership dans discussions comparatives"],"pourLangue":["Connections avec traditions de pays d''origine","Support bilingue pour concepts culturels","Plus de supports visuels pour compréhension","Valorisation de diversité culturelle apportée"],"pourPEI":["Activités adaptées selon objectifs individuels","Choix de modalités d''expression (verbale, artistique, gestuelle)","Environnement d''apprentissage ajusté","Participation flexible selon capacités"]}','{"vocabulary":["traditionnel","culture","autrefois"],"visualSupports":["Carte colorée avec drapeaux, images de traditions d''automne variées, ligne de temps simple montrant ''autrefois'' vs ''maintenant''","Histoire illustrée visuellement, comparaisons côte à côte des traditions, choix d''activités illustrées","Gallery organisée, questions visuelles pour réflexion culturelle"],"movementBreaks":["Gestes pour montrer passage du temps (autrefois vs maintenant)","Mouvements de comptine traditionnelle","Participation gestuelle pendant le conte","Création artistique avec manipulation","Échanges debout entre élèves pour comparaisons","Circulation pour admirer créations","Gestes de salutation culturelle du conte"]}',NULL,NULL,NULL,NULL,'{"questions":["Les élèves ont-ils atteint les objectifs?","Quelles adaptations étaient nécessaires?","Que ferais-je différemment la prochaine fois?"]}',NULL,'',1,15,'extension',1);
INSERT INTO ETFOLessonPlan VALUES('cmf43u40p00nrvj9t6h1jh7rx',23,'Théâtre d''automne','cmf43u40a00mvvj9tk4l6dmf7',1760972400000,45,'Préparation théâtrale : Exercices d''échauffement dramatique (devenir des feuilles, des arbres, des animaux). Introduction des mots du théâtre avec démonstrations : ''jouer'' (mimer), ''spectacle'' (montrer scène), ''rôle'' (se transformer).','Création de spectacle d''automne : En petits groupes flexibles, les élèves choisissent scène d''automne à jouer (animaux se préparant, feuilles tombant, fête d''automne). Préparation avec costumes et accessoires adaptés. Répétitions courtes avec support différencié.','Festival théâtral d''automne : Chaque groupe présente sa scène courte. Audience d''élèves applaudit et partage appréciations positives. Célébration de la créativité et du courage artistique de tous.','Exprimer les changements d''automne dans l''environnement; Utiliser les observations automnales; Développer la compréhension par des activités langagières variées','["Espace dégagé pour mouvement","Accessoires théâtraux simples (foulards, chapeaux)","Images de différents rôles d''automne","Cartes de vocabulaire théâtral","Boîte de costumes d''automne (tissus, accessoires)","Cartes de scénarios simples avec choix","Accessoires naturels (feuilles, branches sécuritaires)","Espace de ''coulisses'' pour préparation","Caméra ou téléphone pour capturer performances (optionnel)","Espace scénique pour performances","Costumes et accessoires utilisés","Certificats d''acteurs d''automne","Applaudissements et encouragements"]',NULL,'Théâtre d''automne','Préparation théâtrale : Exercices d''échauffement dramatique (devenir des feuilles, des arbres, des animaux). Introduction des mots du théâtre avec démonstrations : ''jouer'' (mimer), ''spectacle'' (montrer scène), ''rôle'' (se transformer).','Création de spectacle d''automne : En petits groupes flexibles, les élèves choisissent scène d''automne à jouer (animaux se préparant, feuilles tombant, fête d