INSERT INTO ETFOLessonPlan VALUES('cmf43u40q00ntvj9tdec71hlk',23,'Poésie d''automne','cmf43u40a00mvvj9tk4l6dmf7',1761058800000,45,'Exploration rythmique : Écoute d''un poème d''automne simple avec battements de mains pour le rythme. Découverte des mots qui ''sonnent pareil'' (rimes). Introduction ludique : ''poème'' (livre ouvert), ''rythme'' (battre), ''rime'' (mots jumeaux).','Atelier de création poétique : Création collective d''un poème d''automne simple avec structure de support. Exploration de mots d''automne qui riment. Illustration poétique avec différents matériaux créatifs selon préférences d''apprentissage.','Café poétique d''automne : Partage volontaire de poèmes créés avec micro ouvert. Célébration de la créativité linguistique et artistique. Réflexion sur beauté des mots et sons.','Décrire les changements d''automne dans l''environnement; Utiliser les observations automnales; Développer l''expression écrite par des activités langagières variées','["Poème d''automne simple et rythmique","Instruments de percussion simples (maracas, tambourins)","Cartes de mots qui riment","Exemples visuels de poèmes illustrés","Structure de poème simple à compléter","Banque de mots d''automne pour inspiration","Matériaux artistiques variés pour illustration","Carnets de poésie personnels","Cartes de rimes d''automne préparées","Poèmes et illustrations créés","Espace ''scène'' pour récitations","Microphone jouet","Applaudissements et encouragements"]',NULL,'Poésie d''automne','Exploration rythmique : Écoute d''un poème d''automne simple avec battements de mains pour le rythme. Découverte des mots qui ''sonnent pareil'' (rimes). Introduction ludique : ''poème'' (livre ouvert), ''rythme'' (battre), ''rime'' (mots jumeaux).','Atelier de création poétique : Création collective d''un poème d''automne simple avec structure de support. Exploration de mots d''automne qui riment. Illustration poétique avec différents matériaux créatifs selon préférences d''apprentissage.','Café poétique d''automne : Partage volontaire de poèmes créés avec micro ouvert. Célébration de la créativité linguistique et artistique. Réflexion sur beauté des mots et sons.','Décrire les changements d''automne dans l''environnement; Utiliser les observations automnales; Développer l''expression écrite par des activités langagières variées',NULL,NULL,NULL,'formative','{"observable":["Montre plaisir dans jeux de sons et rythmes","Reconnaît mots qui riment avec support","Participe créativement à activités poétiques","Exprime appréciation pour beauté des mots"],"checkpoints":["Pendant exploration rythmique : observer engagement avec sons et rythmes","Pendant création : noter originalité et plaisir dans expression","Pendant partage : évaluer confiance et fierté créative"]}',1,'Plan détaillé avec supports visuels',1756911653594,1757594654180,1,'fr','Français (Immersion)','{"pourDifficultés":["Poèmes très simples avec structure guidée","Focus sur rythme et sons plutôt que rimes parfaites","Illustration comme expression poétique principale","Support individuel pour création"],"pourAvancés":["Création de poèmes plus élaborés","Exploration de différentes structures poétiques","Jeu avec métaphores simples sur l''automne","Aide aux autres dans créations poétiques"],"pourLangue":["Poésie avec support de L1 pour inspiration","Focus sur sons et musicalité plutôt que sens parfait","Plus de support visuel pour création","Valorisation de richesse linguistique apportée"],"pourPEI":["Expression poétique adaptée aux capacités","Choix de modalités d''expression (orale, visuelle, gestuelle)","Objectifs ajustés selon besoins individuels","Support pour concepts abstraits"]}','{"vocabulary":["poème","rythme","rime"],"visualSupports":["Poème affiché avec mots qui riment en couleurs, représentation visuelle du rythme, gestes pour chaque concept poétique","Modèles de poèmes simples, banque visuelle de mots qui riment, exemples d''illustrations poétiques variées","Espace poétique aménagé, œuvres poétiques exposées, atmosphère créative et bienveillante"],"movementBreaks":["Battements rythmiques avec mains et instruments","Gestes pour illustrer concepts de poésie","Récitation avec gestes et mouvements","Création artistique active","Partages debout avec expressions corporelles","Récitations avec expression corporelle","Applaudissements et célébrations poétiques"]}',NULL,NULL,NULL,NULL,'{"questions":["Les élèves ont-ils atteint les objectifs?","Quelles adaptations étaient nécessaires?","Que ferais-je différemment la prochaine fois?"]}',NULL,'',1,17,'extension',1);
INSERT INTO ETFOLessonPlan VALUES('cmf43u40r00nvvj9t498u88mi',23,'Légendes d''automne','cmf43u40a00mvvj9tk4l6dmf7',4102416000000,45,'Atmosphère mystique : Création d''ambiance spéciale avec éclairage tamisé et musique douce. Introduction au monde des légendes avec objets mystérieux d''automne. Découverte des mots magiques : ''légende'' (livre ancien), ''magique'' (baguette), ''mystère'' (boîte fermée).','Voyage dans les légendes : Écoute d''une légende d''automne adaptée (pourquoi les feuilles changent de couleur, origine des citrouilles, etc.). Exploration créative libre - chaque élève choisit comment exprimer la légende (dessin, danse, modélisation, narration). Partage des créations dans cercle magique.','Cercle des légendes : Partage des créations dans atmosphère respectueuse et émerveillée. Réflexion sur magie des histoires qui expliquent le monde. Retour à éclairage normal avec sensation d''avoir vécu quelque chose de spécial.','Appliquer les changements d''automne dans l''environnement; Utiliser les observations automnales; Développer l''expression écrite par des activités langagières variées','["Éclairage doux ou chandelles LED","Objets mystérieux liés à l''automne (cristaux, feuilles spéciales, pierres)","Musique instrumentale douce","Livre de légendes décoratif","Boîte à mystères","Légende d''automne adaptée et illustrée","Matériaux créatifs très variés (peinture, pâte à modeler, tissus, éléments naturels)","Espace pour expressions variées","Musique de fond inspireée de la nature","Carnet d''exploration pour ceux qui préfèrent écrire","Créations des élèves","Cercle spécial pour partage","Ambiance douce maintenue","Paroles d''appréciation et d''émerveillement"]',NULL,'Légendes d''automne','Atmosphère mystique : Création d''ambiance spéciale avec éclairage tamisé et musique douce. Introduction au monde des légendes avec objets mystérieux d''automne. Découverte des mots magiques : ''légende'' (livre ancien), ''magique'' (baguette), ''mystère'' (boîte fermée).','Voyage dans les légendes : Écoute d''une légende d''automne adaptée (pourquoi les feuilles changent de couleur, origine des citrouilles, etc.). Exploration créative libre - chaque élève choisit comment exprimer la légende (dessin, danse, modélisation, narration). Partage des créations dans cercle magique.','Cercle des légendes : Partage des créations dans atmosphère respectueuse et émerveillée. Réflexion sur magie des histoires qui expliquent le monde. Retour à éclairage normal avec sensation d''avoir vécu quelque chose de spécial.','Appliquer les changements d''automne dans l''environnement; Utiliser les observations automnales; Développer l''expression écrite par des activités langagières variées',NULL,NULL,NULL,'formative','{"observable":["Participe avec imagination aux activités de légende","Montre appréciation pour histoires explicatives","Exprime créativité à travers modalité choisie","Respecte ambiance spéciale et partages des autres"],"checkpoints":["Pendant écoute : observer engagement imaginatif avec légende","Pendant création : noter expression personnelle et créativité","Pendant partage : évaluer respect et émerveillement pour créations diverses"]}',1,'Plan détaillé avec supports visuels',1756911653595,1757594654180,1,'fr','Français (Immersion)','{"pourDifficultés":["Légende très simple avec concepts concrets","Expression par manipulation d''objets ou dessin","Soutien individuel pour compréhension","Ambiance ajustée si trop stimulante"],"pourAvancés":["Exploration plus approfondie de légendes multiples","Création de leur propre légende d''automne","Réflexion sur rôle des légendes dans cultures","Leadership dans partage et discussions"],"pourLangue":["Légende avec support visuel très fort","Expression principalement créative plutôt que verbale","Connections avec légendes de cultures d''origine","Valorisation de richesse culturelle apportée"],"pourPEI":["Participation ajustée selon besoins sensoriels","Expression dans modalité préférée","Support pour concepts abstraits avec concret","Environnement adapté aux besoins individuels"]}','{"vocabulary":["légende","magique","mystère"],"visualSupports":["Ambiance visuelle créée spécialement, objets tangibles pour concepts abstraits, atmosphère immersive","Légende racontée avec illustrations captivantes, choix d''activités illustrés clairement, inspiration visuelle variée","Exposition temporaire des créations, cercle organisé pour écoute respectueuse, transition douce vers réalité"],"movementBreaks":["Gestes mystérieux et magiques pour vocabulaire","Exploration tactile d''objets de légende","Participation gestuelle pendant l''écoute de légende","Exploration créative libre avec mouvement naturel","Déplacements entre stations d''expression","Partage avec gestes expressifs selon créations","Transition physique douce vers fin d''activité"]}',NULL,NULL,NULL,NULL,'{"questions":["Les élèves ont-ils atteint les objectifs?","Quelles adaptations étaient nécessaires?","Que ferais-je différemment la prochaine fois?"]}',NULL,'',1,18,'extension',0);
INSERT INTO ETFOLessonPlan VALUES('cmf43u40s00nxvj9t51dllmzw',23,'Automne autour du monde','cmf43u40a00mvvj9tk4l6dmf7',4102416000000,45,'Tour du monde d''automne : Présentation de globe terrestre et identification de pays francophones. Observation de photos d''automne de différents pays. Introduction de ''monde'' (globe), ''pays'' (drapeaux), ''différent'' (comparaison visuelle).','Voyage culturel d''automne : Exploration de traditions d''automne de différents pays francophones à travers stations. Station France (vendanges), Station Québec (érables), Station Afrique (saison sèche). Création d''un passeport de voyage avec dessins et découvertes de chaque ''pays''.','Retour de voyage : Partage des découvertes de chaque ''pays'' visité. Comparaison avec automne local - ressemblances et différences. Célébration de la diversité mondiale tout en reconnaissant points communs humains.','Créer les changements d''automne dans l''environnement; Utiliser les observations automnales; Développer l''expression écrite par des activités langagières variées','["Globe terrestre ou mappemonde","Photos d''automne de France, Québec, Suisse, Belgique, Afrique francophone","Drapeaux de pays francophones","Images comparatives montrant différences","3 stations thématiques avec décorations","Images et objets représentatifs de chaque région","Passeports de voyage vierges (25 copies)","Tampons ou autocollants pour chaque station","Matériaux créatifs pour documentation","Musique traditionnelle de chaque région (optionnel)","Passeports complétés des élèves","Tableau de comparaison simple","Photos de l''automne local pour comparaison","Certificats de ''Voyageurs du monde''"]',NULL,'Automne autour du monde','Tour du monde d''automne : Présentation de globe terrestre et identification de pays francophones. Observation de photos d''automne de différents pays. Introduction de ''monde'' (globe), ''pays'' (drapeaux), ''différent'' (comparaison visuelle).','Voyage culturel d''automne : Exploration de traditions d''automne de différents pays francophones à travers stations. Station France (vendanges), Station Québec (érables), Station Afrique (saison sèche). Création d''un passeport de voyage avec dessins et découvertes de chaque ''pays''.','Retour de voyage : Partage des découvertes de chaque ''pays'' visité. Comparaison avec automne local - ressemblances et différences. Célébration de la diversité mondiale tout en reconnaissant points communs humains.','Créer les changements d''automne dans l''environnement; Utiliser les observations automnales; Développer l''expression écrite par des activités langagières variées',NULL,NULL,NULL,'formative','{"observable":["Montre curiosité pour diversité culturelle mondiale","Identifie similitudes et différences entre régions","Utilise ''monde'', ''pays'', ''différent'' dans contexte géographique","Respecte et apprécie diversité culturelle"],"checkpoints":["Stations culturelles : observer engagement et compréhension des différences","Passeport : noter capacité à documenter découvertes","Partage final : écouter réflexions sur diversité et similitudes"]}',1,'Plan détaillé avec supports visuels',1756911653596,1757594654181,1,'fr','Français (Immersion)','{"pourDifficultés":["Focus sur 1-2 pays avec différences très évidentes","Plus d''images et manipulation concrète","Passeport simplifié avec autocollants plutôt qu''dessins","Soutien individuel pour concepts géographiques"],"pourAvancés":["Exploration plus approfondie de cultures multiples","Recherche de causes des différences climatiques","Création de présentation sur pays choisi","Leadership dans comparaisons culturelles"],"pourLangue":["Connections explicites avec pays/cultures d''origine","Valorisation de diversité culturelle apportée","Support bilingue pour concepts géographiques","Partage d''expériences personnelles d''automne"],"pourPEI":["Participation ajustée selon capacités cognitives","Focus sur expériences sensorielles plutôt que concepts abstraits","Passeport adapté aux