INSERT INTO ETFOLessonPlan VALUES('cmf43u42k00rlvj9tf6ihlx3n',23,'Assembler nos collections','cmf43u42j00rjvj9t481uo6wk',1763568000000,45,'Histoire d''assemblage: ''Regardez! J''ai 2 voitures rouges ici et 3 voitures bleues là. Si je les mets ensemble, combien ai-je en tout?''','Exploration d''assemblage: Stations avec différents objets (blocs, animaux, crayons). Élèves créent deux groupes, les assemblent et comptent le total. Narrent leurs actions: ''J''avais... et j''avais... maintenant j''ai...''','Cercle de partage: Élèves montrent leurs assemblages et expliquent: ''J''ai assemblé ___ et ___, maintenant j''ai ___''','Identifier le concept de assembler nos; Appliquer les concepts mathématiques de base; Développer le sens du nombre par la manipulation et le raisonnement','["Matériel de classe"]',NULL,'Assembler nos collections','Histoire d''assemblage: ''Regardez! J''ai 2 voitures rouges ici et 3 voitures bleues là. Si je les mets ensemble, combien ai-je en tout?''','Exploration d''assemblage: Stations avec différents objets (blocs, animaux, crayons). Élèves créent deux groupes, les assemblent et comptent le total. Narrent leurs actions: ''J''avais... et j''avais... maintenant j''ai...''','Cercle de partage: Élèves montrent leurs assemblages et expliquent: ''J''ai assemblé ___ et ___, maintenant j''ai ___''','Identifier le concept de assembler nos; Appliquer les concepts mathématiques de base; Développer le sens du nombre par la manipulation et le raisonnement',NULL,NULL,NULL,'formative','{"observable":["L''élève utilise des manipulatifs concrets pour assembler différentes collections d''objets","L''élève explique sa démarche d''assemblage en utilisant le vocabulaire mathématique approprié en français","L''élève démontre une compréhension de l''addition comme action d''assembler ou de joindre","L''élève identifie les quantités dans chaque collection avant et après l''assemblage","L''élève fait des connections entre l''assemblage physique et le concept mathématique"],"checkpoints":["Assemble correctement des collections d''objets concrets pour représenter l''addition","Explique le processus d''assemblage en utilisant un vocabulaire mathématique simple"]}',1,'Plan détaillé avec supports visuels',1756911653660,1757587623110,1,'fr','Mathématiques','{"pourDifficultés":["Commencer avec seulement 1+1 et 2+1 (sommes jusqu''à 3)","Utiliser objets identiques pour éviter distraction visuelle","Permettre comptage lent avec pointage de chaque objet","Offrir support individuel pendant manipulation"],"pourAvancés":["Introduire sommes jusqu''à 7 (3+4, 2+5) si maîtrise rapide","Demander de créer leurs propres histoires d''assemblage","Encourager à enseigner concept à un pair","Explorer assemblage de 3 groupes au lieu de 2"],"pourLangue":["Utiliser gestes clairs pour ''assembler'' et ''ensemble''","Associer chaque étape à une image visuelle","Permettre narration dans langue première puis français","Utiliser objets culturellement familiers si possible"],"pourPEI":["Adapter manipulatifs selon besoins moteurs (plus gros, texturés)","Modifier attentes de verbalisation (gestes acceptables)","Ajuster éclairage et position selon besoins sensoriels","Fournir pauses fréquentes si nécessaire"]}','{"vocabulary":["assembler","ensemble","en tout","groupe"],"visualSupports":["Tableau magnétique avec aimants colorés pour illustration","Cartes d''histoires visuelles, contenants étiquetés ''Groupe 1'' et ''Groupe 2'', affiche stratégies d''assemblage","Phrases modèles affichées: ''J''avais ___, j''avais ___, maintenant j''ai ___''"],"movementBreaks":["Former des lettres dans l''air avec nos doigts : A, B, C (3 minutes)","Marcher en syllabant notre nom : Ma-rie, Paul, etc. en tapant dans nos mains (2 minutes)","Marcher sur place en récitant l''alphabet lentement (2 minutes)","Danser avec les sons : ''a'' avec les bras, ''o'' en rond, ''i'' pointu (3 minutes)","Ranger nos idées : faire semblant de mettre nos pensées dans une boîte (2 minutes)","Célébrer nos apprentissages : applaudir, lever les bras, sourire (2 minutes)"]}',NULL,NULL,NULL,NULL,'{"questions":["Les élèves ont-ils atteint les objectifs?","Quelles adaptations étaient nécessaires?","Que ferais-je différemment la prochaine fois?"]}',NULL,'',2,1,'core',1);
INSERT INTO ETFOLessonPlan VALUES('cmf43u42l00rnvj9tx6s1lzk7',23,'Histoires de ''plus''','cmf43u42j00rjvj9t481uo6wk',1763654400000,45,'Théâtre mathématique: Présenter histoire avec marionnettes: ''3 lapins mangent. 2 lapins de plus arrivent. Combien de lapins maintenant?''','Ateliers d''histoires: Station 1 - Agir histoires avec objets. Station 2 - Dessiner histoires d''addition. Station 3 - Inventer histoires avec marionnettes. Rotation toutes les 8 minutes.','Spectacle d''histoires: Groupes présentent leurs histoires d''addition favorite.','Explorer le concept de histoires de; Raconter les concepts mathématiques de base; Développer le sens du nombre par la narration','["Matériel de classe"]',NULL,'Histoires de ''plus''','Théâtre mathématique: Présenter histoire avec marionnettes: ''3 lapins mangent. 2 lapins de plus arrivent. Combien de lapins maintenant?''','Ateliers d''histoires: Station 1 - Agir histoires avec objets. Station 2 - Dessiner histoires d''addition. Station 3 - Inventer histoires avec marionnettes. Rotation toutes les 8 minutes.','Spectacle d''histoires: Groupes présentent leurs histoires d''addition favorite.','Explorer le concept de histoires de; Raconter les concepts mathématiques de base; Développer le sens du nombre par la narration',NULL,NULL,NULL,'formative','{"observable":["L''élève raconte des histoires mathématiques simples qui illustrent le concept d''addition","L''élève utilise le mot ''plus'' correctement dans ses récits mathématiques","L''élève fait des connections entre les situations de la vraie vie et l''addition","L''élève écoute et comprend les histoires d''addition racontées par d''autres","L''élève utilise des gestes et des expressions pour appuyer ses histoires mathématiques"],"checkpoints":["Raconte une histoire simple qui montre une situation d''addition","Utilise le vocabulaire ''plus'' et ''ajouter'' dans le contexte approprié"]}',1,'Plan détaillé avec supports visuels',1756911653661,1757587623122,1,'fr','Mathématiques','{"pourDifficultés":["Limiter à histoires avec sommes jusqu''à 5","Fournir histoires pré-écrites avec espaces à remplir","Utiliser support visuel constant (images séquentielles)","Permettre travail en paires pour soutien mutuel"],"pourAvancés":["Encourager histoires avec sommes jusqu''à 10","Demander de créer histoires avec multiple épisodes d''addition","Inviter à dessiner bande dessinée de leur histoire","Proposer d''enseigner leur histoire à d''autres élèves"],"pourLangue":["Utiliser images pour soutenir compréhension narrative","Permettre narration bilingue (L1 puis français)","Associer gestes à vocabulaire clé: plus, arrivent, maintenant","Fournir modèles de phrases simples"],"pourPEI":["Adapter selon besoins sensoriels (volume, éclairage)","Modifier attentes de production (pointer, dessiner vs parler)","Utiliser supports tactiles pour objets d''histoire","Ajuster temps selon rythme individuel"]}','{"vocabulary":["plus","arrivent","maintenant","combien"],"visualSupports":["Images séquentielles de l''histoire: 3 lapins + 2 lapins = ? lapins","Images séquentielles d''histoires, cartes de personnages, décors simples, affiche des étapes: Début + Plus + Fin","Support pour afficher dessins créés, phrases modèles: ''Il y avait ___, puis ___ de plus, maintenant ___''"],"movementBreaks":["Faire l''alphabet avec notre corps : A comme arbre (étirer les bras), B comme ballon (forme ronde) (3 minutes)","Imiter les animaux des histoires : sauter comme un lapin, voler comme un oiseau (3 minutes)","Étirer nos doigts et mains d''écrivains : ouvrir, fermer, tourner (2 minutes)","Faire une pause lecture : s''étirer comme un chat qui se réveille (2 minutes)","Célébrer nos apprentissages : applaudir, lever les bras, sourire (2 minutes)","Ranger nos idées : faire semblant de mettre nos pensées dans une boîte (2 minutes)"]}',NULL,NULL,NULL,NULL,'{"questions":["Les élèves ont-ils atteint les objectifs?","Quelles adaptations étaient nécessaires?","Que ferais-je différemment la prochaine fois?"]}',NULL,'',2,2,'core',1);
INSERT INTO ETFOLessonPlan VALUES('cmf43u42m00rpvj9txqqlpdff',23,'Compter pour additionner','cmf43u42j00rjvj9t481uo6wk',1763740800000,45,'Échauffement de comptage: ''Montrez-moi 3 doigts... maintenant 2 de plus... comptez-les tous!''','Stratégies de comptage: Enseigner ''tout compter'' puis ''compter à partir de''. Pratiquer avec objets, doigts, ligne de nombres. Comparer efficacité des méthodes.','Championnat de comptage: Élèves montrent leur stratégie préférée et expliquent pourquoi.','Découvrir l''addition avec manipulatifs; Appliquer des stratégies d''addition variées; Développer le sens du nombre par la manipulation et le raisonnement','["Matériel de classe"]',NULL,'Compter pour additionner','Échauffement de comptage: ''Montrez-moi 3 doigts... maintenant 2 de plus... comptez-les tous!''','Stratégies de comptage: Enseigner ''tout compter'' puis ''compter à partir de''. Pratiquer avec objets, doigts, ligne de nombres. Comparer efficacité des méthodes.','Championnat de comptage: Élèves montrent leur stratégie préférée et expliquent pourquoi.','Découvrir l''addition avec manipulatifs; Appliquer des stratégies d''addition variées; Développer le sens du nombre par la manipulation et le raisonnement',NULL,NULL,NULL,'formative','{"observable":["L''élève compte avec précision en utilisant des manipulatifs pour résoudre des problèmes d''addition","L''élève démontre différentes stratégies de comptage (tout compter, compter à partir du plus grand nombre)","L''élève utilise ses doigts de manière efficace pour compter et additionner","L''élève explique sa stratégie de comptage en français","L''élève vérifie ses réponses en recomptant ou en utilisant une méthode différente"],"checkpoints":["Utilise des manipulatifs pour compter et additionner des quantités jusqu''à 10","Explique sa stratégie de comptage en utilisant un vocabulaire mathématique approprié"]}',1,'Plan détaillé avec supports visuels',1756911653662,1757587623110,1,'fr','Mathématiques','{"pourDifficultés":["Se concentrer uniquement sur ''tout compter'' jusqu''à maîtrise","Utiliser nombres plus petits (additions jusqu''à 5)","Permettre usage d''objets concrets en tout temps","Offrir plus de temps et encouragement individuel"],"pourAvancés":["Introduire ''compter à rebours'' pour soustraction future","Défier avec additions jusqu''à 15","Demander de comparer plusieurs stratégies sur même problème","Encourager à enseigner stratégie à un pair"],"pourLangue":["Associer chaque stratégie à gestes clairs et répétitifs","Utiliser vocabulaire avec images: commencer, continuer, stratégie","Permettre comptage dans L1 puis traduction en français","Fournir cartes visuelles avec étapes de chaque stratégie"],"pourPEI":["Adapter manipulatifs selon besoins moteurs","Modifier attentes de rapidité (focus sur précision)","Utiliser supports visuels constants et prévisibles","Ajuster selon besoins attentionnels avec pauses"]}','{"vocabulary":["compter","commencer","continuer","stratégie"],"visualSupports":["Affiche des doigts: comment montrer 1, 2, 3, 4, 5 clairement","Cartes de stratégies illustrées, ligne de nombres colorée, tableaux de comparaison: Rapide/Lent, Facile/Difficile","Tableau récapitulatif: ''Notre boîte à stratégies'' avec dessins des méthodes apprises"],"movementBreaks":["Répéter des comptines avec gestes : ''Tête, épaules, genoux et pieds'' (2 minutes)","Faire l''alphabet avec notre corps : A comme arbre (étirer les bras), B comme ballon (forme ronde) (3 minutes)","Danser avec les sons : ''a'' avec les bras, ''o'' en rond, ''i'' pointu (3 minutes)","Étirer nos doigts et mains d''écrivains : ouvrir, fermer, tourner (2 minutes)","Dire au revoir avec tout notre corps : mains, têtes, pieds (2 minutes)","Faire une révérence à nos nouvelles connaissances (1 minute)"]}',NULL,NULL,NULL,NULL,'{"questions":["Les élèves ont-ils atteint les objectifs?","Quelles adaptations étaient nécessaires?","Que ferais-je différemment la prochaine fois?"]}',NULL,'',2,3,'core',1);
INSERT INTO ETFOLessonPlan VALUES('cmf43u42n00rrvj9t5hum0tdf',23,'Nos doigts calculateurs','cmf43u42j00rjvj9t481uo6wk',1764000000000,45,'Danse des doigts: ''Nos doigts sont des calculateurs magiques! Montrez-moi 4... maintenant ajoutez 2...''','Techniques de doigts: Apprendre à représenter nombres sur doigts. Pratiquer additions simples. Utiliser miroirs pour voir stratégies. Comparer méthodes avec partenaires.','Exhibition de doigts: Élèves démontrent leur technique favorite et enseignent aux autres.','Ordonner le concept de nos doigts; Appliquer les concepts mathématiques de base; Développer le sens du nombre par la manipulation et le raisonnement','["Matériel de classe"]',NULL,'Nos doigts calculateurs','Danse des doigts: ''Nos doigts sont des calculateurs magiques! Montrez-moi 4... maintenant ajoutez 2...''','Techniques de doigts: Apprendre à représenter nombres sur doigts. Pratiquer additions simples. Utiliser miroirs pour voir stratégies. Comparer méthodes avec partenaires.','Exhibition de doigts: Élèves démontrent leur technique favorite et enseignent aux autres.','Ordonner le concept de nos doigts; Appliquer les concepts mathématiques de base; Développer le sens du nombre par la manipulation et le raisonnement',NULL,NULL,NULL,'formative','{"observable":["L''élève utilise ses doigts de manière systématique pour représenter des nombres et des opérations d''addition","L''élève montre la flexibilité dans l''utilisation de ses doigts (une main, deux mains, différentes configurations)","L''élève explique comment ses doigts l''aident à calculer en français","L''élève fait des connections entre les représentations avec les doigts et les quantités réelles","L''élève démontre une compréhension que les doigts sont un outil mathématique utile"],"checkpoints":["Utilise ses doigts efficacement pour représenter et calculer des additions jusqu''à 10","Explique comment l''utilisation des doigts aide dans les calculs mathématiques"]}',1,'Plan détaillé avec supports visuels',17