INSERT INTO ETFOLessonPlan VALUES('cmf43u42q00rzvj9tpon3ye1p',23,'Compter en avant intelligemment','cmf43u42j00rjvj9t481uo6wk',1764345600000,45,'Course de stratégies: ''Quelle méthode est plus rapide? 2+7 ou 7+2? Découvrons le secret!''','Comparaison de stratégies: Expérimenter ''tout compter'' vs ''compter à partir du plus grand''. Chronométrer pour voir efficacité. Pratiquer jusqu''à automatisation. Enseigner à un partenaire.','Conseillers en stratégie: Élèves donnent conseils sur quand utiliser quelle stratégie.','Mesurer le comptage avec stratégies; Appliquer les concepts mathématiques de base; Développer la pensée logique par la manipulation et le raisonnement','["Matériel de classe"]',NULL,'Compter en avant intelligemment','Course de stratégies: ''Quelle méthode est plus rapide? 2+7 ou 7+2? Découvrons le secret!''','Comparaison de stratégies: Expérimenter ''tout compter'' vs ''compter à partir du plus grand''. Chronométrer pour voir efficacité. Pratiquer jusqu''à automatisation. Enseigner à un partenaire.','Conseillers en stratégie: Élèves donnent conseils sur quand utiliser quelle stratégie.','Mesurer le comptage avec stratégies; Appliquer les concepts mathématiques de base; Développer la pensée logique par la manipulation et le raisonnement',NULL,NULL,NULL,'formative','{"observable":["L''élève utilise la stratégie de ''compter en avant'' à partir du plus grand nombre","L''élève explique pourquoi commencer avec le plus grand nombre est plus efficace","L''élève applique cette stratégie de manière consistante dans différents problèmes","L''élève démontre une compréhension que l''ordre des nombres n''affecte pas le résultat","L''élève utilise cette stratégie pour résoudre des problèmes d''addition jusqu''à 10"],"checkpoints":["Applique la stratégie de ''compter en avant'' à partir du plus grand nombre","Explique l''avantage de cette stratégie par rapport au comptage traditionnel"]}',1,'Plan détaillé avec supports visuels',1756911653667,1757587623111,1,'fr','Math