INSERT INTO ETFOLessonPlan VALUES('cmf43u42r00s1vj9tbb0n66l4',23,'Faire 10 - notre ancrage','cmf43u42j00rjvj9t481uo6wk',1764604800000,45,'Pouvoir de 10: ''Le nombre 10 est spécial! Il peut nous aider à calculer plus facilement! Regardez!''','Exploration de ''faire 10'': Décomposer nombres pour utiliser 10. Exemple: 7+5 = 7+3+2 = 10+2. Utiliser cadres et jetons visuellement. Pratiquer avec différents nombres.','Magiciens de 10: Élèves démontrent ''tours de magie'' en transformant additions difficiles avec 10.','Comparer le concept de faire 10; Appliquer les concepts mathématiques de base; Développer le raisonnement spatial par la manipulation et le raisonnement','["Matériel de classe"]',NULL,'Faire 10 - notre ancrage','Pouvoir de 10: ''Le nombre 10 est spécial! Il peut nous aider à calculer plus facilement! Regardez!''','Exploration de ''faire 10'': Décomposer nombres pour utiliser 10. Exemple: 7+5 = 7+3+2 = 10+2. Utiliser cadres et jetons visuellement. Pratiquer avec différents nombres.','Magiciens de 10: Élèves démontrent ''tours de magie'' en transformant additions difficiles avec 10.','Comparer le concept de faire 10; Appliquer les concepts mathématiques de base; Développer le raisonnement spatial par la manipulation et le raisonnement',NULL,NULL,NULL,'formative','{"observable":["L''élève comprend et utilise les combinaisons qui font 10 (1+9, 2+8, 3+7, 4+6, 5+5)","L''élève explique l''importance du nombre 10 comme point de référence","L''élève utilise les faits de ''faire 10'' pour résoudre d''autres problèmes d''addition","L''élève démontre une automaticité croissante avec les combinaisons de 10","L''élève fait des connections entre ''faire 10'' et le système de base dix"],"checkpoints":["Maîtrise les combinaisons de nombres qui font 10","Utilise les faits de ''faire 10'' comme stratégie pour d''autres additions"]}',1,'Plan détaillé avec supports visuels',1756911653668,1757587623131,1,'fr','Mathématiques','{"pourDifficultés":["Commencer avec un seul 10 déjà formé + petits nombres (10+1, 10+2)","Utiliser objets concrets en permanence","Se limiter à additions simples nécessitant ''faire 10''","Permettre plus de temps pour chaque étape"],"pourAvancés":["Explorer multiple façons de faire 10 dans une même équation","Défier avec additions jusqu''à 20 utilisant stratégie","Créer leurs propres problèmes ''faire 10''","Enseigner stratégie à élèves plus jeunes"],"pourLangue":["Emphasiser manipulations visuelles over explications verbales","Associer vocabulaire à actions: décomposer (séparer), transformer (changer)","Utiliser couleurs constantes pour étapes (rouge pour original, bleu pour transformé)","Permettre narration dans L1 du processus"],"pourPEI":["Adapter rythme selon capacités de traitement","Simplifier nombre d''étapes selon objectifs individuels","Utiliser supports tactiles pour concept abstrait","Fournir aide-mémoire visuel personnel"]}','{"vocabulary":["décomposer","faire dix","ancrage","transformer"],"visualSupports":["Affiche ''Le Pouvoir Magique de 10'' avec exemples: 6+4=10, 7+3=10, 8+2=10, 9+1=10","Cartes de décomposition, cadres de 10 doubles, flèches de transformation, poster étape par étape","Tableau ''Nos Tours de Magie avec 10'' pour documenter découvertes"],"movementBreaks":["Répéter des comptines avec gestes : ''Tête, épaules, genoux et pieds'' (2 minutes)","Marcher en syllabant notre nom : Ma-rie, Paul, etc. en tapant dans nos mains (2 minutes)","Danser avec les sons : ''a'' avec les bras, ''o'' en rond, ''i'' pointu (3 minutes)","Marcher sur place en récitant l''alphabet lentement (2 minutes)","Célébrer nos apprentissages : applaudir, lever les bras, sourire (2 minutes)","Étirer notre dos d''écrivains : rotation douce des épaules (2 minutes)"]}',NULL,NULL,NULL,NULL,'{"questions":["Les élèves ont-ils atteint les objectifs?","Quelles adaptations étaient nécessaires?","Que ferais-je différemment la prochaine fois?"]}',NULL,'',2,9,'core',1);
INSERT INTO ETFOLessonPlan VALUES('cmf43u42s00s3vj9t94raybzm',23,'Vérifier nos réponses','cmf43u42j00rjvj9t481uo6wk',1764691200000,45,'Détectives mathématiques: ''Comment savoir si notre réponse est correcte? Devenons des détectives des mathématiques!''','Méthodes de vérification: Recompter avec objets, utiliser stratégie différente, estimer avant calculer, vérifier avec calculatrice. Pratiquer détection d''erreurs intentionnelles.','Bureau de vérification: Élèves ''certifient'' le travail des autres en utilisant méthodes apprises.','Ordonner le concept de vérifier nos; Appliquer les concepts mathématiques de base; Développer le raisonnement spatial par la manipulation et le raisonnement','["Matériel de classe"]',NULL,'Vérifier nos réponses','Détectives mathématiques: ''Comment savoir si notre réponse est correcte? Devenons des détectives des mathématiques!''','Méthodes de vérification: Recompter avec objets, utiliser stratégie différente, estimer avant calculer, vérifier avec calculatrice. Pratiquer détection d''erreurs intentionnelles.','Bureau de vérification: Élèves ''certifient'' le travail des autres en utilisant méthodes apprises.','Ordonner le concept de vérifier nos; Appliquer les concepts mathématiques de base; Développer le raisonnement spatial par la manipulation et le raisonnement',NULL,NULL,NULL,'formative','{"observable":["L''élève utilise différentes méthodes pour vérifier ses réponses d''addition (recompter, utiliser des manipulatifs, méthode différente)","L''élève explique l''importance de vérifier son travail mathématique","L''élève identifie et corrige ses erreurs de manière autonome","L''élève développe l''habitude de vérifier systématiquement ses réponses","L''élève utilise le vocabulaire approprié pour expliquer ses méthodes de vérification"],"checkpoints":["Utilise au moins deux méthodes différentes pour vérifier ses réponses d''addition","Explique pourquoi il est important de vérifier son travail mathématique"]}',1,'Plan détaillé avec supports visuels',1756911653669,1757587623127,1,'fr','Mathématiques','{"pourDifficultés":["Se concentrer sur une seule méthode de vérification (recompter)","Utiliser seulement additions très simples pour vérification","Fournir aide-mémoire visuel des étapes","Permettre travail en paires pour soutien mutuel"],"pourAvancés":["Apprendre vérification par estimation (réponse raisonnable?)","Défier avec détection d''erreurs très subtiles","Créer leurs propres problèmes avec erreurs pour défier pairs","Expliquer pourquoi certaines erreurs sont communes"],"pourLangue":["Emphasiser méthodes visuelles de vérification","Associer vocabulaire à actions: vérifier (regarder deux fois), contrôler","Utiliser symboles visuels: ✓ pour correct, X pour erreur","Permettre explication des erreurs dans L1"],"pourPEI":["Adapter nombre de vérifications selon capacités attentionnelles","Modifier méthodes selon besoins cognitifs individuels","Utiliser supports technologiques si approprié","Ajuster critères de précision selon objectifs"]}','{"vocabulary":["vérifier","correct","erreur","contrôler"],"visualSupports":["Affiche ''Bureau d''Enquête Mathématique'' avec question: ''Est-ce que cette réponse a du sens?''","Affiches de méthodes de vérification, listes de contrôle, exemples d''erreurs communes, poster 4 étapes","Panneau ''Bureau de Vérification Officiel'', critères de certification affichés"],"movementBreaks":["Imiter les animaux des histoires : sauter comme un lapin, voler comme un oiseau (3 minutes)","Faire l''alphabet avec notre corps : A comme arbre (étirer les bras), B comme ballon (forme ronde) (3 minutes)","Danser avec les sons : ''a'' avec les bras, ''o'' en rond, ''i'' pointu (3 minutes)","Faire une pause lecture : s''étirer comme un chat qui se réveille (2 minutes)","Étirer notre dos d''écrivains : rotation douce des épaules (2 minutes)","Célébrer nos apprentissages : applaudir, lever les bras, sourire (2 minutes)"]}',NULL,NULL,NULL,NULL,'{"questions":["Les élèves ont-ils atteint les objectifs?","Quelles adaptations étaient nécessaires?","Que ferais-je différemment la prochaine fois?"]}',NULL,'',2,10,'core',1);
INSERT INTO ETFOLessonPlan VALUES('cmf43u42t00s5vj9ti8vk0e8p',23,'Découvrir les symboles + et =','cmf43u42j00rjvj9t481uo6wk',1764777600000,45,'Mystère des symboles: ''Ces signes mystérieux racontent des histoires mathématiques! Découvrons leurs secrets!''','Introduction symbolique: Connecter + avec ''assembler'' et = avec ''fait''. Construire équations avec objets puis symboles. Lire équations à haute voix. Créer équations personnelles.','Lecteurs d''équations: Élèves lisent leurs équations créées et expliquent signification des symboles.','Représenter le concept de découvrir les; Appliquer les concepts mathématiques de base; Développer le raisonnement spatial par la manipulation et le raisonnement','["Matériel de classe"]',NULL,'Découvrir les symboles + et =','Mystère des symboles: ''Ces signes mystérieux racontent des histoires mathématiques! Découvrons leurs secrets!''','Introduction symbolique: Connecter + avec ''assembler'' et = avec ''fait''. Construire équations avec objets puis symboles. Lire équations à haute voix. Créer équations personnelles.','Lecteurs d''équations: Élèves lisent leurs équations créées et expliquent signification des symboles.','Représenter le concept de découvrir les; Appliquer les concepts mathématiques de base; Développer le raisonnement spatial par la manipulation et le raisonnement',NULL,NULL,NULL,'formative','{"observable":["L''élève reconnaît et nomme les symboles + (plus) et = (égale) en français","L''élève utilise correctement les symboles + et = dans des équations simples","L''élève explique la signification des symboles + et = dans le contexte de l''addition","L''élève fait des connections entre les symboles mathématiques et les actions physiques","L''élève écrit des équations simples en utilisant les symboles appropriés"],"checkpoints":["Reconnaît et utilise correctement les symboles + et = dans des équations","Explique la signification des symboles mathématiques en français"]}',1,'Plan détaillé avec supports visuels',1756911653669,1757587623110,1,'fr','Mathématiques','{"pourDifficultés":["Commencer avec seulement le symbole +, retarder introduction de =","Utiliser couleurs différentes pour chaque symbole","Fournir guide visuel avec placement correct","Permettre usage d''objets concrets exclusivement"],"pourAvancés":["Introduire concept d''égalité (3+1 = 2+2)","Explorer équations avec trois nombres (2+3+1)","Créer équations pour défier leurs pairs","Découvrir propriété commutative (3+2 = 2+3)"],"pourLangue":["Associer chaque symbole à mot simple et geste","Utiliser couleurs constantes: + toujours rouge, = toujours bleu","Permettre lecture d''équation dans L1 puis français","Fournir cartes visuelles avec symboles et significations"],"pourPEI":["Adapter taille des symboles selon besoins visuels","Modifier nombre de symboles à apprendre selon objectifs","Utiliser supports tactiles pour symboles (relief, texture)","Ajuster rythme d''introduction selon capacités"]}','{"vocabulary":["plus","égale","équation","symbole"],"visualSupports":["Affiche ''Détectives des Symboles'' avec espaces pour découvertes","Symboles colorés géants, connexions visuelles objet-symbole, affiches: + signifie ''et'', = signifie ''fait''","Tableau collectif: ''Nos équations favorites'' pour afficher créations"],"movementBreaks":["Répéter des comptines avec gestes : ''Tête, épaules, genoux et pieds'' (2 minutes)","Former des lettres dans l''air avec nos doigts : A, B, C (3 minutes)","Danser avec les sons : ''a'' avec les bras, ''o'' en rond, ''i'' pointu (3 minutes)","Marcher sur place en récitant l''alphabet lentement (2 minutes)","Étirer notre dos d''écrivains : rotation douce des épaules (2 minutes)","Célébrer nos apprentissages : applaudir, lever les bras, sourire (2 minutes)"]}',NULL,NULL,NULL,NULL,'{"questions":["Les élèves ont-ils atteint les objectifs?","Quelles adaptations étaient nécessaires?","Que ferais-je différemment la prochaine fois?"]}',NULL,'',2,11,'core',1);
