INSERT INTO ETFOLessonPlan VALUES('cmf43u42x00sdvj9tniprs20d',23,'Art mathématique avec addition','cmf43u42j00rjvj9t481uo6wk',1765296000000,45,'Artistes-mathématiciens: ''L''art et les maths peuvent danser ensemble! Créons des œuvres mathématiques!''','Création artistique: Œuvres montrant additions visuellement. Collages de groupes assemblés. Peintures avec équations intégrées. Sculptures d''addition. Galerie interactive expliquée.','Vernissage mathématique: Exposition des créations avec explications artistiques et mathématiques.','Comparer l''addition avec manipulatifs; Appliquer des stratégies d''addition variées; Développer la résolution de problèmes par la manipulation et le raisonnement','["Matériel de classe"]',NULL,'Art mathématique avec addition','Artistes-mathématiciens: ''L''art et les maths peuvent danser ensemble! Créons des œuvres mathématiques!''','Création artistique: Œuvres montrant additions visuellement. Collages de groupes assemblés. Peintures avec équations intégrées. Sculptures d''addition. Galerie interactive expliquée.','Vernissage mathématique: Exposition des créations avec explications artistiques et mathématiques.','Comparer l''addition avec manipulatifs; Appliquer des stratégies d''addition variées; Développer la résolution de problèmes par la manipulation et le raisonnement',NULL,NULL,NULL,'formative','{"observable":["L''élève crée des œuvres d''art qui incorporent des concepts d''addition de manière créative","L''élève explique comment son art représente des problèmes ou des stratégies d''addition","L''élève fait des connections entre l''expression artistique et les concepts mathématiques","L''élève utilise des couleurs, formes ou patterns pour représenter des quantités et des opérations","L''élève présente son art mathématique en expliquant le processus de création"],"checkpoints":["Crée une œuvre d''art qui représente clairement des concepts d''addition","Explique les connections entre son art et les mathématiques en français"]}',1,'Pl