INSERT INTO ETFOLessonPlan VALUES('cmf43u43400srvj9tsw1n20t3',23,'Découvrir plus et moins','cmf43u43300spvj9tv746gurq',1773846000000,45,'Chanson d''introduction avec gestes: ''Plus de ceci, moins de cela, comparer c''est rigolo!'' Montrer ses mains: une avec beaucoup de doigts, une avec peu.','Jeu des bols magiques: Chaque élève a deux bols. Mettre 2 blocs dans un bol, 4 dans l''autre. Explorer en touchant, comptant. Répéter avec différentes quantités (3 vs 1, 5 vs 2).','Cercle de partage: Chaque élève montre une collection avec ''plus'' ou ''moins''. Chanson de fermeture: ''Plus ou moins, on a appris, bravo les amis!''','Identifier le concept de découvrir plus; Appliquer les concepts mathématiques de base; Développer le sens du nombre par la manipulation et le raisonnement','["Matériel de classe"]',NULL,'Découvrir plus et moins','Chanson d''introduction avec gestes: ''Plus de ceci, moins de cela, comparer c''est rigolo!'' Montrer ses mains: une avec beaucoup de doigts, une avec peu.','Jeu des bols magiques: Chaque élève a deux bols. Mettre 2 blocs dans un bol, 4 dans l''autre. Explorer en touchant, comptant. Répéter avec différentes quantités (3 vs 1, 5 vs 2).','Cercle de partage: Chaque élève montre une collection avec ''plus'' ou ''moins''. Chanson de fermeture: ''Plus ou moins, on a appris, bravo les amis!''','Identifier le concept de découvrir plus; Appliquer les concepts mathématiques de base; Développer le sens du nombre par la manipulation et le raisonnement',NULL,NULL,NULL,'formative','{"observable":["L''élève utilise le langage mathématique plus que et moins que de manière appropriée lors des comparaisons","L''élève manipule des objets concrets pour démontrer les concepts de plus et moins","L''élève identifie visuellement quelle collection contient plus ou moins d''objets","L''élève explique son raisonnement en utilisant des gestes et des mots simples","L''élève fait des liens entre les quantités et les mots mathématiques appropriés"],"checkpoints":["Reconnaît visuellement les différences de quantité entre deux collections","Utilise correctement plus que ou moins que dans des situations concrètes"]}',1,'Plan détaillé avec supports visuels',1756911653681,1757587623112,1,'fr','Mathématiques','{"pourDifficultés":["Commencer avec collections de seulement 2-3 objets très contrastés","Utiliser objets concrets identiques (tous blocs rouges vs tous blocs bleus)","Permettre comptage avec support d''un pair ou adulte","Accepter réponses gestuelles plutôt que verbales initialement"],"pourAvancés":["Explorer collections jusqu''à 8-10 objets","Prédire ''combien de plus'' ou ''combien de moins'' avant comptage","Créer leurs propres problèmes de comparaison pour les pairs","Utiliser vocabulaire précis: ''trois de plus que'', ''deux de moins que''"],"pourLangue":["Associer chaque mot français à geste corporel systématique","Utiliser objets culturellement familiers si possible","Permettre L1 pour explication, encourager répétition en français","Créer carte visuelle personnelle avec mots clés illustrés"],"pourPEI":["Adapter selon objectifs individuels (peut-être focus sur 1-3 seulement)","Utiliser supports sensoriels (textures différentes sur objets)","Permettre temps supplémentaire pour manipulation et observation","Collaborer avec éducateur spécialisé pour stratégies personnalisées"]}','{"vocabulary":["plus","moins","collection"],"visualSupports":["Affiches visuelles: sourire pour ''plus'', visage triste pour ''moins''. Gestes: mains ouvertes largement pour ''plus'', mains rapprochées pour ''moins''","Affiches visuelles: sourire pour ''plus'', visage triste pour ''moins''. Gestes: mains ouvertes largement pour ''plus'', mains rapprochées pour ''moins''","Cercle marqué au sol ou tapis de rassemblement, affichage récapitulatif des gestes plus/moins"],"movementBreaks":["Faire l''alphabet avec notre corps : A comme arbre (étirer les bras), B comme ballon (forme ronde) (3 minutes)","Répéter des comptines avec gestes : ''Tête, épaules, genoux et pieds'' (2 minutes)","Faire une pause lecture : s''étirer comme un chat qui se réveille (2 minutes)","Danser avec les sons : ''a'' avec les bras, ''o'' en rond, ''i'' pointu (3 minutes)","Célébrer nos apprentissages : applaudir, lever les bras, sourire (2 minutes)","Dire au revoir avec tout notre corps : mains, têtes, pieds (2 minutes)"]}',NULL,NULL,NULL,NULL,'{"questions":["Les élèves ont-ils atteint les objectifs?","Quelles adaptations étaient nécessaires?","Que ferais-je différemment la prochaine fois?"]}',NULL,'',2,1,'core',1);
INSERT INTO ETFOLessonPlan VALUES('cmf43u43500stvj9tbr68u5x6',23,'Aligner pour comparer','cmf43u43300spvj9tv746gurq',1773932400000,45,'Jeu d''alignement corporel: Les élèves se mettent en ligne par taille, puis comptent pour voir qui a ''plus'' d''élèves dans chaque rangée formée.','Station d''alignement: Sur tapis, placer 4 ours rouges en ligne, puis 6 ours bleus en ligne parallèle. Observer, compter, comparer. Répéter avec d''autres quantités. Les élèves manipulent et créent leurs propres alignements.','Galerie d''alignements: Élèves font le tour pour admirer les alignements créés. Chacun explique sa comparaison avec ''plus'' ou ''moins''.','Explorer le concept de aligner pour; Appliquer les concepts mathématiques de base; Développer le sens du nombre par la manipulation et le raisonnement','["Matériel de classe"]',NULL,'Aligner pour comparer','Jeu d''alignement corporel: Les élèves se mettent en ligne par taille, puis comptent pour voir qui a ''plus'' d''élèves dans chaque rangée formée.','Station d''alignement: Sur tapis, placer 4 ours rouges en ligne, puis 6 ours bleus en ligne parallèle. Observer, compter, comparer. Répéter avec d''autres quantités. Les élèves manipulent et créent leurs propres alignements.','Galerie d''alignements: Élèves font le tour pour admirer les alignements créés. Chacun explique sa comparaison avec ''plus'' ou ''moins''.','Explorer le concept de aligner pour; Appliquer les concepts mathématiques de base; Développer le sens du nombre par la manipulation et le raisonnement',NULL,NULL,NULL,'formative','{"observable":["L''élève aligne des objets de façon organisée pour faciliter la comparaison","L''élève utilise la correspondance un-à-un pour comparer deux collections","L''élève démontre la compréhension que l''alignement aide à voir les différences","L''élève explique pourquoi l''alignement rend la comparaison plus facile","L''élève applique cette stratégie spontanément lors de nouvelles situations"],"checkpoints":["Organise des objets en lignes parallèles pour comparer","Compare avec précision en utilisant la correspondance un-à-un"]}',1,'Plan détaillé avec supports visuels',1756911653681,1757587623117,1,'fr','Mathématiques','{"pourDifficultés":["Commencer avec seulement 2-4 objets par rangée","Utiliser objets très différents visuellement (grands blocs vs petits jetons)","Permettre aide de partenaire pour alignement","Fournir support physique (règle) pour alignement droit"],"pourAvancés":["Créer alignements jusqu''à 10 objets par rangée","Prédire le résultat de comparaison avant comptage","Créer des rangées de longueurs égales (même nombre)","Expliquer stratégies d''alignement aux autres"],"pourLangue":["Répéter vocabulaire ''aligner'', ''rangée'', ''ligne'' avec gestes","Utiliser objets culturellement significatifs si possible","Créer glossaire visuel personnel des termes géométriques","Permettre description en L1 puis traduire ensemble"],"pourPEI":["Adapter matériaux selon besoins moteurs (objets plus gros)","Utiliser repères tactiles pour alignement (texture sur tapis)","Permettre temps supplémentaire et pauses fréquentes","Simplifier à un seul critère de comparaison à la fois"]}','{"vocabulary":["aligner","voir","comparer"],"visualSupports":["Lignes au sol clairement marquées, signalisation visuelle pour ''rangée 1'' et ''rangée 2''","Tapis avec lignes tracées pour guider l''alignement. Flèches pointant vers les rangées pour diriger l''attention","Parcours de galerie marqué au sol, panneaux ''Galerie de comparaison''"],"movementBreaks":["Former des lettres dans l''air avec nos doigts : A, B, C (3 minutes)","Marcher en syllabant notre nom : Ma-rie, Paul, etc. en tapant dans nos mains (2 minutes)","Faire une pause lecture : s''étirer comme un chat qui se réveille (2 minutes)","Étirer nos doigts et mains d''écrivains : ouvrir, fermer, tourner (2 minutes)","Étirer notre dos d''écrivains : rotation douce des épaules (2 minutes)","Faire une révérence à nos nouvelles connaissances (1 minute)"]}',NULL,NULL,NULL,NULL,'{"questions":["Les élèves ont-ils atteint les objectifs?","Quelles adaptations étaient nécessaires?","Que ferais-je différemment la prochaine fois?"]}',NULL,'',2,2,'core',1);
INSERT INTO ETFOLessonPlan VALUES('cmf43u43600svvj9ta29vcb2u',23,'Grand et petit avec nos mains','cmf43u43300spvj9tv746gurq',1774018800000,45,'Chanson des tailles avec mouvements: ''Grand comme un éléphant'' (bras levés), ''Petit comme une souris'' (accroupi). Répéter avec différents animaux.','Centre d''exploration des tailles: Tables avec objets variés. Élèves touchent, soupèsent, comparent. Créer des paires ''grand/petit'' avec même type d''objet (grand livre/petit livre). Utiliser les mains pour ''mesurer'' et comparer.','Défilé des tailles: Élèves choisissent un objet grand et un petit, défilent en montrant la différence aux amis.','Découvrir le concept de grand et; Appliquer les concepts mathématiques de base; Développer le sens du nombre par la manipulation et le raisonnement','["Matériel de classe"]',NULL,'Grand et petit avec nos mains','Chanson des tailles avec mouvements: ''Grand comme un éléphant'' (bras levés), ''Petit comme une souris'' (accroupi). Répéter avec différents animaux.','Centre d''exploration des tailles: Tables avec objets variés. Élèves touchent, soupèsent, comparent. Créer des paires ''grand/petit'' avec même type d''objet (grand livre/petit livre). Utiliser les mains pour ''mesurer'' et comparer.','Défilé des tailles: Élèves choisissent un objet grand et un petit, défilent en montrant la différence aux amis.','Découvrir le concept de grand et; Appliquer les concepts mathématiques de base; Développer le sens du nombre par la manipulation et le raisonnement',NULL,NULL,NULL,'formative','{"observable":["L''élève utilise ses mains et son corps pour représenter les concepts de grand et petit","L''élève fait des comparaisons physiques appropriées entre les objets","L''élève verbalise les différences de taille en utilisant grand et petit","L''élève démontre la compréhension que la taille peut varier selon différentes dimensions","L''élève établit des connexions entre les manipulations physiques et les concepts mathématiques"],"checkpoints":["Représente physiquement les concepts de grand et petit","Verbalise les comparaisons de taille de manière appropriée"]}',1,'Plan détaillé avec supports visuels',1756911653682,1757587623118,1,'fr','Mathématiques','{"pourDifficultés":["Utiliser seulement objets avec différences de taille très évidentes","Commencer par comparaison tactile (toucher) avant visuelle","Fournir objets familiers de la vie quotidienne","Permettre tri en petits groupes avec support d''adulte"],"pourAvancés":["Introduire comparaisons à 3 critères (grand-moyen-petit)","Estimer et vérifier tailles avec unités non-standards (mains)","Créer collections ordonnées par taille progressive","Verbaliser relations de taille avec plus de précision"],"pourLangue":["Associer mots français à gestes très expressifs","Utiliser objets de leur culture d''origine pour comparaisons","Créer cartes visuelles bilingues grand/petit","Encourager description en L1 puis apprendre équivalent français"],"pourPEI":["Adapter objets selon capacités motrices (préhension facile)","Utiliser repères tactiles (textures) pour différencier tailles","Permettre temps d''exploration prolongé sans pression","Simplifier à une paire d''objets à la fois si nécessaire"]}','{"vocabulary":["grand","petit","taille"],"visualSupports":["Images d''animaux affichées au tableau, gestes corporels agrandis pour ''grand'' et ''petit''","Affiches d''animaux grands et petits. Gestes: bras écartés pour ''grand'', mains rapprochées pour ''petit''","Parcours de défilé marqué au sol, panneaux d''encouragement ''Bravo!''"],"movementBreaks":["Former des lettres dans l''air avec nos doigts : A, B, C (3 minutes)","Répéter des comptines avec gestes : ''Tête, épaules, genoux et pieds'' (2 minutes)","Étirer nos doigts et mains d''écrivains : ouvrir, fermer, tourner (2 minutes)","Faire des gestes de marionnettes pour raconter notre histoire (3 minutes)","Étirer notre dos d''écrivains : rotation douce des épaules (2 minutes)","Célébrer nos apprentissages : applaudir, lever les bras, sourire (2 minutes)"]}',NULL,NULL,NULL,NULL,'{"questions":["Les élèves ont-ils atteint les objectifs?","Quelles adaptations étaient nécessaires?","Que ferais-je différemment la prochaine fois?"]}',NULL,'',2,3,'core',1);
INSERT INTO ETFOLessonPlan VALUES('cmf43u43700sxvj9t6srw11fn',23,'Jeux de comparaison','cmf43u43300spvj9tv746gurq',1774278000000,45,'Échauffement de comparaison: Montrer deux cartes, élèves lèvent la main droite pour ''plus'' et gauche pour ''moins''. Démarrer lentement, accélérer graduellement.','Jeu ''Bataille de comparaison'': En paires, chaque élève retourne une carte. Celui qui a ''plus'' garde les deux cartes. Variante taille: comparer les objets sur les cartes pour ''grand'' vs ''petit''. Rotation des partenaires à mi-parcours.','Cercle de célébration: Chaque élève partage son moment préféré du jeu. Chanson: ''Jouer et comparer, c''est amusant!''','Ordonner le concept de jeux de; Participer à les concepts mathématiques de base; Développer le sens du nombre par le jeu dirigé','["Matériel de classe"]',NULL,'Jeux de comparaison','Échauffement de comparaison: Montrer deux cartes, élèves lèvent la main droite pour ''plus'' et gauche pour ''moins''. Démarrer lentement, accélérer graduellement.','Jeu ''Bataille de comparaison'': En paires, chaque élève retourne une carte. Celui qui a ''plus'' garde les deux cartes. Variante taille: comparer les objets sur les cartes pour ''grand'' vs ''petit''. Rotation des partenaires à mi-parcours.','Cercle de célébration: Chaque élève partage son moment préféré du jeu. Chanson: ''Jouer et comparer, c''est amusant!''','Ordonner le concept de jeux de; Participer à les concepts mathématiques de base; Développer le sens du nombre par le jeu dirigé',NULL,NULL,NULL,'formative','{"observable":["L''élève participe activement aux jeux de comparaison avec engagement","L''élève applique les règles des jeux de comparaison de manière autonome","L''élève utilise le vocabulaire mathématique approprié pendant les jeux","L''élève démontre une compréhension des stratégies de comparaison à travers le jeu","L''élève fait preuve de pensée critique lors des défis de comparaison"],"checkpoints":["Participe aux jeux en appliquant les concepts de comparaison","Utilise les stratégies apprises dans des contextes ludiques"]}',1,'Plan détaillé avec supports visuels',1756911653683,1757587623118,1,'fr','Mathématiques','{"pourDifficultés":["Utiliser cartes avec nombres 1-5 seulement pour simplifier","Permettre aide de partenaire plus fort pour lecture des cartes","Utiliser cartes avec points visuels plutôt que chiffres","Jouer en équipes plutôt qu''individuellement"],"pourAvancés":["Introduire calculs simples (différences entre cartes)","Utiliser cartes jusqu''à 15 ou 20","Créer règles additionnelles pour complexifier","Agir comme mentors pour élèves en difficulté"],"pourLangue":["Répéter vocabulaire de jeu avec gestes systématiques","Utiliser cartes avec images culturellement familières","Permettre explication des règles en L1 d''abord","Créer glossaire visuel des termes de jeu"],"pourPEI":["Adapter cartes selon besoins visuels (plus grandes, contrastées)","Permettre manipulation plus lente et répétitions","Utiliser supports tactiles si nécessaires","Ajuster règles selon objectifs individuels du PEI"]}','{"vocabulary":["jeu","carte","gagner"],"visualSupports":["Affiches côté droit = ''PLUS'', côté gauche = ''MOINS'', gestes manuels clairs","Affiches des règles du jeu avec images. Signaux visuels pour ''gagner'' (pouce en l''air) et ''égalité'' (mains plates)","Cercle de partage marqué au sol, affichage des mots positifs du jeu"],"movementBreaks":["Imiter les animaux des histoires : sauter comme un lapin, voler comme un oiseau (3 minutes)","Faire l''alphabet avec notre corps : A comme arbre (étirer les bras), B comme ballon (forme ronde) (3 minutes)","Danser avec les sons : ''a'' avec les bras, ''o'' en rond, ''i'' pointu (3 minutes)","Étirer nos doigts et mains d''écrivains : ouvrir, fermer, tourner (2 minutes)","Célébrer nos apprentissages : applaudir, lever les bras, sourire (2 minutes)","Étirer notre dos d''écrivains : rotation douce des épaules (2 minutes)"]}',NULL,NULL,NULL,NULL,'{"questions":["Les élèves ont-ils atteint les objectifs?","Quelles adaptations étaient nécessaires?","Que ferais-je différemment la prochaine fois?"]}',NULL,'',2,4,'core',1);
INSERT INTO ETFOLessonPlan VALUES('cmf43u43800szvj9t98r1tu3t',23,'Ordre croissant avec 3 objets','cmf43u43300spvj9tv746gurq',1774364400000,45,'Alignement physique: Trois élèves se placent en ordre de taille devant la classe. Les autres observent et commentent l''ordre ''petit, moyen, grand''.','Station d''ordonnancement: Présenter 3 collections mélangées (2 ours, 6 ours, 4 ours). Élèves les placent en ordre croissant en utilisant leurs mains pour vérifier. Répéter avec différentes combinaisons. Utiliser flèches pour montrer la direction ''croissant''.','Parade ordonnée: Élèves présentent leurs arrangements en expliquant ''petit, moyen, grand'' ou ''moins, plus, beaucoup''.','Représenter le concept de ordre croissant; Appliquer les concepts mathématiques de base; Développer la pensée logique par la manipulation et le raisonnement','["Matériel de classe"]',NULL,'Ordre croissant avec 3 objets','Alignement physique: Trois élèves se placent en ordre de taille devant la classe. Les autres observent et commentent l''ordre ''petit, moyen, grand''.','Station d''ordonnancement: Présenter 3 collections mélangées (2 ours, 6 ours, 4 ours). Élèves les placent en ordre croissant en utilisant leurs mains pour vérifier. Répéter avec différentes combinaisons. Utiliser flèches pour montrer la direction ''croissant''.','Parade ordonnée: Élèves présentent leurs arrangements en expliquant ''petit, moyen, grand'' ou ''moins, plus, beaucoup''.','Représenter le concept de ordre croissant; Appliquer les concepts mathématiques de base; Développer la pensée logique par la manipulation et le raisonnement',NULL,NULL,NULL,'formative','{"observable":["L''élève ordonne correctement trois objets du plus petit au plus grand","L''élève comprend le concept d''ordre croissant et peut l''expliquer","L''élève utilise des stratégies logiques pour déterminer la séquence","L''élève verbalise le processus d''ordonnancement en utilisant le vocabulaire approprié","L''élève reconnaît et corrige ses erreurs lors de l''ordonnancement"],"checkpoints":["Ordonne trois objets en ordre croissant sans aide","Explique le concept d''ordre croissant avec des exemples concrets"]}',1,'Plan détaillé avec supports visuels',1756911653684,1757587623119,1,'fr','Mathématiques','{"pourDifficultés":["Commencer avec seulement 2 collections très contrastées (1 vs 5)","Utiliser objets physiquement différents (gros bloc vs petit jeton)","Fournir support visuel avec emplacements numérotés","Permettre aide directe d''adulte pour placement initial"],"pourAvancés":["Utiliser 4-5 collections à ordonner simultanément","Prédire l''ordre avant manipulation","Créer leurs propres défis d''ordonnancement pour pairs","Utiliser vocabulaire ordonné: premier, deuxième, troisième, dernier"],"pourLangue":["Associer chaque position à geste numerique (1 doigt, 2 doigts, 3 doigts)","Répéter vocabulaire ordinal en français avec support visuel","Utiliser objets culturellement significatifs si disponibles","Créer séquence narrative simple: ''Bébé, enfant, adulte''"],"pourPEI":["Adapter matériaux selon capacités motrices (objets plus gros/légers)","Utiliser repères tactiles pour positions (textures différentes)","Permettre temps prolongé et répétitions multiples","Simplifier à une seule séquence à la fois si nécessaire"]}','{"vocabulary":["ordre","premier","dernier"],"visualSupports":["Ligne au sol pour alignement, cartes visuelles PETIT-MOYEN-GRAND affichées","Ligne numérique 1-6 affichée. Flèches montrant direction croissante. Images séquentielles pour modéliser","Zone de présentation délimitée, rappel visuel des mots clés petit-moyen-grand"],"movementBreaks":["Répéter des comptines avec gestes : ''Tête, épaules, genoux et pieds'' (2 minutes)","Faire l''alphabet avec notre corps : A comme arbre (étirer les bras), B comme ballon (forme ronde) (3 minutes)","Faire une pause lecture : s''étirer comme un chat qui se réveille (2 minutes)","Faire des gestes de marionnettes pour raconter notre histoire (3 minutes)","Étirer notre dos d''écrivains : rotation douce des épaules (2 minutes)","Dire au revoir avec tout notre corps : mains, têtes, pieds (2 minutes)"]}',NULL,NULL,NULL,NULL,'{"questions":["Les élèves ont-ils atteint les objectifs?","Quelles adaptations étaient nécessaires?","Que ferais-je différemment la prochaine fois?"]}',NULL,'',2,5,'core',1);
INSERT INTO ETFOLessonPlan VALUES('cmf43u43900t1vj9t9kxva6ph',23,'Construire des tours de comparaison','cmf43u43300spvj9tv746gurq',1774450800000,45,'Réveil des constructeurs: Mimer la construction d''une tour en empilant des blocs imaginaires, commencer petit et grandir progressivement avec sons ''ding!'' à chaque bloc.','Atelier de construction: En équipes de 2, construire 3 tours: une petite (2-3 blocs), une moyenne (4-5 blocs), une grande (6-8 blocs). Les placer en ordre de hauteur. Comparer avec autres équipes. Documenter avec photos.','Galerie des tours: Tour de classe pour admirer les créations. Chaque équipe explique son ordre de hauteur.','Compter le concept de construire des; Appliquer les concepts mathématiques de base; Développer la pensée logique par la manipulation et le raisonnement','["Matériel de classe"]',NULL,'Construire des tours de comparaison','Réveil des constructeurs: Mimer la construction d''une tour en empilant des blocs imaginaires, commencer petit et grandir progressivement avec sons ''ding!'' à chaque bloc.','Atelier de construction: En équipes de 2, construire 3 tours: une petite (2-3 blocs), une moyenne (4-5 blocs), une grande (6-8 blocs). Les placer en ordre de hauteur. Comparer avec autres équipes. Documenter avec photos.','Galerie des tours: Tour de classe pour admirer les créations. Chaque équipe explique son ordre de hauteur.','Compter le concept de construire des; Appliquer les concepts mathématiques de base; Développer la pensée logique par la manipulation et le raisonnement',NULL,NULL,NULL,'formative','{"observable":["L''élève construit des tours en respectant les principes de comparaison","L''élève utilise la manipulation pour explorer les relations de hauteur","L''élève compare visuellement les hauteurs des différentes constructions","L''élève explique ses choix lors de la construction des tours","L''élève démontre la persévérance lors de tâches de construction complexes"],"checkpoints":["Construit des tours qui démontrent la compréhension des comparaisons","Utilise la construction comme outil de comparaison visuelle"]}',1,'Plan détaillé avec supports visuels',1756911653685,1757587623119,1,'fr','Mathématiques','{"pourDifficultés":["Utiliser blocs plus gros et stables pour faciliter empilement","Permettre tours de 2 hauteurs seulement (petite vs grande)","Fournir support d''adulte pour techniques de construction","Utiliser base stable (boîte) pour commencer tour"],"pourAvancés":["Construire 4-5 tours de hauteurs distinctes","Utiliser techniques de construction plus complexes","Estimer nombre de blocs nécessaires avant construction","Créer tours avec motifs ou décorations ordonnées"],"pourLangue":["Répéter vocabulaire ‘haut’, ‘bas’, ‘tour’ avec gestes clairs","Utiliser comparaisons culturelles (tours de leur pays d''origine)","Permettre explication en L1 puis traduire ensemble","Créer glossaire illustré des termes de construction"],"pourPEI":["Adapter matériaux selon capacités motrices (blocs magnétiques si tremblements)","Utiliser supports visuels pour planifier avant construire","Permettre construction assistée ou avec partenaire","Ajuster attentes de hauteur selon capacités individuelles"]}','{"vocabulary":["tour","haut","bas"],"visualSupports":["Gestes de construction progressive, images de tours de hauteurs différentes","Exemples de tours photographiées en ordre. Graphique montrant progression des hauteurs","Parcours de galerie organisé, panneaux descriptifs pour chaque équipe"],"movementBreaks":["Imiter les animaux des histoires : sauter comme un lapin, voler comme un oiseau (3 minutes)","Faire l''alphabet avec notre corps : A comme arbre (étirer les bras), B comme ballon (forme ronde) (3 minutes)","Marcher sur place en récitant l''alphabet lentement (2 minutes)","Danser avec les sons : ''a'' avec les bras, ''o'' en rond, ''i'' pointu (3 minutes)","Célébrer nos apprentissages : applaudir, lever les bras, sourire (2 minutes)","Dire au revoir avec tout notre corps : mains, têtes, pieds (2 minutes)"]}',NULL,NULL,NULL,NULL,'{"questions":["Les élèves ont-ils atteint les objectifs?","Quelles adaptations étaient nécessaires?","Que ferais-je différemment la prochaine fois?"]}',NULL,'',2,6,'core',1);
INSERT INTO ETFOLessonPlan VALUES('cmf43u43a00t3vj9ttwkatfwo',23,'Ordre décroissant - du grand au petit','cmf43u43300spvj9tv746gurq',1774537200000,45,'Danse décroissante: Commencer debout avec bras levés (grand), graduellement s''accroupir (moyen), finir assis (petit). Répéter avec musique.','Défi décroissant: Présenter 4 collections mélangées (9, 3, 7, 5 objets). Élèves les ordonnent de ''beaucoup'' à ''peu''. Utiliser flèches descendantes pour guider. Comparer avec ordre croissant fait précédemment.','Présentation décroissante: Élèves montrent leur ordre en comptant à rebours ''beaucoup, moyen, peu, rien'' avec gestes.','Calculer le concept de ordre décroissant; Appliquer les concepts mathématiques de base; Développer la pensée logique par la manipulation et le raisonnement','["Matériel de classe"]',NULL,'Ordre décroissant - du grand au petit','Danse décroissante: Commencer debout avec bras levés (grand), graduellement s''accroupir (moyen), finir assis (petit). Répéter avec musique.','Défi décroissant: Présenter 4 collections mélangées (9, 3, 7, 5 objets). Élèves les ordonnent de ''beaucoup'' à ''peu''. Utiliser flèches descendantes pour guider. Comparer avec ordre croissant fait précédemment.','Présentation décroissante: Élèves montrent leur ordre en comptant à rebours ''beaucoup, moyen, peu, rien'' avec gestes.','Calculer le concept de ordre décroissant; Appliquer les concepts mathématiques de base; Développer la pensée logique par la manipulation et le raisonnement',NULL,NULL,NULL,'formative','{"observable":["L''élève ordonne correctement des objets du plus grand au plus petit","L''élève comprend la différence entre ordre croissant et décroissant","L''élève utilise le vocabulaire du grand au petit de manière appropriée","L''élève applique des stratégies logiques pour l''ordre décroissant","L''élève fait des liens entre les deux types d''ordonnancement"],"checkpoints":["Ordonne des objets en ordre décroissant avec précision","Distingue clairement entre ordre croissant et décroissant"]}',1,'Plan détaillé avec supports visuels',1756911653686,1757587623120,1,'fr','Mathématiques','{"pourDifficultés":["Commencer avec seulement 2-3 collections très contrastées","Utiliser objets physiquement très différents en taille/quantité","Fournir modèle visuel permanent d''ordre décroissant","Permettre manipulation assistée avec guidage verbal"],"pourAvancés":["Utiliser 5-6 collections avec différences plus subtiles","Créer ordres croissant ET décroissant simultanément","Prédire ordres avant manipulation physique","Enseigner concept aux pairs ayant difficultés"],"pourLangue":["Associer mots ‘décroissant’, ‘diminuer’ à gestes descendants clairs","Utiliser analogies culturelles (montagnes, cascades)","Créer cartes visuelles bilingues pour concepts d''ordre","Répéter vocabulaire avec supports kinesthésiques"],"pourPEI":["Adapter matériaux selon besoins sensoriels (textures, couleurs contrastées)","Utiliser supports visuels permanents pour référence","Permettre temps supplémentaire et répétitions","Simplifier à un critère à la fois si nécessaire"]}','{"vocabulary":["décroissant","diminuer","plus petit"],"visualSupports":["Démonstration gestuelle claire, escalier descendant dessiné au tableau","Flèches pointant vers le bas colorées. Exemples visuels d''ordre décroissant (escalier descendant)","Séquence visuelle beaucoup → moyen → peu → rien, gestes descendants"],"movementBreaks":["Former des lettres dans l''air avec nos doigts : A, B, C (3 minutes)","Marcher en syllabant notre nom : Ma-rie, Paul, etc. en tapant dans nos mains (2 minutes)","Danser avec les sons : ''a'' avec les bras, ''o'' en rond, ''i'' pointu (3 minutes)","Faire une pause lecture : s''étirer comme un chat qui se réveille (2 minutes)","Étirer notre dos d''écrivains : rotation douce des épaules (2 minutes)","Célébrer nos apprentissages : applaudir, lever les bras, sourire (2 minutes)"]}',NULL,NULL,NULL,NULL,'{"questions":["Les élèves ont-ils atteint les objectifs?","Quelles adaptations étaient nécessaires?","Que ferais-je différemment la prochaine fois?"]}',NULL,'',2,7,'core',1);
INSERT INTO ETFOLessonPlan VALUES('cmf43u43b00t5vj9t1jz9jobp',23,'Comparer avec les nombres 1-10','cmf43u43300spvj9tv746gurq',1774623600000,45,'Comptage rythmé: Compter de 1 à 10 en tapant des mains, puis de 10 à 1. Associer chaque nombre à un geste corporel.','Station numériques: Créer collections de 3, 7, et 5 jetons. Compter chaque collection, associer à carte numérique correspondante. Ordonner les cartes, puis vérifier en comparant les collections. Répéter avec nouvelles quantités tirées aux dés.','Défi numérique: Enseignant montre un nombre, élèves créent rapidement une collection correspondante et la comparent à leur voisin.','Mesurer les nombres de 0 à 10; Appliquer des stratégies de comptage efficaces; Développer la pensée logique par la manipulation et le raisonnement','["Matériel de classe"]',NULL,'Comparer avec les nombres 1-10','Comptage rythmé: Compter de 1 à 10 en tapant des mains, puis de 10 à 1. Associer chaque nombre à un geste corporel.','Station numériques: Créer collections de 3, 7, et 5 jetons. Compter chaque collection, associer à carte numérique correspondante. Ordonner les cartes, puis vérifier en comparant les collections. Répéter avec nouvelles quantités tirées aux dés.','Défi numérique: Enseignant montre un nombre, élèves créent rapidement une collection correspondante et la comparent à leur voisin.','Mesurer les nombres de 0 à 10; Appliquer des stratégies de comptage efficaces; Développer la pensée logique par la manipulation et le raisonnement',NULL,NULL,NULL,'formative','{"observable":["L''élève compare avec précision les nombres de 1 à 10","L''élève utilise des représentations visuelles pour soutenir ses comparaisons","L''élève verbalise les comparaisons numériques en utilisant le vocabulaire approprié","L''élève démontre la compréhension que les nombres plus grands représentent plus","L''élève applique les stratégies de comptage pour vérifier ses comparaisons"],"checkpoints":["Compare correctement tous les nombres de 1 à 10","Explique ses comparaisons en utilisant des références numériques"]}',1,'Plan détaillé avec supports visuels',1756911653687,1757587623121,1,'fr','Mathématiques','{"pourDifficultés":["Limiter à nombres 1-5 initialement","Utiliser correspondance un-à-un systématique (pointer chaque objet)","Fournir ligne numérique individuelle comme support","Permettre comptage avec aide d''adulte ou pair"],"pourAvancés":["Utiliser nombres jusqu''à 15-20","Introduire stratégies de comptage efficaces (groupements)","Créer problèmes de comparaison pour autres élèves","Estimer quantités avant comptage précis"],"pourLangue":["Répéter nombres en français avec gestes numériques","Utiliser comptage corporel (doigts, orteils) culturellement approprié","Créer cartes bilingues nombres/quantités","Permettre comptage en L1 puis traduction en français"],"pourPEI":["Adapter matériaux selon besoins sensoriels (textures, tailles d''objets)","Utiliser supports visuels et tactiles pour comptage","Permettre temps supplémentaire et pauses fréquentes","Ajuster objectifs numériques selon capacités individuelles"]}','{"vocabulary":["compter","combien","nombre"],"visualSupports":["Ligne numérique 1-10 avec gestes associés affichés","Ligne numérique 1-10 affichée. Cartes numériques colorées avec points correspondants","Cartes nombres géantes, références visuelles pour quantités"],"movementBreaks":["Répéter des comptines avec gestes : ''Tête, épaules, genoux et pieds'' (2 minutes)","Imiter les animaux des histoires : sauter comme un lapin, voler comme un oiseau (3 minutes)","Étirer nos doigts et mains d''écrivains : ouvrir, fermer, tourner (2 minutes)","Faire une pause lecture : s''étirer comme un chat qui se réveille (2 minutes)","Célébrer nos apprentissages : applaudir, lever les bras, sourire (2 minutes)","Étirer notre dos d''écrivains : rotation douce des épaules (2 minutes)"]}',NULL,NULL,NULL,NULL,'{"questions":["Les élèves ont-ils atteint les objectifs?","Quelles adaptations étaient nécessaires?","Que ferais-je différemment la prochaine fois?"]}',NULL,'',2,8,'core',1);
INSERT INTO ETFOLessonPlan VALUES('cmf43u43c00t7vj9tgf1t9bqz',23,'Dessiner pour comparer','cmf43u43300spvj9tv746gurq',1774882800000,45,'Dessin dans l''air: Dessiner des collections invisibles dans l''air en comptant. Commencer par 3 cercles, puis 5, puis montrer qu''ils sont différents.','Atelier d''illustration: Dessiner 3 collections différentes sur papier. Une avec 4 étoiles, une avec 4 cœurs (égal), une avec 7 triangles (plus). Utiliser objets concrets comme référence. Comparer avec partenaire et expliquer.','Galerie d''art mathématique: Afficher les dessins, élèves visitent et identifient les comparaisons dans chaque œuvre.','Comparer le concept de dessiner pour; Appliquer les concepts mathématiques de base; Développer le raisonnement spatial par la manipulation et le raisonnement','["Matériel de classe"]',NULL,'Dessiner pour comparer','Dessin dans l''air: Dessiner des collections invisibles dans l''air en comptant. Commencer par 3 cercles, puis 5, puis montrer qu''ils sont différents.','Atelier d''illustration: Dessiner 3 collections différentes sur papier. Une avec 4 étoiles, une avec 4 cœurs (égal), une avec 7 triangles (plus). Utiliser objets concrets comme référence. Comparer avec partenaire et expliquer.','Galerie d''art mathématique: Afficher les dessins, élèves visitent et identifient les comparaisons dans chaque œuvre.','Comparer le concept de dessiner pour; Appliquer les concepts mathématiques de base; Développer le raisonnement spatial par la manipulation et le raisonnement',NULL,NULL,NULL,'formative','{"observable":["L''élève crée des dessins qui représentent clairement les comparaisons","L''élève utilise des stratégies visuelles pour illustrer plus que, moins que, égal à","L''élève explique ses dessins en utilisant le vocabulaire mathématique","L''élève démontre la créativité dans ses représentations visuelles","L''élève fait des liens entre ses dessins et les concepts mathématiques"],"checkpoints":["Crée des représentations visuelles précises pour les comparaisons","Utilise le dessin comme outil de communication mathématique"]}',1,'Plan détaillé avec supports visuels',1756911653688,1757587623123,1,'fr','Mathématiques','{"pourDifficultés":["Fournir gabarits ou formes à tracer pour faciliter dessin","Commencer par collections très petites (1-3 objets)","Permettre utilisation d''autocollants au lieu de dessins","Accepter toute représentation graphique, même approximative"],"pourAvancés":["Créer illustrations plus complexes avec motifs ou détails","Dessiner collections jusqu''à 15-20 objets","Créer histoires visuelles incorporant comparaisons multiples","Utiliser couleurs stratégiquement pour montrer comparaisons"],"pourLangue":["Utiliser vocabulaire artistique simple en français (‘dessiner’, ‘colorier’)","Permettre étiquetage bilingue des créations","Incorporer symboles culturels familiers dans dessins","Encourager narration en L1 puis traduction des comparaisons"],"pourPEI":["Adapter outils selon besoins moteurs (crayons adaptés, supports)","Utiliser supports visuels et tactiles pour planification","Permettre créations collaboratives ou assistées","Valoriser processus créatif autant que résultat final"]}','{"vocabulary":["dessiner","égal","pareil"],"visualSupports":["Démonstration enseignant avec grands gestes, modèles de formes simples au tableau","Exemples de dessins simples affichés. Modèles de formes de base (cercle, carré, triangle)","Zone d''affichage dédiée ‘Galerie mathématique’, parcours de visite organisé"],"movementBreaks":["Marcher en syllabant notre nom : Ma-rie, Paul, etc. en tapant dans nos mains (2 minutes)","Faire l''alphabet avec notre corps : A comme arbre (étirer les bras), B comme ballon (forme ronde) (3 minutes)","Danser avec les sons : ''a'' avec les bras, ''o'' en rond, ''i'' pointu (3 minutes)","Faire des gestes de marionnettes pour raconter notre histoire (3 minutes)","Célébrer nos apprentissages : applaudir, lever les bras, sourire (2 minutes)","Étirer notre dos d''écrivains : rotation douce des épaules (2 minutes)"]}',NULL,NULL,NULL,NULL,'{"questions":["Les élèves ont-ils atteint les objectifs?","Quelles adaptations étaient nécessaires?","Que ferais-je différemment la prochaine fois?"]}',NULL,'',2,9,'core',1);
INSERT INTO ETFOLessonPlan VALUES('cmf43u43d00t9vj9thtabpn7a',23,'Égal ou différent?','cmf43u43300spvj9tv746gurq',1774969200000,45,'Balance humaine: Deux élèves tiennent même nombre d''objets, se balancent d''avant en arrière pour montrer ''équilibre''. Essayer avec nombres différents.','Centre de balance: Utiliser vraies balances avec objets. Placer 5 cubes d''un côté, essayer différentes quantités de l''autre côté jusqu''à équilibre. Découvrir que 5=5. Tester d''autres égalités. Utiliser cartes pour identifier ''égal'' ou ''différent''.','Concours d''égalité: Élèves créent rapidement des collections égales et vérifient avec partenaire. Célébrer toutes les réussites.','Ordonner le concept de égal ou; Appliquer les concepts mathématiques de base; Développer le raisonnement spatial par la manipulation et le raisonnement','["Matériel de classe"]',NULL,'Égal ou différent?','Balance humaine: Deux élèves tiennent même nombre d''objets, se balancent d''avant en arrière pour montrer ''équilibre''. Essayer avec nombres différents.','Centre de balance: Utiliser vraies balances avec objets. Placer 5 cubes d''un côté, essayer différentes quantités de l''autre côté jusqu''à équilibre. Découvrir que 5=5. Tester d''autres égalités. Utiliser cartes pour identifier ''égal'' ou ''différent''.','Concours d''égalité: Élèves créent rapidement des collections égales et vérifient avec partenaire. Célébrer toutes les réussites.','Ordonner le concept de égal ou; Appliquer les concepts mathématiques de base; Développer le raisonnement spatial par la manipulation et le raisonnement',NULL,NULL,NULL,'formative','{"observable":["L''élève identifie correctement quand deux collections sont égales","L''élève reconnaît les différences entre les collections inégales","L''élève utilise le vocabulaire égal et différent de manière appropriée","L''élève applique des stratégies de vérification pour confirmer l''égalité","L''élève explique son raisonnement lors de comparaisons d''égalité"],"checkpoints":["Détermine avec précision si deux collections sont égales ou différentes","Utilise des stratégies appropriées pour vérifier l''égalité"]}',1,'Plan détaillé avec supports visuels',1756911653689,1757587623124,1,'fr','Mathématiques','{"pourDifficultés":["Commencer avec très petites quantités (1=1, 2=2)","Utiliser objets identiques pour éviter confusion","Permettre correspondance un-à-un physique pour vérification","Fournir support visuel permanent pour concept ‘égal’"],"pourAvancés":["Explorer égalités avec objets de poids/tailles différents mais quantités égales","Créer égalités complexes (3+2 = 4+1)","Prédire équilibres avant test avec balance","Expliquer concept d''équilibre à pairs ayant difficultés"],"pourLangue":["Répéter vocabulaire ‘égal’, ‘même’, ‘pareil’ avec gestes d''équilibre","Utiliser concepts d''équilibre et partage culturellement pertinents","Créer cartes visuelles bilingues pour égalité/différence","Encourager explication en L1 puis traduction ensemble"],"pourPEI":["Adapter balances selon capacités motrices (balances plus stables)","Utiliser supports visuels et auditifs (balances avec sons)","Permettre exploration prolongée et répétitions","Ajuster attentes selon objectifs individuels"]}','{"vocabulary":["égal","même","différent"],"visualSupports":["Démonstration gestuelle d''équilibre vs déséquilibre, symboles visuels = et ≠","Affiches montrant balance équilibrée = égal, déséquilibrée = différent. Symboles visuels pour égalité","Zone de concours délimitée, tableau de célébration des égalités trouvées"],"movementBreaks":["Former des lettres dans l''air avec nos doigts : A, B, C (3 minutes)","Imiter les animaux des histoires : sauter comme un lapin, voler comme un oiseau (3 minutes)","Faire des gestes de marionnettes pour raconter notre histoire (3 minutes)","Marcher sur place en récitant l''alphabet lentement (2 minutes)","Étirer notre dos d''écrivains : rotation douce des épaules (2 minutes)","Faire une révérence à nos nouvelles connaissances (1 minute)"]}',NULL,NULL,NULL,NULL,'{"questions":["Les élèves ont-ils atteint les objectifs?","Quelles adaptations étaient nécessaires?","Que ferais-je différemment la prochaine fois?"]}',NULL,'',2,10,'core',1);
INSERT INTO ETFOLessonPlan VALUES('cmf43u43e00tbvj9taxduhaim',23,'Comparer jusqu''à 15','cmf43u43300spvj9tv746gurq',1775055600000,45,'Compte géant: Compter tous ensemble jusqu''à 15 en utilisant voix forte et gestes expressifs. Chaque multiple de 5, faire pause et applaudir.','Défi des grandes collections: Présenter bacs avec 8, 12, et 15 objets. Élèves comptent en groupant par 5 (comme doigts d''une main). Comparer les quantités et les ordonner. Vérifier en recomptant. Créer leurs propres grandes collections.','Parade des grandes collections: Chaque groupe présente sa plus grande collection et explique comment ils l''ont comptée.','Représenter le concept de comparer jusqu''à; Appliquer les concepts mathématiques de base; Développer le raisonnement spatial par la manipulation et le raisonnement','["Matériel de classe"]',NULL,'Comparer jusqu''à 15','Compte géant: Compter tous ensemble jusqu''à 15 en utilisant voix forte et gestes expressifs. Chaque multiple de 5, faire pause et applaudir.','Défi des grandes collections: Présenter bacs avec 8, 12, et 15 objets. Élèves comptent en groupant par 5 (comme doigts d''une main). Comparer les quantités et les ordonner. Vérifier en recomptant. Créer leurs propres grandes collections.','Parade des grandes collections: Chaque groupe présente sa plus grande collection et explique comment ils l''ont comptée.','Représenter le concept de comparer jusqu''à; Appliquer les concepts mathématiques de base; Développer le raisonnement spatial par la manipulation et le raisonnement',NULL,NULL,NULL,'formative','{"observable":["L''élève étend ses compétences de comparaison aux nombres jusqu''à 15","L''élève utilise des stratégies de comptage efficaces pour les nombres plus grands","L''élève maintient la précision lors de comparaisons avec des quantités plus importantes","L''élève adapte ses stratégies visuelles aux nombres plus grands","L''élève démontre la confiance lors de comparaisons avec des nombres étendus"],"checkpoints":["Compare avec précision les nombres jusqu''à 15","Adapte ses stratégies aux quantités plus importantes"]}',1,'Plan détaillé avec supports visuels',1756911653690,1757587623124,1,'fr','Mathématiques','{"pourDifficultés":["Réduire à quantités 5-10 maximum initialement","Utiliser objets très grands et faciles à manipuler","Permettre comptage assisté avec support d''adulte","Grouper par 2 ou 3 au lieu de 5 si nécessaire"],"pourAvancés":["Explorer quantités jusqu''à 20-25 objets","Utiliser stratégies multiples (grouper par 2, 5, ou 10)","Créer défis de comptage pour autres élèves","Estimer quantités avant comptage et vérifier précision"],"pourLangue":["Répéter nombres 11-15 en français avec gestes","Utiliser comptage corporel (doigts, orteils) pour support","Permettre comptage en L1 puis traduction en français","Créer cartes visuelles bilingues pour grandes quantités"],"pourPEI":["Adapter objets selon besoins moteurs (plus gros, textures)","Utiliser supports visuels permanents pour stratégies comptage","Permettre temps prolongé et pauses fréquentes","Ajuster objectifs quantitatifs selon capacités"]}','{"vocabulary":["beaucoup","plusieurs","grouper"],"visualSupports":["Ligne numérique 1-15 avec multiples de 5 en couleur vive","Modèles de groupement par 5 affichés. Ligne numérique jusqu''à 15 avec marques aux multiples de 5","Zone de présentation dédiée, affichage des stratégies de comptage découvertes"],"movementBreaks":["Faire l''alphabet avec notre corps : A comme arbre (étirer les bras), B comme ballon (forme ronde) (3 minutes)","Imiter les animaux des histoires : sauter comme un lapin, voler comme un oiseau (3 minutes)","Faire des gestes de marionnettes pour raconter notre histoire (3 minutes)","Danser avec les sons : ''a'' avec les bras, ''o'' en rond, ''i'' pointu (3 minutes)","Faire une révérence à nos nouvelles connaissances (1 minute)","Célébrer nos apprentissages : applaudir, lever les bras, sourire (2 minutes)"]}',NULL,NULL,NULL,NULL,'{"questions":["Les élèves ont-ils atteint les objectifs?","Quelles adaptations étaient nécessaires?","Que ferais-je différemment la prochaine fois?"]}',NULL,'',2,11,'core',1);
INSERT INTO ETFOLessonPlan VALUES('cmf43u43f00tdvj9th3oi4jhq',23,'Régularités dans l''ordre','cmf43u43300spvj9tv746gurq',1775142000000,45,'Séquence corporelle: Faire séquence ''petit-moyen-grand'' avec positions du corps. Répéter plusieurs fois, puis demander aux élèves de prédire la suivante.','Atelier de séquences: Créer séquences avec objets (petit bloc, moyen bloc, grand bloc, petit bloc...). Élèves continuent la séquence et expliquent la règle. Créer leurs propres séquences pour que partenaires devinent la suite.','Défilé de séquences: Élèves présentent leurs créations en expliquant la règle. Classe essaie de continuer chaque séquence.','Compter le concept de régularités dans; Appliquer les concepts mathématiques de base; Développer le raisonnement spatial par la manipulation et le raisonnement','["Matériel de classe"]',NULL,'Régularités dans l''ordre','Séquence corporelle: Faire séquence ''petit-moyen-grand'' avec positions du corps. Répéter plusieurs fois, puis demander aux élèves de prédire la suivante.','Atelier de séquences: Créer séquences avec objets (petit bloc, moyen bloc, grand bloc, petit bloc...). Élèves continuent la séquence et expliquent la règle. Créer leurs propres séquences pour que partenaires devinent la suite.','Défilé de séquences: Élèves présentent leurs créations en expliquant la règle. Classe essaie de continuer chaque séquence.','Compter le concept de régularités dans; Appliquer les concepts mathématiques de base; Développer le raisonnement spatial par la manipulation et le raisonnement',NULL,NULL,NULL,'formative','{"observable":["L''élève identifie des régularités dans les séquences ordonnées","L''élève prédit les éléments suivants dans une régularité établie","L''élève crée ses propres régularités en utilisant l''ordre","L''élève explique les règles qui gouvernent les régularités observées","L''élève fait des liens entre l''ordre et les motifs répétitifs"],"checkpoints":["Reconnaît et continue des régularités simples basées sur l''ordre","Crée des régularités originales en utilisant des principes d''ordonnancement"]}',1,'Plan détaillé avec supports visuels',1756911653691,1757587623125,1,'fr','Mathématiques','{"pourDifficultés":["Utiliser séquences très simples à 2 éléments (AB, AB)","Fournir début de séquence plus long avant demander continuation","Utiliser objets très contrastés visuellement","Permettre manipulation guidée avec support d''adulte"],"pourAvancés":["Créer séquences complexes à 3-4 éléments (ABC, ABCD)","Introduire séquences croissantes/décroissantes","Créer séquences avec multiples attributs (taille ET couleur)","Enseigner concepts de régularité à pairs en difficulté"],"pourLangue":["Répéter vocabulaire ‘séquence’, ‘continuer’, ‘suivant’ avec gestes","Utiliser séquences culturellement significatives si possible","Créer glossaire visuel des termes de régularité","Permettre explication des règles en L1 puis traduction"],"pourPEI":["Adapter matériaux selon besoins moteurs et sensoriels","Utiliser supports visuels permanents pour types de séquences","Permettre temps prolongé pour découverte de règles","Simplifier à un attribut à la fois (seulement taille, pas couleur)"]}','{"vocabulary":["séquence","continuer","suivant"],"visualSupports":["Cartes de positions corporelles affichées en séquence, flèches de progression","Exemples de séquences affichés avec flèches montrant progression. Cartes aide-mémoire pour types de séquences","Espace d''exposition temporaire, tableau pour noter séquences présentées"],"movementBreaks":["Répéter des comptines avec gestes : ''Tête, épaules, genoux et pieds'' (2 minutes)","Former des lettres dans l''air avec nos doigts : A, B, C (3 minutes)","Faire une pause lecture : s''étirer comme un chat qui se réveille (2 minutes)","Faire des gestes de marionnettes pour raconter notre histoire (3 minutes)","Faire une révérence à nos nouvelles connaissances (1 minute)","Dire au revoir avec tout notre corps : mains, têtes, pieds (2 minutes)"]}',NULL,NULL,NULL,NULL,'{"questions":["Les élèves ont-ils atteint les objectifs?","Quelles adaptations étaient nécessaires?","Que ferais-je différemment la prochaine fois?"]}',NULL,'',2,12,'core',1);
INSERT INTO ETFOLessonPlan VALUES('cmf43u43f00tfvj9tjcmc0x77',23,'Ordonner 5 objets différents','cmf43u43300spvj9tv746gurq',1775228400000,45,'File indienne à 5: Cinq élèves se placent en ordre de taille. Autres observent et commentent. Réorganiser selon d''autres critères (âge, longueur des cheveux).','Défi des 5 éléments: Présenter 5 collections mélangées (2, 5, 8, 3, 7 objets). Élèves les ordonnent de plus petit à plus grand. Répéter avec 5 objets de tailles différentes. Essayer ordre décroissant. Créer leurs propres défis à 5 éléments.','Exposition des 5: Chaque groupe affiche son ordre de 5 éléments et explique son critère d''organisation.','Calculer le concept de ordonner 5; Appliquer les concepts mathématiques de base; Développer la résolution de problèmes par la manipulation et le raisonnement','["Matériel de classe"]',NULL,'Ordonner 5 objets différents','File indienne à 5: Cinq élèves se placent en ordre de taille. Autres observent et commentent. Réorganiser selon d''autres critères (âge, longueur des cheveux).','Défi des 5 éléments: Présenter 5 collections mélangées (2, 5, 8, 3, 7 objets). Élèves les ordonnent de plus petit à plus grand. Répéter avec 5 objets de tailles différentes. Essayer ordre décroissant. Créer leurs propres défis à 5 éléments.','Exposition des 5: Chaque groupe affiche son ordre de 5 éléments et explique son critère d''organisation.','Calculer le concept de ordonner 5; Appliquer les concepts mathématiques de base; Développer la résolution de problèmes par la manipulation et le raisonnement',NULL,NULL,NULL,'formative','{"observable":["L''élève ordonne avec précision cinq objets selon différents critères","L''élève applique des stratégies logiques pour les séquences plus complexes","L''élève démontre la persévérance lors de tâches d''ordonnancement plus difficiles","L''élève vérifie son travail et fait des ajustements au besoin","L''élève explique ses critères d''ordonnancement clairement"],"checkpoints":["Ordonne correctement cinq objets selon le critère donné","Applique des stratégies systématiques pour les tâches plus complexes"]}',1,'Plan détaillé avec supports visuels',1756911653692,1757587623125,1,'fr','Mathématiques','{"pourDifficultés":["Réduire à 3-4 éléments maximum initialement","Utiliser un seul critère très évident (taille très contrastée)","Fournir emplacements numérotés et guidés visuellement","Permettre classement assisté avec aide d''adulte"],"pourAvancés":["Utiliser 6-7 éléments à ordonner simultanément","Introduire multiples critères (taille ET couleur)","Créer systèmes de classement pour toute la classe","Expliquer stratégies d''organisation aux autres"],"pourLangue":["Répéter vocabulaire ‘critère’, ‘organiser’, ‘classer’ avec exemples concrets","Utiliser objets culturellement familiers pour classements","Créer cartes visuelles bilingues pour termes d''organisation","Permettre explication de logique en L1 puis traduction"],"pourPEI":["Adapter matériaux selon capacités motrices et cognitives","Utiliser supports visuels permanents pour types d''ordres","Permettre temps prolongé et approche étape par étape","Simplifier objectifs selon capacités individuelles"]}','{"vocabulary":["critère","organiser","classer"],"visualSupports":["Cartes de critères affichées, ligne au sol pour alignement","Exemples d''ordres à 5 éléments affichés. Numéros 1-5 pour marquer positions","Espace d''exposition organisé, étiquettes pour expliquer critères d''organisation"],"movementBreaks":["Marcher en syllabant notre nom : Ma-rie, Paul, etc. en tapant dans nos mains (2 minutes)","Répéter des comptines avec gestes : ''Tête, épaules, genoux et pieds'' (2 minutes)","Étirer nos doigts et mains d''écrivains : ouvrir, fermer, tourner (2 minutes)","Faire une pause lecture : s''étirer comme un chat qui se réveille (2 minutes)","Étirer notre dos d''écrivains : rotation douce des épaules (2 minutes)","Célébrer nos apprentissages : applaudir, lever les bras, sourire (2 minutes)"]}',NULL,NULL,NULL,NULL,'{"questions":["Les élèves ont-ils atteint les objectifs?","Quelles adaptations étaient nécessaires?","Que ferais-je différemment la prochaine fois?"]}',NULL,'',2,13,'core',1);
INSERT INTO ETFOLessonPlan VALUES('cmf43u43g00thvj9ty56ur6l7',23,'Problèmes de comparaison','cmf43u43300spvj9tv746gurq',1775487600000,45,'Histoire-problème collective: ''Marie a 3 pommes, Jean a 5 pommes. Qui en a plus?'' Résoudre ensemble avec objets concrets et gestes.','Centre de résolution: Stations avec problèmes illustrés simples. Ex: ''Pour faire des équipes égales pour un jeu, combien d''enfants dans chaque équipe?'' Utiliser objets pour tester solutions. Expliquer raisonnement à partenaire.','Partage de solutions: Élèves présentent un problème résolu et expliquent leur démarche. Célébrer toutes les stratégies.','Mesurer le concept de problèmes de; Appliquer les concepts mathématiques de base; Développer la résolution de problèmes par la manipulation et le raisonnement','["Matériel de classe"]',NULL,'Problèmes de comparaison','Histoire-problème collective: ''Marie a 3 pommes, Jean a 5 pommes. Qui en a plus?'' Résoudre ensemble avec objets concrets et gestes.','Centre de résolution: Stations avec problèmes illustrés simples. Ex: ''Pour faire des équipes égales pour un jeu, combien d''enfants dans chaque équipe?'' Utiliser objets pour tester solutions. Expliquer raisonnement à partenaire.','Partage de solutions: Élèves présentent un problème résolu et expliquent leur démarche. Célébrer toutes les stratégies.','Mesurer le concept de problèmes de; Appliquer les concepts mathématiques de base; Développer la résolution de problèmes par la manipulation et le raisonnement',NULL,NULL,NULL,'formative','{"observable":["L''élève comprend les problèmes écrits impliquant des comparaisons","L''élève identifie les informations importantes dans les problèmes de comparaison","L''élève applique des stratégies appropriées pour résoudre les problèmes","L''élève explique son processus de résolution de manière claire","L''élève vérifie ses réponses en utilisant différentes stratégies"],"checkpoints":["Résout des problèmes simples de comparaison avec support","Explique sa démarche de résolution de problèmes"]}',1,'Plan détaillé avec supports visuels',1756911653693,1757587623126,1,'fr','Mathématiques','{"pourDifficultés":["Utiliser problèmes très simples avec nombres 1-5 seulement","Fournir objets concrets abondants pour toute manipulation","Permettre résolution assistée avec guidance étape par étape","Accepter solutions partielles et valoriser processus de réflexion"],"pourAvancés":["Proposer problèmes multi-étapes ou avec nombres plus grands","Encourager recherche de multiples solutions au même problème","Demander création de problèmes originaux pour pairs","Introduire stratégies de vérification plus sophistiquées"],"pourLangue":["Simplifier langage des problèmes, utiliser vocabulaire familier","Permettre explication de raisonnement en L1 puis traduction","Utiliser problèmes avec contextes culturellement pertinents","Fournir glossaire illustré des termes de résolution de problèmes"],"pourPEI":["Adapter problèmes selon capacités cognitives et intérêts","Utiliser supports visuels et concrets abondants","Permettre temps prolongé et approche individualisée","Collaborer avec éducateur spécialisé pour adaptations"]}','{"vocabulary":["problème","solution","résoudre"],"visualSupports":["Cartes de personnages affichées, objets concrets groupés visuellement","Cartes-problèmes avec images claires. Étapes de résolution affichées: lire, manipuler, vérifier, expliquer","Espace de présentation, collection des stratégies partagées"],"movementBreaks":["Marcher en syllabant notre nom : Ma-rie, Paul, etc. en tapant dans nos mains (2 minutes)","Faire l''alphabet avec notre corps : A comme arbre (étirer les bras), B comme ballon (forme ronde) (3 minutes)","Marcher sur place en récitant l''alphabet lentement (2 minutes)","Faire des gestes de marionnettes pour raconter notre histoire (3 minutes)","Célébrer nos apprentissages : applaudir, lever les bras, sourire (2 minutes)","Étirer notre dos d''écrivains : rotation douce des épaules (2 minutes)"]}',NULL,NULL,NULL,