INSERT INTO ETFOLessonPlan VALUES('cmf43u44400utvj9tewnx40nu',23,'Égalité dans la nature','cmf43u43o00tvvj9ttyd3giia',1781017200000,45,'Observation de la nature - regarder des images d''éléments naturels symétriques','Exploration extérieure ou observation d''éléments naturels, création d''équations basées sur observations','Musée de nature - présenter sa découverte d''égalité naturelle favorite','Représenter le concept de égalité dans; Appliquer les concepts mathématiques de base; Développer les stratégies de calcul par la manipulation et le raisonnement','["photos de nature","loupes","carnet d''explorateur","objets naturels collectés","règles","papier","crayons","balance","boîte de rangement pour travaux (1 grande boîte)","certificats d''encouragement (30 copies)","étiquettes autocollantes (2 planches)"]',NULL,'Égalité dans la nature','Observation de la nature - regarder des images d''éléments naturels symétriques','Exploration extérieure ou observation d''éléments naturels, création d''équations basées sur observations','Musée de nature - présenter sa découverte d''égalité naturelle favorite','Représenter le concept de égalité dans; Appliquer les concepts mathématiques de base; Développer les stratégies de calcul par la manipulation et le raisonnement',NULL,NULL,NULL,'formative','{"observable":["L''élève identifie des exemples d''égalité dans la nature","L''élève fait des connections entre les mathématiques et l''environnement","L''élève utilise des éléments naturels pour créer des équations","L''élève démontre une appréciation pour les patterns naturels"],"checkpoints":["Trouve des exemples d''égalité dans la nature","Crée des équations en utilisant des éléments naturels"]}',1,'Plan détaillé avec supports visuels',1756911653716,1757587623267,1,'fr','Mathématiques','{"pourDifficultés":["Symétrie très évidente (visage, papillon)","Objets naturels simples","Focus sur observation plutôt que quantification","Support visuel constant"],"pourAvancés":["Mesurer et quantif