INSERT INTO ETFOLessonPlan VALUES('cmf43u44n00vxvj9tp717pk5t',23,'Formes et solides dans les métiers','cmf43u44800v1vj9t0sfu0ir3',1760972400000,45,'Présentation de photos de professionnels utilisant des formes dans leur travail','Jeu de rôle : les élèves ''travaillent'' comme différents professionnels utilisant les formes','Discussion : quel métier les intéresse et comment ils utiliseraient les formes','Comparer les formes géométriques de base; Appliquer la reconnaissance des formes géométriques; Développer la résolution de problèmes par la manipulation et le raisonnement','["Matériel de classe"]',NULL,'Formes et solides dans les métiers','Présentation de photos de professionnels utilisant des formes dans leur travail','Jeu de rôle : les élèves ''travaillent'' comme différents professionnels utilisant les formes','Discussion : quel métier les intéresse et comment ils utiliseraient les formes','Comparer les formes géométriques de base; Appliquer la reconnaissance des formes géométriques; Développer la résolution de problèmes par la manipulation et le raisonnement',NULL,NULL,NULL,'formative','{"observable":["Élève intègre formes géométriques apprises dans sa création artistique personnelle","Élève utilise techniques artistiques variées (peinture, collage, assemblage) avec intention","Élève nomme les formes utilisées dans son œuvre avec vocabulaire approprié","Élève explique ses choix créatifs et décrit son processus artistique","Élève fait preuve de fierté et de plaisir dans sa création finale"],"checkpoints":["Pendant planification : observer capacité à envisager intégration des formes géométriques","Pendant création : noter utilisation créative des apprentissages et techniques artistiques","Pendant vernissage : évaluer capacité à présenter et décrire son œuvre avec vocabulaire géométrique"]}',1,'Plan détaillé avec supports visuels',1756911653735,1757594654343,1,'fr','Mathématiques','{"pourDifficultés":["Se concentrer sur 2-3 métiers très familiers (cuisinier, constructeur) avec liens évidents","Utiliser objets très concrets et reconnaissables dans jeu de rôle","Permettre observation passive avant participation active aux stations","Simplifier liens: cette personne utilise des cercles, cette personne utilise des carrés"],"pourAvancés":["Explorer métiers moins évidents utilisant géométrie (designer, ingénieur, artiste)","Analyser comment formes influencent fonctionnalité (roue ronde pour rouler, mur carré pour solidité)","Créer liens entre différents métiers partageant mêmes formes géométriques","Proposer d''inventer nouveau métier utilisant formes spécifiques"],"pourLangue":["Associer chaque métier à gestes et actions concrètes (cuisiner, construire, mesurer)","Utiliser photos et démonstrations visuelles plutôt qu''explications verbales longues","Permettre expression en langue première puis traduction simple des métiers connus","Fournir cartes visuelles: métier + outil + forme utilisée"],"pourPEI":["Adapter participation selon capacités: observer, manipuler outils, ou décrire","Utiliser métiers familiers du milieu de vie de l''élève","Ajuster intensité sensorielle des stations selon tolérance","Proposer rôles alternatifs si manipulation d''outils difficile"]}','{"vocabulary":["métier","architecte","utiliser"],"visualSupports":["Images claires et diverses montrant architectes, chefs, mécaniciens, artistes au travail avec formes géométriques visibles","Stations de métiers clairement étiquetées avec instructions visuelles et exemples de réalisations","Récapitulatif visuel des métiers explorés avec exemples de formes associées"],"movementBreaks":["Imiter les animaux des histoires : sauter comme un lapin, voler comme un oiseau (3 minutes)","Faire l''alphabet avec notre corps : A comme arbre (étirer les bras), B comme ballon (forme ronde) (3 minutes)","Danser avec les sons : ''a'' avec les bras, ''o'' en rond, ''i'' pointu (3 minutes)","Marcher sur place en récitant l''alphabet lentement (2 minutes)","Faire une révérence à nos nouvelles connaissances (1 minute)","Étirer notre dos d''écrivains : rotation douce des épaules (2 minutes)"]}',NULL,NULL,NULL,NULL,'{"questions":["Les élèves ont-ils atteint les objectifs?","Quelles adaptations étaient nécessaires?","Que ferais-je différemment la prochaine fois?"]}',NULL,'',2,15,'extension',1);
INSERT INTO ETFOLessonPlan VALUES('cmf43u44n00vzvj9tsmghhg2e',23,'Danse et mouvement avec les formes','cmf43u44800v1vj9t0sfu0ir3',1761058800000,45,'Échauffement corporel : imiter les formes avec tout le corps','Chorégraphie créative où les mouvements représentent les propriétés des formes','Performance finale : présentation des danses de formes devant la classe','Ordonner les formes géométriques de base; Appliquer la reconnaissance des formes géométriques; Développer la résolution de problèmes par la manipulation et le raisonnement','["instruments de musique simples","accessoires de danse","chemises individuelles (30 chemises)","étiquettes autocollantes (2 planches)","boîte de rangement pour travaux (1 grande boîte)"]',NULL,'Danse et mouvement avec les formes','Échauffement corporel : imiter les formes avec tout le corps','Chorégraphie créative où les mouvements représentent les propriétés des formes','Performance finale : présentation des danses de formes devant la classe','Ordonner les formes géométriques de base; Appliquer la reconnaissance des formes géométriques; Développer la résolution de problèmes par la manipulation et le raisonnement',NULL,NULL,NULL,'formative','{"observable":["Élève identifie au moins 2 métiers utilisant formes géométriques dans leur travail","Élève établit liens logiques entre formes et usage professionnel","Élève participe au jeu de rôle en imitant actions professionnelles appropriées","Élève utilise vocabulaire des métiers et des formes de façon contextuelle","Élève exprime intérêt ou curiosité pour découvrir d''autres métiers"],"checkpoints":["Pendant présentation : noter reconnaissance des métiers et formes dans photos","Pendant stations : observer qualité du jeu de rôle et compréhension des liens","Pendant discussion : évaluer capacité à verbaliser connexions métiers-géométrie"]}',1,'Plan détaillé avec supports visuels',1756911653736,1757594654344,1,'fr','Mathématiques','{"pourDifficultés":["Commencer par mouvements simples avec mains seulement avant corps entier","Permettre imitation directe des gestes de l''enseignant plutôt que création libre","Utiliser formes les plus familières (cercle = tourner) avant autres mouvements","Offrir pause et observation si fatigue ou timidité avec mouvement"],"pourAvancés":["Créer chorégraphie complexe combinant plusieurs formes en séquence","Improviser mouvements originaux exprimant propriétés des formes (coins pointus, côtés droits)","Diriger et enseigner mouvements aux autres élèves","Intégrer émotions dans danse géométrique (formes joyeuses, tristes, énergiques)"],"pourLangue":["Utiliser mouvements corporels comme langage universel avant mots","Associer mouvement à mots simples répétés (rond-tourner, carré-stop-go)","Permettre expression corporelle libre puis ajouter vocabulaire français progressivement","Utiliser musiques familières ou de sa culture d''origine si possible"],"pourPEI":["Adapter mouvements selon capacités physiques individuelles","Offrir alternatives assises ou modifiées si mobilité restreinte","Respecter sensibilités auditives (volume, type de musique)","Permettre participation à son rythme sans pression de performance"]}','{"vocabulary":["danser","mouvement","incarner"],"visualSupports":["Démonstrations de postures corporelles représentant chaque forme","Cartes de mouvements illustrant comment danser chaque forme"],"movementBreaks":["Imiter les animaux des histoires : sauter comme un lapin, voler comme un oiseau (3 minutes)","Former des lettres dans l''air avec nos doigts : A, B, C (3 minutes)","Étirer nos doigts et mains d''écrivains : ouvrir, fermer, tourner (2 minutes)","Marcher sur place en récitant l''alphabet lentement (2 minutes)","Célébrer nos apprentissages : applaudir, lever les bras, sourire (2 minutes)","Étirer notre dos d''écrivains : rotation douce des épaules (2 minutes)"]}',NULL,NULL,NULL,NULL,'{"questions":["Les élèves ont-ils atteint les objectifs?","Quelles adaptations étaient nécessaires?","Que ferais-je différemment la prochaine fois?"]}',NULL,'',2,16,'extension',1);
INSERT INTO ETFOLessonPlan VALUES('cmf43u44o00w1vj9tac1co5ne',23,'Cuisine géométrique','cmf43u44800v1vj9t0sfu0ir3',4102416000000,45,'Préparation sécuritaire : lavage des mains et révision des règles de cuisine','Création de collations en forme géométrique avec emporte-pièces et décoration','Dégustation géométrique : savourer les créations en nommant les formes','Représenter le concept de cuisine géométrique; Appliquer les concepts mathématiques de base; Développer les stratégies de calcul par la manipulation et le raisonnement','["emporte-pièces variés","pâte à biscuits","planches de travail","pâte sablée","fruits à découper","fromage","décoration comestible","chemises individuelles (30 chemises)","boîte de rangement pour travaux (1 grande boîte)","lingettes pour nettoyer les mains (1 paquet)"]',NULL,'Cuisine géométrique','Préparation sécuritaire : lavage des mains et révision des règles de cuisine','Création de collations en forme géométrique avec emporte-pièces et décoration','Dégustation géométrique : savourer les créations en nommant les formes','Représenter le concept de cuisine géométrique; Appliquer les concepts mathématiques de base; Développer les stratégies de calcul par la manipulation et le raisonnement',NULL,NULL,NULL,'formative','{"observable":["Élève exprime formes géométriques par mouvements corporels appropriés","Élève adapte son mouvement aux propriétés de chaque forme","Élève participe avec plaisir aux activités de mouvement et danse","Élève utilise vocabulaire des formes pendant activités corporelles","Élève fait preuve de créativité dans expression corporelle des concepts géométriques"],"checkpoints":["Pendant échauffement : observer aisance avec mouvements corporels de base","Pendant chorégraphie : noter précision et créativité dans expression des formes","Pendant présentation : évaluer confiance et plaisir dans performance"]}',1,'Plan détaillé avec supports visuels',1756911653737,1757594654345,1,'fr','Mathématiques','{"pourDifficultés":["Utiliser emporte-pièces plus grands et plus faciles à manipuler","Permettre aide d''un adulte pour pression et découpe","Se concentrer sur 1-2 formes simples plutôt que variété complète","Offrir alternative observation si allergies alimentaires"],"pourAvancés":["Créer compositions artistiques complexes avec formes multiples","Explorer techniques de décoration avancées","Calculer et planifier quantités nécessaires","Enseigner techniques aux autres élèves"],"pourLangue":["Associer actions culinaires à gestes et démonstrations concrètes","Utiliser vocabulaire culinaire simple avec objets réels","Permettre description en langue première des saveurs et textures","Fournir cartes visuelles des étapes de préparation"],"pourPEI":["Adapter outils selon besoins moteurs (emporte-pièces ergonomiques)","Respecter restrictions alimentaires et allergies strictement","Offrir alternatives si manipulation d''aliments difficile","Ajuster participation selon tolérance sensorielle aux textures"]}','{"vocabulary":["cuisine","emporte-pièce","délicieux"],"visualSupports":["Instructions visuelles pour la sécurité alimentaire et l''hygiène","Guide de découpage et techniques de décoration sécuritaires"],"movementBreaks":["Marcher en syllabant notre nom : Ma-rie, Paul, etc. en tapant dans nos mains (2 minutes)","Faire l''alphabet avec notre corps : A comme arbre (étirer les bras), B comme ballon (forme ronde) (3 minutes)","Marcher sur place en récitant l''alphabet lentement (2 minutes)","Danser avec les sons : ''a'' avec les bras, ''o'' en rond, ''i'' pointu (3 minutes)","Ranger nos idées : faire semblant de mettre nos pensées dans une boîte (2 minutes)","Célébrer nos apprentissages : applaudir, lever les bras, sourire (2 minutes)"]}',NULL,NULL,NULL,NULL,'{"questions":["Les élèves ont-ils atteint les objectifs?","Quelles adaptations étaient nécessaires?","Que ferais-je différemment la prochaine fois?"]}',NULL,'',2,17,'extension',0);
INSERT INTO ETFOLessonPlan VALUES('cmf43u44p00w3vj9t3fnokf9p',23,'Histoires de formes magiques','cmf43u44800v1vj9t0sfu0ir3',4102416000000,45,'Lecture d''une histoire modèle avec des formes comme personnages','Création collaborative d''histoires en petits groupes avec les formes comme héros','Théâtre de formes : représentation des histoires devant un public','Démontrer les formes géométriques de base; Raconter la reconnaissance des formes géométriques; Développer les stratégies de calcul par la narration','["formes en feutrine","théâtre de marionnettes","livre d''histoire","marionnettes de formes","décors simples","accessoires de théâtre","étiquettes autocollantes (2 planches)","boîte de rangement pour travaux (1 grande boîte)","chemises individuelles (30 chemises)"]',NULL,'Histoires de formes magiques','Lecture d''une histoire modèle avec des formes comme personnages','Création collaborative d''histoires en petits groupes avec les formes comme héros','Théâtre de formes : représentation des histoires devant un public','Démontrer les formes géométriques de base; Raconter la reconnaissance des formes géométriques; Développer les stratégies de calcul par la narration',NULL,NULL,NULL,'formative','{"observable":["Élève utilise emporte-pièces avec technique appropriée et sécuritaire","Élève identifie et nomme formes créées dans les aliments","Élève fait preuve de créativité dans arrangements et décorations","Élève respecte règles d''hygiène et de sécurité alimentaire","Élève exprime plaisir dans activité culinaire créative"],"checkpoints":["Pendant préparation : observer respect des règles d''hygiène et manipulation sécuritaire","Pendant création : noter précision des formes et créativité des compositions","Pendant dégustation : évaluer capacité à décrire formes et expérience culinaire"]}',1,'Plan détaillé avec supports visuels',1756911653738,1757594654346,1,'fr','Mathématiques','{"pourDifficultés":["Commencer par histoires très simples avec 2 personnages-formes seulement"