INSERT INTO ETFOLessonPlan VALUES('cmf43u45900x9vj9trrgyfgek',23,'Exposition de nos mesures','cmf43u44s00w7vj9txwdvcec6',4102416000000,45,'Préparation d''exposition: ''Nous organisons un musée de la mesure!'' Planification collective de l''exposition. Assignation des rôles: conservateurs, guides, artistes.','Montage de l''exposition: Les élèves organisent leurs travaux, créent des étiquettes explicatives, préparent leurs présentations. Pratique de leur rôle de guide pour expliquer leurs apprentissages.','Répétition générale: pratique des présentations entre élèves. Ajustements finaux de l''exposition. Anticipation de la venue des visiteurs.','Maîtriser le concept de exposition de; Appliquer des outils de mesure non standard; Développer les stratégies de calcul par la manipulation et le raisonnement','["livres d''images variés (6-8 livres)","crayons de couleur (boîte de 24)","tableau d''écriture ou grande feuille","fiches de mots illustrées (50 cartes)","tableaux individuels effaçables (15 tableaux)","marqueurs effaçables (15 marqueurs)","gommes à effacer douces (15 gommes)","lettres magnétiques (jeu complet A-Z)","boîte de rangement pour travaux (1 grande boîte)","certificats d''encouragement (30 copies)","tampons motivants avec encreur (5 tampons)"]',NULL,'Exposition de nos mesures','Préparation d''exposition: ''Nous organisons un musée de la mesure!'' Planification collective de l''exposition. Assignation des rôles: conservateurs, guides, artistes.','Montage de l''exposition: Les élèves organisent leurs travaux, créent des étiquettes explicatives, préparent leurs présentations. Pratique de leur rôle de guide pour expliquer leurs apprentissages.','Répétition générale: pratique des présentations entre élèves. Ajustements finaux de l''exposition. Anticipation de la venue des visiteurs.','Maîtriser le concept de exposition de; Appliquer des outils de mesure non standard; Développer les stratégies de calcul par la manipulation et le raisonnement',NULL,NULL,NULL,'formative','{"observable":["L''élève organise travaux de manière logique","L''élève explique apprentissages clairement","L''élève montre fierté de ses accomplissements","L''élève collabore efficacement pour exposition"],"checkpoints":["Pendant préparation: observer organisation et planification","Durant présentations: noter clarté et confiance","Après exposition: célébrer réussites et apprentissages"]}',1,'Plan détaillé avec supports visuels',1756911653758,1757594654370,1,'fr','Mathématiques','{"pourDifficultés":["Rôle simple mais important dans l''exposition","Support constant de partenaire ou enseignant","Présentation courte et bien pratiquée","Focus sur leurs réussites spécifiques"],"pourAvancés":["Rôle de guide principal ou conservateur","Explication détaillée des processus complexes","Aide autres élèves à préparer leurs présentations","Innovation dans l''organisation de l''exposition"],"pourLangue":["Support visuel supplémentaire pour présentations","Vocabulaire clé disponible en aide-mémoire","Encouragement pour communication multimodale","Célébration de progrès linguistique"],"pourPEI":["Rôle adapté selon capacités de communication","Support alternatif pour présentation si nécessaire","Objectifs personnalisés pour participation","Reconnaissance spéciale de contributions uniques"]}','{"vocabulary":["exposition","montrer","apprentissage"],"visualSupports":["Exemples d''étiquettes d''exposition, organisation spatiale claire"],"movementBreaks":["Répéter des comptines avec gestes : ''Tête, épaules, genoux et pieds'' (2 minutes)","Imiter les animaux des histoires : sauter comme un lapin, voler comme un oiseau (3 minutes)","Marcher sur place en récitant l''alphabet lentement (2 minutes)","Faire une pause lecture : s''étirer comme un chat qui se réveille (2 minutes)","Dire au revoir avec tout notre corps : mains, têtes, pieds (2 minutes)","Étirer notre dos d''écrivains : rotation douce des épaules (2 minutes)"]}',NULL,NULL,NULL,NULL,'{"questions":["Les élèves ont-ils atteint les objectifs?","Quelles adaptations étaient nécessaires?","Que ferais-je différemment la prochaine fois?"]}',NULL,'',2,19,'core',0);
INSERT INTO ETFOLessonPlan VALUES('cmf43u45a00xbvj9tdb3uowjg',23,'Célébrons la mesure','cmf43u44s00w7vj9txwdvcec6',1770912000000,45,'Ouverture festive: ''Bienvenue à notre célébration de la mesure!'' Accueil des visiteurs avec fierté. Chanson thème de l''unité avec tous les gestes appris.','Célébration interactive: Les élèves guident les visiteurs dans leur exposition, démontrent leurs apprentissages, partagent leurs découvertes préférées. Moment de réflexion collective sur le chemin parcouru.','Remise des certificats ''Expert en mesure non-standard''. Cercle final de partage: ''Qu''avez-vous préféré apprendre?'' Engagement à continuer de mesurer dans leur vie quotidienne.','Résoudre le concept de célébrons la; Appliquer des outils de mesure non standard; Développer les stratégies de calcul par la manipulation et le raisonnement','["marionnettes simples (3-4 personnages)","autocollants motivants (1 planche)","tapis de rassemblement coloré","crayons à mine large (30 crayons)","tableaux individuels effaçables (15 tableaux)","gommes à effacer douces (15 gommes)","marqueurs effaçables (15 marqueurs)","fiches de mots illustrées (50 cartes)","certificats d''encouragement (30 copies)","chemises individuelles (30 chemises)","boîte de rangement pour travaux (1 grande boîte)"]',NULL,'Célébrons la mesure','Ouverture festive: ''Bienvenue à notre célébration de la mesure!'' Accueil des visiteurs avec fierté. Chanson thème de l''unité avec tous les gestes appris.','Célébration interactive: Les élèves guident les visiteurs dans leur exposition, démontrent leurs apprentissages, partagent leurs découvertes préférées. Moment de réflexion collective sur le chemin parcouru.','Remise des certificats ''Expert en mesure non-standard''. Cercle final de partage: ''Qu''avez-vous préféré apprendre?'' Engagement à continuer de mesurer dans leur vie quotidienne.','Résoudre le concept de célébrons la; Appliquer des outils de mesure non standard; Développer les stratégies de calcul par la manipulation et le raisonnement',NULL,NULL,NULL,'formative','{"observable":["L''élève partage apprentissages avec confiance","L''élève montre fierté de son parcours d''apprentissage","L''élève fait connexions avec utilisation future","L''élève célèbre succès avec communauté"],"checkpoints":["Pendant célébration: observer confiance et joie","Lors de réflexion: écouter compréhension du chemin parcouru","En clôture: noter engagement pour continuer à mesurer"]}',1,'Plan détaillé avec supports visuels',1756911653759,1757594654371,1,'fr','Mathématiques','{"pourDifficultés":["Rôle spécial mais confortable dans célébration","Support familial encouragé et facilité","Reconnaissance de tous progrès, petits et grands","Célébration personnalisée de leurs réussites"],"pourAvancés":["Rôle de leadership dans cérémonie","Partage d''apprentissages avancés avec audience","Mentorat d''autres élèves pendant événement","Réflexion sur apprentissages futurs en mesure"],"pourLangue":["Support pour communication avec familles","Célébration inclusive de diversité culturelle","Vocabulaire accessible pour partage familial","Reconnaissance de progrès linguistique"],"pourPEI":["Célébration adaptée aux besoins individuels","Support familial selon situations particulières","Reconnaissance de progrès uniques et personnels","Objectifs de célébration personnalisés"]}','{"vocabulary":["célébrer","réfléchir","parcours"],"visualSupports":["Exposition complète, chronologie visuelle des apprentissages, photos souvenirs"],"movementBreaks":["Imiter les animaux des histoires : sauter comme un lapin, voler comme un oiseau (3 minutes)","Former des lettres dans l''air avec nos doigts : A, B, C (3 minutes)","Faire une pause lecture : s''étirer comme un chat qui se réveille (2 minutes)","Marcher sur place en récitant l''alphabet lentement (2 minutes)","Ranger nos idées : faire semblant de mettre nos pensées dans une boîte (2 minutes)","Étirer notre dos d''écrivains : rotation douce des épaules (2 minutes)"]}',NULL,NULL,N