INSERT INTO ETFOLessonPlan VALUES('cmf43u45e00xhvj9tajes9265',23,'Compter avec nos doigts','cmf43u45c00xdvj9trj7k2bg7',1756998000000,45,'Révision de la Leçon 1 avec gestes: ''Hier nous avons trouvé des nombres! Montrez-moi 0, 1, 2, 3 avec vos doigts!'' Chanson des doigts avec mouvement.','Stations de comptage: Station 1 - Compter des blocs dans des boîtes (0-3). Station 2 - Jeu de doigts avec comptines. Station 3 - Tri d''objets par quantité.','Jeu ''Montre-moi'': L''enseignant dit un nombre, les élèves le montrent avec leurs doigts et trouvent ce nombre d''objets.','Explorer le comptage avec stratégies; Appliquer les concepts mathématiques de base; Développer le sens du nombre par la manipulation et le raisonnement','["Matériel de classe"]',NULL,'Compter avec nos doigts','Révision de la Leçon 1 avec gestes: ''Hier nous avons trouvé des nombres! Montrez-moi 0, 1, 2, 3 avec vos doigts!'' Chanson des doigts avec mouvement.','Stations de comptage: Station 1 - Compter des blocs dans des boîtes (0-3). Station 2 - Jeu de doigts avec comptines. Station 3 - Tri d''objets par quantité.','Jeu ''Montre-moi'': L''enseignant dit un nombre, les élèves le montrent avec leurs doigts et trouvent ce nombre d''objets.','Explorer le comptage avec stratégies; Appliquer les concepts mathématiques de base; Développer le sens du nombre par la manipulation et le raisonnement',NULL,NULL,NULL,'formative','{"observable":["Élève construit correctement 13, 14, 15 avec manipulatifs (1 dizaine + unités)","Élève prononce clairement ''treize'', ''quatorze'', ''quinze'' en français","Élève reconnaît le modèle consistant 10+n pour tous les nombres","Élève peut continuer la séquence 11-12-13-14-15 oralement","Élève fait le lien entre représentation concrète et symbole écrit"],"checkpoints":["Pendant l''ouverture: maîtrise de la révision 11-12","Pendant construction: compréhension du modèle dizaine+unités","Pendant chanson: mémorisation de la séquence 13-14-15","Pendant fermeture: capacité à placer nombres dans l''ordre correct"]}',1,'Plan détaillé avec supports visuels',1756911653762,1757594654401,1,'fr','Mathématiques','{"pourDifficultés":["Commencer avec seulement 0-1-2, retarder l''introduction de 3","Utiliser des objets plus gros et faciles à manipuler","Permettre comptage plus lent avec pause entre chaque nombre","Utiliser supports visuels constants pour chaque nombre"],"pourAvancés":["Introduire le comptage jusqu''à 5 si maîtrise rapide","Demander de créer des collections de différentes tailles","Encourager à enseigner le comptage à un pair","Explorer différentes façons de montrer un nombre (doigts, objets, dessins)"],"pourLangue":["Répéter chaque nombre plusieurs fois avec gestes clairs","Associer nombres à des images/photos familières","Permettre comptage dans langue maternelle puis en français","Utiliser objets culturellement familiers quand possible"],"pourPEI":["Adapter les manipulatives selon besoins moteurs (plus gros, texturés)","Modifier attentes de production verbale (gestes ok)","Ajuster éclairage et position selon besoins sensoriels","Fournir pauses sensorielles fréquentes"]}','{"vocabulary":["deux","trois","compter"],"visualSupports":["Cartes nombres 0-3 affichées pour référence","Cartes numériques avec points, lignes de nombre tactile au sol","Cercle de rassemblement avec espace pour objets"],"movementBreaks":["Former des lettres dans l''air avec nos doigts : A, B, C (3 minutes)","Imiter les animaux des histoires : sauter comme un lapin, voler comme un oiseau (3 minutes)","Faire une pause lecture : s''étirer comme un chat qui se réveille (2 minutes)","Étirer nos doigts et mains d''écrivains : ouvrir, fermer, tourner (2 minutes)","Étirer notre dos d''écrivains : rotation douce des épaules (2 minutes)","Faire une révérence à nos nouvelles connaissances (1 minute)"]}',NULL,NULL,NULL,NULL,'{"questions":["Les élèves ont-ils atteint les objectifs?","Quelles adaptations étaient nécessaires?","Que ferais-je différemment la prochaine fois?"]}',NULL,'',