INSERT INTO ETFOLessonPlan VALUES('cmf43u46300yzvj9tqdkor5hg',23,'Comparer les nombres 11-20','cmf43u45w00yjvj9tc3ls30b1',1762185600000,45,'Jeu de devinette: ''Je pense à un nombre entre 11 et 20. Il est plus grand que 15 mais plus petit que 18.'' Introduction des termes de comparaison.','Activités de comparaison avec matériaux de manipulation pour comparer visuellement. Jeux de comparaison par paires et en groupes. Introduction progressive des symboles >, <, =. Pratique avec droites numériques.','Jeu de classement humain: les élèves se placent en ordre croissant ou décroissant avec leurs cartes numériques. Discussion sur les stratégies utilisées.','Mesurer les nombres de 0 à 10; Appliquer des stratégies de comptage efficaces; Développer la pensée logique par la manipulation et le raisonnement','["Cartes numériques 11-20","objets pour représenter","Matériaux de manipulation variés","cartes de comparaison","droites numériques individuelles","symboles >, <, = grands","jetons colorés pour comptage (250 jetons)","feuilles d''exercices plastifiées (25 copies)","crayons effaçables (25 marqueurs)"]',NULL,'Comparer les nombres 11-20','Jeu de devinette: ''Je pense à un nombre entre 11 et 20. Il est plus grand que 15 mais plus petit que 18.'' Introduction des termes de comparaison.','Activités de comparaison avec matériaux de manipulation pour comparer visuellement. Jeux de comparaison par paires et en groupes. Introduction progressive des symboles >, <, =. Pratique avec droites numériques.','Jeu de classement humain: les élèves se placent en ordre croissant ou décroissant avec leurs cartes numériques. Discussion sur les stratégies utilisées.','Mesurer les nombres de 0 à 10; Appliquer des stratégies de comptage efficaces; Développer la pensée logique par la manipulation et le raisonnement',NULL,NULL,NULL,'formative','{"observable":["L''élève utilise les symboles >, <, = pour comparer des nombres teen","L''élève justifie ses comparaisons en référant à la valeur positionnelle","L''élève ordonne une série de nombres 11-20 du plus petit au plus grand","L''élève utilise le vocabulaire comparatif (plus grand, plus petit, égal) correctement","L''élève résout des problèmes de comparaison dans des contextes réels"],"checkpoints":["Compare avec précision n''importe quels deux nombres entre 11 et 20","Ordonne correctement 5 nombres teen ou plus selon différents critères"]}',1,'Plan détaillé avec supports visuels',1756911653787,1757587623379,1,'fr','Mathématiques','{"pourDifficultés":["Permettre les réponses gestuelles avant la production orale","Utiliser des couleurs différentes pour chaque syllabe lors de la lecture","Proposer des supports audio pour accompagner le texte écrit"],"pourAvancés":["Proposer des textes plus complexes avec vocabulaire étendu","Proposer des défis de vocabulaire avec mots plus sophistiqués","Offrir des projets de recherche sur des auteurs franco-canadiens"],"pourLangue":["Répéter les consignes importantes avec des gestes clairs","Utiliser un dictionnaire visuel français-anglais","Utiliser des images et symboles pour soutenir la compréhension"],"pourPEI":["Utiliser des minuteurs visuels pour structurer le temps","Adapter les outils d''écriture (crayons ergonomiques, guides-lignes)","Ajuster l''éclairage et réduire les distractions visuelles"]}','{"vocabulary":["plus grand","plus petit","égal"],"visualSupports":[["Ligne numérique 11-20","cartes avec vocabulaire de comparaison"],["Comparaisons visuelles côte à côte","droite numérique géante","tableaux d''aide pour les symboles"]],"movementBreaks":["Compter en sautant sur place de 11 à 20 (2 minutes)","Lever les bras en comptant, baisser en décomptant (3 minutes)","Marcher et compter: faire des pas correspondant aux nombres (2 minutes)","Taper des mains en comptant par groupes de 10 (2 minutes)","Tourner en comptant, changer de direction à chaque dizaine (3 minutes)","Compter en touchant différentes parties du corps (2 minutes)"]}',NULL,NULL,NULL,NULL,'{"questions":["Les élèves ont-ils atteint les objectifs?","Quelles adaptations étaient nécessaires?","Que ferais-je différemment la prochaine fois?"]}',NULL,'',2,8,'core',1);
INSERT INTO ETFOLessonPlan VALUES('cmf43u46400z1vj9tk15e6hjw',23,'Patterns et régularités avec 11-20','cmf43u45w00yjvj9tc3ls30b1',1762272000000,45,'Présentation d''un pattern simple: 13, 14, 15, ?, ?. Question: ''Que remarquez-vous? Que vient ensuite?''','Exploration de patterns croissants et décroissants. Utilisation d''objets colorés et d''autocollants pour créer des patterns visuels. Création de patterns par les élèves. Découverte de patterns cachés dans la grille de 100.','Galerie de patterns: présentation des créations des élèves. Jeu de prédiction: compléter les patterns créés par les pairs.','Comparer le concept de patterns et; Appliquer les concepts mathématiques de base; Développer le raisonnement spatial par la manipulation et le raisonnement','["Cartes numériques","objets colorés","Objets colorés variés","autocollants","grille de 100","cartes numériques","matériel d''art","contenants de tri (bacs individuels)","ligne numérique au sol (ruban adhésif)","objets à compter (collections de 20-30 items)"]',NULL,'Patterns et régularités avec 11-20','Présentation d''un pattern simple: 13, 14, 15, ?, ?. Question: ''Que remarquez-vous? Que vient ensuite?''','Exploration de patterns croissants et décroissants. Utilisation d''objets colorés et d''autocollants pour créer des patterns visuels. Création de patterns par les élèves. Découverte de patterns cachés dans la grille de 100.','Galerie de patterns: présentation des créations des élèves. Jeu de prédiction: compléter les patterns créés par les pairs.','Comparer le concept de patterns et; Appliquer les concepts mathématiques de base; Développer le raisonnement spatial par la manipulation et le raisonnement',NULL,NULL,NULL,'formative','{"observable":["L''élève identifie des patterns dans la suite 11, 12, 13... 20","L''élève continue des séquences numériques données (ex: 11, 13, 15...)","L''élève crée ses propres patterns en utilisant les nombres teen","L''élève reconnaît les régularités dans l''écriture des nombres teen (1_)","L''élève explique les règles qu''il observe dans différents patterns numériques"],"checkpoints":["Identifie et continue des patterns simples avec les nombres 11-20","Crée des patterns originaux en expliquant sa logique mathématique"]}',1,'Plan détaillé avec supports visuels',1756911653788,1757587623379,1,'fr','Mathématiques','{"pourDifficultés":["Offrir du temps supplémentaire pour compléter les activités","Utiliser des couleurs différentes pour chaque syllabe lors de la lecture","Diviser les tâches longues en étapes plus petites et gérables"],"pourAvancés":["Proposer des défis de vocabulaire avec mots plus sophistiqués","Demander d''enseigner une nouvelle règle de français à un camarade","Offrir des projets de recherche sur des auteurs franco-canadiens"],"pourLangue":["Créer des liens avec des mots similaires dans la langue première","Utiliser un dictionnaire visuel français-anglais","Répéter les consignes importantes avec des gestes clairs"],"pourPEI":["Adapter les outils d''écriture (crayons ergonomiques, guides-lignes)","Offrir des pauses sensorielles fréquentes selon les besoins","Fournir des instructions simples, une étape à la fois"]}','{"vocabulary":["pattern","régularité","prédire"],"visualSupports":[["Pattern affiché en grand","espace pour continuer le pattern"],["Exemples de patterns multiples","grille de 100 avec patterns surlignés","modèles de création"]],"movementBreaks":["Compter en sautant sur place de 11 à 20 (2 minutes)","Lever les bras en comptant, baisser en décomptant (3 minutes)","Marcher et compter: faire des pas correspondant aux nombres (2 minutes)","Taper des mains en comptant par groupes de 10 (2 minutes)","Tourner en comptant, changer de direction à chaque dizaine (3 minutes)","Compter en touchant différentes parties du corps (2 minutes)"]}',NULL,NULL,NULL,NULL,'{"questions":["Les élèves ont-ils atteint les objectifs?","Quelles adaptations étaient nécessaires?","Que ferais-je différemment la prochaine fois?"]}',NULL,'',2,9,'core',1);
INSERT INTO ETFOLessonPlan VALUES('cmf43u46400z3vj9tvrp86rnl',23,'Introduction à l''addition simple avec des nombres teen','cmf43u45w00yjvj9tc3ls30b1',1762358400000,45,'Histoire mathématique: ''Marie a 10 autocollants. Son ami lui en donne 3 de plus. Combien en a-t-elle maintenant?'' Manipulation avec objets concrets.','Exploration de l''addition avec des objets concrets. Focus sur 10 + nombres simples (1-9). Utilisation d''histoires mathématiques et de problèmes contextuels. Introduction de différentes stratégies d''addition.','Création collective d''une histoire mathématique de classe. Les élèves proposent des éléments et résolvent ensemble le problème d''addition.','Ordonner les nombres de 0 à 10; Appliquer des stratégies de comptage efficaces; Développer le raisonnement spatial par la manipulation et le raisonnement','["Autocollants ou objets similaires","boîtes pour grouper","Objets variés pour compter","blocs de base dix","cartes d''histoires mathématiques","feuilles de travail visuelles","cartes de nombres 11-20 (2 jeux par classe)","blocs de base dix (ensembles complets)","tableau des nombres 1-20 (affiche murale)"]',NULL,'Introduction à l''addition simple avec des nombres teen','Histoire mathématique: ''Marie a 10 autocollants. Son ami lui en donne 3 de plus. Combien en a-t-elle maintenant?'' Manipulation avec objets concrets.','Exploration de l''addition avec des objets concrets. Focus sur 10 + nombres simples (1-9). Utilisation d''histoires mathématiques et de problèmes contextuels. Introduction de différentes stratégies d''addition.','Création collective d''une histoire mathématique de classe. Les élèves proposent des éléments et résolvent ensemble le problème d''addition.','Ordonner les nombres de 0 à 10; Appliquer des stratégies de comptage efficaces; Développer le raisonnement spatial par la manipulation et le raisonnement',NULL,NULL,NULL,'formative','{"observable":["L''élève additionne des petits nombres aux nombres teen (ex: 12 + 3)","L''élève utili