INSERT INTO ETFOLessonPlan VALUES('cmf43u46600z7vj9t6m2cuaxr',23,'Jeux mathématiques avec 11-20','cmf43u45w00yjvj9tc3ls30b1',1762790400000,45,'Présentation des centres de jeux mathématiques. Démonstration rapide de chaque jeu et établissement des règles de rotation.','Rotation par centres de jeux: 1) Cartes et dés avec nombres 11-20, 2) Jeu de plateau numérique, 3) Mémoire avec nombres et représentations, 4) Course aux nombres, 5) Construction libre avec défis numériques.','Cercle de partage: chaque groupe partage son jeu préféré et explique pourquoi. Planification des jeux favoris pour les temps libres.','Compter le concept de jeux mathématiques; Participer à les concepts mathématiques de base; Développer le raisonnement spatial par le jeu dirigé','["Matériel pour 4-5 jeux différents","Cartes numériques","dés spéciaux","plateaux de jeu","cartes mémoire","matériel de construction","défis écrits","crayons effaçables (25 marqueurs)","contenants de tri (bacs individuels)","ligne numérique au sol (ruban adhésif)"]',NULL,'Jeux mathématiques avec 11-20','Présentation des centres de jeux mathématiques. Démonstration rapide de chaque jeu et établissement des règles de rotation.','Rotation par centres de jeux: 1) Cartes et dés avec nombres 11-20, 2) Jeu de plateau numérique, 3) Mémoire avec nombres et représentations, 4) Course aux nombres, 5) Construction libre avec défis numériques.','Cercle de partage: chaque groupe partage son jeu préféré et explique pourquoi. Planification des jeux favoris pour les temps libres.','Compter le concept de jeux mathématiques; Participer à les concepts mathématiques de base; Développer le raisonnement spatial par le jeu dirigé',NULL,NULL,NULL,'formative','{"observable":["L''élève participe activement aux jeux en appliquant ses connaissances des teen","L''élève respecte les règles des jeux tout en démontrant sa compréhension numérique","L''élève utilise des stratégies mathématiques pour améliorer sa performance aux jeux","L''élève fait des liens entre les jeux et les concepts mathématiques appris","L''élève aide ses pairs et partage ses stratégies pendant les activités ludiques"],"checkpoints":["Applique avec succès les concepts des nombres teen dans des contextes de jeux","Démontre une attitude positive et collaborative pendant les activités mathématiques"]}',1,'Plan détaillé avec supports visuels',1756911653791,1757587623382,1,'fr','Mathématiques','{"pourDifficultés":["Utiliser des cartes visuelles avec images pour chaque mot nouveau","Diviser les tâches longues en étapes plus petites et gérables","Encourager l''utilisation de manipulatifs (lettres magnétiques, etc.)"],"pourAvancés":["Encourager la création d''histoires originales avec début, milieu, fin","Proposer des textes plus complexes avec vocabulaire étendu","Permettre l''exploration de différents genres littéraires (poésie, théâtre)"],"pourLangue":["Offrir des gestes et actions pour accompagner les mots nouveaux","Permettre les explications dans la langue première si nécessaire","Encourager le jumelage avec un pair plus fort en français"],"pourPEI":["Fournir des instructions simples, une étape à la fois","Offrir des pauses sensorielles fréquentes selon les besoins","Ajuster l''éclairage et réduire les distractions visuelles"]}','{"vocabulary":["jeu","règles","stratégie"],"visualSupports":[["Instructions visuelles pour chaque jeu","timer visible","tableau de rotation"],["Règles illustrées pour chaque centre","exemples de jeu en action","aide-mémoire pour les stratégies"]],"movementBreaks":["Compter en sautant sur place de 11 à 20 (2 minutes)","Lever les bras en comptant, baisser en décomptant (3 minutes)","Marcher et compter: faire des pas correspondant aux nombres (2 minutes)","Taper des mains en comptant par groupes de 10 (2 minutes)","Tourner en comptant, changer de direction à chaque dizaine (3 minutes)","Compter en touchant différentes parties du corps (2 minutes)"]}',NULL,NULL,NULL,NULL,'{"questions":["Les élèves ont-ils atteint les objectifs?","Quelles adaptations étaient nécessaires?","Que ferais-je différemment la prochaine fois?"]}',NULL,'',2,12,'core',1);
INSERT INTO ETFOLessonPlan VALUES('cmf43u46700z9vj9tnr9pt6i4',23,'Estimation avec les nombres 11-20','cmf43u45w00yjvj9tc3ls30b1',1762876800000,45,'Présentation de bocaux mystères avec différentes quantités d''objets. Question: ''Combien y en a-t-il environ? Comment pourriez-vous deviner sans compter?''','Développement de stratégies d''estimation: utilisation de références (groupes de 5, 10), comparaison avec des quantités connues. Activités variées: estimation puis vérification. Création d''un ''guide d''estimation'' de classe.','Création du ''guide d''estimation de classe'' avec les meilleures stratégies découvertes. Test final d''estimation avec un nouveau bocal mystère.','Calculer les nombres de 0 à 10; Appliquer des stratégies de comptage efficaces; Développer la résolution de problèmes par la manipulation et le raisonnement','["Bocaux transparents avec 11-20 objets variés","étiquettes pour les estimations","Objets variés en différentes quantités","bocaux et contenants","référentiels numériques","feuilles d''estimation","objets à compter (collections de 20-30 items)","cartes de nombres 11-20 (2 jeux par classe)","blocs de base dix (ensembles complets)"]',NULL,'Estimation avec les nombres 11-20','Présentation de bocaux mystères avec différentes quantités d''objets. Question: ''Combien y en a-t-il environ? Comment pourriez-vous deviner sans compter?''','Développement de stratégies d''estimation: utilisation de références (groupes de 5, 10), comparaison avec des quantités connues. Activités variées: estimation puis vérification. Création d''un ''guide d''estimation'' de classe.','Création du ''guide d''estimation de classe'' avec les meilleures stratégies découvertes. Test final d''estimation avec un nouveau bocal mystère.','Calculer les nombres de 0 à 10; Appliquer des stratégies de comptage efficaces; Développer la résolution de problèmes par la manipulation et le raisonnement',NULL,NULL,NULL,'formative','{"observable":["L''élève fait des estimations raisonnables d''objets en quantités teen","L''élève utilise des stratégies d''estimation (groups de 10, points de référence)","L''élève compare ses estimations avec les comptes réels","L''élève ajuste ses stratégies d''estimation en fonction des résultats","L''élève explique pourquoi ses estimations sont raisonnables ou non"],"checkpoints":["Fait des estimations dans la fourchette des nombres 11-20 avec une marge d''erreur acceptable","Développe des stratégies d''estimation de plus en plus précises"]}',1,'Plan détaillé avec supports visuels',1756911653792,1757587623383,1,'fr','Mathématiques','{"pourDifficultés":["Utiliser des cartes visuelles avec images pour chaque mot nouveau","Proposer des supports audio pour accompagner le texte écrit","Offrir du temps supplémentaire pour compléter les activités"],"pourAvancés":["Offrir des projets de recherche sur des auteurs franco-canadiens","Permettre l''exploration de différents genres littéraires (poésie, théâtre)","Encourager la création d''histoires originales avec début, milieu, fin"],"pourLangue":["Répéter les consignes importantes avec des gestes clairs","Permettre les explications dans la langue première si nécessaire","Utiliser un dictionnaire visuel français-anglais"],"pourPEI":["Permettre différents moyens d''expression (oral, dessin, technologie)","Utiliser des supports visuels clairs et contrastés","Adapter les outils d''écriture (crayons ergonomiques, guides-lignes)"]}','{"vocabulary":["estimation","environ","raisonnable"],"visualSupports":[["Référentiels visuels (groupes de 10, 15, 20)","échelle d''estimation"],["Stratégies d''estimation affichées","exemples de bonnes et mauvaises estimations","référentiels visuels constants"]],"movementBreaks":["Compter en sautant sur place de 11 à 20 (2 minutes)","Lever les bras en comptant, baisser en décomptant (3 minutes)","Marcher et compter: faire des pas correspondant aux nombres (2 minutes)","Taper des mains en comptant par groupes de 10 (2 minutes)","Tourner en comptant, changer de direction à chaque dizaine (3 minutes)","Compter en touchant différentes parties du corps (2 minutes)"]}',NULL,NULL,NULL,NULL,'{"questions":["Les élèves ont-ils atteint les objectifs?","Quelles adaptations étaient nécessaires?","Que ferais-je différemment la prochaine fois?"]}',NULL,'',2,13,'core',1);
INSERT INTO ETFOLessonPlan VALUES('cmf43u46800zbvj9ttnr73oiz',23,'Nombres ordinaux jusqu''à 20','cmf43u45w00yjvj9tc3ls30b1',1762963200000,45,'Organisation d''une file d''élèves. Introduction: ''Comment peut-on décrire la position de chaque personne dans la file?'' Introduction du vocabulaire ordinal.','Exploration des ordinaux avec files d''élèves, courses simulées, livres sur étagère. Pratique de l''identification de positions. Activités de classement avec objets. Connexion entre nombres cardinaux et ordinaux.','Jeu final: ''Course aux positions''. Les élèves doivent se placer selon les positions ordinales appelées. Récapitulatif du vocabulaire appris.','Mesurer les nombres de 0 à 10; Appliquer des stratégies de comptage efficaces; Développer la résolution de problèmes par la manipulation et le raisonnement','["Cartes ordinales illustrées","Objets à classer","livres","figurines pour courses","cartes ordinales complètes","rubans de positions","tableau des nombres 1-20 (affiche murale)","cubes à encastrer (200-250 cubes)","jetons colorés pour comptage (250 jetons)"]',NULL,'Nombres ordinaux jusqu''à 20','Organisation d''une file d''élèves. Introduction: ''Comment peut-on décrire la position de chaque personne dans la file?'' Introduction du vocabulaire ordinal.','Exploration des ordinaux avec files d''élèves, courses simulées, livres sur étagère. Pratique de l''identification de positions. Activités de classement avec objets. Connexion entre nombres cardinaux et ordinaux.','Jeu final: ''Course aux positions''. Les élèves doivent se placer selon les positions ordinales appelées. Récapitulatif du vocabulaire appris.','Mesurer les nombres de 0 à 10; Appliquer des stratégies de comptage efficaces; Développer la résolution de problèmes par la manipulation et le raisonnement',NULL,NULL,NULL,'formative','{"observable":["L''élève utilise correctement les nombres ordinaux (onzième, douzième... vingtième)","L''élève place des objets en ordre selon des instructions ordinales","L''élève identifie la position d''éléments dans une séquence jusqu''à la 20e position","L''élève fait la distinction entre nombres cardinaux (quantité) et ordinaux (position)","L''élève utilise les nombres ordinaux dans des situations authentiques"],"checkpoints":["Maîtrise les nombres ordinaux jusqu''au vingtième dans différents contextes","Applique correctement le concept de position ordinale dans des activités pratiques"]}',1,'Plan détaillé avec supports visuels',1756911653793,1757587623383,1,'fr','Mathématiques','{"pourDifficultés":["Permettre les réponses gestuelles avant la production orale","Utiliser des couleurs différentes pour chaque syllabe lors de la lecture","Encourager l''utilisation de manipulatifs (lettres magnétiques, etc.)"],"pourAvancés":["Encourager la création d''histoires originales avec début, milieu, fin","Proposer des textes plus complexes avec vocabulaire étendu","Offrir des projets de recherche sur des auteurs franco-canadiens"],"pourLangue":["Utiliser des images et symboles pour soutenir la compréhension","Permettre les explications dans la langue première si nécessaire","Utiliser un dictionnaire visuel français-anglais"],"pourPEI":["Adapter les outils d''écriture (crayons ergonomiques, guides-lignes)","Ajuster l''éclairage et réduire les distractions visuelles","Utiliser des supports visuels clairs et contrastés"]}','{"vocabulary":["premier","deuxième","dernier"],"visualSupports":[["File physique d''élèves","cartes ordinales 1er-10e"],["Tableau de correspondance cardinal/ordinal","exemples de positions illustrées","aide-mémoire pour ordinaux"]],"movementBreaks":["Compter en sautant sur place de 11 à 20 (2 minutes)","Lever les bras en comptant, baisser en décomptant (3 minutes)","Marcher et compter: faire des pas correspondant aux nombres (2 minutes)","Taper des mains en comptant par groupes de 10 (2 minutes)","Tourner en comptant, changer de direction à chaque dizaine (3 minutes)","Compter en touchant différentes parties du corps (2 minutes)"]}',NULL,NULL,NULL,NULL,'{"questions":["Les élèves ont-ils atteint les objectifs?","Quelles adaptations étaient nécessaires?","Que ferais-je différemment la prochaine fois?"]}',NULL,'',2,14,'core',1);
INSERT INTO ETFOLessonPlan VALUES('cmf43u46900zdvj9tiqi7ydvj',23,'Évaluation formative et consolidation','cmf43u45w00yjvj9tc3ls30b1',1763049600000,45,'Révision interactive: ''Tour de mathématiques''. Chaque élève partage une chose qu''il a apprise sur les nombres 11-20.','Évaluation par stations: 1) Construction de nombres avec manipulatifs, 2) Séquences et ordre, 3) Comparaisons, 4) Résolution de problèmes simples, 5) Représentations diverses. Observation et documentation systématiques.','Célébration des progrès. Chaque élève reçoit un certificat personnalisé mentionnant ses forces avec les nombres 11-20. Planification des prochaines aventures mathématiques.','Comparer le concept de évaluation formative; Appliquer les concepts mathématiques de base; Développer la résolution de problèmes par la manipulation et le raisonnement','["Objet ''bâton de parole''","tableau de la classe","Matériel d''évaluation pour chaque station","feuilles d''observation","manipulatifs variés","cartes de tâches","feuilles d''exercices plastifiées (25 copies)","crayons effaçables (25 marqueurs)","contenants de tri (bacs individuels)"]',NULL,'Évaluation formative et consolidation','Révision interactive: ''Tour de mathématiques''. Chaque élève partage une chose qu''il a apprise sur les nombres 11-20.','Évaluation par stations: 1) Construction de nombres avec manipulatifs, 2) Séquences et ordre, 3) Comparaisons, 4) Résolution de problèmes simples, 5) Représentations diverses. Observation et documentation systématiques.','Célébration des progrès. Chaque élève reçoit un certificat personnalisé mentionnant ses forces avec les nombres 11-20. Planification des prochaines aventures mathématiques.','Comparer le concept de évaluation formative; Appliquer les concepts mathématiques de base; Développer la résolution de problèmes par la manipulation et le raisonnement',NULL,NULL,NULL,'formative','{"observable":["L''élève démontre une maîtrise consolidée de tous les nombres 11-20","L''élève transfère ses apprentissages à de nouvelles situations d''évaluation","L''élève autoévalue ses forces et ses défis avec les nombres teen","L''élève utilise diverses stratégies pour démontrer sa compréhension","L''élève fait des connections entre tous les concepts appris dans l''unité"],"checkpoints":["Réussit les tâches d''évaluation formative avec un niveau de maîtrise élevé","Démontre une confiance et une autonomie dans l''utilisation des nombres 11-20"]}',1,'Plan détaillé avec supports visuels',1756911653793,1757587623384,1,'fr','Mathématiques','{"pourDifficultés":["Offrir du temps supplémentaire pour compléter les activités","Utiliser des cartes visuelles avec images pour chaque mot nouveau","Proposer des supports audio pour accompagner le texte écrit"],"pourAvancés":["Proposer des défis de vocabulaire avec mots plus sophistiqués","Proposer des textes plus complexes avec vocabulaire étendu","Demander d''enseigner une nouvelle règle de français à un camarade"],"pourLangue":["Répéter les consignes importantes avec des gestes clairs","Encourager le jumelage avec un pair plus fort en français","Utiliser un dictionnaire visuel français-anglais"],"pourPEI":["Ajuster l''éclairage et réduire les distractions visuelles","Utiliser des minuteurs visuels pour structurer le temps","Adapter les outils d''écriture (crayons ergonomiques, guides-lignes)"]}','{"vocabulary":["évaluation","progrès","amélioration"],"visualSupports":[["Résumé visuel des apprentissages","liste des concepts clés"],["Instructions claires pour chaque station","exemples de tâches réussies","critères d''évaluation visuels"]],"movementBreaks":["Compter en sautant sur place de 11 à 20 (2 minutes)","Lever les bras en comptant, baisser en décomptant (3 minutes)","Marcher et compter: faire des pas correspondant aux nombres (2 minutes)","Taper des mains en comptant par groupes de 10 (2 minutes)","Tourner en comptant, changer de direction à chaque dizaine (3 minutes)","Compter en touchant différentes parties du corps (2 minute