INSERT INTO ETFOLessonPlan VALUES('cmf43u46a00zfvj9tm8nvmdb1',23,'Introduction aux nombres 21-25','cmf43u45w00yjvj9tc3ls30b1',1763136000000,45,'Construction de 20 avec manipulatifs, puis question: ''Que se passe-t-il si nous continuons à compter? Que vient après 20?''','Construction sur la compréhension de 20 en ajoutant des unités. Utilisation de matériaux de manipulation pour montrer 2 dizaines + unités. Exploration des patterns de nommage (vingt-et-un, vingt-deux). Comparaison avec 11-15.','Création d''une ligne numérique collective 20-25. Chaque élève contribue en plaçant un nombre et en expliquant sa structure (2 dizaines + unités).','Ordonner les nombres de 0 à 10; Appliquer des stratégies de comptage efficaces; Développer la résolution de problèmes par la manipulation et le raisonnement','["Blocs de base dix (2 dizaines)","objets à ajouter","Blocs de base dix étendus","objets groupables","cartes numériques 21-25","tableau des nombres étendu","ligne numérique au sol (ruban adhésif)","objets à compter (collections de 20-30 items)","cartes de nombres 11-20 (2 jeux par classe)"]',NULL,'Introduction aux nombres 21-25','Construction de 20 avec manipulatifs, puis question: ''Que se passe-t-il si nous continuons à compter? Que vient après 20?''','Construction sur la compréhension de 20 en ajoutant des unités. Utilisation de matériaux de manipulation pour montrer 2 dizaines + unités. Exploration des patterns de nommage (vingt-et-un, vingt-deux). Comparaison avec 11-15.','Création d''une ligne numérique collective 20-25. Chaque élève contribue en plaçant un nombre et en expliquant sa structure (2 dizaines + unités).','Ordonner les nombres de 0 à 10; Appliquer des stratégies de comptage efficaces; Développer la résolution de problèmes par la manipulation et le raisonnement',NULL,NULL,NULL,'formative','{"observable":["L''élève reconnaît et nomme les nombres 21, 22, 23, 24, 25","L''élève applique sa compréhension de la valeur positionnelle aux vingtaines","L''élève compte en séquence de 20 à 25 avec confiance","L''élève compare les vingtaines avec les nombres teen précédemment appris","L''élève utilise des manipulatifs pour représenter la structure des vingtaines"],"checkpoints":["Transfère avec succès sa compréhension des teen aux nombres 21-25","Reconnaît les patterns et similitudes entre les structures numériques"]}',1,'Plan détaillé avec supports visuels',1756911653794,1757587623385,1,'fr','Mathématiques','{"pourDifficultés":["Offrir du temps supplémentaire pour compléter les activités","Diviser les tâches longues en étapes plus petites et gérables","Permettre les réponses gestuelles avant la production orale"],"pourAvancés":["Demander d''enseigner une nouvelle règle de français à un camarade","Proposer des défis de vocabulaire avec mots plus sophistiqués","Inviter à créer un livre illustré pour les plus jeunes"],"pourLangue":["Offrir des gestes et actions pour accompagner les mots nouveaux","Utiliser des images et symboles pour soutenir la compréhension","Répéter les consignes importantes avec des gestes clairs"],"pourPEI":["Offrir des pauses sensorielles fréquentes selon les besoins","Ajuster l''éclairage et réduire les distractions visuelles","Utiliser des minuteurs visuels pour structurer le temps"]}','{"vocabulary":["vingt-et-un","vingt-deux","troisième dizaine"],"visualSupports":[["Représentation claire de 20","espace pour explorer 21+"],["Comparaisons entre 11-15 et 21-25","patterns de nommage affichés","ligne numérique étendue"]],"movementBreaks":["Compter en sautant sur place de 11 à 20 (2 minutes)","Lever les bras en comptant, baisser en décomptant (3 minutes)","Marcher et compter: faire des pas correspondant aux nombres (2 minutes)","Taper des mains en comptant par groupes de 10 (2 minutes)","Tourner en comptant, changer de direction à chaque dizaine (3 minutes)","Compter en touchant différentes parties du corps (2 minutes)"]}',NULL,NULL,NULL,NULL,'{"questions":["Les élèves ont-ils atteint les objectifs?","Quelles adaptations étaient nécessaires?","Que ferais-je différemment la prochaine fois?"]}',NULL,'',2,16,'extension',1);
INSERT INTO ETFOLessonPlan VALUES('cmf43u46b00zhvj9t67aos43r',23,'Exploration libre: nombres jusqu''à 30','cmf43u45w00yjvj9tc3ls30b1',1763395200000,45,'Présentation de divers matériaux et invitation: ''Aujourd''hui, vous êtes des explorateurs de nombres! Découvrez tout ce que vous pouvez sur les nombres jusqu''à 30.''','Exploration libre avec guidance minimale. Les élèves choisissent leurs matériaux et explorent les patterns, créent des représentations, posent des questions. L''enseignant circule et facilite les découvertes sans diriger.','Cercle de partage des découvertes. Chaque élève ou groupe partage une chose intéressante qu''il a découverte. Création d''un ''mur des découvertes''.','Représenter les nombres de 0 à 10; Explorer des stratégies de comptage efficaces; Développer les stratégies de calcul par l''exploration guidée','["Variété de manipulatifs","cartes vierges","matériel d''art","Manipulatifs variés","papier et crayons","calculatrices simples","livres de nombres","matériel de construction","blocs de base dix (ensembles complets)","tableau des nombres 1-20 (affiche murale)","cubes à encastrer (200-250 cubes)"]',NULL,'Exploration libre: nombres jusqu''à 30','Présentation de divers matériaux et invitation: ''Aujourd''hui, vous êtes des explorateurs de nombres! Découvrez tout ce que vous pouvez sur les nombres jusqu''à 30.''','Exploration libre avec guidance minimale. Les élèves choisissent leurs matériaux et explorent les patterns, créent des représentations, posent des questions. L''enseignant circule et facilite les découvertes sans diriger.','Cercle de partage des découvertes. Chaque élève ou groupe partage une chose intéressante qu''il a découverte. Création d''un ''mur des découvertes''.','Représenter les nombres de 0 à 10; Explorer des stratégies de comptage efficaces; Développer les stratégies de calcul par l''exploration guidée',NULL,NULL,NULL,'formative','{"observable":["L''élève explore de façon autonome les nombres entre 26 et 30","L''élève fait des découvertes sur les patterns dans les vingtaines","L''élève pose des questions mathématiques pertinentes durant l''exploration","L''élève partage ses découvertes avec ses pairs de façon articulée","L''élève utilise créativement le matériel mis à sa disposition"],"checkpoints":["Démontre curiosité et initiative dans l''exploration de nouveaux nombres","Fait des connections mathématiques significatives durant l''exploration libre"]}',1,'Plan détaillé avec supports visuels',1756911653796,1757587623501,1,'fr','Mathématiques','{"pourDifficultés":["Encourager l''utilisation de manipulatifs (lettres magnétiques, etc.)","Utiliser des couleurs différentes pour chaque syllabe lors de la lecture","Permettre les réponses gestuelles avant la production orale"],"pourAvancés":["Proposer des défis de vocabulaire avec mots plus sophistiqués","Encourager la création d''histoires originales avec début, milieu, fin","Permettre l''exploration de différents genres littéraires (poésie, théâtre)"],"pourLangue":["Répéter les consignes importantes avec des gestes clairs","Utiliser des images et symboles pour soutenir la compréhension","Créer des liens avec des mots similaires dans la langue première"],"pourPEI":["Fournir des instructions simples, une étape à la fois","Utiliser des supports visuels clairs et contrastés","Adapter les outils d''écriture (crayons ergonomiques, guides-lignes)"]}','{"vocabulary":["explorer","découvrir","indépendant"],"visualSupports":[["Exemples de questions d''exploration","stations d''exploration marquées"],["Questions guide affichées","exemples de découvertes possibles","espace pour documenter les trouvailles"]],"movementBreaks":["Compter en sautant sur place de 11 à 20 (2 minutes)","Lever les bras en comptant, baisser en décomptant (3 minutes)","Marcher et compter: faire des pas correspondant aux nombres (2 minutes)","Taper des mains en comptant par groupes de 10 (2 minutes)","Tourner en comptant, changer de direction à chaque dizaine (3 minutes)","Compter en touchant différentes parties du corps (2 minutes)"]}',NULL,NULL,NULL,NULL,'{"questions":["Les élèves ont-ils atteint les objectifs?","Quelles adaptations étaient nécessaires?","Que ferais-je différemment la prochaine fois?"]}',NULL,'',2,17,'extension',1);
INSERT INTO ETFOLessonPlan VALUES('cmf43u46c00zjvj9tuy9nmsbf',23,'Projet: Collection et comptage','cmf43u45w00yjvj9tc3ls30b1',4102416000000,45,'Présentation du projet: ''Choisissez une collection personnelle de 11-30 objets. Vous allez devenir des experts de votre collection!'' Explication des critères et du processus.','Travail individuel sur les projets. Les élèves comptent, organisent, représentent et analysent leurs collections. Création de différentes représentations (dessins, graphiques, textes). Préparation des présentations.','Préparation finale des présentations. Les élèves pratiquent leurs présentations avec un partenaire et reçoivent des encouragements pour la séance de partage.','Démontrer le concept de projet: collection; Réaliser les concepts mathématiques de base; Développer les stratégies de calcul par la création personnelle','["Exemples de collections","feuilles de planification de projet","Collections personnelles des élèves","matériel d''art et de création","feuilles de travail pour projet","appareils photo si disponibles","jetons colorés pour comptage (250 jetons)","feuilles d''exercices plastifiées (25 copies)","crayons effaçables (25 marqueurs)"]',NULL,'Projet: Collection et comptage','Présentation du projet: ''Choisissez une collection personnelle de 11-30 objets. Vous allez devenir des experts de votre collection!'' Explication des critères et du processus.','Travail individuel sur les projets. Les élèves comptent, organisent, représentent et analysent leurs collections. Création de différentes représentations (dessins, graphiques, textes). Préparation des présentations.','Préparation finale des présentations. Les élèves pratiquent leurs présentations avec un partenaire et reçoivent des encouragements pour la séance de partage.','Démontrer le concept de projet: collection; Réaliser les concepts mathématiques de base; Développer les stratégies de calcul par la création personnelle',NULL,NULL,NULL,'formative','{"observable":["L''élève planifie et organise sa collection d''objets de façon systématique","L''élève compte sa collection en utilisant des stratégies efficaces","L''élève représente sa collection avec des nombres, graphiques ou dessins","L''élève présente son projet en utilisant le vocabulaire mathématique approprié","L''élève fait des comparaisons mathématiques entre les différentes collections"],"checkpoints":["Réalise un projet de comptage démontrant sa maîtrise des nombres teen","Communique efficacement ses apprentissages mathématiques dans un contexte authentique"]}',1,'Plan détaillé avec supports visuels',1756911653797,1757587623501,1,'fr','Mathématiques','{"pourDifficultés":["Encourager l''utilisation de manipulatifs (lettres magnétiques, etc.)","Utiliser des couleurs différentes pour chaque syllabe lors de la lecture","Diviser les tâches longues en étapes plus petites et gérables"],"pourAvancés":["Demander d''enseigner une nouvelle règle de français à un camarade","Offrir des projets de recherche sur des auteurs franco-canadiens","Permettre l''exploration de différents genres littéraires (poésie, théâtre)"],"pourLangue":["Encourager le jumelage avec un pair plus fort en français","Utiliser un dictionnaire visuel français-anglais","Utiliser des images et symboles pour soutenir la compréhension"],"pourPEI":["Offrir des pauses sensorielles fréquentes selon les besoins","Permettre différents moyens d''expression (oral, dessin, technologie)","Utiliser des minuteurs visuels pour structurer le temps"]}','{"vocabulary":["projet","collection","présentation"],"visualSupports":[["Étapes du projet illustrées","exemples de présentations finales","critères de réussite"],["Guide de projet étape par étape","exemples de représentations","aide-mémoire pour présentation"]],"movementBreaks":["Compter en sautant sur place de 11 à 20 (2 minutes)","Lever les bras en comptant, baisser en décomptant (3 minutes)","Marcher et compter: faire des pas correspondant aux nombres (2 minutes)","Taper des mains en comptant par groupes de 10 (2 minutes)","Tourner en comptant, changer de direction à chaque dizaine (3 minutes)","Compter en touchant différentes parties du corps (2 minutes)"]}',NULL,NULL,NULL,NULL,'{"questions":["Les élèves ont-ils atteint les objectifs?","Quelles adaptations étaient nécessaires?","Que ferais-je différemment la prochaine fois?"]}',NULL,'',2,18,'extension',0);
INSERT INTO ETFOLessonPlan VALUES('cmf43u46d00zlvj9tfiryki4e',23,'Partage et célébration des apprentissages','cmf43u45w00yjvj9tc3ls30b1',4102416000000,45,'Préparation de l''espace de présentation. Accueil des invités (parents, autres classes). Introduction du contexte d''apprentissage et des réalisations des élèves.','Séance de partage organisée où les élèves présentent leurs projets de collection. Chaque élève explique sa collection, ses découvertes mathématiques et ses apprentissages. Questions et interactions avec le public.','Cercle de célébration finale. Chaque élève reçoit des commentaires positifs. Photo de groupe avec les collections. Planification des prochaines aventures mathématiques.','Maîtriser le concept de partage et; Appliquer les concepts mathématiques de base; Développer les stratégies de calcul par la célébration collective','["Espace de présentation aménagé","projets des élèves exposés","Collections et présentations des élèves","micro si disponible","espace pour circulation","contenants de tri (bacs individuels)","ligne numérique au sol (ruban adhésif)","objets à compter (collections de 20-30 items)"]',NULL,'Partage et célébration des apprentissages','Préparation de l''espace de présentation. Accueil des invités (parents, autres classes). Introduction du contexte d''apprentissage et des réalisations des élèves.','Séance de partage organisée où les élèves présentent leurs projets de collection. Chaque élève explique sa collection, ses découvertes mathématiques et ses apprentissages. Questions et interactions avec le public.','Cercle de célébration finale. Chaque élève reçoit des commentaires positifs. Photo de groupe avec les collections. Planification des prochaines aventures mathématiques.','Maîtriser le concept de partage et; Appliquer les concepts mathématiques de base; Développer les stratégies de calcul par la célébration collective',NULL,NULL,NULL,'formative','{"observable":["L''élève présente ses apprentissages avec fierté et clarté","L''élève écoute respectueusement les présentations de ses pairs","L''élève pose des questions mathématiques pertinentes aux présentateurs","L''élève fait des connections entre son apprentissage et celui des autres","L''élève célèbre les succès mathématiques collectifs et individuels"],"checkpoints":["Articule clairement ses apprentissages sur les nombres teen","Démontre une appréciation et compréhension des apprentissages de ses pairs"]}',1,'Plan détaillé avec supports visuels',1756911653798,1757587623501,1,'fr','Mathématiques','{"pourDifficultés":["Utiliser des couleurs différentes pour chaque syllabe lors de la lecture","Utiliser des cartes visuelles avec images pour chaque mot nouveau","Offrir du temps supplémentaire pour compléter les activités"],"pourAvancés":["Encourager la création d''histoires originales avec début, milieu, fin","Proposer des textes plus complexes avec vocabulaire étendu","Permettre l''exploration de différents genres littéraires (poésie, théâtre)"],"pourLangue":["Créer des liens avec des mots similaires dans la langue première","Utiliser des images et symboles pour soutenir la compréhension","Permettre les explications dans la langue première si nécessaire"],"pourPEI":["Permettre différents moyens d''expression (oral, dessin, technologie)","Utiliser des minuteurs visuels pour structurer le temps","Adapter les outils d''écriture (crayons ergonomiques, guides-lignes)"]}','{"vocabulary":["partager","célébrer","fier"],"visualSupports":[["Affichage des apprentissages de l''unité","exemples de progrès","documentation visuelle du parcours"],["Support pour présentations nerveuses","ordre de passage affiché","questions guides pour le public"]],"movementBreaks":["Compter en sautant sur place de 11 à 20 (2 minutes)","Lever les bras en comptant, baisser en décomptant (3 minutes)","Marcher et compter: faire des pas correspondant aux nombres (2 minutes)","Taper des mains en comptant par groupes de 10 (2 minutes)","Tourner en comptant, changer de direction à chaque dizaine (3 minutes)","Compter en touchant différentes parties du corps (2 minutes)"]}',NULL,NULL,NULL,NULL,'{"questions":["Les élèves ont-ils atteint les objectifs?","Quelles adaptations étaient nécessaires?","Que ferais-je différemment la prochaine fois?"]}',NULL,'',2,19,'core',0);
INSERT INTO ETFOLessonPlan VALUES('cmf43u46e00znvj9txu69ecgb',23,'Réflexion et planification future','cmf43u45w00yjvj9tc3ls30b1',1763481600000,45,'Voyage dans le temps: ''Pensez au début de notre unité sur les nombres 11-20. Qu''est-ce qui a changé dans vos connaissances mathématiques?''','Réflexion guidée sur le parcours d''apprentissage. Création de portfolios ou journaux de bord. Discussion des mathématiques futures. Établissement d''objectifs personnels pour les prochains apprentissages.','Création d''un ''arbre des apprentissages'' collectif où chaque élève ajoute une feuille représentant un apprentissage important. Engagement pour l''aventure mathématique continue.','Résoudre le concept de réflexion et; Appliquer les concepts mathématiques de base; Développer les stratégies de calcul par la manipulation et le raisonnement','["Photos ou travaux du début de l''unité","Matériel pour portfolios","feuilles de réflexion","crayons et matériel d''art","exemples de mathématiques avancées","cartes de nombres 11-20 (2 jeux par classe)","blocs de base dix (ensembles complets)","tableau des nombres 1-20 (affiche murale)"]',NULL,'Réflexion et planification future','Voyage dans le temps: ''Pensez au début de notre unité sur les nombres 11-20. Qu''est-ce qui a changé dans vos connaissances mathématiques?''','Réflexion guidée sur le parcours d''apprentissage. Création de portfolios ou journaux de bord. Discussion des mathématiques futures. Établissement d''objectifs personnels pour les prochains apprentissages.','Création d''un ''arbre des apprentissages'' collectif où chaque élève ajoute une feuille représentant un apprentissage important. Engagement pour l''aventure mathématique continue.','Résoudre le concept de réflexion et; Appliquer les concepts mathématiques de base; Développer les stratégies de calcul par la manipulation et le raisonnement',NULL,NULL,NULL,'formative','{"observable":["L''élève identifie ses apprentissages les plus significatifs de l''unité","L''élève reconnaît les défis qu''il a surmontés avec les nombres teen","L''élève exprime ses questions ou curiosités pour les apprentissages futurs","L''élève évalue sa croissance mathématique depuis le début de l''unité","L''élève propose des goals personnels pour continuer son apprentissage numérique"],"checkpoints":["Démontre une métacognition développée sur ses apprentissages mathématiques","Exprime une motivation et vision positive pour ses apprentissages futurs en mathématiques"]}',1,'Plan détaillé avec supports visuels',1756911653799,1757587623501,1,'fr','Mathématiques','{"pourDifficultés":["Encourager l''utilisation de manipulatifs (lettres magnétiques, etc.)","Proposer des supports audio pour accompagner le texte écrit","Permettre les réponses gestuelles avant la production orale"],"pourAvancés":["Offrir des projets de recherche sur des auteurs franco-canadiens","Demander d''enseigner une nouvelle règle de français à un camarade","Encourager la création d''histoires originales avec début, milieu, fin"],"pourLangue":["Encourager le jumelage avec un pair plus fort en français","Offrir des gestes et actions pour accompagner les mots nouveaux","Créer des liens avec des mots similaires dans la langue première"],"pourPEI":["Utiliser des minuteurs visuels pour structurer le temps","Permettre différents moyens d''expression (oral, dessin, technologie)","Ajuster l''éclairage et réduire les distractions visuelles"]}','{"vocabulary":["réflexion","apprentissage","futur"],"visualSupports":[["Ligne de temps des apprentissages","comparaisons avant/après","portfolios individuels"],["Questions de réflexion affichées","exemples de portfolios","aperçu des mathématiques futures"]],"movementBreaks":["Compter en sautant sur place de 11 à 20 (2 minutes)","Lever les bras en comptant, baisser en décomptant (3 minutes)","Marcher et compter: faire des pas correspondant aux nombres (2 minutes)","Taper des mains en comptant par groupes de 10 (2 minutes)","Tourner en comptant, changer de direction à chaque dizaine (3 minutes)","Compter en touchant différentes parties du corps (2 minutes)"]}',NULL,NULL,NULL,NULL,'{"questions":["Les élèves ont-ils atteint les objectifs?","Quelles adaptations étaient nécessaires?","Que ferais-je différemment la prochaine fois?"]}',NULL,'',2,20,'core',1);
INSERT INTO ETFOLessonPlan VALUES('cmf43u46h00zrvj9tr8csiifz',23,'Découverte des motifs autour de nous','cmf43u46g00zpvj9tw2pwyb6r',1770998400000,45,'Promenade des motifs: Explorer la classe pour trouver des motifs (carreaux, rayures, points). ''Regardez partout! Les motifs sont cachés!''','Chasse aux motifs: Équipes explorent avec loupes pour documenter motifs trouvés. Dessiner ou photographier découvertes. Créer galerie de motifs de classe.','Partage des trésors: Chaque équipe présente son motif préféré trouvé. ''Qu''est-ce qui se répète?''','Identifier les motifs répétitifs; Appliquer des séquences répétitives créatives; Développer le sens du nombre par la manipulation et le raisonnement','["Matériel de classe"]',NULL,'Découverte des motifs autour de nous','Promenade des motifs: Explorer la classe pour trouver des motifs (carreaux, rayures, points). ''Regardez partout! Les motifs sont cachés!''','Chasse aux motifs: Équipes explorent avec loupes pour documenter motifs trouvés. Dessiner ou photographier découvertes. Créer galerie de motifs de classe.','Partage des trésors: Chaque équipe présente son motif préféré trouvé. ''Qu''est-ce qui se répète?''','Identifier les motifs répétitifs; Appliquer des séquences répétitives créatives; Développer le sens du nombre par la manipulation et le raisonnement',NULL,NULL,NULL,'formative','{"observable":["Élève identifie au moins 2 motifs différents dans l''environnement","Élève explique ce qui se répète dans un motif simple","Élève utilise vocabulaire: motif, répéter, même en contexte","Élève participe activement à l''exploration et documentation"],"checkpoints":["Pendant promenade: Vérifier si élève pointe vraiment des motifs","Pendant documentation: Observer qualité des dessins/descriptions","Pendant partage: Noter utilisation du vocabulaire des motifs"]}',1,'Plan détaillé avec supports visuels',1756911653801,1757594654424,1,'fr','Mathématiques','{"pourDifficultés":["Utiliser seulement motifs très évidents (rayures, pois) au début","Permettre travail en partenariat avec élève plus avancé","Fournir exemples pré-dessinés à compléter plutôt que création libre","Offrir plus de temps pour exploration avec moins de pression de documentation"],"pourAvancés":["Chercher motifs plus complexes (ABCD, patterns cachés)","Créer catégories de motifs trouvés (couleur, forme, taille)","Aider autres élèves à identifier motifs difficiles","Inventer nouveaux motifs inspirés des découvertes"],"pourLangue":["Associer mot ''motif'' avec gestes de répétition","Utiliser objets familiers culturellement pour premiers exemples","Permettre description en langue première puis traduction","Fournir vocabulaire visuel: répéter, même, encore"],"pourPEI":["Adapter exploration selon mobilité (zone restreinte si nécessaire)","Modifier outils de documentation (photos au lieu de dessins)","Ajuster attentes de participation (pointage au lieu de description)","Fournir supports sensoriels appropriés (réduction bruit, éclairage)"]}','{"vocabulary":["motif","répéter","même"],"visualSupports":["Affiches grandes avec exemples de motifs évidents: rayures, pois, carreaux","Affiches de motifs simples (AB, AAB, ABC), tableau d''exemples avec flèches montrant répétition","Espace d''affichage désigné pour galerie, cercle de rassemblement"],"movementBreaks":["Former des lettres dans l''air avec nos doigts : A, B, C (3 minutes)","Répéter des comptines avec gestes : ''Tête, épaules, genoux et pieds'' (2 minutes)","Faire des gestes de marionnettes pour raconter notre histoire (3 minutes)","Danser avec les sons : ''a'' avec les bras, ''o'' en rond, ''i'' pointu (3 minutes)","Ranger nos idées : faire semblant de mettre nos pensées dans une boîte (2 minutes)","Étirer notre dos d''écrivains : rotation douce des épaules (2 minutes)"]}',NULL,NULL,NULL,NULL,'{"questions":["Les élèves ont-ils atteint les objectifs?","Quelles adaptations étaient nécessaires?","Que ferais-je différemment la prochaine fois?"]}',NULL,'',2,1,'core',1);
INSERT INTO ETFOLessonPlan VALUES('cmf43u46i00ztvj9t56px2xby',23,'Construire des motifs simples','cmf43u46g00zpvj9tw2pwyb6r',1771862400000,45,'Révision énergique: ''Hier nous avons trouvé des motifs! Aujourd''hui nous en créons!'' Montrer modèle rouge-bleu-rouge-bleu.','Ateliers de construction: Station 1 - Tours AB avec blocs. Station 2 - Colliers AB avec perles. Station 3 - Lignes AB avec jetons. Rotation toutes les 8 minutes.','Galerie de motifs: Exposer créations et inviter commentaires. ''Quel motif continue le mieux?''','Explorer les motifs répétitifs; Appliquer des séquences répétitives créatives; Développer le sens du nombre par la manipulation et le raisonnement','["Matériel de classe"]',NULL,'Construire des motifs simples','Révision énergique: ''Hier nous avons trouvé des motifs! Aujourd''hui nous en créons!'' Montrer modèle rouge-bleu-rouge-bleu.','Ateliers de construction: Station 1 - Tours AB avec blocs. Station 2 - Colliers AB avec perles. Station 3 - Lignes AB avec jetons. Rotation toutes les 8 minutes.','Galerie de motifs: Exposer créations et inviter commentaires. ''Quel motif continue le mieux?''','Explorer les motifs répétitifs; Appliquer des séquences répétitives créatives; Développer le sens du nombre par la manipulation et le raisonnement',NULL,NULL,NULL,'formative','{"observable":["Élève crée motif AB correct avec au moins 4 éléments","Élève explique l''alternance dans son motif","Élève utilise vocabulaire: construire, alterner, suivant","Élève participe aux 3 stations avec engagement"],"checkpoints":["Station 1: Vérifier construction tours AB correctes","Station 2: Observer enfilage perles en alternance","Station 3: Noter alignement jetons selon motif AB"]}',1,'Plan détaillé avec supports visuels',1756911653802,1757594654425,1,'fr','Mathématiques','{"pourDifficultés":["Commencer avec seulement 4 éléments AB-AB au lieu de longues séquences","Utiliser objets plus gros et faciles à manipuler","Permettre imitation directe des modèles avant création libre","Fournir support verbal constant: ''rouge, bleu, rouge, bleu''"],"pourAvancés":["Introduire patterns AAB ou ABB s''ils maîtrisent AB","Créer motifs avec 3 couleurs (ABC)","Enseigner leur technique à un camarade","Inventer patterns originaux et les démontrer"],"pourLangue":["Associer ''alterner'' avec gestes de va-et-vient","Répéter vocabulaire: construire, suivant, alterner","Utiliser modèles visuels constants avec flèches","Permettre comptage rythmique dans langue première"],"pourPEI":["Adapter manipulatifs selon capacités motrices (plus gros, texturés)","Modifier attentes de production (montrer au lieu de construire)","Ajuster durée stations selon attention individuelle","Fournir supports visuels renforcés avec couleurs vives"]}','{"vocabulary":["construire","alterner","suivant"],"visualSupports":["Grand modèle AB au tableau avec flèches montrant alternance","Cartes modèles AB plastifiées à chaque station, code couleur au sol","Espace d''exposition organisé par type de motif"],"movementBreaks":["Faire l''alphabet avec notre corps : A comme arbre (étirer les bras), B comme ballon (forme ronde) (3 minutes)","Répéter des comptines avec gestes : ''Tête, épaules, genoux et pieds'' (2 minutes)","Étirer nos doigts et mains d''écrivains : ouvrir, fermer, tourner (2 minutes)","Danser avec les sons : ''a'' avec les bras, ''o'' en rond, ''i'' pointu (3 minutes)","Étirer notre dos d''écrivains : rotation douce des épaules (2 minutes)","Ranger nos idées : faire semblant de mettre nos pensées dans une boîte (2 minutes)"]}',NULL,NULL,NULL,NULL,'{"questions":["Les élèves ont-ils atteint les objectifs?","Quelles adaptations étaient nécessaires?","Que ferais-je différemment la prochaine fois?"]}',NULL,'',2,2,'core',1);
INSERT INTO ETFOLessonPlan VALUES('cmf43u46j00zvvj9tskuwennz',23,'Motifs sonores et corporels','cmf43u46g00zpvj9tw2pwyb6r',1771948800000,45,'Échauffement rythmique: ''Clap-clap-stomp, clap-clap-stomp'' avec mouvements corporels expressifs.','Exploration multi-sensorielle: Créer motifs avec voix (fort-doux), corps (saut-marche), instruments (tambour-cloche). Enregistrer créations musicales.','Concert de motifs: Chaque groupe présente son motif sonore. Audience devine le motif.','Découvrir les motifs répétitifs; Appliquer des séquences répétitives créatives; Développer le sens du nombre par la manipulation et le raisonnement','["Matériel de classe"]',NULL,'Motifs sonores et corporels','Échauffement rythmique: ''Clap-clap-stomp, clap-clap-stomp'' avec mouvements corporels expressifs.','Exploration multi-sensorielle: Créer motifs avec voix (fort-doux), corps (saut-marche), instruments (tambour-cloche). Enregistrer créations musicales.','Concert de motifs: Chaque groupe présente son motif sonore. Audience devine le motif.','Découvrir les motifs répétitifs; Appliquer des séquences répétitives créatives; Développer le sens du nombre par la manipulation et le raisonnement',NULL,NULL,NULL,'formative','{"observable":["Élève maintient motif rythmique simple sur 8 temps","Élève distingue entre sons forts et doux dans motifs","Élève utilise vocabulaire: rythme, son, mouvement","Élève participe aux créations collectives avec enthousiasme"],"checkpoints":["Pendant échauffement: Vérifier si suit le rythme de base","Pendant exploration: Observer créativité et coopération","Pendant concert: Noter capacité à maintenir motif en groupe"]}',1,'Plan détaillé avec supports visuels',1756911653803,1757594654426,1,'fr','Mathématiques','{"pourDifficultés":["Utiliser seulement 2 sons alternants (fort-doux) au début","Permettre imitation plutôt que création libre","Fournir support physique pour garder le rythme (tenir mains)","Utiliser motifs très courts (4 temps maximum)"],"pourAvancés":["Créer motifs à 3 éléments (fort-doux-moyen)","Combiner motifs corporels ET sonores simultanément","Diriger groupe comme chef d''orchestre","Inventer notation personnelle pour leurs motifs"],"pourLangue":["Associer mots à gestes clairs: rythme = battement régulier","Utiliser onomatopées universelles (boom, clap, ding)","Répéter vocabulaire avec actions motrices","Permettre expressions rythmiques de leur culture"],"pourPEI":["Adapter instruments selon capacités motrices (plus légers/lourds)","Modifier niveau sonore selon sensibilités auditives","Offrir participation par observation si préférée","Utiliser vibrations tactiles pour perception rythme"]}','{"vocabulary":["rythme","son","mouvement"],"visualSupports":["Cartes de gestes avec images: clap (mains), stomp (pieds)","Cartes de gestes, symboles pour sons forts/doux, pictogrammes mouvements","Espace de ''scène'' désigné, public assis en demi-cercle"],"movementBreaks":["Imiter les animaux des histoires : sauter comme un lapin, voler comme un oiseau (3 minutes)","Faire l''alphabet avec notre corps : A comme arbre (étirer les bras), B comme ballon (forme ronde) (3 minutes)","Étirer nos doigts et mains d''écrivains : ouvrir, fermer, tourner (2 minutes)","Danser avec les sons : ''a'' avec les bras, ''o'' en rond, ''i'' pointu (3 minutes)","Ranger nos idées : faire semblant de mettre nos pensées dans une boîte (2 minutes)","Dire au revoir avec tout notre corps : mains, têtes, pieds (2 minutes)"]}',NULL,NULL,NULL,NULL,'{"questions":["Les élèves ont-ils atteint les objectifs?","Quelles adaptations étaient nécessaires?","Que ferais-je différemment la prochaine fois?"]}',NULL,'',2,3,'core',1);
INSERT INTO ETFOLessonPlan VALUES('cmf43u46k00zxvj9thil96jzf',23,'Trier et classer nos trésors','cmf43u46g00zpvj9tw2pwyb6r',1772035200000,45,'Mystère du tri: Présenter boîte mélangée d''objets. ''Comment pouvons-nous organiser tout cela?''','Défis de tri: Trier par couleur, forme, taille, texture. Expliquer choix de tri. Deviner règle de tri d''un partenaire. Créer nouveau système de tri original.','Jeu ''Devine ma règle'': Un élève trie, les autres devinent la règle utilisée.','Ordonner le concept de trier et; Appliquer les concepts mathématiques de base; Développer le sens du nombre par la manipulation et le raisonnement','["Matériel de classe"]',NULL,'Trier et classer nos trésors','Mystère du tri: Présenter boîte mélangée d''objets. ''Comment pouvons-nous organiser tout cela?''','Défis de tri: Trier par couleur, forme, taille, texture. Expliquer choix de tri. Deviner règle de tri d''un partenaire. Créer nouveau système de tri original.','Jeu ''Devine ma règle'': Un élève trie, les autres devinent la règle utilisée.','Ordonner le concept de trier et; Appliquer les concepts mathématiques de base; Développer le sens du nombre par la manipulation et le raisonnement',NULL,NULL,NULL,'formative','{"observable":["Élève trie objets selon au moins un attribut de façon cohérente","Élève explique sa règle de classification simplement","Élève utilise vocabulaire: trier, groupe, règle, attribut","Élève respecte classifications différentes des autres"],"checkpoints":["Pendant exploration: Vérifier cohérence des groupes créés","Pendant explication: Noter clarté de justification","Pendant jeu final: Observer capacité à deviner règles"]}',1,'Plan détaillé avec supports visuels',1756911653804,1757594654427,1,'fr','Mathématiques','{"pourDifficultés":["Commencer avec seulement 2 groupes de tri évidents (rouge vs bleu)","Utiliser objets très différents pour faciliter distinction","Permettre travail avec partenaire pour support","Fournir modèles visuels constants pour chaque attribut"],"pourAvancés":["Créer systèmes de tri à double critère (couleur ET forme)","Inventer nouvelles catégories non-évidentes","Enseigner stratégie de tri à d''autres élèves","Défier classe avec tris complexes à deviner"],"pourLangue":["Associer chaque attribut à geste ou image claire","Répéter vocabulaire: trier = séparer, groupe = ensemble","Utiliser objets familiers culturellement","Permettre explication en langue première puis traduction"],"pourPEI":["Adapter taille objets selon capacités motrices fines","Modifier nombre d''objets à trier (moins si fatigue)","Utiliser supports visuels renforcés avec couleurs vives","Accepter pointage au lieu de manipulation si nécessaire"]}','{"vocabulary":["trier","groupe","règle","attribut"],"visualSupports":["Boîte transparente pleine d''objets mélangés, tableaux de classification vierges","Cercles de tri colorés, cartes d''attributs affichées, exemples de classifications au tableau","Espace de démonstration désigné, cercle pour audience"],"movementBreaks":["Marcher en syllabant notre nom : Ma-rie, Paul, etc. en tapant dans nos mains (2 minutes)","Former des lettres dans l''air avec nos doigts : A, B, C (3 minutes)","Marcher sur place en récitant l''alphabet lentement (2 minutes)","Faire des gestes de marionnettes pour raconter notre histoire (3 minutes)","Étirer notre dos d''écrivains : rotation douce des épaules (2 minutes)","Ranger nos idées : faire semblant de mettre nos pensées dans une boîte (2 minutes)"]}',NULL,NULL,NULL,NULL,'{"questions":["Les élèves ont-ils atteint les objectifs?","Quelles adaptations étaient nécessaires?","Que ferais-je différemment la prochaine fois?"]}',NULL,'',2,4,'core',1);
INSERT INTO ETFOLessonPlan VALUES('cmf43u46l00zzvj9t2eo5pj16',23,'Prédire la suite des motifs','cmf43u46g00zpvj9tw2pwyb6r',1772121600000,45,'Jeu de devinette: Montrer début de motif ''rouge-bleu-rouge-?'' Suspense: ''Qu''est-ce qui vient ensuite?''','Détectives de motifs: Compléter motifs interrompus. Prédire suite avec confidence. Vérifier prédictions. Créer motifs pour défier camarades.','Cercle de prédiction: Chacun propose motif, classe prédit ensemble l''élément suivant.','Représenter les motifs répétitifs; Appliquer des séquences répétitives créatives; Développer la pensée logique par la manipulation et le raisonnement','["Matériel de classe"]',NULL,'Prédire la suite des motifs','Jeu de devinette: Montrer début de motif ''rouge-bleu-rouge-?'' Suspense: ''Qu''est-ce qui vient ensuite?''','Détectives de motifs: Compléter motifs interrompus. Prédire suite avec confidence. Vérifier prédictions. Créer motifs pour défier camarades.','Cercle de prédiction: Chacun propose motif, classe prédit ensemble l''élément suivant.','Représenter les motifs répétitifs; Appliquer des séquences répétitives créatives; Développer la pensée logique par la manipulation et le raisonnement',NULL,NULL,NULL,'formative','{"observable":["Élève prédit correctement suite dans motifs AB simples","Élève explique sa stratégie de prédiction (''je regarde ce qui se répète'')","Élève utilise vocabulaire: prédire, suivant, après","Élève montre confiance en faisant des tentatives"],"checkpoints":["Pendant démonstration: Vérifier prédictions initiales","Pendant travail individuel: Observer stratégies utilisées","Pendant cercle: Noter participation et justifications"]}',1,'Plan détaillé avec supports visuels',1756911653805,1757594654428,1,'fr','Mathématiques','{"pourDifficultés":["Utiliser seulement motifs AB très courts (4 éléments maximum)","Donner indices verbaux: ''Regarde, c''est rouge, bleu, rouge...''","Permettre manipulation physique avant prédiction","Offrir choix multiples au lieu de réponse libre"],"pourAvancés":["Introduire motifs plus complexes (AABB, ABCD)","Créer motifs à multiples attributs (couleur ET forme)","Défier classe avec séquences longues","Prédire plusieurs éléments suivants au lieu d''un seul"],"pourLangue":["Répéter ''prédire'' avec geste de regarder vers l''avenir","Utiliser ''suivant'' avec mouvement de doigt vers droite","Associer ''?'' avec expression faciale questionnante","Permettre prédiction par gestes avant mots"],"pourPEI":["Adapter présentation selon besoins visuels (plus gros, contraste)","Modifier attentes: pointer au lieu de nommer","Utiliser supports tactiles si nécessaire","Ajuster nombre de prédictions attendues"]}','{"vocabulary":["prédire","suivant","après"],"visualSupports":["Séquence visible au tableau avec espace pour prédiction","Cartes avec points d''interrogation, flèches de direction, tableau de réponses","Cercle au sol, espace central pour démonstrations"],"movementBreaks":["Faire l''alphabet avec notre corps : A comme arbre (étirer les bras), B comme ballon (forme ronde) (3 minutes)","Former des lettres dans l''air avec nos doigts : A, B, C (3 minutes)","Danser avec les sons : ''a'' avec les bras, ''o'' en rond, ''i'' pointu (3 minutes)","Faire des gestes de marionnettes pour raconter notre histoire (3 minutes)","Dire au revoir avec tout notre corps : mains, têtes, pieds (2 minutes)","Ranger nos idées : faire semblant de mettre nos pensées dans une boîte (2 minutes)"]}',NULL,NULL,NULL,NULL,'{"questions":["Les élèves ont-ils atteint les objectifs?","Quelles adaptations étaient nécessaires?","Que ferais-je différemment la prochaine fois?"]}',NULL,'',2,5,'core',1);
INSERT INTO ETFOLessonPlan VALUES('cmf43u46l0101vj9tf15moha3',23,'Motifs complexes ABC','cmf43u46g00zpvj9tw2pwyb6r',1772208000000,45,'Évolution des motifs: Réviser AB, puis révéler ''Aujourd''hui: rouge-bleu-vert-rouge-bleu-vert!''','Défis ABC: Construire motifs à trois éléments. Transformer motifs AB en ABC. Inventer motifs ABC originaux. Enseigner motif à un partenaire.','Exposition ABC: Présenter créations et expliquer la ''règle de trois'' de leur motif.','Compter les motifs répétitifs; Appliquer des séquences répétitives créatives; Développer la pensée logique par la manipulation et le raisonnement','["Matériel de classe"]',NULL,'Motifs complexes ABC','Évolution des motifs: Réviser AB, puis révéler ''Aujourd''hui: rouge-bleu-vert-rouge-bleu-vert!''','Défis ABC: Construire motifs à trois éléments. Transformer motifs AB en ABC. Inventer motifs ABC originaux. Enseigner motif à un partenaire.','Exposition ABC: Présenter créations et expliquer la ''règle de trois'' de leur motif.','Compter les motifs répétitifs; Appliquer des séquences répétitives créatives; Développer la pensée logique par la manipulation et le raisonnement',NULL,NULL,NULL,'formative','{"observable":["Élève crée motif ABC correct sur au moins 6 éléments","Élève explique le cycle de trois dans son motif","Élève utilise vocabulaire: trois, cycle, recommencer","Élève distingue entre motifs AB et ABC correctement"],"checkpoints":["Pendant construction: Vérifier séquence ABC répétée","Pendant transformation: Observer compréhension des différences","Pendant exposition: Noter clarté des explications"]}',1,'Plan détaillé avec supports visuels',1756911653806,1757594654429,1,'fr','Mathématiques','{"pourDifficultés":["Rester avec motifs AB jusqu''à maîtrise complète","Utiliser seulement 6 éléments ABC-ABC au lieu de longues séquences","Fournir modèle à copier avant création libre","Compter à voix haute: un-deux-trois-un-deux-trois"],"pourAvancés":["Créer motifs ABCD ou patterns plus complexes","Combiner attributs: couleur ET forme en patterns","Inventer systèmes de notation pour leurs motifs","Enseigner technique ABC à élèves en difficulté"],"pourLangue":["Associer ''trois'' avec gestes des doigts clairs","Répéter ''cycle'' avec mouvement circulaire","Utiliser ''recommencer'' avec geste de retour au début","Compter en langue première puis en français"],"pourPEI":["Adapter matériel selon capacités motrices (plus gros, légers)","Réduire nombre d''éléments si concentration limitée","Utiliser supports visuels renforcés avec couleurs vives","Permettre pauses fréquentes pour éviter surcharge"]}','{"vocabulary":["trois","cycle","recommencer"],"visualSupports":["Séquence AB au tableau, puis ABC avec flèche montrant cycle","Cartes modèles ABC plastifiées, code couleur pour séquences, lignes de construction","Zone d''exposition désignée, cercle pour présentations"],"movementBreaks":["Former des lettres dans l''air avec nos doigts : A, B, C (3 minutes)","Répéter des comptines avec gestes : ''Tête, épaules, genoux et pieds'' (2 minutes)","Marcher sur place en récitant l''alphabet lentement (2 minutes)","Faire des gestes de marionnettes pour raconter notre histoire (3 minutes)","Étirer notre dos d''écrivains : rotation douce des épaules (2 minutes)","Faire une révérence à nos nouvelles connaissances (1 minute)"]}',NULL,NULL,NULL,NULL,'{"questions":["Les élèves ont-ils atteint les objectifs?","Quelles adaptations étaient nécessaires?","Que ferais-je différemment la prochaine fois?"]}',NULL,'',2,6,'core',1);
INSERT INTO ETFOLessonPlan VALUES('cmf43u46m0103vj9th9afxmv4',23,'Motifs dans la nature','cmf43u46g00zpvj9tw2pwyb6r',1772467200000,45,'Préparation d''explorateurs: ''La nature est pleine de motifs secrets! Devenons des détectives nature!''','Expédition nature: Explorer extérieur pour motifs (feuilles, fleurs, écorce, nuages). Dessiner découvertes. Créer collection de motifs naturels. Comparer avec motifs artificiels.','Musée nature: Exposer trouvailles et discuter ''Pourquoi la nature fait-elle des motifs?''','Calculer les motifs répétitifs; Appliquer des séquences répétitives créatives; Développer la pensée logique par la manipulation et le raisonnement','["Matériel de classe"]',NULL,'Motifs dans la nature','Préparation d''explorateurs: ''La nature est pleine de motifs secrets! Devenons des détectives nature!''','Expédition nature: Explorer extérieur pour motifs (feuilles, fleurs, écorce, nuages). Dessiner découvertes. Créer collection de motifs naturels. Comparer avec motifs artificiels.','Musée nature: Exposer trouvailles et discuter ''Pourquoi la nature fait-elle des motifs?''','Calculer les motifs répétitifs; Appliquer des séquences répétitives créatives; Développer la pensée logique par la manipulation et le raisonnement',NULL,NULL,NULL,'formative','{"observable":["Élève identifie au moins 3 motifs différents dans la nature","Élève documente découvertes par dessin ou collection","Élève utilise vocabulaire: nature, découvrir, observer","Élève fait liens entre motifs naturels et artificiels"],"checkpoints":["Pendant exploration: Vérifier découvertes authentiques de motifs","Pendant documentation: Observer qualité des représentations","Pendant partage: Noter vocabulaire et explications"]}',1,'Plan détaillé avec supports visuels',1756911653807,1757594654430,1,'fr','Mathématiques','{"pourDifficultés":["Fournir images de motifs naturels à chercher spécifiquement","Permettre travail en partenariat avec guide","Utiliser zone restreinte pour exploration plus focalisée","Accepter dessins simples au lieu de représentations détaillées"],"pourAvancés":["Chercher motifs plus subtils (textures, organisations)","Catégoriser découvertes par type de motif (spirales, rayés, etc.)","Créer hypothèses sur pourquoi motifs existent dans nature","Documenter avec descriptions détaillées écrites"],"pourLangue":["Associer vocabulaire nature avec objets réels touchés","Utiliser ''découvrir'' avec geste de chercher et trouver","Répéter ''observer'' avec gestes des yeux","Permettre descriptions en langue première puis traduction"],"pourPEI":["Adapter exploration selon mobilité (zones accessibles)","Modifier outils selon capacités motrices (crayons plus gros)","Ajuster durée extérieure selon tolérance","Fournir alternatives sensorielles (tactiles, auditives)"]}','{"vocabulary":["nature","découvrir","observer"],"visualSupports":["Images de motifs naturels: spirales coquillages, rayées zèbres, écailles poissons","Guide visuel de motifs naturels, carnet d''exploration structuré avec sections","Zone d''exposition organisée, étiquettes pour classification"],"movementBreaks":["Former des lettres dans l''air avec nos doigts : A, B, C (3 minutes)","Faire l''alphabet avec notre corps : A comme arbre (étirer les bras), B comme ballon (forme ronde) (3 minutes)","Danser avec les sons : ''a'' avec les bras, ''o'' en rond, ''i'' pointu (3 minutes)","Étirer nos doigts et mains d''écrivains : ouvrir, fermer, tourner (2 minutes)","Célébrer nos apprentissages : applaudir, lever les bras, sourire (2 minutes)","Étirer notre dos d''écrivains : rotation douce des épaules (2 minutes)"]}',NULL,NULL,NULL,NULL,'{"questions":["Les élèves ont-ils atteint les objectifs?","Quelles adaptations étaient nécessaires?","Que ferais-je différemment la prochaine fois?"]}',NULL,'',2,7,'core',1);
INSERT INTO ETFOLessonPlan VALUES('cmf43u46n0105vj9tfewzhzsp',23,'Réparer des motifs brisés','cmf43u46g00zpvj9tw2pwyb6r',1772553600000,45,'Alerte motifs brisés: ''Oh non! Des motifs sont cassés! Nous sommes les réparateurs de motifs!''','Clinique de réparation: Diagnostiquer erreurs dans motifs présentés. Expliquer où est le problème. Proposer corrections. Vérifier réparations avec partenaire.','Certificat de réparateur: Célébrer succès et remettre ''diplômes de réparateurs de motifs''.','Mesurer les motifs répétitifs; Appliquer des séquences répétitives créatives; Développer la pensée logique par la manipulation et le raisonnement','["Matériel de classe"]',NULL,'Réparer des motifs brisés','Alerte motifs brisés: ''Oh non! Des motifs sont cassés! Nous sommes les réparateurs de motifs!''','Clinique de réparation: Diagnostiquer erreurs dans motifs présentés. Expliquer où est le problème. Proposer corrections. Vérifier réparations avec partenaire.','Certificat de réparateur: Célébrer succès et remettre ''diplômes de réparateurs de motifs''.','Mesurer les motifs répétitifs; Appliquer des séquences répétitives créatives; Développer la pensée logique par la manipulation et le raisonnement',NULL,NULL,NULL,'formative','{"observable":["Élève identifie erreurs dans motifs AB et ABC simples","Élève propose corrections appropriées pour rétablir motif","Élève utilise vocabulaire: erreur, réparer, corriger","Élève explique pourquoi élément ne correspond pas au motif"],"checkpoints":["Pendant diagnostic: Vérifier détection précise des erreurs","Pendant réparation: Observer logêque des corrections","Pendant vérification: Noter compréhension du motif réparé"]}',1,'Plan détaillé avec supports visuels',1756911653807,1757594654431,1,'fr','Mathématiques','{"pourDifficultés":["Commencer avec erreurs très évidentes (couleur complètement différente)","Montrer motif correct à côté pour comparaison","Permettre travail en équipe pour support mutuel","Accepter identification d''erreur même sans correction parfaite"],"pourAvancés":["Présenter erreurs plus subtiles (formes similaires)","Donner motifs avec erreurs multiples à réparer","Demander création de motifs brisés pour défier camarades","Expliquer pourquoi erreur brise le motif"],"pourLangue":["Associer ''erreur'' avec geste de ''non'' ou ''stop''","Montrer ''réparer'' avec gestes de réparation","Utiliser ''corriger'' avec mouvement de changement","Répéter vocabulaire avec actions concrètes"],"pourPEI":["Utiliser erreurs visuelles très contrastantes","Modifier nombre d''erreurs à chercher selon attention","Permettre pointage au lieu de manipulation si nécessaire","Adapter outils de correction selon capacités motrices"]}','{"vocabulary":["erreur","réparer","corriger"],"visualSupports":["Exemple de motif cassé vs réparé au tableau","Cartes diagnostiques, outils de réparation visuels, tableau avant/après","Espace cérémoniel pour remise de certificats"],"movementBreaks":["Marcher en syllabant notre nom : Ma-rie, Paul, etc. en tapant dans nos mains (2 minutes)","Répéter des comptines avec gestes : ''Tête, épaules, genoux et pieds'' (2 minutes)","Faire une pause lecture : s''étirer comme un chat qui se réveille (2 minutes)","Danser avec les sons : ''a'' avec les bras, ''o'' en rond, ''i'' pointu (3 minutes)","Étirer notre dos d''écrivains : rotation douce des épaules (2 minutes)","Dire au revoir avec tout notre corps : mains, têtes, pieds (2 minutes)"]}',NULL,NULL,NULL,NULL,'{"questions":["Les élèves ont-ils atteint les objectifs?","Quelles adaptations étaient nécessaires?","Que ferais-je différemment la prochaine fois?"]}',NULL,'',2,8,'core',1);
INSERT INTO ETFOLessonPlan VALUES('cmf43u46o0107vj9tz0pf6y4e',23,'Comparer et contraster des motifs','cmf43u46g00zpvj9tw2pwyb6r',1772640000000,45,'Jeu des jumeaux: Présenter motifs similaires. ''Sont-ils identiques ou différents? Comment le savez-vous?''','Laboratoire de comparaison: Analyser paires de motifs. Identifier points communs et différences. Classer motifs par familles. Créer motifs ''cousins'' (similaires mais pas identiques).','Galerie de familles: Exposer groupes de motifs similaires et expliquer liens de parenté.','Comparer les motifs répétitifs; Appliquer des séquences répétitives créatives; Développer le raisonnement spatial par la manipulation et le raisonnement','["Matériel de classe"]',NULL,'Comparer et contraster des motifs','Jeu des jumeaux: Présenter motifs similaires. ''Sont-ils identiques ou différents? Comment le savez-vous?''','Laboratoire de comparaison: Analyser paires de motifs. Identifier points communs et différences. Classer motifs par familles. Créer motifs ''cousins'' (similaires mais pas identiques).','Galerie de familles: Exposer groupes de motifs similaires et expliquer liens de parenté.','Comparer les motifs répétitifs; Appliquer des séquences répétitives créatives; Développer le raisonnement spatial par la manipulation et le raisonnement',NULL,NULL,NULL,'formative','{"observable":["Élève identifie similarités et différences entre motifs simples","Élève groupe motifs similaires ensemble correctement","Élève utilise vocabulaire: comparer, similaire, différent, famille","Élève explique ses critères de regroupement"],"checkpoints":["Pendant comparaisons: Vérifier précision des observations","Pendant classification: Observer logêque des regroupements","Pendant présentation: Noter utilisation vocabulaire spécifique"]}',1,'Plan détaillé avec supports visuels',1756911653808,1757594654432,1,'fr','Mathématiques','{"pourDifficultés":["Utiliser seulement comparaisons très évidentes (AB vs CD)","Fournir phrases à compléter: ''C''est pareil parce que..., c''est différent parce que...''","Permettre comparaisons par pointage avant verbalisation","Travailler avec seulement 2 motifs à la fois"],"pourAvancés":["Comparer motifs avec multiples attributs (couleur ET forme)","Créer système de classification original","Identifier sous-catégories dans familles (AB courts vs longs)","Expliquer pourquoi certains motifs appartiennent à même famille"],"pourLangue":["Utiliser gestes pour ''similaire'' (rapprocher) et ''différent'' (éloigner)","Répéter ''comparer'' avec geste des yeux allant d''un à l''autre","Associer ''famille'' avec geste de regroupement","Utiliser objets concrets familiers pour premiers comparaisons"],"pourPEI":["Adapter présentation visuelle (contraste, taille)","Réduire nombre de motifs à comparer simultanément","Utiliser supports tactiles pour distinction","Modifier attentes de production verbale selon capacités"]}','{"vocabulary":["comparer","similaire","différent","famille"],"visualSupports":["Paires de motifs affichées côte à côte pour comparaison directe","Tableaux Venn simples, cartes de comparaison, codes couleur par famille","Espace exposition organisé par familles, étiquettes claires"],"movementBreaks":["Former des lettres dans l''air avec nos doigts : A, B, C (3 minutes)","Faire l''alphabet avec notre corps : A comme arbre (étirer les bras), B comme ballon (forme ronde) (3 minutes)","Faire des gestes de marionnettes pour raconter notre histoire (3 minutes)","Danser avec les sons : ''a'' avec les bras, ''o'' en rond, ''i'' pointu (3 minutes)","Faire une révérence à nos nouvelles connaissances (1 minute)","Ranger nos idées : faire semblant de mettre nos pensées dans une boîte (2 minutes)"]}',NULL,NULL,NULL,NULL,'{"questions":["Les élèves ont-ils atteint les objectifs?","Quelles adaptations étaient nécessaires?","Que ferais-je différemment la prochaine fois?"]}',NULL,'',2,9,'core',1);
INSERT INTO ETFOLessonPlan VALUES('cmf43u46p0109vj9tb4hesm58',23,'Créer des motifs personnels','cmf43u46g00zpvj9tw2pwyb6r',1772726400000,45,'Inspiration créative: ''Vous êtes maintenant des artistes de motifs! Créez quelque chose que personne n''a jamais vu!''','Atelier création libre: Inventer motifs personnels uniques. Utiliser couleurs, formes, textures préférées. Documenter dans cahier personnel. Enseigner motif à quelqu''un d''autre.','Vernissage personnel: Chaque artiste présente sa création unique et explique son inspiration.','Ordonner les motifs répétitifs; Créer des séquences répétitives créatives; Développer le raisonnement spatial par la manipulation et le raisonnement','["autocollants motivants (1 planche)","livres d''images variés (6-8 livres)","crayons de couleur (boîte de 24)","fiches de mots illustrées (50 cartes)","papier ligné pour débutants (30 feuilles)","cahiers d''écriture (30 cahiers)","livrets de lecture simple (niveau débutant, 15 copies)","marqueurs effaçables (15 marqueurs)","chemises individuelles (30 chemises)","étiquettes autocollantes (2 planches)","boîte de rangement pour travaux (1 grande boîte)"]',NULL,'Créer des motifs personnels','Inspiration créative: ''Vous êtes maintenant des artistes de motifs! Créez quelque chose que personne n''a jamais vu!''','Atelier création libre: Inventer motifs personnels uniques. Utiliser couleurs, formes, textures préférées. Documenter dans cahier personnel. Enseigner motif à quelqu''un d''autre.','Vernissage personnel: Chaque artiste présente sa création unique et explique son inspiration.','Ordonner les motifs répétitifs; Créer des séquences répétitives créatives; Développer le raisonnement spatial par la manipulation et le raisonnement',NULL,NULL,NULL,'formative','{"observable":["Élève crée motif personnel cohérent et répétable","Élève explique les choix dans sa création","Élève utilise vocabulaire: créer, unique, personnel","Élève montre fierté et ownership de sa création"],"checkpoints":["Pendant création: Vérifier originalité et cohérence du motif","Pendant documentation: Observer soin et précision","Pendant présentation: Noter confiance et clarté d''explication"]}',1,'Plan détaillé avec supports visuels',1756911653809,1757594654433,1,'fr','Mathématiques','{"pourDifficultés":["Simplifier avec seulement 2 couleurs/formes pour premiers motifs","Fournir modèles concrets à imiter avant création libre","Permettre collaboration avec partenaire plus expérimenté","Accepter motifs plus courts (4-6 éléments) comme réussites"],"pourAvancés":["Créer motifs avec multiples attributs (couleur ET forme ET taille)","Inventer nouveaux types de motifs non-enseignés","Défier classe avec motifs complexes à continuer","Créer histoire ou chanson incorporant leur motif personnel"],"pourLangue":["Associer ''créer'' avec gestes de construction/invention","Répéter ''unique'' avec geste de ''seulement un''","Utiliser ''personnel'' en montrant soi-même","Permettre création motifs inspirés de leur culture d''origine"],"pourPEI":["Adapter matériel selon besoins moteurs (plus gros, légers)","Modifier attentes créatives selon capacités","Utiliser supports visuels renforcés pour inspiration","Permettre expression non-verbale de la créativité"]}','{"vocabulary":["créer","unique","personnel"],"visualSupports":["Galerie d''inspiration, matériaux organisés par type, exemples de créativité"],"movementBreaks":["Répéter des comptines avec gestes : ''Tête, épaules, genoux et pieds'' (2 minutes)","Faire l''alphabet avec notre corps : A comme arbre (étirer les bras), B comme ballon (forme ronde) (3 minutes)","Étirer nos doigts et mains d''écrivains : ouvrir, fermer, tourner (2 minutes)","Danser avec les sons : ''a'' avec les bras, ''o'' en rond, ''i'' pointu (3 minutes)","Célébrer nos apprentissages : applaudir, lever les bras, sourire (2 minutes)","Étirer notre dos d''écrivains : rotation douce des épaules (2 minutes)"]}',NULL,NULL,NULL,NULL,'{"questions":["Les élèves ont-ils atteint les objectifs?","Quelles adaptations étaient nécessaires?","Que ferais-je différemment la prochaine fois?"]}',NULL,'',2,10,'core',1);
INSERT INTO ETFOLessonPlan VALUES('cmf43u46q010bvj9tnctibdrn',23,'Motifs cachés - résolution de mystères','cmf43u46g00zpvj9tw2pwyb6r',1772812800000,45,'Mission secrète: ''Agents secrets, des motifs sont cachés dans des codes mystérieux! Mission: les décoder!''','Enquêtes de motifs: Résoudre motifs avec parties couvertes. Utiliser indices pour prédire parties cachées. Créer cartes mystère pour défier camarades. Documenter méthodes de résolution.','Rapport d''agents: Présenter résolutions et expliquer méthodes de déduction utilisées.','Représenter les motifs répétitifs; Appliquer des séquences répétitives créatives; Développer le raisonnement spatial par la manipulation et le raisonnement','["Matériel de classe"]',NULL,'Motifs cachés - résolution de mystères','Mission secrète: ''Agents secrets, des motifs sont cachés dans des codes mystérieux! Mission: les décoder!''','Enquêtes de motifs: Résoudre motifs avec parties couvertes. Utiliser indices pour prédire parties cachées. Créer cartes mystère pour défier camarades. Documenter méthodes de résolution.','Rapport d''agents: Présenter résolutions et expliquer méthodes de déduction utilisées.','Représenter les motifs répétitifs; Appliquer des séquences répétitives créatives; Développer le raisonnement spatial par la manipulation et le raisonnement',NULL,NULL,NULL,'formative','{"observable":["Élève résout motifs simples avec 1-2 éléments cachés","Élève explique sa stratégie de déduction","Élève utilise vocabulaire: mystère, révéler, déduire","Élève persiste face aux défis sans abandonner rapidement"],"checkpoints":["Pendant résolution: Observer stratégies utilisées","Pendant création: Vérifier compréhension du concept mystère","Pendant rapport: Noter clarté des explications logiques"]}',1,'Plan détaillé avec supports visuels',1756911653810,1757594654434,1,'fr','Mathématiques','{"pourDifficultés":["Commencer avec seulement 1 élément caché à la fin du motif","Fournir choix multiples au lieu de réponse libre","Permettre travail en partenariat pour soutien mutuel","Révéler progressivement plus d''indices si blocage"],"pourAvancés":["Présenter motifs avec plusieurs éléments cachés non-consécutifs","Créer motifs mystères originaux pour défier la classe","Résoudre motifs à double attributs (couleur ET forme cachés)","Expliquer stratégies de déduction à d''autres élèves"],"pourLangue":["Associer ''mystère'' avec geste de questionner et chercher","Utiliser ''révéler'' avec mouvement de découvrir","Répéter ''déduire'' avec geste de réflexion logique","Permettre explication de stratégie en langue première d''abord"],"pourPEI":["Adapter présentation visuelle (contraste, taille des cachettes)","Réduire nombre de mystères à résoudre selon attention","Utiliser supports tactiles pour exploration des motifs","Modifier attentes de documentation selon capacités"]}','{"vocabulary":["mystère","révéler","déduire"],"visualSupports":["Exemple de motif avec révélation progressive au tableau","Cartes avec révélations progressives, tableau de stratégies de déduction","Espace rapport avec mystères résolus affichés"],"movementBreaks":["Répéter des comptines avec gestes : ''Tête, épaules, genoux et pieds'' (2 minutes)","Marcher en syllabant notre nom : Ma-rie, Paul, etc. en tapant dans nos mains (2 minutes)","Danser avec les sons : ''a'' avec les bras, ''o'' en rond, ''i'' pointu (3 minutes)","Faire une pause lecture : s''étirer comme un chat qui se réveille (2 minutes)","Dire au revoir avec tout notre corps : mains, têtes, pieds (2 minutes)","Faire une révérence à nos nouvelles connaissances (1 minute)"]}',NULL,NULL,NULL,NULL,'{"questions":["Les élèves ont-ils atteint les objectifs?","Quelles adaptations étaient nécessaires?","Que ferais-je différemment la prochaine fois?"]}',NULL,'',2,11,'core',1);
INSERT INTO ETFOLessonPlan VALUES('cmf43u46q010dvj9ttvrpza0j',23,'Motifs temporels et calendriers','cmf43u46g00zpvj9tw2pwyb6r',1773068400000,45,'Voyage dans le temps: ''Les motifs ne sont pas que dans l''espace, ils sont aussi dans le TEMPS!''','Exploration temporelle: Identifier motifs dans semaine (lundi-mardi-...). Observer motifs météo. Créer calendrier personnel avec motifs d''activités. Prédire motifs futurs.','Prophètes du temps: Prédire motifs de demain, semaine prochaine, saison suivante.','Compter les motifs répétitifs; Appliquer des séquences répétitives créatives; Développer le raisonnement spatial par la manipulation et le raisonnement','["marionnettes simples (3-4 personnages)","livres d''images variés (6-8 livres)","tableau d''écriture ou grande feuille","marqueurs effaçables (15 marqueurs)","papier ligné pour débutants (30 feuilles)","lettres magnétiques (jeu complet A-Z)","cahiers d''écriture (30 cahiers)","fiches de mots illustrées (50 cartes)","boîte de rangement pour travaux (1 grande boîte)","tampons motivants avec encreur (5 tampons)","étiquettes autocollantes (2 planches)"]',NULL,'Motifs temporels et calendriers','Voyage dans le temps: ''Les motifs ne sont pas que dans l''espace, ils sont aussi dans le TEMPS!''','Exploration temporelle: Identifier motifs dans semaine (lundi-mardi-...). Observer motifs météo. Créer calendrier personnel avec motifs d''activités. Prédire motifs futurs.','Prophètes du temps: Prédire motifs de demain, semaine prochaine, saison suivante.','Compter les motifs répétitifs; Appliquer des séquences répétitives créatives; Développer le raisonnement spatial par la manipulation et le raisonnement',NULL,NULL,NULL,'formative','{"observable":["L''élève manipule le matériel mathématique avec aisance","L''élève explique sa pensée mathématique en français simple","L''élève fait des liens entre les concepts et la vie quotidienne","L''élève vérifie ses réponses en utilisant une autre stratégie"],"checkpoints":["Comprend le concept mathématique ciblé","Utilise le vocabulaire mathématique approprié","Applique la stratégie apprise à de nouveaux problèmes","Montre sa compréhension par des exemples concrets"]}',1,'Plan détaillé avec supports visuels',1756911653811,1757594654435,1,'fr','Mathématiques','{"pourDifficultés":["Offrir du temps supplémentaire pour compléter les activités","Permettre les réponses gestuelles avant la production orale","Utiliser des cartes visuelles avec images pour chaque mot nouveau"],"pourAvancés":["Proposer des défis de vocabulaire avec mots plus sophistiqués","Offrir des projets de recherche sur des auteurs franco-canadiens","Proposer des textes plus complexes avec vocabulaire étendu"],"pourLangue":["Utiliser des images et symboles pour soutenir la compréhension","Offrir des gestes et actions pour accompagner les mots nouveaux","Répéter les consignes importantes avec des gestes clairs"],"pourPEI":["Offrir des pauses sensorielles fréquentes selon les besoins","Adapter les outils d''écriture (crayons ergonomiques, guides-lignes)","Utiliser des supports visuels clairs et contrastés"]}','{"vocabulary":["temps","jour","semaine","cycle"],"visualSupports":["Calendriers colorés, cartes temporelles, graphiques de routine"],"movementBreaks":["Former des lettres dans l''air avec nos doigts : A, B, C (3 minutes)","Marcher en syllabant notre nom : Ma-rie, Paul, etc. en tapant dans nos mains (2 minutes)","Faire des gestes de marionnettes pour raconter notre histoire (3 minutes)","Faire une pause lecture : s''étirer comme un chat qui se réveille (2 minutes)","Étirer notre dos d''écrivains : rotation douce des épaules (2 minutes)","Faire une révérence à nos nouvelles connaissances (1 minute)"]}',NULL,NULL,NULL,NULL,'{"questions":["Les élèves ont-ils atteint les objectifs?","Quelles adaptations étaient nécessaires?","Que ferais-je différemment la prochaine fois?"]}',NULL,'',2,12,'core',1);
