INSERT INTO ETFOLessonPlan VALUES('cmf43u47c011nvj9tzhl7bh9e',23,'Évaluation et célébration','cmf43u46z010vvj9tr8bazk9v',1768320000000,45,'TOUR DE FIERTÉ: ''Raconte une chose de la soustraction que tu sais maintenant faire et dont tu es fier!'' Chaque élève partage un succès personnel.','FESTIVAL ÉVALUATION (20 min): 5 kiosques festifs - ''Défis Objets'', ''Résolution Images'', ''Jeux Rapides'', ''Problèmes Vraie Vie'', ''Création Libre''. PORTFOLIO PERSONNEL (7 min): Chaque élève choisit ses 3 meilleures réussites pour portfolio.','GRANDE CÉRÉMONIE: Remise des certificats ''Expert en Soustraction Grade 1''. Photos de groupe, applaudissements. PROMESSE COLLECTIVE: ''Nous continuerons à utiliser la soustraction dans notre vie!''','Compter le concept de évaluation et; Appliquer les concepts mathématiques de base; Développer le raisonnement spatial par la célébration collective','["Matériel de classe"]',NULL,'Évaluation et célébration','TOUR DE FIERTÉ: ''Raconte une chose de la soustraction que tu sais maintenant faire et dont tu es fier!'' Chaque élève partage un succès personnel.','FESTIVAL ÉVALUATION (20 min): 5 kiosques festifs - ''Défis Objets'', ''Résolution Images'', ''Jeux Rapides'', ''Problèmes Vraie Vie'', ''Création Libre''. PORTFOLIO PERSONNEL (7 min): Chaque élève choisit ses 3 meilleures réussites pour portfolio.','GRANDE CÉRÉMONIE: Remise des certificats ''Expert en Soustraction Grade 1''. Photos de groupe, applaudissements. PROMESSE COLLECTIVE: ''Nous continuerons à utiliser la soustraction dans notre vie!''','Compter le concept de évaluation et; Appliquer les concepts mathématiques de base; Développer le raisonnement spatial par la célébration collective',NULL,NULL,NULL,'formative','{"observable":["L''élève expérimente au moins 2 stratégies différentes de soustraction","L''élève explique sa stratégie préférée avec justification simple","L''élève reconnaît que différentes méthodes donnent même réponse","L''élève démontre ouverture à essayer nouvelles approches"],"checkpoints":["Observation directe pendant exploration aux 4 kiosques","Écoute des justifications lors du choix de stratégie préférée","Notes sur flexibilité et adaptation aux différentes méthodes","Documentation des stratégies maîtrisées par chaque élève"]}',1,'Plan détaillé avec supports visuels',1756911653833,1757594654459,1,'fr','Mathématiques','{"pourDifficultés":["Concentrer évaluation sur progrès personnels plutôt que standards absolus","Permettre démonstration de réussites avec support (objets, aide)","Célébrer particulièrement efforts et persévérance montrés","Inclure dans portfolio des tentatives courageuses même imparfaites"],"pourAvancés":["Encourager démonstration de stratégies sophistiquées développées","Inclure défis plus complexes dans leur évaluation personnelle","Valoriser leur rôle de mentors pendant les apprentissages","Documenter innovations et créativité mathématique montrées"],"pourLangue":["Permettre démonstration de compréhension par actions plutôt que mots","Valoriser utilisation croissante du vocabulaire français mathématique","Célébrer courage de participer malgré barrière linguistique","Inclure progrès en communication mathématique dans célébration"],"pourPEI":["Adapter critères évaluation selon objectifs individuels établis","Célébrer tous types de progrès selon capacités personnelles","Utiliser formats évaluation appropriés aux besoins individuels","Focus sur participation, effort et progrès dans zone proximale"]}','{"vocabulary":["réussir","fier","apprendre","progrès","célébrer"],"visualSupports":["Affiche ''Nos Réussites en Soustraction'' avec étoiles pour chaque progrès mentionné","Banderoles colorées ''Festival de la Soustraction!'', affiches encourageantes à chaque kiosque","Grande bannière ''Félicitations Experts en Soustraction!'', mur photos du parcours d''apprentissage"],"movementBreaks":["Faire l''alphabet avec notre corps : A comme arbre (étirer les bras), B comme ballon (forme ronde) (3 minutes)","Marcher en syllabant notre nom : Ma-rie, Paul, etc. en tapant dans nos mains (2 minutes)","Rotations entre kiosques comme mouvement naturel","Danse de célébration entre rotations (1 minute chacune)","Parade finale de célébration avec certificats (dernières 2 minutes)"]}',NULL,NULL,NULL,NULL,'{"questions":["Les élèves ont-ils atteint les objectifs?","Quelles adaptations étaient nécessaires?","Que ferais-je différemment la prochaine fois?"]}',NULL,'',2,12,'core',1);
INSERT INTO ETFOLessonPlan VALUES('cmf43u47d011pvj9tjmsd1zhi',23,'Créer nos propres problèmes','cmf43u46z010vvj9tr8bazk9v',1768406400000,45,'INSPIRATION D''AUTEUR: ''Nous allons devenir auteurs de mathématiques! Voici comment créer un problème: choisir personnages, décider ce qui arrive, faire calcul.'' Démonstration création problème en direct.','ATELIER AUTEURS (20 min): Création individuelle de 2 problèmes originaux avec illustrations. CAFÉ LITTÉRAIRE (7 min): Partage en petits groupes, élèves lisent créations et pairs résolvent.','PREMIÈRE LITTÉRAIRE: Lancement officiel du ''Livre de Problèmes de Notre Classe''. 3 auteurs volontaires lisent leurs créations. SIGNATURE DÉDICACES: Chacun signe cahier des autres comme vrais auteurs.','Calculer le concept de créer nos; Créer les concepts mathématiques de base; Développer la résolution de problèmes par la manipulation et le raisonnement','["Matériel de classe"]',NULL,'Créer nos propres problèmes','INSPIRATION D''AUTEUR: ''Nous allons devenir auteurs de mathématiques! Voici comment créer un problème: choisir personnages, décider ce qui arrive, faire calcul.'' Démonstration création problème en direct.','ATELIER AUTEURS (20 min): Création individuelle de 2 problèmes originaux avec illustrations. CAFÉ LITTÉRAIRE (7 min): Partage en petits groupes, élèves lisent créations et pairs résolvent.','PREMIÈRE LITTÉRAIRE: Lancement officiel du ''Livre de Problèmes de Notre Classe''. 3 auteurs volontaires lisent leurs créations. SIGNATURE DÉDICACES: Chacun signe cahier des autres comme vrais auteurs.','Calculer le concept de créer nos; Créer les concepts mathématiques de base; Développer la résolution de problèmes par la manipulation et le raisonnement',NULL,NULL,NULL,'formative','{"observable":["L''élève explique sa démarche de résolution en séquence logique","L''élève utilise vocabulaire mathématique approprié lors d''explications","L''élève démontre patience et clarté en enseignant à un pair","L''élève identifie étapes importantes de sa méthode de résolution"],"checkpoints":["Observation directe pendant sessions mini-professeurs","Écoute de la qualité et clarté des explications données","Notes sur utilisation spontanée de vocabulaire séquentiel","Documentation des stratégies d''enseignement développées par élèves"]}',1,'Plan détaillé avec supports visuels',1756911653834,1757594654460,1,'fr','Mathématiques','{"pourDifficultés":["Utiliser gabarits pré-formatés avec début d''histoire","Permettre collaboration avec pair plus créatif","Accepter dessins avec explications orales simples","Utiliser nombres très petits (0-3) dans leurs créations"],"pourAvancés":["Encourager création d''histoires à plusieurs étapes","Défis: créer problèmes avec nombres plus grands","Devenir éditeurs aidant à améliorer créations des pairs","Illustrer avec détails sophistiqués"],"pourLangue":["Permettre création dans langue première puis traduction","Utiliser beaucoup d''illustrations pour compenser vocabulaire","Encourager narration orale avant écriture","Accepter mélange linguistique dans créations"],"pourPEI":["Adapter format selon capacités (oral, visuel, tactile)","Utiliser supports technologiques si disponibles","Permettre création collaborative ou assistée","Célébrer créativité sous toutes ses formes"]}','{"vocabulary":["créer","inventer","partager","enlever","histoire"],"visualSupports":["Affiche ''Recette d''un Problème'': 1.Choisir héros 2.Créer situation 3.Ajouter soustraction 4.Poser question","Exemples de problèmes créés par d''autres enfants, modèles de mise en page","Bannière ''Première Mondiale: Nos Problèmes de Soustraction'', affiche auteurs de la classe"],"movementBreaks":["Répéter des comptines avec gestes : ''Tête, épaules, genoux et pieds'' (2 minutes)","Marcher en syllabant notre nom : Ma-rie, Paul, etc. en tapant dans nos mains (2 minutes)","Étirements créatifs avec gestes d''écriture et dessin (minute 12)","Transition café littéraire comme mouvement naturel","Étirer notre dos d''écrivains : rotation douce des épaules (2 minutes)","Célébrer nos apprentissages : applaudir, lever les bras, sourire (2 minutes)"]}',NULL,NULL,NULL,NULL,'{"questions":["Les élèves ont-ils atteint les objectifs?","Quelles adaptations étaient nécessaires?","Que ferais-je différemment la prochaine fois?"]}',NULL,'',2,13,'core',1);
INSERT INTO ETFOLessonPlan VALUES('cmf43u47e011rvj9t4f3ekqju',23,'Soustraction avec des dessins','cmf43u46z010vvj9tr8bazk9v',1768492800000,45,'INSPIRATION ARTISTE: Admirons des œuvres d''art qui racontent des histoires mathématiques! Démonstration: transformer ''5 oiseaux, 2 s''envolent'' en belle illustration colorée.','ATELIER ARTISTE-MATHÉMATICIEN (25 min): Création individuelle d''œuvres intégrant soustraction et art. Techniques libres: dessin, collage, peinture. EXPOSITION TEMPORAIRE (2 min): Installation rapide des œuvres pour admiration.','VERNISSAGE OFFICIEL: Inauguration Galerie ''Art-Mathématiques Grade 1''. Chaque artiste présente brièvement son œuvre. Applaudissements et félicitations mutuelles.','Mesurer la soustraction par manipulation; Appliquer des méthodes de soustraction concrètes; Développer la résolution de problèmes par la manipulation et le raisonnement','["Matériel de classe"]',NULL,'Soustraction avec des dessins','INSPIRATION ARTISTE: Admirons des œuvres d''art qui racontent des histoires mathématiques! Démonstration: transformer ''5 oiseaux, 2 s''envolent'' en belle illustration colorée.','ATELIER ARTISTE-MATHÉMATICIEN (25 min): Création individuelle d''œuvres intégrant soustraction et art. Techniques libres: dessin, collage, peinture. EXPOSITION TEMPORAIRE (2 min): Installation rapide des œuvres pour admiration.','VERNISSAGE OFFICIEL: Inauguration Galerie ''Art-Mathématiques Grade 1''. Chaque artiste présente brièvement son œuvre. Applaudissements et félicitations mutuelles.','Mesurer la soustraction par manipulation; Appliquer des méthodes de soustraction concrètes; Développer la résolution de problèmes par la manipulation et le raisonnement',NULL,NULL,NULL,'formative','{"observable":["L''élève démontre compréhension concepts soustraction selon son niveau","L''élève utilise stratégies appropriées pour résoudre problèmes","L''élève exprime fierté et confiance face à ses apprentissages","L''élève reconnaît ses progrès depuis début des appren