INSERT INTO ETFOLessonPlan VALUES('cmf43u47h011xvj9tswmp1dz9',23,'Projet mathématique','cmf43u46z010vvj9tr8bazk9v',4102416000000,45,'Révision championnat de la leçon 18','Atelier de projets mathématiques','Planification de la présentation','Représenter le concept de projet mathématique; Réaliser les concepts mathématiques de base; Développer les stratégies de calcul par la création personnelle','["Matériel de classe"]',NULL,'Projet mathématique','Révision championnat de la leçon 18','Atelier de projets mathématiques','Planification de la présentation','Représenter le concept de projet mathématique; Réaliser les concepts mathématiques de base; Développer les stratégies de calcul par la création personnelle',NULL,NULL,NULL,'formative','{"observable":["L''élève explique une soustraction à un partenaire","L''élève utilise du matériel pour démontrer un concept","L''élève encourage son partenaire avec patience","L''élève utilise le vocabulaire mathématique approprié"],"checkpoints":["Observation des interactions élève-enseignant/élève-apprenant","Écoute des explications données par les ''enseignants''","Documentation photo/vidéo des moments d''enseignement","Auto-évaluation: ''Comment je me sens comme enseignant?''"]}',1,'Plan détaillé avec supports visuels',1756911653837,1757594654464,1,'fr','Mathématiques','{"pourDifficultés":["Offrir choix entre 3 projets prédéfinis avec étapes claires","Permettre projets très simples: livre à 2 pages, collage simple","Fournir templates et modèles à compléter","Accepter représentations non-conventionnelles"],"pourAvancés":["Encourager projets complexes intégrant plusieurs concepts","Proposer création de jeux mathématiques complets","Développer projets pour enseigner aux autres","Intégrer technologies si disponibles"],"pourLangue":["Privilégier projets très visuels avec peu de texte","Permettre annotations dans langue première","Utiliser projets universels (nombres, images, symboles)","Jumeler avec élève bilingue pour soutien"],"pourPEI":["Adapter projets selon capacités individuelles","Permettre participation avec aide adulte ou pair","Accepter contributions à son niveau (coller, pointer, choisir)","Célébrer toute forme d''expression créative"]}','{"vocabulary":["projet","démontrer","complet"],"visualSupports":["Affiche ''Nos Projets Créatifs!'', galerie d''idées de projets mathématiques","Affiches d''idées créatives: livre de math, jeu inventé, histoire illustrée, sculpture de nombres","Affiche ''Comment présenter'': 1. Montrer 2. Expliquer 3. Partager ce qu''on aime"],"movementBreaks":["Former des lettres dans l''air avec nos doigts : A, B, C (3 minutes)","Répéter des comptines avec gestes : ''Tête, épaules, genoux et pieds'' (2 minutes)","Visite des créations des autres (minute 15)","Pause étirement créatif avec les mains (minute 22)","Étirer notre dos d''écrivains : rotation douce des épaules (2 minutes)","Célébrer nos apprentissages : applaudir, lever les bras, sourire (2 minutes)"]}',NULL,NULL,NULL,NULL,'{"questions":["Les élèves ont-ils atteint les objectifs?","Quelles adaptations étaient nécessaires?","Que ferais-je différemment la prochaine fois?"]}',NULL,'',2,17,'extension',0);
INSERT INTO ETFOLessonPlan VALUES('cmf43u47i011zvj9t0o7qnh2h',23,'Célébration et réflexion','cmf43u46z010vvj9tr8bazk9v',1768838400000,45,'Installation de la galerie de projets','Festival de fin d''unité','Photo souvenir et promesses','Démontrer le concept de célébration et; Appliquer les concepts mathématiques de base; Développer les stratégies de calcul par la célébration collective','["Matériel de classe"]',NULL,'Célébration et réflexion','Installation de la galerie de projets','Festival de fin d''unité','Photo souvenir et promesses','Démontrer le concept de célébration et; Appliquer les concepts mathématiques de base; Développer les stratégies de calcul par la célébration collective',NULL,NULL,NULL,'formative','{"observable":["L''élève applique stratégies de soustraction dans contexte ludique","L''élève persévère face aux défis mathématiques","L''élève démontre fairplay et esprit sportif","L''élève utilise vocabulaire mathématique dans interactions de jeu"],"checkpoints":["Observation des stratégies utilisées pendant les jeux","Documentation des progrès dans résolution de problèmes complexes","Évaluation de l''engagement et motivation dans activités challengeantes","Auto-réflexion: ''Quel jeu m''a le mieux aidé à apprendre?''"]}',1,'Plan détaillé avec supports visuels',1756911653838,1757594654465,1,'fr','Mathématiques','{"pourDifficultés":["Célébrer progrès personnels plutôt que comparaisons","Permettre réflexion silencieuse ou avec aide adulte","Utiliser supports visuels pour montrer croissance","Accepter participation à leur niveau de confort"],"pourAvancés":["Encourager à mentionner apprentissages favoris et prochains défis souhaités","Proposer de créer message d''encouragement pour futurs élèves","Inviter à partager stratégies d''apprentissage efficaces","Demander réflexion sur connexions entre concepts"],"pourLangue":["Permettre expression de fierté dans langue première","Utiliser photos et images pour faciliter réflexion","Accepter gestes et expressions non-verbales","Jumeler avec élève bilingue pour traduction si souhaité"],"pourPEI":["Adapter célébration selon préférences sensorielles","Permettre participation selon capacités individuelles","Utiliser moyens de communication préférés","Célébrer tous types de progrès et participation"]}','{"vocabulary":["célébrer","réfléchir","parcours"],"visualSupports":["Bannière ''Notre Voyage Mathématique!'', panneau ''Fiers de nos apprentissages!''","Frise chronologique de l''unité, galerie ''Avant/Après'' montrant progrès, affichage des moments marquants","Bannière ''Classe des Maîtres Soustraction 2024!'', arrière-plan décoratif pour photo"],"movementBreaks":["Répéter des comptines avec gestes : ''Tête, épaules, genoux et pieds'' (2 minutes)","Marcher en syllabant notre nom : Ma-rie, Paul, etc. en tapant dans nos mains (2 minutes)","Tour de la galerie avec applaudissements (minute 10)","Danse de célébration mathématique (minute 20)","Faire une révérence à nos nouvelles connaissances (1 minute)","Célébrer nos apprentissages : applaudir, lever les bras, sourire (2 minutes)"]}',NULL,NULL,NULL,NULL,'{"questions":["Les élèves ont-ils atteint les objectifs?","Quelles adaptations étaient nécessaires?","Que ferais-je différemment la prochaine fois?"]}',NULL,'',2,18,'extension',1);
INSERT INTO ETFOLessonPlan VALUES('cmf43u47k0123vj9t8dmqu97e',23,'Découvrir le calcul mental avec nos doigts','cmf43u47j0121vj9tf7qvug77',1776783600000,45,'Chanson d''ouverture avec gestes: ''Mes dix doigts sont mes amis, ils m''aident à compter ici!'' Montrer tous les doigts, puis cacher et révéler différents nombres.','Station rotation: 1) Additions avec doigts (2+1, 3+2), 2) Marionnettes de doigts qui ''parlent'' maths, 3) Cubes unifix pour vérifier les calculs de doigts. Démonstration explicite: ''Je pense 2+3. Je mets 2 doigts, puis j''ajoute 3. Je compte tous mes doigts: 1,2,3,4,5!''','Jeu ''Devinez mon calcul'': Un élève montre ses doigts pour une addition, les autres devinent l''équation. Célébrer que nos doigts sont des outils mathématiques!','Identifier le concept de découvrir le; Appliquer les concepts mathématiques de base; Développer le sens du nombre par la manipulation et le raisonnement','["Matériel de classe"]',NULL,'Découvrir le calcul mental avec nos doigts','Chanson d''ouverture avec gestes: ''Mes dix doigts sont mes amis, ils m''aident à compter ici!'' Montrer tous les doigts, puis cacher et révéler différents nombres.','Station rotation: 1) Additions avec doigts (2+1, 3+2), 2) Marionnettes de doigts qui ''parlent'' maths, 3) Cubes unifix pour vérifier les calculs de doigts. Démonstration explicite: ''Je pense 2+3. Je mets 2 doigts, puis j''ajoute 3. Je compte tous mes doigts: 1,2,3,4,5!''','Jeu ''Devinez mon calcul'': Un élève montre ses doigts pour une addition, les autres devinent l''équation. Célébrer que nos doigts sont des outils mathématiques!','Identifier le concept de découvrir le; Appliquer les concepts mathématiques de base; Développer le sens du nombre par la manipulation et le raisonnement',NULL,NULL,NULL,'formative','{"observable":["Élève utilise ses doigts pour représenter nombres","Élève compte correctement le total après addition","Élève utilise vocabulaire: calcul mental, doigts, additionner","Élève explique sa stratégie avec phrases simples"],"checkpoints":["Pendant ouverture: Noter participation à la chanson gestuelle","Pendant stations: Observer utilisation correcte des doigts","Pendant fermeture: Vérifier compréhension du jeu des devinettes"]}',1,'Plan détaillé avec supports visuels',1756911653840,1757594654470,1,'fr','Mathématiques','{"pourDifficultés":["Limiter aux additions 1+1, 2+1, 2+2 maximum","Utiliser objets physiques avant transition aux doigts","Permettre comptage lent avec verbalisation de chaque nombre","Offrir soutien individuel pendant manipulations"],"pourAvancés":["Introduire additions jusqu''à 8 (3+5, 4+4) si maîtrise rapide","Demander d''enseigner stratégie à un pair en difficulté","Explorer calcul mental sans objets pour certaines additions","Créer leurs propres jeux de calcul mental avec doigts"],"pourLangue":["Utiliser gestes clairs pour ''calcul mental'' et ''doigts''","Associer chaque nombre à image visuelle familière","Permettre comptage dans langue première puis français","Utiliser objets culturellement significatifs si disponibles"],"pourPEI":["Adapter manipulatifs selon besoins moteurs (plus gros, texturés)","Modifier attentes de verbalisation selon capacités","Ajuster éclairage et position pour besoins sensoriels","Permettre pauses fréquentes selon plan individualisé"]}','{"vocabulary":["calcul mental","doigts","additionner","stratégie"],"visualSupports":["Affiches murales montrant différentes façons de montrer les nombres avec les doigts. Tableaux de référence des additions simples avec illustrations de mains."],"movementBreaks":["Marcher en syllabant notre nom : Ma-rie, Paul, etc. en tapant dans nos mains (2 minutes)","Former des lettres dans l''air avec nos doigts : A, B, C (3 minutes)","Étirer nos doigts et mains d''écrivains : ouvrir, fermer, tourner (2 minutes)","Faire une pause lecture : s''étirer comme un chat qui se réveille (2 minutes)","Faire une révérence à nos nouvelles connaissances (1 minute)","Étirer notre dos d''écrivains : rotation douce des épaules (2 minutes)"]}',NULL,NULL,NULL,NULL,'{"questions":["Les élèves ont-ils atteint les objectifs?","Quelles adaptations étaient nécessaires?","Que ferais-je différemment la prochaine fois?"]}',NULL,'',2,1,'core',1);
INSERT INTO ETFOLessonPlan VALUES('cmf43u47l0125vj9tii7vpfyw',23,'Compter à partir d''un nombre','cmf43u47j0121vj9tf7qvug77',1776870000000,45,'Révision rapide: Montrer 3+2 avec les doigts. Puis démonstration dramatique: ''Compter 1,2,3,4,5 vs commencer à 3 et dire 4,5!'' Lequel est plus rapide?','Enseignement explicite avec ligne numérique: ''Pour 4+3, je commence à 4 (pas à 1!) et je saute: 5,6,7!'' Pratique guidée avec problèmes variés. Course amicale: qui peut faire 5+2 plus rapidement, en comptant depuis 1 ou depuis 5?','Réflexion guidée: ''Pourquoi commencer par le plus grand nombre est-il plus intelligent?'' Engagement: promettre d''essayer cette stratégie à la maison!','Explorer le comptage avec stratégies; Appliquer les concepts mathématiques de base; Développer le sens du nombre par la manipulation et le raisonnement','["Matériel de classe"]',NULL,'Compter à partir d''un nombre','Révision rapide: Montrer 3+2 avec les doigts. Puis démonstration dramatique: ''Compter 1,2,3,4,5 vs commencer à 3 et dire 4,5!'' Lequel est plus rapide?','Enseignement explicite avec ligne numérique: ''Pour 4+3, je commence à 4 (pas à 1!) et je saute: 5,6,7!'' Pratique guidée avec problèmes variés. Course amicale: qui peut faire 5+2 plus rapidement, en comptant depuis 1 ou depuis 5?','Réflexion guidée: ''Pourquoi commencer par le plus grand nombre est-il plus intelligent?'' Engagement: promettre d''essayer cette stratégie à la maison!','Explorer le comptage avec stratégies; Appliquer les concepts mathématiques de base; Développer le sens du nombre par la manipulation et le raisonnement',NULL,NULL,NULL,'formative','{"observable":["Élève identifie le plus grand nombre dans addition","Élève commence comptage à partir du plus grand nombre","Élève utilise vocabulaire: compter en partant de, efficace","Élève démontre compréhension de l''efficacité de cette méthode"],"checkpoints":["Pendant ouverture: Noter compréhension de la comparaison de rapidité","Pendant pratique: Observer utilisation correcte de la ligne numérique","Pendant fermeture: Vérifier capacité d''expliquer pourquoi méthode plus intelligente"]}',1,'Plan détaillé avec supports visuels',1756911653841,1757594654471,1,'fr','Mathématiques','{"pourDifficultés":["Commencer avec additions très simples (4+1, 5+1, 3+2)","Utiliser ligne numérique avec doigt pour pointer chaque nombre","Permettre comptage à voix haute avec support visuel","Pratiquer d''abord avec plus petit nombre + 1 seulement"],"pourAvancés":["Introduire additions avec nombres plus grands (7+4, 8+3)","Explorer stratégie ''compter à rebours'' pour soustractions","Demander d''expliquer pourquoi cette méthode est plus efficace","Créer leurs propres exemples pour enseigner aux pairs"],"pourLangue":["Utiliser gestes clairs pour ''compter en partant de'' et ''plus rapide''","Associer chaque étape à mouvement physique sur ligne numérique","Permettre verbalisation dans langue première pour comprendre concept","Utiliser comparaisons visuelles pour montrer efficacité"],"pourPEI":["Adapter ligne numérique selon besoins moteurs (plus large, texturée)","Modifier attentes de rapidité selon capacités individuelles","Ajuster position et éclairage pour optimiser accès visuel","Fournir pauses sensorielles fréquentes si nécessaire"]}','{"vocabulary":["compter en partant de","efficace","plus rapide"],"visualSupports":["Ligne numérique colorée de 0-20. Affiches comparant les deux méthodes. Cartes stratégies avec images step-by-step."],"movementBreaks":["Marcher en syllabant notre nom : Ma-rie, Paul, etc. en tapant dans nos mains (2 minutes)","Répéter des comptines avec gestes : ''Tête, épaules, genoux et pieds'' (2 minutes)","Danser avec les sons : ''a'' avec les bras, ''o'' en rond, ''i'' pointu (3 minutes)","Marcher sur place en récitant l''alphabet lentement (2 minutes)","Faire une révérence à nos nouvelles connaissances (1 minute)","Étirer notre dos d''écrivains : rotation douce des épaules (2 minutes)"]}',NULL,NULL,NULL,NULL,'{"questions":["Les élèves ont-ils atteint les objectifs?","Quelles adaptations étaient nécessaires?","Que ferais-je différemment la prochaine fois?"]}',NULL,'',2,2,'core',1);
INSERT INTO ETFOLessonPlan VALUES('cmf43u47m0127vj9t5yehprun',23,'Mes premiers doubles magiques','cmf43u47j0121vj9tf7qvug77',1776956400000,45,'Jeu du miroir: par paires, un élève fait un geste avec des objets, l''autre ''reflète'' exactement la même chose. Introduire: ''C''est un double!''','Exploration des doubles dans la nature et notre corps: 2 yeux, 2 mains, 2 pieds. Créer des doubles avec pâte à modeler. Station apprentissage: cartes doubles à associer, construction de doubles avec blocs, chanson des doubles avec gestes.','Chanson finale des doubles: ''1+1 fait 2, 2+2 fait 4, 3+3 fait 6, et encore plus!'' avec gestes. Chaque élève partage son double préféré.','Découvrir le concept de mes premiers; Appliquer les concepts mathématiques de base; Développer le sens du nombre par la manipulation et le raisonnement','["Matériel de classe"]',NULL,'Mes premiers doubles magiques','Jeu du miroir: par paires, un élève fait un geste avec des objets, l''autre ''reflète'' exactement la même chose. Introduire: ''C''est un double!''','Exploration des doubles dans la nature et notre corps: 2 yeux, 2 mains, 2 pieds. Créer des doubles avec pâte à modeler. Station apprentissage: cartes doubles à associer, construction de doubles avec blocs, chanson des doubles avec gestes.','Chanson finale des doubles: ''1+1 fait 2, 2+2 fait 4, 3+3 fait 6, et encore plus!'' avec gestes. Chaque élève partage son double préféré.','Découvrir le concept de mes premiers; Appliquer les concepts mathématiques de base; Développer le sens du nombre par la manipulation et le raisonnement',NULL,NULL,NULL,'formative','{"observable":["Élève identifie objets identiques par paires","Élève crée doubles avec matériaux (blocs, pâte)","Élève utilise vocabulaire: doubles, même nombre, jumeaux","Élève récite au moins 3 faits de doubles (1+1, 2+2, 3+3)"],"checkpoints":["Pendant ouverture: Observer compréhension du jeu miroir","Pendant stations: Vérifier création correcte de doubles","Pendant fermeture: Noter participation à chanson des doubles"]}',1,'Plan détaillé avec supports visuels',1756911653842,1757594654472,1,'fr','Mathématiques','{"pourDifficultés":["Commencer avec doubles très concrets (1+1, 2+2) uniquement","Utiliser objets réels identiques avant représentations abstraites","Permettre manipulation lente avec verbalisation de chaque étape","Associer chaque double à partie du corps familiar (2 mains, 2 yeux)"],"pourAvancés":["Introduire doubles plus grands (6+6, 7+7) si compréhension solide","Explorer concept d''à peu près doubles (5+6, 4+5)","Demander de trouver doubles dans environnement classe","Créer histoire mathématique utilisant plusieurs doubles"],"pourLangue":["Utiliser objets identiques visuellement très clairs","Associer geste miroir à mot ''double'' répété","Permettre utilisation langue maternelle pour identifier paires","Utiliser chanson avec gestes répétitifs pour mémorisation"],"pourPEI":["Adapter matériaux selon besoins tactiles (texturés, plus gros)","Modifier attentes motrices pour créations pâte à modeler","Ajuster éclairage et contraste pour reconnaissance visuelle","Permettre temps additionnel pour exploration des stations"]}','{"vocabulary":["doubles","même nombre","magique","facile"],"visualSupports":["Affiches murales des doubles avec images symétriques (papillons, maisons, visages). Cartes de référence plastifiées. Tableau des doubles avec illustrations."],"movementBreaks":["Former des lettres dans l''air avec nos doigts : A, B, C (3 minutes)","Faire l''alphabet avec notre corps : A comme arbre (étirer les bras), B comme ballon (forme ronde) (3 minutes)","Étirer nos doigts et mains d''écrivains : ouvrir, fermer, tourner (2 minutes)","Faire des gestes de marionnettes pour raconter notre histoire (3 minutes)","Dire au revoir avec tout notre corps : mains, têtes, pieds (2 minutes)","Ranger nos idées : faire semblant de mettre nos pensées dans une boîte (2 minutes)"]}',NULL,NULL,NULL,NULL,'{"questions":["Les élèves ont-ils atteint les objectifs?","Quelles adaptations étaient nécessaires?","Que ferais-je différemment la prochaine fois?"]}',NULL,'',2,3,'core',1);
INSERT INTO ETFOLessonPlan VALUES('cmf43u47m0129vj9t6o34c2ck',23,'Doubles plus un','cmf43u47j0121vj9tf7qvug77',1777042800000,45,'Révision rapide des doubles avec chanson. Puis mystère: ''Que se passe-t-il si j''ajoute UN de plus à un double?'' Démonstration avec objets.','Découverte guidée: ''Je sais que 3+3=6. Donc 3+4, c''est juste 6+1=7!'' Pratique avec manipulatives: construire le double, ajouter un cube différent. Jeu ''Presque jumeaux'': identifier les additions qui sont ''presque des doubles''.','Partage de découvertes: ''Quel presque double avez-vous trouvé le plus facile?'' Promesse d''utiliser cette stratégie intelligente!','Ordonner le concept de doubles plus; Appliquer les concepts mathématiques de base; Développer le sens du nombre par la manipulation et le raisonnement','["Matériel de classe"]',NULL,'Doubles plus un','Révision rapide des doubles avec chanson. Puis mystère: ''Que se passe-t-il si j''ajoute UN de plus à un double?'' Démonstration avec objets.','Découverte guidée: ''Je sais que 3+3=6. Donc 3+4, c''est juste 6+1=7!'' Pratique avec manipulatives: construire le double, ajouter un cube différent. Jeu ''Presque jumeaux'': identifier les additions qui sont ''presque des doubles''.','Partage de découvertes: ''Quel presque double avez-vous trouvé le plus facile?'' Promesse d''utiliser cette stratégie intelligente!','Ordonner le concept de doubles plus; Appliquer les concepts mathématiques de base; Développer le sens du nombre par la manipulation et le raisonnement',NULL,NULL,NULL,'formative','{"observable":["Élève identifie le double dans presque-double (3+4 vient de 3+3)","Élève ajoute correctement +1 au résultat du double","Élève utilise vocabulaire: doubles plus un, presque double","Élève explique stratégie avec matériel concret"],"checkpoints":["Pendant ouverture: Observer compréhension du mystère +1","Pendant pratique: Vérifier utilisation correcte de la stratégie","Pendant jeu: Noter reconnaissance presque-doubles vs autres additions"]}',1,'Plan détaillé avec supports visuels',1756911653843,1757594654473,1,'fr','Mathématiques','{"pourDifficultés":["Maîtriser d''abord les doubles avant ajouter +1","Utiliser objets concrets pour visualiser double + objet différent","Commencer avec 2+3, 3+4 seulement (petits nombres)","Permettre comptage lent après identification du double"],"pourAvancés":["Introduire doubles-moins-un (5+4=6-1, 7+6=8-1)","Explorer presque-doubles plus grands (6+7, 8+9)","Demander d''expliquer stratégie à autre élève","Créer histoire math avec plusieurs presque-doubles"],"pourLangue":["Utiliser geste clair: double (mains identiques) + un (lever doigt)","Associer ''presque'' à expressions culturellement familières","Permettre explication dans langue première puis français","Utiliser couleur vive pour accentuer l''objet supplémentaire"],"pourPEI":["Adapter manipulatifs selon capacités motrices individuelles","Modifier attentes de verbalisation selon besoins communication","Ajuster éclairage pour distinguer couleurs doubles vs extras","Fournir temps additionnel pour manipulation et découverte"]}','{"vocabulary":["doubles plus un","presque double","un de plus"],"visualSupports":["Cartes visuelles montrant double + jeton différent. Affiche stratégie step-by-step. Tableau comparatif doubles vs presque doubles."],"movementBreaks":["Imiter les animaux des histoires : sauter comme un lapin, voler comme un oiseau (3 minutes)","Former des lettres dans l''air avec nos doigts : A, B, C (3 minutes)","Faire des gestes de marionnettes pour raconter notre histoire (3 minutes)","Étirer nos doigts et mains d''écrivains : ouvrir, fermer, tourner (2 minutes)","Dire au revoir avec tout notre corps : mains, têtes, pieds (2 minutes)","Ranger nos idées : faire semblant de mettre nos pensées dans une boîte (2 minutes)"]}',NULL,NULL,NULL,NULL,'{"questions":["Les élèves ont-ils atteint les objectifs?","Quelles adaptations étaient nécessaires?","Que ferais-je différemment la prochaine fois?"]}',NULL,'',2,4,'core',1);
INSERT INTO ETFOLessonPlan VALUES('cmf43u47n012bvj9t2jnv9t0j',23,'La famille du 10 magique','cmf43u47j0121vj9tf7qvug77',1777302000000,45,'Mystère de la boîte magique: montrer une boîte d''œufs de 10. ''Cette boîte veut toujours être complète! Trouvons toutes les façons de la remplir!''','Exploration systématique avec ten frames: commencer avec 1 jeton rouge, combien de bleus pour faire 10? Puis 2 rouges, etc. Création d''un mur des ''liens vers 10''. Jeu ''Partenaires de 10'': cartes flash rapides.','Célébration de la famille du 10: chanter tous les liens découverts. ''Nous connaissons maintenant tous les amis du 10!''','Représenter la famille et ses membres; Appliquer les rôles familiaux avec respect; Développer la pensée logique par la manipulation et le raisonnement','["Matériel de classe"]',NULL,'La famille du 10 magique','Mystère de la boîte magique: montrer une boîte d''œufs de 10. ''Cette boîte veut toujours être complète! Trouvons toutes les façons de la remplir!''','Exploration systématique avec ten frames: commencer avec 1 jeton rouge, combien de bleus pour faire 10? Puis 2 rouges, etc. Création d''un mur des ''liens vers 10''. Jeu ''Partenaires de 10'': cartes flash rapides.','Célébration de la famille du 10: chanter tous les liens découverts. ''Nous connaissons maintenant tous les amis du 10!''','Représenter la famille et ses membres; Appliquer les rôles familiaux avec respect; Développer la pensée logique par la manipulation et le raisonnement',NULL,NULL,NULL,'formative','{"observable":["Élève identifie au moins 3 liens vers 10 différents","Élève utilise ten frame pour démontrer liens vers 10","Élève utilise vocabulaire: faire 10, partenaires de 10, liens","Élève explique comment deux nombres font 10 ensemble"],"checkpoints":["Pendant ouverture: Observer compréhension concept boîte complète","Pendant exploration: Vérifier découverte systématique des liens","Pendant jeu flash: Noter rapidité de reconnaissance liens maîtrisés"]}',1,'Plan détaillé avec supports visuels',1756911653844,1757594654474,1,'fr','Mathématiques','{"pourDifficultés":["Commencer avec seulement 3 liens vers 10 (5+5, 6+4, 7+3)","Utiliser objets concrets avant ten frames abstraits","Permettre comptage lent pour vérifier chaque lien","Fournir support individuel pendant exploration"],"pourAvancés":["Découvrir liens vers 20 (10+10, 11+9, 12+8)","Identifier patterns dans les liens vers 10 (à mesure qu''un augmente, l''autre diminue)","Enseigner un lien vers 10 à un pair en difficulté","Créer jeu de mémoire avec liens vers 10"],"pourLangue":["Utiliser gestes clairs pour ''faire 10'' et ''partenaires''","Associer chaque lien à couleur spécifique pour mémorisation","Permettre verbalisation dans langue première puis français","Utiliser objets familiers culturellement si disponibles"],"pourPEI":["Adapter ten frames selon besoins visuels (plus gros, contrastés)","Modifier attentes motrices pour manipulation jetons","Ajuster rythme selon capacités attentionnelles individuelles","Permettre pauses fréquentes pendant exploration"]}','{"vocabulary":["faire 10","partenaires de 10","liens vers 10"],"visualSupports":["Ten frames géants muraux. Affiche ''Famille du 10'' avec toutes les combinaisons. Cartes visuelles colorées pour chaque lien."],"movementBreaks":["Marcher en syllabant notre nom : Ma-rie, Paul, etc. en tapant dans nos mains (2 minutes)","Former des lettres dans l''air avec nos doigts : A, B, C (3 minutes)","Marcher sur place en récitant l''alphabet lentement (2 minutes)","Étirer nos doigts et mains d''écrivains : ouvrir, fermer, tourner (2 minutes)","Faire une révérence à nos nouvelles connaissances (1 minute)","Dire au revoir avec tout notre corps : mains, têtes, pieds (2 minutes)"]}',NULL,NULL,NULL,NULL,'{"questions":["Les élèves ont-ils atteint les objectifs?","Quelles adaptations étaient nécessaires?","Que ferais-je différemment la prochaine fois?"]}',NULL,'',2,5,'core',1);
INSERT INTO ETFOLessonPlan VALUES('cmf43u47o012dvj9trumc50up',23,'Utiliser 10 pour additionner','cmf43u47j0121vj9tf7qvug77',1777388400000,45,'Problème mystère au tableau: ''8+5=?'' Défi: ''Pouvez-vous utiliser votre connaissance du 10 pour résoudre ceci plus facilement?''','Enseignement explicite de la décomposition: ''8+5 → je prends 2 du 5 pour faire 8+2=10, puis j''ajoute les 3 restants: 10+3=13!'' Pratique guidée avec ten frames et schémas visuels. Stations: problèmes variés avec support.','Réflexion: ''Comment faire 10 d''abord vous a-t-il aidé?'' Partage de stratégies réussies. Promesse d''utiliser cette ''super stratégie''!','Compter l''addition avec manipulatifs; Appliquer des stratégies d''addition variées; Développer la pensée logique par la manipulation et le raisonnement','["crayons de couleur (boîte de 24)","tableau d''écriture ou grande feuille","affiches d''alphabet avec images (alphabet complet)","gommes à effacer douces (15 gommes)","marqueurs effaçables (15 marqueurs)","tableaux individuels effaçables (15 tableaux)","fiches de mots illustrées (50 cartes)","livrets de lecture simple (niveau débutant, 15 copies)","lingettes pour nettoyer les mains (1 paquet)","chemises individuelles (30 chemises)","tampons motivants avec encreur (5 tampons)"]',NULL,'Utiliser 10 pour additionner','Problème mystère au tableau: ''8+5=?'' Défi: ''Pouvez-vous utiliser votre connaissance du 10 pour résoudre ceci plus facilement?''','Enseignement explicite de la décomposition: ''8+5 → je prends 2 du 5 pour faire 8+2=10, puis j''ajoute les 3 restants: 10+3=13!'' Pratique guidée avec ten frames et schémas visuels. Stations: problèmes variés avec support.','Réflexion: ''Comment faire 10 d''abord vous a-t-il aidé?'' Partage de stratégies réussies. Promesse d''utiliser cette ''super stratégie''!','Compter l''addition avec manipulatifs; Appliquer des stratégies d''addition variées; Développer la pensée logique par la manipulation et le raisonnement',NULL,NULL,NULL,'formative','{"observable":["L''élève utilise des objets concrets pour additionner","L''élève explique sa stratégie d''addition en français","L''élève vérifie ses réponses en comptant","L''élève reconnaît le signe + et le mot ''plus''"],"checkpoints":["Additionne deux nombres jusqu''à 5 avec manipulatifs","Explique: ''deux plus trois égale cinq''","Utilise différentes stratégies (compter, grouper)","Résout des problèmes concrets d''addition"]}',1,'Plan détaillé avec supports visuels',1756911653845,1757594654475,1,'fr','Mathématiques','{"pourDifficultés":["Limiter aux calculs simples avec nombres jusqu''à 10","Utiliser objets concrets et manipulatifs","Permettre comptage à voix haute avec support visuel","Donner plus de temps et encouragement"],"pourAvancés":["Introduire nombres plus grands et calculs complexes","Explorer multiples stratégies pour même problème","Créer leurs propres problèmes et défis","Enseigner stratégies aux pairs"],"pourLangue":["Utiliser gestes et supports visuels pour vocabulaire mathématique","Permettre expression en langue première pour vérifier compréhension","Répéter et modéliser vocabulaire clé","Associer concepts à objets et images concrètes"],"pourPEI":["Adapter matériel selon besoins moteurs et sensoriels","Ajuster rythme et attentes selon capacités individuelles","Fournir supports personnalisés si nécessaire","Offrir pauses et alternatives selon besoins"]}','{"vocabulary":["décomposer","faire 10 d''abord","puis ajouter"],"visualSupports":["Schémas muraux montrant la décomposition step-by-step. Ten frames avec lignes de décomposition. Affiches de référence stratégique."],"movementBreaks":["Imiter les animaux des histoires : sauter comme un lapin, voler comme un oiseau (3 minutes)","Faire l''alphabet avec notre corps : A comme arbre (étirer les bras), B comme ballon (forme ronde) (3 minutes)","Faire des gestes de marionnettes pour raconter notre histoire (3 minutes)","Faire une pause lecture : s''étirer comme un chat qui se réveille (2 minutes)","Dire 