INSERT INTO ETFOLessonPlan VALUES('cmf43u47v012pvj9tip8yvrv1',23,'Faire 10 avec des nombres plus grands','cmf43u47j0121vj9tf7qvug77',1778079600000,45,'Défi du jour: ''13+8=?'' Rappel: ''Comment notre stratégie favorite ''faire 10'' peut-elle nous aider avec des nombres plus grands?''','Extension de la stratégie: 13+8 → je prends 7 du 8 pour faire 13+7=20, puis j''ajoute le 1 restant: 20+1=21. Pratique avec ten frames doubles. Application à diverses situations avec nombres jusqu''à 20.','Émerveillement: ''Notre stratégie fonctionne même avec de grands nombres!'' Partage des découvertes et succès personnels.','Compter les nombres de 0 à 10; Appliquer des stratégies de comptage efficaces; Développer le raisonnement spatial par la manipulation et le raisonnement','["marionnettes simples (3-4 personnages)","autocollants motivants (1 planche)","tapis de rassemblement coloré","lettres magnétiques (jeu complet A-Z)","livrets de lecture simple (niveau débutant, 15 copies)","tableaux individuels effaçables (15 tableaux)","crayons à mine large (30 crayons)","marqueurs effaçables (15 marqueurs)","boîte de rangement pour travaux (1 grande boîte)","chemises individuelles (30 chemises)","lingettes pour nettoyer les mains (1 paquet)"]',NULL,'Faire 10 avec des nombres plus grands','Défi du jour: ''13+8=?'' Rappel: ''Comment notre stratégie favorite ''faire 10'' peut-elle nous aider avec des nombres plus grands?''','Extension de la stratégie: 13+8 → je prends 7 du 8 pour faire 13+7=20, puis j''ajoute le 1 restant: 20+1=21. Pratique avec ten frames doubles. Application à diverses situations avec nombres jusqu''à 20.','Émerveillement: ''Notre stratégie fonctionne même avec de grands nombres!'' Partage des découvertes et succès personnels.','Compter les nombres de 0 à 10; Appliquer des stratégies de comptage efficaces; Développer le raisonnement spatial par la manipulation et le raisonnement',NULL,NULL,NULL,'formative','{"observable":["L''élève compte de 1 à 10 en touchant chaque objet"