INSERT INTO ETFOLessonPlan VALUES('cmf43u498015nvj9twtfv1oix',23,'Les animaux dans leur maison naturelle','cmf43u496015jvj9tbdn7emo8',1777042800000,45,'Animal home guessing game - show animal pictures and guess where they live','Create simple animal habitat dioramas using natural and craft materials','Habitat gallery walk - students present their dioramas and explain animal homes','Découvrir les animaux et leurs besoins; Expérimenter avec les caractéristiques des êtres vivants; Développer la démarche scientifique par l''investigation scientifique','["animal picture cards","habitat picture cards","small boxes","natural materials (twigs, leaves, sand)","animal figures","blue fabric","Images de familles diverses (monoparentales, recomposées, multiculturelles)","sticky notes for feedback","observation checklist"]',NULL,'Les animaux dans leur maison naturelle','Animal home guessing game - show animal pictures and guess where they live','Create simple animal habitat dioramas using natural and craft materials','Habitat gallery walk - students present their dioramas and explain animal homes','Découvrir les animaux et leurs besoins; Expérimenter avec les caractéristiques des êtres vivants; Développer la démarche scientifique par l''investigation scientifique',NULL,NULL,NULL,'formative','{"observable":["L''élève associe correctement 3+ animaux à leurs habitats","L''élève utilise vocabulaire ''maison'', ''habitat'' appropriément","L''élève explique pourquoi animal a besoin habitat spécifique"],"checkpoints":["Place animal dans bon habitat sur diorama","Nomme habitat de 2+ animaux familiers","Explique une raison pourquoi animal vit là"]}',1,'Plan détaillé avec supports visuels',1756911653900,1757594654542,1,'fr','Sciences de la nature','{"pourDifficultés":["Utiliser 3-4 animaux très familiers seulement","Associer animal-habitat avec images identiques","Permettre manipulation d''objets concrets (figurines)"],"pourAvancés":["Explorer pourquoi certains animaux changent d''habitat 