INSERT INTO ETFOLessonPlan VALUES('cmf43u499015pvj9ttvgwohc1',23,'Les plantes ont leur place aussi','cmf43u496015jvj9tbdn7emo8',1777302000000,45,'Plant location detective game - examine plants in different school locations','Plant a classroom experiment with same seeds in different conditions (light, dark, wet, dry)','Plant placement predictions - students predict which planted seeds will grow best','Examiner les plantes et leur croissance; Expérimenter avec les besoins essentiels des plantes; Développer la démarche scientifique par l''investigation scientifique','["observation journals","plant identification guides","seeds","small pots","potting soil","water","labels","prediction cards","pencils"]',NULL,'Les plantes ont leur place aussi','Plant location detective game - examine plants in different school locations','Plant a classroom experiment with same seeds in different conditions (light, dark, wet, dry)','Plant placement predictions - students predict which planted seeds will grow best','Examiner les plantes et leur croissance; Expérimenter avec les besoins essentiels des plantes; Développer la démarche scientifique par l''investigation scientifique',NULL,NULL,NULL,'formative','{"observable":["L''élève identifie où 2+ plantes poussent naturellement","L''élève explique pourquoi lieu important pour plantes","L''élève fait prédictions sur croissance des graines"],"checkpoints":["Associe plante à son environnement préféré","Utilise ''place'', ''pousser'' dans contexte approprié","Prédit quelle graine poussera mieux et pourquoi"]}',1,'Plan détaillé avec supports visuels',1756911653901,1757594654543,1,'fr','Sciences de la nature','{"pourDifficultés":["Utiliser 2-3 plantes très visibles seulement (tournesol, fougère)","Montrer exemples évidents (cactus=sec, nénuphar=eau)","Permettre réponses par désignation d''images"],"pourAvancés":["Explorer micro-environnements (sous roches, troncs d''arbres)","Prédire quelles plantes survivraient dans différents endroits","Créer guide de plantes selon leurs préférences de lieu"],"pourLangue":["Cartes visuelles ''place'', ''pousser'', ''endroit'' avec actions","Utiliser vraies plantes pour vocabulaire tactile","Permettre comparaisons avec plantes de culture d''origine"],"pourPEI":["Adapter selon allergies ou sensibilités aux plantes","Fournir gants si difficultés tactiles avec terre","Simplifier expérience à 2 conditions seulement (lumière/ombre)"]}','{"vocabulary":["place","pousser","endroit"],"visualSupports":["plant location preference chart (sun plants, shade plants, water plants)","plant needs diagram, experiment tracking chart"],"movementBreaks":["Marcher en syllabant notre nom : Ma-rie, Paul, etc. en tapant dans nos mains (2 minutes)","Répéter des comptines avec gestes : ''Tête, épaules, genoux et pieds'' (2 minutes)","Danser avec les sons : ''a'' avec les bras, ''o'' en rond, ''i'' pointu (3 minutes)","Faire une pause lecture : s''étirer comme un chat qui se réveille (2 minutes)","Célébrer nos apprentissages : applaudir, lever les bras, sourire (2 minutes)","Ranger nos idées : faire semblant de mettre nos pensées dans une boîte (2 minutes)"]}',NULL,NULL,NULL,NULL,'{"questions":["Les élèves ont-ils atteint les objectifs?","Quelles adaptations étaient nécessaires?","Que ferais-je différemment la prochaine fois?"]}',NULL,'',3,3,'core',1);
INSERT INTO ETFOLessonPlan VALUES('cmf43u49a015rvj9tren939cp',23,'Tout est connecté dans la nature','cmf43u496015jvj9tbdn7emo8',1777388400000,45,'Connection web game - hold yarn to show how students are connected to each other','Create nature connection chains using pictures and arrows to show relationships','Connection sharing circle - students share one nature connection they discovered','Prédire le concept de tout est; Expérimenter avec la méthode d''investigation scientifique; Développer la démarche scientifique par l''investigation scientifique','["ball of yarn","connection cards","nature picture cards","arrow stickers","large paper","glue sticks","speaking stone or talking object","circle carpet or floor markers"]',NULL,'Tout est connecté dans la nature','Connection web game - hold yarn to show how students are connected to each other','Create nature connection chains using pictures and arrows to show relationships','Connection sharing circle - students share one nature connection they discovered','Prédire le concept de tout est; Expérimenter avec la méthode d''investigation scientifique; Développer la démarche scientifique par l''investigation scientifique',NULL,NULL,NULL,'formative','{"observable":["L''élève identifie 2+ connexions simples dans nature","L''élève utilise vocabulaire ''connecté'', ''ensemble'' appropriément","L''élève explique pourquoi éléments dépendent les uns des autres"],"checkpoints":["Relie 2 éléments nature avec flèche ou ficelle","Explique connexion oiseau-arbre ou abeille-fleur","Utilise ''ensemble'' pour décrire relation nature"]}',1,'Plan détaillé avec supports visuels',1756911653902,1757594654544,1,'fr','Sciences de la nature','{"pourDifficultés":["Utiliser connexions très évidentes (abeille-fleur, poisson-eau)","Montrer avec objets concrets et ficelle pour ''connexion''","Se limiter à 2-3 connexions simples maximum"],"pourAvancés":["Explorer que se passe-t-il si une connexion est brisée","Créer chaînes de connexions multiples (sol