INSERT INTO ETFOLessonPlan VALUES('cmf43u49d015zvj9t624jyyjs',23,'Réduire nos déchets','cmf43u496015jvj9tbdn7emo8',1777906800000,45,'Classroom waste audit - examine what gets thrown away in one day','Waste reduction challenge - students brainstorm and practice ways to make less waste','Waste reduction commitment ceremony - students choose one waste reduction action to practice','Tester le concept de réduire nos; Expérimenter avec la méthode d''investigation scientifique; Développer l''observation systématique par l''investigation scientifique','["waste collection bags","sorting gloves","clipboards","waste reduction idea cards","reusable containers","both sides paper examples","chart paper for recording ideas","markers"]',NULL,'Réduire nos déchets','Classroom waste audit - examine what gets thrown away in one day','Waste reduction challenge - students brainstorm and practice ways to make less waste','Waste reduction commitment ceremony - students choose one waste reduction action to practice','Tester le concept de réduire nos; Expérimenter avec la méthode d''investigation scientifique; Développer l''observation systématique par l''investigation scientifique',NULL,NULL,NULL,'formative','{"observable":["L''élève identifie 3+ façons de réduire déchets","L''élève démontre action de réduction (utiliser moins)","L''élève explique pourquoi moins de déchets aide environnement"],"checkpoints":["Choisit et pratique action de réduction","Utilise ''réduire'' et ''moins'' correctement","Compare quantités avant/après réduction"]}',1,'Plan détaillé avec supports visuels',1756911653906,1757594654548,1,'fr','Sciences de la nature','{"pourDifficultés":["Se concentrer sur 1-2 exemples très évidents (papier, plastique)","Utiliser vraies poubelles pour trier ce qu''on peut réduire","Commencer par réduire à l''école seulement"],"pourAvancés":["Calculer combien de déchets évités par actions de réduction","Créer plan de réduction pour école entière","Comparer déchets avant/après changements