INSERT INTO ETFOLessonPlan VALUES('cmf43u49m016jvj9t6d9bpqba',23,'Partager notre planète équitablement','cmf43u496015jvj9tbdn7emo8',4102416000000,45,'Playground sharing reflection - discuss how students share playground space fairly','Design fair use plan for school natural spaces that considers all living things','Environmental sharing pledge - students commit to fair environmental sharing practices','Démontrer le concept de partager notre; Expérimenter avec la méthode d''investigation scientifique; Développer le respect de la nature par l''investigation scientifique','["playground map","sharing scenario cards","school grounds map","design materials","planning sheets","commitment cards","markers or pencils"]',NULL,'Partager notre planète équitablement','Playground sharing reflection - discuss how students share playground space fairly','Design fair use plan for school natural spaces that considers all living things','Environmental sharing pledge - students commit to fair environmental sharing practices','Démontrer le concept de partager notre; Expérimenter avec la méthode d''investigation scientifique; Développer le respect de la nature par l''investigation scientifique',NULL,NULL,NULL,'formative','{"observable":["L''élève comprend concept de partage équitable d''espaces","L''élève contribue à planification inclusive d''espaces","L''élève s''engage au partage respectueux de l''environnement"],"checkpoints":["Explique pourquoi espaces verts importants pour tous","Propose solutions pour partage équitable","Utilise ''partager équitablement'' dans contexte approprié"]}',1,'Plan détaillé avec supports visuels',1756911653915,1757594654558,1,'fr','Sciences de la nature','{"pourDifficultés":["Se concentrer sur partage d''espaces familiers (parc, cour d''école)","Utiliser exemples concrets de partage équitable","Commencer par ‘chacun a sa place’"],"pourAvancés":["Explorer justice environnementale et accès égal à nature","Concevoir espaces qui répondent aux besoins de tous",