INSERT INTO ETFOLessonPlan VALUES('cmf43u49n016lvj9tq0s69yyt',23,'Devenir des ambassadeurs de l''environnement','cmf43u496015jvj9tbdn7emo8',4102416000000,45,'Ambassador preparation - students choose their best environmental learning to share','Create environmental education presentations for younger students or family members','Ambassador commissioning ceremony - students receive environmental educator certificates','Appliquer le concept de devenir des; Expérimenter avec la méthode d''investigation scientifique; Développer le respect de la nature par l''investigation scientifique','["learning portfolio","presentation planning sheets","presentation materials","visual aids","demonstration supplies","chart paper for recording ideas","markers"]',NULL,'Devenir des ambassadeurs de l''environnement','Ambassador preparation - students choose their best environmental learning to share','Create environmental education presentations for younger students or family members','Ambassador commissioning ceremony - students receive environmental educator certificates','Appliquer le concept de devenir des; Expérimenter avec la méthode d''investigation scientifique; Développer le respect de la nature par l''investigation scientifique',NULL,NULL,NULL,'formative','{"observable":["L''élève prépare contenu éducatif sur environnement","L''élève démontre confiance pour enseigner autres","L''élève s''identifie comme ambassadeur environnemental"],"checkpoints":["Crée présentation ou démonstration environnementale","Partage apprentissage avec authenticité et enthousiasme","S''engage à continuer éducation environnementale"]}',1,'Plan détaillé avec supports visuels',1756911653916,1757594654559,1,'fr','Sciences de la nature','{"pourDifficultés":["Commencer par partager 1 conseil simple avec ami","Utiliser supports visuels pour aider présentation","Pratiquer avec partenaire avant présenter au groupe"],"pourAvancés":["Préparer présentation pour classes plus jeunes","Créer matériels pédagogiques pour