INSERT INTO ETFOLessonPlan VALUES('cmf43u4cd01crvj9trzw7jrlp',23,'Écouter comme des scientifiques','cmf43u4ca01cjvj9t5oghlh0g',1757343600000,45,'Sound detective game - students close eyes and identify familiar classroom sounds','sound exploration stations where students safely shake, tap, and drop different materials to compare sounds','Sound symphony - students create patterns with their favorite sound-makers from the lesson','Prédire le concept de écouter comme; Expérimenter avec la méthode d''investigation scientifique; Développer la démarche scientifique par l''investigation scientifique','["contenants avec matériaux sonores (riz, haricots, sable)","blocs de bois variés","cuillères de métal","matériaux doux et silencieux","espace d''écoute calme","contenants avec matériaux sonores (riz, haricots, sable)","blocs de bois variés","cuillères de métal","matériaux doux et silencieux","espace d''écoute calme","certificats d''encouragement (30 copies)","étiquettes autocollantes (2 planches)","boîte de rangement pour travaux (1 grande boîte)"]',NULL,'Écouter comme des scientifiques','Sound detective game - students close eyes and identify familiar classroom sounds','sound exploration stations where students safely shake, tap, and drop different materials to compare sounds','Sound symphony - students create patterns with their favorite sound-makers from the lesson','Prédire le concept de écouter comme; Expérimenter avec la méthode d''investigation scientifique; Développer la démarche scientifique par l''investigation scientifique',NULL,NULL,NULL,'formative','{"observable":["Participe activement aux activités scientifiques","Suit les règles de sécurité de façon appropriée","Utilise le matériel scientifique avec soin","Exprime sa curiosité et pose des questions","Utilise le vocabulaire scientifique approprié (écouter, sons, différent)"],"checkpoints":["Noter l''engagement et la participation","Observer l''utilisation appropriée du matériel","Documenter les questions et déco