INSERT INTO ETFOLessonPlan VALUES('cmf4e9s4a000hvj8vtscwrmaz',23,'Techniques mixtes','cmf43u3s8004pvj9tvo44st5a',1770825600000,45,'Observation d''œuvres utilisant techniques mixtes; Discussion: ''Que remarquez-vous dans ces créations?''; Démonstration: impression + dessin + collage; Brainstorming des combinaisons possibles; Planification libre individuelle','Exploration libre avec toutes les techniques disponibles; Création d''une œuvre personnelle mixte; Expérimentation avec superposition et juxtaposition; Ajustements selon les effets obtenus; Documentation du processus créatif','Galerie des techniques mixtes; Présentation individuelle: ''Expliquez vos choix techniques''; Identification des combinaisons les plus réussies; Appréciation de la diversité créative; Planification d''utilisations futures','Combiner impression et autres techniques artistiques; Développer la créativité et l''innovation; Intégrer les apprentissages précédents','{"opening":["Matériel d''impression varié","Crayons de couleur et marqueurs","Papier de couleurs variées","Colle et éléments de collage","Ciseaux sécuritaires","Exemples d''art mixte simple"],"main":[],"closing":[]}',NULL,'Techniques mixtes','Observation d''œuvres utilisant techniques mixtes; Discussion: ''Que remarquez-vous dans ces créations?''; Démonstration: impression + dessin + collage; Brainstorming des combinaisons possibles; Planification libre individuelle','Exploration libre avec toutes les techniques disponibles; Création d''une œuvre personnelle mixte; Expérimentation avec superposition et juxtaposition; Ajustements selon les effets obtenus; Documentation du processus créatif','Galerie des techniques mixtes; Présentation individuelle: ''Expliquez vos choix techniques''; Identification des combinaisons les plus réussies; Appréciation de la diversité créative; Planification d''utilisations futures','Combiner impression et autres techniques artistiques; Développer la créativité et l''innovation; Intégrer les apprentissages p