INSERT INTO ETFOLessonPlan VALUES('cmf4e9s4c000jvj8vm1jcp3i7',23,'Motifs de saisons','cmf43u3s8004pvj9tvo44st5a',1770912000000,45,'Observation par la fenêtre: signes de l''hiver; Discussion sur les caractéristiques visuelles de l''hiver; Observation de photos de paysages hivernaux; Introduction des couleurs et formes de l''hiver; Planification d''un ''paysage hivernal en motifs''','Création de motifs de flocons avec tampons spéciaux; Expérimentation avec la peinture blanche sur papier foncé; Ajout d''éléments brillants pour l''effet ''glacé''; Création d''un paysage hivernal stylisé; Superposition de motifs pour effet de profondeur','Exposition ''Galerie d''hiver''; Recherche des différentes interprétations de l''hiver; Discussion sur les émotions évoquées par les créations; Connexion avec les expériences personnelles de l''hiver; Planification d''observations hivernales pour l''art','Créer des motifs inspirés de l''hiver; Faire des liens entre art et observations saisonnières; Développer la sensibilité environnementale','{"opening":["Tampons thématiques hiver (flocons, sapins, mitaines)","Peinture blanche, bleue, argent","Papier bleu foncé et noir","Paillettes et éléments brillants","Photos d''hiver et de neige","Matériel pour créer des tampons flocons"],"main":[],"closing":[]}',NULL,'Motifs de saisons','Observation par la fenêtre: signes de l''hiver; Discussion sur les caractéristiques visuelles de l''hiver; Observation de photos de paysages hivernaux; Introduction des couleurs et formes de l''hiver; Planification d''un ''paysage hivernal en motifs''','Création de motifs de flocons avec tampons spéciaux; Expérimentation avec la peinture blanche sur papier foncé; Ajout d''éléments brillants pour l''effet ''glacé''; Création d''un paysage hivernal stylisé; Superposition de motifs pour effet de profondeur','Exposition ''Galerie d''hiver''; Recherche des différentes interprétations de l''hiver; Discussion sur les émotions évoquées par les créations; Connexion avec les expériences personnelles de l''hiver; Planification d''observations hivernales pour l''art','Créer des motifs inspirés de l''hiver; Faire des liens entre art et observations saisonnières; Développer la sensibilité environnementale','{"pourDifficultés":["Modèles simples de motifs hivernaux","Défis avec création de tampons flocons personnalisés","Support pour élèves moins familiers avec l''hiver"],"pourAvancés":[],"pourLangue":[],"pourPEI":[]}',NULL,NULL,'formative','{"observable":["Utilisation appropriée des couleurs hivernales","Création de motifs évocateurs de la saison","Connexions verbalisées entre observation et création"],"checkpoints":["Représentation reconnaissable de l''hiver","Choix esthétiques cohérents avec le thème","Expression personnelle de l''expérience saisonnière"]}',0,NULL,1756929180828,1757594653791,1,'fr','Arts visuels',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,4,11,'core',1);
INSERT INTO ETFOLessonPlan VALUES('cmf4e9s4d000lvj8vdtkwym1s',23,'Auto-évaluation artistique','cmf43u3s8004pvj9tvo44st5a',1770998400000,45,'Retrouvaille avec son portfolio personnel; Observation chronologique des créations; Discussion: ''Que remarquez-vous dans vos œuvres?''; Introduction des critères d''auto-évaluation; Démonstration d''auto-évaluation positive','Auto-évaluation guidée avec fiche illustrée; Sélection des 3 œuvres préférées avec justifications; Identification des techniques maîtrisées; Reconnaissance des défis surmontés; Planification des apprentissages futurs','Partage en pairs des auto-évaluations; Célébration des progrès identifiés; Planification collective des prochains défis artistiques; Préparation du portfolio pour présentation; Reconnaissance de chacun comme artiste unique','Développer la capacité de réflexion sur son travail; Utiliser le vocabulaire artistique approprié; Reconnaître ses progrès et ses préférences','{"opening":["Portfolio individuel des œuvres créées","Fiche d''auto-évaluation avec pictogrammes","Miroir pour auto-observation","Vocabulaire artistique affiché","Appareil photo pour documentation"],"main":[],"closing":[]}',NULL,'Auto-évaluation artistique','Retrouvaille avec son portfolio personnel; Observation chronologique des créations; Discussion: ''Que remarquez-vous dans vos œuvres?''; Introduction des critères d''auto-évaluation; Démonstration d''auto-évaluation positive','Auto-évaluation guidée avec fiche illustrée; Sélection des 3 œuvres préférées avec justifications; Identification des techniques maîtrisées; Reconnaissance des défis surmontés; Planification des apprentissages futurs','Partage en pairs des auto-évaluations; Célébration des progrès identifiés; Planification collective des prochains défis artistiques; Préparation du portfolio pour présentation; Reconnaissance de chacun comme artiste unique','Développer la capacité de réflexion sur son travail; Utiliser le vocabulaire artistique approprié; Reconnaître ses 