INSERT INTO ETFOLessonPlan VALUES('cmf4e9s4f000nvj8v0c385og7',23,'Préparation d''exposition','cmf43u3s8004pvj9tvo44st5a',4102416000000,45,'Visite d''une ''vraie'' exposition ou observation de photos; Discussion: ''Comment présente-t-on l''art dans les galeries?''; Démonstration de préparation d''une œuvre pour exposition; Introduction du rôle d''artiste-exposant; Planification de notre mini-galerie de classe','Sélection finale des œuvres à exposer; Nettoyage et retouches mineures si nécessaire; Création d''étiquettes avec titre et nom d''artiste; Encadrement ou mise en valeur des œuvres; Installation collaborative dans l''espace d''exposition','Tour de la galerie en mode ''vernissage''; Pratique de présentation orale simple; Préparation des invitations pour les familles; Établissement des règles de comportement en galerie; Célébration du travail de préparation accompli','Préparer ses œuvres pour le partage public; Développer la fierté du travail accompli; Apprendre les bases de la présentation artistique','{"opening":["Cadres simples ou bordures décoratives","Étiquettes pour identifier les œuvres","Matériel de nettoyage et retouche","Crayons pour signatures","Ruban adhésif et punaises","Espace d''exposition préparé"],"main":[],"closing":[]}',NULL,'Préparation d''exposition','Visite d''une ''vraie'' exposition ou observation de photos; Discussion: ''Comment présente-t-on l''art dans les galeries?''; Démonstration de préparation d''une œuvre pour exposition; Introduction du rôle d''artiste-exposant; Planification de notre mini-galerie de classe','Sélection finale des œuvres à exposer; Nettoyage et retouches mineures si nécessaire; Création d''étiquettes avec titre et nom d''artiste; Encadrement ou mise en valeur des œuvres; Installation collaborative dans l''espace d''exposition','Tour de la galerie en mode ''vernissage''; Pratique de présentation orale simple; Préparation des invitations pour les familles; Établissement des règles de comportement en galerie; Célébration du travail de préparation accompli','Préparer ses œuvres pour le partage public; Développer la fierté du travail accompli; Apprendre les bases de la présentation artistique','{"pourDifficultés":["Aide personnalisée pour l''organisation","Responsabilités d''aide pour élèves avancés","Support émotionnel pour élèves anxieux"],"pourAvancés":[],"pourLangue":[],"pourPEI":[]}',NULL,NULL,'formative','{"observable":["Soin dans la préparation des œuvres","Fierté appropriée du travail accompli","Respect pour l''art (sien et celui des autres)"],"checkpoints":["Participation active à la préparation","Attention aux détails de présentation","Attitude respectueuse envers l''exposition"]}',0,NULL,1756929180830,1757594653793,1,'fr','Arts visuels',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,4,13,'core',0);
INSERT INTO ETFOLessonPlan VALUES('cmf4e9s4f000pvj8vvtfb007a',23,'Partage et célébration','cmf43u3s8004pvj9tvo44st5a',1771862400000,45,'Accueil officiel des invités (familles, autres classes); Remise des badges ''Artiste'' à chaque élève; Présentation du parcours artistique de l''unité; Remerciements et reconnaissance du travail accompli; Ouverture officielle de l''exposition','Visites guidées par les élèves-artistes; Présentations individuelles courtes devant les œuvres; Démonstrations techniques en direct; Interactions avec les invités et explications; Signature du livre d''or par les visiteurs','Rassemblement final avec tous les participants; Lecture de quelques commentaires du livre d''or; Remise des certificats d''accomplissement artistique; Planification de la conservation des œuvres; Célébration collective des artistes de la classe','Présenter et célébrer les créations accomplies; Développer les compétences de communication; Reconnaître les apprentissages réalisés','{"opening":["Exposition montée et préparée","Microphone ou système d''amplification simple","Badges ''Artiste'' pour chaque élève","Livre d''or pour les commentaires","Rafraîchissements simples","Certificats de participation artistique"],"main":[],"closing":[]}',NULL,'Partage et célébration','Accueil officiel des invités (familles, autres classes); Remise des badges ''Artiste'' à chaque élève; Présentation du parcours artistique de l''unité; Remerciements et reconnaissance du travail accompli; Ouverture officielle de l''exposition','Visites guidées par les élèves-artistes; Présentations individuelles courtes devant les œuvres; Démonstrations techniques en direct; Interactions avec les invités et explications; Signature du livre d''or par les visiteurs','Rassemblement final avec tous les participants; Lecture de quelques commentaires du livre d''or; Remise des certificats d''accomplissement artistique; Planification de la conservation des œuvres; Célébration collective des artistes de la classe','Présenter et célébrer les créations accomplies; Développer les compétences de communication; Reconnaître les apprentissages réalisés','{"pourDifficultés":["Formats de présentation adaptés à chaque élève","Soutien par les pairs pour élèves timides","Rôles spéciaux pour élèves avec besoins particuliers"],"pourAvancés":[],"pourLangue":[],"pourPEI":[]}',NULL,NULL,'formative','{"observable":["Confiance dans la présentation de son travail","Capacité de communiquer sur son processus créatif","Fierté appropriée des accomplissements"],"checkpoints":["Participation à la célébration","Communication efficace sur son art","Reconnaissance des apprentissages réalisés"]}',0,NULL,1756929180831,1757594653794,1,'fr','Arts visuels',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,4,14,'core',1);
INSERT INTO LongRangePlan VALUES('cmebyc98h0001vjr1cvh4knsh',23,'Français (Immersion) - Grade 1 French Immersion Excellence','2025-2026',NULL,1,'Français (Immersion)','A comprehensive French language arts program developing emergent literacy through systematic phonological awareness, high-frequency word mastery, guided reading progressions, and authentic writing experiences. Integrates oral communication, cultural identity, and joyful engagement with French literature.',replace('SPECIFIC MEASURABLE LEARNING GOALS:\n• Students will decode CVC words in French with 90% accuracy by December\n• Students will recognize 50 high-frequency French words automatically by March  \n• Students will read Level C French texts independently by June\n• Students will write 3-sentence stories using emergent spelling by April\n• Students will participate in 5-minute French conversations using complete sentences by May\n• Students will demonstrate comprehension through retelling with 80% accuracy\n• Students will identify all French phonemes and graphemes by February\n• Students will use 200+ French vocabulary words in context by year end','\n',char(10)),'[{"month":"Septembre","theme":"Bienvenue à l''école - Building Our French Community","focus":"Oral language, classroom French, routines and expectations","integration":"Social Studies (classroom community), Math (counting classmates)"},{"month":"Octobre","theme":"Ma famille et moi - Family Stories and Traditions","focus":"Personal narratives, family vocabulary, beginning reading","integration":"Arts (family portraits), Social Studies (family structures)"},{"month":"Novembre","theme":"Les fêtes d''automne - Celebrating Together","focus":"Cultural stories, descriptive language, letter-sound relationships","integration":"Science (seasonal changes), Arts (celebration art)"},{"month":"Décembre","theme":"L''hiver magique - Winter Wonder Stories","focus":"Fiction vs non-fiction, story elements, writing lists and cards","integration":"Science (winter weather), Math (calendar and time)"},{"month":"Janvier","theme":"Nos amis les animaux - Animal Adventures","focus":"Information texts, research skills, descriptive writing","integration":"Science (living things), Arts (animal art)"},{"month":"Février","theme":"Ma communauté - Community Helpers and Places","focus":"Procedural texts, question formation, letter writing","integration":"Social Studies (community), Math (mapping)"},{"month":"Mars","theme":"Le printemps en fleurs - Spring Growth","focus":"Poetry, word families, journal writing","integration":"Science (plant growth), Arts (nature art)"},{"month":"Avril","theme":"Contes et légendes - Stories from Many Cultures","focus":"Traditional tales, comparing stories, creative writing","integration":"Social Studies (cultures), Arts (story illustration)"},{"month":"Mai","theme":"Notre monde - Exploring Our World","focus":"Non-fiction features, research projects, presentations","integration":"Science (environments), Social Studies (geography)"},{"month":"Juin","theme":"Célébrons nos apprentissages - Celebrating Learning","focus":"Reflection, showcasing growth, summer reading preparation","integration":"All subjects - year-end culminating activities"}]',replace('ESSENTIAL QUESTIONS (Grade 1 Appropriate):\n• Comment je parle? (How do I speak?)\n• Où sont les mots? (Where are words?)\n• Qui raconte? (Who tells stories?)\n• Pourquoi lire? (Why read?)\n• Comment j''écris? (How do I write?)\n• Qu''est-ce qu''on dit? (What do we say?)','\n',char(10)),replace('COMPREHENSIVE ASSESSMENT STRATEGY:\n\nFORMATIVE ASSESSMENT (Daily/Weekly):\n• Running Records: PM Benchmarks French (bi-weekly) with error analysis\n• Phonics Quick-Checks: Weekly systematic phoneme assessment\n• Oral Language Sampling: Monthly video recordings with rubrics\n• Interactive Writing Observations: Daily anecdotal notes\n• Reading Response Discussions: Participation tracking charts\n• Word Work Checks: Weekly sight word assessments\n\nSUMMATIVE ASSESSMENT (Monthly/Term):\n• Portfolio Conferences: Student self-selected best work\n• Performance Tasks: Storytelling, readers theatre, puppet shows\n• Writing Samples: Monthly collection (narrative, informational, opinion)\n• French Literacy Skills Checklist: Comprehensive monthly review\n• Reading Level Assessments: GB+ or PM Benchmarks monthly\n• Oral Communication Rubrics: Formal presentations quarterly','\n',char(10)),replace('SPECIFIC RESOURCE REQUIREMENTS:\n\nCore Instructional Materials:\n• GB+ Lecteurs levels AA-J (30 copies each level)\n• Raconte-moi l''alphabet (phonics program)\n• 50 French high-frequency word cards (laminated)\n• Individual white boards and markers (30 sets)\n• French sound wall materials\n\nClassroom Library:\n• 200+ French picture books across genres\n• 50 dual-language books for ELL support\n• 30 wordless books for storytelling\n• 25 big books for shared reading\n• 15 poetry anthologies for children\n\nTechnology:\n• 6 tablets with French learning apps\n• Headphones with microphones (30)\n• Document camera for modeled writing\n• Access to Radio-Canada Jeunesse\n\nConsumables:\n• Writing journals (30 x 3 terms)\n• Phonics workbooks (30)\n• Home reading logs (30 x monthly)\n• Portfolio folders (30)','\n',char(10)),'Améliorer les stratégies d''immersion. Approfondir les connaissances culturelles Mi''kmaq. Explorer l''apprentissage par le jeu. Développer l''évaluation authentique.',NULL,NULL,NULL,'2025-08-14T22:09:29.537Z','2025-08-19T17:09:49.403Z','{"math":["Number books and counting stories","Word problems in French","Calendar and time vocabulary","Measurement language in French"],"science":["Science vocabulary in French","Observation journals","Non-fiction reading about nature","Procedural writing for experiments"],"socialStudies":["Community vocabulary","Cultural stories and traditions","Map reading and directions","Family and identity texts"],"arts":["Illustrating stories","Drama and readers theatre","Songs and poetry","Visual vocabulary development"],"physicalEducation":["Movement vocabulary","Game instructions in French","Action words and verbs","Body parts vocabulary"]}',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'{"immediateNeeds":["Reading Recovery training in French - August intensive","Guided Reading in French Immersion - September workshop"],"termOne":["Assessment in French Literacy - October PD day","Differentiation for Diverse Learners - November collaborative"],"termTwo":["Indigenous Perspectives in French - January workshop","Writing Workshop Model - February training","Family Engagement Strategies - March conference"],"ongoing":["Weekly grade team collaboration - Thursdays 3:30-4:30","Monthly French department meetings - First Tuesday","Quarterly literacy coach observations and feedback"],"summerPlanning":["Advanced French Immersion Institute - July","Technology Integration for Language Learning - August"]}',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'{"framework":"Universal Design for Learning with specific accommodations","strugglingLearners":["Pre-teach vocabulary with visual cards","Provide sentence frames for oral and written work","Use manipulatives for phonics (letter tiles)","Offer extra time and repeated practice","Partner with supportive peer for activities","Break tasks into smaller steps with checkpoints","Provide recorded models of reading"],"advancedLearners":["Offer choice in reading materials (higher levels)","Extend writing tasks with additional challenges","Provide leadership roles in group work","Create opportunities for peer teaching","Introduce additional vocabulary and expressions","Encourage creative project extensions","Connect to French media and authentic resources"],"englishLanguageLearners":["Use total physical response (TPR) methods","Provide visual vocabulary cards in L1 when possible","Allow code-switching during transition period","Partner with bilingual buddies","Focus on high-frequency words first","Use gestures and demonstrations extensively","Celebrate multilingual connections"],"iepStudents":["Follow individual accommodation plans","Provide assistive technology as specified","Modify expectations according to IEP goals","Use multi-sensory approaches consistently","Provide alternative response formats","Collaborate with resource team weekly","Document progress toward IEP objectives"]}',NULL,NULL,NULL,replace('AUTHENTIC MI''KMAQ INTEGRATION:\n\nPartnership Development:\n• Collaborate with Mi''kmaq Education Coordinator (September meeting scheduled)\n• Elder Mary Bernard invited for monthly storytelling sessions\n• Keptin Stephen Augustine consultation on traditional stories\n\nSpecific Integration:\n• September: Mi''kmaq welcome protocols and greetings in daily routine\n• October: Family structures in Mi''kmaq culture, Seven Sacred Teachings\n• November: Harvest celebrations and gratitude practices\n• December: Winter stories from Mi''kmaq oral tradition\n• January: Animal teachings and relationships with nature\n• February: Community roles in traditional and contemporary Mi''kmaq life\n• March: Mi''kmaq observations of seasonal changes\n• April: Traditional Mi''kmaq stories and legends (with permission)\n• May: Land-based learning on traditional territory\n• June: Celebrating learning with Mi''kmaq drumming and song\n\nResources:\n• "Muin and the Seven Bird Hunters" by Lillian Marshall\n• "The Sharing Circle" by Theresa Meuse-Dallien\n• Mi''kmaq language integration where appropriate\n• Land acknowledgment in French and Mi''kmaq daily','\n',char(10)),replace('PROFESSIONAL RESOURCE LIBRARY:\n\nProfessional Books:\n• "L''apprentissage de la lecture et de l''écriture" - Nadon\n• "La lecture guidée" - Fountas & Pinnell (French adaptation)\n• "Les 5 au quotidien" - Boushey & Moser (French version)\n• "Enseigner la lecture" - Giasson\n\nAssessment Tools:\n• PM Benchmarks Kit (French)\n• GB+ Assessment Kit\n• Observation Survey (Marie Clay - French)\n• Trousse d''évaluation en lecture\n\nDigital Resources:\n• Boukili app subscription\n• TumbleBooks French collection\n• Idéllo educational platform\n• Centre franco resources','\n',char(10)),replace('COMPREHENSIVE FAMILY ENGAGEMENT:\n\nWeekly Communication:\n• Bilingual classroom newsletter every Friday\n• Week at a Glance French vocabulary list\n• Home reading recommendations and tips\n• Celebration of student work samples\n\nMonthly Engagement:\n• Curriculum focus explanation newsletter\n• French literacy night (third Thursday)\n• Home learning activity calendar\n• Parent volunteer opportunities\n\nAssessment Communication:\n• Portfolio preparation guides (sent 1 week before conferences)\n• Monthly reading level updates\n• Writing sample analysis and growth charts\n• Video clips of oral French development (with consent)\n\nCultural Celebrations:\n• Family story sharing invitations\n• Multicultural book recommendations\n• Heritage language connections to French\n• Community cultural events calendar\n\nSupport Resources:\n• French pronunciation guides for families\n• Apps and websites for French practice\n• Public library French resource lists\n• Summer French maintenance activities','\n',char(10)));
INSERT INTO LongRangePlan VALUES('cmebyc98k0003vjr1svziz0in',23,'Mathematics Excellence - Grade 1 French Immersion','2025-2026',NULL,1,'Mathématiques','A hands-on, inquiry-based mathematics program building number sense to 100, operational fluency, pattern recognition, spatial reasoning, and problem-solving strategies through concrete-pictorial-abstract progressions aligned with current research in mathematical cognition.',replace('SPECIFIC MEASURABLE LEARNING GOALS:\n• Students will count to 100 by 1s, 2s, 5s, and 10s with 95% accuracy\n• Students will solve addition problems to 20 using 3+ strategies\n• Students will solve subtraction problems to 20 using 3+ strategies  \n• Students will identify, create, and extend AB, ABC, AAB, and AABB patterns\n• Students will name and describe 8 2D shapes and 5 3D solids in French\n• Students will measure using non-standard units with 90% accuracy\n• Students will collect, organize, and interpret data in 3 different ways\n• Students will solve word problems using drawing, acting out, or manipulatives\n• Students will explain mathematical thinking orally in French\n• Students will recognize number patterns and relationships to 100','\n',char(10)),'[{"month":"Septembre","theme":"Les nombres autour de nous - Numbers Everywhere","focus":"Counting, number recognition, one-to-one correspondence","concepts":"Numbers to 20, counting collections, number stories","integration":"Science (counting observations), French (number books)"},{"month":"Octobre","theme":"Régularités et relations - Patterns and Relationships","focus":"Pattern recognition, creation, and extension","concepts":"AB, ABC patterns, growing patterns, number patterns","integration":"Music (rhythm patterns), Art (visual patterns)"},{"month":"Novembre","theme":"L''addition jusqu''à 10 - Building Addition Sense","focus":"Addition concepts, strategies, and fluency","concepts":"Combining, counting on, doubles, near doubles","integration":"PE (scoring games), Science (combining materials)"},{"month":"Décembre","theme":"Formes et espace - Geometry Around Us","focus":"2D shapes, 3D solids, spatial relationships","concepts":"Shape attributes, sorting, building, position words","integration":"Art (shape art), Social Studies (mapping)"},{"month":"Janvier","theme":"La soustraction - Taking Away and Comparing","focus":"Subtraction concepts and strategies","concepts":"Take away, comparison, counting back, related facts","integration":"French (subtraction stories), Science (comparing)"},{"month":"Février","theme":"Mesurer notre monde - Measurement Explorations","focus":"Length, mass, capacity, time","concepts":"Non-standard units, comparison, ordering","integration":"PE (measuring jumps), Science (measuring growth)"},{"month":"Mars","theme":"Nombres jusqu''à 100 - Exploring Larger Numbers","focus":"Place value, skip counting, number relationships","concepts":"Tens and ones, counting by 2s, 5s, 10s","integration":"Social Studies (100th day), French (100 words)"},{"month":"Avril","theme":"Données et probabilité - Data and Chance","focus":"Collecting, organizing, and interpreting data","concepts":"Surveys, graphs, likelihood, simple probability","integration":"Science (weather data), Social Studies (preferences)"},{"month":"Mai","theme":"Résolution de problèmes - Problem Solving Power","focus":"Multiple strategies, explaining thinking","concepts":"Word problems, multi-step problems, creating problems","integration":"All subjects - real-world problem solving"},{"month":"Juin","theme":"Célébration mathématique - Math Celebration","focus":"Review, consolidation, and showcasing learning","concepts":"Math games, puzzles, investigations, math fair","integration":"Family engagement, cross-curricular projects"}]',replace('ESSENTIAL QUESTIONS (Maximum 6 words):\n• Combien y a-t-il? (How many are there?)\n• Qu''est-ce qui vient après? (What comes next?)\n• Comment peut-on résoudre? (How can we solve?)\n• Où sont les nombres? (Where are numbers?)\n• Quelle est la règle? (What''s the pattern?)\n• Comment peut-on mesurer? (How can we measure?)','\n',char(10)),replace('COMPREHENSIVE ASSESSMENT STRATEGY:\n\nFORMATIVE ASSESSMENT (Daily/Weekly):\n• Number Talks: Daily 10-minute sessions with observation\n• Math Journals: Weekly reflections with picture representations\n• Exit Tickets: 3x weekly problem-solving checks\n• Manipulative Work: Photo documentation of strategies\n• Think-Pair-Share: Peer discussion observations\n• Game-Based Assessment: Strategy tracking during math games\n• Error Analysis: Weekly misconception identification\n\nSUMMATIVE ASSESSMENT (Monthly/Term):\n• Problem-Solving Performance Tasks: Open-ended monthly challenges\n• Diagnostic Interviews: Individual 5-minute monthly check-ins\n• Portfolio Conferences: Student-selected best work quarterly\n• Skills Checklists: Comprehensive monthly review\n• Math Celebrations: Family math nights with demonstrations\n• Digital Portfolios: Video explanations of thinking','\n',char(10)),replace('SPECIFIC MATH RESOURCE REQUIREMENTS:\n\nManipulatives (Class Sets):\n• Base-10 blocks (15 sets)\n• Pattern blocks (500 pieces)\n• Counting bears (500)\n• Two-color counters (500)\n• Dice (various types - 60)\n• Dominoes (10 sets)\n• Unifix cubes (1000)\n• Geoboards with elastics (30)\n• Tangrams (30 sets)\n• Clocks (30)\n\nMeasurement Tools:\n• Balance scales (6)\n• Non-standard measurement tools\n• Measuring tapes/rulers (30)\n• Thermometers (10)\n• Calendars (wall and individual)\n\nGames and Activities:\n• Math board games (20 different)\n• Card games for math facts\n• Puzzle sets\n• Math center activities (rotating)\n\nTechnology:\n• Math learning apps (tablets)\n• Interactive whiteboard software\n• Virtual manipulatives access\n• Online math games subscription','\n',char(10)),'Deepen understanding of developmental math progressions. Improve French math vocabulary. Explore play-based math learning. Strengthen formative assessment practices.',NULL,NULL,NULL,'2025-08-14T22:09:29.540Z','2025-08-19T02:40:47.839Z','{"french":["Math vocabulary in French daily","Number books and counting songs","Word problems in French","Math journals in French"],"science":["Measurement in experiments","Data collection from observations","Patterns in nature","Sorting and classifying"],"socialStudies":["Mapping and location","Timeline mathematics","Community helper math","Money and economics"],"arts":["Geometric art projects","Pattern creation","Symmetry in art","Rhythm and counting in music"],"physicalEducation":["Scoring and counting","Measurement of performance","Time and duration","Spatial awareness"]}',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'{"immediateNeeds":["Building Thinking Classrooms - Peter Liljedahl method training","French Mathematical Vocabulary Development - August workshop"],"termOne":["Number Sense Interventions - September PD","Cognitively Guided Instruction - October training","Math Talk Communities - November workshop"],"termTwo":["Problem-Based Learning - January intensive","Assessment in Mathematics - February conference","Technology in Math - March training"],"ongoing":["Lesson Study Cycles - Monthly with grade team","Math Learning Community - Bi-weekly Wednesdays","Jo Boaler''s Mathematical Mindsets online course"],"resources":["Which One Doesn''t Belong? website","Estimation180 daily practice","Would You Rather Math discussions"]}',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'{"framework":"Tiered instruction with multiple entry points","strugglingLearners":["Pre-teach vocabulary with math word wall","Provide concrete manipulatives for all problems","Break problems into smaller steps","Use number lines and hundreds charts","Partner with math buddy for support","Reduce number size in problems","Provide visual models and drawings","Extra practice with basic facts","Use of calculator for checking"],"advancedLearners":["Extend numbers beyond 100","Multi-step problem solving","Create problems for others to solve","Explore different problem-solving strategies","Math journaling with explanations","Leadership in math games and activities","Investigation projects","Mental math challenges","Pattern explorations beyond curriculum"],"englishLanguageLearners":["Visual vocabulary cards for math terms","Gesture and demonstration for concepts","Allow explanations in first language initially","Peer translation support","Concrete materials for all concepts","Picture dictionaries for math","Word banks for problem solving","Extra time for language processing"],"iepStudents":["Modified number ranges as per IEP","Alternative response formats","Assistive technology (talking calculator)","Sensory materials for counting","Movement breaks during math","Reduced problem sets","Focus on priority outcomes","Regular check-ins and support"]}',NULL,NULL,NULL,replace('AUTHENTIC MI''KMAQ MATHEMATICAL INTEGRATION:\n\nCultural Mathematics Connections:\n• Traditional counting systems and number concepts\n• Patterns in Mi''kmaq beadwork and basket weaving\n• Geometric designs in traditional art and regalia\n• Time concepts in seasonal calendars and moon cycles\n• Measurement in traditional building and crafts\n• Data in traditional weather prediction methods\n\nSpecific Monthly Integration:\n• September: Mi''kmaq counting words and games\n• October: Patterns in traditional Mi''kmaq art\n• November: Story problems using Mi''kmaq contexts\n• December: Geometry in wigwam construction\n• January: Traditional games involving subtraction\n• February: Measuring with natural materials\n• March: Counting in Mi''kmaq to 100\n• April: Traditional weather data and predictions\n• May: Problem-solving through traditional stories\n• June: Math in Mi''kmaq games and celebrations\n\nResources and Partnerships:\n• Elder consultation on traditional mathematics\n• Mi''kmaq Mawio''mi games with mathematical elements\n• Visits to Mi''kmaq Heritage Centre for pattern study\n• Guest speakers on traditional crafts and mathematics','\n',char(10)),replace('MATH PROFESSIONAL LIBRARY:\n\nTeacher Resources:\n• "Building Thinking Classrooms" - Liljedahl\n• "Mathematical Mindsets" - Jo Boaler\n• "Number Talks" - Sherry Parrish\n• "Mathématiques - Sens du nombre" - Small\n• "L''enseignement des mathématiques" Tome 1 & 2\n\nAssessment Resources:\n• PRIME Diagnostic Kit\n• Leaps and Bounds assessment\n• First Steps in Mathematics\n• Math Recovery assessment tools\n\nChildren''s Literature:\n• French counting books collection (25)\n• Math concept story books (40)\n• Problem-solving stories (20)\n• Shape and pattern books (15)\n\nDigital Resources:\n• Mathies.ca tools\n• Desmos activities\n• Which One Doesn''t Belong?\n• Splat! activities\n• Number Talk images','\n',char(10)),replace('FAMILY MATH ENGAGEMENT:\n\nWeekly Support:\n• Math at Home newsletter with family activities\n• Week''s learning goals and vocabulary (French/English)\n• Game suggestions using household items\n• Questions to ask your child about math\n\nMonthly Programs:\n• Family Math Night (second Tuesday, 6-7 PM)\n• Take-Home Math Bags with games and activities\n• Parent workshops on supporting math at home\n• Math challenges for families to solve together\n\nAssessment Communication:\n• Monthly skills checklist sent home\n• Video clips of problem-solving strategies\n• Portfolio samples with growth commentary\n• Celebration of mathematical thinking examples\n\nResources for Families:\n• Recommended math apps (free options prioritized)\n• Library book lists for math stories\n• Websites for practice (French and English)\n• Summer math calendars with daily activities\n• Grocery store math activities guide\n• Cooking and measurement activities','\n',char(10)));
INSERT INTO LongRangePlan VALUES('cmebyc98q0005vjr19wxzdygh',23,'Natural Sciences Excellence - Grade 1 French Immersion','2025-2026',NULL,1,'Sciences de la nature','An inquiry-based science program fostering curiosity about living things, energy, seasonal changes, and environmental stewardship through hands-on investigations, outdoor explorations, and scientific thinking development appropriate for 6-year-old learners.',replace('SPECIFIC MEASURABLE LEARNING GOALS:\n• Students will observe and document 10 seasonal changes using scientific drawings\n• Students will classify 20 objects as living/non-living with 90% accuracy\n• Students will identify 5 basic needs of living things through investigation\n• Students will name 3 energy sources in their daily environment\n• Students will predict outcomes of 5 simple experiments with reasoning\n• Students will use 30 French science vocabulary words in context\n• Students will ask testable questions about natural phenomena\n• Students will record observations using pictures, numbers, and words\n• Students will identify 5 ways humans impact the environment\n• Students will demonstrate 10 safety procedures in science activities','\n',char(10)),'[{"month":"Septembre","theme":"Notre environnement scolaire - School Environment","focus":"Observation skills, living vs non-living, school yard exploration","safety":"Outdoor boundaries, plant safety, no picking without permission","activities":"Nature walk protocols, observation journals, classification games"},{"month":"Octobre","theme":"Les changements d''automne - Fall Changes","focus":"Seasonal observations, leaf study, animal preparation","safety":"Weather-appropriate clothing, mushroom awareness, insect safety","activities":"Leaf collection and pressing, weather tracking, squirrel observations"},{"month":"Novembre","theme":"Les besoins des êtres vivants - Needs of Living Things","focus":"Basic needs, animal homes, plant needs","safety":"Hand washing after handling materials, pet visit protocols","activities":"Classroom plant care, animal habitat models, needs sorting"},{"month":"Décembre","theme":"L''énergie dans nos vies - Energy in Our Lives","focus":"Light, heat, sound, movement energy","safety":"Electrical safety, hot/cold safety, loud sound protection","activities":"Shadow exploration, warmth investigations, sound makers"},{"month":"Janvier","theme":"L''hiver et ses merveilles - Winter Wonders","focus":"Snow and ice properties, winter adaptations","safety":"Ice safety, hypothermia prevention, proper winter gear","activities":"Snow investigations, ice experiments, animal tracking"},{"month":"Février","theme":"La croissance et les changements - Growth and Changes","focus":"Human growth, plant growth, life cycles","safety":"Seed safety (no beans if allergies), growth chart hygiene","activities":"Bean plant growing, growth measurements, baby photo timeline"},{"month":"Mars","theme":"L''eau dans notre monde - Water in Our World","focus":"Water properties, water cycle basics, conservation","safety":"Water table rules, spill procedures, drinking water only","activities":"Float/sink experiments, rain collection, water art"},{"month":"Avril","theme":"Le réveil du printemps - Spring Awakening","focus":"Spring changes, new life, garden planning","safety":"Garden tool safety, sun protection, insect awareness","activities":"Seed starting, bird watching, spring journal"},{"month":"Mai","theme":"Les petites bêtes - Small Creatures","focus":"Insects, worms, small animal study","safety":"No touching without permission, gentle handling, allergies","activities":"Bug hotels, worm bins, magnifying explorations"},{"month":"Juin","theme":"Notre impact sur la nature - Our Environmental Impact","focus":"Recycling, conservation, environmental protection","safety":"Garbage handling safety, recycling sorting rules","activities":"School yard cleanup, recycling audit, conservation pledges"}]',replace('ESSENTIAL QUESTIONS (Concrete & Observable):\n• Qu''est-ce qui vit? (What is alive?)\n• Que voit-on dehors? (What do we see outside?)\n• Comment ça change? (How does it change?)\n• D''où vient l''énergie? (Where does energy come from?)\n• Comment on sait? (How do we know?)\n• Pourquoi c''est important? (Why does it matter?)','\n',char(10)),replace('COMPREHENSIVE ASSESSMENT WITH SAFETY FOCUS:\n\nSAFETY PROTOCOLS (MANDATORY):\n• Outdoor supervision ratio: 1:8 maximum\n• Hand washing before/after all investigations\n• No tasting without explicit permission\n• Safety goggles for any splashing activities\n• Allergy awareness for all nature materials\n• Emergency procedures posted and practiced\n• First aid kit accessibility verified daily\n• Weather safety guidelines followed\n\nFORMATIVE ASSESSMENT (Daily/Weekly):\n• Science journals with dated observations\n• Photo documentation of investigations\n• "I Notice, I Wonder" charts\n• Prediction vs. outcome recordings\n• Scientific drawing progression portfolios\n• Oral explanations in French\n• Safety procedure demonstrations\n\nSUMMATIVE ASSESSMENT (Unit/Term):\n• Investigation projects with presentations\n• Living/non-living sorting assessments\n• Seasonal change documentation books\n• Energy use home audits\n• Science fair projects (simplified)\n• Nature collection classifications','\n',char(10)),replace('SCIENCE RESOURCE REQUIREMENTS:\n\nSafety Equipment (PRIORITY):\n• Safety goggles (30 child-sized)\n• First aid kit (classroom dedicated)\n• Hand sanitizer stations (3)\n• Allergy alert signs\n• Emergency contact forms\n\nInvestigation Tools:\n• Magnifying glasses (30)\n• Collection containers with lids (30)\n• Measuring tools (rulers, scales, thermometers)\n• Science journals (30)\n• Digital camera for documentation\n• Microscope (1 classroom model)\n\nLiving Things Materials:\n• Classroom plants (6 different types)\n• Butterfly garden kit\n• Worm bin composter\n• Bird feeders and seeds\n• Aquarium or terrarium\n\nExperimental Materials:\n• Safety-approved science kit\n• Water table and tools\n• Sand/soil samples\n• Weather monitoring tools\n• Simple machines set\n\nConsumables:\n• Seeds for planting\n• pH paper\n• Coffee filters\n• Food coloring\n• Baking soda/vinegar','\n',char(10)),'Expand outdoor education skills. Deepen Indigenous science knowledge. Improve inquiry facilitation. Develop authentic science assessment.',NULL,NULL,NULL,'2025-08-14T22:09:29.546Z','2025-08-18T12:34:11.708Z','{"french":["Science vocabulary development","Observation writing in journals","Science information books","Oral presentations of findings"],"math":["Measurement in investigations","Graphing and data collection","Pattern recognition in nature","Counting and sorting activities"],"socialStudies":["Community helpers (scientists)","Environmental citizenship","Cultural science practices","Local environment study"],"arts":["Scientific drawing techniques","Nature art and crafts","Seasonal art projects","Music from nature sounds"],"physicalEducation":["Animal movement games","Outdoor exploration fitness","Energy and movement","Season-appropriate activities"]}',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'{"criticalSafety":["MANDATORY: Outdoor Education Safety Certification - Before September","Science Safety for Primary Grades - August workshop"],"immediateNeeds":["Inquiry-Based Science for Grade 1 - September PD","French Science Vocabulary Development - September"],"termOne":["Outdoor Classroom Management - October","Indigenous Science Perspectives - November","STEM Integration K-2 - December"],"termTwo":["Environmental Education - January","Science Literacy Integration - February","Assessment in Science - March"],"ongoing":["Scientists in Schools partnership program","Nature PEI educator workshops","Science safety updates quarterly"]}',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'{"framework":"Hands-on exploration with multiple entry points","strugglingLearners":["Partner for all investigations","Pre-teach science vocabulary with pictures","Simplified observation sheets","Concrete materials for all concepts","Step-by-step visual instructions","Modified recording methods (drawings only)","Extra time for explorations","Reduced variables in experiments"],"advancedLearners":["Additional variables in experiments","Research extensions on topics","Lead science demonstrations","Create science books for kindergarten","Design their own investigations","Science expert roles in groups","Connection to global issues","Science fair advanced projects"],"englishLanguageLearners":["Picture vocabulary cards for all terms","Demonstrations before vocabulary","Native language science journals okay","Peer translators during discussions","Visual safety instructions","Hands-on learning prioritized","Label everything with pictures","Science word walls in multiple languages"],"iepStudents":["Sensory considerations for materials","Alternative investigation methods","Modified safety equipment if needed","Visual schedules for experiments","Frequent check-ins during activities","Adapted recording methods","Focus on priority science concepts","Support personnel during investigations"]}',NULL,NULL,NULL,replace('AUTHENTIC MI''KMAQ SCIENCE INTEGRATION:\n\nTraditional Ecological Knowledge:\n• Seasonal rounds and traditional calendar integration\n• Medicine wheel teachings and four directions\n• Traditional uses of plants (with Elder guidance)\n• Animal teachings and relationships\n• Water as sacred - conservation teachings\n• Seven Sacred Teachings through nature\n\nMonthly Integration with Safety:\n• September: Mi''kmaq names for local plants and animals\n• October: Traditional knowledge of seasonal changes\n• November: Animal teachings about preparation and sharing\n• December: Winter solstice and light celebrations\n• January: Traditional winter survival knowledge\n• February: Growth teachings from Elder stories\n• March: Water protection and respect teachings\n• April: Traditional spring medicines (observation only)\n• May: Relationship with small creatures\n• June: Land stewardship and seven generations thinking\n\nPartnerships:\n• Monthly Elder visits for outdoor teachings\n• Mi''kmaq Confederacy environmental programs\n• Traditional medicine garden visits (look don''t touch)\n• Participation in water ceremonies (age-appropriate)','\n',char(10)),replace('SCIENCE TEACHING RESOURCES:\n\nProfessional Books:\n• "Primary Science" - Harlen\n• "L''enseignement des sciences" - Thouin\n• "Outdoor Learning" - Cornell\n• "Indigenous Science Education" - Aikenhead\n\nChildren''s Science Literature:\n• French science picture books (40)\n• Lifecycle books collection (15)\n• Weather and seasons books (20)\n• Environmental books (15)\n\nDigital Resources:\n• ScienceKids.co.nz\n• Let''s Talk Science resources\n• CBC Kids science videos\n• BrainPOP Jr. (French version)\n\nSafety Resources:\n• STAO Safety in Elementary Science\n• Safe Science Procedures Manual\n• Allergy awareness posters\n• Emergency procedure cards','\n',char(10)),replace('SCIENCE FAMILY ENGAGEMENT:\n\nSafety Communication Priority:\n• Science safety rules sent home for signature\n• Allergy and medical needs form required\n• Outdoor exploration permission forms\n• Photo consent for science documentation\n\nWeekly Updates:\n• Science discovery of the week\n• Home science extension activities\n• Vocabulary in French and English\n• Safety reminders for home experiments\n\nMonthly Programs:\n• Family Science Night (first Thursday)\n• Take-home science kits (safe materials only)\n• Parent volunteer training for field trips\n• Science fair family preparation guide\n\nSeasonal Events:\n• Fall: Nature walk and collection day\n• Winter: Snow science family day\n• Spring: Garden planting celebration\n• Year-end: Science showcase\n\nHome-School Connections:\n• Kitchen science ideas (safe, supervised)\n• Nature observation challenges\n• Weather tracking activities\n• Environmental action projects','\n',char(10)));
INSERT INTO LongRangePlan VALUES('cmebyc98s0007vjr1v0a2ibp5',23,'Social Studies Excellence - Grade 1 French Immersion','2025-2026',NULL,1,'Sciences humaines','A community-centered social studies program exploring identity, citizenship, geography, history, and relationships through developmentally appropriate investigations of family, school, and community contexts, with emphasis on PEI culture and Mi''kmaq heritage.',replace('SPECIFIC MEASURABLE LEARNING GOALS:\n• Students will identify 5 roles and responsibilities in family, school, and community\n• Students will recognize 10 community helpers and their contributions\n• Students will create 3 different types of maps (classroom, school, neighborhood)\n• Students will distinguish between needs and wants with 85% accuracy\n• Students will demonstrate 5 digital citizenship safety rules\n• Students will describe 3 family traditions from different cultures\n• Students will identify 5 ways PEI has changed over time\n• Students will use 25 French social studies vocabulary words appropriately\n• Students will show respect for diversity in 100% of interactions\n• Students will participate in 3 community service projects','\n',char(10)),'[{"month":"Septembre","theme":"Qui suis-je? - My Identity","focus":"Personal identity, uniqueness, belonging","sensitivity":"No pressure to share family details","activities":"Self-portraits, name stories, interest inventories"},{"month":"Octobre","theme":"Ma famille unique - My Unique Family","focus":"Family diversity, roles, traditions","sensitivity":"All family structures validated, optional sharing","activities":"Family trees (flexible format), tradition sharing, helper roles"},{"month":"Novembre","theme":"Notre école communauté - Our School Community","focus":"School roles, responsibilities, belonging","sensitivity":"Include all staff as school family","activities":"School helper interviews, classroom jobs, kindness tracking"},{"month":"Décembre","theme":"Célébrations autour du monde - Global Celebrations","focus":"Cultural diversity, traditions, respect","sensitivity":"Include non-religious winter traditions","activities":"Celebration research, family tradition sharing, light festivals"},{"month":"Janvier","theme":"Ma communauté locale - My Local Community","focus":"Neighborhood, community helpers, services","sensitivity":"Respect for all occupations and contributions","activities":"Community walks, helper thank you cards, service mapping"},{"month":"Février","theme":"L''histoire de ma communauté - Community History","focus":"Past and present, changes over time, heritage","sensitivity":"Include Indigenous history as foundational","activities":"Then/now comparisons, Elder visits, artifact exploration"},{"month":"Mars","theme":"La géographie de l''Î.-P.-É. - PEI Geography","focus":"Maps, landforms, special places","sensitivity":"Acknowledge traditional Mi''kmaq territory","activities":"Map making, virtual island tours, special places project"},{"month":"Avril","theme":"Citoyens numériques - Digital Citizens","focus":"Online safety, digital footprints, kindness online","sensitivity":"Family technology rules respected","activities":"Safety scenarios, digital kindness pledge, avatar creation"},{"month":"Mai","theme":"Besoins et désirs - Needs and Wants","focus":"Economic concepts, resources, sharing","sensitivity":"No judgment on family economic situations","activities":"Needs/wants sorting, classroom economy, sharing circle"},{"month":"Juin","theme":"Être un bon citoyen - Being a Good Citizen","focus":"Rights, responsibilities, making a difference","sensitivity":"Age-appropriate civic engagement","activities":"Kindness projects, school improvement ideas, citizenship certificates"}]',replace('ESSENTIAL QUESTIONS (Identity and Community Focus):\n• Qui suis-je? (Who am I?)\n• Qui est ma famille? (Who is my family?)\n• Où est ma place? (Where do I belong?)\n• Comment vivre ensemble? (How do we live together?)\n• Qu''est-ce qui change? (What changes?)\n• Comment je peux aider? (How can I help?)','\n',char(10)),replace('COMPREHENSIVE ASSESSMENT WITH CRITICAL SAFETY PROTOCOLS:\n\nEMOTIONAL AND FAMILY SAFETY PROTOCOLS (MANDATORY):\n• Family diversity celebrated - no assumptions about family structure\n• Optional sharing only - never force family information disclosure\n• Alternative topics always available for sensitive situations\n• Privacy protection for ALL family matters\n• Trauma-informed approaches required\n• Advanced communication with families about sensitive topics\n• Safe person to talk to identified for each child\n• Confidential reporting system for concerns\n• Cultural sensitivity in all family discussions\n• Digital safety rules strictly enforced\n\nFAMILY SENSITIVITY PROTOCOLS:\n• "Family" defined broadly and inclusively\n• No Mother''s/Father''s Day mandatory activities\n• Foster/adoption situations handled sensitively\n• Separated/divorced family accommodations\n• Grief and loss support available\n• Economic diversity respected\n• LGBTQ+ families explicitly welcomed\n• Multi-generational families honored\n\nFORMATIVE ASSESSMENT (Daily/Weekly):\n• Community circle discussions with sharing protocols\n• Identity portfolio development (student choice items)\n• Map-making progression checks\n• Role-play observations for citizenship\n• Digital citizenship practice scenarios\n• "My Community" ongoing books\n• Respect and kindness tracking\n\nSUMMATIVE ASSESSMENT (Unit/Term):\n• Family celebration projects (structure flexible)\n• Community helper interviews and presentations\n• Personal timeline creation (sensitive to adoption/foster)\n• Map skills demonstrations\n• Digital safety poster creation\n• Heritage sharing (completely optional)\n• Service learning reflections','\n',char(10)),replace('SOCIAL STUDIES RESOURCE REQUIREMENTS:\n\nMapping Resources:\n• Globe and world map\n• PEI maps (various types)\n• Classroom grid maps\n• Compass sets (6)\n• Map puzzles\n• Digital mapping tools access\n\nCultural Resources:\n• Multicultural family books (30)\n• Heritage celebration resources\n• Traditional clothing examples\n• Cultural artifact collection\n• Music from many cultures\n• Food models/pictures\n\nCommunity Study:\n• Community helper costumes\n• Career exploration materials\n• Local business partnerships\n• Field trip permissions\n• Guest speaker coordination\n\nDigital Citizenship:\n• Online safety posters\n• Device models for practice\n• Digital scenario cards\n• Internet safety videos\n• Privacy protection materials\n\nHistorical Resources:\n• Then/now photo collections\n• PEI history materials\n• Mi''kmaq cultural items\n• Timeline materials\n• Heritage trunk borrowing','\n',char(10)),'Deepen Treaty education knowledge. Strengthen anti-bias teaching. Develop community partnerships. Improve inclusive social studies.',NULL,NULL,NULL,'2025-08-14T22:09:29.548Z','2025-08-18T12:45:52.865Z','{"french":["Identity vocabulary development","Family stories in French","Community helper interviews","Map labels in French"],"math":["Timeline number concepts","Map grid coordinates","Graphing family data","Needs/wants sorting and counting"],"science":["Seasonal community changes","Environmental citizenship","Technology then and now","Geographic features study"],"arts":["Cultural art exploration","Family portraits","Community murals","Heritage crafts"],"health":["Family roles in health","Community safety helpers","Emotional well-being","Digital wellness"]}',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'{"criticalTraining":["MANDATORY: Trauma-Informed Teaching - August","Family Diversity and Inclusion - Before September"],"immediateNeeds":["PEI History and Culture - September workshop","Mi''kmaq Cultural Competency - September with Elders"],"termOne":["Digital Citizenship K-2 - October training","Geography Skills for Primary - November","Anti-Bias Education - December workshop"],"termTwo":["Community Partnerships - January","Heritage Fair preparation - February","Global Citizenship - March conference"],"ongoing":["Cultural competency circles monthly","Family engagement strategies PLC","Social justice in primary education study group"]}',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'{"framework":"Inclusive practices honoring all learners and families","strugglingLearners":["Visual supports for all concepts","Simplified maps with fewer elements","Partner support for discussions","Sentence starters for sharing","Concrete role-play opportunities","Modified timeline activities","Picture-based assessments","Extra time for processing"],"advancedLearners":["Research projects on interests","Create resources for class","Lead mapping activities","Interview community members","Compare communities globally","Historical investigation projects","Junior tour guide training","Citizenship action projects"],"englishLanguageLearners":["Native language identity work welcomed","Visual vocabulary for all terms","Cultural sharing celebrated","Translation support available","Picture maps and timelines","Gesture and demonstration","Multicultural resources prioritized","Family involvement encouraged"],"iepStudents":["Social stories for new concepts","Visual schedules for activities","Adapted sharing formats","Sensory considerations for activities","Alternative response methods","Focus on priority concepts","Support personnel collaboration","Individualized success criteria"]}',NULL,NULL,NULL,replace('AUTHENTIC MI''KMAQ INTEGRATION:\n\nFoundational Understanding:\n• PEI is in Mi''kma''ki, traditional Mi''kmaq territory\n• We are all Treaty people with responsibilities\n• Mi''kmaq people are contemporary community members\n• Traditional and modern Mi''kmaq life both valued\n\nMonthly Integration:\n• September: Mi''kmaq identity and belonging teachings\n• October: Mi''kmaq family structures and clan system\n• November: Traditional and contemporary Mi''kmaq education\n• December: Mi''kmaq winter celebrations and stories\n• January: Mi''kmaq community roles and governance\n• February: Mi''kmaq history on PEI (pre-contact to present)\n• March: Traditional place names and land relationships\n• April: Mi''kmaq technology past and present\n• May: Traditional sharing and trade practices\n• June: Seven Sacred Teachings for good citizenship\n\nPartnerships and Resources:\n• Mi''kmaq Confederacy of PEI partnership\n• Elder-in-Residence program participation\n• Lennox Island First Nation connections\n• Abegweit First Nation collaborations\n• Mi''kmaq language integration (greetings, place names)\n• Contemporary Mi''kmaq authors and artists\n• Traditional games and activities\n• Land-based learning experiences','\n',char(10)),replace('SOCIAL STUDIES TEACHING LIBRARY:\n\nProfessional Resources:\n• "Teaching Social Studies in Primary" - Parker\n• "Culturally Responsive Teaching" - Gay\n• "PEI Grade 1 Social Studies Guide"\n• "Mi''kmaq History of PEI" - Augustine\n\nChildren''s Literature:\n• Family diversity books (40)\n• Community helper books (25)\n• PEI-specific books (15)\n• Mi''kmaq stories (20)\n• Geography books (15)\n• Digital citizenship books (10)\n\nCultural Resources:\n• Mi''kmaq Education Resources\n• Newcomer family resources\n• Acadian cultural materials\n• Irish/Scottish PEI heritage\n• Multicultural celebration guides\n\nDigital Resources:\n• Google Earth for virtual tours\n• PEI Archives online\n• Safe websites for research\n• Virtual museum tours\n• Community helper videos','\n',char(10)),replace('FAMILY ENGAGEMENT IN SOCIAL STUDIES:\n\nSensitive Topic Communication:\n• Advanced notice of family-related units\n• Optional participation in family sharing\n• Alternative activities always available\n• Confidential family situation form\n\nWeekly Communication:\n• Social studies focus for the week\n• Vocabulary in French and English\n• Home extension activities (optional)\n• Community connection opportunities\n\nMonthly Programs:\n• Family Heritage Night (optional participation)\n• Community Helper visit coordination\n• Cultural celebration potlucks (inclusive)\n• Walking field trips with family volunteers\n\nAssessment Communication:\n• Portfolio development guides\n• Identity project explanations\n• Digital citizenship family resources\n• Progress in social skills development\n\nFamily Contribution Opportunities:\n• Share career/occupation (all types valued)\n• Cultural tradition sharing (optional)\n• Family artifact lending library\n• Community connection facilitation\n• Heritage language sharing\n• Travel experiences and photos','\n',char(10)));
INSERT INTO LongRangePlan VALUES('cmebyc98v0009vjr16o3e7awo',23,'Visual Arts Excellence - Grade 1 French Immersion','2025-2026',NULL,1,'Arts visuels','A process-focused visual arts program developing creative expression, fine motor skills, cultural appreciation, and artistic vocabulary through exploration of diverse materials, techniques, and artistic traditions, emphasizing joy and confidence in art-making.',replace('SPECIFIC MEASURABLE LEARNING GOALS:\n• Students will explore 10 different art materials and techniques safely\n• Students will create artwork expressing 5 different emotions/ideas\n• Students will use 8 elements of art (line, shape, color, texture) in creations\n• Students will describe their artwork using 20 French art vocabulary words\n• Students will demonstrate proper care of 15 art tools and materials\n• Students will create art inspired by 3 different cultures respectfully\n• Students will participate in 4 collaborative art projects successfully\n• Students will present artwork to others with confidence 3 times\n• Students will observe and discuss 10 works by various artists\n• Students will maintain an art portfolio showing growth over time','\n',char(10)),'[{"month":"Septembre","theme":"Découvrir l''art dans notre monde - Art All Around Us","focus":"Art materials exploration, classroom art, observing","techniques":"Drawing, coloring, cutting, gluing basics","vocabulary":"ligne, forme, couleur, papier, crayon","materials":"Crayons, markers, paper, glue, scissors (safety)"},{"month":"Octobre","theme":"Les couleurs et les sentiments - Colors and Feelings","focus":"Color mixing, emotional expression, autumn art","techniques":"Painting basics, color mixing, brush techniques","vocabulary":"rouge, bleu, jaune, mélanger, pinceau","materials":"Tempera paint, brushes, sponges, paper"},{"month":"Novembre","theme":"Les textures et les motifs - Textures and Patterns","focus":"Texture exploration, pattern creation, printmaking","techniques":"Printing, rubbing, stamping, pattern making","vocabulary":"texture, motif, répéter, empreinte","materials":"Texture plates, stamps, found objects"},{"month":"Décembre","theme":"Les célébrations par l''art - Celebration Art","focus":"Cultural celebrations, gift making, light and shadow","techniques":"Paper crafts, folding, decorating","vocabulary":"décorer, plier, couper, offrir","materials":"Special papers, ribbons, recyclables"},{"month":"Janvier","theme":"Portraits et identité - Portraits and Identity","focus":"Self-portraits, facial features, identity expression","techniques":"Drawing faces, proportions basics, mixed media","vocabulary":"visage, yeux, nez, bouche, autoportrait","materials":"Mirrors, skin-tone materials, collage items"},{"month":"Février","theme":"L''art dans la nature - Art in Nature","focus":"Natural materials, environmental art, seasons","techniques":"Nature collage, land art, observational drawing","vocabulary":"nature, feuille, branche, pierre, naturel","materials":"Natural materials, clay, sand, rocks"},{"month":"Mars","theme":"Sculptures et 3D - Sculptures and 3D Art","focus":"Building, constructing, 3D thinking","techniques":"Clay work, paper sculpture, assemblage","vocabulary":"sculpture, construire, 3D, argile","materials":"Model magic, recyclables, tape, wire"},{"month":"Avril","theme":"Art printanier - Spring Art","focus":"Growth, flowers, new life, outdoor art","techniques":"Watercolor, tissue paper, garden art","vocabulary":"printemps, fleur, pousser, jardin","materials":"Watercolors, tissue paper, chalk"},{"month":"Mai","theme":"Les histoires dans l''art - Stories in Art","focus":"Narrative art, illustration, sequential art","techniques":"Story illustration, comic strips, murals","vocabulary":"histoire, illustrer, personnage, scène","materials":"Various drawing materials, large paper"},{"month":"Juin","theme":"Notre galerie d''art - Our Art Gallery","focus":"Exhibition, curation, celebration, reflection","techniques":"Display techniques, artist statements","vocabulary":"exposition, galerie, artiste, chef-d''œuvre","materials":"Mounting materials, labels, frames"}]',replace('ESSENTIAL QUESTIONS (Process and Joy Focus):\n• Comment je crée? (How do I create?)\n• Qu''est-ce que je vois? (What do I see?)\n• Comment ça me fait sentir? (How does it make me feel?)\n• Qu''est-ce qui est beau? (What is beautiful?)\n• Comment je peux essayer? (How can I try?)\n• Où voit-on l''art? (Where do we see art?)','\n',char(10)),replace('COMPREHENSIVE ASSESSMENT STRATEGY:\n\nPROCESS-FOCUSED APPROACH:\n• Emphasis on exploration and experimentation\n• Growth over time valued more than products\n• All attempts celebrated and documented\n• No comparison between students'' work\n• Risk-taking and creativity encouraged\n\nFORMATIVE ASSESSMENT (Ongoing):\n• Process observations with photo documentation\n• Artist statements (oral for Grade 1)\n• Peer feedback circles (kind comments only)\n• Self-reflection using emoji scales\n• Effort and engagement tracking\n• Problem-solving documentation\n• Material exploration checklists\n\nSUMMATIVE ASSESSMENT (Portfolio-Based):\n• Monthly portfolio additions (student choice)\n• Growth over time documentation\n• Artist of the Month celebrations\n• Family art nights with exhibitions\n• Digital portfolio creation\n• Process videos when possible\n• Collaborative project contributions','\n',char(10)),replace('VISUAL ARTS RESOURCE REQUIREMENTS:\n\nBasic Drawing Materials:\n• Crayons (multiple sets, various sizes)\n• Markers (washable, multiple sets)\n• Pencils (various grades)\n• Erasers (kneaded and regular)\n• Oil pastels (30 sets)\n• Chalk pastels (with fixative)\n\nPainting Supplies:\n• Tempera paint (all colors, gallons)\n• Watercolor sets (30)\n• Brushes (various sizes, 100+)\n• Paint shirts/aprons (30)\n• Water containers (30)\n• Sponges and painting tools\n\nPaper and Surfaces:\n• White drawing paper (reams)\n• Construction paper (all colors)\n• Watercolor paper\n• Cardboard sheets\n• Canvas boards (special projects)\n\n3D Materials:\n• Model Magic/clay\n• Playdough (homemade)\n• Recyclable materials\n• Glue (sticks and liquid)\n• Tape (various types)\n• Wire and string\n\nSafety Equipment:\n• Safety scissors (30)\n• Table coverings\n• Hand wipes\n• Paper towels\n• Soap and sanitizer','\n',char(10)),'Explore process-based art education. Learn traditional Indigenous art forms. Develop inclusive art practices. Strengthen art-literacy connections.',NULL,NULL,NULL,'2025-08-14T22:09:29.551Z','2025-08-19T01:49:42.307Z','{"french":["Art vocabulary development","Describing artwork in French","French artists exploration","Illustrated French stories"],"math":["Geometric shapes in art","Pattern and symmetry","Measuring for art projects","Color mixing ratios"],"science":["Nature art and observation","Color and light science","Seasonal art projects","Material properties exploration"],"socialStudies":["Cultural art traditions","Community art projects","Historical art styles","Identity through art"],"music":["Art inspired by music","Rhythm in visual patterns","Sound and color connections","Performance art basics"]}',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'{"immediateNeeds":["Teaching Artist workshops - August","Process Art for Primary - September"],"termOne":["Fine Motor Development through Art - October","Cultural Arts Integration - November","Adaptive Art for All Learners - December"],"termTwo":["Digital Art Tools K-2 - January","Assessment in Arts - February","Environmental Art - March"],"ongoing":["Local artist partnerships","Confederation Centre education programs","Art Gallery of PEI collaborations","Online art education courses"],"resources":["Deep Space Sparkle blog","Art for Kids Hub videos","Cassie Stephens art teaching"]}',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'{"framework":"Multi-sensory approaches with adapted tools","strugglingLearners":["Adapted grip tools for fine motor challenges","Larger materials for easier manipulation","Step-by-step visual instructions","Partner support for challenging techniques","Extended time for completion","Simplified versions of projects","Hand-over-hand support when needed","Choice in materials and techniques"],"advancedLearners":["Additional technique challenges","Mixed media explorations","Artist research projects","Peer teaching opportunities","Gallery curator roles","Advanced tool introduction","Personal art challenges","Art journal maintenance"],"englishLanguageLearners":["Visual vocabulary cards for all terms","Demonstration before explanation","Native language art discussions welcomed","Picture instructions for techniques","Partner translations during sharing","Cultural art connections celebrated","Gesture and showing encouraged","Art speaks when words cannot"],"iepStudents":["Sensory-friendly material alternatives","Weighted tools for proprioception","Visual schedules for art activities","Calm-down art corner available","Modified expectations per IEP","Alternative art mediums (digital)","Support staff collaboration","Therapeutic art approaches"]}',NULL,NULL,NULL,replace('AUTHENTIC INDIGENOUS ART INTEGRATION:\n\nMi''kmaq Artistic Traditions:\n• Beadwork patterns and designs (visual only for Grade 1)\n• Birchbark art and etching traditions\n• Traditional clothing and regalia appreciation\n• Petroglyphs and rock art study\n• Contemporary Mi''kmaq artists showcase\n• Quillwork designs and patterns\n\nSafety with Cultural Materials:\n• Visual appreciation only for delicate items\n• Reproductions used for hands-on exploration\n• Elder guidance for cultural appropriateness\n• Respectful representation always emphasized\n\nMonthly Integration:\n• September: Mi''kmaq patterns in nature\n• October: Traditional autumn art and colors\n• November: Beadwork pattern exploration\n• December: Star designs and winter art\n• January: Traditional portrait styles\n• February: Natural materials in Mi''kmaq art\n• March: Basket weaving patterns (paper weaving)\n• April: Spring symbols in Mi''kmaq art\n• May: Story rocks and pictographs\n• June: Celebration regalia appreciation\n\nContemporary Connections:\n• Alan Syliboy artwork exploration\n• Loretta Gould illustrations\n• Local Mi''kmaq artist visits\n• Confederation Centre Indigenous exhibitions','\n',char(10)),replace('ART EDUCATION RESOURCES:\n\nProfessional Books:\n• "First Steps in Art" - MaryAnn Kohl\n• "Process Art for Preschoolers" - Megan Schiller\n• "L''art à la maternelle" - Sophie Bonnet\n• "Anti-Bias Art Activities" - Tomas\n\nChildren''s Art Books:\n• Artist biography picture books (25)\n• How-to-draw books (15)\n• Art technique books (20)\n• Cultural art books (20)\n• Museum collection books (10)\n\nArtist Resources:\n• Art print collection (50+)\n• Artist postcards\n• Virtual museum access\n• Local artist connections\n• Indigenous art resources\n\nDigital Resources:\n• Art Hub for Kids\n• Deep Space Sparkle\n• NGA Kids Zone\n• Tate Kids\n• Chrome Music Lab (for sound art)','\n',char(10)),replace('VISUAL ARTS FAMILY ENGAGEMENT:\n\nMaterials Safety Communication:\n• Art materials list with safety notes\n• Allergy alert for art supplies\n• Clothing protection reminders\n• Safe storage of art materials at home\n\nWeekly Updates:\n• Art technique of the week\n• Home art extension ideas\n• Artist spotlight information\n• Process photos shared (with consent)\n\nMonthly Programs:\n• Family Art Night (third Wednesday)\n• Take-home art kits (monthly)\n• Parent volunteer art assistants\n• Gallery walk preparations\n\nExhibition Communications:\n• Portfolio development updates\n• Artist statement preparations\n• Exhibition invitation designs\n• Digital gallery access\n\nHome Art Support:\n• Simple art activities list\n• Recycled materials requests\n• Nature collection opportunities\n• Kitchen art suggestions\n• Screen-free art challenges\n• Summer art ideas calendar','\n',char(10)));
INSERT INTO LongRangePlan VALUES('cmebyc98x000bvjr1finmuibw',23,'Personal and Social Development Excellence - Grade 1 French Immersion','2025-2026',NULL,1,'Formation personnelle et sociale','A comprehensive wellness program fostering emotional literacy, physical health, safety awareness, positive relationships, and self-regulation through developmentally appropriate, trauma-informed practices that honor the whole child and celebrate growth.',replace('SPECIFIC MEASURABLE LEARNING GOALS:\n• Students will identify and name 5 basic emotions using emoji scales by December\n• Students will demonstrate 3 calm-down strategies independently by March\n• Students will practice 10 personal hygiene habits correctly with 90% consistency\n• Students will identify 5 trusted adults in their safety network\n• Students will use 4 conflict resolution steps with peer support\n• Students will recognize 8 body safety rules and boundaries\n• Students will demonstrate kindness in 95% of peer interactions\n• Students will identify healthy vs unhealthy foods with 85% accuracy\n• Students will participate in 15 minutes of physical activity daily\n• Students will express personal strengths and challenges appropriately','\n',char(10)),'[{"month":"Septembre","theme":"Moi, moi-même et je - Understanding Myself","focus":"Self-awareness, emotions, uniqueness","sevenTeachings":"RESPECT - Respecting ourselves","safety":"Personal space and body boundaries"},{"month":"Octobre","theme":"Mes émotions - My Feelings","focus":"Emotion identification, expression, regulation","sevenTeachings":"WISDOM - Understanding our feelings","safety":"It''s okay to feel all emotions"},{"month":"Novembre","theme":"Mon corps en santé - My Healthy Body","focus":"Hygiene, nutrition, exercise, sleep","sevenTeachings":"LOVE - Loving our bodies","safety":"Body safety and privacy rules"},{"month":"Décembre","theme":"Sain et sauf - Safe and Sound","focus":"Safety rules, trusted adults, emergency procedures","sevenTeachings":"COURAGE - Being brave to stay safe","safety":"Stranger danger, online safety basics"},{"month":"Janvier","theme":"Amis et sentiments - Friends and Feelings","focus":"Friendship skills, empathy, conflict resolution","sevenTeachings":"HONESTY - True friendship","safety":"Consent in play and friendships"},{"month":"Février","theme":"La gentillesse compte - Kindness Matters","focus":"Acts of kindness, inclusion, anti-bullying","sevenTeachings":"HUMILITY - Helping others","safety":"Standing up against meanness safely"},{"month":"Mars","theme":"Gérer mes défis - Managing Challenges","focus":"Problem-solving, resilience, asking for help","sevenTeachings":"TRUTH - Being honest about struggles","safety":"When and how to ask for help"},{"month":"Avril","theme":"Grandir et apprendre - Growing and Learning","focus":"Growth mindset, celebrating progress, goals","sevenTeachings":"All Seven Teachings Review","safety":"Safe risk-taking in learning"},{"month":"Mai","theme":"Ma communauté de soutien - My Support Community","focus":"Helpers, gratitude, contributing","sevenTeachings":"Community and connection","safety":"Community safety helpers"},{"month":"Juin","theme":"Célébrer notre voyage - Celebrating Our Journey","focus":"Reflection, growth, summer wellness","sevenTeachings":"Celebration of all teachings","safety":"Summer safety preparation"}]',replace('ESSENTIAL QUESTIONS (Wellness and Safety Focus):\n• Comment je me sens? (How do I feel?)\n• Qui peut m''aider? (Who can help me?)\n• Comment rester en sécurité? (How to stay safe?)\n• Qu''est-ce qui est sain? (What is healthy?)\n• Comment être gentil? (How to be kind?)\n• Pourquoi je suis spécial? (Why am I special?)','\n',char(10)),replace('COMPREHENSIVE WELLNESS ASSESSMENT:\n\nEMOTIONAL SAFETY PROTOCOLS:\n• Private feelings check-ins (not public sharing)\n• Choice in sharing personal information\n• Alternative expressions (art, movement, writing)\n• Trauma-informed observation practices\n• Confidential concern reporting system\n• Regular wellness surveys (emoji-based)\n• Family communication about sensitive topics\n\nFORMATIVE ASSESSMENT (Daily/Weekly):\n• Emotion check-in circles (voluntary sharing)\n• Calm-down strategy observations\n• Kindness tracking (caught being kind)\n• Physical activity participation logs\n• Healthy choices documentation\n• Safety rule demonstrations\n• Self-regulation progress notes\n\nSUMMATIVE ASSESSMENT (Term):\n• Personal wellness portfolio\n• Safety knowledge demonstrations\n• Friendship skills role-play\n• Healthy habits self-assessment\n• Growth celebration conferences\n• Family wellness projects (optional)\n• Digital wellness poster creation','\n',char(10)),replace('WELLNESS PROGRAM RESOURCES:\n\nEmotional Regulation:\n• Feelings posters and cards (French/English)\n• Calm-down kit materials\n• Zones of Regulation resources\n• Mindfulness bells and timers\n• Emotion thermometers\n• Breathing exercise visuals\n\nPhysical Health:\n• Hand washing posters\n• Healthy food models\n• Exercise equipment (age-appropriate)\n• First aid demonstration materials\n• Body outline posters\n• Hygiene supplies\n\nSafety Education:\n• Body safety teaching dolls\n• Trusted adult network templates\n• Safety scenario cards\n• Emergency procedure visuals\n• Digital safety materials\n• Stranger danger resources\n\nBooks and Media:\n• Feelings books collection (30)\n• Body safety books (10)\n• Friendship books (20)\n• Health and wellness books (15)\n• Mindfulness books (10)\n\nSensory Support:\n• Fidget tools\n• Weighted lap pads\n• Noise-reducing headphones\n• Calm-down bottles\n• Stress balls\n• Texture materials','\n',char(10)),'Strengthen trauma-informed practices. Develop mindfulness teaching. Improve social-emotional learning. Enhance inclusive wellness education.',NULL,NULL,NULL,'2025-08-14T22:09:29.553Z','2025-08-19T02:38:10.576Z','{"Fran\u00e7ais (Immersion)": "Social vocabulary, feelings journal, communication skills, story sharing", "Math\u00e9matiques": "Growth charts, fair sharing problems, time management, wellness tracking", "Sciences de la nature": "Body systems, health habits, environmental wellness, nature and wellbeing", "Sciences humaines": "Community roles, citizenship, cultural identity, social responsibility", "Arts visuels": "Identity expression through art, emotion in color, self-portraits, feelings collage"}',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'{"mandatory":["Trauma-Informed Teaching Certificate - August mandatory","Mental Health First Aid for Children - September required","Body Safety Education Training - Before October"],"termOne":["Social-Emotional Learning Strategies - October PD day","Zones of Regulation Training - November workshop","Mindfulness for Children - December online course"],"termTwo":["Restorative Justice Circles - January training","Anti-Bullying Strategies - February conference","Inclusive Health Education - March workshop"],"ongoing":["Monthly wellness team meetings","School counselor collaboration weekly","Public Health nurse consultations","Family wellness workshop facilitation"]}',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'{"framework":"Trauma-informed, inclusive wellness education","strugglingLearners":["Visual emotion cards for expression","Simplified safety rules with pictures","Partner support for activities","Modified physical activities","Extra time for emotional processing","Sensory tools for regulation","One-on-one check-ins","Alternative calm-down spaces"],"advancedLearners":["Peer helper roles","Emotion coaching for others","Wellness ambassador duties","Create resources for class","Lead physical activities","Research health topics","Mentor younger students","Family wellness projects"],"englishLanguageLearners":["Emotion words in multiple languages","Visual safety demonstrations","Cultural health practices welcomed","Translation for key concepts","Picture-based assessments","Family involvement encouraged","Gesture and movement communication","Multilingual wellness resources"],"iepStudents":["Individualized wellness goals","Sensory accommodations","Alternative regulation strategies","Modified physical activities","Visual schedules for routines","Quiet space availability","Support personnel collaboration","Adapted assessment methods"]}',NULL,NULL,NULL,replace('MI''KMAQ WELLNESS TEACHINGS:\n\nSeven Sacred Teachings Integration:\n• RESPECT (Septembre) - Respecting ourselves and others\n• WISDOM (Octobre) - Understanding emotions and needs  \n• LOVE (Novembre) - Caring for our bodies and hearts\n• COURAGE (Décembre) - Being brave to stay safe\n• HONESTY (Janvier) - True friendship and trust\n• HUMILITY (Mars) - Helping others and asking for help\n• TRUTH (Avril) - Being true to ourselves\n\nMedicine Wheel Teachings:\n• Physical wellness (East - Spring) - Body health\n• Emotional wellness (South - Summer) - Feelings\n• Mental wellness (West - Fall) - Learning and growth\n• Spiritual wellness (North - Winter) - Connection\n\nMonthly Elder Wisdom:\n• September: Identity and belonging teachings\n• October: Emotional balance from nature\n• November: Traditional health practices (observation)\n• December: Winter safety wisdom\n• January: Community and relationships\n• February: Kindness in Mi''kmaq culture\n• March: Resilience teachings from stories\n• April: Growth and renewal\n• May: Gratitude practices\n• June: Celebration and reflection\n\nResources:\n• Elder visits for wellness teachings\n• Smudging demonstrations (optional participation)\n• Traditional games for physical wellness\n• Story-based social teachings','\n',char(10)),'{"emotionalRegulation":"Emotion identification charts and feeling wheels; calming strategies posters and visual guides","socialSkills":"Friendship and conflict resolution visual guides; communication skills posters and role-play materials","safetyWellness":"Personal safety books and educational materials; community helper identification and contact information","mindfulness":"Age-appropriate meditation and relaxation resources; gratitude journals and appreciation activities","culturalFamily":"Books representing diverse family structures and cultural traditions; materials supporting various religious and spiritual practices"}',replace('FAMILY WELLNESS PARTNERSHIP:\n\nSensitive Topic Communication:\n• Advanced notice of body safety units\n• Opt-out options for sensitive topics\n• Alternative activities always available\n• Confidential family situation forms\n• Trauma-informed communication\n• Mental health resources provided\n\nWeekly Wellness Updates:\n• Emotion of the week exploration\n• Wellness tips for families\n• Home practice suggestions (optional)\n• Celebration of growth moments\n\nMonthly Programs:\n• Family Wellness Night (first Monday)\n• Parent wellness workshops (optional)\n• Community health nurse visits\n• Counselor coffee chats\n\nSafety Communication Priority:\n• Body safety rules sent home\n• Trusted adult network building\n• Online safety family guide\n• Emergency procedure practice\n• Consent education materials\n\nResources for Families:\n• Emotion coaching strategies\n• Calm-down techniques for home\n• Healthy snack ideas\n• Physical activity suggestions\n• Book recommendations for feelings\n• Crisis support numbers\n• Summer wellness calendar','\n',char(10)));
