PRAGMA foreign_keys=OFF;
BEGIN TRANSACTION;
CREATE TABLE IF NOT EXISTS "_prisma_migrations" (
    "id"                    TEXT PRIMARY KEY NOT NULL,
    "checksum"              TEXT NOT NULL,
    "finished_at"           DATETIME,
    "migration_name"        TEXT NOT NULL,
    "logs"                  TEXT,
    "rolled_back_at"        DATETIME,
    "started_at"            DATETIME NOT NULL DEFAULT current_timestamp,
    "applied_steps_count"   INTEGER UNSIGNED NOT NULL DEFAULT 0
);
CREATE TABLE IF NOT EXISTS "Subject" (
    "id" INTEGER NOT NULL PRIMARY KEY AUTOINCREMENT,
    "name" TEXT NOT NULL,
    "userId" INTEGER,
    "createdAt" DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP, "nameEn" TEXT, "nameFr" TEXT,
    CONSTRAINT "Subject_userId_fkey" FOREIGN KEY ("userId") REFERENCES "User" ("id") ON DELETE SET NULL ON UPDATE CASCADE
);
CREATE TABLE IF NOT EXISTS "CalendarEvent" (
    "id" INTEGER NOT NULL PRIMARY KEY AUTOINCREMENT,
    "title" TEXT NOT NULL,
    "description" TEXT,
    "start" DATETIME NOT NULL,
    "end" DATETIME NOT NULL,
    "allDay" BOOLEAN NOT NULL DEFAULT false,
    "eventType" TEXT NOT NULL,
    "source" TEXT NOT NULL DEFAULT 'MANUAL',
    "teacherId" INTEGER,
    "schoolId" INTEGER,
    "createdAt" DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
    "updatedAt" DATETIME NOT NULL,
    CONSTRAINT "CalendarEvent_teacherId_fkey" FOREIGN KEY ("teacherId") REFERENCES "User" ("id") ON DELETE SET NULL ON UPDATE CASCADE
);
CREATE TABLE IF NOT EXISTS "User" (
    "id" INTEGER NOT NULL PRIMARY KEY AUTOINCREMENT,
    "email" TEXT NOT NULL,
    "password" TEXT NOT NULL,
    "name" TEXT NOT NULL,
    "role" TEXT NOT NULL DEFAULT 'teacher',
    "preferredLanguage" TEXT NOT NULL DEFAULT 'en'
, "grade" TEXT, "program" TEXT);
CREATE TABLE IF NOT EXISTS "ClassRoutine" (
    "id" INTEGER NOT NULL PRIMARY KEY AUTOINCREMENT,
    "userId" INTEGER NOT NULL,
    "title" TEXT NOT NULL,
    "description" TEXT NOT NULL,
    "category" TEXT NOT NULL,
    "timeOfDay" TEXT,
    "priority" INTEGER NOT NULL DEFAULT 0,
    "isActive" BOOLEAN NOT NULL DEFAULT true,
    "createdAt" DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
    "updatedAt" DATETIME NOT NULL,
    CONSTRAINT "ClassRoutine_userId_fkey" FOREIGN KEY ("userId") REFERENCES "User" ("id") ON DELETE RESTRICT ON UPDATE CASCADE
);
CREATE TABLE IF NOT EXISTS "CurriculumImport" (
    "id" TEXT NOT NULL PRIMARY KEY,
    "userId" INTEGER NOT NULL,
    "filename" TEXT,
    "originalName" TEXT,
    "mimeType" TEXT,
    "fileSize" INTEGER,
    "filePath" TEXT,
    "grade" INTEGER,
    "subject" TEXT,
    "status" TEXT NOT NULL DEFAULT 'UPLOADING',
    "sourceFormat" TEXT,
    "sourceFile" TEXT,
    "rawText" TEXT,
    "parsedData" TEXT,
    "errorMessage" TEXT,
    "totalOutcomes" INTEGER NOT NULL DEFAULT 0,
    "processedOutcomes" INTEGER NOT NULL DEFAULT 0,
    "errorLog" JSONB,
    "metadata" JSONB,
    "processedAt" DATETIME,
    "createdAt" DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
    "updatedAt" DATETIME NOT NULL,
    "completedAt" DATETIME,
    CONSTRAINT "CurriculumImport_userId_fkey" FOREIGN KEY ("userId") REFERENCES "User" ("id") ON DELETE RESTRICT ON UPDATE CASCADE
);
CREATE TABLE IF NOT EXISTS "ExpectationCluster" (
    "id" TEXT NOT NULL PRIMARY KEY,
    "importId" TEXT NOT NULL,
    "clusterName" TEXT NOT NULL,
    "clusterType" TEXT NOT NULL,
    "expectationIds" JSONB NOT NULL,
    "centroid" JSONB,
    "confidence" REAL NOT NULL DEFAULT 0.0,
    "suggestedTheme" TEXT,
    "metadata" JSONB,
    "createdAt" DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
    CONSTRAINT "ExpectationCluster_importId_fkey" FOREIGN KEY ("importId") REFERENCES "CurriculumImport" ("id") ON DELETE CASCADE ON UPDATE CASCADE
);
CREATE TABLE IF NOT EXISTS "CurriculumExpectation" (
    "id" TEXT NOT NULL PRIMARY KEY,
    "code" TEXT NOT NULL,
    "description" TEXT NOT NULL,
    "strand" TEXT NOT NULL,
    "substrand" TEXT,
    "grade" INTEGER NOT NULL,
    "subject" TEXT NOT NULL,
    "descriptionFr" TEXT,
    "strandFr" TEXT,
    "substrandFr" TEXT,
    "importId" TEXT,
    "createdAt" DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
    "updatedAt" DATETIME NOT NULL, "title" TEXT, "titleFr" TEXT,
    CONSTRAINT "CurriculumExpectation_importId_fkey" FOREIGN KEY ("importId") REFERENCES "CurriculumImport" ("id") ON DELETE SET NULL ON UPDATE CASCADE
);
CREATE TABLE IF NOT EXISTS "CurriculumExpectationEmbedding" (
    "id" TEXT NOT NULL PRIMARY KEY,
    "expectationId" TEXT NOT NULL,
    "embedding" JSONB NOT NULL,
    "model" TEXT NOT NULL,
    "createdAt" DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
    "updatedAt" DATETIME NOT NULL,
    CONSTRAINT "CurriculumExpectationEmbedding_expectationId_fkey" FOREIGN KEY ("expectationId") REFERENCES "CurriculumExpectation" ("id") ON DELETE CASCADE ON UPDATE CASCADE
);
CREATE TABLE IF NOT EXISTS "ExternalActivity" (
    "id" TEXT NOT NULL PRIMARY KEY,
    "externalId" TEXT NOT NULL,
    "source" TEXT NOT NULL,
    "url" TEXT NOT NULL,
    "title" TEXT NOT NULL,
    "description" TEXT,
    "thumbnailUrl" TEXT,
    "duration" INTEGER,
    "activityType" TEXT NOT NULL,
    "gradeMin" INTEGER NOT NULL,
    "gradeMax" INTEGER NOT NULL,
    "subject" TEXT NOT NULL,
    "language" TEXT NOT NULL DEFAULT 'en',
    "materials" JSONB NOT NULL,
    "technology" JSONB,
    "groupSize" TEXT,
    "sourceRating" REAL,
    "sourceReviews" INTEGER,
    "internalRating" REAL,
    "internalReviews" INTEGER,
    "curriculumTags" JSONB NOT NULL,
    "learningGoals" JSONB,
    "isFree" BOOLEAN NOT NULL DEFAULT true,
    "price" REAL,
    "license" TEXT,
    "lastVerified" DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
    "isActive" BOOLEAN NOT NULL DEFAULT true,
    "createdAt" DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
    "updatedAt" DATETIME NOT NULL
);
CREATE TABLE IF NOT EXISTS "ActivityImport" (
    "id" TEXT NOT NULL PRIMARY KEY,
    "userId" INTEGER NOT NULL,
    "activityId" TEXT NOT NULL,
    "lessonPlanId" TEXT,
    "lessonSection" TEXT,
    "customizations" JSONB,
    "notes" TEXT,
    "timesUsed" INTEGER NOT NULL DEFAULT 1,
    "lastUsed" DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
    "effectiveness" INTEGER,
    "createdAt" DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
    CONSTRAINT "ActivityImport_userId_fkey" FOREIGN KEY ("userId") REFERENCES "User" ("id") ON DELETE RESTRICT ON UPDATE CASCADE,
    CONSTRAINT "ActivityImport_activityId_fkey" FOREIGN KEY ("activityId") REFERENCES "ExternalActivity" ("id") ON DELETE RESTRICT ON UPDATE CASCADE,
    CONSTRAINT "ActivityImport_lessonPlanId_fkey" FOREIGN KEY ("lessonPlanId") REFERENCES "ETFOLessonPlan" ("id") ON DELETE SET NULL ON UPDATE CASCADE
);
CREATE TABLE IF NOT EXISTS "ActivityRating" (
    "id" TEXT NOT NULL PRIMARY KEY,
    "userId" INTEGER NOT NULL,
    "activityId" TEXT NOT NULL,
    "rating" INTEGER NOT NULL,
    "review" TEXT,
    "wouldRecommend" BOOLEAN,
    "gradeUsed" INTEGER,
    "subjectUsed" TEXT,
    "workedWell" TEXT,
    "challenges" TEXT,
    "createdAt" DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
    CONSTRAINT "ActivityRating_userId_fkey" FOREIGN KEY ("userId") REFERENCES "User" ("id") ON DELETE RESTRICT ON UPDATE CASCADE,
    CONSTRAINT "ActivityRating_activityId_fkey" FOREIGN KEY ("activityId") REFERENCES "ExternalActivity" ("id") ON DELETE RESTRICT ON UPDATE CASCADE
);
CREATE TABLE IF NOT EXISTS "ActivityCollectionItem" (
    "collectionId" TEXT NOT NULL,
    "activityId" TEXT NOT NULL,
    "addedAt" DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,

    PRIMARY KEY ("collectionId", "activityId"),
    CONSTRAINT "ActivityCollectionItem_collectionId_fkey" FOREIGN KEY ("collectionId") REFERENCES "ActivityCollection" ("id") ON DELETE CASCADE ON UPDATE CASCADE,
    CONSTRAINT "ActivityCollectionItem_activityId_fkey" FOREIGN KEY ("activityId") REFERENCES "ExternalActivity" ("id") ON DELETE CASCADE ON UPDATE CASCADE
);
CREATE TABLE IF NOT EXISTS "WeeklyPlannerState" (
    "id" TEXT NOT NULL PRIMARY KEY,
    "userId" INTEGER NOT NULL,
    "defaultView" TEXT NOT NULL DEFAULT 'week',
    "timeSlotDuration" INTEGER NOT NULL DEFAULT 30,
    "showWeekends" BOOLEAN NOT NULL DEFAULT false,
    "startOfWeek" INTEGER NOT NULL DEFAULT 1,
    "workingHours" TEXT NOT NULL DEFAULT '{"start":"08:00","end":"16:00"}',
    "sidebarExpanded" BOOLEAN NOT NULL DEFAULT true,
    "showMiniCalendar" BOOLEAN NOT NULL DEFAULT true,
    "showResourcePanel" BOOLEAN NOT NULL DEFAULT true,
    "compactMode" BOOLEAN NOT NULL DEFAULT false,
    "theme" TEXT NOT NULL DEFAULT 'light',
    "autoSave" BOOLEAN NOT NULL DEFAULT true,
    "autoSaveInterval" INTEGER NOT NULL DEFAULT 30,
    "showUncoveredOutcomes" BOOLEAN NOT NULL DEFAULT true,
    "defaultLessonDuration" INTEGER NOT NULL DEFAULT 60,
    "currentWeekStart" DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
    "lastActiveView" TEXT,
    "draftChanges" TEXT,
    "undoHistory" TEXT NOT NULL DEFAULT '[]',
    "redoHistory" TEXT NOT NULL DEFAULT '[]',
    "maxHistorySize" INTEGER NOT NULL DEFAULT 50,
    "lastSyncedAt" DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
    "hasOfflineChanges" BOOLEAN NOT NULL DEFAULT false,
    "offlineData" TEXT,
    "createdAt" DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
    "updatedAt" DATETIME NOT NULL,
    CONSTRAINT "WeeklyPlannerState_userId_fkey" FOREIGN KEY ("userId") REFERENCES "User" ("id") ON DELETE CASCADE ON UPDATE CASCADE
);
CREATE TABLE IF NOT EXISTS "TemplateRating" (
    "id" TEXT NOT NULL PRIMARY KEY,
    "templateId" TEXT NOT NULL,
    "userId" INTEGER NOT NULL,
    "rating" INTEGER NOT NULL,
    "comment" TEXT,
    "createdAt" DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
    CONSTRAINT "TemplateRating_templateId_fkey" FOREIGN KEY ("templateId") REFERENCES "PlanTemplate" ("id") ON DELETE CASCADE ON UPDATE CASCADE
);
CREATE TABLE IF NOT EXISTS "TemplateVariation" (
    "id" TEXT NOT NULL PRIMARY KEY,
    "templateId" TEXT NOT NULL,
    "name" TEXT NOT NULL,
    "nameFr" TEXT,
    "description" TEXT,
    "modificationNotes" TEXT,
    "content" JSONB NOT NULL,
    "createdAt" DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
    CONSTRAINT "TemplateVariation_templateId_fkey" FOREIGN KEY ("templateId") REFERENCES "PlanTemplate" ("id") ON DELETE CASCADE ON UPDATE CASCADE
);
CREATE TABLE IF NOT EXISTS "DaybookEntryExpectation" (
    "daybookEntryId" TEXT NOT NULL,
    "expectationId" TEXT NOT NULL,
    "coverage" TEXT,

    PRIMARY KEY ("daybookEntryId", "expectationId"),
    CONSTRAINT "DaybookEntryExpectation_daybookEntryId_fkey" FOREIGN KEY ("daybookEntryId") REFERENCES "DaybookEntry" ("id") ON DELETE CASCADE ON UPDATE CASCADE,
    CONSTRAINT "DaybookEntryExpectation_expectationId_fkey" FOREIGN KEY ("expectationId") REFERENCES "CurriculumExpectation" ("id") ON DELETE CASCADE ON UPDATE CASCADE
);
CREATE TABLE IF NOT EXISTS "ETFOLessonPlanExpectation" (
    "lessonPlanId" TEXT NOT NULL,
    "expectationId" TEXT NOT NULL,

    PRIMARY KEY ("lessonPlanId", "expectationId"),
    CONSTRAINT "ETFOLessonPlanExpectation_lessonPlanId_fkey" FOREIGN KEY ("lessonPlanId") REFERENCES "ETFOLessonPlan" ("id") ON DELETE CASCADE ON UPDATE CASCADE,
    CONSTRAINT "ETFOLessonPlanExpectation_expectationId_fkey" FOREIGN KEY ("expectationId") REFERENCES "CurriculumExpectation" ("id") ON DELETE CASCADE ON UPDATE CASCADE
);
CREATE TABLE IF NOT EXISTS "LongRangePlanExpectation" (
    "longRangePlanId" TEXT NOT NULL,
    "expectationId" TEXT NOT NULL,
    "plannedTerm" TEXT,

    PRIMARY KEY ("longRangePlanId", "expectationId"),
    CONSTRAINT "LongRangePlanExpectation_longRangePlanId_fkey" FOREIGN KEY ("longRangePlanId") REFERENCES "LongRangePlan" ("id") ON DELETE CASCADE ON UPDATE CASCADE,
    CONSTRAINT "LongRangePlanExpectation_expectationId_fkey" FOREIGN KEY ("expectationId") REFERENCES "CurriculumExpectation" ("id") ON DELETE CASCADE ON UPDATE CASCADE
);
CREATE TABLE IF NOT EXISTS "UnitPlanExpectation" (
    "unitPlanId" TEXT NOT NULL,
    "expectationId" TEXT NOT NULL,

    PRIMARY KEY ("unitPlanId", "expectationId"),
    CONSTRAINT "UnitPlanExpectation_unitPlanId_fkey" FOREIGN KEY ("unitPlanId") REFERENCES "UnitPlan" ("id") ON DELETE CASCADE ON UPDATE CASCADE,
    CONSTRAINT "UnitPlanExpectation_expectationId_fkey" FOREIGN KEY ("expectationId") REFERENCES "CurriculumExpectation" ("id") ON DELETE CASCADE ON UPDATE CASCADE
);
CREATE TABLE IF NOT EXISTS "RecentPlanAccess" (
    "id" TEXT NOT NULL PRIMARY KEY,
    "userId" INTEGER NOT NULL,
    "planType" TEXT NOT NULL,
    "planId" TEXT NOT NULL,
    "lastAccessed" DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
    "accessCount" INTEGER NOT NULL DEFAULT 1,
    "createdAt" DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
    "updatedAt" DATETIME NOT NULL,
    CONSTRAINT "RecentPlanAccess_userId_fkey" FOREIGN KEY ("userId") REFERENCES "User" ("id") ON DELETE CASCADE ON UPDATE CASCADE
);
CREATE TABLE IF NOT EXISTS "UnavailableBlock" (
    "id" INTEGER NOT NULL PRIMARY KEY AUTOINCREMENT,
    "teacherId" INTEGER,
    "date" DATETIME NOT NULL,
    "startMin" INTEGER NOT NULL,
    "endMin" INTEGER NOT NULL,
    "reason" TEXT NOT NULL,
    "blockType" TEXT NOT NULL,
    "createdAt" DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
    "updatedAt" DATETIME NOT NULL,
    CONSTRAINT "UnavailableBlock_teacherId_fkey" FOREIGN KEY ("teacherId") REFERENCES "User" ("id") ON DELETE SET NULL ON UPDATE CASCADE
);
CREATE TABLE IF NOT EXISTS "ClassroomAnnouncement" (
    "id" INTEGER NOT NULL PRIMARY KEY AUTOINCREMENT,
    "userId" INTEGER NOT NULL,
    "title" TEXT NOT NULL,
    "timeframe" TEXT NOT NULL,
    "contentFr" TEXT NOT NULL,
    "contentEn" TEXT NOT NULL,
    "createdAt" DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
    "updatedAt" DATETIME NOT NULL,
    CONSTRAINT "ClassroomAnnouncement_userId_fkey" FOREIGN KEY ("userId") REFERENCES "User" ("id") ON DELETE RESTRICT ON UPDATE CASCADE
);
CREATE TABLE IF NOT EXISTS "ActivityCollection" (
    "id" TEXT NOT NULL PRIMARY KEY,
    "userId" INTEGER NOT NULL,
    "name" TEXT NOT NULL,
    "description" TEXT,
    "createdAt" DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
    "updatedAt" DATETIME NOT NULL,
    CONSTRAINT "ActivityCollection_userId_fkey" FOREIGN KEY ("userId") REFERENCES "User" ("id") ON DELETE RESTRICT ON UPDATE CASCADE
);
CREATE TABLE IF NOT EXISTS "PlanTemplate" (
    "id" TEXT NOT NULL PRIMARY KEY,
    "title" TEXT NOT NULL,
    "titleFr" TEXT,
    "description" TEXT,
    "descriptionFr" TEXT,
    "type" TEXT NOT NULL,
    "category" TEXT NOT NULL,
    "subject" TEXT,
    "gradeMin" INTEGER,
    "gradeMax" INTEGER,
    "tags" JSONB NOT NULL,
    "keywords" JSONB NOT NULL,
    "isSystem" BOOLEAN NOT NULL DEFAULT false,
    "createdByUserId" INTEGER,
    "content" JSONB NOT NULL,
    "estimatedWeeks" INTEGER,
    "unitStructure" JSONB,
    "estimatedMinutes" INTEGER,
    "lessonStructure" JSONB,
    "usageCount" INTEGER NOT NULL DEFAULT 0,
    "lastUsedAt" DATETIME,
    "averageRating" REAL DEFAULT 0,
    "createdAt" DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
    "updatedAt" DATETIME NOT NULL,
    CONSTRAINT "PlanTemplate_createdByUserId_fkey" FOREIGN KEY ("createdByUserId") REFERENCES "User" ("id") ON DELETE SET NULL ON UPDATE CASCADE
);
CREATE TABLE IF NOT EXISTS "DaybookEntry" (
    "id" TEXT NOT NULL PRIMARY KEY,
    "userId" INTEGER NOT NULL,
    "date" DATETIME NOT NULL,
    "lessonPlanId" TEXT,
    "whatWorked" TEXT,
    "whatDidntWork" TEXT,
    "nextSteps" TEXT,
    "classEngagement" TEXT,
    "commonChallenges" TEXT,
    "notableAchievements" TEXT,
    "notes" TEXT,
    "privateNotes" TEXT,
    "whatWorkedFr" TEXT,
    "whatDidntWorkFr" TEXT,
    "nextStepsFr" TEXT,
    "notesFr" TEXT,
    "overallRating" INTEGER,
    "wouldReuseLesson" BOOLEAN,
    "createdAt" DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
    "updatedAt" DATETIME NOT NULL,
    CONSTRAINT "DaybookEntry_userId_fkey" FOREIGN KEY ("userId") REFERENCES "User" ("id") ON DELETE RESTRICT ON UPDATE CASCADE,
    CONSTRAINT "DaybookEntry_lessonPlanId_fkey" FOREIGN KEY ("lessonPlanId") REFERENCES "ETFOLessonPlan" ("id") ON DELETE SET NULL ON UPDATE CASCADE
);
CREATE TABLE IF NOT EXISTS "Newsletter" (
    "id" TEXT NOT NULL PRIMARY KEY,
    "userId" INTEGER NOT NULL,
    "title" TEXT NOT NULL,
    "titleFr" TEXT,
    "dateFrom" DATETIME NOT NULL,
    "dateTo" DATETIME NOT NULL,
    "tone" TEXT NOT NULL,
    "templateType" TEXT NOT NULL,
    "sections" JSONB NOT NULL,
    "metadata" JSONB,
    "isDraft" BOOLEAN NOT NULL DEFAULT true,
    "sentAt" DATETIME,
    "focusAreas" JSONB,
    "includeUpcomingEvents" BOOLEAN NOT NULL DEFAULT true,
    "lessonPlansUsed" JSONB,
    "createdAt" DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
    "updatedAt" DATETIME NOT NULL,
    CONSTRAINT "Newsletter_userId_fkey" FOREIGN KEY ("userId") REFERENCES "User" ("id") ON DELETE CASCADE ON UPDATE CASCADE
);
CREATE TABLE IF NOT EXISTS "SubstitutePlan" (
    "id" TEXT NOT NULL PRIMARY KEY,
    "userId" INTEGER NOT NULL,
    "title" TEXT NOT NULL,
    "dateFor" DATETIME NOT NULL,
    "grade" INTEGER,
    "subject" TEXT,
    "schedule" JSONB NOT NULL,
    "classroomRoutines" JSONB NOT NULL,
    "emergencyInfo" JSONB NOT NULL,
    "lessonPlans" JSONB NOT NULL,
    "behaviorPlan" JSONB NOT NULL,
    "studentNotes" JSONB NOT NULL,
    "materialsList" JSONB NOT NULL,
    "importantInfo" JSONB,
    "sourceUnitPlanId" TEXT,
    "sourceLessonPlanIds" JSONB,
    "generationContext" JSONB,
    "teacherContact" JSONB,
    "adminContact" JSONB,
    "isActive" BOOLEAN NOT NULL DEFAULT true,
    "lastUsed" DATETIME,
    "useCount" INTEGER NOT NULL DEFAULT 0,
    "createdAt" DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
    "updatedAt" DATETIME NOT NULL,
    CONSTRAINT "SubstitutePlan_userId_fkey" FOREIGN KEY ("userId") REFERENCES "User" ("id") ON DELETE CASCADE ON UPDATE CASCADE
);
CREATE TABLE IF NOT EXISTS "Notification" (
    "id" INTEGER NOT NULL PRIMARY KEY AUTOINCREMENT,
    "userId" INTEGER NOT NULL,
    "type" TEXT NOT NULL,
    "title" TEXT NOT NULL,
    "message" TEXT NOT NULL,
    "data" JSONB,
    "read" BOOLEAN NOT NULL DEFAULT false,
    "createdAt" DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
    "updatedAt" DATETIME NOT NULL,
    CONSTRAINT "Notification_userId_fkey" FOREIGN KEY ("userId") REFERENCES "User" ("id") ON DELETE RESTRICT ON UPDATE CASCADE
);
CREATE TABLE IF NOT EXISTS "PerformanceTaskTemplate" (
    "id" TEXT NOT NULL PRIMARY KEY,
    "userId" INTEGER NOT NULL,
    "title" TEXT NOT NULL,
    "subject" TEXT NOT NULL,
    "gradeMin" INTEGER NOT NULL,
    "gradeMax" INTEGER NOT NULL,
    "scenario" TEXT NOT NULL,
    "role" TEXT NOT NULL,
    "audience" TEXT NOT NULL,
    "format" TEXT NOT NULL,
    "rubricTemplate" JSONB,
    "isPublic" BOOLEAN NOT NULL DEFAULT false,
    "timesUsed" INTEGER NOT NULL DEFAULT 0,
    "createdAt" DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
    "updatedAt" DATETIME NOT NULL,
    CONSTRAINT "PerformanceTaskTemplate_userId_fkey" FOREIGN KEY ("userId") REFERENCES "User" ("id") ON DELETE CASCADE ON UPDATE CASCADE
);
CREATE TABLE IF NOT EXISTS "EssentialQuestionTemplate" (
    "id" TEXT NOT NULL PRIMARY KEY,
    "question" TEXT NOT NULL,
    "subject" TEXT NOT NULL,
    "gradeMin" INTEGER NOT NULL,
    "gradeMax" INTEGER NOT NULL,
    "category" TEXT NOT NULL,
    "bloomsLevel" TEXT,
    "cognitiveLoad" TEXT DEFAULT 'medium',
    "timesUsed" INTEGER NOT NULL DEFAULT 0,
    "rating" REAL NOT NULL DEFAULT 0.0,
    "createdAt" DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
    "updatedAt" DATETIME NOT NULL
);
CREATE TABLE IF NOT EXISTS "TransferSkillTemplate" (
    "id" TEXT NOT NULL PRIMARY KEY,
    "skillName" TEXT NOT NULL,
    "description" TEXT NOT NULL,
    "category" TEXT NOT NULL,
    "gradeMin" INTEGER NOT NULL,
    "gradeMax" INTEGER NOT NULL,
    "performanceIndicators" JSONB,
    "assessmentMethods" JSONB,
    "isCore" BOOLEAN NOT NULL DEFAULT false,
    "createdAt" DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP
);
CREATE TABLE IF NOT EXISTS "UnitPlanResource" (
    "id" TEXT NOT NULL PRIMARY KEY,
    "unitPlanId" TEXT NOT NULL,
    "title" TEXT NOT NULL,
    "type" TEXT NOT NULL,
    "url" TEXT,
    "notes" TEXT,
    "createdAt" DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
    CONSTRAINT "UnitPlanResource_unitPlanId_fkey" FOREIGN KEY ("unitPlanId") REFERENCES "UnitPlan" ("id") ON DELETE RESTRICT ON UPDATE CASCADE
);
CREATE TABLE IF NOT EXISTS "ETFOLessonPlanResource" (
    "id" TEXT NOT NULL PRIMARY KEY,
    "lessonPlanId" TEXT NOT NULL,
    "title" TEXT NOT NULL,
    "type" TEXT NOT NULL,
    "url" TEXT,
    "content" TEXT,
    "createdAt" DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
    CONSTRAINT "ETFOLessonPlanResource_lessonPlanId_fkey" FOREIGN KEY ("lessonPlanId") REFERENCES "ETFOLessonPlan" ("id") ON DELETE RESTRICT ON UPDATE CASCADE
);
CREATE TABLE IF NOT EXISTS "UnitPlanTransferSkill" (
    "unitPlanId" TEXT NOT NULL,
    "transferSkillId" TEXT NOT NULL,
    "emphasis" TEXT NOT NULL DEFAULT 'developing',

    PRIMARY KEY ("unitPlanId", "transferSkillId"),
    CONSTRAINT "UnitPlanTransferSkill_unitPlanId_fkey" FOREIGN KEY ("unitPlanId") REFERENCES "UnitPlan" ("id") ON DELETE CASCADE ON UPDATE CASCADE,
    CONSTRAINT "UnitPlanTransferSkill_transferSkillId_fkey" FOREIGN KEY ("transferSkillId") REFERENCES "TransferSkillTemplate" ("id") ON DELETE CASCADE ON UPDATE CASCADE
);
CREATE TABLE IF NOT EXISTS "ETFOLessonPlan" (
    "id" TEXT NOT NULL PRIMARY KEY,
    "userId" INTEGER NOT NULL,
    "title" TEXT NOT NULL,
    "unitPlanId" TEXT NOT NULL,
    "date" DATETIME NOT NULL,
    "duration" INTEGER NOT NULL,
    "mindsOn" TEXT,
    "action" TEXT,
    "consolidation" TEXT,
    "learningGoals" TEXT,
    "materials" JSONB,
    "grouping" TEXT,
    "titleFr" TEXT,
    "mindsOnFr" TEXT,
    "actionFr" TEXT,
    "consolidationFr" TEXT,
    "learningGoalsFr" TEXT,
    "accommodations" JSONB,
    "modifications" JSONB,
    "extensions" JSONB,
    "assessmentType" TEXT,
    "assessmentNotes" TEXT,
    "isSubFriendly" BOOLEAN NOT NULL DEFAULT true,
    "subNotes" TEXT,
    "createdAt" DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
    "updatedAt" DATETIME NOT NULL,
    "grade" INTEGER,
    "language" TEXT,
    "subject" TEXT,
    "differentiationStrategies" JSONB,
    "engagementHooks" JSONB,
    "formativeCheckpoints" JSONB,
    "interventionStrategies" JSONB,
    "performanceOpportunities" TEXT,
    "priorKnowledgeCheck" TEXT,
    "reflectionActivities" JSONB,
    "wheretoFramework" JSONB,
    "indigenousPerspectives" TEXT, slotNumber INTEGER DEFAULT 1, lessonNumber INTEGER, lessonType TEXT DEFAULT 'core', isScheduled INTEGER DEFAULT 1,
    CONSTRAINT "ETFOLessonPlan_unitPlanId_fkey" FOREIGN KEY ("unitPlanId") REFERENCES "UnitPlan" ("id") ON DELETE RESTRICT ON UPDATE CASCADE,
    CONSTRAINT "ETFOLessonPlan_userId_fkey" FOREIGN KEY ("userId") REFERENCES "User" ("id") ON DELETE RESTRICT ON UPDATE CASCADE
);
CREATE TABLE IF NOT EXISTS "LongRangePlan" (
    "id" TEXT NOT NULL PRIMARY KEY,
    "userId" INTEGER NOT NULL,
    "title" TEXT NOT NULL,
    "academicYear" TEXT NOT NULL,
    "term" TEXT,
    "grade" INTEGER NOT NULL,
    "subject" TEXT NOT NULL,
    "description" TEXT,
    "goals" TEXT,
    "themes" JSONB,
    "overarchingQuestions" TEXT,
    "assessmentOverview" TEXT,
    "resourceNeeds" TEXT,
    "professionalGoals" TEXT,
    "titleFr" TEXT,
    "descriptionFr" TEXT,
    "goalsFr" TEXT,
    "createdAt" DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
    "updatedAt" DATETIME NOT NULL,
    "crossCurricularConnections" JSONB,
