CREATE TABLE IF NOT EXISTS "UnitPlan" (
    "id" TEXT NOT NULL PRIMARY KEY,
    "userId" INTEGER NOT NULL,
    "title" TEXT NOT NULL,
    "longRangePlanId" TEXT NOT NULL,
    "description" TEXT,
    "bigIdeas" TEXT,
    "essentialQuestions" JSONB,
    "startDate" DATETIME NOT NULL,
    "endDate" DATETIME NOT NULL,
    "estimatedHours" INTEGER,
    "titleFr" TEXT,
    "descriptionFr" TEXT,
    "bigIdeasFr" TEXT,
    "assessmentPlan" TEXT,
    "successCriteria" JSONB,
    "createdAt" DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
    "updatedAt" DATETIME NOT NULL,
    "communityConnections" TEXT,
    "crossCurricularConnections" TEXT,
    "culminatingTask" TEXT,
    "differentiationStrategies" JSONB,
    "environmentalEducation" TEXT,
    "fieldTripsAndGuestSpeakers" TEXT,
    "indigenousPerspectives" TEXT,
    "keyVocabulary" JSONB,
    "learningSkills" JSONB,
    "parentCommunicationPlan" TEXT,
    "priorKnowledge" TEXT,
    "socialJusticeConnections" TEXT,
    "technologyIntegration" TEXT,
    "assessmentRubric" JSONB,
    "enduringUnderstandings" TEXT,
    "evidenceTypes" JSONB,
    "performanceIndicators" JSONB,
    "performanceTask" JSONB,
    "transferableSkills" JSONB,
    "isLocked" BOOLEAN NOT NULL DEFAULT false,
    "lockedAt" DATETIME,
    "lockedReason" TEXT,
    CONSTRAINT "UnitPlan_longRangePlanId_fkey" FOREIGN KEY ("longRangePlanId") REFERENCES "LongRangePlan" ("id") ON DELETE RESTRICT ON UPDATE CASCADE,
    CONSTRAINT "UnitPlan_userId_fkey" FOREIGN KEY ("userId") REFERENCES "User" ("id") ON DELETE RESTRICT ON UPDATE CASCADE
);
CREATE TABLE IF NOT EXISTS "Student" (
    "id" TEXT NOT NULL PRIMARY KEY,
    "userId" INTEGER NOT NULL,
    "firstName" TEXT NOT NULL,
    "lastName" TEXT NOT NULL,
    "studentId" TEXT,
    "studentNumber" TEXT,
    "dateOfBirth" DATETIME,
    "grade" INTEGER NOT NULL,
    "program" TEXT,
    "homeroom" TEXT,
    "hasIEP" BOOLEAN NOT NULL DEFAULT false,
    "iepGoals" JSONB,
    "accommodations" JSONB,
    "specialNeeds" TEXT,
    "parentContact" JSONB,
    "enrollmentDate" DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
    "withdrawalDate" DATETIME,
    "isActive" BOOLEAN NOT NULL DEFAULT true,
    "status" TEXT NOT NULL DEFAULT 'active',
    "notes" TEXT,
    "createdAt" DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
    "updatedAt" DATETIME NOT NULL,
    CONSTRAINT "Student_userId_fkey" FOREIGN KEY ("userId") REFERENCES "User" ("id") ON DELETE CASCADE ON UPDATE CASCADE
);
CREATE TABLE IF NOT EXISTS "StudentArtifact" (
    "id" TEXT NOT NULL PRIMARY KEY,
    "studentId" TEXT NOT NULL,
    "userId" INTEGER NOT NULL,
    "artifactType" TEXT NOT NULL,
    "title" TEXT NOT NULL,
    "description" TEXT,
    "filePath" TEXT,
    "fileName" TEXT,
    "fileSize" INTEGER,
    "mimeType" TEXT,
    "textContent" TEXT,
    "metadata" JSONB,
    "checksum" TEXT,
    "thumbnailPath" TEXT,
    "thumbnailUrl" TEXT,
    "collectionContext" TEXT,
    "dateCollected" DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
    "isPrivate" BOOLEAN NOT NULL DEFAULT false,
    "isArchived" BOOLEAN NOT NULL DEFAULT false,
    "tags" JSONB,
    "processingStatus" TEXT NOT NULL DEFAULT 'PENDING',
    "processingError" TEXT,
    "processingCompletedAt" DATETIME,
    "lastAssessedDate" DATETIME,
    "createdAt" DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
    "updatedAt" DATETIME NOT NULL,
    CONSTRAINT "StudentArtifact_userId_fkey" FOREIGN KEY ("userId") REFERENCES "User" ("id") ON DELETE CASCADE ON UPDATE CASCADE,
    CONSTRAINT "StudentArtifact_studentId_fkey" FOREIGN KEY ("studentId") REFERENCES "Student" ("id") ON DELETE CASCADE ON UPDATE CASCADE
);
CREATE TABLE IF NOT EXISTS "StudentArtifactOutcome" (
    "artifactId" TEXT NOT NULL,
    "outcomeId" TEXT NOT NULL,
    "evidenceType" TEXT NOT NULL,
    "teacherNote" TEXT,
    "confidenceLevel" TEXT NOT NULL DEFAULT 'MEDIUM',
    "contextualFactors" TEXT,
    "dateAssessed" DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,

    PRIMARY KEY ("artifactId", "outcomeId"),
    CONSTRAINT "StudentArtifactOutcome_outcomeId_fkey" FOREIGN KEY ("outcomeId") REFERENCES "CurriculumExpectation" ("id") ON DELETE CASCADE ON UPDATE CASCADE,
    CONSTRAINT "StudentArtifactOutcome_artifactId_fkey" FOREIGN KEY ("artifactId") REFERENCES "StudentArtifact" ("id") ON DELETE CASCADE ON UPDATE CASCADE
);
CREATE TABLE IF NOT EXISTS "StudentOutcomeProgress" (
    "id" TEXT NOT NULL PRIMARY KEY,
    "studentId" TEXT NOT NULL,
    "outcomeId" TEXT NOT NULL,
    "userId" INTEGER NOT NULL,
    "currentLevel" TEXT NOT NULL DEFAULT 'NOT_YET',
    "previousLevel" TEXT,
    "lastAssessmentDate" DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
    "lastAssessedDate" DATETIME,
    "totalEvidencePieces" INTEGER NOT NULL DEFAULT 0,
    "strongestEvidence" JSONB,
    "areasForGrowth" TEXT,
    "strengths" TEXT,
    "teacherNotes" TEXT,
    "parentShared" BOOLEAN NOT NULL DEFAULT false,
    "parentShareDate" DATETIME,
    "isArchived" BOOLEAN NOT NULL DEFAULT false,
    "createdAt" DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
    "updatedAt" DATETIME NOT NULL,
    CONSTRAINT "StudentOutcomeProgress_userId_fkey" FOREIGN KEY ("userId") REFERENCES "User" ("id") ON DELETE CASCADE ON UPDATE CASCADE,
    CONSTRAINT "StudentOutcomeProgress_outcomeId_fkey" FOREIGN KEY ("outcomeId") REFERENCES "CurriculumExpectation" ("id") ON DELETE CASCADE ON UPDATE CASCADE,
    CONSTRAINT "StudentOutcomeProgress_studentId_fkey" FOREIGN KEY ("studentId") REFERENCES "Student" ("id") ON DELETE CASCADE ON UPDATE CASCADE
);
CREATE TABLE IF NOT EXISTS "Assessment" (
    "id" TEXT NOT NULL PRIMARY KEY,
    "studentId" TEXT NOT NULL,
    "teacherId" INTEGER NOT NULL,
    "subject" TEXT NOT NULL,
    "expectation" TEXT NOT NULL,
    "expectationCode" TEXT,
    "level" TEXT NOT NULL,
    "evidenceType" TEXT NOT NULL,
    "description" TEXT,
    "notes" TEXT,
    "artifacts" JSONB,
    "date" DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
    "createdAt" DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
    "updatedAt" DATETIME NOT NULL,
    CONSTRAINT "Assessment_teacherId_fkey" FOREIGN KEY ("teacherId") REFERENCES "User" ("id") ON DELETE CASCADE ON UPDATE CASCADE,
    CONSTRAINT "Assessment_studentId_fkey" FOREIGN KEY ("studentId") REFERENCES "Student" ("id") ON DELETE CASCADE ON UPDATE CASCADE
);
CREATE TABLE IF NOT EXISTS "Report" (
    "id" TEXT NOT NULL PRIMARY KEY,
    "type" TEXT NOT NULL,
    "title" TEXT NOT NULL,
    "studentId" TEXT,
    "teacherId" INTEGER NOT NULL,
    "dateRangeStart" DATETIME NOT NULL,
    "dateRangeEnd" DATETIME NOT NULL,
    "subjects" JSONB,
    "format" TEXT NOT NULL,
    "status" TEXT NOT NULL DEFAULT 'draft',
    "url" TEXT,
    "metadata" JSONB,
    "createdAt" DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
    "updatedAt" DATETIME NOT NULL,
    CONSTRAINT "Report_teacherId_fkey" FOREIGN KEY ("teacherId") REFERENCES "User" ("id") ON DELETE CASCADE ON UPDATE CASCADE,
    CONSTRAINT "Report_studentId_fkey" FOREIGN KEY ("studentId") REFERENCES "Student" ("id") ON DELETE CASCADE ON UPDATE CASCADE
);
CREATE TABLE IF NOT EXISTS "Artifact" (
    "id" TEXT NOT NULL PRIMARY KEY,
    "filename" TEXT NOT NULL,
    "originalName" TEXT NOT NULL,
    "mimeType" TEXT NOT NULL,
    "size" INTEGER NOT NULL,
    "url" TEXT NOT NULL,
    "thumbnailUrl" TEXT,
    "studentId" TEXT,
    "assessmentId" TEXT,
    "uploadedBy" INTEGER NOT NULL,
    "processingStatus" TEXT NOT NULL DEFAULT 'pending',
    "tags" JSONB,
    "description" TEXT,
    "metadata" JSONB,
    "createdAt" DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
    "updatedAt" DATETIME NOT NULL,
    CONSTRAINT "Artifact_uploadedBy_fkey" FOREIGN KEY ("uploadedBy") REFERENCES "User" ("id") ON DELETE CASCADE ON UPDATE CASCADE,
    CONSTRAINT "Artifact_studentId_fkey" FOREIGN KEY ("studentId") REFERENCES "Student" ("id") ON DELETE CASCADE ON UPDATE CASCADE
);
